INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişine Üzülmedim', 'gidisine-uzulmedim-riza-aslan-9mger', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gidişine hiç üzülmedim

daha önceden giden

herkes gibi

zamanı gelince

sen de bir gün - gidecektin -', 'gidişine hiç üzülmedim daha önceden giden herkes gibi zamanı gelince sen de bir gün - gidecektin -...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gidisine-uzulmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu Beklemek', 'sonu-beklemek-riza-aslan-qektd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geçen her gün

bir adım daha yaklaşırken sona

ve bu son

yaklaşılan her adımda

biraz daha büyürken

öylece

ve bu son yokmuşcasına

sonu beklemeye

onunla yaşamaya devam ediyorum', 'geçen her gün bir adım daha yaklaşırken sona ve bu son yaklaşılan her adımda biraz daha büyürken öylece ve bu son yokmuşcasına sonu beklemey...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sonu-beklemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
