INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayret', 'hayret-langston-hughes-fh4cm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alacakaranlığın maviliği.

Yanmamış henüz ışıklar.

                   Hey bak!

                   Şimdi yandılar!', 'Alacakaranlığın maviliği. Yanmamış henüz ışıklar.                    Hey bak!                    Şimdi yandılar!...', ARRAY['Türk Edebiyatı','Şiir','Langston Hughes']::text[], 8.5, '{"poet":"Langston Hughes","poet_slug":"langston-hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-langston-hughes-h7zke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden benim yalnızlığım olsun,

Neden benim şarkımmış,

Neden benim olsun ki o düşler,

                   ertelenmiş,

                   gereksiz yere

                   uztılmış', 'Neden benim yalnızlığım olsun, Neden benim şarkımmış, Neden benim olsun ki o düşler,                    ertelenmiş,                    gerek...', ARRAY['Türk Edebiyatı','Şiir','Langston Hughes']::text[], 8.5, '{"poet":"Langston Hughes","poet_slug":"langston-hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/soyle-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşatmak', 'yasatmak-ersin-gurdal-k51ax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülün ömrü kısa olur derler

Sen o gülü kalbine ek

Bilki oda yaşar seninle

Ta..Sen bende ölene dek

Aşktır bu yaşatın derler

Yaşatalım ki şaşırsın felek

Ben onu başarırım sevgili

Ta..Sen bende ölene dek', 'Gülün ömrü kısa olur derler Sen o gülü kalbine ek Bilki oda yaşar seninle Ta..Sen bende ölene dek Aşktır bu yaşatın derler Yaşatalım ki şaşı...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gürdal']::text[], 8.5, '{"poet":"Ersin Gürdal","poet_slug":"ersin-gurdal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasatmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-langston-hughes-2a2kq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahbap,bak sözüm sana,

doğmak zordur

ölmek de bayağı,

öyleyse

bir sevgi bulmaya bak kendine

ikisinin arasında.', 'Ahbap,bak sözüm sana, doğmak zordur ölmek de bayağı, öyleyse bir sevgi bulmaya bak kendine ikisinin arasında....', ARRAY['Türk Edebiyatı','Şiir','Langston Hughes']::text[], 8.5, '{"poet":"Langston Hughes","poet_slug":"langston-hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ogut-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metronun Kalabalık Saati', 'metronun-kalabalik-saati-langston-hughes-5h59i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İç içe

soluklar ve kokular

öylesine yan yana

iç içe

kara ve beyaz

öylesine sıkışık

yer kalmamış korkuya.', 'İç içe soluklar ve kokular öylesine yan yana iç içe kara ve beyaz öylesine sıkışık yer kalmamış korkuya....', ARRAY['Türk Edebiyatı','Şiir','Langston Hughes']::text[], 8.5, '{"poet":"Langston Hughes","poet_slug":"langston-hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/metronun-kalabalik-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılacağız', 'ayrilacagiz-taner-tuncel-431pd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden diye sorma sakın birdaha,

Kader diyelim gitsin ayrılacağız,

Ağlama arkamdan sil gözyaşını 

Kader diyelim gitsin ayrılacağız,

Elveda sevgilim ayrılacağız

Olmadı sevgilim başaramadık,

Paylaşmak nr imiş anlayamadık,

Bu büyük sevgiden tat alamadık,

Kader diyelim gitsin ayrılacağız,

Elveda sevgilim ayrılacağız

Belkide bir ömür boyu unutamıyacağız,

Bu büyük sevgiyi çok arayacağız,

Ölmek için Tanrıya yalvaracağız,

Kader diyelim gitsin ayrılacağız,

Elveda birtanem ayrılacağız...', 'Neden diye sorma sakın birdaha, Kader diyelim gitsin ayrılacağız, Ağlama arkamdan sil gözyaşını  Kader diyelim gitsin ayrılacağız, Elveda se...', ARRAY['Türk Edebiyatı','Şiir','Taner Tuncel']::text[], 8.5, '{"poet":"Taner Tuncel","poet_slug":"taner-tuncel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayrilacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereus Kızları', 'nereus-kizlari-hilmi-yavuz-cqj6b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '‘nereus kızları tıpkı toprak gibi,

     		       su gibi, güneş gibi yaşarlar. Onlarda

		        yazın ışıkları etle deriye dönüşür’

	            Marqueite Yourcenar (Doğu Öyküleri’nden)

aşk! o yokedici melek!

dağ süzülür, -ve 

rüzgâr, yüzümdür benim artık

		beklemek

sararmış, özlemek

kararmıştır. yolculuklar gümüş

e çürümüş bir uçurum kokmaktadırlar

gölgelemek, yeşermiştir

nerde nereus kızları? nerde kaldılar?

-gitmişlerdir...

bu kadar bozguncu ve siyah ve hep aynı

güneşe hangi sevinç dayanır?

			hangi dilek?

zeytinler, dalgın nar ağaçları

küçük kır tanrıları gibi

dağa tırmanır

yapraklar bedense bir örnek

			giyinmişlerdir

dağ bozumu günleri henüz gelmemiştir.

ölmek, morarır; dünyada-olmak

büsbütün kararır

işte şimdi tam bir yerden

kalkıp bir yere gitmek

solgun sümbül tadındadır

aşksa o yokedici melek

nerededir? elimde ölüm de

		var, -ve

dağ, gövdemdir benim artık', '‘nereus kızları tıpkı toprak gibi,      		       su gibi, güneş gibi yaşarlar. Onlarda 		        yazın ışıkları etle deriye dönüşür’ 	      ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/nereus-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Endymion', 'endymion-hilmi-yavuz-be6y0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben daima uçurumlar edinirim

bir yerden ötekine göçerken

işte sessiz saatlerde kederden

türemiş bir söylen

		gibi göl

ve bağlaşığı enymion

birlikte kıvrılıp uyurlar

ana-bir acıyla ayışığı...

		da mı birliktedirler?

şimdi bu uçurum illerinden

uçup göle kaçalım. kirli-olmak

bizi orda bekliyor

		...içimi melekler...

aşklarsa bağlanmak için iyidir

		-ne farkeder?

melekler kendiliğindendirler

öyle varolurlar...

belki benim terkettiğim şiirden

artakalan bu bahçeyi

hesperid’ler yüklenir,

toplayıp yolları götürür...

		mü diyorsun?

		-daha erken!.

ben daima uçurumlar edinirim 

bir yerden  ötekine göçerken', 'ben daima uçurumlar edinirim bir yerden ötekine göçerken işte sessiz saatlerde kederden türemiş bir söylen 		gibi göl ve bağlaşığı enymion b...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/endymion-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban Atlarını Kışkırtan Dionysos', 'yaban-atlarini-kiskirtan-dionysos-hilmi-yavuz-ic82r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‘kışkırt yaban atlarını, kışkırt,

			dionysos!..’ dediler

uzat aşkları ordan, orda fener,

			kayalar, gelirdi...

kim kalbini sana yedirdi?

her şey bir’di o zaman: atlar, logos

tek olan biz’dik, çayırlar-

sa başta sessizlikten doğma silenos

ve birlikte çiğ yenen günler...

yapraklar, yağmurun teniyse eğer

		sen o yaprağa beden-

sin ve tek değilsin: anababis, onbinler!..

giderek kim neyi eksik gördüyse

onu bütünler... gibisin: bir tören!..

şimdi sulara gizlen ve göç,

		onlarla beraber

kül parmaklı akşam dokunurdu sana

		özenle... ve yer yer

insanlar küldendiler... diye söyledim

ben hangi yolcuyu izleyen gemilerdim

		ve neden

hep söylen’dim, hep söylendim, hep söylen?

‘kışkırt yaban atlarını, kışkırt,

			dionysos!..’ dediler', '‘kışkırt yaban atlarını, kışkırt, 			dionysos!..’ dediler uzat aşkları ordan, orda fener, 			kayalar, gelirdi... kim kalbini sana yedirdi? h...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaban-atlarini-kiskirtan-dionysos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma', 'yapma-hakan-firen-ow1yn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaktaydın ama

