INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Satırla...', 'bes-satirla-nazim-hikmet-ran-agrgw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Annelerin ninnilerinden 

spikerin okuduğu habere kadar,', 'Annelerin ninnilerinden  spikerin okuduğu habere kadar,...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bes-satirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinç İle Hüzün', 'sevinc-i-le-huzun-ozdemir-asaf-s66uq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevinci kapıştılar taşımayı bilmeden,

Şimdi bilen yok, nerede oturuyor.

Köyün delisi Hüzün, yalnız kaldı yollarda

Adam-adam, sınıyor, arAyor yoldaşını..

Kıskandıran özlemi, yüzünden okunuyor.

Görünüp siliniyor o gündenberi.

Sevinç bin an gözlerde, dudaklarda.

Yerini sevgilisi Hüzün''e bırakıyor.

Sevinç''se, uzaklarda, hep uzaklarda..

Şöyle bir görünüyor, hemencecik uçuyor.

İşte o günden beri gözlerde, dudaklarda

Hüzün, aramaktadır yitik yavuklusunu.

O günden beri Sevinç yerinde durmaz

Ve kişiliğini ararken uzaklarda

O günden beri kimliksiz hüzün olmaz...', 'Sevinci kapıştılar taşımayı bilmeden, Şimdi bilen yok, nerede oturuyor. Köyün delisi Hüzün, yalnız kaldı yollarda Adam-adam, sınıyor, arAyor...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevinc-ile-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Acayip Duygu...', 'bir-acayip-duygu-nazim-hikmet-ran-zpd75', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '«Mürdüm eriği 

çiçek açmıştır. 

— ilkönce zerdali çiçek açar 

mürdüm en sonra — 

Sevgilim, 

çimenin üzerine 

diz üstü oturalım 

karşı-be-karşı. 

Hava lezzetli ve aydınlık 

— fakat iyice ısınmadı daha — 

çağlanın kabuğu 

yemyeşil tüylüdür 

henüz yumuşacık... 

Bahtiyarız 

yaşayabildiğimiz için. 


..........
..........', '«Mürdüm eriği  çiçek açmıştır.  — ilkönce zerdali çiçek açar  mürdüm en sonra —  Sevgilim,  çimenin üzerine  diz üstü oturalım  karşı-be-kar...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-acayip-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dakika', 'bir-dakika-nazim-hikmet-ran-4d5dq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deniz durgun göl gibi, gitgide genişliyor   

Sular kayalıklarda nurdan izler işliyor,   

Engine sarkan gökler baştan başa yıldızlı..   

Şimdi göğsümde kalbim çarpıyor hızlı hızlı.   

Göklerden bir yıldızın gölgesi düşmüş suya   

Dalmış s
..........
..........', 'Deniz durgun göl gibi, gitgide genişliyor    Sular kayalıklarda nurdan izler işliyor,    Engine sarkan gökler baştan başa yıldızlı..    Şimd...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-dakika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Süre Sonra,', 'bir-sure-sonra-veronica-a-shoffstall-sa6xj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sure sonra, 

bir eli tutmakla bir ruhu zincirlemek arasindaki 

ince farki ogrenirsin, 

Ve askin yaslanmak, 

birlikte olmanin da guvende olmak 

anlamina gelmedigini ogrenirsin, 

Ve opucuklerin sozlesme 

ve hediyelerin de vaat olmadigini ogrenmeye 

baslarsin, 

Ve yenilgileri 

basin dik ve gozlerin acik karsilamaya baslarsin, 

bir cocugun uzuntusu ile degil, bir yetiskinin 

zerafeti ile, 

Ve herseyi bugunu dusunerek yapmayi da ogrenirsin 

cunku yarin ile ilgili hersey belirsizdir. 

Bir sure sonra gunes isiginin yakici oldugunu 

ogrenirsin 

eger fazla maruz kalirsan 

Bu yuzden, 

baska birisinin sana cicek getirmesini beklemeden 

kendi bahceni yarat 

ve kendi ruhunu kendin susle. 

Ve goreceksin ki dayaniklisin... 

Ve kuvvetlisin, 

Ve degerlisin.', 'Bir sure sonra,  bir eli tutmakla bir ruhu zincirlemek arasindaki  ince farki ogrenirsin,  Ve askin yaslanmak,  birlikte olmanin da guvende ...', ARRAY['Türk Edebiyatı','Şiir','Veronica A. Shoffstall']::text[], 8.5, '{"poet":"Veronica A. Shoffstall","poet_slug":"veronica-a-shoffstall","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-sure-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler mi İstiyorum?', 'neler-mi-i-stiyorum-victor-hugo-gbm59', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neler mi istiyorum uyaninca her sabah

Ne bahardan bir nese, ne de yazdan bir cicek

Siyah, siyah cok siyah kadife kadar siyah

Bir sacin buklesini bana kim getirecek

Neler mi istiyorum gurbette aksamlardan

Ne ruzgardan bir buse, ne de bir pembe kelebek

Derin, derin cok derin, ufuklar kadar derin

Bir cift gözün rengini bana kim getirecek', 'Neler mi istiyorum uyaninca her sabah Ne bahardan bir nese, ne de yazdan bir cicek Siyah, siyah cok siyah kadife kadar siyah Bir sacin bukle...', ARRAY['Türk Edebiyatı','Şiir','Victor Hugo']::text[], 8.5, '{"poet":"Victor Hugo","poet_slug":"victor-hugo","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neler-mi-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-hurrem-sabuncu-yqdys', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zeynep Asbuzoğlu''na adanmıştır

Zambakta durduğu gibi değil beyaz.

kuytusuna sakladığı tüm renklerin sentezini,

savurmuş kelebeğin ebrulisi uğruna.

Elçiler göndereceğim,

Tanrı''nın sureti bildiğimiz hayatın şemlesine

sana dair...

Yakasını birleştiremediğimiz,

düşünmeden anıza vurduğumuz

aşklardı bizi yitirten.

Nasıl da değiştiriyor küçük bir virgül

cümlenin anlamını,

değiştirebilir miyim acaba senin anlamını?

Eteklerine düşen dağ sandığım,

sanıpta ulaşmaya çalıştığım

küçüklüğümdü beni sorgulayan.

Peşi sıra ebruliye koşan beyaz,

farkında değil tek olduğunu,

farkında değil özel olduğunu!', 'Zeynep Asbuzoğlu''na adanmıştır Zambakta durduğu gibi değil beyaz. kuytusuna sakladığı tüm renklerin sentezini, savurmuş kelebeğin ebrulisi u...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Sabuncu']::text[], 8.5, '{"poet":"Hürrem Sabuncu","poet_slug":"hurrem-sabuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beyaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber', 'haber-arif-damar-ns9nv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor sevgikim,

günlerdir ara vermeden;

senin nefesin gibi sıcak,hayat veren

bereketli,ferah,serin.

Öğrendim ki sen,

bin bilmem şu kadar kilometre ırakta

bir haftadır evlisin.

Ben,ot yatağımda uykusuzum yağmurlu gecelerde

sesini dinliyorum tabiatın.

beraber yürüdüğümüz yollar,

ayaklarının,

toprağa vuruşu geçiyor gözümün önünden.

Bir ışık aydınlatıyor kararan camları,

hayalin kıyıyor bana son defa canevimden.

Sağıma dönüyorum.', 'Yağmur yağıyor sevgikim, günlerdir ara vermeden; senin nefesin gibi sıcak,hayat veren bereketli,ferah,serin. Öğrendim ki sen, bin bilmem şu ...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif-damar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/haber-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-naci-saner-q0gsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sus hiç konuşma beni dinle.

Seni görmesem , duymasam bile

Hep yanımda hissettim.

Umutla konuşmuştum hatırlarmısın.

Hayallerimi süslemiştim seninle

Bu bir sevgimiydi neydi anlayamadım.

Bağlandım hislerimle ne bileyim.

Unutmak kolaymı ? Gelde unut

Dalgın bakışlarım

Ellerim öylesine titrek

Resmini dahi bilmiyorum senin 

Yaşlar dolsada gözlerime

Ağlamak gelmiyor içimden', 'Sen sus hiç konuşma beni dinle. Seni görmesem , duymasam bile Hep yanımda hissettim. Umutla konuşmuştum hatırlarmısın. Hayallerimi süslemişt...', ARRAY['Türk Edebiyatı','Şiir','Naci Saner']::text[], 8.5, '{"poet":"Naci Saner","poet_slug":"naci-saner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sitem-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye', 'geceye-aziz-akgun-l4lbv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir şiir okurum simsiyah yokluğa

sonra yokluğu doldurur varlığın

alevdir aşkın yaklaşamam yangına 

bir girdap olur boğar beni varlığın', 'bir şiir okurum simsiyah yokluğa sonra yokluğu doldurur varlığın alevdir aşkın yaklaşamam yangına  bir girdap olur boğar beni varlığın...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
