INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günler', 'gunler-nazim-hikmet-ran-p1jyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçip gitmiş günler gelin

rakı için sarhoş olun

ıslıkla bir şeyler çalın

geberiyorum
..........
..........', 'Geçip gitmiş günler gelin rakı için sarhoş olun ıslıkla bir şeyler çalın geberiyorum .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hyaldi Yaşamak', 'bir-hyaldi-yasamak-ahmet-volkan-uckan-ngquy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne sevgili ve ılık Meltem ile o yaşam

Ruhuma bedenime rüzgarın sürecekti

İlk yaz ışıltısında yanıma gelecekti,

Beklenen yanlız oydu ışıltısı o akşam

Yüzüme sürtünerek yine bir seher vakti,

Biliyorum geçeçek,bitmez onun rüzgarı.

Bin yıllardır istedi ol sevdayı, ol yari

Ben değildim sevilen yanlızca ruhum sevdi.

Yine seherimdesin ,yine hep benimlesin.

Bulabilsem içimin en içinde ben seni,

Olsun ,bir hayal olsun,alabilsem buseni.

Canımdan bir canımsın,bir parçam, bir yanımsın.

O akşam ne bekledim,nede sen bana geldin,

Yokluğuna alıştım,sevgimi alıkoydum

Şuracığımda hep o asi kor.Yoruldum

Hasretinle,sensizlik cehennemim.

İstemek nefesini ellerini aramak,

Hep öpmek boşlukları,öpmek yine sen diye

Ve illaki gelecek,o belalı kış yine.

Bense merhaba dedim yine gülümseyerek.Oysa;

salt onlar mutluydular.Tinsel bir merasimle,

Usulca yok olurken,son kez dalgalanarak,

Dediler.. Bir hayaldi ,o Meltem''le yaşamak.', 'Ne sevgili ve ılık Meltem ile o yaşam Ruhuma bedenime rüzgarın sürecekti İlk yaz ışıltısında yanıma gelecekti, Beklenen yanlız oydu ışıltısı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan Uçkan']::text[], 8.5, '{"poet":"Ahmet Volkan Uçkan","poet_slug":"ahmet-volkan-uckan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-hyaldi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz...', 'guz-nazim-hikmet-ran-o7g9r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günler gitgide kısalıyor, 

yağmurlar başlamak üzre. 

Kapım ardına kadar açık bekledi seni. 

Niye böyle geç kaldın?', 'Günler gitgide kısalıyor,  yağmurlar başlamak üzre.  Kapım ardına kadar açık bekledi seni.  Niye böyle geç kaldın?...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hürriyet Kavgası...', 'hurriyet-kavgasi-nazim-hikmet-ran-rf7l6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine kitapları, türküleri, bayraklarıyla geldiler, 

dalga dalga aydınlık oldular, 

yürüdüler karanlığın üstüne. 

Meydanları zaptettiler yine.
..........
..........', 'Yine kitapları, türküleri, bayraklarıyla geldiler,  dalga dalga aydınlık oldular,  yürüdüler karanlığın üstüne.  Meydanları zaptettiler yine...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hurriyet-kavgasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Sevda', 'i-ki-sevda-nazim-hikmet-ran-f10qf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gönülde iki sevda olamaz

yalan 

olabilir.

Şehrinde soğuk yağmurların

gece otel odasında sırtüstü yatıyorum

gözlerim tavana dikili

bulutlar geçiyor tavandan

ıslak asfaltı geçen kamyonlar gibi ağır

ve sağda uzakta 

ak bir yapı

yüz katlı belki

tepesinde altın iğne parlıyor.

Bulutlar geçiyor tavandan 

karpuz kay
..........
..........', 'Bir gönülde iki sevda olamaz yalan  olabilir. Şehrinde soğuk yağmurların gece otel odasında sırtüstü yatıyorum gözlerim tavana dikili bulutl...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimiz', 'i-kimiz-nazim-hikmet-ran-bplcg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İkimiz de biliyoruz, sevgilim,

öğrettiler:

               aç kalmayı, üşümeyi,

               yorgunluğu ölesiye

               ve birbirimizden ayrı 
..........
..........', 'İkimiz de biliyoruz, sevgilim, öğrettiler:                aç kalmayı, üşümeyi,                yorgunluğu ölesiye                ve birbirimi...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ikimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkıncı Yılımız', 'kirkinci-yilimiz-nazim-hikmet-ran-jfbq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hepimiz kırk yıl önce doğduk, 

kırk yıl önce sabahleyin 

kırk yıl önce gün ışırken Bedreddin''in İznik Gölü''nde 

çamlı bellerinden birinde Köroğlu''nun 

ve Sibirya''dan, esirlikten dönen Bolşevik Osman', 'Hepimiz kırk yıl önce doğduk,  kırk yıl önce sabahleyin  kırk yıl önce gün ışırken Bedreddin''in İznik Gölü''nde  çamlı bellerinden birinde Kö...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kirkinci-yilimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyıdaki İhtiyar', 'kiyidaki-i-htiyar-nazim-hikmet-ran-fyvvv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derin dağlar kat kat sıralanmıştı

çamlık iniyordu denize kadar

kıyıda iri yarı bir ihtiyar

çakıllara sırtüstü uzanmıştı

ve bu olgun güneşli Eylül  günü

uzak haberi batmış gemilerin

poyraz yeli mavi masmavi serin

okşuyordu ihtiyarın yüzünü

ve karnını
..........
..........', 'Derin dağlar kat kat sıralanmıştı çamlık iniyordu denize kadar kıyıda iri yarı bir ihtiyar çakıllara sırtüstü uzanmıştı ve bu olgun güneşli ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kiyidaki-ihtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocalmaya Alışıyorum', 'kocalmaya-alisiyorum-nazim-hikmet-ran-xo9qi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kocalmaya alışıyorum dünyanın en zor zanaatına, 

kapıları çalmaya son kere, 

durup durmadan ayrılığa. 

Saatler, akarsınız, akarsını
..........
..........', 'Kocalmaya alışıyorum dünyanın en zor zanaatına,  kapıları çalmaya son kere,  durup durmadan ayrılığa.  Saatler, akarsınız, akarsını ...........', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kocalmaya-alisiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasılsın', 'nasilsin-nazim-hikmet-ran-wkbhp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyi günlerimde çok eller uzanır ellerime,

Resmimi, suratımı baş köşeye asarlar...

Fakat demir kapıların 
..........
..........', 'İyi günlerimde çok eller uzanır ellerime, Resmimi, suratımı baş köşeye asarlar... Fakat demir kapıların  .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nasilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orkestra', 'orkestra-nazim-hikmet-ran-yxtps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana bak! 

Hey! 

Avanak! 

Elinden o zırıltıyı bıraksana! 

Sana, 

üç telinde üç sıska bülbül öten 

üç telli saz 

yaramaz! 

Bana bak! 

Hey! 

Avanak! 

Üç telinde üç sıska bülbül öten 

üç telli saz 

dağlarla dalgalarla kütleleri 

ileri 

atlatamaz! 

Üç telli saz 

yatağını deği
..........
..........', 'Bana bak!  Hey!  Avanak!  Elinden o zırıltıyı bıraksana!  Sana,  üç telinde üç sıska bülbül öten  üç telli saz  yaramaz!  Bana bak!  Hey!  A...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/orkestra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
