INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbete Mektup', 'gurbete-mektup-erhan-ozalevli-tropw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küskünlükler çilemizin bir garip ağıdıydı,

Ve sen, aryalara dökülmüş en güzel notalarıydın hep.

Ben ise bıkmadan usanmadan seni dinlerdim,

Kurumuş gül kokulu, karanlık gecelerin soluksuzluğunda.

Üzülme boşuna gülüm, barışıklık bana yazılmış gazel değil,

Ben içimde türküleri barındırırım, denizlerin türküsünü.

Hani fırtınalı gecelerde kendi ağıdına ağlayıp

Kendini bilinmezliğinde yitiren denizlerin türküsü.

Bilir misin?

İşte ben, o umarsız fırtınaların

Denizin kasvetli sisleri arasından çalıp,

Kıyılara attığı batık bir geminin dertleriyim.

Zarf içine sıkıştırılmış kağıt parçalarından tanıyabildin mı ki?

Hain ve sus pus tuzağına düşmüş günlerin ardından

Ne bir sitem sığdırabilirim iki satir arasına,

Ne de bir coşkun türkü tutturabilirim gelen mektup ardından.

Titrek yüreğimin sesini duyabiliyor musun? 

Toprağının seni sarıp kucaklayamadığı,

Rüzgarın acı ağıdının tanıdık olmadığı,

Ve düşlerin farklı dillerde görüldüğü bir diyarda

Kendini bir başına ve yalnız sanmayasın....

Bak kapat gözlerini, duyuyor musun?

Gurbet kokulu akasyalara inat,

Bir yürek çırpıyor taa uzaklarda,

Adı konulmamış diyarlarda.

Hani kanadı olsa beni terk edecek, 

Uçmayı yeni öğrenen bir serçe titrekliğinde.

Ama yaşlı bir anka kuşu sanki cesaretini takmış kanadına,

Senin için koca okyanusları arşınlamakta.

Beni istemsiz sitemlerin sisinde yitirip gitme, 

Ve unutma! 

Yarınlara emanet umutlarım ve bir de

Seninle söylenecek yarım kalan bir türkümüz var,

İnsanların hayat dedikleri....

Ankara-11.2.2001', 'Küskünlükler çilemizin bir garip ağıdıydı, Ve sen, aryalara dökülmüş en güzel notalarıydın hep. Ben ise bıkmadan usanmadan seni dinlerdim, K...', ARRAY['Türk Edebiyatı','Şiir','Erhan Özalevli']::text[], 8.5, '{"poet":"Erhan Özalevli","poet_slug":"erhan-ozalevli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gurbete-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bekleyişin Öyküsü', 'bir-bekleyisin-oykusu-sair-bera-37qhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saat 2:40 seni hala bekliyorum 

geleceksin ümidi hala yaşıyor içimde birtanem 

biliyorum birazdan kapıdan geçecek ve 

bak ben geldim senin beni beklediğini biliyordum diyeceksin

ve sarılacaksın bana 

çünkü ne kadar çok sevdiğimi ve daha 2 saat önce gitmene rağmen seni özlediğimi biliyorsun 

gözlerim taksim meydanın da dolaşıyor 

kime baksam sen zannediyorum 

kimi görsem sana benzetiyorum

lanet olsun ne biçim bir şey bu aşk ya.

çok geç oldu ama geleceksin biliyorum.

üşüdüm;kollarında ısınmak istiyorum

sakın yanlış anlama üşüdüğümden dolayı titremiyorum 

ya gelmessin korkusu bu sadece 

sen korkunca titremezmisin gülüm.

ama ne olursa olsun  geleceksin biliyorum.

saaat neden  geçmek bilmiyor bu gec

yagmurlu gecelerde hava çok karanlıktır biliyorum

olsun sen çabuk gelesin diye sana bahar lar yolladım

birde yüreğimele üflediğüim sevgiler 

çünkü geleceksin biliyorum....

üzerimde herzaman bildiğin yeşil kazağım

senin kadar ısıtamasada ısıtıyor sağolsun 

mbardan çıkan sevgililer kolkola nereye gidiyorlar bilmiyorum

taksim bu gece daha  bir başka 

çünkü geleceksin biliyorum.

saat 3 ü geçti 

ev çoktaan benden vazgeçti 

ben senden vazgeçemiyorum.

gelmedin  yağmurun kızı  canın sağolsun.

üşüttüğümden değil öksürüğüm 

bilirsin hep sigara içerim seni beklerken ondan herhalde 

sevgidede aşırı kaçtım hep tütündede  boşveerr 

dünyaya kazık mı kakacaz sanki atın ölümü arpadan olsun 

aaaaa nerdeyse sabah olacak 

olsun 

sana bu sefer  sitemlerimi  değil 

sadece bir damla

gözyaşı bırakıyorum 

senin istediğin gibi  sevin

bu aşkın sonunda 

belkide hiç hatırlanmayacak 

ıslak bir elveda 

bırakıyorum..', 'saat 2:40 seni hala bekliyorum  geleceksin ümidi hala yaşıyor içimde birtanem  biliyorum birazdan kapıdan geçecek ve  bak ben geldim senin b...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-bekleyisin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüveyda''ya Ağıt', 'ruveyda-ya-agit-nurullah-genc-59947', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir aziz değilim, hele gündüz değilim

Attığı her adımda siyah bir iz bırakan

Bir yanında ürküten bir baldıran gövdesi

Bir yanında kederi özümleyen bir lâle

Merhamet sahrasının uyuyan gecesiyim

Bırak da, böyle bitsin bu günahkâr serüven

Bırak da kurtarayım bu emânet sarayı

Yeter, intiharınla oyduğun yüreğimi

Umutsuz şarkılarla avutulduğum yeter

Göğsümde bir yanardağ kıvranıyor Rüveyda

Yaraları kapandıkça kanıyor Rüveyda

Duman çöktü güneşin sitem aynalarına

Aralandı perdeler; şimdi sessiz değilim

Dertliyim, viraneyim, ben bir aziz değilim

Azizler tohum eker sevgi tarlalarına

Senin gözlerin dram; oysa ağlatan benim

Ben dilenci; sen sultan; sevgi dağıtan benim

Sen ışık; ben karanlık ve aydınlatan benim

Ben ölümüm; sen hayat; cana can katan benim

Sabah sende oluyor; güneşi tutan benim

Soran ben; sorulan sen; hüznü damıtan benim

Öldüren ben; ölen sen; kabirde yatan benim

Sen sevda yüklü bulut, göklerimin sahibi

Saklıyorum içimde seni bir tufan gibi

Nerde uğruna ömür verdiğim belâ, nerde

Her hatıra bir demet zakkum meyhanelerde

Düşlerim esrarınla çoğalan pervanedir

Götür benden ahzânı, bana ihsanı getir

Yalanı reddederken düşüyorum yalana

Ben bir aziz değilim Rüveyda, anlaşana

Bu ağıdı öldüğün için söylemiyorum

Sen ölmedin Rüveyda; at vuruldu; ben öldüm

Her hamlesi bir tabut şimdi bakışlarının

Yıkayıp kefenledin; mehtabına gömüldüm

Her iklime kanatlı bir haberci salsınlar

Çağır âşıklarını; namazımı kılsınlar

Duysun âlem ateşin dağı erittiğini

Bu illetin taşları bile çürüttüğünü

Gün olur da, ayrılık yumağı çözülür mü

Bergüzârım ayaklar altında ezilir mi

Rüveyda, görür müyüm yeşil ufuklarını

Seninle bir sonsuzluk bulur muyum Rüveyda

Yoksa hep bu kabirde kalır mıyım Rüveyda

(13.02.2001-İstanbul)', 'Ben bir aziz değilim, hele gündüz değilim Attığı her adımda siyah bir iz bırakan Bir yanında ürküten bir baldıran gövdesi Bir yanında kederi...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ruveyda-ya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Fırtın Ardından', 'bir-firtin-ardindan-zekeriya-cavus-lhcrd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duman duman üstüne

Diyecek yok keyfine

Sanki çaredir keyfine

Bir sigara fırtının ardında

Umurunda mı dünya

Bir çöküntü omuzunda

Zararları hayat yolunda

Bir sigara fırtının ardında

Bugün dünyam karanlık 

Zevkim zararda bir anlık

Kısa bir ömür iki canlık

Bir sigara fırtının ardında

Çırpınıyorsun her çekişinde

Ömrün tükeniyor her nefesinde

Bilirmisin kanallar açılır ciğerinde

Bir sigara fırtının ardında', 'Duman duman üstüne Diyecek yok keyfine Sanki çaredir keyfine Bir sigara fırtının ardında Umurunda mı dünya Bir çöküntü omuzunda Zararları ha...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Çavuş']::text[], 8.5, '{"poet":"Zekeriya Çavuş","poet_slug":"zekeriya-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-firtin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Bir Kuştur Soluğum', 'kirmizi-bir-kustur-solugum-cemal-sureya-wp68z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı bir kuştur soluğum

