INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskici', 'eskici-meltem-pirlibeylioglu-1p7g5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir eskiciyim, 

Sırtımda heybem,elimde torbam yok,

Ama yüküm ağır biliyorum.

Haydi yok mu eskiniz,eskiler alıyorum.

Unuttuğunuz dostlukları,

Yaşayamadığınız sevdaları,

Yüreğinizde sıkışıp kalmış umutları,

Hoşgörüyü,sabrı,paylaşmayı,

Bir köşeye attığınız sevgiyi ve saygıyı,

Artık anmadığınız güzel hatıraları,

Dünden bugüne unutulan ne varsa verin  bana.

Yeniden tüm dünyaya dağıtmak istiyorum,

Bunun için yıllardır eskiler alıyorum.

                                                                   17/03/2001   AYDIN', 'Ben bir eskiciyim,  Sırtımda heybem,elimde torbam yok, Ama yüküm ağır biliyorum. Haydi yok mu eskiniz,eskiler alıyorum. Unuttuğunuz dostlukl...', ARRAY['Türk Edebiyatı','Şiir','Meltem Pirlibeylioğlu']::text[], 8.5, '{"poet":"Meltem Pirlibeylioğlu","poet_slug":"meltem-pirlibeylioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eskici-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naat', 'naat-i-smet-ozel-6v95a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dinleyin ey vakti duymak doruğuna varanlar

Falları grafiklerde bakılanlar siz de işitin..

Külden martı doğuran odalıklar

Ve kahyalar

Kara pıhtılarıyla damgalanmış veznelerde dili

Şehvetsiz çilingirler, yaltak çerçiler

Celepler ki sıvışık, natırlar ki nadan

Ey hayat rengini sazendelik sanan

Yırtlaz kalabalık! 

Dinleyin bendeki kırgın ikindiyi,

Hepiniz kulak verin.

Güneşin

Koskoca beldeye suskunluk yaygısını serdiği

Yazlar yok

Yok artık altında suskun yolları saklı tutan

Karla örtülmüş kırların kışı

Gitti giden, yerine gelmedi başka biri

Orada

Duyumsatmadı kendini hiçlik bile

Belli ki son yüzyılımız göğsümüzden

Varla yok harman eden sesi uçursak

Diye bize verildi

Yetti bir yüzyıl böcekler ve otlarda

Soluyuş izlerimiz silmek için

Ne yesek

Lokmaya vurulur gibi değil

Yuduma gelmiyor içtiklerimiz

Dernekler toplanıyor dışta tutmak için 

Kanat vuruşlarını yumuşak tutan etkeni

Utançlı sessizliği tanımaz kalemlerle

Kapanıyor bilanço

Top mermisi, kör testere

Defalarca boyanmış çaput parçaları

Sıkıştırdık günlerimiz arasına ki

Serazat kahkahalar atalım

Yapmacıktan nefretimiz

Sebep olsun kavgamıza

Bekleyiş arzından kovsunlar bizi

Ne yemen biraz öncemiz diyelim

Ne biraz sonramız meksika

Canı pek bir dünya son yüzyılda yaşadığımız

Yüzü perdahla kavi, peçesi paramparça

Üstü başı kükürtlü bu dünyadan

Kancıklık

Sıçradı çevirdiğimiz sayfalara

Artık kimse bize haber vermeyecek

Hemen şu tepenin ardında

Saldırmaya hazır ve müsellah

Bir düşman taburu durduğunu

Çünkü gerçekten yok

Böyle bir ordu

Bir düşmanımız kaldı

Kendi

Dudaklarımız 

Arasında.

Biliyoruz günden güne çopurlaşan yer yuvarlağında

Bizleri yan çizen birer hemşehri haline sokan nedir

Çırpını çırpını giden atlardan indik

Girmek için patavatsız yurttaşlar sırasına

Zihnimiz, acizlerin şikayetleri sığacak kadar

Kanırtılırken ses etmedik

Öcümüz alınacak korkusuyla irkildik

Kaldıysa bir soru içimizde

O da birşey:

Nerdedir yerle gök arasındaki ulak,

Nerde biz? .

Kimseden bir işaret gelmeyecek

Bir melek kimsenin alnını sıvazlamazsa

Söylemez size kimse dünyadaki ömrü boyunca

Hiçbir insana yan bakışı olmayan kimdi

Kimdi yan gözle bakmadı kır çiçeklerine bile

Öğretmek için cephe nedir

Kıyam etti

Torunu kucağında

Dönünce bütün gövdesiyle döndü

Bir bu anlaşılsaydı son yüzyılda

Bir bilinebilseydi

Nedir veche..

Dinleyin ey vakti duymak doruğuna varanlar

Sıyırın kahkaha sırçasını cildinizden

Omzunuzdan vaveyla heybesini atın

Boşa çıksın reislerin, kahinlerin, şairlerin kuvveti

Güler yüzlü olmak neydi onu hatırlayın

Neydi söğüt gölgesinde gülümsemek

Ağız dolusu gülmeden taşlıkta...', 'Dinleyin ey vakti duymak doruğuna varanlar Falları grafiklerde bakılanlar siz de işitin.. Külden martı doğuran odalıklar Ve kahyalar Kara pı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/naat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsal Uyarı', 'kutsal-uyari-sair-baraka-7r9nf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni sevmek

Bir ibadettir

İşte bu böyle

Bil ve bildir

Ya hu

Ya hu

Deyu

deyu

Tekgülüm ailesi fertlerine.....

barakadan', 'Beni sevmek Bir ibadettir İşte bu böyle Bil ve bildir Ya hu Ya hu Deyu deyu Tekgülüm ailesi fertlerine..... barakadan...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kutsal-uyari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Son', 'kotu-son-faruk-gorgulu-iznk7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'only after the last tree has been

                                               cut down

only afyter the last river has been

                                                poisoned

only after the last fish has been

                                                cought

only then you will find that

                                                 money can not be eaten

                            Cree Indian Prophecy', 'only after the last tree has been                                                cut down only afyter the last river has been               ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kotu-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikız''ın Türküsü', 'delikiz-in-turkusu-olcin-orkun-hi7ay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baharı görmüş mü hiç ömründe

Hep sonbaharlar da

Hep kışlar da yaşamış Delikız

Kavurucu sıcağında bile güneşin

Yüreğini hep ayazlar okşamış ..

Dudağında hep yarım sevda türküleri

Yüzünde ,

yaşanmamış sevgilerin izleri

Saçlarını karçiçekleriyle süslemiş,

kalbinde solmayan kançiçekleri ..

Avuçlarında tutam, tutam umutlar,

demet ,demet sevgiler taşımış Delikız

Çiçekleri bahtındanda kara.

Siyahın,

büyüsünü nakışladığı gecegözlerinin

ufkunda uzanan yollar

dalıp ,dalıp gittiği noktalar kara ..

... beyaz ve ışıltılı olan,

yalnızca umutlarıdır Delikızın

Bittiği yerde başlayan hikayeler gibi

Kardelen çiçekleri gibi.

Hoyrat dalgaların sürüklediği yüreği ellerinde

Yinede sımsıcak, yinede duygulu

Yinede tertemiz, yinede coşkulu.

Adeta meydan okur gibi zemheri ye ..

Birkaç damla yalancı yağmura aldanırda

Kızgın çöllerin ortasında bitiverir

Deliçiçekler gibi ..', 'Baharı görmüş mü hiç ömründe Hep sonbaharlar da Hep kışlar da yaşamış Delikız Kavurucu sıcağında bile güneşin Yüreğini hep ayazlar okşamış ....', ARRAY['Türk Edebiyatı','Şiir','Olçin Orkun']::text[], 8.5, '{"poet":"Olçin Orkun","poet_slug":"olcin-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/delikiz-in-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kelebek', 'beyaz-kelebek-hakan-sengorun-6mkr3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baharı kaybetmiş beyaz kelebek

Dokundum yağmur oldu düşüme

Ellerine kondu beyaz kelebek

Yaşadım düş oldu ölümlerime

Ellerindi beyaz kelebek

Düşledim gözlerinde

Ağladı beyaz kelebek

Sustum rengine

Sendin beyaz kelebek

Kanatların değdi rüzgara

Üşüdün 

Sevda oldu beyaz kelebek

Düşündüm uçtu bana...', 'Baharı kaybetmiş beyaz kelebek Dokundum yağmur oldu düşüme Ellerine kondu beyaz kelebek Yaşadım düş oldu ölümlerime Ellerindi beyaz kelebek ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyaz-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Gün İçin Şiirler', 'eski-bir-gun-i-cin-siirler-arkadas-zekai-ozger-sk8fx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve sevinç güzel bir denizle başladı

ve güneş ipi kalınlaştırıyordu

sonra ansızın uzayıverdi ip

bir ucu orda kaldı

bir ucu bende

ve iki uç arasında sıkışan

karışık bir sevgiyi acabayla büyüten 

bir güzelliğin negatifini büyüten

ince bir yüreğe dayanamadı

ip

koptu

sevinç

güzel bir denizle kaldı

ve güneş bir bulutla rahibeleşiyordu

sevgilim

bugün 

helva yedim şarap içtim göğe uzandım

avuçlarımda hüzünlü bir aşk

ince kemikli bir eli okşuyorum

göğü okşuyorum

yabani bir diken batıyor avuçlarıma

bir çakıyla parmağımı kesiyorum yanlışlıkla

sanki bilerek yanlışlıkla kesiyorum

sanki aşkı kesiyorum

aşk parmağımda yanlış bir uçurum

dokunurken bırakır ürkek bir martı gibi 

çünkü deniz orda

-ben alışkın değilim bir eli martılamaya

çünkü deniz orda

çünkü deniz orda

-heyecan verir bana aşk

çekilir kuytusuna 

uzar gider gecede 

bırakarak cinsel tortusunu 

sevgi

denizin başlangıcı

seni koruyacam

tamamlıyacam

seni kazanmalıyım

istediğim kadar beslerim seni

büyütürüm içimde seni

çok çok çok 

bir şey ver bana

seni seviyorum

                                    (Eylül 1970)', 'Ve sevinç güzel bir denizle başladı ve güneş ipi kalınlaştırıyordu sonra ansızın uzayıverdi ip bir ucu orda kaldı bir ucu bende ve iki uç ar...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/eski-bir-gun-icin-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaz Geçmeliyim', 'vaz-gecmeliyim-olcin-orkun-tednw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitmeliyim artık

Dinmeli yüreğimde bu yasak fırtına

Hakkım yok birtanem,

yasak aşkını taşımaya

Hakkım yok yağmurum sana ..

Bitmeli artık

Bitmeli bu yasak sevda

Dönmeliyim boş ve yavan dünyama

Dönmeliyim birtanem yalnızlığıma ..

Kolay olmasada vazgeçmek o Denizgözlerinden

Silmeliyim gözlerimden,

gözlerinin hayalini

Vazgeçmeliyim yüreğinin büyülü sıcağından

Kolay olmasada reddetmek

yeşerten yağmurunu

Vazgeçmeliyim birtanem

vazgeçmeliyim senden ..

Çıldırtasıya yaksada,kahretsede hasretin

Söndürmeliyim yüreğimde ki volkanı

Ve 

Gitmeliyim yağmur yüreklim

Vazgeçmeliyim sevginden ...', 'Gitmeliyim artık Dinmeli yüreğimde bu yasak fırtına Hakkım yok birtanem, yasak aşkını taşımaya Hakkım yok yağmurum sana .. Bitmeli artık Bit...', ARRAY['Türk Edebiyatı','Şiir','Olçin Orkun']::text[], 8.5, '{"poet":"Olçin Orkun","poet_slug":"olcin-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/vaz-gecmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim Mevlana', 'sana-geldim-mevlana-yavuz-bulent-bakiler-zhftg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana geldim Mevlana...

Düştüm yollara Fatiha''larla

Önümde yemyeşil ışıktan bir iz

Yıkanmış yaprak gibi tertemiz

Sana geldim Mevlana...

Herşey öylesine mağrur,sessiz,tertemiz

Geçmiş asırlardan beri tertemiz

Bir el dokundurursam sandukalara

Uyanır Horasan erleri

Sana geldim Mevlana...

Divan durdum önünde, duygulu, sessiz

İçimde ne hasret, ne gül, ne bülbül

Şimdi ezan nur alem, nur Konya

İşte sabır, işte aşk, işte tevekkül

Sen bilirsin Mevlana...

Sana geldim Mevlana...

Ayet ayet İslam,nakış nakış Türk

Bir türbe içinde ne güzel mana

Serin bir rüzgarla çok uzaklardan

Sana geldim Mevlana...', 'Sana geldim Mevlana... Düştüm yollara Fatiha''larla Önümde yemyeşil ışıktan bir iz Yıkanmış yaprak gibi tertemiz Sana geldim Mevlana... Herşe...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-geldim-mevlana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-metin-basaran-q3txh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurşun değsede bedenime 

Acı vermez gözlerin (ayrılık) kadar

Yar kalbimde yerin büyük

Silinmez inan ölene kadar

Bir bana sarılmanı sıkıca

Bir sarılıp dans etmeyi

Bir de dans ederken öpmeni

Özlüyorum biliyor musun?

Gözlerin güzel bir tanem

Sev beni der gibi

Dudağın güzel gülüm 

Öp beni der gibi', 'Kurşun değsede bedenime  Acı vermez gözlerin (ayrılık) kadar Yar kalbimde yerin büyük Silinmez inan ölene kadar Bir bana sarılmanı sıkıca Bi...', ARRAY['Türk Edebiyatı','Şiir','Metin Başaran']::text[], 8.5, '{"poet":"Metin Başaran","poet_slug":"metin-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopardın', 'kopardin-nurullah-genc-7pz9m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir hicran çölüne bıraktın beni

Kalbine girdiğim yolu kopardın

Yaydın üzerime yalan gölgeni

Adını andığı dili kopardın

İçimden boşluğa savruldu külün

Hüznün ateşiyle yandı kakülün

Yıllardır ruhumda öten bülbülün

Her seher konduğu dalı kopardın

Uzattıkça sana boş ellerimi

Birer birer yıktın hayallerimi

Bilmem, ölü müyüm, yoksa diri mi

Saçımdan sn siyah teli kopardın

Gönlümde aşkınla hergün yeşeren

Göğü yıldız yıldız önüme seren

O güzel, bembeyaz gülü kopardın

Aynasında yalnız seni gösteren', 'Bir hicran çölüne bıraktın beni Kalbine girdiğim yolu kopardın Yaydın üzerime yalan gölgeni Adını andığı dili kopardın İçimden boşluğa savru...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kopardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Ateşi', 'sensizlik-atesi-gamze-cirakman-rp4zl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Feryatlarıma tutunup tırmanırken

hasretinin zirvesine,

düşmek korkusu geliyor aklıma

ve acıtıyor bedenimi...

Seni hiç görememe endişesi var ya

titretiyor içimi sensizliğin ateşiyle...', 'Feryatlarıma tutunup tırmanırken hasretinin zirvesine, düşmek korkusu geliyor aklıma ve acıtıyor bedenimi... Seni hiç görememe endişesi var ...', ARRAY['Türk Edebiyatı','Şiir','Gamze Çırakman']::text[], 8.5, '{"poet":"Gamze Çırakman","poet_slug":"gamze-cirakman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensizlik-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-gamze-cirakman-z3xpj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitmek, ne korkunç bir sözcük.

vedalaşmak,bırakmak,terk etmek,ayrılmak...

tek bir veda bütün bir ömür sürüyor...

sanki binlerce parçalanmış midye kabuğunun çizdiği bir yoldan gidiyorum,

var olmayan inciyi aramış birinin izini sürüyorum.

biliyorum,

bir insanın sevgisini kaybetmek,

zorlukla ulaşılmış bir doruktan aşağı yuvarlanmaktır...

gece başladığında yok olacak son gölgedir,

uçurumun üstüne düşen bir ''gölge''

MERHABA SEVGİLİM.........', 'Gitmek, ne korkunç bir sözcük. vedalaşmak,bırakmak,terk etmek,ayrılmak... tek bir veda bütün bir ömür sürüyor... sanki binlerce parçalanmış ...', ARRAY['Türk Edebiyatı','Şiir','Gamze Çırakman']::text[], 8.5, '{"poet":"Gamze Çırakman","poet_slug":"gamze-cirakman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/golge-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Şiir', 'beyaz-siir-kazim-yaman-7carq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana beyaz şiirler yazdım

Yarınların beyaz olsun diye

Sana beyaz şiirler yazdım

gönlüne huzur dolsun diye

Bir beyaz şiir oku 

Belki anlarsın

Bir beyaz şiir oku 

Belki biraz yaşarsın', 'Sana beyaz şiirler yazdım Yarınların beyaz olsun diye Sana beyaz şiirler yazdım gönlüne huzur dolsun diye Bir beyaz şiir oku  Belki anlarsın...', ARRAY['Türk Edebiyatı','Şiir','Kazım Yaman']::text[], 8.5, '{"poet":"Kazım Yaman","poet_slug":"kazim-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyaz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Dünyalar Rubaisi', 'baska-dunyalar-rubaisi-husrev-hatemi-1nsj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyan,başka gezegende,başka bir yer...

Dünyandan Dünyama bir an ses ver

O mutlu an sona erdikten sonra

Beni bir Kara-Deliğe gönder', 'Dünyan,başka gezegende,başka bir yer... Dünyandan Dünyama bir an ses ver O mutlu an sona erdikten sonra Beni bir Kara-Deliğe gönder...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/baska-dunyalar-rubaisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Könül Varag Kidek', 'konul-varag-kidek-rustem-behrudi-sk47m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gizledib (1) açmadıg o sirrimizi,

Dayanıb dursag da üzbeüz (2) onda.

''Sevirem ''demedig, bir-birimizi ,

Sözsüz de (3) duyurdu gelbimiz onda. (4)

...Bu da ki ,ayrılıg - eşgin  son sözü ,

Bu da ayrılığın sevgilisi - gem.

Könül , varag gedeg ,bu ayrılığın 

Men daha gemini çekebilmerem.

...Hicrandan  beziksen (5) özünü aldat ,

Don biç (6) ayrılığa sebrimden menim .

Teze bir mehebbet çıharıp yaşat ,

Könlünde dağılmış gebrimden menim.

Demirem : -Sevilme , sevme demirem ,

Men ki incimirem (7) ,unut ,ne olar ?(8)

Men ancag bilmirem ,unudabilmir 

Nedense  hemişe (9) unudulanlar...

                                                       1988

-------------------------------------------------------------

1-saklayıp .2- yüz yüze . 3- konuşmadan da .

4-o zaman . 5- bezsen,bıksan. 6- elbise kes

7- incimiyorum ,darılmıyorum .8- ne olur.

9-her zaman.', 'Gizledib (1) açmadıg o sirrimizi, Dayanıb dursag da üzbeüz (2) onda. ''Sevirem ''demedig, bir-birimizi , Sözsüz de (3) duyurdu gelbimiz onda. ...', ARRAY['Türk Edebiyatı','Şiir','Rüstem Behrudi']::text[], 8.5, '{"poet":"Rüstem Behrudi","poet_slug":"rustem-behrudi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/konul-varag-kidek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilber', 'dilber-ergun-kurubal-kheoc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey yüreğimde yara açan dilber

bakma öyle gözlerinle bana hayat ver..

bir damla aşkına susamış dudaklarım

ölüm inan bana bir nefes kadar yakın

su ol deniz ol okyanus ol ak gönlüme

dolsun göz pınarlarım aksın delice

alev ol ateş ol köz ol yak türkünü yine

ağlasın şarkılar böyle her gece....', 'Ey yüreğimde yara açan dilber bakma öyle gözlerinle bana hayat ver.. bir damla aşkına susamış dudaklarım ölüm inan bana bir nefes kadar yakı...', ARRAY['Türk Edebiyatı','Şiir','Ergün Kurubal']::text[], 8.5, '{"poet":"Ergün Kurubal","poet_slug":"ergun-kurubal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceydi', 'geceydi-chriss-cairon-doubu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostlara sustum :

Bir kendime bozdum sevdamın sessizliğini .

Bir ben duydum adını ,

Bir ben söyledim.

Yazılmamış mektuplar gönderdim sana

Olmayan postanelerden ...



Şarkım olacaksan yarım kalma .

Yarım kalma hikayem olacaksan .

Ben şair , sen şiir :

Sevdam ol ;

 Yüreğimde kalıp ,

Alnıma yazılacaksan ... 



Şimdi sen : kalbimin közünde , 

kıvılcım kıvamında ağrıyan

Anlatmak zor ;

Vakit dar ,

Zaman ellerimde bulut şimdi .

Bir şeyler söylemek isterdim sana :

Oysa 

Vakit dar 

Ve anlatmak zor ...

Yağmur yağmıyordu ,

Şarkılarda yoktu ,

Adında geçmiyordu ; düştün aklıma.

Canım yandı ...

					09.01.01

Bir kelimeye

Bin anlam yüklemek gibiydi

Adını söylemek ,

Adını bağırmak güzeldi

O yıldıza doğru ,

Zaman zaman  ...

02.12.00



Onlara benzemek değildi sevmek ...

Aynı kitabı okuyup

Aynı şarkıyı dinlemek ,

Konuşmak , konuşulmak

Bakmak değildi ...

Öyle bir şeydi ;

İçimin içinde ...

					02.12.00



Neden seni bıraktığımı düşündüm bugün ;

Sevda öyle gerektiriyor idi dedim sonra kendime ,

Ayrılıkta yaşanmalıydı içinde .

Böyle yaşanmalıydı sevmek ,

Bir yerde bırakıp gitmeliydi ...

..............

ölümün geldi aklıma sonra ...

hayata ve aşka isyanım ,

figanım aklıma geldi Tanrıya ,..

Ve sana bıraktığım PAPATYA .

					23.11.00

Gözlerin söz olduğu vakitlerde gel ;

Yüzünde sevdalı bir tebessüm ,

Gözlerinde aşk ,

Yüreğin ellerinde olsun .

Gözlerin söz vakit gel ;

Evren SEN olsun ...

						        Adana’00

Neden sen ?...

Laf değil şimdi sevda ,

Aşk için zaman çok erken .

Yalnızlık bana yetiyorken ;

neden sen ?...

Adın anıldı kaç zaman ,

Yıldızlara sevdayı anlatırken ...

						      Adana’00

Beni bul !

Sokak lambaları yanmaz buraların ,

Yüzler karanlığa gizlenmiştir .

Hangi eve baksan hüzün akar duvarlarından ,

Gölgesi yoktur bu sokakta oturanların .

Kaldırımlarından başkaları geçmez ,

Merhabası yoktur birbirine insanların .

Her zaman bir beklenen vardır buradakiler için :

Birisi gelsin beni bulsun diye .

Çünkü ; kaybolmuşlar bilmez çıkış yolunu .

İçinde bir yerlerdeyim ;

Beni bul !..

						    Adana’01

	 



Adını söylemek güzeldi ;

Ortasına düşerken bir gecenin ,

Seni düşünmek özeldi ...

Bir kedinin ayak seslerini duymak gibiydi

Sesine dokunmak.

Elini tutmak ;

Söylenmemiş bir türküye kendini vermek gibiydi .

							18.01.01

Şarkılar söyleniyordu olmadığın mekanlarda .

Adın anılıyordu o vakitler .

Ve her defasında ,

Yarım kalıyordu adın ...

							22.01.01

Sana gece yarısı hikayeleri okuyordum ,

O uzaktaki yıldızdan .

Bir başıma idim :

Koruyordum ,

Hikayeleri yarım bırakmaktan ...

							22.01.01

Sevda bilmezlere düştü .

Anlamazlara kaldı .

Oysa haberleri yok ;

Bir yüreğin

Kullanma kılavuzu olmadığının ...

Yere atıp kırarlar

Yahut oynayıp bozarlardı ;

Garantisi var sanırlardı .

Oysa haberleri yok ;

Bir yüreğin

Garantisi olmadığının ...

	27.01.01', 'Dostlara sustum : Bir kendime bozdum sevdamın sessizliğini . Bir ben duydum adını , Bir ben söyledim. Yazılmamış mektuplar gönderdim sana Ol...', ARRAY['Türk Edebiyatı','Şiir','Chriss Cairon']::text[], 8.5, '{"poet":"Chriss Cairon","poet_slug":"chriss-cairon","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığıntı Kuşu', 'siginti-kusu-arkadas-zekai-ozger-gwju1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'akşam

hüznümün soluk aynası

vurdukça yüreğime kanım oynaşır

derinleşir acısı parmakuçlarımın

kırmızı bir ölümü görmüş gibi

kanarım.

yoruldum

değiştirmekten kanını yüreğimin

hergün yeniden başlayan 

çığırtkan bir şarkıyı söylemekten

hergün

yeni bir şarkı bestelemekten

ben hüznün 

ben gölgemin kiracısı

yeni bir ev değiştirmekten

hergün

gövdemle büyüyen hüznümle

kimselerden habersiz eskiyen yüreğimin

dinlemiyorlar

dinlemiyorlar şarkısını oy

sustukça çoğalıyor tekliğim

ah benim sıska yüreğim

ah benim kimselere söz geçiremez yüreğim

ah benim 

neyim kaldı elimde

ah benim

üreyemiyorum kendime

böyle niye beni

biraz yankı biraz karıncayken

şimdi eski bir enosis düşlerim

kendimi koparıyorum kendimden

yetişemiyorum.

tekliğim

yorgun ve kanadı kırık kuştur

hüznün yapraklarında gölgelendiği

kim koparır dalından

ağzı açık bir gülü

kırmızı bir ölümü görmüş gibi

kanarım

yoruldum

değiştirmekten kanını yüreğimin

ne zaman bitecek

bu hüzün.

                                           (Soyut, Ocak 1968)', 'akşam hüznümün soluk aynası vurdukça yüreğime kanım oynaşır derinleşir acısı parmakuçlarımın kırmızı bir ölümü görmüş gibi kanarım. yoruldum...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/siginti-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumu Sürüklüyorum', 'ruhumu-surukluyorum-metin-bektas-n9jbs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bekliyorum, 

                     ateşten kirpikleriyle 

                     alaca karanlığında akşamın ; 

                     alnı ak dalgalarla söyleşerek 

                     ve bakir bir yalnızlığın 

                     tam ortasında... 

                     Bekliyorum 

                     bir gölge gibi peşinden 

                     ruhumu sürüklüyorum... 

                     Avuçlarını ver bana küçük kız ! 

                     Dudaklarımızda ıslıklar 

                     bir masal ülkesinin melodisini 

                     söylesin ; 

                     ve bütün sevişmelerin dışında, 

                     yaz yağmurlarından kalma bir hüzünle, 

                     taze bir gül yaprağını usulca öper gibi 

                     dokunsun dudaklarına dudaklarım 

                     diyemiyorum... 

                     Bekliyorum 

                     ve bir gölge gibi peşinden 

                     ruhumu sürüklüyorum... 

                     Öyle bakma gözlerime 

                     inciler saçan bir bulutun rahmetiyle ne olur ? 

                     Kutsal bir sabah kadar serin 

                     ve bir savaş kahramanının asaletiyle 

                     bakma öyle gözlerime... 

                     Biliyorum 

                     bize böylesi gerek aşkın !... 

                     Sevmek acı çekmek değil mi zaten ? 

                     Vakur ve özgece beklemek değil mi ? 

                     Sevmek ; gönül diyetini ödemek değil midir ; 

                     sevgiliye... 

                     Ey yüreği mercan sularda yıkanmış, 

                     gök sızısı bakışlı kız !... 

                     Görmez misin ruhumun usul, usul yandığını 

                     ney misali... 

                     Bütün vesvesesini yaktım içimin 

                     bak ! 

                     Büyük umutların bedelidir çünkü 

                     bu gönül kanı ; 

                     ve sevdanın miracına ermiş bir şairin 

                     seslenişidir bu... 

                     Bu ak köpüklü gönül şarabından 

                     sende iç ; 

                     hadi korkma ! 

                     Ve kır çiçeklerinden bir fecr gibi 

                     doğ artık sabahlarıma... 

                     Bekliyorum 

                     ve bir gölge gibi peşinden 

                     ruhumu sürüklüyorum...', 'Bekliyorum,                       ateşten kirpikleriyle                       alaca karanlığında akşamın ;                       alnı ak dal...', ARRAY['Türk Edebiyatı','Şiir','Metin Bektaş']::text[], 8.5, '{"poet":"Metin Bektaş","poet_slug":"metin-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ruhumu-surukluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Uzak ÜLkelerin Çocuğuyum', 'ben-uzak-ulkelerin-cocuguyum-metin-bektas-uzrvr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bekleme beni 

                     ben uzak ülkelerin çocuğuyum 

                     Yağmurlar dolmuştur hep içime 

                     o yüzden ıslaktır gözlerim benim 

                     Şah damarımdan vurmuştur ihanetler, 

                     acılarla doludur içim dışım 

                     ve gülmek hiç yakışmaz dudaklarıma... 

                     Sen özleme beni 

                     kartal yuvalarına takılı umutlarım yok benim 

                     Sabrı dudaklarıma kanla yazmışım 

                     Tepinirken birileri 

                     özlemlerimin üzerinde hayasızca, 

                     soluğu,yalnızlıklara zincirlediğim 

                     akşamlarda almışım... 

                     Sen isteme beni 

                     yüreğimden başka hiç bir şeyim yok benim 

                     Koşmuşum çıplak sevdalarımla 

                     insanlığına yıllarca insanların 

                     ve her güldüğüm yerde yapayalnız 

                     her öldüğümde mezarsız kalmışım... 

                     Sen dinleme beni 

                     ucuz lisanlara tahammülüm yok benim 

                     Mavi gökler,kızıl şafaklar 

                     anlatsınlar söyleyeceklerimi sana 

                     Bir mazlumun iç çekişinde 

                     ve bir garibin 

                     ahında gizlidir benim dilim... 

                     Sen arama beni 

                     taze gül yapraklarına dürülü 

                     altın ışıklı sevinçlerim yok benim 

                     dev dev soluyorum tüm kavruk inançları 

                     ve farkettiğim günden beri gülüm ; gözyaşlarımı 

                     sevmeyi 

                     hiç beceremiyorum 

                     Aslan ölümlerinde söylenen 

                     her şeyi 

                     sana bırakıyorum 

                     Gidiyorum 

                     benim dünyam değil bu dünya 

                     ben uzak ülkelerin çocuğuyum.', 'Sen bekleme beni                       ben uzak ülkelerin çocuğuyum                       Yağmurlar dolmuştur hep içime                     ...', ARRAY['Türk Edebiyatı','Şiir','Metin Bektaş']::text[], 8.5, '{"poet":"Metin Bektaş","poet_slug":"metin-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ben-uzak-ulkelerin-cocuguyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakladım Seni', 'sakladim-seni-ali-atilgan-hyerh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yerlere sakladım seni

Kimselerin bulamayacağı

Kimselerin erişemeyeceği

Yıldızların arasına

Yağmur damlalarına

Martı çığlıklarına 

Vapur düdüklerine

Bazen şiirlerin mısralarına

Bazende şarkıların namelerine

Sokaklarıma ,yanlızlıklarıma 

Sakladım seni

Umutsuzluklarıma 

Seni özlemlerime;

Gözlerime sakladım seni

Kimseler bulamasın  diye', 'Bir yerlere sakladım seni Kimselerin bulamayacağı Kimselerin erişemeyeceği Yıldızların arasına Yağmur damlalarına Martı çığlıklarına  Vapur ...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sakladim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar gördüm', 'sevdalar-gordum-ali-atilgan-xgs54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdalar gördüm;

Sonbahar yaprakları gibi

oradan oraya

sevdalar gördüm;

uçsuz bucaksız

denizler gibi,

dalgalı..

sevdalar gördüm

öksüz çoçuklar gibi

bir başına 

çaresiz.......', 'Sevdalar gördüm; Sonbahar yaprakları gibi oradan oraya sevdalar gördüm; uçsuz bucaksız denizler gibi, dalgalı.. sevdalar gördüm öksüz çoçukl...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdalar-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutsam', 'unutsam-ali-atilgan-k1g9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesini unutsam,

dalgalar hatırlatır.

gözlerini unutsam,

yıldızlar hatırlatır.

Kokunu unutsam

rüzgarlar hatırlatır

seni unutsam 

şarkılar hatırlatır', 'Sesini unutsam, dalgalar hatırlatır. gözlerini unutsam, yıldızlar hatırlatır. Kokunu unutsam rüzgarlar hatırlatır seni unutsam  şarkılar hat...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemler', 'ozlemler-ali-atilgan-1kf3y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçsuz bucaksız denizlerde 

Gördüm özlemi

Dalgalar  olup kıyılara 

Vurdu kendini

Gökyüzünde gördüm 

Fırtınalar oldu;

yağmurlar oldu

Yıldırımlar oldu

Topraklara

İnsanlarda gördüm özlemi

Uçsuz bucaksız  yanlızlıklarında

Bakıyordu.Sanki bakışları

Ufukları delercesine', 'Uçsuz bucaksız denizlerde  Gördüm özlemi Dalgalar  olup kıyılara  Vurdu kendini Gökyüzünde gördüm  Fırtınalar oldu; yağmurlar oldu Yıldırıml...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Kırıntısı', 'umut-kirintisi-ali-atilgan-u5njz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün  yıldızlar kayboldu

Mis kokulu   rüzgarlar

dalgalar;

özlemlerim bitti.

Kör karanlıklarım kaldı yine

O uçsuz bucaksız

hani bir resim çizerdik ya

uzaklarda bir yerde;

yanlız bir ağaç vardı

yine o ağacın altında,

yine o karanlık

sensiz;

yıldızları göremiyorum

rüzgarları hissetmiyor

ya çiçekler;

onlar artık sen kokmuyor

Camlarım buğulanmıyor

gözlerim gülmüyor

Martılar bile;

onlar  bile sessiz artık.

akıp giden zaman olsun

sen mutlu ol

biliyorsun;gözlerinin ışıltısını

yıldızlara benzetirim hep

şimdi  parıldayan her yıldıza

bakarken ben,

gözlerin gelecek aklıma

bir gün bir yerlerde 

gelirsem aklına 

sebepsiz;

o da  yeter.', 'Bugün  yıldızlar kayboldu Mis kokulu   rüzgarlar dalgalar; özlemlerim bitti. Kör karanlıklarım kaldı yine O uçsuz bucaksız hani bir resim çi...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/umut-kirintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pul Pul', 'pul-pul-can-yucel-1f3eu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sağ gözü ağladı önce, durduğu yerde,

Ne acıdığından, ne de kederinden;

Zati ilk düşen damlada 

Ne insanlar, ne kendisi vardı...

Koştular çırılçıplak,

Mağara duvarlarına çizilmiş ceylan gözleri,

Koştular, koştular sahile;

İlk düşen damlada deniz vardı...

Şaşırdılar, utandılar da birbirlerinden

Daldılar, daldılar derine

Nefesleri, nefesleri kesilinceye dek;

Işıklı bitkiler içinde

Işıklı balıklar gördüler,

Şaşırdılar, şaşırdılarda ...

Zati ilk düşen damlada güneş vardı...', 'Sağ gözü ağladı önce, durduğu yerde, Ne acıdığından, ne de kederinden; Zati ilk düşen damlada  Ne insanlar, ne kendisi vardı... Koştular çır...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/pul-pul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çobanın Sevdası', 'cobanin-sevdasi-bayram-tunca-ju4zc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldım kavalı elime, çaldım ney gibi acı acı

Tabip değil, yaban gülüdür, derdimin ilacı

Ölüm Allah’ın emri, hasretlik ondan da acı

Başkaları acımadı Yaban gülü bari sen acı

Kavalımın sesini koyun ile kuzu dinledi

Onlar bile lisan-ı haliyle meleşip inledi

Yaban gülü gelmeden hasretliğim dinmedi

Dağ taş, ağaç yaprak, ot toprak, hep inledi

Bak, saldım koyun ile kuzuyu düz ovaya

Yıllarca koşturdum durdum oraya buraya

Bir derman bulamadım, kalbimdeki yaraya

Yarim gelseydi, merhem olurdu bu yaraya

Saldım koyun - kuzuyu yeşil çayıra

Yaban Gülümle oturduk, bir bayıra

Aşkımızı ilân ettik gerisini Mevlâ kayıra

Bundan sonra, ikimizi ancak ölüm ayıra

Serdik kepeneği yeşil çimenin üstüne

Yaban güllüyle ikimiz oturduk üstüne

Kalbimize yaptık, o sevginin büstüne

Kimseyi sevmeyiz bu sevginin üstüne

Saldım koyun ile kuzuyu yeşil çimene

Biz birbirimizi ezelden sevdik kime ne

Allah kaderimizi böyle yazmış kime ne

Bundan böyle bizi ölüm ayırır kime ne

Saldım koyun ile kuzuyu ormana

El görürse, söz eder diye, gelmedim obana

Dayanamıyorum, yetim misali ayrı kalmana

Bizimkilere, dünürcü saldım, anana babana

Çok bekletme, yazıktır bu bayram çobana

Her an, aşkından yağ gibi eriyor baksana

Utanıyorsan babandan, söylesene anana

Gelin gitmek istiyom, desene bu çobana

Nihayet Yaban Gülüm, bize gelin geliyor

Çoban Bayram ile Yaban Gülü evleniyor

Görenler, ne de güzel yakışmışlar diyor

Gökteki Melek bile bu vuslatı alkışlıyor

B. TUNCA/16.03.2001-14.35', 'Aldım kavalı elime, çaldım ney gibi acı acı Tabip değil, yaban gülüdür, derdimin ilacı Ölüm Allah’ın emri, hasretlik ondan da acı Başkaları ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/cobanin-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Güzel*', 'hey-guzel-bayram-tunca-k40ib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzele/güzel mi gelir, sanırsın naz

Hey Leylâ, ne olur insafa gel biraz

Başkaları acımadı sen olsun acı az

Gelirsen insafa, duyarım çook haz

Hey güzel baki mi sanırsın o güzelliğini

Her güzel gibi bir gün alırlar güzelliğini

Nice huriler gelip geçti bu fani dünyadan

Hem de gençliğine tam olarak doymadan

Sanma ki, bu güzelliğin baki kalır sende

Bir gün gelir, zerresi dahi kalmaz sende

Bu güzelliğin verilmiş bir emanettir sende

Bence, her şeyin fani olduğunu bil sen de

Eğer, verilen bu güzelliği bakileştirmek istersen

Eğer, sen de ''helal dairesi keyfe kafidir'' dersen

Gel sen de bu güzelliğini helal dairesinde harca

Katiyen girme, gayri meşru yola ömür boyunca

18.03.2001-10.30', 'Güzele/güzel mi gelir, sanırsın naz Hey Leylâ, ne olur insafa gel biraz Başkaları acımadı sen olsun acı az Gelirsen insafa, duyarım çook haz...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hey-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
