INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Musikileri', 'kar-musikileri-yahya-kemal-beyatli-xhvut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Varşova 1927-

Bin yıldan uzun bir gecenin bestesidir bu.

Bin yıl sürecek zannedilen kar sesidir bu.

Bir kuytu manastırda duâlar gibi gamlı,

Yüzlerce ağızdan koro hâlinde devamlı,

Bir erganun âhengi yayılmakta derinden...

Duydumsa da zevk almadım İslav kederinden.

Zihnim bu şehirden, bu devirden çok uzakta,

Tanbûri Cemil Bey çalıyor eski plâkta.

Birdenbire mes''ûdum işitmek hevesiyle

Gönlüm dolu İstanbul''un en özlü sesiyle.

Sandım ki uzaklaştı yağan kar ve karanlık,

Uykumda bütün bir gece Körfez''deyim artık!', '-Varşova 1927- Bin yıldan uzun bir gecenin bestesidir bu. Bin yıl sürecek zannedilen kar sesidir bu. Bir kuytu manastırda duâlar gibi gamlı,...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kar-musikileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-asli-han-s5qjv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yerine ulaşamayan mektuplar gibiyim.

Damgalı,

pullu,

parası ödenmiş

           sahipsiz.

          Kalbim yanlış adreste

          Sende kaldı.', 'Yerine ulaşamayan mektuplar gibiyim. Damgalı, pullu, parası ödenmiş            sahipsiz.           Kalbim yanlış adreste           Sende kal...', ARRAY['Türk Edebiyatı','Şiir','Aslı Han']::text[], 8.5, '{"poet":"Aslı Han","poet_slug":"asli-han","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mektup-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
