INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fetihe Doğru', 'fetihe-dogru-mustafa-bagci-8397t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fetihe doğru gitmeden atıldı bütün temeller,

  Sonra yola koyuldu; askerle toplar gülleler,

  Edirne''den İstanbul''a hareket etti her nefer

  O anda hiç susmaz tekbir sesleriyle mehter..

  Sultan Mehmed dedi: ileri aslanlarım ileri!

  Parola; ölürsek şehidiz kalırsak gazi,

  Her nefer dile getirdi Kelime-i Şehadeti,

  Her askerin aklında peygamberimizin hadisi.

  Şahilerle, güllelerle Bizans surlarını deldik,

  Tevhidle, tekbirle surlardan içeri girdik,

  Mehter takımının cenk havalarıyla hücum ettik;

  Ortalığı inleten tekbir sesleriyle İstanbul''u fethettik.

  Bin elli sekiz yıllık Bizans; tarihe karıştı,

  Başkent; Edirne''den İstanbul''a taşındı.

  Dünyaya İslam''ın namı bir kez daha kanıtlandı,

  Osmanlı; ''imparatorluk'' ünvanını şanla aldı.', 'Fetihe doğru gitmeden atıldı bütün temeller,   Sonra yola koyuldu; askerle toplar gülleler,   Edirne''den İstanbul''a hareket etti her nefer  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bağcı']::text[], 8.5, '{"poet":"Mustafa Bağcı","poet_slug":"mustafa-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fetihe-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Malazgirt Zaferi', 'malazgirt-zaferi-mustafa-bagci-6e6xc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yükselecek İslam; müreyyet namın,

  Selçuklular kılıcı olacak bu savaşta İslam''ın,

  Meydan Malazgirt; Diyojen''le Alparslan''ın,

  Sözümüz; kanımız aksa da zafer İslam''ın.

  Bir destan yazdık Malazgirt ovasında,

  Alparslan ile Romen Diyojen arasında,

  Bozguna uğradı Bizans; Türkler''in hücumunda,

  Dünyaya nam saldı İslam; bu savaşla.

  Anadolu kapısı açıldı Türkler''e Alparslan''la 

  Terk etmedik toprakları, devam ettik Osmanlılarla,

  Bin dokuz yüz yirmi iki başka bir 26 Ağustos''la

  Büsbütün topraklar bizim oldu Anadolu''da.', 'Yükselecek İslam; müreyyet namın,   Selçuklular kılıcı olacak bu savaşta İslam''ın,   Meydan Malazgirt; Diyojen''le Alparslan''ın,   Sözümüz; k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bağcı']::text[], 8.5, '{"poet":"Mustafa Bağcı","poet_slug":"mustafa-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/malazgirt-zaferi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-erdem-ozbek-f3zv2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni ayrılık acısı kadar sevdim 

yıkılan taş duvarların arasında

yüzümün silüetinin vurduğu

tozlu resimler ardında düştüm salıncaktan

bekledim seni 

ölümü bekleyen kanser hastası gibi

seni sevdiğim eve gittim geçen hafta sonu

merdivenin 3.basamağı hala kırık

boynumda unutmuşum evin anahtarını

hani kaybetmekten korkardımya hep

onun için asmıştım sanırım 

ama kaybettim 

dağın yamacında oturmuştukya hani

öyle dalıp gitmişim yine orada

beş şişe içmişim şaraptan 

sigarayı zaten sayamadım

seni ayrılık acısı kadar sevdim

yüzüm ellerim kanamış

kışın soğuğu dokunmuş olacak

çatlak çatlak yüreğim 

içime akmış hep sensiz irinlerim

koca gözlü baykuş gibi açılmış kanatların

belki uçmaktasın artık

göğsüm ağrıyor, hemde nasıl bir bilsen 

bakma sesimin çıkmadığına 

içimdeki tütünleri yakıp külünü bastım 

ondandır sessizliğim

seni ayrılık acısı kadar sevdim

ama sevmedim ayrılığı 

denizdeki yakamozların onda biri kadar

en son dün gece girdin rüyama 

o en sevdiğim kareli gömleğini giymişsin

dudakların soğuk 

heyecanlanınca olurdu hep buz gibi

anlayamadım bu sefer sebebini

tırnaklarınıda kesmişsin, istediğim gibi olmuş

saçlarını da açmışsın

hayıra yordum seni, sonra iyice sarıp yüreğime koydum

seni ayrılık acısı kadar sevdim 

belkide ayrılığı sevdim, seni zannaderken

erdem özbek  19/03/2001', 'seni ayrılık acısı kadar sevdim  yıkılan taş duvarların arasında yüzümün silüetinin vurduğu tozlu resimler ardında düştüm salıncaktan bekled...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özbek']::text[], 8.5, '{"poet":"Erdem Özbek","poet_slug":"erdem-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/seni-sevdim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-yahya-kemal-beyatli-imr0e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerce ne gördüm ne de kimseye sordum, 

''Yarab! hele kalp ağrılarım durdu!'' diyordum. 

His var mı bu alemde nekahat gibi tatlı 

Gönlüm bu sevincin heyecanıyla kanatlı 

Bir taze bahar alemi seyretti felekte, 

Mevsim mütehayyil, vakit akşamdı Bebek''te, 

Akşam!.. Lekesiz,,saf, iyi bir yüz gibi akşam!.. 

Ta karşı bayırlarda tutuşmuş iki üç cam; 

Sakin koyu,şen cepheli kasrıyle Küçüksu, 

Ardında vatan semtinin ormanları kuytu; 

Bir neşeli hengamede çepçevre yamaçlar 

Hep aynı tehassüsle meyillenmiş ağaçlar 

Dalgın duyuyor rüzgarın ahengini dal dal. 

Baktım süzülüp geçti açıktan iki sandal. 

Bir lahzada bir pancur açılmış gibi yazdan 

Bir bestenin engin sesi yükseldi boğazdan 

Coşmuş yine bir aşkın uzak hatırasıyla, 

Aksetti uyanmış tepelerden sırasıyla, 

Dağ dağ o güzel ses bütün etrafı gezindi: 

Görmüş ve geçirmiş denizin kalbine sindi. 

Ani bir üzüntüyle bu rüyadan uyandım. 

Tekrar o alev gömleği giymiş gibi yandım, 

Her yerden o,hem aynı bakış ,aynı emelde, 

Bir kanlı gül ağzında ve mey kasesi elde; 

Her yerden o, hem aynı güzellikte göründü, 

Sandım bu biten gün beni ram ettiği gündü.', 'Günlerce ne gördüm ne de kimseye sordum,  ''Yarab! hele kalp ağrılarım durdu!'' diyordum.  His var mı bu alemde nekahat gibi tatlı  Gönlüm bu ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ses-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-yahya-kemal-beyatli-jz6nx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fani ömür biter, bir uzun sonbahar olur. 

Yaprak, çiçek ve kuş dağılır, tarumar olur.

Mevsim boyunca kendini hissettirir veda; 

Artık bu dağdağayla uğuldar deniz ve dağ.

Yazdan kalan ne varsa olurken haşır neşir. 

Günler hazinleşir, geceler uhrevileşir; 

Teşrinlerin bu hüznü geçer ta iliklere. 

Anlar ki yolcu yol görünür selviliklere. 

Dünyanın ufku gözlere gittikçe tar olur. 

Her gün sürüklenip yaşamak ruha bar olur. 

İnsan duyar yerin dile gelmiş sükutunu; 

Bir başka musikiiye geçiş farz eder bunu. 

Teslim olunca vadesi gelmiş zevaline, 

Benzer cihana gelmeden evvelki haline. 

Yaprak nasıl düşerse akıp kaybolan suya 

Ruh öyle yollanır uyanılmaz bir uykuya: 

Duymaz bu anda taş gibi kalbinde bir sızı; 

Fark etmez anne - toprak ölüm maceramızı.', 'Fani ömür biter, bir uzun sonbahar olur.  Yaprak, çiçek ve kuş dağılır, tarumar olur. Mevsim boyunca kendini hissettirir veda;  Artık bu dağ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sonbahar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufuklar', 'ufuklar-yahya-kemal-beyatli-1ivr0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruh ufuksuz yaşamaz. 

Dağlar ufkunda mehabet, 

Ova ufkunda huzur, 

Deniz ufkunda teselli duyulur. 

Yalnız onlarda bulur ruh ezeli lezzetini. 

Bu ufuklar avutur ruhu saatlerce, fakat 

Bir zaman sonra derinden duyulur yalnızlık. 

Ruh arar kendine bir ruh ufku. 

Manevi ufku pek engin ulu peygamberler 

- Bahsin üstündedir onlar-lakin 

Hayli me''ud idiler dünyada; 

Yaşıyorlardı havarileri, ashabiyle; 

Ne ufuklar! Ne güzel ruh imiş onlar! Yarab! 

Annemin na''şını gördümdü; 

Bakıyorken bana sabit ve donuk gözlerle, 

Acıdan çıldıracaktım. 

Aradan elli dokuz yıl geçti. 

Ah o sabit bakış el''an yaradır kalbimde, 

O yaşarken o semavi, o gülümser gözler 

Ne kadar engin ufuklardı bana; 

Teneşir tahtası üstünde o gün, 

Bakmaz olmuşlardı artık bu bizim dünyaya. 

Yaşıyan her fani 

Yaşıyan ruh özler, 

Her sıkıldıkça arar, 

Dar hayatında ya dost ufku, ya canan ufku.', 'Ruh ufuksuz yaşamaz.  Dağlar ufkunda mehabet,  Ova ufkunda huzur,  Deniz ufkunda teselli duyulur.  Yalnız onlarda bulur ruh ezeli lezzetini....', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ufuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-orhan-veli-kanik-0wrql', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kargalar, sakın anneme söylemeyin! 

Bugün toplar atılırken evden kaçıp 

Harbiye Nezareti’ne gideceğim. 

Söylemezseniz size macun alırım, 

Simit alırım, horoz şekeri alırım; 

Sizi kayık salıncağına bindiririm kargalar, 

Bütün zıpzıplarımı size veririm. 

Kargalar, ne olur anneme söylemeyin!', 'Kargalar, sakın anneme söylemeyin!  Bugün toplar atılırken evden kaçıp  Harbiye Nezareti’ne gideceğim.  Söylemezseniz size macun alırım,  Si...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bayram-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birdenbire', 'birdenbire-orhan-veli-kanik-8e08w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sey birdenbire oldu.

Birdenbire vurdu gün isigi yere;

Gökyüzü birdenbire oldu;

Mavi birdenbire.

Her sey birdenbire oldu;

Birdenbire tütmeye basladi duman topraktan;

Filiz birdenbire oldu, tomurcuk birdenbire.

Yemis birdenbire oldu.

Birdenbire,

Birdenbire;

Her sey birdenbire oldu.

Kiz birdenbire, oglan birdenbire;

Yollar, kirlar, kediler, insanlar...

Ask birdenbire oldu,

Sevinç birdenbire.', 'Her sey birdenbire oldu. Birdenbire vurdu gün isigi yere; Gökyüzü birdenbire oldu; Mavi birdenbire. Her sey birdenbire oldu; Birdenbire tütm...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birdenbire-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehri Bırakmak', 'bir-sehri-birakmak-orhan-veli-kanik-auzne', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehirde yağmur altında dolaşılır

Limandaki mavnalara bakıp

Şarkılar mırıldanılır geceleri.

Bu şehrin sokakları çoktur,

Binlerce insan gelir gider sokaklarında..

Her akşam çayımı getiren

Ve bir Beyaz Rus olmasına rağmen

Hoşuma giden garson kadın bu şehirdedir.

Bu şehirdedir

Valsler, foksrotlar altında

Suman''dan, Bramsdan

Parçalar çaldığı zaman dönüp

Bana bakan ihtiyar piyanist.

Doğduğum köye müşteri taşıyan

Şirket vapurları bu şehirdedir.

Hatıralarım bu şehirdedir.

Sevdiklerim,

Ölmüşlerimin mezarları.

Bu şehirdedir işim gücüm,

Ekmek param.

Fakat bütün bunlara mukabil

Yine budur başka bir şehirdeki

Bir kadın yüzünden

Bıraktığım şehir.

Papirus, 1967', 'Bu şehirde yağmur altında dolaşılır Limandaki mavnalara bakıp Şarkılar mırıldanılır geceleri. Bu şehrin sokakları çoktur, Binlerce insan gel...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-sehri-birakmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Çarşı', 'kapali-carsi-orhan-veli-kanik-1zg4j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Giyilmemiş çamaşırlar nasıl kokar bilirsin,

Sandık odalarında; 

Senin de dükkânın öyle kokar işte.

Ablamı tanımazsın,

Hürriyette gelin olacaktı, yaşasaydı; 

Bu teller onun telleri,

Bu duvak onun duvağı işte.

Ya bu çamurdaki kadınlar? 

Bu mavi mavi,

Bu yeşil yeşil fistanlı...

Geceleri de ayakta mi dururlar böyle? 

Ya bu pembezar gömlek? 

Onun da bir hikayesi yok mu? 

Kapalı Çarşı deyip geçme; 

Kapalı Çarşı,

Kapalı kutu', 'Giyilmemiş çamaşırlar nasıl kokar bilirsin, Sandık odalarında;  Senin de dükkânın öyle kokar işte. Ablamı tanımazsın, Hürriyette gelin olaca...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kapali-carsi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmakarışık', 'karmakarisik-orhan-veli-kanik-7g2rq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir okla yarali kalbim

Boyacinin sandiginda;

Guvercinim kagit helvasinda;

Sevgilim kayigin burnunda;

Yarisi balik,

Yarisi insan;

In miyim?

Cin miyim?

Ben neyim?', 'Bir okla yarali kalbim Boyacinin sandiginda; Guvercinim kagit helvasinda; Sevgilim kayigin burnunda; Yarisi balik, Yarisi insan; In miyim? C...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karmakarisik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabaha Kadar', 'sabaha-kadar-orhan-veli-kanik-8pkgk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu şairler sevgililerden beter; 

Nedir bu adamlardan çektiğim? 

Olur mu böyle, bütün bir geceyi 

Bir mısranın mahremiyetinde geçirmek? 

Dinle bakalım, işitebilir misin 

Türküsünü damların, bacaların 

Yahut da karıncaların buğday taşıdıklarını 

Yuvalarına? 

Beklemesem olmaz mı güneşin doğmasını 

Kullanılmış kafiyeleri yollamak içein, 

Kapıma gelecek çöpçülerle, 

Deniz kenarına? 

Şeytan diyor ki: ''Aç pencereyi; 

Bağır, bağır, bağır; sabaha kadar.''', 'Şu şairler sevgililerden beter;  Nedir bu adamlardan çektiğim?  Olur mu böyle, bütün bir geceyi  Bir mısranın mahremiyetinde geçirmek?  Dinl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sabaha-kadar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şanolu Şiir', 'sanolu-siir-orhan-veli-kanik-a1s2v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadehlerin biri gelir, biri gider; 

Mezeler çeşit çeşit; 

Bir sevdiğim şanoda şarkı söyler: 

Biri yanıbaşımda, 

İçer içer, ötekini kıskanır. 

Kıskanma, güzelim, kıskanma; 

Senin yerin başka, 

Onun yeri başka.', 'Kadehlerin biri gelir, biri gider;  Mezeler çeşit çeşit;  Bir sevdiğim şanoda şarkı söyler:  Biri yanıbaşımda,  İçer içer, ötekini kıskanır....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanolu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şoförün Karısı', 'soforun-karisi-orhan-veli-kanik-477wq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şöförün karısı, kıyma bana;

El etme öyle pencereden,

Soyunup dökünüp;

Senin, eniştende gözün var;

Benimse gençliğim var;

Mapuslarda çürüyemem;

Başımı belaya sokma benim;

Kıyma bana.', 'Şöförün karısı, kıyma bana; El etme öyle pencereden, Soyunup dökünüp; Senin, eniştende gözün var; Benimse gençliğim var; Mapuslarda çürüyeme...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/soforun-karisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Anam', 'canim-anam-aydin-cemal-rskb2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her ankaraya gelişimde

sabahın kuru soğuğuna aldırmadan

beklersin beni balkonda

ah anam canım anam

bir ankara gelişimde

göremez isem seni balkonda

biliyorum bekleyeceksin beni

cennet bahçenin kapısında', 'her ankaraya gelişimde sabahın kuru soğuğuna aldırmadan beklersin beni balkonda ah anam canım anam bir ankara gelişimde göremez isem seni ba...', ARRAY['Türk Edebiyatı','Şiir','Aydın Cemal']::text[], 8.5, '{"poet":"Aydın Cemal","poet_slug":"aydin-cemal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canim-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysa', 'oysa-aydin-cemal-yzvgf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Savaşma seviş diye

Yazarlar duvarlara

Birkez sevişebilmek için,

Ne savaşlar yapılır oysa.', 'Savaşma seviş diye Yazarlar duvarlara Birkez sevişebilmek için, Ne savaşlar yapılır oysa....', ARRAY['Türk Edebiyatı','Şiir','Aydın Cemal']::text[], 8.5, '{"poet":"Aydın Cemal","poet_slug":"aydin-cemal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oysa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürü Bre Yalan Dünya', 'yuru-bre-yalan-dunya-pir-sultan-abdal-hvdui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürü bre yalan dünya

Yalan dünya değil misin

Hasan ile Hüseyin''i

Alan dünya değil misin

Ali bindi Düldül ata

Can dayanmaz bu firkata

Boz kurt ile kıyamete

Kalan dünya değil misin

Tanrı''nın Arslan''ın alıp

Düldül''ü dağlara salıp

Yedi kere ıssız kalıp

Dolan dünya değil misin

Bak şu kaşa, bak şu göze

Ciğer kebap oldu köze

Muhammed''i bir top beze

Saran dünya değil misin

Pir Sultan''ım ne yatarsın

Kurmuş çarhını dönersin

Ne konarsın ne göçersin

Duran dünya değil misin', 'Yürü bre yalan dünya Yalan dünya değil misin Hasan ile Hüseyin''i Alan dünya değil misin Ali bindi Düldül ata Can dayanmaz bu firkata Boz kur...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuru-bre-yalan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyur İdik Uyardılar', 'uyur-i-dik-uyardilar-pir-sultan-abdal-a2nvg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyur idik uyardılar

Diriye saydılar bizi

Koyun olduk ses anladık

Sürüye saydılar bizi

Sürülüp kasaba gittik

Kanarada mekan tuttuk

Seri Hakk''a teslim ettik

Ölüye saydılar bizi

Halimizi hal eyledik

Yolumuzu yol eyledik

Her çiçekten bal eyledik

Arıya saydılar bizi

Pir divanına dizildik

Aşk defterine yazıldık

Bal olduk şerbet ezildik

Doluya saydılar bizi

Pir Sultan Abdal''ım şunda

Çok keramet var insanda

O cihanda bu cihanda

Ali''ye saydılar bizi', 'Uyur idik uyardılar Diriye saydılar bizi Koyun olduk ses anladık Sürüye saydılar bizi Sürülüp kasaba gittik Kanarada mekan tuttuk Seri Hakk''...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyur-idik-uyardilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Yalan Dünyaya (Bulamadım)', 'su-yalan-dunyaya-bulamadim-pir-sultan-abdal-95n95', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu yalan dünyaya geldim geleli

Özge elden özge yar bulamadım

Yaralandım al kanlara boyandım

Elimin kanını yur bulamadım

Dostun zülüfleri destedir deste

Erenler hak için oturmuş posta

Bir zaman sağ gezdim bir zaman hasta

Hasta halin nedir der bulamadım

Felek kırdı benim kolum kanadım

Baykuş gibi viranlarda tünedim

Bugün üç güzelin nabzın sınadım

Can feda yoluna der bulamadım

Pir Sultan Abdal''ım dağlar ben olsam

Dağlarda biten laleler ben olsam

Alem çiçek olsa arı ben olsam

Dost elinden tatlı bal bulamadım', 'Şu yalan dünyaya geldim geleli Özge elden özge yar bulamadım Yaralandım al kanlara boyandım Elimin kanını yur bulamadım Dostun zülüfleri des...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-yalan-dunyaya-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Tanrım', 'ey-tanrim-aydin-cemal-11xuu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ey Tanrım!

şarabı yasak eyleyecektin

neden aşkın tohumlarını

insanların kalbine serptin

hadi aşkı yarattın diyelim

bari balıksız olsaydı denizlerin', 'ey Tanrım! şarabı yasak eyleyecektin neden aşkın tohumlarını insanların kalbine serptin hadi aşkı yarattın diyelim bari balıksız olsaydı den...', ARRAY['Türk Edebiyatı','Şiir','Aydın Cemal']::text[], 8.5, '{"poet":"Aydın Cemal","poet_slug":"aydin-cemal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ey-tanrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendedir Sende', 'sendedir-sende-pir-sultan-abdal-bzo0s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni görüp yönün öte döndürme

Yine gitmez meylim sendedir sende

Yıkıp hilâl kaşlarını yere indirme

Günah sende değil bendedir bende

Şeker vardır dudağında dilinde

Arzumanım kaldı gonca gülünde

Sen bir padişâhsın hükmün elinde

Senin ile dâvam sendedir sende

Sensiz çıkıp yaylaları yaylamam

Engeller içinde sırrın söylemem

Çok günah işledim inkâr eylemem

İk''ellerim kızıl kandadır kanda

Nice beyler ile gezdim yoruldum

Kan bulanık aktım duruldum

Sencileyin çok güzele sarıldım

Dahi sevgin candadır canda

Pîr Sultan Abdal''ım böyle deyiptir

Âşıklar güzeli sevegeliptir

Bir güzel sevmeyle kanlı m''oluptur

Kellem terkidedir yandadır yanda', 'Beni görüp yönün öte döndürme Yine gitmez meylim sendedir sende Yıkıp hilâl kaşlarını yere indirme Günah sende değil bendedir bende Şeker va...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sendedir-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazarlık Mı Olur', 'pazarlik-mi-olur-pir-sultan-abdal-q6jib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ilgıt ılgıt esen seher yelleri

Doğru gelir doğru gider mi yar yar

Hakkın emri ile çürüyen canlar

Verdiği ikrarda durur mu yar yar

Pazarlık mı olur adil dükkanda

Neylim muhabbetim yar kaldı sende

Bu divan olmazsa ulu divanda

Dost benim sualimi verir mi yar yar

Bahçemde açılmış yar gonca güller

Gülün fidanından sefil bülbüller

Aşıktan maşuğa da sarılan kollar

Bin yıl yerde yatsa çürür mü yar yar

ABDAL PİR SULTAN''ım gönlü zar olan

Döner mi sözünden gerçek er olan

Senin gibi ahtı sadık yar olan

Verdiği ikrardan döner mi yar yar', 'Ilgıt ılgıt esen seher yelleri Doğru gelir doğru gider mi yar yar Hakkın emri ile çürüyen canlar Verdiği ikrarda durur mu yar yar Pazarlık m...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pazarlik-mi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötme Bülbül Ötme', 'otme-bulbul-otme-pir-sultan-abdal-8q4pj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ötme bülbül ötme şen değil bağım

Dost senin derdinden ben yana yana

Tükendi fitilim eridi yağım

Dost senin derdinden ben yana yana

Deryadan bölünmüş sellere döndüm

Ateşi kararmış küllere döndüm

Vakitsiz açılmış güllere döndüm

Dost senin derdinden ben yana yana

Haberin duyarsın peyikler ile

Yaramı sarsınlar şehidler ile

Kırk yıl dağda gezdim geyikler ile

Dost senin derdinden ben yana yana

Abdal Pir Sultan''ım, doldum eksildim

Yemeden içmeden sudan kesildim

Zülfün kemendine kondum asıldım

Dost senin derdinden ben yana yana

		

Pir Sultan Abdal', 'Ötme bülbül ötme şen değil bağım Dost senin derdinden ben yana yana Tükendi fitilim eridi yağım Dost senin derdinden ben yana yana Deryadan ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/otme-bulbul-otme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda Her Kişinin Dostu Bulunmaz', 'orda-her-kisinin-dostu-bulunmaz-pir-sultan-abdal-blt0v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıktım yücesine seyran eyledim

Gönül eğlencesi küstü bulunmaz

Dostlar bizden muhabbetin kaldırmış

Hiç bir ikrarında ahdi bulunmaz

Zülüflerin top top olmuş çığalı

Rakiplerin hak''dan olsun zevali

Bir günahkar kulum doğdum doğalı

Günahkar kulunun dostu bulunmaz

Kanı benim ile lokma yiyenler

Baş ü canı dost yoluna koyanlar

Sen ölmeden ben ölürüm diyenler

Dostlar da geriye kaçtı bulunmaz

Yine karçılandı dağların başı

Durmadan akıyor gözümün yaşı

Vefasız elinden gitse bir kişi

Hakikat ceminde desti bulunmaz

Biz de gezer idik irfanda sazda

Biz de bulunurduk cem de, niyaz da

Bize de gel oldu kanlı Sivas da

Hızır paşa bizi astı bulunmaz

PİR SULTAN ABDAL''ım destim damanda

İsmim koca Haydar, neslim Yemen''de

Garip başa bir hal gelse zamanda

Orda her kişinin dostu bulunmaz', 'Çıktım yücesine seyran eyledim Gönül eğlencesi küstü bulunmaz Dostlar bizden muhabbetin kaldırmış Hiç bir ikrarında ahdi bulunmaz Zülüflerin...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/orda-her-kisinin-dostu-bulunmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Yar Diyeyim', 'nasil-yar-diyeyim-pir-sultan-abdal-t03uj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl yar diyeyim ben böyle yare

Mecnun edip çöle saldıktan sonra

Alemin bağına bülbüller konmuş

Nidem benim gülüm solduktan sonra

Karadır kaşların keman istemem

Şu gönlümden özge mihman istemem

Ölsem de derdime derman istemem

Ok vurup sinemi deldikten sonra

Coşkun çaylar gibi çağlamayan yar

Gönlünü gönlüme bağlamayan yar

Benim bu halime ağlamayan yar

Daha ağlamasın öldükten sonra

Pir Sultan Abdal''ım sürem bu yolu

İnsan-ı kamilin olurum kulu

İster yağmur yağsın isterse dolu

Nidem ben ummana daldıktan sonra', 'Nasıl yar diyeyim ben böyle yare Mecnun edip çöle saldıktan sonra Alemin bağına bülbüller konmuş Nidem benim gülüm solduktan sonra Karadır k...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-yar-diyeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Olayım Kalem Tutan Eline', 'kul-olayim-kalem-tutan-eline-pir-sultan-abdal-x12r7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kul olayım kalem tutan eline

Kâtip ahvalimi şah''a böyle yaz

Şekerler ezeyim şirin diline

Kâtip ahvalimi şah''a böyle yaz

Allahı seversen kâtip böyle yaz

Dün ü gün ol şah''a eylerim niyaz

Umarım yıkılır şu kanlı Sivas

Kâtip ahvalimi şah''a böyle yaz

Sivas illerinde sazım çalınır

Çamlı beller bölük bölük bölünür

Ben dosttan ayrıldım bağrım delinir

Kâtip ahvalimi şah''a böyle yaz

Münafıkın her dediği oluyor

Gül benzimiz sararuban soluyor

Gidi Mervan sâd oluban gülüyor

Kâtip ahvalimi şah''a böyle yaz

Pir Sultan Abdal''ım ey Hızır Paşa

Gör ki neler gelir sağ olan başa

Hasret koydu bizi kavim kardaşa

Kâtip ahvalimi şah''a böyle yaz', 'Kul olayım kalem tutan eline Kâtip ahvalimi şah''a böyle yaz Şekerler ezeyim şirin diline Kâtip ahvalimi şah''a böyle yaz Allahı seversen kâti...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kul-olayim-kalem-tutan-eline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Başlı Koca Kadı', 'koca-basli-koca-kadi-pir-sultan-abdal-bui9b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koca başlı koca kadı

Sende hiç din iman var mı

Haramı helali yedi

Sende hiç din iman var mı

Fetva verir yalan yulan

Domuz gibi dağı dolan

Sırtına vururum palan

Senin gibi hayvan var mı

İman eder amel etmez

Hakk''ın buyruğuna gitmez

Kadılar yaş yere yatmaz

Hiç böyle bir şeytan var mı

Pir Sultan''ım zatlarımız

Gerçektir şöhretlerimiz

Haram yemez itlerimiz

Bu sözümde yalan var mı', 'Koca başlı koca kadı Sende hiç din iman var mı Haramı helali yedi Sende hiç din iman var mı Fetva verir yalan yulan Domuz gibi dağı dolan Sı...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/koca-basli-koca-kadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyanın Üzerinde Kurulu Direk', 'dunyanin-uzerinde-kurulu-direk-pir-sultan-abdal-g4wko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyanın üzerinde kurulu direk

Emek sayılmadan, sızlar bu yürek

Bu düzeni kim kurmuş bizler de bilek

Söyle canım söyle dinlesin canlar

Ocağa koymuşlar köşe taşını

Hak kollasın gerçeklerin işini

Bir gün ağrıdırlar senin başını

Söyle canım söyle dinlesin canlar

Adem eker yeryüzüne ekini

Ekin saklar yer altında kökünü

Ayıkla gör karasını akını

Söyle canım söyle dinlesin canlar

Pir Sultan Abdal''ım farz eylesinler

Yola gelmeyenden edilmez minnet

Cümlenin muradı dünyada cennet

Söyle canım söyle dinlesin canlar', 'Dünyanın üzerinde kurulu direk Emek sayılmadan, sızlar bu yürek Bu düzeni kim kurmuş bizler de bilek Söyle canım söyle dinlesin canlar Ocağa...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunyanin-uzerinde-kurulu-direk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönen Dönsün', 'donen-donsun-pir-sultan-abdal-ajwis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koyun beni hak aşkına yanayım

Dönen dönsün ben dönmezem yolumdan

Yolumdan dönüp de mahrum mu kalayım

Dönen dönsün ben dönmezem yolumdan

Kadılar müftüler fetva yazarsa

İşte kement işte boynum asarsa

İşte hançer işte başım keserse

Dönen dönsün ben dönmezem yolumdan

Bir gün mahşer olur divan kurulur

Suçlu suçsuz varsa orda bulunur

Piri olmayanlar anda bilinir

Dönen dönsün ben dönmezem yolumdan

PİR SULTAN''ım arşa çıkar ünümüz

O da bizim ulumuzdur pirimiz

Hakka teslim olsun garip canımız

Dönen dönsün ben dönmezem yolumdan', 'Koyun beni hak aşkına yanayım Dönen dönsün ben dönmezem yolumdan Yolumdan dönüp de mahrum mu kalayım Dönen dönsün ben dönmezem yolumdan Kadı...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donen-donsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzelin Aşığıyım', 'bir-guzelin-asigiyim-pir-sultan-abdal-5ezpn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güzelin aşığıyım erenler

Onun için taşa tutar el beni

Gündüz hayalimde gece düşümde

Kumdan kuma savuruyor yel beni

Al gül olsam al gerdana takılsam

Kemer olsam ince bele sarılsam

Köle olsam pazarlarda satılsam

Yarim deyi al sinene sar beni

Abdal Pir Sultan''ım gamzeler oktur

Hezaran sinemde yaralar çoktur

Benim senden özge sevdiğim yoktur

İnanmazsan git Allah''a sor beni', 'Bir güzelin aşığıyım erenler Onun için taşa tutar el beni Gündüz hayalimde gece düşümde Kumdan kuma savuruyor yel beni Al gül olsam al gerda...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-guzelin-asigiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Öldüğümde', 'ben-oldugumde-aydin-cemal-squ3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlarmısın Erdem''im ben ölgüğümde

Ağlama sen teselli et sevgili babamı

Alper, sen kardeşimi.

Ablamı da sevgililerime bırakıyorum

Yaşadığımı anlamadılar

Ama öldüğümü bilirlerse.

Canım annem!

Seni ise ne teselli edebilirki

Yaşıyor olmamdan başka', 'Ağlarmısın Erdem''im ben ölgüğümde Ağlama sen teselli et sevgili babamı Alper, sen kardeşimi. Ablamı da sevgililerime bırakıyorum Yaşadığımı ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Cemal']::text[], 8.5, '{"poet":"Aydın Cemal","poet_slug":"aydin-cemal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-oldugumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senlik Benlik Nedir Bırak', 'senlik-benlik-nedir-birak-asik-veysel-satiroglu-i43f9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah birdir Peygamber Hak 

Rabbül âlemindir mutlak 

Senlik benlik nedir bırak 

Söyleyim geldi sırası 

Kürt’ü Türk’ü ne Çerkez’i 

Hep Ademin oğlu kızı 

Beraberce şehit gazi 

Yanlış var mı ve neresi 

Kuran’a bak İncil’e bak 

Dört kitabın dördü de hak 

Hakir görüp ırk ayırmak 

Hakikatte yüz karası 

Binbir ismin birinden tut 

Senlik benlik nedir sil at 

Tuttuğun yola doğru git 

Yoldan çıkıp olma asi 

Yezit nedir, ne kızılbaş 

Değil miyiz hep bir kardaş 

Bizi yakar bizim ataş 

Söndürmektir tek çaresi 

Kişi ne çeker dilinden 

Hem belinden, hem elinden 

Hayır ve şer emelinden 

Hakikat bunun burası 

Şu âlemi yaratan bir 

Odur külli şeye kâdir 

Alevi Sünnilik nedir 

Menfaattir varvarası 

Cümle canlı hep topraktan 

Var olmuştur emir Haktan 

Rahmet dile sen Allah’tan 

Tükenmez rahmet deryası 

Veysel sapma sağa sola 

Sen Allah’tan birlik dile 

İkilikten gelir bela 

Dava insanlık davası…', 'Allah birdir Peygamber Hak  Rabbül âlemindir mutlak  Senlik benlik nedir bırak  Söyleyim geldi sırası  Kürt’ü Türk’ü ne Çerkez’i  Hep Ademin...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/senlik-benlik-nedir-birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ver Diye Diye', 'bos-ver-diye-diye-aydin-cemal-oefn0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kırmızı ışıkta geçtin görmedin mi?

yol bomboş

boş ver geçelim.

otobanda kaza olmuş

ticari taksiye uçak çarpmış

boş ver nasılsa içinde biz yoktuk.

bina sallanıyor

üstümüze çökecek

boş ver az sonra geçecek.

Marmarada deprem olmuş

göçük altında otuzbin kişi kalmış

boş ver allah alınlarına öyle yazmış.

boş ver diye diye

o da gitti musalla taşı üstüne

sordu imam cemate

nasıl bilirdiniz azizi?

cemat hep bir ağızdan

boş ver hadi gömelim dedi.', 'kırmızı ışıkta geçtin görmedin mi? yol bomboş boş ver geçelim. otobanda kaza olmuş ticari taksiye uçak çarpmış boş ver nasılsa içinde biz yo...', ARRAY['Türk Edebiyatı','Şiir','Aydın Cemal']::text[], 8.5, '{"poet":"Aydın Cemal","poet_slug":"aydin-cemal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bos-ver-diye-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin Ağaçlarıydı', 'zeytin-agaclariydi-esra-demir-stte6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zamanı gelicek zamanlar 

Diğilmiydi bizim gibileri kandıranlar

Yara bağlayan zamanlar 

Bir ümide hayat bağlayanlar

Zeytin Ağaçlarıydı bizleri saklayanlar

Güneşimizi kapayanlar

Halen size bir mektup yazmak ister ellerim

Uzanamadıklarıma dokunmak ister gözlerim 

Beni ağaç yapan yapraklarda yeşillenen şiirlerim

Viyana,2001', 'Zamanı gelicek zamanlar  Diğilmiydi bizim gibileri kandıranlar Yara bağlayan zamanlar  Bir ümide hayat bağlayanlar Zeytin Ağaçlarıydı bizler...', ARRAY['Türk Edebiyatı','Şiir','Esra Demir']::text[], 8.5, '{"poet":"Esra Demir","poet_slug":"esra-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zeytin-agaclariydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-arif-baltaci-4nwwh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vuslat mıdır sence 

Bedendeki birleşme 

Ya da ayrılık mıdır?

ebedi görüşmeme...', 'Vuslat mıdır sence  Bedendeki birleşme  Ya da ayrılık mıdır? ebedi görüşmeme......', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vuslat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınarım', 'cinarim-mustafa-bagci-8e7ni', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerde o altıyüz yirmi üç yıllık çınarım,

  Ya! Kayı torunu Osmanlı.

  Ben onu Söğüt''te Bursa''da anarım,

  Ya!Cihan imparatorluğu Osmanlı.

  Avrupa ayağının önünde secde etti,

  Orduların Balkanlar''ı inletti titretti,

  Asya Afrika üstünlüğünü kabul etti,

  Ya! Üç kıta hakimi Osmanlı.

  Duy sesimizi Cihan! Duy sesimizi,

  Eksik etmeyiz yeryüzünde cenklerimizi,

  Semaya yayılan tekbir seslerimizi,

  Ya! Türk devleti Osmanlı.

  İslamiyet''in yayılışına hız kattınız,

  Hak dini üç kıtaya cenkle yaydınız,

  Peygamberimizin hadisini imanla kazandınız,

  Ya! İslam''ın kılıcı Osmanlı.', 'Nerde o altıyüz yirmi üç yıllık çınarım,   Ya! Kayı torunu Osmanlı.   Ben onu Söğüt''te Bursa''da anarım,   Ya!Cihan imparatorluğu Osmanlı.   ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bağcı']::text[], 8.5, '{"poet":"Mustafa Bağcı","poet_slug":"mustafa-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cinarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osman Gazim', 'osman-gazim-mustafa-bagci-y9eza', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tam yediyüz iki yıl önce bundan;

  Bir beylik kuruldu Söğüt ve Domaniç''te,

  Osman Gazim bir çınar fidesi dikti Söğüt''te,

  Torunları büyüttü fideyi, sonra oldu kocaman.

  Osman Gazim bir ara uykusuna dalar,

  Düşünde gördüğü karnından çıkan sarmaşıklar,

  Bu sarmaşıklar cihanı üç yönden sarar,

  Bu düşle belli olur gelecekteki Osmanlılar.

  Bu fide Osmanlı''dır, torunlar hükümdar,

  Fatih''im, Yavuz''um, Beyazıt''ım Sultan Muradlar,

  Sulamak için arkalarında erler, ellerinde kılıçlar,

  Meydanlardan meydana kanlarını toprağa akıtmışlar.

  Kayı aşiretinin önderi Osman Gazim.

  Koca Osmanlı''nın temeli Osman Gazim.

  Ulu çınarların şahı Osman Gazim.

  Çınarlar hep  seni çağrışır Osman Gazim...', 'Tam yediyüz iki yıl önce bundan;   Bir beylik kuruldu Söğüt ve Domaniç''te,   Osman Gazim bir çınar fidesi dikti Söğüt''te,   Torunları büyütt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bağcı']::text[], 8.5, '{"poet":"Mustafa Bağcı","poet_slug":"mustafa-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/osman-gazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehter', 'mehter-mustafa-bagci-bwhzv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Osmanlı imparatorluğunun nuru,

  Türk askerinin gururu,

  Selçuklulardan kalma grubu,

  Eski ordu marşımız mehter.

  Savaşlarda cesaret verir nefere,

  Çalar durmadan boru, kös, nakkare,

  Tekbir sesleri arasında yayılır her yere,

  Orduya zafer tattıran takım mehter.', 'Osmanlı imparatorluğunun nuru,   Türk askerinin gururu,   Selçuklulardan kalma grubu,   Eski ordu marşımız mehter.   Savaşlarda cesaret veri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bağcı']::text[], 8.5, '{"poet":"Mustafa Bağcı","poet_slug":"mustafa-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mehter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstadlar Geçidi', 'ustadlar-gecidi-sair-baraka-qu1zj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili dostlarım

Bugünlerde belliki

İyi birşeyler oluyor

Bakın mesela

Geçen sizlere

Bir çifttekerlek 

Canbazından

Bahsetmiştim

Hani şu 

Dörttekerliklilere

Nispeten

Ne iştir ki

Bugünde

Yine dünyaca ünlü

yokedici kas üstadı

Kungfu dövüş

Ekibiyle ülkemize gelmiş

Ve yine açık alanda

Bir vesileyle 

Gösteri yapmışlar

Ha bide bizim varoş

Çocukları bizde varız

Breykledir

Taksimin tam göbeğinde

Adetten olduğundan

Taksim etmişler

Taksimdekilerle

Bakın burası genç

Ve eğlenen

Bir ülke demek için

Bak sen

En üstadları dünyanın

Heryanı istanbulun

Maharet gösteriyor

İmaj gırlandı

Kameralar ihyalandı

İnterlendi

Telelendi

Bütün ülke

Bütün dünya

İstanbulu

Keyifli eğlenceli

Ünlülerin sokakta

Gezdiği çook önemli

Tarihi eserleri olan

Merak edilecek bir yerdir

İmajımı veriliyor 

Sinsice

Olsun ne iyi

Ülkem batılı modern

İmajınıda veriyor

Dimi

Yinede merak ediyorum

Bu ilginç medyalama

Ki dahianedir

Kimin ki

Ülkem insanı

Eleleverme alışkanlığı

Olmadığını 

Bildiğimden

Gayrı

Herhal bir ticari 

Kuruluştur

Devlet ticaret 

Yapmadığına göre

Peki ama kim

Olimpiyatçılar derim

Dostum maccoroni bile

Yadırgar

Eski patronlar mı

Uyandılarda

Acaba 

Bilmemde

Aklıma sanki 

Bir vakıf gelir

Hevesli ilericiler vakfı

Mı acaba

Ki kurulmamıştır bile

İşte o an 

Dedimki bak 

Bu sade bir vatandaş dır

Bakmıştır ki bir türlü

Hiç kimse bununla 

İlgilenmiyor

O da tutmuş

Vermiş bir faal ömrü

Gerçekleştirebilmeye

Ülkem rüyasını

Tutmuş sokak sokak

Meydan meydan

Yalınayak karın aç

Dolaşmış elinde

Çeptellemesiyle

Vukuat bulan

Tüm karşılaşmaları

Bütün gazete

Bütün telegösterirlere

Haber salmaya

Gezmekteymiş 

Büyük haber büyük haber

Bir vatanperver

Bir rumuz türk

Vatandaşı

Pige

O  halde 

ya hu

ya da

bilmece

bilmede

kardeşlerime..........

barakadan', 'Sevgili dostlarım Bugünlerde belliki İyi birşeyler oluyor Bakın mesela Geçen sizlere Bir çifttekerlek  Canbazından Bahsetmiştim Hani şu  Dör...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/ustadlar-gecidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar', 'uzaklar-ali-atilgan-0jk2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bİr sevda gemisiydi bindiğimiz

uzaklara yelken açtık dümensiz

yıldızlar yol gösterir

martılar şarkı söyler

dalgalar sessiz', 'Bİr sevda gemisiydi bindiğimiz uzaklara yelken açtık dümensiz yıldızlar yol gösterir martılar şarkı söyler dalgalar sessiz...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uzaklar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Zor', 'cok-zor-ali-atilgan-b4q4x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen yanımda; karşımdayken

gözlerimi , kırpmaya korkardım

her kırpışta geçen o saliseler  bile

bana sanki bir asırmış gibi gelirdi

ya şimdi; ne kadar uzak

ne kadar  uzaksın

sesini duymak istiyorum

aynı havayı koklamak..

bir yerlerde oturmak

laflamak belki biraz

dolaşmak avare avare

yağmurda;

sırılsıklam ıslanmak

zormuş; hemde çok

özlemleri anlatmak', 'sen yanımda; karşımdayken gözlerimi , kırpmaya korkardım her kırpışta geçen o saliseler  bile bana sanki bir asırmış gibi gelirdi ya şimdi; ...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cok-zor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilgi', 'yenilgi-ahmet-uslu-2cmhd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gizli bahçelerimizi yıktılar

plazalar dikmek için üstüne

atıldık, satıldık, örselendik

bulvarlar açıldı üstümüze

aşklarımızı film yaptılar

küskünlüklerimiz aç haber merkezlerinin

ve habercilerin alemlerine meze oldular

sevgimiz kınandı gazetelerde

aglayışımıza şarkılar yazıp

top on listelerine alet edildik

bir köşeye çekilip suçlular gibi

oturdugumuz yerde yenildik

yenildik ey halkım unutma bizi!!!', 'gizli bahçelerimizi yıktılar plazalar dikmek için üstüne atıldık, satıldık, örselendik bulvarlar açıldı üstümüze aşklarımızı film yaptılar k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu']::text[], 8.5, '{"poet":"Ahmet Uslu","poet_slug":"ahmet-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yenilgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadık İşte', 'yasadik-i-ste-ahmet-uslu-q7aet', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içimizi sarmalayan o garip ışıgın

peşinde avare güzeller

uzansak tutacagız pişmanlıkları

ve umudu baglayacagız düşkırıklıklarına

ucundan tutup aşkın

tortusu birikecek ayrılıkların

sevimsiz ve şaşkın

koca bir örnek büyütecegiz hayalimizde

utanışa sıgmayacak güzeller sevecegiz sonra

her dönüşte içimize bakıp

aglayacagız ıslak ıslak

dert diyecegiz bunun adına

kapkara bir gecede bembeyaz bir diş gibi

sırıtacak umutlar

ama yine de aşık olacagız biz

hep uzaktan, hep yanık, hep dumanlı

başımız dönecek, biz dönemeyecegiz

kaderin oyunu başlattıgı yere

şöyle bir ''yaşadık işte'' diyemeyecegiz

gögsümüzü gere gere!...', 'içimizi sarmalayan o garip ışıgın peşinde avare güzeller uzansak tutacagız pişmanlıkları ve umudu baglayacagız düşkırıklıklarına ucundan tut...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu']::text[], 8.5, '{"poet":"Ahmet Uslu","poet_slug":"ahmet-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasadik-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağ', 'cag-ahmet-uslu-m88ld', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kendi gök kubbemden indim

kendi yeryüzüme

yalanlar getirdim, avuç dolusu yalanlar

bir sana geldim ben

bir de dertlerine aşıkların

türkü söylemek için

türküleri erimiş insanlar tanıdım

solmuş nakaratlar gördüm bir de

    aşka susamışları kandırdı güzeller

ve dünya da onları kandırdı

çağ parayı indirdi yeryüzüne

ama mutlulugu kaldırdı

yeni türküler söylemeli insan

yeniden aşık olmalı mesela

''to be or not to be'' yanlış ikilem

yaşayabilmek asıl mesele!', 'kendi gök kubbemden indim kendi yeryüzüme yalanlar getirdim, avuç dolusu yalanlar bir sana geldim ben bir de dertlerine aşıkların türkü söyl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu']::text[], 8.5, '{"poet":"Ahmet Uslu","poet_slug":"ahmet-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksi Şöförü', 'taksi-soforu-sair-baraka-wd5ev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Televizyonda bir haber

Uluslar arası bir bisiklet

Üstadı çifttekerlek canbazı

Etrafında yığınla toplanan

Polislere gösteri yapmış

Belli ki bir yabancı firma

Promosyon yapıyor

Hedef kitle polis

Polisler çok heyecanlanmış

Gösteriyi dağıtmak için

geldiklerinde

Gözleri dalmış canbaza

Seyre başlamışlar

Yani yasaklarken

Kendilerini yasak iş

Yapmaya sevketmişler

Güzel bir mahareti

İzlemek için

Tek başına

Olmaz beyim olmaz

Hep sana hep sana olmaz

Tabiki menfi olacaksın

Sorarsın her halükarda

Poliste değişikli mi

Yapılıyor

Yoksa bizim de

Bisikletli polislerimiz mi

Olacak

Olursa sevinirim

Çünkü ben

Amsterdama bayılırım

İngilizlerin atlarını

Ürkütücü bulurum

Demmekki avrupa düşüncesinde

Daha güzeli seçiyoruz

Yok eğer bu eğitim

Gösterisi

Bak polisim

Yarın sen buna bineceksin

Görüyormusun

Pek de kolay

Öğrenirsen eğer

Artık çamurlarda yürümeyeceksin

Ayakkabıların eskimeyecek

Hırsızın peşinden koşarken

İşte al öğren

En maharetlisi budur

Bu sana çok gelir

Sen polissin

Riskli hareketler 

Yaptıracak

Canbazlıkları yapmazsın

Evet akrobasi 

Formasyon meselesi

ise eğer

be güzel kardeşim

şimdiye kadar neden

halletmedin

şu formasyon

meseleni

yok eğer anca şimdi 

yapıyorsan

sorarlar

böyle güzel bir gündemi

neden paylaşırsın

yalnız polisimle benim

dimi sorarlar

ihaleyi kim aldı

sessizce derinden

işte dostum

görüyorsun ya

senin için avrupa

bir dolandırıcılık

meselesi

bir talan meselesi

derim de

hayret ederim

ki

onca zamandan beri

başladılardı memluk i osmaniyeyi

talan etmeye

padişahı kovduktan beri

birkaç parça

saray konak parçası

olsa da birkaç hanesinde

saadet şehri

istanbulun

ki

asıl talan

cumhuriyet adına

talandan kurtarmak için

devlete cumhuriyet

mülkü olarak devrettiğinde başladı

cumhuriyet herkese

eşit dağıtmak isterken

cumhuriyet efendilerinin

dönemi bitmesini bekleyen

bir kenara sinmiş

sokak çakalı sessizliğinde

talancı çapulcular

o gün be bugün

hala ve derinden

talana devam ediyor

olmaz  vatandaşım olmaz

böyle avrupalı olunmaz

orası çiftlik değil

yoksa onlar derki

ne o

osmanlı malı bitti

şimdide bizi mi 

yağmalayacaksın

art niyet olur

talanın sonu yok

malın mülkün ne önemi var

esas akıldır

esas yaratımdır

esas üretimdir

onda her zenginlik

var billah var

talandan ediğindiğin

miskinlilkten silken kalk

bırak cumhuriyetin

mülkün temeli olsun

sen yarat

sen üret

avrupa senden alsın

bir düşünceni

bin altın mecidiyeye sat

asıl mirasın bu

dimi ki sen 

bin yıldır

imparatorluk 

çocuğusun

aklınla iradenle

tüm zenginliklere muktedirsin

bırak talanı

yarat üret zenginleş muassırlıkta

benim senin onun için

bizim sizin onlar için

baraka ali ayşe

annemler babanlar yaşlılarımız için

oğullarımız kızlarımız kardeşlerimiz için

sakatlarımız 

hastalarımız 

cici evletlarımız için

yarınımız için

son deminde ahretin

cennet mutluluğunu

bu dünyaya

bir celse de olsa

hayatı bedbaht geçmiş

o mümtaz atalarımızın

çilelerinin yüz suyu hayrına

yaşatalım kuralım

şu dünyevi cenneti be insanım

işte böyle bir hikaye

kimse demez

derse de demez

ama ben diyorum

demezse bile deme

sizi seviyorum

insanımsın

benim

derim

eğer

gerçeksen

insanımıza.........

barakadan', 'Televizyonda bir haber Uluslar arası bir bisiklet Üstadı çifttekerlek canbazı Etrafında yığınla toplanan Polislere gösteri yapmış Belli ki b...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":168,"source_url":"https://www.antoloji.com/taksi-soforu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amerikan Rüyası', 'amerikan-ruyasi-sair-baraka-7sdiw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hem ne diyorsunuz siz ya

Amerika da

Yüzelli yıl evveli

Aynen bizim gibi

Yolları tozlu çamurlu

Topraklı atarabalı

Gringolar cowboylar

köy basar bar basar

tabaklar kadehler havada

siperlik işi görür

herşey pahalı kıt

işsizlik dizboyu

iç göç felaket 

insanlar ölüyor 

yollarda mevsimlik

tarım işcileri

barakakentler heryanı

haydutlar bi aman

bankalar günde beşon

araklanıyor

herölüm açık cinayet

yasalara göre uygulanıyor

onlarında kurtarıcıları vardı

hani şu gece gelen kovboy gibi

devamlı kargaşa savaş dövüş

her yanda ihtilaller dizboyu

insan kıyımları çizgiromalık

işte hani şu

amerikan filimlerde

görürdük ya

hertaraf popart

yeniyetme kokart zenginleri

işte onlar aynen bizim gibi

moralimizi bozmaya gerek yok

bak amerika supermanı icad etmişti

kalkınması hızlandı

dörtyüz yerine

ikiyüz yılda

amerika bu dünyaya

padişah oldu

birde biliyormusunuz

amerikayı kuranlar

eski imparatorluk

çocuklarıydılar

bazıları ise köle idiler

efendi oldular

ha gayret ha

ümitlenelim

baksana bizim de

bir supermanımız var şimdi

onlardan ısmarlama

en azından

yerli osmanlı

ama parçalar

amerikadan

sevelim birbirimiz

birbirimizdeki dürüstlüğü

bu bolca yeter

yeni amerika

imar etmeye

imara

onlar giderken forrest gumpsa

biz gidelim

nasretlanda

kentimara........

barakadan', 'Hem ne diyorsunuz siz ya Amerika da Yüzelli yıl evveli Aynen bizim gibi Yolları tozlu çamurlu Topraklı atarabalı Gringolar cowboylar köy bas...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/amerikan-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hip Hop İmparatorluğu', 'hip-hop-i-mparatorlugu-sair-baraka-7vusp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çağın çocukları

Şu şarkıcı oğlanlar

Beatles, lennon, 

Sting, georges, dylan

Aslında onlar

Roma

Senatosunun

Excentric

Marginal

Calligülalarıdır

Sansabastiyanı

Sanjorj aziz pol leridirler

Daha ki

Brütüsü

Julyeni

Konstantini

Sparktüsü 

Adriain ı 

Marcaurelius dırlar

Ve hatta derimki

Senato binası

Aslen mepthree dir

Şimdilik pek gelmek 

İstemiyorlar

senatodan evvel

Halkın önünde

Prova yapıyorlar

Oy topluyorlar

En yüksek makama

Oturabilmek için

Eski roma yaşıyor

Sadece kılık değiştirmiş

Bahane değiştirmiş

Yeni kelimeler icat edip

Yeni kanunlar söylemiş

Yaşıyor eski roma

Bazen bir galyalı irlanda da

Bazende 

Ameriakanın başında

Bazen senato askıya alınıyor

Savaşlar oluyor

İhanetler ihtiraslar

Aynı terennüm ediyor

Daha kıvrakçasına daha atik

Daha dinamik daha compact

Ama genişleyerek

Tüm dünyayı sararak

Eyaletler eyaletler şeklinde

Globalleşerek

Evet evet

Roma var dostlarım

Bazen aziz hristiyan krallığı

Bazen osmanlı kolosu

Bazen frenkdomtomları

Bazen büyük bretanya

Yada çarrusya

Olarak karşımıza çıkıyor

İşte böyle arkadaşlar

Şu şarkıcılar varya

Onlar asıl savaşı

Yapıyorlar

Yayarak dünyaya

Aslen roma idealini

Sözleriyle

Sesleriyle

Maharet

Beceri

Zekayla

Nazikçe

Yayıyorlar

Unutmaki roma 

Geleneğine göre

Soy yoktur

Sezar tacı alanadır

O yüzden mi

Rating yaptırıyorlar

Kim romayı

Ele geçirecek

Halk oyunu elde edecek diye

Ya dostlarım

İşte böyle

Romanın elden gitmesini

İstemiyorsanız

O calligülla luther kılıklı

Şarkıcılardan

Sakınınız

Esrarına girmeyiniz

Ki roma

Yürüsün

Birleşelim

Görüşelim

Sevişelim

Globalement

ya hu

ya vu

ilk ve son okuyana.........

barakadan', 'Çağın çocukları Şu şarkıcı oğlanlar Beatles, lennon,  Sting, georges, dylan Aslında onlar Roma Senatosunun Excentric Marginal Calligülalarıd...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/hip-hop-imparatorlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak 06', 'uzak-06-oguz-ozdem-1mmfp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sesin de anısı olur; gördüm, sustum

aşk vardı bizim karanlığımızda

gülümseyecekti de belki gündüz yüzüyle

bilseydik bizden önce türkü söylediğini suyun

sevincimizi biçen ilk terzimizdi su

mezar ve ülke, iki sınırsız kumaştı bize

ölümü sevdik, evler kurduk dünyaya kilden

''can verirsin'' dedi tanrılar ''öbür dünyada''

ölünce bakarsan ağaca, ağaçtaki elmaya

''tanrım'' dedim, saflığıyla ilk hecenin

hangi zamanı boyar, senin rengin

unutmuşsun sözcüğü, öğütülmüş ilk sözcük

işittim, susmuş; imgenin ritmiyle büyü

konuşur dedim gökyüzü, bitince şairin işi

seviyorum olimposu, gel bizim mahalleye.', 'sesin de anısı olur; gördüm, sustum aşk vardı bizim karanlığımızda gülümseyecekti de belki gündüz yüzüyle bilseydik bizden önce türkü söyled...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Özdem']::text[], 8.5, '{"poet":"Oğuz Özdem","poet_slug":"oguz-ozdem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzak-06-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnun', 'mecnun-sair-baraka-d4h6x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mecnun

nebula dağlarında 

dolanıyorum

yitirdim yarimi

aranıyorum

bir tek kelamına

doyamıyorum

göster kendini 

ey güzel

karadeliklere bulanıyorum

görsem o mübarek 

cemalini bir an

diye gaz halkalarına 

dolanıyorum

bir selamına 

terki zaman etmeye 

davranıyorum

bir sırrına müebbet

yıldızlaşıyorum ben

ya hak ya hu

daha ne kadar

çile

ne kadar 

cennet

bir görümlük

feyze

hu ya rab

hu ya tad

o tad o tad

ne arz

ne ahiret

ne bağ ne bahçe

ya şa 

ya rab

yeter bana

yarenlik

ya zar

ya zar

idrakine

ya hu

ya hu

leylama......

barakadan', 'Mecnun nebula dağlarında  dolanıyorum yitirdim yarimi aranıyorum bir tek kelamına doyamıyorum göster kendini  ey güzel karadeliklere bulanıy...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mecnun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ormanlarım Yanıyor', 'ormanlarim-yaniyor-ozgur-yesildag-te3md', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine ormanlarım yanıyor

             dertliyim bu gece

Kokunu özledim,dudaklarını

              ve aşkını olabildiğince

İçiyorum şimdi

Elimdeki tek senle

              vesikalık resminle

Bir yandan içiyor

Bir yandan yanıyorum

Memleketime benzedim

              yanacak orman kalmadı içimde...', 'Yine ormanlarım yanıyor              dertliyim bu gece Kokunu özledim,dudaklarını               ve aşkını olabildiğince İçiyorum şimdi Elimd...', ARRAY['Türk Edebiyatı','Şiir','Özgür Yeşildağ']::text[], 8.5, '{"poet":"Özgür Yeşildağ","poet_slug":"ozgur-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ormanlarim-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takatsız cüce', 'takatsiz-cuce-sair-baraka-3p9db', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Takatsız cüce

O na tü kaka

Bu na bu dane

O pis

Bu gavur

O kötü bu mendebur

Ona sataş

Bunla didiş

Onu at

Bunu ez

Nedir derdin

Be kardeşim

Strestemisin

Tahammülün yok 

Hiçbirşeye

Ata ata devri alini

Çöplüğe çevirdin

Vura vura fikri alini

Kevgire çevirdin

Döve döve şahsi alini

Bilirmisin

Dev idin

Aynalara sığmayan

Ufuklar çatlardı

Hasetinden

Bolluk sende idi

Güçte bereketde

Her kavim 

Sana gelirdi

Sende yaşar

Sende beslenirdi

Her fikir sende doğar

Sende evrenleşirdi

Has idin barış idin

Düzen idin kardeşlik idin

Sevgi idin hürmet idin

Biçare

Ata ata özünü

Takatsız

Cüceye çevirdin

Gebereceksin be

Sen sus ki

Ben yine

Devleşeyim

Oksijen ya

Oksiyen

Temiz berrak

Oksiyen

İtipkakanlara......

barakadan', 'Takatsız cüce O na tü kaka Bu na bu dane O pis Bu gavur O kötü bu mendebur Ona sataş Bunla didiş Onu at Bunu ez Nedir derdin Be kardeşim Str...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/takatsiz-cuce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ve Karanfil', 'gul-ve-karanfil-ozgur-yesildag-ntheo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güle inat sevdim seni

hüzünlü bir baharda

intikam koktuğum

                 sıkıntılı bir akşamda

ama beceremedim işte

yürümüyor aşk

                 yalan olunca

sende bir karanfil kadar güzelsin ama

güle inat sevdim seni

veremedim aşka kendimi

kusura bakma...', 'Güle inat sevdim seni hüzünlü bir baharda intikam koktuğum                  sıkıntılı bir akşamda ama beceremedim işte yürümüyor aşk        ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Yeşildağ']::text[], 8.5, '{"poet":"Özgür Yeşildağ","poet_slug":"ozgur-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gul-ve-karanfil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuktum ufacıktım', 'cocuktum-ufaciktim-sair-baraka-hh08l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuktum ufacıktım

Bak görüyormusun

Bizde bir zamanlar 

Onlar gibi çocuktuk

Tıpkı onlar gibi

Birbirimizi bulduğumuzda

Tüm öğrendiklerimizi

Her duyduğumuzu

Birbirimize heyecanla

Nefes sıklığında

Fosur fosur

Anlatırdık

Hatta en kankasına

Annem babam

Abim ablam

Dayım amcamlardan

Duyduklarımızı söyler

Hadi ya diye

Heyecanlanırdık

Şimdi bakıyorumda

Onlara

Utanıyorum

Kendimden

Sanki bir dedikodumda

Yanlış izlenim 

Vermişim ben

Yalan söylemişim 

ben diye

kızıl elmaya..........

barakadan', 'Çocuktum ufacıktım Bak görüyormusun Bizde bir zamanlar  Onlar gibi çocuktuk Tıpkı onlar gibi Birbirimizi bulduğumuzda Tüm öğrendiklerimizi H...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cocuktum-ufaciktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlamayışına', 'beni-anlamayisina-nurullah-genc-m3899', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bir uygarlığı getirdim; anlamadın

Yavuz kahramanları, şiirin burçlarını

Ayak ucuna koydum gecenin saçlarını

Urganmış boynumda taşıdığın gerdanlık 

Sana hükümdarlığı getirdim; anlamadın

Sevda suya karışır, sızar kan dağlarına

Köpüren yüreğimde zıpkınlanır umutlar

Yüzün tunç gibi çöker ülkemin bağlarına

Irmaklar bilmediğin kadar hülyalı akar

Her vadi bir yanıyla senin yüzüne bakar

Bir yanında münzevi hıçkıran Leyla kuşu

Sen henüz tanımadın sevda denen yokuşu

Sen henüz yorulmadın yokuşta devler gibi

Yıkılmak üzre olan çaresiz evler gibi

Sen henüz vurulmadın uçarken göklerinde

Sen henüz bir oltaya takılmadan derinde

Karalar bağlamadın; beni anlayamazsın

O kalp sende oldukça gülüm, ağlayamazsın

Seni bir yıldız gibi koyacağım göklere

Her gece ışığını ruhumdan alacaksın

Aldanma gururunu okşayan çiçeklere

En güzel güllerini ruhumla alacaksın

Kopacak sanıyorsun bu ip ince yerinden 

Bu ipin her çizgisi yaralı bir dev gibi

İnecek sanıyorsun bu bayrak gönderinden 

Bu sevda tükenecek sönen bir alev gibi

Sen hala anlamadın sevginin en hasını

Sen hala çözemedin ırmağın dünyasını 

O, coşkun bir denizin sularına yürürken 

Sen hasta bir çeşmeden doldurmuşsun tasını

Gittiği her iklime sevdanı götürürken 

Gözyaşı çukuruna gömmüşsün deltasını

Henüz bir tokat gibi inmedi yüzüne aşk 

Kalbine çivilerle gömülmedi ayrılık

Görmedin bir arslanın can çekişen resmini

Yalnızlık kitabında okumadın ismini

Bir takvim yaprağında yanmadı bakışların

Dökülen tüylerine tutunmadın kuşların

Karanlık köşelerde acı acı gülmedin 

Sen henüz kovulduğun kapılarda ölmedin

O Celali uykudan uyanmadın, uyanma

Düşlerimin rengine boyanmadın, boyanma

Bir kuş gibi çırpınan kalbimin kafesine

Bir avuç yem bıraksan ölür müsün, a gülüm

Feryadı kayaları parçalayan sesine 

Ömür boyu yabancı kalır mısın, a gülüm

Sen henüz bir zindanın küflü duvarlarına

Çarpmadın gözyaşıyla boğulan gözlerini

Sen henüz diken diken saplamadın göğsüne

Dudağında kuruyup dağılan sözlerini 

Sen henüz dokunmadın yalnızlığa kan gibi

Acıyı kaynatmadın içinde volkan gibi

Karalar bağlamadın beni anlayamazsın

O kalp sende oldukça gülüm, ağlayamazsın', 'Sana bir uygarlığı getirdim; anlamadın Yavuz kahramanları, şiirin burçlarını Ayak ucuna koydum gecenin saçlarını Urganmış boynumda taşıdığın...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/beni-anlamayisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşma 338', 'kosma-338-karacaoglan-qs2ho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüceden mi geldin sen seher yeli

Daha dostum eller ile gezer mi? 

Solmuş derler gül benzinin iziği, 

Daha dostum eskisinden güzel mi? 

O ne dedi, sen ne dedin varıncak? 

Oğlan aşık mısın? Dedi görüncek

El kavuşturup divanına duruncak

Daha dostum eskisinden güzel mi? 

Kolda götürürüm yavrı baz gibi

Yüzerim göllerde boymul kaz gibi

Bahçandan açılan top nergiz gibi

Toplar toplar, dost zülfüne dizer mi? 

Karac’oğlan, gider kendi yoluna

Çiğ ibrişim pek yakışır beline, 

Divitin, kalemin almış eline; 

O dost bizi defterine yazar mı?', 'Yüceden mi geldin sen seher yeli Daha dostum eller ile gezer mi?  Solmuş derler gül benzinin iziği,  Daha dostum eskisinden güzel mi?  O ne ...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kosma-338-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşma 282', 'kosma-282-karacaoglan-0reqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seherden uğradım dostun köyüne“

Hoş geldin sevdiğim, in! ” dedi bana.

Domurcuk memesin verdi ağzıma,

“Yorgunsun sevdiğim, em! ” dedi bana.

Benim yârim gelişinden bellidir,

Ak elleri deste deste güllüdür,

İbrişim kuşaklı ince bellidir

“İnce bellerimi sar! ” dedi bana.

Benim yârim bana yalan söylemez.

Söylerse de gıybetimi eylemez.

İl yanında ikrârını söylemez

“İlleri uyut da gel! ” dedi bana

Mestine de deli gönül mestine,

Âşık olan gül gönderir dostuna.

Telli mahramasın attı üstüme

“Terlersen sevdiğim, sil! ” dedi bana

Karac’oğlan, sırrın kime danışır? 

Siyâh zülfü mah yüzüne kıvrışır.

Ayrılanlar elbet bir gün kavuşur“

Ağlama sevdiğim, gül! ” dedi bana', 'Seherden uğradım dostun köyüne“ Hoş geldin sevdiğim, in! ” dedi bana. Domurcuk memesin verdi ağzıma, “Yorgunsun sevdiğim, em! ” dedi bana. B...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kosma-282-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötesi', 'otesi-hasan-hatip-wxtu0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ötesindeyim aşkın,

Yinede şu gönlüm aç.

Gözlerini aç şaşkın,

Dünyanın içine kaç.

Yol yok bundan ileri,

Bir ileri bir geri,

Gitsen desen geri geri,

Başında üç beş tel saç...', 'Ötesindeyim aşkın, Yinede şu gönlüm aç. Gözlerini aç şaşkın, Dünyanın içine kaç. Yol yok bundan ileri, Bir ileri bir geri, Gitsen desen geri...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hatip']::text[], 8.5, '{"poet":"Hasan Hatip","poet_slug":"hasan-hatip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Dilinin En Büyük Şairine Rubailer', 'turk-dilinin-en-buyuk-sairine-rubailer-husrev-hatemi-crfgi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Yunus ki bu toprakta açılmış gülmüş,

Bir dem o da ağlamış, avunmuş, gülmüş.

Esrarını aşkın bize açmış bir bir,

Susmuş ve o esrar yeniden örtülmüş.

II

Yunus ki nergisde güler, gülde kanar,

Kırlarda gelincikte onun bağrı yanar,

Toprak onu bir baharda almış sanırım,

Her yıl bunu tekrar merasimle anar.', 'I Yunus ki bu toprakta açılmış gülmüş, Bir dem o da ağlamış, avunmuş, gülmüş. Esrarını aşkın bize açmış bir bir, Susmuş ve o esrar yeniden ö...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/turk-dilinin-en-buyuk-sairine-rubailer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Hukumuz Vardı', 'seninle-hukumuz-vardi-metin-bektas-nh465', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi biz seninle bir şiirin

                  son mısralarındayız

                  içimizdeki yaşama çığlığı

                  bilinmez inceliklerle örülen

                  ümidi ve şefkati teselli etmiyor artık

                  halbuki

                  ne çok severdim seni

                  güneşleri tutup gerdanına gül diye

                  takasım gelirdi

                  şiirlerden demetler tutuşturasım gelirdi

                  ince ve uzun parmaklarına

                  sen hayatın ruhuydun,

                  daha kutsaldın ölümden

                  ve seninle hukukumuz vardı

                  unuttun

                  bana başkaldırmayı öğreten

                  dudaklarından

                  hicranı içtim yıllarca teselli diye

                  bir deprem yalnızlığında unuttum

                  var olmanın serseri sarhoşluğunu

                  ve ben yalnız,

                  yapayalnız konuşurken bile

                  hep

                  seni dinledim

                  seninle hukukumuz vardı

                  unuttun

                  bir şeyler söyle şimdi bana

                  hiç duymadığım bir şeyler

                  bir iç ateşi gibi sarsın içimi kelimelerin

                  ve anlasın tutkuların deliceliğini

                  tutkularca kahraman ruhum

                  bu dönülmez yokuşu

                  aşmak düşer artık bize

                  sabretmek düşer vakur ve özgece

                  aşkı ak hüzünlerle yaşamak düşer

                  ve tutsak etmek düşer gözbebeklerimi

                  can çekişen umutlarımın başucunda

                  ihanete meyilli yüreklerde

                  erdemler yaşamaz gülüm

                  ritmi bozuktur

                  var oluşa yürümeyen ayakların

                  akıp gider susuzluklar ormanına

                  bütün Allahsızlıklar

                  ve dönüşü olmaz geriye merhametsizliklerin

                  Sen ey sevgili

                  önce sevgiye yönelmelisin

                  bitirmelisin kendinle kavgalarını,

                  özge bir hayatın tuzaksız şefkatleriyle

                  yıldızları,gecelere bırakmalısın

                  öğrenmelisin

                  kırılan gönüllere gönül kanı ödemeyi

                  ve

                  suya yazılmış bile olsa hukukumuz

                  asla

                  ama asla

                  unutmamalısın

                  unutmamalısın...', 'Şimdi biz seninle bir şiirin                   son mısralarındayız                   içimizdeki yaşama çığlığı                   bilinmez in...', ARRAY['Türk Edebiyatı','Şiir','Metin Bektaş']::text[], 8.5, '{"poet":"Metin Bektaş","poet_slug":"metin-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/seninle-hukumuz-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Veda', 'i-kinci-veda-cigdem-arpacioglu-dx4ug', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç yaşadınız mı?

Geriye dönememenin ezikliğini,

İstemsiz sözler ettiğiniz telefonu

Can havliyle yere atıp kırmanın çaresizliğini,

Bitmeyen kuşku ve tedirginliği,

Gecesi gündüzü aynı olan bir günü,

Gerçeği ellerinizde tutarken,

Gerçeği yalan yapmanın ızdırabını,

Sekiz ay karnında taşıdığı bebeğini

Kaybetmiş bir annenin duyduğu acıyı,

Hiç yaşadınız mı?

Gözükara umuduyla gökte havalanırken

Yere çakılmış bir uçurtma olmayı,

Sarsıla sarsıla size koşan,

İçinizde saklı tuttuğunuz hüznü,

Hiç yaşadınız mı?

Başınız dizlerinizin arasında ,

Damla damla akıttığınız gözyaşlarını

Hiç yaşadınız mı?

Yirmi yılda tattığınız ikinci büyük, zorunlu elvedayı

Hiç yaşadınız mı?

Kendimin  olmayacağı bir hayatta 

Ona mutluluklar dilemenin yürekteki sızısını

Yaşadınız mı hiç?

Şu an benim yaşadığım zorunlu ayrılığı....', 'Hiç yaşadınız mı? Geriye dönememenin ezikliğini, İstemsiz sözler ettiğiniz telefonu Can havliyle yere atıp kırmanın çaresizliğini, Bitmeyen ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Arpacıoğlu']::text[], 8.5, '{"poet":"Çiğdem Arpacıoğlu","poet_slug":"cigdem-arpacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ikinci-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olan Yaşamak', 'zor-olan-yasamak-basri-erkan-lyam2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zor olan yaşamak sevgilim,

Adımlamak bu hayatı bıkıp usanmadan,

Gecenin karanlığını dost edinmek

Sessizce gözyaşı dökmek zor olan

Zor olan yaşamaktır sevgilim,

Bir hançerli yüreği taşımak,

Taşıdığın hançerli yüreği duyurmamak,

Ve kan akan yüreği susturmak...

Yoksa sevdiğim ,

Ölüm nedir ki bizler için,

Bir atımlık kurşun namluda...

Zor olan ölmek değil yaşamak inan', 'Zor olan yaşamak sevgilim, Adımlamak bu hayatı bıkıp usanmadan, Gecenin karanlığını dost edinmek Sessizce gözyaşı dökmek zor olan Zor olan y...', ARRAY['Türk Edebiyatı','Şiir','Basri Erkan']::text[], 8.5, '{"poet":"Basri Erkan","poet_slug":"basri-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-olan-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor', 'sor-ayhan-eralp-mf320', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç gecem vardır seni aldattığım

Bilmesen de  kalbime  kazıdığım

Rüyalarımdan    çekip   gözlerini

Kararttığın  nice  gündüzlere sor.

İsmini söyledim göçmen  kuşlara

Yolunu   şaşıran    tüm   turnalara

Gece   gözlerinin   mağdur  ettiği

Burcunu terk etmiş yıldızlara sor.

Bir   bir    tükettiğim     ihtimalleri

Sana    adadığım    tüm   geceleri

İhmal ettiğim  tüm mukaddesleri

İçine  düştüğüm  cehenneme  sor

Güneş  yapıp   geceme   gözlerini

Asla    inkar   etmedim   gözlerini

Elest bezminde gördüm gözlerini

İhmal  ettiğim  mukaddeslere sor

            3.1.1999', 'Kaç gecem vardır seni aldattığım Bilmesen de  kalbime  kazıdığım Rüyalarımdan    çekip   gözlerini Kararttığın  nice  gündüzlere sor. İsmini...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Eralp']::text[], 8.5, '{"poet":"Ayhan Eralp","poet_slug":"ayhan-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömre Bedel Gibisin', 'omre-bedel-gibisin-ahmet-kuruoglu-nl280', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili Arkadaşıma: 

Nefesin: Bir esişte sanki, 

                Fırtınalar koparacakmış gibi.

Nefesin: O kadar güçlü ve heybetli ki, 

                Yüreğindeki yangını söndürmek ister gibi 

Gülüşün: Geçip giden acı geçmişi, 

                 Sırtından vurmak istermiş gibi.

Gülüşün: Hüzünlü bulutların ardındaki, 

                 Büyüleyici gökkuşağı gibi.

Ellerin: Unutamadığın kederleri,                   

              Bir kalemde silmek istermiş gibi.

Ellerin: Yüreğindeki sayısız hançeri, 

              Çıkartmak ister gibi.

Gözlerin: Issız ve karanlık gecelerdeki, 

                 Mehtapta parlayan yıldız gibi.

Gözlerin: Yağmur yüklü bir bulut sanki, 

                 Yağmak istermiş gibi dertli.

Göz Yaşın: Bir türlü küllenmeyen ateşi, 

                    Söndürmek ister gibi.

Göz Yaşın: Daha da kuvvetlendiriyor ateşi, 

                    Tıpkı bir kıvılcım gibi.

Sesin: Bazen ürkek nazlı bir ceylan gibi,                              

             Bazende kükreyen vahşi bir aslan gibi. 

Sesin: Güle nağmeler söyleyen bülbülleri, 

             Kıskandıracakmış gibi.

Sözlerin: Bir masal bir roman gibi, 

                 Kafiyelerle süslenmiş bir şiir gibi.

Sözlerin: Ele veriyor dostum seni, 

                 Tıpkı buğulu gözlerin gibi.

Kalbin: Bazen azgın bir volkan gibi, 

              Bazende saman alevi misali.

Kalbin: Öyle derin öyle engin ki, 

              Uçsuz bucaksız okyanus gibi.

Ve Ben: Bu sonu belli olmayan okyanusta sanki, 

                Hep varolmak istiyorum batık bir gemi gibi. 

Ve Ben: Hiç bırakmak istemiyorum seni, 

                Tıpkı etle tırnak gibi.

Ve Ben: Unutamam seninle geçirdiğim günleri, 

                Her saniyesi '''' bir ömre bedel gibi ''''.', 'Sevgili Arkadaşıma:  Nefesin: Bir esişte sanki,                  Fırtınalar koparacakmış gibi. Nefesin: O kadar güçlü ve heybetli ki,       ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/omre-bedel-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidan', 'fidan-erzurumlu-emrah-tugmw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahtan uğradım ben bir fidana

Dedim mahmur musun, dedi ki yok yok

Ak elleri boğum boğum kınalı

Dedim bayram mıdır, dedi ki yok yok

Dedim inci nedir, dedi dişimdir

Dedim kalem nedir, dedi kaşımdır

Dedim on beş nedir, dedi yaşımdır

Dedim daha var mı, dedi ki yok yok

Dedim Erzurum nen, dedi ilimdir

Dedim giderm misin, dedi yolumdur

Dedim Emrah nedir, dedi kulumdur

Dedim satar mısın, söyledi yok yok', 'Sabahtan uğradım ben bir fidana Dedim mahmur musun, dedi ki yok yok Ak elleri boğum boğum kınalı Dedim bayram mıdır, dedi ki yok yok Dedim i...', ARRAY['Türk Edebiyatı','Şiir','Erzurumlu Emrah']::text[], 8.5, '{"poet":"Erzurumlu Emrah","poet_slug":"erzurumlu-emrah","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fidan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARANLIKLAR', 'karanliklar-resul-bal-8glaz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KARANLIKLAR

Karanliklar sarmışsa dört biryanı

Ve...Bağrına saplanmışsa hançer

İnim inim inliyorsa karanlık

Ve düşman titriyorsa bağri karanlık ve yaralı

Dağ dorukları yalnız değilsiniz

Tapınacak tapınak  arıyorsan

Eğer kendine dost

İşte tapınak

Başı dumanlı dağ dorukları bekliyor .seni

Karanlıklar pusu kurmus  dört bir yana

Gencecik canlar alınmış

Ağlar dağlar ,ağlar gökyüzü

Çığlık atan şahanlar ve

Ceylanlar kadar özgür

Şimdi gökyüzünden seyre dalar

Ve özgürlük türküsü söyler şahanlar.

Korkuyu özlemiyle  yenen,

Yüce dost yalnız değilsin oralarda

İste orada sahanlar

Dağ doruklarını mesken edinmişler

Pençelerinde özgürlük tohumu

Ve günesten bir parça kopararak

Dolaşıyorlar dağları', 'KARANLIKLAR Karanliklar sarmışsa dört biryanı Ve...Bağrına saplanmışsa hançer İnim inim inliyorsa karanlık Ve düşman titriyorsa bağri karanl...', ARRAY['Türk Edebiyatı','Şiir','Resul Bal']::text[], 8.5, '{"poet":"Resul Bal","poet_slug":"resul-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karanliklar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygusuzluğum Benim Bu', 'duygusuzlugum-benim-bu-metin-vatansever-it9c9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taştan bir heykel düşün,

Gözlerinde belirsiz bir umut vardır,

Dudaklarında acı bir tebessüm,

Yüzünün her hattı gergindir

Bilir saklamayı derdini

İçindeki acı alev alev de olsa belli etmez

İşte ben oyum,

Ya da o heykel benim benzerim...

Bir ağaç düşün,

Bütün yapraklarını dökmüşte,

Dalında bir tek yaprak kalmış,

Gövdesinde derin yaralar olan bir ağaç düşün,

Karşı koyan bütün doğal güçlere

Yine de dimdik duran bir ağaç,

İşte ben oyum,

Ya da o ağaç benim benzerim...

Bir kaya düşün,

Her yağmurda zerre zerre dağılan,

Her rüzgarda savrulan bir kaya düşün,

Duygusuz, sebebsiz eriyen o kayayı ,

Hatırla,

İşte o benim,

Yada o kaya benim benzerim...', 'Taştan bir heykel düşün, Gözlerinde belirsiz bir umut vardır, Dudaklarında acı bir tebessüm, Yüzünün her hattı gergindir Bilir saklamayı der...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/duygusuzlugum-benim-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven Fedakar Olmalı', 'seven-fedakar-olmali-metin-vatansever-bletx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanlı zamansız, 

Savaş açtım bu dopdolu yürekle acılara, 

Düşman bildim geceleri, 

Bir kalp durdurdum benliğimi saran nefesimden, 

Dudağımda çürüttüğüm sevgi sözünü, 

Gözbebeklerimdeki umudu söndürdüm, 

Açılmadan yalan sevgilere, 

Oysa! ..

Seven fedakar olmalıydı değil mi? ..

Senin için bir ömrü yaşattım bu kalpte, 

Gün geldi, 

Deli oldum sevisiz duygulardan, 

Çıldırdım, 

O zaman demir parmaklıklar kondu, 

Günlerce bekledim senden esecek yelleri, 

Şahlandıkça dalga dalga, 

Benliğimi aldı yalın günlerim, 

Dizlerimdeki son derman çöküşüm oldu, 

Senin diktiğin zafer bayrağı, 

Benim mezartaşım şimdi, 

Hani sen derdin ya; 

''Seven fedakar olmalı'' diye

Sözüm yok

Son sözü sen söyle

Söylede bu ıstırap bitsin...', 'Zamanlı zamansız,  Savaş açtım bu dopdolu yürekle acılara,  Düşman bildim geceleri,  Bir kalp durdurdum benliğimi saran nefesimden,  Dudağım...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seven-fedakar-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umutsuzluğun Getirdiği', 'bir-umutsuzlugun-getirdigi-metin-vatansever-lotgs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalemim, celladım olacak benim biliyorum

Yavaş yavaş her dizede dönülmesi gitmekten zor olacak,

Her düşünüşüme dizelerimde bir çıkmaz,

Her çıkmaz da yüzlerce umutsuzluk olacak

Her umutsuz, tesellisiz dizemde de

Keder olacak, Ölüm olacak!..

Bir gece yine böyle bir düşünüşte, 

Böyle bir umutsuzlukta,

Oturup son satırlarımı yazacağım,

Yağmurlu bir akşam olacak belki,

Öyle bir sonu dizeleyeceğim ki,

Bileklerimde kalem tutacak derman kalmayacak,

Beynimde koyu bir karanlık, sessizlik olacak,

herşeyi yaratan ellerim

Son kez avuçlayacak yüzümü,

O an hiç bir duygu yeşermeyecek,

Hiç bir umut döndüremeyecek geri,

O öyle bir gidiş olacak ki,

Bir yürek çarpmayacak,

Kara sevdalı, tutkun bir benlik susacak,

O beden, o ruh, o sevda bitmeyecek mi?

O beden bitecek elbet,

O ruh var olacak belki,

Ama o sevda,

Sana olan o sonsuz aşk

Her zaman var olacak,

Bir bedenin çökmesiyle,

Bir aşk bitmiyorsa eğer...', 'Kalemim, celladım olacak benim biliyorum Yavaş yavaş her dizede dönülmesi gitmekten zor olacak, Her düşünüşüme dizelerimde bir çıkmaz, Her ç...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-umutsuzlugun-getirdigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmemecesine', 'donmemecesine-burak-ergindag-f0sw1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her defasında bu son olsun der,

Yinede çaresiz boyun eğerdim gidişlerine...

Nerden bilirdim birgün sözünü tutacağını

   ''Dönmemecesine''..!', 'Her defasında bu son olsun der, Yinede çaresiz boyun eğerdim gidişlerine... Nerden bilirdim birgün sözünü tutacağını    ''Dönmemecesine''..!...', ARRAY['Türk Edebiyatı','Şiir','Burak Ergindağ']::text[], 8.5, '{"poet":"Burak Ergindağ","poet_slug":"burak-ergindag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/donmemecesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-burak-ergindag-ld3pw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay en son yüzünü sakladığında bir çocuktum

ve karanlık kaldıramayacağım kadar ağırdı.

Şimdi ay birkez daha yüzünü saklıyor ama 

daha farklı...

Büyüdüğümü sanıyordum..

Yanılmışım..

Görüyorum ki hala bir çocuk kadar çaresiz

ve savunmasızım...', 'Ay en son yüzünü sakladığında bir çocuktum ve karanlık kaldıramayacağım kadar ağırdı. Şimdi ay birkez daha yüzünü saklıyor ama  daha farklı....', ARRAY['Türk Edebiyatı','Şiir','Burak Ergindağ']::text[], 8.5, '{"poet":"Burak Ergindağ","poet_slug":"burak-ergindag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuk-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurum', 'ucurum-burak-ergindag-i23bc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve ben artık her sabah uyandığımda bir uçurumun

dibinde buluyorum kendimi.

Öyle hain bi karanlık çökmüş ki üstüme

yerden bile kalkamıyorum.

-Allahım nasıl geldim ben bu yere..?

-Yok yok buraya düşmüş olamam.

Muhtemelen karanlıkta yolumu kaybedip

gelmişmdir yada kara bi bulutun beyaz

yapraklarından dökülen bi yağmur damlası gibi

rüzgarı eze eze ,

rüzgarı sindire sindire gelip konmuşumdur bu şehre.

Başka bir açıklaması olamaz diyorum.

Zaten başka bi açıklamada beklemiyorum.

Önemli olan buraya nasıl geldiğim değil,

geliş yolunu bile bilmediğim bu garip şehirden nasıl geri döneceğim..

Zaten bu yüzden her akşam gün batımında 

bir başka uçurumun yanı başında buluyorum kendimi.

Az sona düşeceğimi biliyorum..

Tutunmam gereken bir dal arıyorum,

bir derman.

Oysa dermanlarım hep yordun olduğunu söylüyor

yada uykusuz.

Bir tanesi çıkıp da demiyor dostum seninde uyuman gerekmiyormu?

Sen neden uyumuyorsun?

Bilmiyor musun  artık benim uyumaktan bile korktuğumu?

Aslında kızmaya hakkım yok sana.

Karanlığımın ne karanlık,

acımın ne kadar acımasız olduğunu bilemezsin

ben anlatmadıktan sonra..

Ben sırf bu yüzden ne vakit uyansam bir gece yarısı

uykumdan,

bir başka uçurumdan yuvarlanır buluıyorum kendimi.

Kalkıp aynaya bakıyorum sonra.

Gözlerim,gözlerimi tanıyamıyorum atık..

Şuraya bak sakallarımda çıkmaya başlamış.

Bu kadar büyümüş olamam diyorum.

Zaman bu kadar acımaasız olamaz.

Oysa herşeyin,yalnızlıkların bile yalan yalnış

yaşandığı bu garip şehirde elle tutulan tekşey zaman.

Oysa ben kendimi hala ondört yaşında hissediyorum.

Hani arkadaşımın başını taşla yarışım varya 

işte onu hiç unutamıyorum,

birde o kızıl ağustos gecesi gözlerine vurulduğum deli sevdamı.

Ben kendimi hala ondört yaşımdaki gibi çocuk sevdalı

ve hırçın dalgalara göğüs geren kum taneleri gibi

delikenlı hissediyorum.

Oysa kağıttan bir gemiymişimde haberim yokmuş.

Oyuncak olmuşumrüzgarın eline.

Durmadan savuruyor beni,hırpalıyor ,vuruyor bir yerlere.

Daha ne kadar dayanabilirim bilmiiyorum yada ne zaman bir kara parçası bulabilirim.

Güneşimi kaybetmişim bak..

Üzülmüyorum.

Biliyorum ki o zaman yıldızları görmem mümkün olmayacak.

Bir uçurumun kenarında tek ayak üstünde duruyorum 

ve sırf hayata gıcıklık olsun diye,

sırf sana söz verdim diye gülümsüyorum.

Biliyor musun sevdiğim bu halimle bile seni hala,

seni hala ,seni hala...

Görüyorsunya hala söyleyemiyorum...', 'Ve ben artık her sabah uyandığımda bir uçurumun dibinde buluyorum kendimi. Öyle hain bi karanlık çökmüş ki üstüme yerden bile kalkamıyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Burak Ergindağ']::text[], 8.5, '{"poet":"Burak Ergindağ","poet_slug":"burak-ergindag","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/ucurum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-ertugrul-sakar-qmp03', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayalimde sevdim,yaşadım,sustum

Düşlerim evlendi, boşadım,sustum

Mevsimler boyu koştum peşi sıra

Yaşanmamışları yaşadım,sustum', 'Hayalimde sevdim,yaşadım,sustum Düşlerim evlendi, boşadım,sustum Mevsimler boyu koştum peşi sıra Yaşanmamışları yaşadım,sustum...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sustum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-zubeyde-basaran-s49t2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aç gönlün,gönle faydasını

Dost yüreklerde ara

Masum güzellikleri arayan sen 

Bulunmayan yerde

Çiz ve karala', 'Aç gönlün,gönle faydasını Dost yüreklerde ara Masum güzellikleri arayan sen  Bulunmayan yerde Çiz ve karala...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dost-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narçiçek', 'narcicek-jale-demirdogen-zrthc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..................Annem Narçiçek''in anısına...

Önce buruşturdum,

Sonra katladım ;

Kağıt paralarımdan

Üç adet kuş yaptım...

Birini umuda uçurdum,

Birini mutluluğa...

Birini de sana NARÇİÇEK !

Yıllarca biriktirdim ;

Bir havuz yaptım göz yaşlarımdan...

Avucuma üç demir para aldım.

Ve içimden tuttum üç dilek ;

Biri umut içindi,

İkincisi  mutluluk ,

Üçüncüsü senin için NARÇİÇEK !

Dilekleri havuza attım ,

Sen yattığın yerden ,

Gülümseyerek bana baktın .

Öyle manidar gülme sakın ,

Hangi dilek gerçekleşecek ,

Bilemezsin  NARÇİÇEK !', '..................Annem Narçiçek''in anısına... Önce buruşturdum, Sonra katladım ; Kağıt paralarımdan Üç adet kuş yaptım... Birini umuda uçur...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/narcicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Begonya', 'olu-begonya-jale-demirdogen-xq1u6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seneler boyunca,

En karanlık cephesinde bekletildim evinin.

Ve beni ,

En kuzeyine yerleştirmiştin yüreğinin.

Şimdi ;

Rengarenk çiçeklerimi açmadığım için

Sitemdesin.

Oysa ;

Suskun ve narin begonyandım ben senin.

Sıcacık bir iklimde yeşerebilirdim ancak ;

Bilemedin !

Ela gözlerinin önünde ,

Bir süre can çekiştim...

Görmedin !

Artık perdeleri kapat !

Suya da  lüzum yok ...

Dikkat et !

Toprağıma dokunursan ,

Öfkesi acıtabilir ellerini ,

Kahverengisinin !

Biliyorum şimdi ;

Köşedeki çiçekçiye gideceksin ;

Yorulma...

Onun söyleyeceğini ben söyleyeyim ;

'' Üzgünüm ...

Begonyanız , ölmüş efendim ! ''', 'Seneler boyunca, En karanlık cephesinde bekletildim evinin. Ve beni , En kuzeyine yerleştirmiştin yüreğinin. Şimdi ; Rengarenk çiçeklerimi a...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olu-begonya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisbet', 'nisbet-jale-demirdogen-9qkwb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmuru seviyorum...

Yağmadan önce de,

Yağarken de...

Hüznü seviyorum...

Her gün geçtiğim sokakların kaldırım taşlarında,

Sırılsıklam yatarken hüzün,

Bu kenti daha çok seviyorum nedense...

Ve böyle yağmurlu günlerde,

Sırf daha güzel görünsün diye  bu kent;

Yağmuru hüzne peşkeş çekiyorum hep!

Birde sana...

Birde güneşe nisbet!', 'Yağmuru seviyorum... Yağmadan önce de, Yağarken de... Hüznü seviyorum... Her gün geçtiğim sokakların kaldırım taşlarında, Sırılsıklam yatark...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nisbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Çınarın Nikâh Töreni', 'i-ki-cinarin-nik-h-toreni-jale-demirdogen-a74g7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahd ettik;

El ayak çekildiğinde sevişeceğiz!

Ayrı topraklarda dikilip,

İhtiyar birer çınar olana dek,

Birbirimizi Beklemişiz!

Sabrı ezberlettiler bize;

Bilmezsiniz!

Ne çok gölge ettik,

Yapraklarımızın altında,

Az serinlemediniz!

Dayanılmaz oldu hasret;

Ege''den Marmara''dan da

Gayrı vazgeçtik...

Şimdi toprağında yer aç;

Kökünden kestik gövdemizi,

Dallarımızı doladık birbirine;

Sana geldik!

Anlıyor musun bizi,

Sevişeceğiz Akdeniz!

Sen takacaksın yüzükleri,

Lütfen herkesi gönder;

Kalabalıklarda ziyan edilmeyecek kadar,

Bekletildi sevgimiz!

Uçsuz bucaksız sahil,

Ay ışığı ve deniz;

Siz kalabilirsiniz!

Dikkat edin;

Öyle özel, öyle tek, öyle sonsuz ki bu tören;

Az sonra izleyeceğiniz!...', 'Ahd ettik; El ayak çekildiğinde sevişeceğiz! Ayrı topraklarda dikilip, İhtiyar birer çınar olana dek, Birbirimizi Beklemişiz! Sabrı ezberlet...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iki-cinarin-nikah-toreni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürüvvet Teyze''nin Kurabiyeleri', 'muruvvet-teyze-nin-kurabiyeleri-jale-demirdogen-g5m39', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ankara''da

Akdeniz caddesinde,

Ocak apartmanında otururduk.

Apartmanın adıyla dalga geçen,

Büyümeye hevesli çocuklardık hepimiz.

Kışın geldiğini

Kapı komşumuz 

Mürüvvet Teyze''nin kurabiyelerinin kokusundan anlardık

Okulların açılmasıyla birlikte,

Mürüvvet Teyze''nin kabul günleri başlardı.

Kabul günlerinin o pürtelaş sabahlarında,

Kurabiye kokusu sarardı tüm apartmanı...

Tatlı kadındı Mürüvvet Teyze,

Bir oğlu bir de kızı vardı.

Oğlu Murat''ın takma adı j.r.''dı.

Ablamınki ise Sue Ellen...

Malum, televizyondaki Dallasın oynadığı yıllardı.

Bana mahallede Pamela olmayı yakıştırmışlardı..

Elbet bir de Boby''im vardı;

Adı Can''dı.

Mürüvvet Teyze''nin kızı Çimen,

Sarı saçlı, yeşil gözlü bir kızdı ;

Güzeldi.

Gizli gizli onu kıskanırdım.

Güzelliği için değil,

Kurabiye pişiren bir annesi olduğu için  kıskandığımı,

O apartmandan taşındıktan çok sonra anladım!

Ankara''ydı.

Akdeniz caddesi,Ocak apartmanıydı.

Okullar açılır, kabul günleri başlardı.

Bizim evde hiç kabul günü olmazdı.

Mutsuzdum;

Dallasçılık oynardım...

Mutsuzluğumun ortasında yükselen,

Mürüvvet Teyze''nin kurabiyelerinin kokusuna

ve hayata asılırdım!', 'Ankara''da Akdeniz caddesinde, Ocak apartmanında otururduk. Apartmanın adıyla dalga geçen, Büyümeye hevesli çocuklardık hepimiz. Kışın geldiğ...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/muruvvet-teyze-nin-kurabiyeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'REYHAN', 'reyhan-i-lhan-gasi-d7cmi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüyadaydım sanki seninle 

En güzel duyguydu bu

Yağmur vardı dışarıda sen yanımdaydın

Hani hiç bitmeyecek demiştin 

Ağlamayacak hep gülecektik 

Ne yazık ki rüyada bende,

  usul usul beraberce bittik...', 'Rüyadaydım sanki seninle  En güzel duyguydu bu Yağmur vardı dışarıda sen yanımdaydın Hani hiç bitmeyecek demiştin  Ağlamayacak hep gülecekti...', ARRAY['Türk Edebiyatı','Şiir','İlhan Gaşi']::text[], 8.5, '{"poet":"İlhan Gaşi","poet_slug":"i-lhan-gasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/reyhan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 've..', 've-fatih-mehmet-bnpm7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 've akşamlara kusuyordum yalnızlığımı..

ve kelebek oluyordum, yağmur gibi hassas..

ve ağlıyordum kadere ezilmişliğimi..

ve ölüyordum.. 

ve sen yoktun benle, hala...', 've akşamlara kusuyordum yalnızlığımı.. ve kelebek oluyordum, yağmur gibi hassas.. ve ağlıyordum kadere ezilmişliğimi.. ve ölüyordum..  ve se...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet']::text[], 8.5, '{"poet":"Fatih Mehmet","poet_slug":"fatih-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir..', 'bir-fatih-mehmet-ty15d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün daha bitti..

Bir avuntu, bir umut, bir film, bir rüya daha..

Bir hayal daha söndü..

Bir ışık, bir dünya, bir göz, bir aşk daha..

Ve kalan bir nefes..

O''da yalan...', 'Bir gün daha bitti.. Bir avuntu, bir umut, bir film, bir rüya daha.. Bir hayal daha söndü.. Bir ışık, bir dünya, bir göz, bir aşk daha.. Ve ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet']::text[], 8.5, '{"poet":"Fatih Mehmet","poet_slug":"fatih-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Arar Sevdiğim', 'belki-arar-sevdigim-aytekin-gezici-n9emo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulağım sevdiğin sesine hasret

Ecel gelecekse eğer

N''olur biraz beklesin

Belki arar sevdiğim', 'Kulağım sevdiğin sesine hasret Ecel gelecekse eğer N''olur biraz beklesin Belki arar sevdiğim...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Gezici']::text[], 8.5, '{"poet":"Aytekin Gezici","poet_slug":"aytekin-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/belki-arar-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-turgay-sahin-a4cgf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sadece kendine yaptıkların için değil, 

bana kattığın güzellikler için. 

SENİ SEVİYORUM! 

İçimdeki çocuğu, saklı kalmış beni yeryüzüne 

çıkardığın ve sana ihtiyacım olduğu her an tüm 

duyarlılığınla yanı başımda olduğun için. 

SENİ SEVİYORUM! 

Elini kalbimin üzerinde hissettiğim zaman, 

üzüntülerimi alıp, onların yerine şimdiye kadar 

hiç kimsenin başaramadığı o sıcaklığı, o içtenlik 

ışığını bana duyurmayı başardığın için. 

SENİ SEVİYORUM! 

Hayatımı kutsal bir sevgi tapınağına çevirdiğin 

ve her günümü yaşam şenliğine, unutulmayan 

şiirlere dönüştürdüğün için. 

SENİ SEVİYORUM! 

Çünkü, sen, şimdiye kadar hiç başaramadığım şeyleri, 

kendimle dost ve barışık olmayı ve hiç bir zaman

tadamadığım kadar mutlu olmamı sağlıyorsun.

ve bütün bunları yalnızca sözlerinle, dokunuşunla

yada işaretle değil, kendin olmakla yapıyorsun. 

HİÇ KUŞKUSUZ, SAĞLIKLI SEVGİ 

VE GERÇEK DOSTLUK, 

ÖLÜMSÜZ ARKADAŞLIK BUDUR...', 'Sadece kendine yaptıkların için değil,  bana kattığın güzellikler için.  SENİ SEVİYORUM!  İçimdeki çocuğu, saklı kalmış beni yeryüzüne  çıka...', ARRAY['Türk Edebiyatı','Şiir','Turgay Şahin']::text[], 8.5, '{"poet":"Turgay Şahin","poet_slug":"turgay-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-seviyorum-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda yolculuk', 'umuda-yolculuk-olcin-orkun-z36nn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bitmeyen gecelerde, sabah olurmu ?..

Gözyaşları sel gibiyken

     gözler kurur mu ?

Alev alev yakarken hasret acısı,

Çırpınışlar boşuna

     çare bulunur mu ? ..

Uzaklarda görünen ışık,

Bir avuç mutluluk mu ?

Hayallerle yaşanmazken,

Gerçekler bulunurmu ?

Kolay değil acılara karşı direnmek,

Gün gelir de

Acılar son bulur,

Hayaller gerçek olurmu ? ..', 'Bitmeyen gecelerde, sabah olurmu ?.. Gözyaşları sel gibiyken      gözler kurur mu ? Alev alev yakarken hasret acısı, Çırpınışlar boşuna     ...', ARRAY['Türk Edebiyatı','Şiir','Olçin Orkun']::text[], 8.5, '{"poet":"Olçin Orkun","poet_slug":"olcin-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umuda-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöküyorum', 'cokuyorum-cahit-sitki-taranci-kbpne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saltanat sürmektedir içimde bir hükümdar,

Hırsının pençesinde,şehvetinin esiri;

Etrafını almıştır dalkavuk ve riyakar;

Korkulu bir sarayım doğduğum günden beri.

Ne gizli cinayetler,neler neler oluyor,

Denize her gün körpe cesetler döküyorum.

Ne baharlar soluyor,ne baharlar soluyor,

Azamet ve ihtişam içinde çöküyorum!', 'Saltanat sürmektedir içimde bir hükümdar, Hırsının pençesinde,şehvetinin esiri; Etrafını almıştır dalkavuk ve riyakar; Korkulu bir sarayım d...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cokuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-metin-vatansever-oc4lt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekleyiş; Bir özleyiş gönüldeki güzeli,

Bekleyiş; Bir süsleyiş binbir hisle emeli,

Neden?  O çok sevene ''unut bekleme'' derler,

Oysa! Seven ümitsiz de olsa beklemeli...', 'Bekleyiş; Bir özleyiş gönüldeki güzeli, Bekleyiş; Bir süsleyiş binbir hisle emeli, Neden?  O çok sevene ''unut bekleme'' derler, Oysa! Seven ü...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bekleyis-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evvelim Sensin', 'evvelim-sensin-neset-ertas-05jxr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cahildim dünyanın rengine kandım

Hayale aldandım boşuna yandım

Seni ilelebet benimsin sandım

Ölürüm sevdiğim zehirim sensin

Evvelim sen oldun ahirim sensin

Sözüm yok şu benden kırıldığına

Gidip başka dala sarıldığına

Gönlüm inanmıyor ayrıldığına

Gözyaşım sen oldun kahirim sensin

Evvelim sen oldun ahirim sensin

Garibim can yakıp gönül kırmadım

Senden ayrı ben bir mekan kurmadım

Daha bir gönüle ikrar vermedim

Batınım sen oldun zahirim sensin

Evvelim sen oldun ahirim sensin', 'Cahildim dünyanın rengine kandım Hayale aldandım boşuna yandım Seni ilelebet benimsin sandım Ölürüm sevdiğim zehirim sensin Evvelim sen oldu...', ARRAY['Türk Edebiyatı','Şiir','Neşet Ertaş']::text[], 8.5, '{"poet":"Neşet Ertaş","poet_slug":"neset-ertas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/evvelim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğin Sesi', 'sessizligin-sesi-cem-cem-jp087', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sessizliğinde sesi vardır, 

bir acısı, bir beklediği, bir istediği...

sessizlikte adamdır gecede, 

herkes gittiğinde 

her şey bittiğinde...', 'sessizliğinde sesi vardır,  bir acısı, bir beklediği, bir istediği... sessizlikte adamdır gecede,  herkes gittiğinde  her şey bittiğinde......', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sessizligin-sesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında', 'aslinda-cem-cem-ul3qz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrılmanın da bir adabı vardır, 

ayrılırken, 

bir ''aslındalı cümle'' kurmak gerekir... 

''aslındalı cümle''yi gözü dolu dolu, 

sesi kırık bulutlu söylemek gerekir.. 

“aslındalı cümle”nin hemen ardından, 

layık olmadığının mecburi yalancılığıyla devam eden sözleri, 

sıkıla sıkıla görüntülü, 

gözleri kaçıra kaçıra, 

kirpikleri aça kapaya, 

söylemek gerekir... 

''aslındalı cümle''nin müdafaasına soyunmak üzere, 

karşılıklarını önceden düşünmüş, planlamış, kurmuş, öğrenmiş, 

ve aslında çoktan uzaklara gitmiş yüreğin yerine, 

sahte bir yürek gerekir... 

tüm sözlerin bittiği, 

sessizliğin konuşmaya başladığı bir anda, 

son bir kez gözgöze gelmek, 

ellerin özlenilecek nemini, kırgın avuç içlerinde, son defa hissetmek, 

birinin gül kalması için birinin toprak olması gerçeğini kabullenmek, 

ve biriyle geldiğin bir yerden hiçbiriyle dönmek gerekir.. 

aslında ayrılmanın da bir adabı vardır, 

ayrılırken adabına uymak gerekir...', 'ayrılmanın da bir adabı vardır,  ayrılırken,  bir ''aslındalı cümle'' kurmak gerekir...  ''aslındalı cümle''yi gözü dolu dolu,  sesi kırık bulut...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aslinda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıvrım Kıvrım', 'kivrim-kivrim-cem-cem-uenre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gitme 

severken, 

kıvrım kıvrım olur dudaklarım dayanamam, 

gidersen.. 

gelme 

gidersen, 

heyecanı

tüketir kavuşmanın durduramam, 

gelirsen...', 'gitme  severken,  kıvrım kıvrım olur dudaklarım dayanamam,  gidersen..  gelme  gidersen,  heyecanı tüketir kavuşmanın durduramam,  gelirsen....', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kivrim-kivrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum', 'kum-cem-cem-jhh5h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ya sen dök beni, 

yada bekle.. 

ben süzüleyim parmaklarından... 

beni düşünme, 

sonbahar gelir, 

bir rüzgar eser yine, 

yine toplanır tanelerim, 

beni avuçlarına doldurduğun sahilde...', 'ya sen dök beni,  yada bekle..  ben süzüleyim parmaklarından...  beni düşünme,  sonbahar gelir,  bir rüzgar eser yine,  yine toplanır tanele...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Kez Son Kez', 'i-lk-kez-son-kez-cem-cem-032pr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ateşten çıktım, 

herşey soğuk son kez daha... 

belki de bir çok kezleri bir kez daha artırmak için bir kez daha idi, 

ama 

sıcaklık farkı çoktu, 

dahasını yuttu, 

ona bir son verdi. 

ilk kez son kezle bitti..', 'ateşten çıktım,  herşey soğuk son kez daha...  belki de bir çok kezleri bir kez daha artırmak için bir kez daha idi,  ama  sıcaklık farkı ço...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ilk-kez-son-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tehlikeli', 'tehlikeli-cem-cem-oj5dy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tehlikeyi sezince kaçacak kadar 

tehlikesiz değilim ben... 

günün gitmesine 

karanlığın çökmesine 

güneş bile taraftar değilken, 

ve çekip giderken, 

korku dolu sarı gözlerle, 

benle başbaşa kalmak gecede, 

yürek ister. 

tehlikelidir gece, 

tehlikelidir gözler!!!', 'tehlikeyi sezince kaçacak kadar  tehlikesiz değilim ben...  günün gitmesine  karanlığın çökmesine  güneş bile taraftar değilken,  ve çekip g...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tehlikeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Ama', 'yasak-ama-cem-cem-xpm28', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hekim kontrolünde sevmem lazımdı benim... 

bünye uygunluğu testleri, 

bol sorulu formlar, 

günlerce sonuç beklemeler, 

ilgili onaylar, 

reçeteli sevgiler... 

yattı balık yan gidiyor yine .. 

sodyum fazlalığı , 

potasyum eksikliği , 

ortam ısısının uygunsuzluğu, 

yada bilmem ne bela.. 

yasak ama, 

''günde altı saatte bir''den fazla yanında olmak istiyorum ... 

yasak ama, 

avuçlarımdan avuçlarına ısı nakli denetimsiz.. 

yasak ama, 

gözlerinin ışıltısı tehlikeli, heyecanlandırıyor.. 

yasak ama, 

omzundan hiç kalkmak istemiyorum .. 

yasak ama, 

sana alışıyor bünyem .. 

yasak ama, 

seni seviyorum …', 'hekim kontrolünde sevmem lazımdı benim...  bünye uygunluğu testleri,  bol sorulu formlar,  günlerce sonuç beklemeler,  ilgili onaylar,  reçe...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasak-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler', 'turkuler-cem-cem-m0wps', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben sevgimi bir türküye verdim, 

sonralardan kaç türkü en çok sevdiğim oldu bilmem... 

kızılı ve ateşi, 

beyazı ve suyu, 

karayı ve geceyi, 

kahverengiyi ve toprağı öğrendim hepsinden... 

ama bir şey gördüm ki hepsinde birden, 

türküler sözleri gibidir, 

sözleri değişmez, 

ne kadar değiştirmek istersen iste, 

sözleri izin vermez...', 'ben sevgimi bir türküye verdim,  sonralardan kaç türkü en çok sevdiğim oldu bilmem...  kızılı ve ateşi,  beyazı ve suyu,  karayı ve geceyi, ...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/turkuler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-cem-cem-969os', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'demin bardağı sarması gibi, 

bardağın dudağa dokunması gibi, 

dudağın çaya kavuşması gibi, 

yudum yudum sevdim seni...', 'demin bardağı sarması gibi,  bardağın dudağa dokunması gibi,  dudağın çaya kavuşması gibi,  yudum yudum sevdim seni......', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevdim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim', 'beklerim-cem-cem-925q2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gelmene karar veremedim, 

bekledim...

gitmene gönül koyamadım, 

gitmese dedim... 

ne zaman gelirsen kabulüm, 

ne zaman gidersen, 

beklerim...', 'gelmene karar veremedim,  bekledim... gitmene gönül koyamadım,  gitmese dedim...  ne zaman gelirsen kabulüm,  ne zaman gidersen,  beklerim.....', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beklerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim içime sığmadığında', 'i-cim-icime-sigmadiginda-cem-cem-pavpl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gecede bitirdim tüm güzel sözleri, 

gülün kırmızısını denizin mavisini... 

içim içime sığmadığında o hep geldi, 

ya da hep o varken sığmadı içim içime...', 'gecede bitirdim tüm güzel sözleri,  gülün kırmızısını denizin mavisini...  içim içime sığmadığında o hep geldi,  ya da hep o varken sığmadı ...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icim-icime-sigmadiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolda kalan', 'yolda-kalan-cem-cem-f92hp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'önce hayatı hayale yolladık, 

yolda kaldık... 

sonra hayal parçalayıp, 

hayata bozduk, 

yaranamadık... 

yolda kalan hayatlar, 

tanınması zor hayaller,

öylece kalakaldık...', 'önce hayatı hayale yolladık,  yolda kaldık...  sonra hayal parçalayıp,  hayata bozduk,  yaranamadık...  yolda kalan hayatlar,  tanınması zor...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yolda-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buralar Kadıköy', 'buralar-kadikoy-cem-cem-uuewb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sebepsiz hüzünlendiğim yerlerde yürüyorum, 

adımlarımın arkasında gereksiz takipteyim,

son vapur da kavuştu kıyıya tüm anlamsızlığıyla, 

kulaklarım donuyor çok üşüyorum. 

buralar kadıköy, 

ben buraları çok seviyorum....', 'sebepsiz hüzünlendiğim yerlerde yürüyorum,  adımlarımın arkasında gereksiz takipteyim, son vapur da kavuştu kıyıya tüm anlamsızlığıyla,  kul...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/buralar-kadikoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebeler', 'korebeler-cem-cem-jidci', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'oyuna göre, 

kör ebeyiz hepimiz.. 

ve şikayetçi değiliz hiçbirimiz, 

ebe olmaktan, kör kalmaktan …', 'oyuna göre,  kör ebeyiz hepimiz..  ve şikayetçi değiliz hiçbirimiz,  ebe olmaktan, kör kalmaktan …...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/korebeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirpiklerim', 'kirpiklerim-cem-cem-p41c1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne zaman sahilde bir yağmur damlası düşse kirpiklerime, 

yağmuru kalır, 

damlası düşer kirpiklerimden... 

ne zaman dudaklarım değer kirpiklerimden düşene,

şarkım gelir dilime, 

şarkımı söylerim içimden, 

dudaklarım kurur yine, 

damlamı bekler kirpiklerimden...', 'ne zaman sahilde bir yağmur damlası düşse kirpiklerime,  yağmuru kalır,  damlası düşer kirpiklerimden...  ne zaman dudaklarım değer kirpikle...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirpiklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fasiküller', 'fasikuller-cem-cem-xezwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'fasikül fasikül yaşadık... 

konusu vardı, 

sırası vardı, 

süresi vardı..', 'fasikül fasikül yaşadık...  konusu vardı,  sırası vardı,  süresi vardı.....', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/fasikuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelepçe', 'kelepce-cem-cem-bsiuj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen dizelerini dindiremedin, 

tükendin, 

gittin. 

ben aklıma kelepçeli bakakaldım... 

güzel gözlüm, 

dağlara savur artık söyleyemediğin tüm sözleri, 

ve bir daha asla dönme geri .... 

çünkü ben, 

çoktan kuruttum veremediğim gülleri ..', 'sen dizelerini dindiremedin,  tükendin,  gittin.  ben aklıma kelepçeli bakakaldım...  güzel gözlüm,  dağlara savur artık söyleyemediğin tüm ...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kelepce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-cem-cem-5v0b5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'damlamıyorum 

sadece hayal. 

kırsallığım, 

kızgınlığım, 

çekingenliğim, 

benliğim... 

gelinlik giymiş çınar ağacıyla, 

kulaklarının arkasına karanfil takan beyaz güvercin gibi,

koca bir hayal ..', 'damlamıyorum  sadece hayal.  kırsallığım,  kızgınlığım,  çekingenliğim,  benliğim...  gelinlik giymiş çınar ağacıyla,  kulaklarının arkasına...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayal-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazsa Olmaz', 'olmazsa-olmaz-cem-cem-o2sss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaprak sarıya mecbur, 

havalar ılık, 

su dolap dışı, 

balkon kapıları sıkı sıkı kapalı, 

kaynamayan ikindi çayı, 

erken yemek, geç kalma sıkıntısı..

hayallere gelecek yasağı ,

geçmiş tekrarı, 

eskisi denilecek eskilerin zamanı.. 

olmazsa olmaz, 

olsa iyi olur, 

olmasa da olur.. 

yaprak yeşile mecbur, 

havalar sıcak, 

su dolapta buz, 

sokak arası balkonlarında ikindi keyif çayları, 

yemek üstü sigara keyfi, 

hayallerin zamanı, heyecanı, 

bekleme ,beklenme tadı .. 

olmazsa olmaz , 

olmazsa olmaz , 

olmazsa olmaz .', 'yaprak sarıya mecbur,  havalar ılık,  su dolap dışı,  balkon kapıları sıkı sıkı kapalı,  kaynamayan ikindi çayı,  erken yemek, geç kalma sık...', ARRAY['Türk Edebiyatı','Şiir','Cem Cem']::text[], 8.5, '{"poet":"Cem Cem","poet_slug":"cem-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olmazsa-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hasretimsin', 'hasretimsin-sair-gulce-zlh62', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapkara gökyüzünde güneş çıkacak

Hazan dolu bahçemde güller açacak

Beni affettiğin gün

Hatalıyım biliyorum

Sevgini haketmedim

Seni öyle çok sevdim

Sevdiğimi diyemedim

hasretinle yanar kalbim 

birgün gelecek diye

çağırsam gelirsin biliyorum

sevdamı gömmüşüm kalbime

sanmaki sevmiyorum

sanmakiumarsızım

dertlerim le başbaşa kalmışım

hasretin yok eder beni

tek avuntumsun sen

hayalinle yaşamak tek mutluluk

istersen sevmedi de

değerimi bilmedi

haketmedi beni

gözlerimden süzülüyorsa yaşlar

tebessümlerim donuyorsa birden

kaçmak son çaremdi anlamalısın

ama anlayamazsın

sen benmisinki anlayasın

Gülce', 'Kapkara gökyüzünde güneş çıkacak Hazan dolu bahçemde güller açacak Beni affettiğin gün Hatalıyım biliyorum Sevgini haketmedim Seni öyle çok ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gülce']::text[], 8.5, '{"poet":"Şair Gülce","poet_slug":"sair-gulce","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hasretimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-necip-fazil-kisakurek-hnxcz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her ağızda, her telde fanilik dırıltısı,

Sonunda tek şarkı, tabutun gıcırtısı.', 'Her ağızda, her telde fanilik dırıltısı, Sonunda tek şarkı, tabutun gıcırtısı....', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sarki-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızgınım', 'kizginim-berkut-bahar-xh2wd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen kaderimmisin benim

Yoksa sadece bir hevesmi

Belkide sadece titreyen bedenim

Aldanıyordur.

Sen, belkide sen gerçekten aradığım

Sonunda bulduğum, tadına vardığım

Ya da bakışlarına, gülüşüne kandığım

Kadınsındır.', 'Sen kaderimmisin benim Yoksa sadece bir hevesmi Belkide sadece titreyen bedenim Aldanıyordur. Sen, belkide sen gerçekten aradığım Sonunda bu...', ARRAY['Türk Edebiyatı','Şiir','Berkut Bahar']::text[], 8.5, '{"poet":"Berkut Bahar","poet_slug":"berkut-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kizginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliksiz Sevda', 'kimliksiz-sevda-mehmet-kepez-68t8y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sakin liman değilmiş sevda

ufku görüp dokunamazmış insan

sevenler,

zor yolun yılmaz savaşçısı olurmuş

iki yürek,

iki iklim,

savrulurmuş fırtınada....

ben anadoluya sevdalandım aslında

bozkırlarını sevdim

hoyratlarımda şahlandı yıldızlar

sen barakalarda dillendin

höllükte büyüttük umutlarımızı

toprağa sarıldık seninle

şose boylarında eğlenmeyi bilmedik

yaşamayı tez,

kavgayı geç

sevdayı hiç bilmedik,

sevdamızı sakladık,akıtıp düşlere saldık gecelerce

delice sevdik sevda çıkmazını bilmedik...

ayrıntılara takıldı dileklerin,

son durağıysa bilmedi düşlerim

asırlarca aradım çağlayanını

birbirimize kimlik olmayı beceremedik....', 'sakin liman değilmiş sevda ufku görüp dokunamazmış insan sevenler, zor yolun yılmaz savaşçısı olurmuş iki yürek, iki iklim, savrulurmuş fırt...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kepez']::text[], 8.5, '{"poet":"Mehmet Kepez","poet_slug":"mehmet-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kimliksiz-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmet', 'kismet-mustafa-tarakci-7fds1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gonca idin gül oldun

Al al yanaklarınla...

Hepsi sevda çiçeği

Hepsi sevgiye hasret.

Kopardılar dalından,

Ayırdılar yarinden

Seni sevda çiçeği 

Kimeydin kime kısmet.', 'Gonca idin gül oldun Al al yanaklarınla... Hepsi sevda çiçeği Hepsi sevgiye hasret. Kopardılar dalından, Ayırdılar yarinden Seni sevda çiçeğ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tarakçı']::text[], 8.5, '{"poet":"Mustafa Tarakçı","poet_slug":"mustafa-tarakci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kismet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olağan', 'olagan-sude-su-07twg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kulaklarımda sesinin uğuldayışı

Durmaksızın.. ve ansızın

Iskaladığımız mutluluklarmış.. hayatımızı bezeyen

Ve göğsümüze sapladığımız o zehirli hançer

Geç kalmışlığımıza ödettiğimiz bedel

Şimdi ıpıssız bi şehirde yaralıyım

Kanarken

Sızılarıma merham sordum

Kaygılarıma umut

Ve çaresizliğime sen''i

Oysa ki ilk değil sendeleyişim

Kimi iklimlerden hatırımda kalan

Aynı sahneler, aynı sözler..

Anladım ki alacak dersim de yok

Her seferinde takılıp düştüğüm

Bağışlamasız döngü''den', 'Kulaklarımda sesinin uğuldayışı Durmaksızın.. ve ansızın Iskaladığımız mutluluklarmış.. hayatımızı bezeyen Ve göğsümüze sapladığımız o zehir...', ARRAY['Türk Edebiyatı','Şiir','Sude Su']::text[], 8.5, '{"poet":"Sude Su","poet_slug":"sude-su","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olagan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-sude-su-oui1f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En sadık,

Bir o kadar nankör olan..', 'En sadık, Bir o kadar nankör olan.....', ARRAY['Türk Edebiyatı','Şiir','Sude Su']::text[], 8.5, '{"poet":"Sude Su","poet_slug":"sude-su","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aci-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE ÇOK NE ÇOK', 'ne-cok-ne-cok-sumru-sipahi-li90z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırık birer vazoyuz şimdi

Ödünç alınmış hayatları yaşayan

Birbirimize verdiğimiz çiçekler

Yaban otundan farksız

Ne çabuk ne çirkin tükettik mucizeleri

Sen ruhu hasta kalbi umutsuz adam

Ne çok ne deli sevdim ben seni...', 'Kırık birer vazoyuz şimdi Ödünç alınmış hayatları yaşayan Birbirimize verdiğimiz çiçekler Yaban otundan farksız Ne çabuk ne çirkin tükettik ...', ARRAY['Türk Edebiyatı','Şiir','Sumru Sipahi']::text[], 8.5, '{"poet":"Sumru Sipahi","poet_slug":"sumru-sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ne-cok-ne-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Solurken Yüreğim', 'geceyi-solurken-yuregim-ahmet-sahin-soner-b27ly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlham Peri ‘ me ....

Bu gece gözlerim ışıksız kaldı , 

Yıldızlar ışıdı yüzüme , ay parladı ansızın

Geceyi solurken yüreğim

Kalemim düştü masamın üzerine

Bir parça kağıda sarıldım

Beynimde dolaşan çizgiler 

Birer harf olabilme arifesinde

Harflerimi mısralarla birleştiremiyorum ,

Bir şeyler eksik sanki 

Kırmızı bir mum yakıyorum

Mısralarımı ısıtsın diye

Tavşan kanı çay kıvamında gidip geliyorum

Yinede bir şeyler eksik

Pilli bir radyo ile oynuyorum ,

Fm bandından yayın yapan bir radyonun ,

Çırtlak sesli kızının sesini dinliyorum

Biraz daha büküyorum kulağını

Füdayda ‘da Ankaralım diyor bir adam

Füdaydada Ankaralım füdayda

Gecenin karanlık telkisinde

Caddelerdeki insanların seslerini dinliyorum

Ama yinede bir şeyler eksik

Bir sigara yakıyorum

Yorumlamakta güçlük çektiğim 

Belli belirsiz şekiller çiziyorum

Ve sonra bu tavşan oldu diyorum ,

62 den tavşan yapmayı bilir misin sen ?

Hani üzerine kulak çizersin ‘ M ‘ harfinden 

 Pencereyi açıyorum

Serin bir rüzgar esiyor

Bir bardak su içiyorum

Radyo haberleri veriyor bir yandan

İçinde ben oluyorum bir vakit

Sonra ince sazın eşliğinde ,

Bir yurdum türküsüne kaptırıyorum kendimi

Ver elini ver bana eftelya

Bir vakit karanlıkta dans ediyorum.

Sen hiç saz eşliğinde dans ettin mi ?

Etmemişsindir sanırım

Yıldızları sayıyorum birer birer 

Onlar basamağından bir sayıyı çarpanlarına ayırıyorum

Geçmez oluyor zaman

Saniyeler dakika oluyor

Dakikalar saat ,

Saatlerse ne bileyim ne zamanı ,

Tadımı bulamıyorum bu gece

Ve halen bir şeyler eksik sanki

Karanlık bir merdivenden çıkıyorum yukarılara

Yeşil ışık yayan bir el fenerinin ışığında

Çıktıkça gecenin karanlığını soluyorum

Bir vakit sonra yıldızlara ulaşıyorum

Üç ’e  beş metre bir teras katından

Görebildiğim sekiz on yıldızla konuşuyorum

Rüzgar esiyor ara sıra

Hoş bir kokuyu taşıyor yüreğimin içerisine

Martıların çığlıklarını duyar gibiyim

Denizlerdeki yakamozlardan önce

Ama yinede bir şeyler eksik

Kalemim harfler çizmeye cesaret edemiyor.

Ve mısralarım duygusuz ,

Başım önümde odama dönüyorum .

Bir an ılık bir nefes beliriyor.

Hoş bir ses çınlıyor kulaklarımda.

Özlem kadar özlem doluyor yüreğime

Penceremden içeri bir ışık gibi süzülüyor hayalin 

Gözlerinde yıldızların ışıltısı ,

Denizlerin kokusunu getiriyorsun .

Penceremin perdesini havalandırıyor nefesin

Bir rüzgar serinliğinde

Havalandırdığın denizin sularını serpiştiriyorsun üzerime

Bir meltem esintisi olup dolduruyorsun odamı

Siyah camdan masamın ,

Borda deri kaplı ,

Üzerine kanaviçe isli 

Tekerlekli İtalyan iskemlesi ne  oturuyorsun

Kırmızı mum’ un alevi ışıyor yüzüne

Ve gölgen aksediyor odamın duvarından

Sende özlediğim kadar özlem buluyorum

Kalemim dansetmeye başlıyor

Kalın italik harflerin eşliğinde 

Arial tur bir karakter oluyorum

Elimi uzatıyorum eline

İlhamım diyorum geldin işte

Bak radyoda tango çalıyor

‘ Papatya gibisin beyaz ve ince tutuşur yüreğim seni görünce ‘

Kadın çığlık çığlığa sanki ağlar gibi

Sanki uçar gibi gökyüzüne söylüyor şarkısını ,

Şarkının dizelerine renkler veriyoruz seninle Peri ‘ m

Kırmızı mumun yanan alevinde tutuşuyor yüreğim

Seni çekiyorum kendime özlemim kadar

Ve uçarcasına dans ediyorum seninle

Bütün saf duyguları işliyor gözlerin ,

Mumun alevinde parlayan gözlerimin içerisine

Bende yüreğimden süzüyorum seni 

Ve yüreğimde senden dolma duygular oluşturuyorum ,

Sen bir duygu yüreğim süzgeç oluyor peri’ m

Her şey geçiyor sen kalıyorsun yüreğimde

İngiliz alfabesinden olma harflerle işliyorum

Sonra harfler birleşip senden kalma mısraları doğuruyor.

Mısraların arasında kayboluyoruz.

Her mısrada yüreğimin özlemi kadar

Gökyüzündeki yıldızlar kadar

Duygularımız oluyor senden ve benden 

İlham oluyorsun geceme ,

Gecemden ve senden düşen sözlerime

İlham oluyor , sen doluyorsun peri ‘m

Özlediğim kadar özlemle

Karanlık bir gecede

Siyah cam masamın aynasında 

Kırmızı , ortalığa isler yayarak yanan mumun alevinde ,

Parlayan yüzünle ,

O deniz kokan teninle 

Yıldızlar saçan gözlerine

Yüreğime ilham olan sesinle 

İyi ki geldin Peri ‘m özlemin hoş geldin', 'İlham Peri ‘ me .... Bu gece gözlerim ışıksız kaldı ,  Yıldızlar ışıdı yüzüme , ay parladı ansızın Geceyi solurken yüreğim Kalemim düştü mas...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/geceyi-solurken-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işıgında', 'ay-isiginda-adnan-yucel-hpbtx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceler midir tükenip giden

Aylar mı yoksa ay ışığında

Ey soluğumu soluğunda sevdiğim

Sesimi sesinde dinleyip,yüreğinin rengine gönül verdiğim.

Bil ki senden uzak ne kuşları avutabilir beni buranın', 'Geceler midir tükenip giden Aylar mı yoksa ay ışığında Ey soluğumu soluğunda sevdiğim Sesimi sesinde dinleyip,yüreğinin rengine gönül verdiğ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ay-isiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önceki sen', 'onceki-sen-husamettin-unsal-2b3co', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni arıyorum,

yüreğimdeki dün gibi

Benimle olmanı istiyorum 

Önceki dün gibi

Dalgaların sahili dövdüğü ve martıların ağladıgı ayrılığı,

Dünü silmek istiyorum,önceki güne geçmek

Yeniden yaşamak, 

Sevgiyi ve seni...

Dünü istiyorum,önceki dünü

Kollarımda sen,gözlerimde sen,yüreğimde sen

Seni gözlerimde istiyorum

Önceki dünde,önceki seni...', 'seni arıyorum, yüreğimdeki dün gibi Benimle olmanı istiyorum  Önceki dün gibi Dalgaların sahili dövdüğü ve martıların ağladıgı ayrılığı, Dün...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Ünsal']::text[], 8.5, '{"poet":"Hüsamettin Ünsal","poet_slug":"husamettin-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onceki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazır Ol', 'hazir-ol-basri-erkan-7tpv2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarını dökmeye hazır ol.

Hazır ol gafil avlayan zamansız acılara kucak açmaya.

Düşman kesilen zamana lanet ayğdırmaya

Alevlenen ateşi söndüremeden yüreğinin kül olmasına...

Hazır oll

Hazır ol itiraf yağmurlarında inkarı yenmeye

İmkansız da olsa

İmkansızı sevdiğini sevmeye...

Mutlulukla acı arasında yıkılan köprüde acıya teslim olmaya

Hazır oll...

Hazır ol

Tüm benliğinle benim olmaya...', 'Gözyaşlarını dökmeye hazır ol. Hazır ol gafil avlayan zamansız acılara kucak açmaya. Düşman kesilen zamana lanet ayğdırmaya Alevlenen ateşi ...', ARRAY['Türk Edebiyatı','Şiir','Basri Erkan']::text[], 8.5, '{"poet":"Basri Erkan","poet_slug":"basri-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hazir-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmiydin', 'senmiydin-husamettin-unsal-m3c8b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senmiydin hatırlatan

Unuttuğum gözyaşlarımı

Yoksa senmiydin ağlatan

Hergece,acımasızca...

Geceler sessizdi,çaresiz ve yalnızdım

Yoktun,olmayacaktın.

Unuttuğum gözyaşlarım,

Unutturduğun mutluluğumsun', 'Senmiydin hatırlatan Unuttuğum gözyaşlarımı Yoksa senmiydin ağlatan Hergece,acımasızca... Geceler sessizdi,çaresiz ve yalnızdım Yoktun,olmay...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Ünsal']::text[], 8.5, '{"poet":"Hüsamettin Ünsal","poet_slug":"husamettin-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senmiydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Degin', 'sonsuza-degin-basri-erkan-rdar4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tuzum olsan,

Sensiz bir eksiklik duysam.

İçtiğim su gibi,

bana can versen.

Ekmeim olsan,

acıktığımda yudum yudum beni doyursan.

Yaram gibi;sana kavuştuğumda iyileşebilsem

Fenerim olsan

Gideceğim yolu hiç sönmeyen ışığınla bulsam.

Kutup yıldızım olsan

Gecelerimde bir güneş gibi beni aydınlatsan...

Her daim yanıbaşımda beni dimdik ayakta tutsan.

Acımtrak hüznüme ortak olsan,

Tatlı hüznümsün diye sana seslenebilsem.

Yaşamının 35 yılını bana bahşetsen,

Gözlerinin derinliklerinde kendimi yansıtabilsem.

Ömrüme bedelsin diye gözlerimi sonsuza değin kapatsaaam,kapatsam.', 'Tuzum olsan, Sensiz bir eksiklik duysam. İçtiğim su gibi, bana can versen. Ekmeim olsan, acıktığımda yudum yudum beni doyursan. Yaram gibi;s...', ARRAY['Türk Edebiyatı','Şiir','Basri Erkan']::text[], 8.5, '{"poet":"Basri Erkan","poet_slug":"basri-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonsuza-degin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-alev-kutluozen-qkakt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gül pembesi dudaklarına akıyor sevdam

suskunluğumda arıyorum seni

kuşların çığlığında duyuyorum

rüzgarın esişinde sesin

karışıyorum yalan düşlere

dağlara, denizlere, nehirlere

dağlar cesaretim nehirler hasretim

deniz en güzel düşlerim oluyor

yarım kalan bir aşkın

dallarından kopardığım

yasak meyvalarını tadıyorum

gül kokuyor tenim 

                                SENİ ÖZLÜYORUM', 'gül pembesi dudaklarına akıyor sevdam suskunluğumda arıyorum seni kuşların çığlığında duyuyorum rüzgarın esişinde sesin karışıyorum yalan dü...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-ozluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-ahmet-bedirhan-p770f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Serabındı beni sana çeken

Esaretim neden bu derece bilmem

Vaveyla bu gönle gerekliyken

Garip bir hüzün ve ayrı bir sevgi

İçindeyim şimdi, gönlümün sultanı sensin SEVGİ! ! ! ...', 'Serabındı beni sana çeken Esaretim neden bu derece bilmem Vaveyla bu gönle gerekliyken Garip bir hüzün ve ayrı bir sevgi İçindeyim şimdi, gö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bedirhan']::text[], 8.5, '{"poet":"Ahmet Bedirhan","poet_slug":"ahmet-bedirhan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgi-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-basri-erkan-d35pk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay ışığının aydınlattığı deniz kenarında

Karanlığın o gizemli dunyasında

Odaklanıyorum dalgaların şairane mırıltısına

Uçsuz bucaksız enginlere...

Fısıldıyolar name name yureklerımızden kopan notaları

Çiziyorlar oynaşlarında,köpüruşlerınde gozbebeklerının derınlıklerını

Belirtiyorlar kabarışlarında gülüşünü,heycanlarını,arzularını...

Benliğimin kayıp oluşunda.', 'Ay ışığının aydınlattığı deniz kenarında Karanlığın o gizemli dunyasında Odaklanıyorum dalgaların şairane mırıltısına Uçsuz bucaksız enginle...', ARRAY['Türk Edebiyatı','Şiir','Basri Erkan']::text[], 8.5, '{"poet":"Basri Erkan","poet_slug":"basri-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/giz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert', 'dert-ahmet-bedirhan-kkw4v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim bir derdim vardı

Bu gün ama unuttum, 

Çünkü bu gün

Herhalde kendimi kaybettim

Sessiz sedasız geçen 

Her günün ardından

Ağlayarak bakmaya

Korkarak karanlıktan 

Aydınlığa çıkmaya

Ve artık seni unuttuğumu bilerek

Yeni bir aşk peşinde

Koşmaya

Hazırım

Çünkü bugün

Ben bu derdi düşünüyordum

Herhalde

Ama unuttum...

08.01.2001', 'Benim bir derdim vardı Bu gün ama unuttum,  Çünkü bu gün Herhalde kendimi kaybettim Sessiz sedasız geçen  Her günün ardından Ağlayarak bakma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bedirhan']::text[], 8.5, '{"poet":"Ahmet Bedirhan","poet_slug":"ahmet-bedirhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dert-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan İçindeki Dikenlerdir', 'aglayan-i-cindeki-dikenlerdir-ethem-vayvayli-9m3y0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'soygun başladı

sabahdı erkenden gözlerinde

akşam olduğunda sedefler ortacıkta

bir sahilde,buğuya bulaşmış yanaklarıyla

terkedilmişti

başkasından

kadındın

yüreğin dağ babalığını emerse

ancak bilebilecek sıcaklıkta

sahra bakışına ram

incecik incecikti

gülüşmelerin

ağlayan içindeki dikenlerdi

yıldızların kovduğu çocuklar

doluşmuştu kapından

incilerin ve mamuşkaların ardından

harap gölgeliklere geçerken yaşam

koşuşmuştu çoçuklar

ardınsıra kapından

şimdi hür özlemleri çoğaltırsın

aşk bulunmaz fırsat kalırken

iki parmağın hep tıkırdar

hep ağlar şafaktaki karıncadan atın

farkındaysan her akşam

her alaca güneşin ardından

bozgunu tutar omuzların

bir adamın arkasından

o adam benim

şehrin puslu aynasından

yarım gülümseyen

körkütük

parkesi Beyoğlu kokan

tanımazsın

şapkamı unuttum Kadıköy vapurunda

şansından

şimdi gel

ben sana kaldım', 'soygun başladı sabahdı erkenden gözlerinde akşam olduğunda sedefler ortacıkta bir sahilde,buğuya bulaşmış yanaklarıyla terkedilmişti başkası...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/aglayan-icindeki-dikenlerdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık ŞARKISI', 'yalnizlik-sarkisi-alev-kutluozen-pl1ll', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Az sonra bitecek bir düş gibi

gece vakti

açılır kapılar büyülü boşluklara

sonsuza.....

düştü üzerime yağmurlar 

ayrılığın adını ölüm koyduğun

utangaç bir akşam üstünde

doladı boynuma kollarını

rüzgar çanları

tutldu ay

            tutuldu güneş

                                 tutuldu gökyüzü

ve tutuldu aşkımız

doruklarda yankılandı

sarı çiçek dağları

kutsandı günahlarım

kekik kokan yamaçlarında

uludağ''ın

eğdi boynunu tutsaklığım

YALNIZIM', 'Az sonra bitecek bir düş gibi gece vakti açılır kapılar büyülü boşluklara sonsuza..... düştü üzerime yağmurlar  ayrılığın adını ölüm koyduğu...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizlik-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmayın', 'dokunmayin-jale-demirdogen-2w8ky', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hüzün kentinin nüfus kütüğünde kayıtlı adım

Beni o kentin sokaklarında arayın

İklim güzse

Mevsim Ekimse

Ayın adı hüzünse

Bir sarı yaprak yere düşmüşse

Bunu yazmak için ben o ağacın altındayım

Benden neşeli dizeler ummayın

Küçükken resim defterime

Bir yaprak çizip içini yeşille boyamadım

Çocukluğumun perdelerini örttüler

Dediler ki ışıklara;

Sakın içeri sızmayın!

Sizin saçlarınızı okşarken elleri annenizin,

Ben muhtemelen

Bir yorgan altı karanlığındayım

Bu şiir biraz uzun olacak

Canınız sıkıldıysa

Devamını okumayın!

Ben hüzün apartmanının üçüncü katında yaşarım

Adımı o apartmanın zillerinde arayın

Vakit geceyse

Ay geceye küsmüşse

Bir yıldız yere düşmüşse

Bunu yazmak için ben

O apartmanın terasındayım

Benden neşeli dizeler ummayım

Küçükken resim defterime

Bir yıldız çizip

İçini kırmızıyla boyamadım

Birer birer değil, kalabalık geldiler

Çocukluğumu üstümden kitlediler

Dediler ki kapılara;

Sakın ha açılmayın!

Siz salıncaklarda sallanırken özgürce

Ben içerde tam on yıl yattım!

Canınızı sıktıysa bu şiir,

Sakın  başa dönüp  bir daha okumayın!

Beni ararsanız yani,

Hüzün neredeyse

Ben oradayım.

Kime sorsanız gösterirler beni

Beni  öldürün;

Dizelerime dokunmayın!', 'Bir hüzün kentinin nüfus kütüğünde kayıtlı adım Beni o kentin sokaklarında arayın İklim güzse Mevsim Ekimse Ayın adı hüzünse Bir sarı yaprak...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dokunmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hürriyet', 'hurriyet-jale-demirdogen-yjwnj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alıp başımı gitmek istiyorum

Bir sokak çalgıcısını takıp koluma

Sözlerini anlamadığım bir lisanın ezgisini mırıldanarak

Toprağı yeni sulanmış bir papatyayı koparıp kökünden,

Takarak saçlarıma...

Tarihe yazıp geçmişimi,

Ve geleceğimi kapatıp fallara

Alıp başımı gitmek istiyorum..

Vazgeçtim

Kurşuna dizdim işte tüm hayallerimi

Siyah önlüğümle eve dönmek için binmeyim o okul otobüsüne

Geç kalmayım hiç,

Babam beklemesin köşede

Tırnakları kırmızı ojeli bir çift zarif el

Elmalı turta koymasın önüme...

Kolalı beyaz yakamı bırakın kirli kalsın..

Anason tadında bir sevdam olmasın hiç

Hayallerim olmasın

Olmasın çünkü artık,

Ağlamak istemiyorum..

Ben alıp başımı gitmek istiyorum

Kimsesiz bir sokak çocuğuna sarılmak

Onun kömür gözlerinin karanlığında kaybolmak

Boğulmak bir köprü altı ayyaşının şarap şişesinin içinde...

Bilmiyorsunuz

Sırtıma kıyamıyorum artık,

Onu dayayıp bir soğuk duvara

Hiç değilse bir kere

Alnımdan vurulmak istiyorum!

Alıp başımı gitmem mümkün değil

Başımı da bırakıp gitmem gerek

Çünkü aklım başımdayken,

Bir sokak çalgıcısı

Kimsesiz bir çocuk,

Ve bir köprü altı ayyaşı kadar bile

Hürriyetim yok!', 'Alıp başımı gitmek istiyorum Bir sokak çalgıcısını takıp koluma Sözlerini anlamadığım bir lisanın ezgisini mırıldanarak Toprağı yeni sulanmı...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hurriyet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Ayna Söyle Bana', 'ayna-ayna-soyle-bana-jale-demirdogen-f6db5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine öyle bakıyorsun yüzüme

Arada bir hep böyle bakarsın zaten

Kahkahalarını zor tutar gibi bir halin var

İşte tamam

Saçlarımı yaptırdım

Gözlerimi boyadım

Yanaklarımı alladım

Dudaklarımı parlattım

Bir gülücük sipariş ettim

Öyle pahalanmış ki sorma

Yok zamanda lazım dedim,

Bastırıp parayı aldım

Kondurdum ağzımın kenarına

İşte şimdi hazırım

Oyuna başlayalım

Ayna ayna söyle bana

Benden daha aptalı var mı dünyada?

Yine inandım

Yine aldandım

Şimdi kahkahalarını patlat

Haklısın

Ben yine sana kaldım', 'Yine öyle bakıyorsun yüzüme Arada bir hep böyle bakarsın zaten Kahkahalarını zor tutar gibi bir halin var İşte tamam Saçlarımı yaptırdım Göz...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayna-ayna-soyle-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rus Salatası Ustası', 'rus-salatasi-ustasi-jale-demirdogen-ug7i7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana hiç söz vermedin

Verseydin tutar mıydın, bilemiyorum

Ciddi bir kavgamız olmadı hiç

Olsaydı ağlar mıydım, bilemiyorum

Sen çok yaşamadın

Yaşasaydın sana şiir yazar mıydım

Sanırım evet.

Artık böyle olasılıklarla çok ilgilenmiyorum

O mayonezi nasıl  o kadar kıvamda tutturuyordun

Ben şimdi bunu merak ediyorum

Senin gibi güzel mayonez yapamayacağım için

Mayonez yapmaya hiç niyetlenmiyorum.

Marketlerde satılıyor

Gidip bir kavanoz alıyorum

Her mayonez alışımda ona gülümsüyorum

Sen kendini mayonez mi sanıyorsun,

Anneminkileri görmeliydin diyorum.

Tatlı bir yalan gibi kırık dökük anıları,

Acı bir gerçek gibi hayatıma kazıdın

Ey Rus Salatası ustası kadın!

Seni tatlı bir yalanken de

Acı bir gerçekken de

Seni seviyorum', 'Bana hiç söz vermedin Verseydin tutar mıydın, bilemiyorum Ciddi bir kavgamız olmadı hiç Olsaydı ağlar mıydım, bilemiyorum Sen çok yaşamadın ...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/rus-salatasi-ustasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrim ''e', 'evrim-e-alev-kutluozen-00bge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '..Evrim ''e......

sonra sessizce girdin yüreğime

bir sağa bir sola baktın

kimseler var mı diye

iğne yapraklı ormanların

kekik kokulu yamaçların

can kızı...

sevgiye bezeyip umutları

yeryüzüne yağmurlar yağdırdı

bal yaptı bir ece arı

sürdü acıyı dudaklarına

küstü kimi gün

kanayan kuşların kanadında

kucakladı aşkı

hıçkırığında gizlendi dağ çiçeklerinin

özüne sindi

kimi gün güldü

yaz yağmurlarına karıştı

fesleğen kokuları

ay parçası PERİ kızı

seni dağlar kıskandı

dağlar sineye bastı gül yaprağını

kokunu sarmaladı rüzgar

coğaltım can evimde seni

bir masal olup

sağalttın düşlerimi

HOŞ GELDİN......

hoş geldin bebeğim / senin 

yalnızlığa hesap soran

minicik yüreğini sevdim.', '..Evrim ''e...... sonra sessizce girdin yüreğime bir sağa bir sola baktın kimseler var mı diye iğne yapraklı ormanların kekik kokulu yamaçlar...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/evrim-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Prospektüsü', 'askin-prospektusu-jale-demirdogen-27oxn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazmış, güzmüş, kara kışmış

Mevsim fark etmez

Bir gün mutlaka dünden daha parlak doğar gün

Yüreğindeki tüm çiçeklerin yüzü bahara döner

İçinde kilitli kalmış bir kapı aralanır

Her şeyi unutursun

Sararmış bir defter yaprağıdır artık dün.

İki ile iki hiç bir zaman dört etmez

Ne konuşulanı anlarsın

Ne söyleneni duyarsın

Unuttuğun şairleri birer birer hatırlar,

Artık uzun cümleler kurmaya çalışırsın

Ve altından kalkamadığın onca sorunun

Bir köşede bekler durur

Sen sebepsiz kahkahalarına

Çabucak alışırsın.

Dilinde tüm zamanların en güzel aşk şarkısı,

Gardrop önlerinde ne giyeceğim kaygısı

Bütünlerin önemi yoktur

Her şey detaylarda saklı...

Dünya toptan karanlıksa,

Bir tek rengin vardır, o da;

Onun verdiği bir demet papatyanın sarısı.

Aşk böyledir işte....

Böyle girer karışır kanının kırmızısına

Yan etkileri bunca güzel bir ilaç gibidir aşk

Şaşırır da kalırsın

Okumadan prospektüsü,

Avuç avuç alırsın.

Sonra....

Bir sabah uyanıp mevsimi fark edersin

İçindeki kapılar yüzüne kapanır bir bir

İki ile ikiyi topladığında dörttür rakam

Nefret ediyorsundur tüm şairlerden

Ve alışamazsın bir türlü gözyaşlarına...

Nerde hata yaptım diye sorma

Aşkın prospektüsünü oku;

Orda aynen şöyle yazar;

Sakın aşkı tenine bulaştırma!

Yoksa kendini Aslı,

Sevdiğini de Kerem sanırsın

Aşk biter,

Sen döner dolanır,

Yine kendine varırsın.', 'Yazmış, güzmüş, kara kışmış Mevsim fark etmez Bir gün mutlaka dünden daha parlak doğar gün Yüreğindeki tüm çiçeklerin yüzü bahara döner İçin...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/askin-prospektusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nadide Koy Sevdası', 'bir-nadide-koy-sevdasi-jale-demirdogen-9nvvz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben dalgalı hırçın deniz

Sen o nadide koyda,

Bedenini yosun sarmış bir eski kaya.

Benim sularımda binbir maceranın tuzu,

Senin oyuklarında dokunulmamış aşkın tadı.

Varmak için tadına,

Sinene vura vura

Canını yaktım hakkım yok!

Kapılıp gitmeliyim artık bir akıntıya...

Görmüyor musun?

Senin yosunlarının ardında vakur bir yürek saklı.

Bir de bana bak,

Yüzü seni aldatmasın,

Bu denizin dibi kara!

Ben istemez miydim dupduru

Bir çarşaf kıpırtısızlığında

Serilmeyi koynuna...

O nadide koyda bir ömür düşlemez miydim?

Gel gör ki suçlu yalnız ben değilim,

Aman vermeden esti

Tarih boyu fırtına!

Ben o fırtınanın esiri dalgalı hırçın deniz,

Sen o nadide koyda

Bedeninin yosun sarmış bir eski kaya.

Beni gönderirken bir akıntıya,

Bir damlamı yosunlarının arasında sakla.

O damla sana sevdalandı,

Onu asla bırakma.', 'Ben dalgalı hırçın deniz Sen o nadide koyda, Bedenini yosun sarmış bir eski kaya. Benim sularımda binbir maceranın tuzu, Senin oyuklarında d...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-nadide-koy-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göktürk - 1', 'gokturk-1-mustafa-bagci-zsh5c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar biz; Juan Juanlar''ın hakimiyetinde;

  Yaşıyorduk başımızda Bumin''le; Altay dağının eteklerinde,

  Av avlayarak, demir döverek uğraşırdık her işle;

  Ergenekon denen eski yurdumuzla destan yazdık işte.

  Dinimizin adı; Gök Tanrı, boyumuzun adı; Aşına,

  Bağımsızlık kazanmak istiyoruz Bumin kağanla,

  Ta ki! Juan Juanlara isyan edene kadar daha;

  Bağımsız olmak için mücadele ettik Juan Juanlarla.

  Beşyüz elli iki yılında koyulduk yola kafileyle,

  Altay dağlarından hareket ettik Ötüken''e,

  Ele geçirdik kutlu yurdu; kağanımız Bumin''le

  Göktürk devletini kurduk, başkent Ötüken olmak üzere.

  En parlak dönemimizi yaşadık Mu-kan''la,

  Batıda sınır genişleten İstemi Yabgu''yla,

  Güneyde Çin, batıda Sasaniler''le yapılan savaşla,

  Türk tarihine destan yazdı Göktürk; hakanlarla.', 'Bir zamanlar biz; Juan Juanlar''ın hakimiyetinde;   Yaşıyorduk başımızda Bumin''le; Altay dağının eteklerinde,   Av avlayarak, demir döverek u...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bağcı']::text[], 8.5, '{"poet":"Mustafa Bağcı","poet_slug":"mustafa-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gokturk-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
