INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin İstanbul Oluyor Birden', 'gozlerin-i-stanbul-oluyor-birden-yavuz-bulent-bakiler-t9mz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle bir yağmur başlıyor iplik iplik,

Bir güzellik doğuyor yüreğime şiirden.

Martılar konuyor omuzlarıma,

Gözlerin İstanbul oluyor birden.

Akşamlardan, gecelerden, senden uzağım

Şiirlerim rüzgardır uzak dağlardan esen

Durgun sular gibi azalacağım

Bir gün, birdenbire çıkıp gelmesen.

Şarkılarla geleceksin, duygulu, ince

Yalnız gözlerime bak diyeceksin.

Ellerim usulca ellerine değince

Kaybolup gideceksin

Bir elim seni çizecek bütün pencerelere

Bir elim seni silecek.

Kalbim: Ebemkuşağı; günde bin kere

Senin için yeni baştan can kesilecek.

Ne güzel seni bulmak bütün yüzlerde

Sonra seni kaybetmek hemen her yerde

Ne güzel bineceğim vapurları kaçırmak

Yapayalnız kalmak iskelelerde.

Seninle bir yağmur başlıyor iplik iplik,

Bir güzellik doğuyor yüreğime şiirden.

Martılar konuyor omuzlarıma,

Gözlerin İstanbul oluyor birden.', 'Seninle bir yağmur başlıyor iplik iplik, Bir güzellik doğuyor yüreğime şiirden. Martılar konuyor omuzlarıma, Gözlerin İstanbul oluyor birden...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozlerin-istanbul-oluyor-birden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-i-nci-ozcan-pqge8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tenim toprak olsada ruhum seni sevecek

İnan mahşerde bile gösyaşım dinmeyecek

Gözümü sende açtım başkasını göremem

İnan senden başkasına ben sevgilim diyemem', 'Tenim toprak olsada ruhum seni sevecek İnan mahşerde bile gösyaşım dinmeyecek Gözümü sende açtım başkasını göremem İnan senden başkasına ben...', ARRAY['Türk Edebiyatı','Şiir','İnci Özcan']::text[], 8.5, '{"poet":"İnci Özcan","poet_slug":"i-nci-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Bittiği Yerde', 'denizin-bittigi-yerde-alber-sarapcioglu-7vfer', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizin bittiği yerde

Ak bir kısrak yelesi gibi

O bembeyaz dalgalar

Dövüyorsa yosunlu kayaları

Tıpkı acıların

Tıpkı özlemlerin

Yüreğini dövdüğü gibi

Kıyasıya

Denizin bittiği yerde

Altın saçlı güneş

Altına boyuyorsa

Bir zamanlar

Kumsala savurduğumuz

Serseri ayak izlerimizi

Aldırışsız

Denizin bittiği yerde

İnce yakamozlar

Kırılıyorsa sahilde unufak

Kırılıyorsa

O en güzel anılar

Göz uçlarında 

Damla damla

Denizin bittiği yerde

Yemyeşil bir ağaç gölgesinde

Uyukluyorsa yalnızlığın

Yanıbaşında

Ağlıyorsa hasretin

Saklayacak

Sevdamdan başka

Hiç bir şeyin 

Kalmamışsa

Denizin bittiği yerde

Ben başlarım

(27/3/2001 İstanbul)', 'Denizin bittiği yerde Ak bir kısrak yelesi gibi O bembeyaz dalgalar Dövüyorsa yosunlu kayaları Tıpkı acıların Tıpkı özlemlerin Yüreğini dövd...', ARRAY['Türk Edebiyatı','Şiir','Alber Şarapçıoğlu']::text[], 8.5, '{"poet":"Alber Şarapçıoğlu","poet_slug":"alber-sarapcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/denizin-bittigi-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Parçam', 'ay-parcam-alber-sarapcioglu-b3239', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay vururdu saçlarına

Işıklanırdı siluetin

Yüzünün bir yarısı ayda

Bir yarısı karanlık.

Gözlerin parlardı

Tukuazın yeşilinde

Mavileri kıskandırıp.

Aya dönerdin

Şöyle bir bakardın

Gözlerin daha ışıklı...

Sarhoş olurdum ışığının seliyle

Öpmeye çekinirdim ay yarısı tenini

Dudaklarım örseler diye...

Ölsem derdim kollarında

Işıklara boğulup

Ölümü bile farketmeden...', 'Ay vururdu saçlarına Işıklanırdı siluetin Yüzünün bir yarısı ayda Bir yarısı karanlık. Gözlerin parlardı Tukuazın yeşilinde Mavileri kıskand...', ARRAY['Türk Edebiyatı','Şiir','Alber Şarapçıoğlu']::text[], 8.5, '{"poet":"Alber Şarapçıoğlu","poet_slug":"alber-sarapcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ay-parcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-alber-sarapcioglu-e3kpy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herkes ömründe en az bir kere

Yastığına sarılıp uyumuştur

Sevgilisi niyetine.

Bense her gece

Her gece

Yeter be!', 'Herkes ömründe en az bir kere Yastığına sarılıp uyumuştur Sevgilisi niyetine. Bense her gece Her gece Yeter be!...', ARRAY['Türk Edebiyatı','Şiir','Alber Şarapçıoğlu']::text[], 8.5, '{"poet":"Alber Şarapçıoğlu","poet_slug":"alber-sarapcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeter-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-aziz-altintas-bqqu8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine SEVGİ rüzgârları bekler yelkenim,

Esmesen de...

Yine SEVGİ suları bekler teknem,

Akmasan da...

Yine SEVGİ tohumları bekler bahçem,

Ekmesen de...

Yine SEVGİ yağmurları bekler gönlüm,

Yağmasan da...

SEVGİ limanıdır bu, sensiz ve sessiz ,

Gelsen de, gelmesen de...', 'Yine SEVGİ rüzgârları bekler yelkenim, Esmesen de... Yine SEVGİ suları bekler teknem, Akmasan da... Yine SEVGİ tohumları bekler bahçem, Ekme...', ARRAY['Türk Edebiyatı','Şiir','Aziz Altıntaş']::text[], 8.5, '{"poet":"Aziz Altıntaş","poet_slug":"aziz-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık Macerası', 'yanlizlik-macerasi-aziz-altintas-dwtl4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle yalnız kaldım ki hayatımda

Kimi gün öldüm kimi gün ilah oldum

Çok zaman annemin dizlerine hasret

Koydum başımı kendi dizlerime

Doya doya ağladım

Paylaşırsa dost paylaşırmış

İnsanın derdini sevincini

Dost ümidiyle ortalığa düşmeye gör

Hangi kapıyı çalsan kimseler yok

Hangi omuza dokunsam yabancı çıkar

Aşık mı olmadım taparcasına

Bir Mecnun geçti o çöllerden bir de ben

Diz mi çektirmedim alemde Kerem gibi

Ferhat gibi gürz mü sallamadım dağlara

Ne Leyla yar oldu bana ne Aslı ne Şirin

O gün bugün sırtımı kendim sıvazlıyorum

Sabahları sokağa çıkmadan evvel

Cesaret şairim, cesaret

Kendi saçlarımı okşuyorum geceleri

Sevgilimin saçları niyetine.', 'Öyle yalnız kaldım ki hayatımda Kimi gün öldüm kimi gün ilah oldum Çok zaman annemin dizlerine hasret Koydum başımı kendi dizlerime Doya doy...', ARRAY['Türk Edebiyatı','Şiir','Aziz Altıntaş']::text[], 8.5, '{"poet":"Aziz Altıntaş","poet_slug":"aziz-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yanlizlik-macerasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim', 'i-brahim-aziz-altintas-hlwf9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İbrâhim, içimdeki putları devir elindeki baltayla

Kırılan putların yerine yenilerini koyan kim?

Güneş buzdan evimi yıktı, koca buzlar düştü

Putların boyunları kırıldı. 

İbrâhim, güneşi evime sokan kim?

Asma bahçelerinde dolaşan güzelleri 

bühtannaşır put yaptı

Ben ki, zamansız bahçeleri kucakladım,

güzeller bende kaldı.

İbrâhim, gönlümü put sanıp kıran kim?', 'İbrâhim, içimdeki putları devir elindeki baltayla Kırılan putların yerine yenilerini koyan kim? Güneş buzdan evimi yıktı, koca buzlar düştü ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Altıntaş']::text[], 8.5, '{"poet":"Aziz Altıntaş","poet_slug":"aziz-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ibrahim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O yağmur', 'o-yagmur-zubeyde-basaran-goi82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Damlaların  iz bırakıyor  gözlerimde

Masadım yere değil  benliğime düşmende

Akışın derin yara, vehmin ecel teceli

Varlığın yaradanın  varlığı, haklığı, sade esenliği

O  ki  seni yarattı  bizler olalım diye 

O ki gönül  gözü  vermiş  hakkını farkedelim  diye

İşte  yine düştüm tenime sen varlığın habercisisin  değil mi?

Dönüp  keskin  ve sade bakışlarıyla

Ve  temiz

İşte o yağmurum... 

Farkettin öyle mi?', 'Damlaların  iz bırakıyor  gözlerimde Masadım yere değil  benliğime düşmende Akışın derin yara, vehmin ecel teceli Varlığın yaradanın  varlığ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/o-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebileye', 'sebileye-sair-sahi-hwdgs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'S oğuk gecelerin sisli sabahlarında bir türkü tadıydı

     ve sıcak bir kahvenin dumanındaydın sen.

E lbetlerle başlayan ve bitmiyen bir gurbet

    her biten gün yeni bir umut senin için.

B uluştuğumuz günler tek tesellim buralarda,avuntu yani

    ve ben geçen her gün biraz daha tutkunum sana

İ llaki sen olmalıymışsın en baştan

    seni tanıyabilmek ve seni sevmek için

L oşlukta kasvet buğusunu yırtan en aydınlıksın

    hiçbir şeyimken her şeyim oluverdin

E lvadasız yaşamak istiyorum bu aşkı

    ve şuna inan ki seni çok seviyorum...', 'S oğuk gecelerin sisli sabahlarında bir türkü tadıydı      ve sıcak bir kahvenin dumanındaydın sen. E lbetlerle başlayan ve bitmiyen bir gur...', ARRAY['Türk Edebiyatı','Şiir','Şair Sahi']::text[], 8.5, '{"poet":"Şair Sahi","poet_slug":"sair-sahi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sebileye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'saebileye 2', 'saebileye-2-sair-sahi-vky8w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'S evgi sürgünündeyim,kanayan aşk ve yanlızlık

    hücrelerinde tek işkence sana mecburiyet.

E klenen hasrete birde sarılan güzel göz tütünü

     her çekişimde saçlarının kokusu var.

B andırılarak yenen katıksız bir ekmek

     nemli  duvarların güneşe hasretliğinde yine sen.

İ nadına yaşıyorum

     yarınlarda  sen olacaksın çünkü.

L ale saflığı bürünecek mavilere

     papatya ahenği olacak geceler.

E n sonunda diyorum en sonunda 

    sensizlik yaraları kapanacak.

E lde kalansa güneş aydınlığında yürüyeceğimiz

    mutlu yarınlarda beni unutma......', 'S evgi sürgünündeyim,kanayan aşk ve yanlızlık     hücrelerinde tek işkence sana mecburiyet. E klenen hasrete birde sarılan güzel göz tütünü ...', ARRAY['Türk Edebiyatı','Şiir','Şair Sahi']::text[], 8.5, '{"poet":"Şair Sahi","poet_slug":"sair-sahi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/saebileye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'deli gibi aşık olsamda', 'deli-gibi-asik-olsamda-sair-sahi-qtf2e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deli gibi aşık olsada güle

Kim acır çöllere öten bülbüle

Bir gün alev alev yanıpta küle

Dönmek istiyorum dönemiyorum

Hıçkıra hıçkıra ağlamaktansa

Başıma karalar bağlamaktansa

Bu yüreğimi her gün dağlamaktansa

Ölmek istiyorum ölemiyorum....', 'Deli gibi aşık olsada güle Kim acır çöllere öten bülbüle Bir gün alev alev yanıpta küle Dönmek istiyorum dönemiyorum Hıçkıra hıçkıra ağlamak...', ARRAY['Türk Edebiyatı','Şiir','Şair Sahi']::text[], 8.5, '{"poet":"Şair Sahi","poet_slug":"sair-sahi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-gibi-asik-olsamda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırıklar', 'hickiriklar-sair-sahi-aclj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saatler bitmiyor yapa yanlızım  

Gülmek istiyorum gülemiyorum

Sensiz olmak mıdır hep alın yazım

Bilmek istiyorum bilemiyorum

Esirgedin nazlı hilal kaşını

Harap ettin çiçek kokan başını

Yüreğime akan gözüm yaşını

Silmek istiyorum silemiyorum

Sanki her şey efsaneydi masaldı

Ayrılık ruhumu elimden aldı

Gözlerim yollara takılıp kaldı

Gelmek istiyorum gelemiyorum

Göğüs germek için acılarıma

Titreyişlerime sancılarıma

Seni bir kez olsun avuçlarıma 

Almak istiyorum alamıyorum

Saçılan bir köpük olmak dilinde

Boğulmak sarının ince telimde

Sır gibi sonsuza değin kalbinde

Kalmak istiyorum kalamıyorum

Unutuyor beni sırlı gözlerin

İçime bir yara işliyor derin

Dudakların kulakların ellerin 

Olmak istiyorum olamıyorum

Seni sevmek için yaptıklarıma 

Bakmak istiyorum bakamıyorum

Senin bu yaptığına hıçkırarak

Ağlamak istiyorum ağlayamıyorum', 'Saatler bitmiyor yapa yanlızım   Gülmek istiyorum gülemiyorum Sensiz olmak mıdır hep alın yazım Bilmek istiyorum bilemiyorum Esirgedin nazlı...', ARRAY['Türk Edebiyatı','Şiir','Şair Sahi']::text[], 8.5, '{"poet":"Şair Sahi","poet_slug":"sair-sahi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hickiriklar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüren Sevda', 'olduren-sevda-ozcan-nevres-dwqqv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yol boyu çeşmesinde durup su içeyim dedim

Kitabesi takılınca gözüme irkildim

Su geçmez oldu boğazımdan, yandı yüreğim

Nasıl bir sevdaymış bu benim bilmediğim

“Sevda pınarından kana kana içmeden,

Murat köprüsünden gelip geçmeden

Yaşı henüz on sekizine basmadan

Ecel alıp götürdü onu, genç yaşına bakmadan

Ne gelir elden, yazgısını kötü yazmışsa yaradan

Yörük kızı Hesna’nın hayratıdır bu su

Ey yabancı, bilmesen de Hesna kızın öyküsünü

Kana kana iç, eksik etme hayır duasını”

Çoban sürünce koyunlarını çeşmeye

Koşuşup sıralandılar yalaktan su içmeye

Vardım çobanın yanına,

Sordum, tanır mıydın Hesna kızı diye

Ağlamaklı oldu, sulandı gözleri

Tanırdım dedi, kim tanımazdı ki o güzeli

Bir içim suydu o, aha bu sudan berraktı teni

Köyümüz görmemişti hiç böylesine güzeli

Bir delikanlıya tutulmuştu yüreği

Söz kesmişlerdi biri birlerine töremizin gereği

Hele bir askerliğini bitirsin, tez evleneceklerdi.

Acı haber gelince sözlün şehit oldu diye

Yemeden  içmeden kesildi, döndü bir deliye

Ahlarla vahlarla geçen günler uzun sürmedi

Yıllar oldu onu yitireli ama, acısı hala dinmedi

Bu çeşmeden her su içen, sormadan edemedi

Kim bu kız, neden çok gençken yitirildi

Anlatırım her sorana, kanasa da yüreğim

Anlat be çoban, yüreğindeki acıya aldırma

Anlat ki herkes öğrensin candan nasıl sevilirmiş

Varsın yürekler sızlasın, canlar acısın

Dileğim, ayrılıkların olduğu sevdalar hiç yaşanmasın 

				Özcan NEVRES', 'Yol boyu çeşmesinde durup su içeyim dedim Kitabesi takılınca gözüme irkildim Su geçmez oldu boğazımdan, yandı yüreğim Nasıl bir sevdaymış bu...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olduren-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar Diken Diken', 'anilar-diken-diken-ozcan-nevres-ijx6n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anılar diken diken tırmalar yüreğimi

Ve ben Mutsuzlukla altında sabahladığım

Deniz kenarında ki söğüt ağacını

Vefasızlığınla anımsarım bir bir

Bir hıçkırık düğümlenir boğazımda

Her şeyden kaçmak isterim

Yaşamaktan bile

Sahildeki sandalımı bilirsin

Adı Nalan

Yeşil boyalı

Sensizlikten kurtulmak için

Lacivertlerin en koyu olduğu yere giderim

Kürekler gıcır gıcır öter

Su serpintileriyle ıslanırım

Körfezin en karanlık olduğu yerde

Başı boş bıraktığım sandalımda

Dalgaların şırıltıları arasında

Yine

Seni düşünürüm

Ve sensizliğime

Uzun uzun ağlarım

				Özcan NEVRES', 'Anılar diken diken tırmalar yüreğimi Ve ben Mutsuzlukla altında sabahladığım Deniz kenarında ki söğüt ağacını Vefasızlığınla anımsarım bir b...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anilar-diken-diken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir De Size Bir Haber', 'bir-de-size-bir-haber-sair-baraka-9jnf9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir de size bir haber

Falanca sivilize ülkede

Kanun dermiş ki

Bir evlilik düşer

Eğer üçyıl boyunca

Beden bedenden 

Ayrı kalırsa

Kadının bedeni

Erkeğin bedenine

Değmezse göçer gider

Evde evlilikte

Çok ilginç değilmi

Bakın şimdi haberlere

Kadının biri

Notere mektup bırakmış

Demişki mektupta

Delildir yargıda

Koymuş günün anını

Demiş başlar

Cürüm tespit süresi

Boşanma gerisayımı

İlk geceden itibaren

Sağ kalçasına

Hergün yeni bir

Nebat adı yazmış

Bunuda mektupta

İlan etmiş kaydola

Gelmiş çatmış şafak

Başvurmuş adli sicile

Avva idi fert olmuş

Kayda geçile

Demişler varmı delilin

Demiş yeddi eminde

Başlarını sallayıp

Birde adama soralım

Demiş sual etmişler

Doğrumudur demişler

Hey yoksa sen

Müktedir değilmisin

Arınmı var 

hicrandamısın

yalan der valla

demiş inkar eylemiş

fert olan arkişi

ispatım var demiş

sorarım dostuma

er kişi kocama

efendime ağama

bilirmi ki ben en son

ne zaman elma yedim

adam kişi gamsız 

çaresiz kalacak damsız

kısar sesini soy tarı

hergece saat sekizde

duadan sonra

bizde adettendir

arlık saflık tandır

şaşalamış kalmışlar

düpedüz yalan söylüyor

edebsiz namsız

diye diye sormuşlar

başka meyva başka nebat 

yemediniz mi siz onca zaman

bir halt bir düşün

ne acıdırki biz biliyoruz

senin yalan söylediğini

elimizde kanıt var

gösterirki sen hiç

meyvayı evde yememişsin

karıştırmışsın hali

evin sandığın mutlu yeri

evli evin sandın

evli evinde kaldı

bizde seni fert leş meye

karar verdik biline

verdik

herkesce biline

verdic verdik

sivil kurumcu bir hatun

demişci düzmece bu

hepsi bunların hilece

aldatmaca hukuku

bir diğer gözlemci

nerde adamın hakları

bir gümbürtü 

bir tantana

bir o yana bir bu yana

bilirkişi karar verdi

leylanın sağ kalçasında

mevyalı bir elyazması

yonca gonca ander var 

baktık gördük ki

her bir günde 

bir elma var

her birinde 

bir başka cins

henüz yenilmemiş

demekki uğramamış 

seninki senin bedenine

meyva kasene

terrü balına

mahv şarabına

git sun bir başka

elverene

evlenine ha şa

evreni huşa

eltut anına

yan ında taşı yana

o ne tad dırki

ne gam sana herfert

gelir de abad olursun

bahş olursun bir kavme

işte böyle devam ediyor

illaki kadın elyazması

kalça takvimini

yeddi emine kaydetti

kaybedersem sen öde

yanlış karar verdinse

sig ortağı istemiş

şimdi de miyam mide

hatır atlarını yazıyor

küllü aleme

yeni fertte halini

anlatan dramalarda

seri seri

işte gördünüzmü

dostlarım tek bir incelik

has anlamda

bedenden bedene

kaç kişiyi ihya etti

işte bu demo krasiyle

aranızı yakınlaştırır

evli evine

köylü köyüne

kavuşturur

bir tek kelime

bir tek beden

sevgiyi hırçınlaştırır

işte bu kardeşlerim

hukukun cilvesi

şeytanı bir hilede

taşıtmasıdır iyiye

onu celbetmeye

mert ebe

mertebe halliyle

işte bu kardeşlerim

kötüden hayıra çıkmak

hafiflemek

demlenmek

eve ben leşme

ebe ev eyleşme

evcim leşme

fertsel fertsel

gerisi baha ne

bana ne

ya hu ya hu

deyu deyu

ka nu na

ya hak ka

ya hasa 

ya hukka

ya hut

ya hu da

ves vese

lam ev la

vela kuv ved

hu zim

hu ha

ya şa

ya rab

sizigidisizidüzücülerime.......

barakadan', 'Bir de size bir haber Falanca sivilize ülkede Kanun dermiş ki Bir evlilik düşer Eğer üçyıl boyunca Beden bedenden  Ayrı kalırsa Kadının bede...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":172,"source_url":"https://www.antoloji.com/bir-de-size-bir-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadasım SAHIN''e', 'arkadasim-sahin-e-kutlu-turk-jli4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayalleri olan bir insan vardı,

bunları paylastıgı biriside vardı,

ama ruyalarında hep yalnızdı, 

kimsesi yoktu onun duyguları dısında,

ben farklımıyım diye dusunurken hayatın anlamsızlıgını bulmak istercesine dusunur fakat kendi var olusu dısında anlamları arardı,

hayalleri olan bir insan vardı,

gelecek icin planları olan bir insan vardı,

inandıgı arkadasları vardı,

kendini arkadasının yerine koyar onun icin dusunur ve yeni fırsatlar olusturma cabası icinde kaybolurduç

hayalleri olan bir insan vardı,

artık arkadasları olmadıgını dusunen bir insan oldu o,

sevenlerinin kim oldugunu arama telasına girdi,

onları arama cabasındayken kendini sevip sevmedigini dusunmeye basladı,

dusunceler icinde yuzerken hayalleri olan baska insanları gordu ve onların bos telaslarını.

hayalleri olan bir insan vardı,

artık onun hayalleri yok !

artık onun arkadası da yok !

bosuna aglayan ve anlamsızlıklar icinde kaybolan bir insan dısında kimse yok ARTIK !', 'hayalleri olan bir insan vardı, bunları paylastıgı biriside vardı, ama ruyalarında hep yalnızdı,  kimsesi yoktu onun duyguları dısında, ben ...', ARRAY['Türk Edebiyatı','Şiir','Kutlu Türk']::text[], 8.5, '{"poet":"Kutlu Türk","poet_slug":"kutlu-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/arkadasim-sahin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-osman-pelit-e99rz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümün sahili bomboş

Ne bir martı

Uğrar olmuş

Nede sevginin tek hecesi

Doğmayacak güneşin 

Bekçiliğini vermişler bana

Ne gelir elden 

Seni beklemekten başka.', 'Gönlümün sahili bomboş Ne bir martı Uğrar olmuş Nede sevginin tek hecesi Doğmayacak güneşin  Bekçiliğini vermişler bana Ne gelir elden  Seni...', ARRAY['Türk Edebiyatı','Şiir','Osman Pelit']::text[], 8.5, '{"poet":"Osman Pelit","poet_slug":"osman-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rezidüel Volüm', 'reziduel-volum-gaffar-karadogan-ogs64', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derin bir inspirasyon ile

Hapsettik, rezidüel kapasite içine

Günün kahrolası kederini

Benimlesiniz bundan böyle

Zorlu ekspirasyonlar bile

Sizi çıkaramayacak içimden

Ömrümün binikiyüz mililitresi', 'Derin bir inspirasyon ile Hapsettik, rezidüel kapasite içine Günün kahrolası kederini Benimlesiniz bundan böyle Zorlu ekspirasyonlar bile Si...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/reziduel-volum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Travay', 'travay-gaffar-karadogan-1f7wt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kulak verirken

Çocuğun kalp seslerine beş dakikada bir

Başımızı kaşımaya vaktimiz vardı

Birde hastanın bağırışlarını dinlemeye

Fondaki müzik ilgilendirmiyordu bizi

Hey fetus! ne sen sıkıntıya gir

Ne de intörnü sıkıntıya sok

Bak annen doğumun birinci evresini yaşıyor

Ölmek istiyorum diye bağırarak

Bu vakitlerde

Dünya soğuk, insanlar soğuk

Soğuk savaş var dünyada

Ama fetus yine de sen

Gel artık', 'Kulak verirken Çocuğun kalp seslerine beş dakikada bir Başımızı kaşımaya vaktimiz vardı Birde hastanın bağırışlarını dinlemeye Fondaki müzik...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/travay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pratisyen', 'pratisyen-gaffar-karadogan-k2j6s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün olur alır başımı giderim

Fadimenin düğününde halay çekmeye

Pratisyen olarak

Kahraman olamam belki

Ama taht kurulacak gönüller beni bekliyor

İstersem şair olurum, belkide ressam

Multipotent stem-cell misaliyim ben

Ben; kırsal kesimin hekimi

Ben; yüreğinde yükselmek

Bir basamak daha yükselmek

Hırsı olmayanların hekimi', 'Gün olur alır başımı giderim Fadimenin düğününde halay çekmeye Pratisyen olarak Kahraman olamam belki Ama taht kurulacak gönüller beni bekli...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/pratisyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-gaffar-karadogan-bw6q1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tası, tarağı toplayıp

Terk ediyoruz kıyı şehrini

Tas, tarak birde anıları almalıyız yanımıza

Geride iyi dilekler bırakarak

Yaşasın arkadaşlar

Östrojen ve androjen replasmanı alacak kadar', 'Tası, tarağı toplayıp Terk ediyoruz kıyı şehrini Tas, tarak birde anıları almalıyız yanımıza Geride iyi dilekler bırakarak Yaşasın arkadaşla...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayrilik-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resüsitasyon', 'resusitasyon-gaffar-karadogan-u09cn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dahiliyeciyiz biz

Kronik hastalıkların kronik umudu

Usulüne uygun resüsitasyon ekibinin aktörü

Bir yol tutturmuş her aktör

Romaya doğru

Beğenmez bir diğer yolu

Romada pupiller fiks, pupiller dilate

Sözler bitmiş 

Herşeyi anlatan düz bir EKG', 'Dahiliyeciyiz biz Kronik hastalıkların kronik umudu Usulüne uygun resüsitasyon ekibinin aktörü Bir yol tutturmuş her aktör Romaya doğru Beğe...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/resusitasyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lösemili Ahmet''e', 'losemili-ahmet-e-gaffar-karadogan-tsfen', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Metotreksat siyah saçları çok görmüştü Ahmet''e

Ama Ahmet''in gözleri

İki çakmak taşı gibi pırıl pırıl

Umut dolu

Ben feleğin bu çarkına

Ne çomaklar, ne blastlar sokarım diyor

Normal zenginlikteki kemik iliği ile

Mikroskop başında öğreniyoruz

Zenginliğinde normalinin olduğunu

Ve yetmediğini

Beş yıllık yaşama yüzde biçilmemesine

Ahmet''in beş yıllık yaşam yüzdesi var

Bizim yaşamaya vaktimiz yok', 'Metotreksat siyah saçları çok görmüştü Ahmet''e Ama Ahmet''in gözleri İki çakmak taşı gibi pırıl pırıl Umut dolu Ben feleğin bu çarkına Ne çom...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/losemili-ahmet-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman O''na Yıl Yazmamış...', 'zaman-o-na-yil-yazmamis-husrev-hatemi-4edyc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman O''na yıl yazmamış,silmilş

Ne zerafet,ne eda eksilmiş

Demek,Zaman sandığım kadar zalim

Ve güzelden anlamaz değilmiş', 'Zaman O''na yıl yazmamış,silmilş Ne zerafet,ne eda eksilmiş Demek,Zaman sandığım kadar zalim Ve güzelden anlamaz değilmiş...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-o-na-yil-yazmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilen Hiç Ölümlü Olmamalı', 'sevilen-hic-olumlu-olmamali-husrev-hatemi-05g0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevilen hiç ölümlü olmamalı

Kader ona zulümlü olmamalı

Zaman, O''na dokunmadan geçiver

Kimse ondan alımlı olmamalı', 'Sevilen hiç ölümlü olmamalı Kader ona zulümlü olmamalı Zaman, O''na dokunmadan geçiver Kimse ondan alımlı olmamalı...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevilen-hic-olumlu-olmamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Tekne', 'kucuk-tekne-engin-ertug-r3n13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açıldım küçük teknemle okyanuslara

Sapıyorum uçsuz bucaksız yollara

Bitmiyor hiç, kara için gözlem

Küçük teknemin adı hep özlem', 'Açıldım küçük teknemle okyanuslara Sapıyorum uçsuz bucaksız yollara Bitmiyor hiç, kara için gözlem Küçük teknemin adı hep özlem...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kucuk-tekne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanto', 'kanto-cemal-sureya-5os8b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben nerde bir çift göz gördümse

Tuttum onu güzelce sana tamamladım

Sen binlerce yaşayasın diye yaptım bunu

Bir bunun için yaptım

			-Garson bira getir

			  Garsonun a
..........
..........', 'Ben nerde bir çift göz gördümse Tuttum onu güzelce sana tamamladım Sen binlerce yaşayasın diye yaptım bunu Bir bunun için yaptım 			-Garson ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kanto-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelleme', 'guzelleme-cemal-sureya-tsevt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak bunlar ellerin senin bunlar ayakların

Bunlar o kadar güzel ki artık o kadar olur

Bunlar da saçların işte akşamdan çözülü

Bak bu sensin çocuğum enine boyuna

Bu da yatak olduğuna göre altımızdaki

Sabaha kadar koynumda yatmışsın

Bak bende yal
..........
..........', 'Bak bunlar ellerin senin bunlar ayakların Bunlar o kadar güzel ki artık o kadar olur Bunlar da saçların işte akşamdan çözülü Bak bu sensin ç...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guzelleme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afrika', 'afrika-cemal-sureya-0sk2q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Afrika dediğin bir garip kıta

El bilir
