INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önceleyin', 'onceleyin-cemal-sureya-iduu4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce bir ellerin var

Yalnızlığımla benim aramda

Sonra birden kapılar açılıverdi

ağzına ka
..........
..........', 'Önce bir ellerin var Yalnızlığımla benim aramda Sonra birden kapılar açılıverdi ağzına ka .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/onceleyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülke', 'ulke-cemal-sureya-65cdo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saat Çini vurdu birden: pirinççç

Ben gittim bembeyaz uykusuzluktan

Kasketimi eğip üstüne acılarımın

Sen yüzüne sürgün olduğum kadın

Karanlık her sokaktaydın gizli her köşedeydin

Bir çocuk boyuna bir suyu söylerdi. Mavi.

Bir takım genç anneleri uzatırdı bir keman

Sen tutar kendini incecik sevdirirdin

Bir umuttun bir misillemeydin yalnızlığa

Yalnız aşkı vardır aşkı olanın

Ve kaybetmek daha güç bulamamaktan

Sen yüzüne sürgün olduğum kadın

Kardeşim olan gözlerini unutamadım

Çocuğum olan alnını sevgilim olan ağzını

Dostum olan ellerini unutamadım

Karım olan karnını ve önlerini

Orospum olan yanlarını ve arkalarını

İşte bütün bunlarını bunlarını bunlar
..........
..........', 'Saat Çini vurdu birden: pirinççç Ben gittim bembeyaz uykusuzluktan Kasketimi eğip üstüne acılarımın Sen yüzüne sürgün olduğum kadın Karanlık...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ulke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-mustafa-gokgoz-ltovi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gideli kaç yıl oldu, inan saymaktan usandım.

Yaprak yaprak dökülen o takvimlerde hal kalmadı

Rüyalara senle daldım, hep hayalinle uyandım

Senden bir haber umduğum fincanlarda fal kalmadı

Varlığının özlemini hep taşıdım bunca zaman

Döneceğin o yolları yar diye kokladım her an

Kelimeler aciz kaldı derdimi dökmeye inan

Feleğe hesap soracak fikrimde sual kalmadı

Gece gündüz hasretinle yıllar yılı nasıl yandım

Hatıralarla baş başa göz yaşlarımda ıslandım

Senden ayrı bu ellerde ben kimsesiz; yetim kaldım

Seni arayıp durduğum yollarda mecal kalmadı

Yokluğun derin yaradır sabır beziyle sardığım

Duaların hesabı yok gelsin diye yakardığım

Ömrün Artık son demleri musalla taşı vardığım

Artık dönsen de faydasız vuslata mahal kalmadı', 'Sen gideli kaç yıl oldu, inan saymaktan usandım. Yaprak yaprak dökülen o takvimlerde hal kalmadı Rüyalara senle daldım, hep hayalinle uyandı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerekmez', 'gerekmez-mustafa-gokgoz-hdtjx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlar erken yağdı diye saçlara,

Bahardan ümidi kesmek gerekmez

Gıptayla bakıp da gür ağaçlara

Kadere talihe küsmek gerekmez

Yok var olur bir gün beklemek gerek

Tüm geceler gündüz olur giderek,

Savrulan yıllara sitem ederek,

Deli rüzgar gibi esmek gerekmez.

Fırtınalar diner elbet gönülde,

Bülbüle haz verir, solan bir gül de.,

Vefalı kalmadı diyerek elde,

Kapanan yarayı deşmek gerekmez.

Sulanan toprağa haset besleyip,

Yetişen buğdaya murdardır deyip,

Namerde el açıp aman dileyip,

Gururu ayağa sermek gerekmez.

Gözlerin yaşlarla dolsa da hatta,

Bahar gelir elbet, belki şubatta,

Ufacık ta olsa her maslahatta,

Gökgöz’ü incitip kırmak gerekmez', 'Karlar erken yağdı diye saçlara, Bahardan ümidi kesmek gerekmez Gıptayla bakıp da gür ağaçlara Kadere talihe küsmek gerekmez Yok var olur bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gerekmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-mustafa-gokgoz-oy0yc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hazanı görmez tomurcuk, solar yazın son demin de,

Her rüyadan uyanılır, her günün vardır batımı,

Devran öyle kurulmuş ki şu insanlık aleminde

Ömre mihenk taşı yoktur, belki bir adım atımı.', 'Hazanı görmez tomurcuk, solar yazın son demin de, Her rüyadan uyanılır, her günün vardır batımı, Devran öyle kurulmuş ki şu insanlık alemind...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayata-dair-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bundan Gayrı', 'bundan-gayri-mustafa-gokgoz-y20aj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Füsun kayboldu artık, cemre bu yıl düşmeyecek

Hüzünlenmek hakkın gönül, var git ağla bundan gayrı.

Umutlar son demde soldu, beklemek boş dönmeyecek,

Yolda kalan gözlerini, var git dağla bundan gayrı.

Arılara haram artık, çiçekten damlayan ballar,

Sevdadan eser kalmadı, sarmıyor açılan kollar,

Zemherirde karla doldu, yare çıkan bütün yollar,

Dumanlı dağlara doğru, var git çağla bundan gayrı.

Güneş doğmayacak belki, yarın hayatın son günü,

Kim bilir yenilen lokma, belki ahretin öğünü,

Hiçbir zaman olmayacak gülle, bülbülün düğünü

Sende kendi urganını var git yağla bundan gayrı', 'Füsun kayboldu artık, cemre bu yıl düşmeyecek Hüzünlenmek hakkın gönül, var git ağla bundan gayrı. Umutlar son demde soldu, beklemek boş dön...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bundan-gayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüsnü Hat', 'husnu-hat-mustafa-gokgoz-sqbbl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünden evvel yarını düşünmekti tek suçumuz

Bir gülün peşine düşüp, gitmekti kabahat

Bahar ile birlikte bitince son umudumuz

Anladık ki beyhude yaşanmazmış bu hayat

Sevgi dedik, aşk dedik; ömür verdik bir ana

Boşaymış geç anladık, kanmışız bir yalana

Sevilenler vefasız, bakmaz darda kalana,

Şurasına inandım, yok bu dünyada rahat

Yar dedik, vefasız; halden anlamaz kula,

Yanlış mevsimde çıktık, sevda denilen yola

Hayat derler bu zor, meşakkatli okula.

Alnımıza yazılan değildir ki hüsnü hat', 'Dünden evvel yarını düşünmekti tek suçumuz Bir gülün peşine düşüp, gitmekti kabahat Bahar ile birlikte bitince son umudumuz Anladık ki beyhu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/husnu-hat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi', 'birisi-mustafa-gokgoz-c0ucs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep harcandı o,

Doğduğundan beri.

Annesi o küçükken yine çocuk yaptı,

Babası o evdeyken başkalarına oyuncaklar aldı.

Öğretmenleri harcadı okulda,

Arkadaşları oyunda harcadı,

Ortaokulda lisede..

Bir kız sevmişti,

Kız başkası için harcadı onu.

Hep böyle oldu ölünceye kadar,

Cepten cebe dolaştı...

Ve bir gün harcanamaz olunca

Tanrı  tarafından,

Tedavülden kaldırıldı...

1989, Kayseri', 'Hep harcandı o, Doğduğundan beri. Annesi o küçükken yine çocuk yaptı, Babası o evdeyken başkalarına oyuncaklar aldı. Öğretmenleri harcadı ok...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihan', 'nihan-mustafa-gokgoz-ef1np', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nihanları aşikar kılmayasın bu demde,

Sırrını hiç kimseye verme hüdadan hayrı,

Boşuna arayıp ta yorulma, bu alemde,

Ne ararsan bulunur derde devadan gayrı.

Medet umma kimseden, her kulu Hızır sanma.

Çölde zemzem arama merve, safa’dan gayrı.

Kederleri görmeden, neşeye hazırlanma.

Yaşanmamışı hayra , yorma rüyadan gayrı.

Ömür dediğin nedir, iki nefes arası,

Ardında bir şey kalmaz bir hoş sedadan gayrı.

Gelip çatınca kaderdeki ölüm sırası

Seni bir uğurlayan var mı saladan gayrı.

Hani arkadaşların, nerde seni sevenler

Tenine  kimse değmez, yılan çıyandan gayrı.

Senden sonra tufandı hani nerde ölenler

Giderken fayda vermez kefen parandan gayrı.', 'Nihanları aşikar kılmayasın bu demde, Sırrını hiç kimseye verme hüdadan hayrı, Boşuna arayıp ta yorulma, bu alemde, Ne ararsan bulunur derde...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nihan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta Mektuplar ( 1 )', 'bir-dosta-mektuplar-1-ozcan-nevres-ustxz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç zaman oldu sana yazmayalı

Hani bir sevgilimiz vardı paylaşamadığımız

Uğrunda nice kez küsüp darıldığımız

Onu gördüm dün çay bahçesinde

Tanıyamadım onu ilk bakıştığımızda

Kim bu demiştim tanıdık biri galiba

Dostça gülümsemesi yabancı gelmedi bana

Gülen gözlerinde geçmişi aradım

Bunca yıl sonra onu gözlerinden tanıdım

Saçlarında tek sarı tel kalmamış

Gözleri hüzünle harelenmiş

Belki inanmayacaksın ama

Eski güzelliğinden eser kalmamış

Gidip yanına oturduğumda

Seni sordu titreyen bir sesle

Görüyor musun onu dedi hasretle

Dedim mektuplaşıyoruz seyrek te olsa

Dedi yazarsan selamımı söyle çokça

Kırarmış saçlarına harelenmiş gözlerine 

Takıldı gözlerim uzun süre. 

Geçmişi yaşadım gözlerinin derinliklerinde

Yıllar nasıl da yıpratmış bu kadını

Bu muydu her gün evinin önünü arşınladığımız

O güzeller güzeli Yelda

Nasılda kapışırdık onun uğruna

Uzun uzun söyleştik geçmişimizin üstüne

Evlenmiş ama uzun sürmemiş evliliği

Seni sordu yine 

Evlendi mi mutlu mu diye

Dedim onun da gülmedi yüzü evlilikten yana

Terk edildiğinden beri darıldı tüm kadınlara

İçkiye verdi kendini 

Dertlerinden kurtulmayı umarcasına

Dedi ya sen, sen ne durumdasın

Yoksa sen de onun gibi umarsız mısın

Dedim senden başka hiç umarım olmadı ki

Özleminle yaşadım bunca yılları

Gözlerime baktı uzun uzun

Gözlerinden yaşlar süzülüyordu

Kalk dedi, kalk gidiyoruz

Çok efkarlandım, çayla dağılmaz bu efkarım

Hadi ne duruyorsun gidelim birkaç tek atalım

Madamın yerinde yarıladık geceyi

Gidelim diye kalktığımızda o ödedi hesabı

Nasılda yıkıldım anlatamam

Sarıldık biri birimize tuttuk benim evin yolunu

İleride yine yazacağım 

Bende merak ediyorum bu beraberliğin sonunu

				Özcan NEVRES', 'Kaç zaman oldu sana yazmayalı Hani bir sevgilimiz vardı paylaşamadığımız Uğrunda nice kez küsüp darıldığımız Onu gördüm dün çay bahçesinde T...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bir-dosta-mektuplar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta Mektuplar ( 2 )', 'bir-dosta-mektuplar-2-ozcan-nevres-pi194', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sitem ediyorsun be dost, 

Uzun zamandır yazmadım diye

Bilemezsin ki başıma neler geldiğini

Hani o Yelda vardı ya eski sevgili

Gelip evime kendi evi gibi postu seren

Üstelik eşimden boşandım dulum diyen

Bilirsin bizim erkeklik defterinde

Yazılı değildir jigololuk denen erdemsizlik

Emeklilik maaşı yetmez olunca

Her gün vur patlasın çal oynasın yaşamaya

Sattım babadan kalma tarlayı da

Kalaycı kumuydu, uyuzdu, verimsizdi ama

Yine de gitti iyi sayılacak paraya 

Takriri verip koyunca parayı cebe 

Soluğu aldım Kuyumcu Yücel’de

Beş burma, beşte beşi bir yerde koydum cebe

Götürüp serdim Yelda’nın önüne 

Ne sevindi, ne sevindi bilemezsin.

Bir de imam nikahı kıyalım dedim

Ne gereği var dedi

Biri birimizi sevmemiz yetmez mi delicesine

 Kalan parayı da koydum yüklükte bir yere

Ertesi gün evden çıktım alış verişe

Döndüğümde Yelda yoktu anlamadım niye. 

Aklıma yüklükteki para geldi

Baktım para yerinde mi diye

Bizim parada uçmuş Yelda’yla birlikte

Savcılığa baş vurdum dolandırıldım diye

Şimdilerde ülke kazan ben kepçe

Yelda’yı arıyorum ama yok çare

Gazetedeki haber dikkatimi çekti

Tam benim gibi başka kelekler de varmış 

Diyecektim ki...

Meğer resimdeki bizim Yelda’ymış

Kocasıyla birlikte bekar ihtiyarlara

Evlilik tezgahı kurarmış

Gittim buldum o iki rezili

Aman dediler şikayetçi olma

Vereceğiz senden tüm aldıklarımızı

İki bilezik iki de beşi bir yerde verdiler

Aman sıkıştırma fırsat ver bize

Yeni bir   kelek var tezgahımızda

Hele onu bir kelekle yelim

Senden ne aldıysak hepsini bil cebinde

Günlerdir ne gelen var ne giden

Yeni kelek bendim anlaşılan

Ders olsun sana da başıma gelenler

Bakma kusuruma yazmakta gecikirsem yine

				Özcan NEVRES', 'Yine sitem ediyorsun be dost,  Uzun zamandır yazmadım diye Bilemezsin ki başıma neler geldiğini Hani o Yelda vardı ya eski sevgili Gelip evi...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bir-dosta-mektuplar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç değil', 'gec-degil-riza-aslan-r6jih', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hiç bir şey için geç değildi aslında.

ne kaçan bir fırsat vardı orta da,

ne de ,olması istenilen bir durum.

olay, aslında bir beklenti sadece

olay, gerçekleşmeyecek bir hayal.

olay, bir başlangıç isteği aslında

- başlanılamayan-

28-03-2001', 'hiç bir şey için geç değildi aslında. ne kaçan bir fırsat vardı orta da, ne de ,olması istenilen bir durum. olay, aslında bir beklenti sadec...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gec-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam Üstüdür', 'bir-aksam-ustudur-ahmed-arif-c3qkk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir akşam üstüdür şarabî 

Bahçeler ve dağlar üzre hükümran; 

Tam dünyayı dolaşmak saatindesin. 

Ay ışığı su içer birazdan. 

Kızarmış kalçalarını çanlar 

Alabildiğine vurur. 

Sen çocuk tulumunda 

Matbaa mürekkebi 

Rüsva olmuş ellerinin emeği, 

Manşetlerde kilometre kilometre yalan 

Sallanır durur. 

Bir akşam üstüdür katil, muhteşem 

Alıp götürmüşler dost dediğini 

Almış rüzgârlar içini, 

Ümide benzer, sevdaya benzer... 

Soğuk bir namludur kör ve pusuda 

Ense kökünde zulüm, 

Ve sermiş cânım sofrasını dört başı mâmur 

Burnun dibine hürriyet. 

Seviyorum mümkün değil; 

Aranızda kurşun, yasak bölge var 

Sen genç, sevdan ölünecek kadar güzel 

Kanunu yapanlar ihtiyar.', 'Bir akşam üstüdür şarabî  Bahçeler ve dağlar üzre hükümran;  Tam dünyayı dolaşmak saatindesin.  Ay ışığı su içer birazdan.  Kızarmış kalçala...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-aksam-ustudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hiç Olmadın ki', 'hic-olmadin-ki-nurten-altinok-68hna', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün de yoksun

Gelmedin... 

Bir telefon bile etmedin

Parmaklarıma düştü yine yüreğimin acısı

Gurbet kadar keskin kokuyorsa da içimdeki acı

Denek taşı yüreğime yeniliyorum

Yeniliyorum içimdeki sana

Ve oturup sil baştan

Hiçbir şey olmamışçasına

Kağıda kaleme sarılıyorum

Kırgınım yarınlara

Her seferinde bu son  olsun diyorum 

Bu seni son arayışım

Bu sana son seslenişim

Ve,  son şiirim sana yazacağım

Yeminler ediyorum

Ekmek, Kur ''an adına

Küfürlerin bini bir para

Bu son

Son

Diyorum ya...

Yapamıyorum

Yeminlerin diyeti  omzumda

Yeniden yazıyorum...

Beni bana bırakıp gidişin var ya hani

Seninle dopdolu

Hiçbir şey yaşanmamışçasına

Gözlerini unuttun bende gülüm

Hatırlasana

Ellerini unuttun avuçlarımda

Yüreğini... Yüreğimin yanında

Seni unuttun gülüm...Seni

Yanı başımda

Gidebildin mi? 

Bu kadar kolay mı sırt dönmek anılara? 

İsyanım kabarıyor da azgın dalgalar gibi

Yenik düşüyorum yalnızlığıma

İçimdeki sevgiye acıyorum

Gözlerin büyüyor gözlerimde..özlediğim

Avuçlayıp yüzünü bakasım geliyor

Öpesim geliyor

Öpesim... öpesim... sonra,

İki yanıma düşüyor  yorgun kollarım

Aynalar kırılıyor yüreğimde sızım sızım

Aynalarda çaresizliğim

Paramparçayım

Umutlarım üşüyor göz pınarlarımda

Dudaklarımda buz dağları karaya oturuyorum

Donuyorum

Yıldırımlardan bin volkan başımda

Yanıyorum

Aldırmıyorum

O gidişin var ya hani,beni bana bıraktığın

O kadar kolay  sandığın

Gözlerin bende emanet kaldı  be gülüm. Baksana

Ellerin bende kaldı

Yüreğin bende kaldı.. Alsana

Alsana...

Bu gün de yoksun

Gelmedin... 

Bir telefon bile etmedin

Parmaklarıma düştü yine yüreğimin acısı

Bilmedin....

Bilemedin....', 'Bu gün de yoksun Gelmedin...  Bir telefon bile etmedin Parmaklarıma düştü yine yüreğimin acısı Gurbet kadar keskin kokuyorsa da içimdeki acı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/hic-olmadin-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yağmur', 'yagmur-nurten-altinok-jnq4a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarın yine yağmur yağacak

Yine bir bahanem olacak  / sana gelmemem için

Fırtınalar çıkacak

Lodoslar dalgaları yıkacak

Trafik ana baba günü

Köprüler kilitlenecek

Yarın yine yağmur yağacak

Ben yine sana gelemiyeceğim

Unutup içimdeki yağmurları

Güneşi bekliyeceğim

Oysa! ...', 'Yarın yine yağmur yağacak Yine bir bahanem olacak  / sana gelmemem için Fırtınalar çıkacak Lodoslar dalgaları yıkacak Trafik ana baba günü K...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yagmur-986-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gümülcine', 'gumulcine-nurten-altinok-bu4wv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tek yalnızlığım bu sokaklarda

Dibi delik ceplerde, bana kalan

Budanmış ta koca çınarın dalları

Hep ayni eltokmak, vurur kapıları

Bayrak yarışı gibi zaman değişen tenlerde

Bir çoğunun yitirişiyle ürperdim de

Çocukluğum ağladı fırdöndü eteklerde

Gençliğim ezilmiş ilk topuklu terliğimde

Medeniyet belli ki uğramamış bazı semtlere

Kat kat üstünde yükselmiş cephelerde

Yine benimki mahsun beklemede

Taş, kerpiç, tuğla kesitinde

En çok öpemediğim ellere yandım

Göremediğim yüzlere

Sessiz kalan kapı zillerinde

Duyamadığım ayak seslerine

Ben bu yarışın neresindeyim?', 'Bir tek yalnızlığım bu sokaklarda Dibi delik ceplerde, bana kalan Budanmış ta koca çınarın dalları Hep ayni eltokmak, vurur kapıları Bayrak ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gumulcine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevda', 'sevda-nurten-altinok-it82l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bensiz yapamazsın sevdam

Kalemim düşmedikçe parmaklarımdan

Beni bırakamazsın

Kelepçeledim seni mısralara 

kaçamazsın

Sen bensiz yatamazsın sevdam

Geceler yaşadıkça koynumda

Beni unutamazsın

Kilitledim seni umutlara

Kıramazsın

Sen bensiz olamazsın sevdam

Bu yürek attıkça bu kafeste

Çıkamazsın

Azat etsem de tüm yanılgıları

Beni bana bırakamazsın

Benim sen olduğumu 

Unutamazsın

Ben sevdayım

Benim adım sevda', 'Sen bensiz yapamazsın sevdam Kalemim düşmedikçe parmaklarımdan Beni bırakamazsın Kelepçeledim seni mısralara  kaçamazsın Sen bensiz yatamazs...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevda-346-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gurbet-1', 'gurbet-1-nurten-altinok-r17ik', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam oluyor

Davetsiz karabasanlarda anılar filizleniyor

En keskin çığlıklarda sessizlik iki büklüm

Yıldızlar ağlıyor samanyolunda

Yolunu yitirmiş

Miğferi düşmüş güneş can çekişiyor  bir yerlerde

Dalgaların sesi çok uzak

Balıkların gözyaşı parmak ucumda sızı

Akşam oluyor

Korkular gizleniyor köşe başlarında

Sokak lambalarında anılar ağlıyor

Bir çocuk sesi 

Sıcacık bir koyunda uykuyu arıyor

Devleşiyor yetimliğim

Yetimliğim acı veriyor

Kahroluyorum

Yüreğimi bohçalayıp gözlerime 

Sırılsıklam

Gidiyorum', 'Akşam oluyor Davetsiz karabasanlarda anılar filizleniyor En keskin çığlıklarda sessizlik iki büklüm Yıldızlar ağlıyor samanyolunda Yolunu yi...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gurbet-1-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanımeli BİR', 'hanimeli-bi-r-nurten-altinok-dzelg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hanımeli

Gözlerimin yürek yürek atışını aradım bu sokaklarda

Arnavut kaldırımlarında çocukluğumun ayak izlerini

Kurbağa başlıklı çeşme başında gençliğimin tazeliğini

Hangi rüzgâr esti geçti buradan?  Bu kadar acımasız

. Dalından koparılmış bir hanımeli... 

. Yanıyor şimdi

Kaç kez kırbaçladı yağmur, tırnak yazısı duvarlarımı, kim bilir? 

Kaç kez mahkûm edildim en yakın uzaklara 

Kaç kez törpülendi zincirlerim yarınlara

Kaç kez doğumu yaşadım sıla sancılarında

. Dalından koparılmış bir hanımeli

. Kanıyor şimdi...

Kilit vurulmuş kapılarda zamanın acımasız izi, paslı

Omuzlarda kimler gitti kim bilir, kaç kişi, yıllar yılı

Gecelerin karabasanlarını yaşadım, susturup içimdeki yalnızlığı

Ne giden geri geldi, ne gidenin selamı

Ne kalanın hayır duası

. Dalından koparılmış bir hanımeli

. Ağlıyor şimdi.

Kaldırımlarda silinmiş, ayak izlerimin sesiyim

Duvarlarda yüzüm asılmış, sararmış resim gibiyim

Boşuna bekler avuçlarım, bir sıcacık eli, öpmek istediğim

Boşuna bekler gözlerim, bir çift çakır gözü, görmek istediğim

Hangi rüzgâr esti geçti buradan? Bu kadar acımasız! 

. Dalından koparılmış bir hanımeli

. Soluyor şimdi

Nurten Altınok', 'Hanımeli Gözlerimin yürek yürek atışını aradım bu sokaklarda Arnavut kaldırımlarında çocukluğumun ayak izlerini Kurbağa başlıklı çeşme başın...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hanimeli-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milenyum Sonrası Düşünceler', 'milenyum-sonrasi-dusunceler-gaffar-karadogan-24p1u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dijital kıyamet kaygısını 

Yaşamadı onlar

Suları zaten kesik

Elektrik, gaz lambalı sohbetleri kıskandığında

Uğruyordu toprak damlı evlere

Özlemiyorlardı havai fişek gösterilerini

Yıldızlar ve ay yetiyordu onlara

Göğü süslemek için

Taşıyorlardı umutları

Yıllara değil

Katır sırtlarında

Köyden kente doğru', 'Dijital kıyamet kaygısını  Yaşamadı onlar Suları zaten kesik Elektrik, gaz lambalı sohbetleri kıskandığında Uğruyordu toprak damlı evlere Öz...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/milenyum-sonrasi-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün ve Sevinç', 'huzun-ve-sevinc-muzeyyen-tuba-jxfth', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüksek binalarda yumuşak pamuklara

Sarılmışken ağlayan bebekler,

Düğmeden gözlü, kısa saçlı bebeğe

Sevinir çocuk olmadan büyüyen çocuklar.

Tararken tek oyuncağının saçlarını,

Onun gibi olmasını bekler tek annesinin.

Gülmenin ayıp olduğunu öğretir babaları

Sessizlikle büyürler içleri heyecanla doluyken

Ağlamak ister ama 

Utanır bu kez kendi gözyaşlarından bile...

Anlayamaz oyuncağının kaybolmasını,

Çocukluğuyla birlikte...

Bir hasret eker yüreğine.

Yeşillenir, dal verir umutları

Kimilerinin  hor göreceği sevinçlerle...', 'Yüksek binalarda yumuşak pamuklara Sarılmışken ağlayan bebekler, Düğmeden gözlü, kısa saçlı bebeğe Sevinir çocuk olmadan büyüyen çocuklar. T...', ARRAY['Türk Edebiyatı','Şiir','Müzeyyen Tuba']::text[], 8.5, '{"poet":"Müzeyyen Tuba","poet_slug":"muzeyyen-tuba","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/huzun-ve-sevinc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karnowski', 'karnowski-gaffar-karadogan-59qbo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Performansımızı sorduk Karnowski''ye

Yüz vermedi bize

Hani doksanıda çok görmemişti

Minör bulgularımız olmasada

Şikayetimiz vardı 

Birilerinden ve kendimizden

''Her hastaya yapılacak bir şey vardır'' demiştin 

Karnowski!

Bize kim ne yapacaksa yapsın artık

Beklemek düşürüyor performansımızı

Kutsallık adına paralandığımız bu meslekte', 'Performansımızı sorduk Karnowski''ye Yüz vermedi bize Hani doksanıda çok görmemişti Minör bulgularımız olmasada Şikayetimiz vardı  Birilerind...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/karnowski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Delik', 'kara-delik-i-brahim-sirkeci-g9miz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kara delik art&yacute;k yüre&eth;im

	gözlerime bak&yacute;&thorn;&yacute;n

bir Cumartesi annesi art&yacute;k

Galatasaray lisesi önünde

Yüzüm siliniyor önünden

iki karadelik içinde

	kaybolma hissiyle

sonsuza do&eth;ru dü&thorn;üyorsun.', 'Bir kara delik art&yacute;k yüre&eth;im 	gözlerime bak&yacute;&thorn;&yacute;n bir Cumartesi annesi art&yacute;k Galatasaray lisesi önünde Y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-delik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülen Yüzler', 'gulen-yuzler-bulent-yuksel-he2ss', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülen yüzler, güzel sözler

Heyecanlandırıyor mu seni de?

Biliyorum

Sen de anlatmak istiyorsun, yaşamın ne olduğunu

Sırtına vurup, boğazından sökmek istiyorsun kelimeleri

Umutsuz kalıyorsun, anlatmak istediklerini anlatamayınca

Temel sorular karıştırıyor düşüncelerini

Neyim? 

Neden buradayım? 

Nereye gidiyorum?

Biliyorum

Bulamıyorsun çözümünü

Okkalı bir küfür savuruyorsun ağız dolusu

Sıkıntılı yaşamında olmak istediğin en son kişi

Kendin oluyorsun bir anda

Sorulara cevap aradıkça

Sorular çoğalıyor, sorunlar büyüyor

Yaşadıkça yaşlanmıyorsun aslında

Yaşlandığını hissettikçe yaşlanıyorsun

Umutsuzluğa kapılınca, çaresizsin

Hoşgörülü davrandıkça, ısınıyorsun insanlara

Sevgiyi yaşadıkça, hayata bir anlam veriyorsun

Ve bööyle sürüp gidiyor

Yaşıyorsun cevaplanmamış sorularla

Yaşlanıyorsun, heyecanı arayarak

Biliyorum

Gülen yüzlerle

Güzel sözlerle tesselli oluyorsun

Benim gibi...', 'Gülen yüzler, güzel sözler Heyecanlandırıyor mu seni de? Biliyorum Sen de anlatmak istiyorsun, yaşamın ne olduğunu Sırtına vurup, boğazından...', ARRAY['Türk Edebiyatı','Şiir','Bülent Yüksel']::text[], 8.5, '{"poet":"Bülent Yüksel","poet_slug":"bulent-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gulen-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damdan Damlaya Damlayadan', 'damdan-damlaya-damlayadan-i-brahim-sirkeci-iqmn8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hani sen var ya

o küpelerin var ya

	o yürek taklidi yapan

lakin canca&eth;az&yacute;m,

	o yürek

kula&eth;&yacute;na küpe olsun

	diye de&eth;il ki;

yüre&eth;ime

	kulak olsun diye.', 'hani sen var ya o küpelerin var ya 	o yürek taklidi yapan lakin canca&eth;az&yacute;m, 	o yürek kula&eth;&yacute;na küpe olsun 	diye de&eth;...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/damdan-damlaya-damlayadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Ziyareti', 'bir-dost-ziyareti-i-brahim-sirkeci-q2vuh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Orta halli bir k&yacute;&thorn; günü

bilinmez merdivenler

lo&thorn; bir odaya ç&yacute;kard&yacute; beni

ç&yacute;plak bir masa ve 

so&eth;uklu&eth;un kar&thorn;&yacute;lad&yacute;

bakamad&yacute;m ona

biraz &yacute;s&yacute;n&yacute;r diye

pembe, beyaz ve ye&thorn;il

koydum.

Olmad&yacute;.

her&thorn;eyini ç&yacute;kar&yacute;p gitmi&thorn;sin

soyunmay&yacute; severdin

		(soyunmu&thorn;lu&eth;unu severdim

soyunduklar&yacute;n&yacute;n hepsi oradayd&yacute;:

resmiyetin, ince gözlü&eth;ün

kuma&thorn; pantolonun, formalitelerin

sizli bizli konu&thorn;malar&yacute;n

so&eth;uklu&eth;un....

bakamad&yacute;m,

so&eth;uklu&eth;unu b&yacute;rakm&yacute;&thorn;t&yacute;n

ke&thorn;ke ba&thorn;ka bir yerde

bulayd&yacute;m seni

ne de olsa

so&eth;uklu&eth;unu b&yacute;rakm&yacute;&thorn;t&yacute;n.', 'Orta halli bir k&yacute;&thorn; günü bilinmez merdivenler lo&thorn; bir odaya ç&yacute;kard&yacute; beni ç&yacute;plak bir masa ve  so&eth;u...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-dost-ziyareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-i-brahim-sirkeci-hg900', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel bir sabahta 

özledi&eth;im renktesin

tad&yacute;n, bir esmer üzümsuyu tad&yacute;

Gülü&thorn;ün, Akdeniz s&yacute;cakl&yacute;&eth;&yacute;nda

al&yacute; al, moru mor

güzel bir sabahta

	özledi&eth;im renktesin

Üzerine bir leylak a&eth;ac&yacute; e&eth;ilmi&thorn;

Çok zamand&yacute;r dü&thorn;ünde

	çatallanm&yacute;&thorn; yollar var

telve biraz köpürmü&thorn; orada

pek güzel ç&yacute;km&yacute;&thorn; fal&yacute;nda

söyleyemedi&eth;im &thorn;eyler var

sevdalar, umutlar, yolculuklar

diledi&eth;in herneyse ikiye 

		bölünmü&thorn;

ama bir sen vars&yacute;n orada

		bir de ben

Fal&yacute;n sonunda uyanm&yacute;&thorn;s&yacute;n

	ku&thorn;lar konmu&thorn; gö&eth;süne

mor leylaklar içinde

	mutlu gülümsemi&thorn;sin', 'Güzel bir sabahta  özledi&eth;im renktesin tad&yacute;n, bir esmer üzümsuyu tad&yacute; Gülü&thorn;ün, Akdeniz s&yacute;cakl&yacute;&eth;&ya...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fallot', 'fallot-gaffar-karadogan-2ksr0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mediasten penceresinden

Bakıyorlardı bize

Pencerenin buğusunu siliyordu 

Negatoskobun loş ışığı

Büyük arterler

Köşe kapmaca oynuyordu mediastende

Kah transpozisyon oluyor

Kah ata binşyordu aort

Üsküdarı geçmemişse fallot

Yapacak bir şey vardır elbet

Total korreksiyon gibi

Çocuklarımızın beynini 

Hipoksik bırakamayacaksın fallot

Ayıracaklar kötüden iyiyi

Ve tanıyacaklar seni', 'Mediasten penceresinden Bakıyorlardı bize Pencerenin buğusunu siliyordu  Negatoskobun loş ışığı Büyük arterler Köşe kapmaca oynuyordu medias...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/fallot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfelik', 'kufelik-i-brahim-sirkeci-o573a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'pastoral bir &thorn;ölen giriyor dü&thorn;lemime

Koca Akhisar tütün k&yacute;r&yacute;yor,

	-k&yacute;rmalarda do&eth;mu&thorn; ya babam

		herhalde bu zaman-

gecenin karanl&yacute;&eth;&yacute;nda

	topra&eth;a dönük ayd&yacute;nlanm&yacute;&thorn; yüzler

	&yacute;&thorn;&yacute;&eth;&yacute;yla

	herbiri birer ate&thorn; böce&eth;i

			lüx lambalar&yacute;n.

öyle ya hiç de&eth;i&thorn;memi&thorn; bu.

	hala lambalar lüx

	sar&yacute; dünyan&yacute;n çal&yacute;&thorn;kan insanlar&yacute;na

yüzleri topra&eth;a dü&thorn;mü&thorn;

	tütün k&yacute;r&yacute;yorlar

	her lambaya üç be&thorn; ki&thorn;i

	uzun uzun susuyorlar

		birbirlerine kay&yacute;ts&yacute;z

	sabahlara kavu&thorn;an yaln&yacute;zl&yacute;klarda.

sabaha kar&thorn;&yacute; 

	özenle toplanm&yacute;&thorn; tütünlerin

				hepsi küfelik

		&Yacute;zmir’e do&eth;ru herkes küfelik.', 'pastoral bir &thorn;ölen giriyor dü&thorn;lemime Koca Akhisar tütün k&yacute;r&yacute;yor, 	-k&yacute;rmalarda do&eth;mu&thorn; ya babam 		h...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kufelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gun Ortasinda Karanlik', 'gun-ortasinda-karanlik-i-brahim-sirkeci-gskp3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''masis''e'' 

mutemadiyen ay taklidi yapan bir gunes 

pek de nazli, kendini gostermede 

hep ucuk gri onunde bir perde 

arasi yok saatlerle de 

sasiriveriyor insan kendine 

ne zaman karanlik cokse ustune 

caktirmadan kendini gosteriyor ortayerinde 

imparatorluk lesi bu ulkenin 

gecenin icinde ay yok, gunes islak 

renkler siyahtan ayrisiyor tatlar IssIz 

dusunden uyaninca insan dusunun icine 

kara bir kedi usulca sahneyi terkeder 

dusler islak, dingin, dogurgan, sicak 

ayirdina varamadigimiz yaz(i) anlasildi 

    gizlisi saklisi kaldiysa, 

    gunahkar cemal sureya 

sheffield, 13 agustos 2000.', '''masis''e''  mutemadiyen ay taklidi yapan bir gunes  pek de nazli, kendini gostermede  hep ucuk gri onunde bir perde  arasi yok saatlerle de  ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gun-ortasinda-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Insomniaktan Aforizmalar', 'bir-insomniaktan-aforizmalar-i-brahim-sirkeci-bxz27', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I. 

buralardan bir yerden mi gectin nedir 

gogumde bulutsu bir dogu mutlulugu 

II. 

askere gider gibi degil okula gider gibi 

gelmisim ve kalmisim, filintanin pasi gibi 

III. 

oradan alip suraya koymusum seni 

goruyor musun koydugum yeri 

IV. 

annenin adindan cikarinca kardesini sesin kaliyor geriye 

ne tuhaf sonra hic kaybolmuyor 

V. 

seni ilk gordugum de cicek getiren cocugun donuk bakislarinda 

secici gecirgen bembeyaz bir sevda gibiydin 

VI. 

ben seni kisa opemem, cunku 

hep uzun kosulara opuluyorum 

VII. 

burnun bir akdeniz limani gozlerin 

kozu bir nargilenin suya yansiyan 

VIII. 

dokundugun yerde gul bitiyor sevda 

basliyor gizeminde guzellik gizli guzelim 

IX. 

su kucucuk kocaman dunyada 

biz iki kocaman minik yaramaz 

X. 

bu dizeler senden olma cocuklarim benim, hepsi kiz 

bir askyili icinde bir askyolu uzaklikta herbiri 

XI. 

cimenlerin terinde yikanmis 

ay gecmis caydan gelirken 

XII. 

bi duzine dize 

duzene, duzune, dizine 

   Mart 2000', 'I.  buralardan bir yerden mi gectin nedir  gogumde bulutsu bir dogu mutlulugu  II.  askere gider gibi degil okula gider gibi  gelmisim ve ka...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-insomniaktan-aforizmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Izmir', 'guzel-izmir-i-brahim-sirkeci-p6lyj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Homer''den beri kirgin 

Ege''nin simsiyah zeytinlerini 

            aydinlatmaya yetmez 

            bodrum sairinin dizeleri 

yüzyillari avutmaya çalisan 

            papatya çiçekleri 

Adem''in Havva''ya ilk hediyesi 

    uzatmislar bembeyaz ellerini 

    oksamak istercesine zeytinin belini 

            cesaret bularak 

çelimsiz imbat yelinden 

sheffield, 8 Subat 2000', 'Homer''den beri kirgin  Ege''nin simsiyah zeytinlerini              aydinlatmaya yetmez              bodrum sairinin dizeleri  yüzyillari avut...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-izmir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya Sepetlerinin Ilki', 'papatya-sepetlerinin-ilki-i-brahim-sirkeci-b1c5q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yuzune dokunuyorum 

ellerim islaniyor 

butun gece disarida kalmissin 

cig yagmis gozaltlarina 

        sonra kiragimis 

ellerin butun gece bana uzanmis 

perdeleri ortmus, kapilari kapatmis 

dudaklarin, ashk olmus, o kadar 

ilkkiraz tadinda olmuslar 

            mürdüm erigi renginde olmuslar 

bacaklarin uzamis uzandikca ellerin 

tasinmaktan oradan buraya, uzaga 

gozlerin, mutluluktan kapandi kapanacak 

zorla aciyorsun gozkapaklarini ki 

sahit olsunlar butun olan bitmeyene 

icine dokunuyorum, nemli, kirilgan 

kulaginin kiyisinda bir barakada oturuyorum 

deniz kokuyorsun, deniz sen kokuyor.. 

yelkenlerim birer gelincik yapragi, 

karanfil kokulu ogullar ulkesine sefere cikmisim 

sana gelen yollar bile Romadan gecermis meger 

sezara selam soyle, gozlerinden gozlerinden operim. 

20 Subat 2000, Sheffield.', 'Yuzune dokunuyorum  ellerim islaniyor  butun gece disarida kalmissin  cig yagmis gozaltlarina          sonra kiragimis  ellerin butun gece b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sirkeci']::text[], 8.5, '{"poet":"İbrahim Sirkeci","poet_slug":"i-brahim-sirkeci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/papatya-sepetlerinin-ilki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Seni Anlatması Için', 'sana-seni-anlatmasi-icin-muzeyyen-tuba-sfa4l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir  yudum su içtim yine bardağımdan

Yağmurların toprak kokusunu hissettim.

Çamurda oynayan umutlu çocukları gördüm

Ve kaderine ağlayan  insanın gözlerini.

Akşam sabah rüzgar esiyorsa yüreğinde

Yağmurlar yağıyorsa  ellerinden

Sen de uyutmalısın  kederlerini

Büyümesi, güzelleşmesi,değişmesi için

Bir gün  gelip sana, seni anlatması için...', 'Bir  yudum su içtim yine bardağımdan Yağmurların toprak kokusunu hissettim. Çamurda oynayan umutlu çocukları gördüm Ve kaderine ağlayan  ins...', ARRAY['Türk Edebiyatı','Şiir','Müzeyyen Tuba']::text[], 8.5, '{"poet":"Müzeyyen Tuba","poet_slug":"muzeyyen-tuba","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-seni-anlatmasi-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitiş', 'bitis-muzeyyen-tuba-62zxu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gurbet mi ayrılık mı hasret mi 

Nedir bu başımıza gelenler

Umut mu besliyoruz yüreğimizde

Gözlerimizde.

Bir yabancı geçiyor,

Zaten hep yabancıydı

Geçiyor bazen günler 

Zaten hep geçerdi.

Anlatmak  daha  zor 

Bilirsin...

Anlatmak ta zordu zaten.

Bitiş mi  başlangıç mı?

Bitiş  aslında  hiç  başlamadı...', 'Gurbet mi ayrılık mı hasret mi  Nedir bu başımıza gelenler Umut mu besliyoruz yüreğimizde Gözlerimizde. Bir yabancı geçiyor, Zaten hep yaban...', ARRAY['Türk Edebiyatı','Şiir','Müzeyyen Tuba']::text[], 8.5, '{"poet":"Müzeyyen Tuba","poet_slug":"muzeyyen-tuba","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bitis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçun Kuşlar Uçun', 'ucun-kuslar-ucun-arif-baltaci-o7lgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Rıza Tevfik BÖLÜKBAŞI''nın anısına saygıyla)

Vatanıma döndüm umut boş çıktı

Sevdiğim evlenmiş sözler yaş çıktı

Sevgimin sonunda aşk sarhoş çıktı

Sılada garip bir tekamül vardır.

Akan sular durmuş çiçekler solmuş

Sevdiğim evlenmiş anacım ölmüş

Sılada maziden dertlerim kalmış

Yapayalnız duran bir melül vardır

Sıla mı gurbet mi anlayamadım

Ruhum sensiz kaldı ağlayamadım

Gönül kapısını bağlayamadım

Hasretin içinde bir müşkül vardır

Gurbete gittimde düşmedim dara 

Dertlerle boğuştum almadım yara 

Asla sürülmedi alnıma kara 

Derdime bilinmez bir formül vardır.

Umudum kalmadı artık sıladan

Bana yarar gelmez sensiz hayattan 

Yaşayamam artık yarim olmadan

Namerde verilen bir ödül vardır

Sevgilim evlenmiş döndüm yerime 

Sılayı unuttum baktım sevmeye 

Aradım derman yok sensiz gezmeye 

Güzel dediğinde bir kakül vardır

Namertmişsin meğer döndün sözünden

Hiç mi sevmemiştin beni gönülden

Belli ki memnunsun alın yazından

Sahte sevgide de bir usül vardır.

Uçun kuşlar uçun tekrar gurbete 

Artık bizden yarar gelmez devlete 

Yarab götür bizi ebediyete 

İbresi bozulmuş bir baskül vardır.', '(Rıza Tevfik BÖLÜKBAŞI''nın anısına saygıyla) Vatanıma döndüm umut boş çıktı Sevdiğim evlenmiş sözler yaş çıktı Sevgimin sonunda aşk sarhoş ç...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ucun-kuslar-ucun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-sair-hezaran-ssalu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Devrilmiş bir ploterya üzerine kuruyorum şimdi

devrik cümlelerimi 

Harflerim bile yana yatık 

Düşmeye durmuş

ve bedenimi karartan zincirlerden halkalar 

kaldı iz iz 

Dalgalanmış vucüdumda ağlayan yaralar var..

Susturmak uzerina kurulu anlayacağınız 

her infaz işkencesi.

Bilmiyorlar ama;delirmiş beynimden 

                                  çürümüş vucüdumdan

                                   kesilmiş dilimden 

                                   ''alamazlar seni asla''

ölümde olsa ''unutturamazlar''...', 'Devrilmiş bir ploterya üzerine kuruyorum şimdi devrik cümlelerimi  Harflerim bile yana yatık  Düşmeye durmuş ve bedenimi karartan zincirlerd...', ARRAY['Türk Edebiyatı','Şiir','Şair Hezaran']::text[], 8.5, '{"poet":"Şair Hezaran","poet_slug":"sair-hezaran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/surgun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuvayi Milliye', 'kuvayi-milliye-nazim-hikmet-ran-0gnm8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onlar ki toprakta karınca, 

              suda balık, 

              havada kuş kadar 

             çokturlar; 

korkak, 

            cesur, 

            câhil, 

            hakîm 

            ve çocukturlar 

ve kahreden 

            yaratan ki onlardır, 

destânımızda yalnız onların mâceraları vardır. 

Onlar ki uyup hainin iğvâsına 

            sancaklarını elden yere düşürürler
..........
..........', 'Onlar ki toprakta karınca,                suda balık,                havada kuş kadar               çokturlar;  korkak,              cesur, ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuvayi-milliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanlar', 'zamanlar-sair-hezaran-i41er', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geniş zamanlara uyarlıyordum sevdaları

                     ''-r'' ''leri söyliyemesemde 

                       seviyoyum.

Ve cüzdanımdaydı beyaz bir kimlikte taşıdığım

                                                        sevgilim......

O şimdiki zamanın doğum sancılarından 

                     yargısız yaralarına mühür tutturuyordu.

Oysa ben '' yorumsuz bir sevgiliye 

                    şimdiki sevdalardan alıp 

                     geniş zamanlarda yaşatmak isterdim''...', 'Geniş zamanlara uyarlıyordum sevdaları                      ''-r'' ''leri söyliyemesemde                         seviyoyum. Ve cüzdanımdaydı be...', ARRAY['Türk Edebiyatı','Şiir','Şair Hezaran']::text[], 8.5, '{"poet":"Şair Hezaran","poet_slug":"sair-hezaran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zamanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Neydi', 'ask-neydi-arif-baltaci-t5myc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık bir sonbahar akşamında 

Aniden içime bir sızı düştü

Yoksa aşk dedikleri bu muydu

Ya da bir anlık sevinçten sonra

Gözlerde oluşan nemim adımıydı aşk

Her aşkta ayrılık

Her aşkta acı

Her aşkta gözyaşı

Olmasa aşk yaşanmazmıydı

Neydi aşk dedikleri anlayamadım

Kalbimin hızla çarpması aşk sayılmazmıydı

Aşık olmak için ne gerekiyordu

Aşk duygusunu yaşamak için 

Sabaha kadar onu düşünmekmi lazımdı

Aşk sadece güzel birine mi bağlanmaktı

Ama ben sabaha kadar düşündüm 

Ağladım ayrıldım acıyı tattım

Ama bir kız için değildi

Bunun adı aşk değilmi şimdi

Aşk sadece birinimi sevmekti

İnsanları doğayı,hayvanları

Allah’ı sevmekte aşk değil miydi

Gökyüzünü,yağmuru,baharı,kuşları

Sevmek aşka sığmaz mıydı

Sonunda ayrılık olmayan sevgilere 

Aşk denmez miydi sizin oralarda

Aşk vuslata ulaşamadan ölmek miydi sence 

Aşk güzellikle acıyı 

Bir arada yaşamak mıydı

Aşkı bulmak için 

Bazı şeylerden vazgeçmek mi lazımdı

Aşk imkansızlık mıydı

Kucaklaşamadan vurulmak mıydı aşk

Ya da kurşunların önüne geçip

Uğruna ölmekmiydi

Eğer aşk buysa arkadaş

Zor rastlanır bu devirde

Aşka düşene', 'Karanlık bir sonbahar akşamında  Aniden içime bir sızı düştü Yoksa aşk dedikleri bu muydu Ya da bir anlık sevinçten sonra Gözlerde oluşan ne...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ask-neydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Artırma', 'acik-artirma-sair-hezaran-5nfa1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendimi satıyorum ey ahali

Acılışı siz yapın,biçin bir değer

Görsünler bir hayat kaç para eder.

Dış görünüşüme bakmayın 

Meziyetim beynimde.

Düşünürüm ben ;herşeyi,herkesi

Biçin bir değer 

Görsünler düşünmek kaç para eder.

Kimim kimsem yok benim 

Yanlızım 

Sevenim , sevdiğim yok . 

biçin bir deger

Görsünler yanlızlık kaç para eder.

Ben aşkları severim

bir sevdicek bulamadım 

o yüzden yanlış yaşarım aşkı 

biçin bir değer

Görsünler bu yürek kaç para eder.

Ne oldu,alanınız yokmu beni

beş para etmezmiyim 

beş para etmezmi beynim 

                                 yanlızlığım

                                   yüreğim

haklısınız

haklısınız ben işe yaramazım..', 'Kendimi satıyorum ey ahali Acılışı siz yapın,biçin bir değer Görsünler bir hayat kaç para eder. Dış görünüşüme bakmayın  Meziyetim beynimde....', ARRAY['Türk Edebiyatı','Şiir','Şair Hezaran']::text[], 8.5, '{"poet":"Şair Hezaran","poet_slug":"sair-hezaran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/acik-artirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Bana Kaldı', 'olmek-bana-kaldi-arif-baltaci-up4lu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne yapayım olamam sensiz

Gidiyorsun ha benden habersiz

Ne yaptım sana terkettin beni 

Bakışlarım buğulu bakışlarım çaresiz

Birgün sende beni ararsın 

Belki pişman olur ağlarsın

Seni ne kadar sevdiğimi bilsen

Neden terkettim diye  yanarsın.

Sen gittin hasret bana kaldı

Sen sevdin nefret bana kaldı

Seni unutamadım sarı gülüm

Sen yaşadın ölmek bana kaldı.', 'Ne yapayım olamam sensiz Gidiyorsun ha benden habersiz Ne yaptım sana terkettin beni  Bakışlarım buğulu bakışlarım çaresiz Birgün sende beni...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmek-bana-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-sair-hezaran-56sqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çivi tutmaz duvarların çürümüşlüğünde

Bir bedenin hükümsüzlüğü 

Mikrop saçan sevdalar yaşatırdı.

çelik paslanmazlığında diye satılırdı her şey

oysa kıvam demirdendi. 

ve bir yaşamak ki 

her şey güneşe yenilmişti.', 'Çivi tutmaz duvarların çürümüşlüğünde Bir bedenin hükümsüzlüğü  Mikrop saçan sevdalar yaşatırdı. çelik paslanmazlığında diye satılırdı her ş...', ARRAY['Türk Edebiyatı','Şiir','Şair Hezaran']::text[], 8.5, '{"poet":"Şair Hezaran","poet_slug":"sair-hezaran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dus-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Sevdam', 'mechul-sevdam-sair-sahi-tbbp1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmek istiyorum

Seni sevmek için senin beni sevmeni istiyorum

yanlızca beni sevmeni

Yaşadıklarımız yaşayacaklarımızdan az olmalı

seni sevmek istiyorum

hüzünle gecen dünlerime inat

işte bende seviyorum demeyi ve 

mutluluk denizinde seninle yüzmeyi istiyorum.

beni sevmeni istiyorum , yanlızca sevmeni.

sen kimsin bilmiyorum 

ama seni seviyorum 

bana her gelişinde

beni bir öncekinden çok sevmeni istiyorum.

vuran her dakikanın

senin adını andıgım an olmasını istiyorum.

ben senin beni sevmeni istiyorum.

senle girdigimiz sevgi yarışında ,

hep yenilmeni ve her yenilişinde 

kazanmak için benden çok sevmeni istiyorum.

ben beni sevmeni istiyorum .

kendinden bile fazla.

her sarılışında özlemeni , her özlediğinde sarılmanı.

ve beni sevmeni istiyorum , 

benden bile fazla.

seni sevmek istiyorum .

sana gelmek istiyorum

ben sen olmak istiyorum.

ama benim oldugum kadar

istermisin bilmiyorum ama 

seni sevmek istiyorum

ve senin beni benden çok sevmeni istiyorum

söylesene meçhul sevdam

senden çok şeymi istiyorum.....', 'Seni sevmek istiyorum Seni sevmek için senin beni sevmeni istiyorum yanlızca beni sevmeni Yaşadıklarımız yaşayacaklarımızdan az olmalı seni ...', ARRAY['Türk Edebiyatı','Şiir','Şair Sahi']::text[], 8.5, '{"poet":"Şair Sahi","poet_slug":"sair-sahi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mechul-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-arif-baltaci-s0x37', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen papatyalar arasında 

Gelinciktin ne oldu 

Bir güle değiştin beni gamsız 

Söylemiştiler o yar çok vefasız

Lokmam boğazımda kaldı

Hani hani ölümsüzdü aşkımız 

Beni neden terkettin anlayamadım 

Ya da bizansın bu olayda ne rolü vardı

Yoksa aşkımız hepatit-b mi olmuştu

Aşkımızın viagraya da ihtiyacı yoktu

Beni neden terkettin anlayamadım

Kurumuş gül kadar değeri yokmu sevgimin 

Önce yere attın sonra çiğnedin

Ama boşver üzülme ben seni sevdim

Kaprisini sevdim.

Benim inat sevgilim.', 'Sen papatyalar arasında  Gelinciktin ne oldu  Bir güle değiştin beni gamsız  Söylemiştiler o yar çok vefasız Lokmam boğazımda kaldı Hani han...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelincik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Oldukça', 'sen-oldukca-serhat-kulu-1eh9m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuş olup uçmak isterdim yanına,

Varsın kanadım kırsınlar benimsin ya

Önüme dizilseler bölük bölük

Duvarlar örseler metrelerce

Yıkmam mı sandın yanımda sen,

Sen oldukça...', 'Kuş olup uçmak isterdim yanına, Varsın kanadım kırsınlar benimsin ya Önüme dizilseler bölük bölük Duvarlar örseler metrelerce Yıkmam mı sand...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-oldukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odak', 'odak-radovan-pavlovski-5gv5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Taştan zarif bir şey yap bana 

bir iplik çek yıldız yumağından 

sessizliğimi sesine bağla 

beni sevdaya taşı 

beni bütünüyle götür 

Yan yana diziver anahtarları 

varsın kan kandan döllensin 

Ölülerin işitimini geri vermeye 

gelmiştir artık 

güneyli davulcular 

Bir kıvılcım uçuşuyor yarıgecelerde ve öğlelerde 

Aydınlığın anahtarlarını koruyandır o 

İçimdeki güneş şiire mahkum .', 'Taştan zarif bir şey yap bana  bir iplik çek yıldız yumağından  sessizliğimi sesine bağla  beni sevdaya taşı  beni bütünüyle götür  Yan yana...', ARRAY['Türk Edebiyatı','Şiir','Radovan Pavlovski']::text[], 8.5, '{"poet":"Radovan Pavlovski","poet_slug":"radovan-pavlovski","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/odak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savrulur İçimde Pompei''nin Külleri', 'savrulur-i-cimde-pompei-nin-kulleri-hasan-sutay-kjo85', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey içimde patlayan Pompei

Nerde lavların?

İçimi parçalıyor

Alevlerin keskin tırnakları

İçimi alevler yalıyor.

Dur yok durak yok

İçimi yalıyor alevler.

Bir fırtına kopuyor

Kayboluyor birden evler

Ateşin dilleriyle

Her yerde alevden devler.

Yangın sonrası

Etrafıma üşüşür

Vampirler halkası.

Yangın ortasında

Ben ağlarım, yüreğim üşür.

Savrulur içimde

Pompei''nin külleri.

Talan olan bahçelerime

Yanıp kavrulan

Uçup savrulan

O güzelim güllerime

Ağlıyorum yine.', 'Ey içimde patlayan Pompei Nerde lavların? İçimi parçalıyor Alevlerin keskin tırnakları İçimi alevler yalıyor. Dur yok durak yok İçimi yalıyo...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sutay']::text[], 8.5, '{"poet":"Hasan Sutay","poet_slug":"hasan-sutay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/savrulur-icimde-pompei-nin-kulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızı Yıldızda Bulabilirsin Yanlız', 'yildizi-yildizda-bulabilirsin-yanliz-radovan-pavlovski-6sq0m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Midye incisinden çıkmış 

Deniz yıldızı aydınlatıyor deniz yolunu, 

Gövdesi oldum düşüncemin 

İlk kez yıldızlar arasında yol, 

Dimdik duracağım zaman içinde 

Ve ilaç bulmak niyetiyle 

Beni ararsa eğer eğilenler 

işte o zaman dile gelecek 

Unutulmuş bir çağ 

Ve unutulmuş bir ulus 

Yola koyulacak 

Unutulmuş yollardan 

Ve kendi izlerini arayacak 

Bulamazsa eğer 

Kuş olacak 

Türkülerde yaşatacak varlığını 

Güneş yok olursa eğer 

Derinliklerinde inip yeryüzünün 

Toprraktan çıkaracak güneşi 

Yıldızı yıldızda bulacak 

Yalnız.', 'Midye incisinden çıkmış  Deniz yıldızı aydınlatıyor deniz yolunu,  Gövdesi oldum düşüncemin  İlk kez yıldızlar arasında yol,  Dimdik duracağ...', ARRAY['Türk Edebiyatı','Şiir','Radovan Pavlovski']::text[], 8.5, '{"poet":"Radovan Pavlovski","poet_slug":"radovan-pavlovski","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yildizi-yildizda-bulabilirsin-yanliz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-radovan-pavlovski-js9vs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş ve ay çalan bir kız 

çıkacak karşına yol ortasında 

boynunda capcanlı gümüş gerdanlık 

Uzun yolculuğa çıkarken 

al elma armağan eden 

bulutlu düşünün 

resmidir o sadece 

Boran ortasında eğer 

öten bir kuşla karşılaşırsan 

bileceksin: 

Şakır şakır şimşekler 

süpürmededir köyünü. 

Ölüm yumurtasından- 

hayat doğuyor 

Kuşla 

yolculuk ediyor 

taş kanatlı 

köyün.', 'Güneş ve ay çalan bir kız  çıkacak karşına yol ortasında  boynunda capcanlı gümüş gerdanlık  Uzun yolculuğa çıkarken  al elma armağan eden  ...', ARRAY['Türk Edebiyatı','Şiir','Radovan Pavlovski']::text[], 8.5, '{"poet":"Radovan Pavlovski","poet_slug":"radovan-pavlovski","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/masal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-yavuz-gunay-9ae76', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'iyi dinle arkadaş kulak ver bana

örf adet bizde özdür gardaşım

sırrını vermesakın herdost olana 

sır dedikleri el yakan közdür gardaşım

san ma bu dünyay tekrar gelinir

dostun en iyisi darda bilinir

aleme sultan olsan namın silinir 

kırallık sefadır sazdır gardaşım....

kanma bu dünyada namert sözüne 

dostunu düşman gösterirler gözüne

darda kalsan bile vurma dizine

dört mevsimin biri yazdır gardaşım

demesinler şu yavuzun sözü yalandır 

doğru söz akıldan kalbe dolandır

üç metre kefen sana kalandır

yaşamak yaraya tuzdur gardaşım..', 'iyi dinle arkadaş kulak ver bana örf adet bizde özdür gardaşım sırrını vermesakın herdost olana  sır dedikleri el yakan közdür gardaşım san ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Günay']::text[], 8.5, '{"poet":"Yavuz Günay","poet_slug":"yavuz-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasihat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüklerim', 'gorduklerim-yavuz-gunay-belfa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'menfaatmi herşey,herşey paramı??

güvendiklerim büyüttü içimdeki yaramı

şerefsiz ellerde yerken haramı

şerefe kadeh kıranlar gördüm

ne utanması kalmış ne,ar ne ayıp

ilim irfan desen ta dünden kayıp

sırtındaki ceketi keramet sayıp 

adamım zaneden hayvanlar gördüm

isyan değil haşa darılma sakın 

bu kılıca dar geliyor bak bu kın

doğacak dediler güneşiniz yakın

son nefesinde güneşi soranlar gördüm

daha söylemeye vamıyor dilim

dostuma kalkacaksa kırılsın elim

hele karşımızdaki düşman diyelim

sırtımdan vuracak ne dostlar gördüm.....', 'menfaatmi herşey,herşey paramı?? güvendiklerim büyüttü içimdeki yaramı şerefsiz ellerde yerken haramı şerefe kadeh kıranlar gördüm ne utanma...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Günay']::text[], 8.5, '{"poet":"Yavuz Günay","poet_slug":"yavuz-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorduklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Kedisi', 'kul-kedisi-cenk-cuneyt-glpek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonbaharın kasvet kokan akşamlarının 

herhangi birinde

yağmur damlası sıradan döngüsü içindedir hayatının

kendiside farkındadır bunun

bar denen dört duvarın tahta iskemlesine sertçe düştüğünde

düşüşün şiddetindenmi bilinmez

parçalanan hayat maskesini

dibinde bulur ayaklarının

üç biradan sonra hesap sormazken zamana

akar yavaşça çalan müzikle yeni hayata

herkes duymaktadır müziği

ama sadece o anlar gürültünün ortasında

tiz kalan sesiyle teomanı belki sadece o yaşar

 teomanın o iki yabancısını', 'Sonbaharın kasvet kokan akşamlarının  herhangi birinde yağmur damlası sıradan döngüsü içindedir hayatının kendiside farkındadır bunun bar de...', ARRAY['Türk Edebiyatı','Şiir','Cenk Cüneyt']::text[], 8.5, '{"poet":"Cenk Cüneyt","poet_slug":"cenk-cuneyt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kul-kedisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Bir Gece', 'kotu-bir-gece-ozlem-kucukcelen-0d3kd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rahatsız bir ruh

Kime yararı dokunur

Görmez olur gözleri

Tatmin olmuş bir vücut

Öpülesi dudaklar çoktan pörsümüş

Gece bitti artık

Kazanan kaybeden yok.

Hüznün zamanı değil.

Çağır mutluluğu

Irmakların bağırışı gibi

Bir anlık korku çığlığı gibi

Kessin nefesini.

Yada bırak kemanlar ağlasın 

Senin yerine

Kim hissedilir?

Hayalken yakın

Dokunduğumda kaçacak gibi

Hayatın en güzel ikilemi

Az sonra 

Başka biri olacak

Bana sen kimsin diyecek...', 'Rahatsız bir ruh Kime yararı dokunur Görmez olur gözleri Tatmin olmuş bir vücut Öpülesi dudaklar çoktan pörsümüş Gece bitti artık Kazanan ka...', ARRAY['Türk Edebiyatı','Şiir','Özlem Küçükçelen']::text[], 8.5, '{"poet":"Özlem Küçükçelen","poet_slug":"ozlem-kucukcelen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kotu-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm zamanı', 'olum-zamani-cenk-cuneyt-u1yl2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüter fezaya tasam ve duman,

savrulur külleri çıplak yüreğimde,

kazanmadan kaybetmenin

dayanılmaz acısı; is kokar koynumda

şimdi ölüm zamanı,

gecenin getirdikleri 

yorgun beyaz tenimde,

karanlığın götürdükleri

yanar kor ateşte 

yandıkça tüter fezaya tasam ve duman

savrulur külleri çıplak yüreğimde,

kazanmadan kaybetmenin

dayanılmaz acısı ,is kokar koynumda

şimdi ölüm zamanı, çaresiz;

yaşamak ağrısı asıldı boynuma

bir çift sinsi göz iki tutam sözle', 'Tüter fezaya tasam ve duman, savrulur külleri çıplak yüreğimde, kazanmadan kaybetmenin dayanılmaz acısı; is kokar koynumda şimdi ölüm zamanı...', ARRAY['Türk Edebiyatı','Şiir','Cenk Cüneyt']::text[], 8.5, '{"poet":"Cenk Cüneyt","poet_slug":"cenk-cuneyt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye İşçi Sınıfına Selam', 'turkiye-i-sci-sinifina-selam-nazim-hikmet-ran-j22dp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkiye işçi sınıfına selâm! 

Selâm yaratana! 

Tohumların tohumuna, serpilip gelişene selâm! 

Bütün yemişler dallarınızdadır. 

Beklenen günler, güzel günlerimiz ellerinizdedir, 

haklı günler,
..........
..........', 'Türkiye işçi sınıfına selâm!  Selâm yaratana!  Tohumların tohumuna, serpilip gelişene selâm!  Bütün yemişler dallarınızdadır.  Beklenen günl...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/turkiye-isci-sinifina-selam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diabet ve Biz', 'diabet-ve-biz-gaffar-karadogan-mqyjo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diabetes mellitus

Beğendinmi yaptığını

Bozdun işte tüm metabolizmayı

Tesadüfen ortaya çıkışına ne demeli

Tesadüfler mi yönlendirecek hep hayatımızı

Gördük işte dibine bakarken gözün

Maküla çevresindeki sert eksüdaları

Birbiri ardına geliyor 

Vasküler komplikasyonlar

Ayakta yara, yürekte yara

Yürekteki yaranın ağrısı yok 

Görüntüsü vardı

Derin ve anlamlı bir Q şeklinde

Kabul etmiyorum

Diabetiklerin sınıflandırılmasını

Tek bir sınıfta toplanmışlar

Nasıl yaşamalıyız dersinde

Nasıl yaşamalıyız dersin be kardeşim

Şeker bile zarar veriyor bedenimize', 'Diabetes mellitus Beğendinmi yaptığını Bozdun işte tüm metabolizmayı Tesadüfen ortaya çıkışına ne demeli Tesadüfler mi yönlendirecek hep hay...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/diabet-ve-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisiz Ölünürmü', 'sevgisiz-olunurmu-merve-betul-ozsoy-9izdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgisiz bir dünya da ölmek istemiyorum

Bir zulüm  cehennemi kaynıyor üstümüzde

İnsanlık kuru  beyan merhamet karaborsa

Karanlık dehlizlerde inliyor hasta ruhlar

Ayak altı edilmiş  aşktan yana ne varsa

Omuzlar hamal olmuş kahır denilen yüke

Mertler yaslana dursun kuştüyü yastıklara

Zulüm boş meydanlarda arzı endam ediyor

Susmak elleri bağlı ağırıma gidiyor

        Güneşi rehin almış çöken kara bulutlar

        Gök yüzü kül renginde 

        Denizler mavi değil

Hayat veren ırmaklar kıpkırmızı akıyor

Analar sitem yüklü

Evlat ölüme sürgün

Gözyaşı içerdeki yangının habercisi

Ağıtlar;yüce kata sunulan bir dilekçe 

Elleri bağlar ama ruha geçmez bilekçe

Sevgisiz bir  dünyada ölmek istemiyorum

        Kaldırsın nurlu şafak

        Demirden nikabını

Ey! Taş yürekli devir sen sevgiye muhataçsın

Kınına girsin öfke namlular çiçek açsın

Çeksin şu hoyrat eller uğursuz gölgesini

Sevgi ile insanlık yoğrulsun yeni baştan

Yükselterek sevginin kardeşliğin sesini

Çıkalım nefret denen bu amansız savaştan

Sevgisiz bir dünya da ölmek istemiyorum

       Kan kokan coğrafyama

       Cemreler düşsün yine

Aşk  efsunlu  bir eldir onarsın kainatı

Sevgi;

Ebed nakışlı müjdesidir sonsuzun

Ezel kadar eskimez kıyamet kadar uzun

       Sevgi ile çözülür insan denen muamma

       Gül rengi duygularla

       Atiye yelken açar

Aşktan bihaber ruhlar kah akar kah durulur

Has duygular üstüne kanlı çarklar kurulur

         Rahmana kafa tutar 

         Bütün acizliğiyle

         Müstekbir başlarını secdeye koymayanlar

Devasa kaygılarla eremezler bir ömür

Bir gülü bir çocuğu sevmenin lezzetine

        Şeytan! Dostları ile dünyayı sömürürken

        Kahretsin kahhar  olan zulmü seyredenleri

Gamzeleri üşüyen  çocukların üstüne

Ölümsüz güneş  saçsın ışıktan tellerini

Karanlık dehlizlere uzaysın ellerini

Sevgisiz bir dünya da  ölmek istemiyorum', 'Sevgisiz bir dünya da ölmek istemiyorum Bir zulüm  cehennemi kaynıyor üstümüzde İnsanlık kuru  beyan merhamet karaborsa Karanlık dehlizlerde...', ARRAY['Türk Edebiyatı','Şiir','Merve Betül Özsoy']::text[], 8.5, '{"poet":"Merve Betül Özsoy","poet_slug":"merve-betul-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sevgisiz-olunurmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbetim Duygularıma', 'nobetim-duygularima-levent-kizildag-itpqb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu soğuk karanlık gecelerde

Yedi nolu devriye, topbaşı,

Şantiye ve kömürlükte

Tuttuğum her nöbette

Seninle yaşarım.

Elimdeki tüfek değil,

Senin elindir.

Uzaklardan gelen düdük sesleri

Nefesindir.

Kör karanlığı bir bıçak gibi kesen

Şeker fabrikasının gürültüsü

Sözlerindir.

			

10.01.1983', 'Şu soğuk karanlık gecelerde Yedi nolu devriye, topbaşı, Şantiye ve kömürlükte Tuttuğum her nöbette Seninle yaşarım. Elimdeki tüfek değil, Se...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nobetimde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Gün', 'yeni-bir-gun-levent-kizildag-1s36u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte yeni bir gün. 

Dün pazardı, 

Pazartesi bugün. 

Şu ağac, şu kaldırım taşı, 

Dün de oradaydı. 

Değisen yalnız 

Günlerin adları tarihleri, 

Takvimlerden duşen bir yaprak. 

Gidiyoruz ölüme 

Hergün bir adım daha atarak

			30.3.1982', 'İşte yeni bir gün.  Dün pazardı,  Pazartesi bugün.  Şu ağac, şu kaldırım taşı,  Dün de oradaydı.  Değisen yalnız  Günlerin adları tarihleri,...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeni-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isirgan Otu', 'isirgan-otu-levent-kizildag-7zc9r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir isirgan otu olmak isterdim.

Hayatta,

Kurudukca, yiprandikca

Her bahar yeniden cogalan

Oylesine aci veren

Oylesine dertsiz

Bir isirgan otu.

		26.04.1982', 'Bir isirgan otu olmak isterdim. Hayatta, Kurudukca, yiprandikca Her bahar yeniden cogalan Oylesine aci veren Oylesine dertsiz Bir isirgan ot...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isirgan-otu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-levent-kizildag-g2itw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi,

Sadece sarilmak degildir sevdigine

Sadece opmek.

Bir cift bakista da bulursun

Gonulden seversen

		24.03.1982', 'Sevgi, Sadece sarilmak degildir sevdigine Sadece opmek. Bir cift bakista da bulursun Gonulden seversen 		24.03.1982...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgi-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-levent-kizildag-e3kz6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve iste,

Duygularin en guzeliymis 

Bir tatli bakista isinmak.

Sevgilerin en guzeliymis

sevgin.

Heyecanlarin en guzeliymis 

O kacamaklarda

Annene yakalanmadan

opusmek.

Ve iste

Herseyin en guzeliymis

Benim oldugunu bilmek

Seni sevmek.

		14.08.1981', 'Ve iste, Duygularin en guzeliymis  Bir tatli bakista isinmak. Sevgilerin en guzeliymis sevgin. Heyecanlarin en guzeliymis  O kacamaklarda An...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-sevmek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozlem', 'ozlem-levent-kizildag-n81me', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artik gecmez gunler

Sensiz.

Hasret hergun artar.

Ama durmaz yasam

Yine de surer

Ben hep

Seni ozlerim

Seni ararim

Bu bir siir degil 

Sevgilim

Duygularim.

		15.06.1997', 'Artik gecmez gunler Sensiz. Hasret hergun artar. Ama durmaz yasam Yine de surer Ben hep Seni ozlerim Seni ararim Bu bir siir degil  Sevgilim...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlem-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın Beni', 'anlarsin-beni-mechul-yazar-puuxr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün susarsa seni benden alan ıslıklar,

O yeşil gözlü kumral çocuk giderse uzaklara,

Uzayan mevsimlerce tek başına kalırsan,

Yalnızlığa dökülürse gözlerinin yaprakları

Anlarsın Beni.......

Senin bana güldüğün gibi sana da gülerlerse,

Orta yerinden kırılırsa en ılık umutların,

Dudaklarında dinerse sevdiğin şarkılar,

Üstelik zaman buz keserse yelkovanlarda,

Anlarsın Beni.......

Taparcasına sevdiğin aynalardan kaçarsan,

Başkalaşan yüzün ürkütürse seni,

Bir hiç uğruna sonsuz özlem dolusu,

Uzağında kalırsan tüm sevdiklerinin...

Anlarsın Beni.......

Her akşam bakışların yaygınlaşırsa karanlığa,

Tren sesleri istasyonlarda büyürse tutkun,

Dönmemek acı yudum olursa kadehlerde,

Çaresiz mutluluk yalvarışlarına açılırsa ellerin,

Anlarsın Beni.......

......Ve bir zamanlar güldüklerin gelir aklına,

Hıçkıra hıçkıra ağlamak istersin

Ağlayamazsın.......

Anlarsın Beni.......', 'Bir gün susarsa seni benden alan ıslıklar, O yeşil gözlü kumral çocuk giderse uzaklara, Uzayan mevsimlerce tek başına kalırsan, Yalnızlığa d...', ARRAY['Türk Edebiyatı','Şiir','Meçhul Yazar']::text[], 8.5, '{"poet":"Meçhul Yazar","poet_slug":"mechul-yazar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlarsin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-erdal-sezer-bbmrp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalemimin yazdığı dilimin söylediği,

Beynimin bildiği tek kelime; sen

Umutlarımın yeşili, düşlerimin pembesi

Yarınımın özlemi yalnız sen!

Düşüncelerimin hayali sen,

Uykularımın rüyası, rüyalarımın adı sen

Sen yaşayamadığım geçmişim,

Yaşamak istediğim geleceğim,

Sen, sen, sen ve sen''ler arasında bir ben...', 'Kalemimin yazdığı dilimin söylediği, Beynimin bildiği tek kelime; sen Umutlarımın yeşili, düşlerimin pembesi Yarınımın özlemi yalnız sen! Dü...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sezer']::text[], 8.5, '{"poet":"Erdal Sezer","poet_slug":"erdal-sezer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-yamans-yaman-gdf3h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kuş olup derin maviliklerde yüzmek istiyorum,

Bulutların üzerinde güneşlemek,

Gökkuşağı ile raks etmek istiyorum.

Bir çağlayan olup köpürmek istiyorum,

Avazım çıktığı kadar bağırıp,

Öfkelenmek fışkırmak istiyorum.

Bir gözyaşı olup sessizce akmak istiyorum,

Sonsuz bir aşkla sevmek,

Severek sevilerek ölmek istiyorum...', 'Bir kuş olup derin maviliklerde yüzmek istiyorum, Bulutların üzerinde güneşlemek, Gökkuşağı ile raks etmek istiyorum. Bir çağlayan olup köpü...', ARRAY['Türk Edebiyatı','Şiir','Yamans Yaman']::text[], 8.5, '{"poet":"Yamans Yaman","poet_slug":"yamans-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandilli Hüzünleri', 'kandilli-huzunleri-duygu-yalcin-v3hsl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler anlar halimden

Uzun ve sessiz geceler

Gündüzler boş gelir

Kandilli parkının dayanılmaz hüznüyüm ben

Karanlık bankta tek başına oturan...

Martıların mesaisi bitmiş çekilmişler köşelerine

Bağırmıyorlar çığlık çığlığa

Paylaşmıyorlar yalnızlığımı

Karşımda Rumeli Hisarı, yanımda yalnızlığım

Yalnızken bile beceremedim tek başına olmayı

İçimde hep başkası...

Uzun ve karanlık şilepler geçer önümden

Adını hiçbir zaman okuyamadığım

Sessiz ve sakin geçer giderler

Yüreğimden kaç şilep geçti sayamadım

Kaç tanesi derinlere gömüldü,

Kaç tanesi yüreğime demirlendi ?

Yalnızlığım bile sıktı beni

Kandilli parkı anlamaz oldu halimi

Artık tek başına kabul etmiyor beni

'''' Mutlu ve aşkla '''' gel diyor

O yüzden gitmiyorum uzun zamandan beri... 

mart 2001 / ist', 'Geceler anlar halimden Uzun ve sessiz geceler Gündüzler boş gelir Kandilli parkının dayanılmaz hüznüyüm ben Karanlık bankta tek başına otura...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kandilli-huzunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Duyguları', 'sonbahar-duygulari-i-brahim-kilinc-uyggi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonbahar hüzünü çökmüş gönlüme.

Bir bahar sevinci arar gezerim.

Sorarım sorarım, cevap yok yine

Usanmaz bir daha sorar gezerim

Yağmur var, bulut var, ve fırtınalar.

Yer ıslak, dal ıslak, gözümde yaşlar.

Bitirmek isterim, yeniden başlar.

Derdime bir derman arar gezerim.

Bu hayat yoluna çıktım çıkalı 

Hem yazı gördüm ben, hem de baharı.

Sonbahar sevdası daha manalı

Koklamaz gülümü, çağlar gezerim

Bu gönül sevdaya düşse ne çıkar.

Sevgili bilmese, bilse ne çıkar.

Önü kar, önü kış, mevsim sonbahar.

Ağaran saçımı yolar gezerim.', 'Sonbahar hüzünü çökmüş gönlüme. Bir bahar sevinci arar gezerim. Sorarım sorarım, cevap yok yine Usanmaz bir daha sorar gezerim Yağmur var, b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-duygulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Hasret', 'ask-ve-hasret-erdal-sezer-dibj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağları dizdim tek tek önüme,

Karşılarına da koydum aşkımı ,

Dağlar öylesine küçüldüler ki,

Elime alıp taş diye atabilirdim onları...

Denizleri koydum tek tek önüme,

Karşılarına da diktim hasretini,

Denizler öylesine küçüldüler ki,

Bir yudumda su diye içebilirdim onları...', 'Dağları dizdim tek tek önüme, Karşılarına da koydum aşkımı , Dağlar öylesine küçüldüler ki, Elime alıp taş diye atabilirdim onları... Denizl...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sezer']::text[], 8.5, '{"poet":"Erdal Sezer","poet_slug":"erdal-sezer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-ve-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilseydim', 'bilseydim-ramazan-yalcin-90k37', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilseydim,

Satardım bir umuda,

Tüm gerçeklerimi.

Yükleyip,

Bir martının kanadında,

Bulutlara tutunmak için

Hafiflerdim,

Umutlarla.

Kara, kapkara ufuklarda,

Pembeyi

Pembemi,

Yaratmak için;

Satardım bir umuda,

Tüm gerçeklerimi.', 'Bilseydim, Satardım bir umuda, Tüm gerçeklerimi. Yükleyip, Bir martının kanadında, Bulutlara tutunmak için Hafiflerdim, Umutlarla. Kara, kap...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Yalçın']::text[], 8.5, '{"poet":"Ramazan Yalçın","poet_slug":"ramazan-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bilseydim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Sahte Aşık', 'i-ki-sahte-asik-eda-karaoglu-3kgm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman insanı sadece avutur

Ümitse acı dönemini uzatır

Bir zamanlar seni düşünerek,ümit etmek 

Benim için çok şeydi 

Her şey gibiydi...

Aslında gerçekte seni düşünmekle

Seni seviyorum demekle

Bir şey söylemiş olmuyordum

Çünkü aşk bizim için bir oyundu 

Ve biz bu oyunda çoktan yerimizi almıştık

Yalnızca iki sahte aşıktık

Birbirini sever görünen iki aşık 

Ama aynı zamanda sahte

Yanyanayken bile birbirini hissedemeyen iki sevgili

Rollerimizi öyle iyi ezberlemiştik 

Sahteliğimizin içine öyle iyi saklanmıştık ki...

Böylece her sahnede gerçek bizden

Biraz daha uzaklaşıyorduk

Sahnenin  dışına çıkmak için

Öylesine çabalıyor ve öylesine çırpınıyorduk ki...

Adeta kapana kısılmış hain bir pusuya yakalanmış gibiydik.

Artık birbirimize yetmediğimizi biliyor

Ancak gerçekliğimizle yüzleşemiyorduk

Bir gerçek vardı 

O da biz biz değildik

Bir sahnede gerçeklerin verdiği acıdan

 kaçan firarlar olmuştuk 

Sahteliğimizin verdiği o kısa ve yalan hazza 

gerçekliğimizi değişiyorduk.

Bu kör sahteliğin içine kendimizi öyle mahkum etmiş

Öylesine nasırlaştırmıştık ki yüreklerimizi...

Artık oynadığımız bu sahtelik bile yetmez olmuştu bize

Biz biz değildik 

Ve biz nereye gidiyorduk?', 'Zaman insanı sadece avutur Ümitse acı dönemini uzatır Bir zamanlar seni düşünerek,ümit etmek  Benim için çok şeydi  Her şey gibiydi... Aslın...', ARRAY['Türk Edebiyatı','Şiir','Eda Karaoğlu']::text[], 8.5, '{"poet":"Eda Karaoğlu","poet_slug":"eda-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/iki-sahte-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgime İyan', 'sevgime-i-yan-havva-gulkan-cnrwt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretin yüreğimi dağlasada,

Gözlerim durmadan ağlasada,

Şunu bilki sana dur demiyeceğim.

Bedenimde canımsın damarımda kanım

Sen isteseydin olurdum kulun,kadının,

Özleminden bedenimden çıksada canım

Şunu bilki sana gel demiyeceğim.

Sensiz günüm zindan olsada,

Kalbime ayrılık acısı dolsada,

Bedenimden ruhumu alsanda,

Şunu bilki sana sev demiyeceğim.', 'Hasretin yüreğimi dağlasada, Gözlerim durmadan ağlasada, Şunu bilki sana dur demiyeceğim. Bedenimde canımsın damarımda kanım Sen isteseydin ...', ARRAY['Türk Edebiyatı','Şiir','Havva Gülkan']::text[], 8.5, '{"poet":"Havva Gülkan","poet_slug":"havva-gulkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgime-iyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-havva-gulkan-29dz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün daha bitti,

Bak akşam oldu,

Hasretinle, özleminle,

Karanlığa gömüldüm işte.

Ne bir mevsimim var ,

Nede bir dostum,

Sensiz ben benimle yine,

Yanlızlığa gömüldüm işte.

Hasretin sardı içimi,

Kanıyor hep yaram

Elimde kaldı son siğaram

Yine dumanına karıştım işte.', 'Bir gün daha bitti, Bak akşam oldu, Hasretinle, özleminle, Karanlığa gömüldüm işte. Ne bir mevsimim var , Nede bir dostum, Sensiz ben beniml...', ARRAY['Türk Edebiyatı','Şiir','Havva Gülkan']::text[], 8.5, '{"poet":"Havva Gülkan","poet_slug":"havva-gulkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Ver', 'selam-ver-ustun-dokmen-gc66e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yola çıkınca her sabah,

bulutlara selam ver.

taşlara, kuşlara,

atlara, otlara,

insanlara selam ver.

ne görürsen selam ver.

sonra  çıkarıp cebinden aynanı,

bir selamda kendine ver.

hatırın kalmasınel gün yanında.

bu dünyada sen de varsın!

üleştir dostluğunu varlığa,

bir kısmı seni de sarsın...', 'yola çıkınca her sabah, bulutlara selam ver. taşlara, kuşlara, atlara, otlara, insanlara selam ver. ne görürsen selam ver. sonra  çıkarıp ce...', ARRAY['Türk Edebiyatı','Şiir','Üstün Dökmen']::text[], 8.5, '{"poet":"Üstün Dökmen","poet_slug":"ustun-dokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/selam-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Başlamayacaktı...', 'ya-baslamayacakti-aytekin-gezici-vh2iz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Odamdayım

Soğuk, karanlık, üşüyorum.

Ya hiç başlamayacaktı bu aşk

Ya da hiç bitmeyecekti', 'Odamdayım Soğuk, karanlık, üşüyorum. Ya hiç başlamayacaktı bu aşk Ya da hiç bitmeyecekti...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Gezici']::text[], 8.5, '{"poet":"Aytekin Gezici","poet_slug":"aytekin-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ya-baslamayacakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Kollarımdan', 'tut-kollarimdan-basri-erkan-63mab', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sabah solmuş,beyaz yüzümde ellerinin şefkatli okşayışlarını bekleyeceğim 

Tümyüreğinle,aşkınla 

Dudaklarımdan beni sımsıcak öpmeni isteyeceğim 

Varlığınla,arzunla... 

Ve ben o an,erişilmesi güç yıldızlara yükseleceğim. 

Yükseleceğimm 

Yokluğunda onlara tutunacağım 

Güneşin kavurucu sıcaklığında yanacağım 

Ve ben güneşi sevgilim diye seveceğim. 

Biliyorum,biliyoruummm 

Firardaydı,firarda 

Suçların en suçsuzunu işledi 

Ateşlerin en yakıcı ve parlak olanında yalınayak yürüdü 

Ve bu gönül müebbett yedii. 

Ve artık herşey... 

Bitiyor,herşeyy bitiyooor 

Tükeniyor hasretimden,canevimden,ocağımdan 

Sendeleye sendeleye bu hayat yokuşunda... 

Düşeceğim,düşeceğimm tut kollarımdann.', 'Bir sabah solmuş,beyaz yüzümde ellerinin şefkatli okşayışlarını bekleyeceğim  Tümyüreğinle,aşkınla  Dudaklarımdan beni sımsıcak öpmeni istey...', ARRAY['Türk Edebiyatı','Şiir','Basri Erkan']::text[], 8.5, '{"poet":"Basri Erkan","poet_slug":"basri-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tut-kollarimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümidini Kırma', 'umidini-kirma-abdullah-gokhan-konbul-l38uv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevdik ikimizde delice sevdik

ummadık hasret bilmedik ayrılık

kaderin önüne geçilmez artık

şimdi sadece umutla kaldık

ümidini kırma sevmedin boş yere

üzülüp ağlama sakın delice

kötü günler kalır bir gün geride

senide benide kurtarır bugün', 'sevdik ikimizde delice sevdik ummadık hasret bilmedik ayrılık kaderin önüne geçilmez artık şimdi sadece umutla kaldık ümidini kırma sevmedin...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gökhan Konbul']::text[], 8.5, '{"poet":"Abdullah Gökhan Konbul","poet_slug":"abdullah-gokhan-konbul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umidini-kirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Dudaklarımda', 'bir-siir-dudaklarimda-abacan-askisev-senkal-j1jxj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şiir dudaklarımda;

Bir şiir ki yalnızlık dolu.

Özlem dolu mutluluğa,

Sevgiye hasret, acı dolu...

Bir şiir dudaklarımda;

Çok çok eskilerden!

Sessizlikle iç içe,

Karanlık gecelerden...

Bir şiir dudaklarımda;

Duygu dolu, aşk dolu!

Hiç kimseye söylenmemiş,

Belki de hiç söylenmeyecek...

Bir şiir dudaklarımda;

Sadece benim olan!

Eski mutlu yıllardan,

Aşktan, sevgiden, hayattan,

Geriye son kalan

Bir şiir dudaklarımda...', 'Bir şiir dudaklarımda; Bir şiir ki yalnızlık dolu. Özlem dolu mutluluğa, Sevgiye hasret, acı dolu... Bir şiir dudaklarımda; Çok çok eskilerd...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-siir-dudaklarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unutma Sakın', 'beni-unutma-sakin-abacan-askisev-senkal-ydgwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayallerim vardı benim;

Ümitlerim yaşıyordu dün.

Gözlerimden okunan mutluluk,

Dolu dolu sevgiydi kalbim...

Beni terkettiğin güne dek,

Tozpembe gördüm geleceği,

Bilemedim seni kaybedeceğimi

Ve herşeyimin yiteceğini...

Çünkü delice sevmiştim seni;

Seni anlayamadım belki,

Veya anlatamadım kendimi.

Hata yalnızca bendim belki,

Ama gerçekten sevmiştim seni...

O soğuk, karanlık kış günü,

Yaşadım ayrılığın hüznünü!

Beni daima hatırla, unutma sakın,

Sevgim, resmim sende kalsın,

Birer hatıra diye saklarsın.

Belki beni  tebessümle anar,

Belki de için için ağlarsın...', 'Hayallerim vardı benim; Ümitlerim yaşıyordu dün. Gözlerimden okunan mutluluk, Dolu dolu sevgiydi kalbim... Beni terkettiğin güne dek, Tozpem...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-unutma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Yarınlar', 'kaybolan-yarinlar-abacan-askisev-senkal-h5gzs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaybolmuş anılarım,

Kaybolmuş hatıralar.

Özlemle, umutla dolu,

Kaybolan yıllar...

Kaybolmuş kitaplarım,

Bomboş şimdi raflar.

Kimbilir nerede saklı,

Kaybolan sayfalar...

Tozlanmış resimlerim,

Silinmiş benden kalanlar.

Artık herbiri başka yerde,

Daha dün benim olanlar...

Unutmuş sevdiklerim,

Yırtılmış mektuplar.

Yok ki, hiç arayanım,

Sır olmuş eski dostlar...

Kapanmış tüm yollarım,

Gözlerimde yaşlar.

Titreyen dudaklarımda,

Son bulur damlalar...

Kaybolmuş hayallerim,

Karanlık şimdi ufuklar.

Ümitlerim dünde kaldı,

Kayboldu yarınlar...', 'Kaybolmuş anılarım, Kaybolmuş hatıralar. Özlemle, umutla dolu, Kaybolan yıllar... Kaybolmuş kitaplarım, Bomboş şimdi raflar. Kimbilir nerede...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kaybolan-yarinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pretends Cieux', 'pretends-cieux-sair-baraka-0wb34', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pretends cieux

Je te le dis moi tout

Jeune et brumeux

Curieux et douteux

Le geste genial en tete

Brave visionnaire

Commande une allure

Tout roi tout ulema

Tout fakir tout dervishe

Tout rumi tout krisna

A ces pays ou la ville

Saint de tout empire

Se rayonne dans la sofia

Dans la sagesse murie

A l instar de nuits

Des sables mouvant

D embacadaires

du bosphore manic

Et votre humble 

Vers la bas a l orient

D ou nait le soleil

D ou vient la lumiere

Un air dedain sure

Un regard conquerant

Un retour glorieux

Une conquete lumineuse

Comme jamais promise

Comme jamais dite

Ni par soliman

Ni par darius

Ni par alexandre

Ni cesar

Ni Antoine agonisant

Dans les bras d adrian 

Ni socrate ni adrogen

N a su s y aventurer

Eh bien alors

Que cela se tient

A un va

Quo va

Que y a t il tant que ça

Toute la lumiere

De la bas au mistral

Y coule profondement

Quel l astuce du doute

Quel l alchimie de l amour

Quel le moulin aux milles potence 

Tant de l elegance

Tant de l art

Tant de l aristo

Tant de la cratie

Tant de la rose

S y fondu

S y forme

S y cree

S y s anime

Qui s aime

Que la beaute

Que l intelligence

Que l imagination

D acttion

A son altesse service

Quelle est la science

A tout ces bonheurs

Et bien voila

Ronronnant le doute

Aborde la seine

Sur les bords

Fete le bal des ginettes

Avec les meteques

Joueur de l echec

A l oriente

Jettant les des

A la turca

A ce dessein

En se foutant

De ces dits

D antant

De ces lies souffreuses

Des vecus des autres

Des ces regrets

Empiete le mont

De notre mere bien aime

Que de livres

Que de theatres

Que de agores

Que de savants

Que de philosophes

S agenouilles 

Dans les terrasses

Dans les cours

Sur les quais

Aux tuilleries

Cote le menage

Au dos la grand roue

Et bien tout compris

Se murmure 

le paradis

Est la

Nest ce pas que la joie

Du grand bonheur

Se cahche a l est de l eden

A notre droite de gaucher

Du coup voila

Un tigerlilly empapionne 

Sous le ciel de paris

Pensant que ce semi fe

Sera guide vers le copain

A peter toute envie

L attendais a la gare

A la bouche du metro

Devant les catherdales

Tu sais celui

Que l on appelle

Peter pan pet

De ce jour a ce jour

S enivrent la valse

Des amis des pans

Et moi au devant

Gueulant a l amour

A l homme

A tiger lily

A peter pan

A l aura divin

A l or en pain

A toi simple

Ami

Mon ami

Bien venu

Parmi nous

Les amants des semifees

Gros gros bisous

Comme la tour eiffel

A ces quatres

Peterpanlarıma.......', 'Pretends cieux Je te le dis moi tout Jeune et brumeux Curieux et douteux Le geste genial en tete Brave visionnaire Commande une allure Tout ...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":135,"source_url":"https://www.antoloji.com/pretends-cieux-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalga Sesleri', 'dalga-sesleri-abacan-askisev-senkal-0j4yo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haykıran dalga seslerini dinlerken,

Bir karanlık gece, yapayalnız seninle!

Denizin kokusunu içime çekerken,

Tatlı bir huzur arıyorum bu gece...

Hırçın deniz dalgalı, ben dalgalı deniz,

Kumsalda soğuk yel, yanımda sen!

Karanlık gecenin içinde birlikteyiz,

Gökyüzünde yıldızlar, kalbimde sen...

Gecenin o sessizliğinde savunmasız,

Islak kumlarda bir şeylerin izleri!

Gölgeler sarmaş dolaş, gamsız tasasız,

Kayalarda yankılanır dalga sesleri...

Bir karanlık gece yapayalnız seninle,

Akdeniz''de serin bir bahar mevsimi.

Fırtınalı ruhumun derinliklerinde,

Kulaklarımda çınlar, o dalga sesleri...', 'Haykıran dalga seslerini dinlerken, Bir karanlık gece, yapayalnız seninle! Denizin kokusunu içime çekerken, Tatlı bir huzur arıyorum bu gece...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalga-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur İçinde Uyu', 'huzur-i-cinde-uyu-abacan-askisev-senkal-6xz5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam olur, heryerde canlanır geçmişten izler,

Karanlıklarda eski yılların cezbeden kokusu.

Neşe dolu, kimi zaman hüzünlü nice sözler,

Dağların sığmadığı koca gönüller dolusu...

Dudakta hep taze duruyor o sevgiliden izler,

Bir nehir çağıldar enginde, daima berrak suyu.

Aşkın ateşini derinlerinde gördüğüm gözler,

Dünyaya kapandı artık, huzur içinde uyu!', 'Akşam olur, heryerde canlanır geçmişten izler, Karanlıklarda eski yılların cezbeden kokusu. Neşe dolu, kimi zaman hüzünlü nice sözler, Dağla...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzur-icinde-uyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-gulseren-onay-8qmxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep bir son vardır,

Ölüm yaşamın,

Nefret sevginin,

Hüzün sevincin,

Vuslat sa hasretin.....

Hep bir son vardır,

Söylenecek son bir söz,

Söylenmek istemez

Ama söyleniverir bir anda,

Elveda......

(28.03.2001/ANTALYA)', 'Hep bir son vardır, Ölüm yaşamın, Nefret sevginin, Hüzün sevincin, Vuslat sa hasretin..... Hep bir son vardır, Söylenecek son bir söz, Söyle...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-soz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-umit-bahadir-n7ys3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün  gece uyandığımda

Gecenin bir yerinde

Saat ikide

Balkonda  gökyüzünün   pırıl, pırıl   berrak  olduğunu  gördüm

Bir şey  daha  gördüm

Yanıp,  yanıp  sönen 

İki  yıldızın  bana  gülümsediğini  gördüm

Gördüğüm bunlarla sınırlı  değildi

Kar  gibi beyaz  üzerinde siyah  tonları  olan  Ay   ı gördüm

Ne  güzel de  aydınlatıyordu   odayı perdenin aralığında  süzülen ışık

Bir  de   bahçede  bulunan   vişne  ağaçlarının  yeni  açmış çiçeklerinin  yerdeki  gölgelerini  gördüm

Ellerimi  kanat yaptım gökyüzüne uçmak için değil

Ayı , yıldızı,  pırıl, pırıl   berrak  gökyüzünü  kucaklamak için

Tutmak istedim 

 Yeni açılmış   vişne  çiçeklerinin  yerdeki gölgelerini 

Kucaklayamadı  kollarım  ayı   yıldızı   ve  güneşi

Tutamadı  parmaklarım   vişne çiçeklerinin  gölgelerini ama

Kalbim   aklım fikrim  kucakladı

Hem de  aşkla  şevkle   heyecanla

birde   gururla  önemseyerek', 'Dün  gece uyandığımda Gecenin bir yerinde Saat ikide Balkonda  gökyüzünün   pırıl, pırıl   berrak  olduğunu  gördüm Bir şey  daha  gördüm Ya...', ARRAY['Türk Edebiyatı','Şiir','Ümit Bahadır']::text[], 8.5, '{"poet":"Ümit Bahadır","poet_slug":"umit-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dun-gece-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Bitimi', 'gun-bitimi-durmus-akil-hrebl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün bitityor, birileri gidiyor buradan.

Birileri bu şehri terk ediyor.

Biliyorum birileri aldatıyor insanları

Kimisi ağlıyor;kimisi gülüyor.

Çaresizce yaşıyorsun kendince yanlızlığını.

Ayrılıkları gösteriyor isimsiz sevdaların,

ya da sevda sandıkların öylesine yaşanan.

Sen bilmiyorsun benim seni sevdiğimi.

Ben biliyorum; seni seviyorum.', 'Gün bitityor, birileri gidiyor buradan. Birileri bu şehri terk ediyor. Biliyorum birileri aldatıyor insanları Kimisi ağlıyor;kimisi gülüyor....', ARRAY['Türk Edebiyatı','Şiir','Durmuş Akıl']::text[], 8.5, '{"poet":"Durmuş Akıl","poet_slug":"durmus-akil","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gun-bitimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Kadar', 'ozlemin-kadar-nihat-behram-fzht5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güzelim;

  serçelermi taşıdı sana, 

    çimen çimen, 

       karadut oyası 

           zülüflerini.

çigdem tüten gamzeleri

  omuzlarına kırdan mı sardın?

yadellerden esen yelde 

   sevdalın mı var?

    unutma,

       hicbir şey yakışmıyor kalbime', 'güzelim;   serçelermi taşıdı sana,      çimen çimen,         karadut oyası             zülüflerini. çigdem tüten gamzeleri   omuzlarına kırd...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozlemin-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Ormanları', 'dus-ormanlari-eren-zeki-nalbant-ijbq5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düş ormanlarında yürüyorum

pervasızca

seni mi arıyorum

yoksa bahane ederek kendimi mi?

yaprak hışırtıları

ayak sesleri

su çağıltısı..

derin bir sessizlik

düşüyorum

bir uçurumdan düşer gibi

uçuyorum

yeni uçmayı öğrenen bir kuş gibi

görüyorum

sanki ilk kez görüyorum

sensizliğin sessizliğini duyuyorum

düş ormanlarında geziyorum

pervasızca

seni mi arıyorum

yoksa bahane ederek kendimi mi

bilmiyorum', 'Düş ormanlarında yürüyorum pervasızca seni mi arıyorum yoksa bahane ederek kendimi mi? yaprak hışırtıları ayak sesleri su çağıltısı.. derin ...', ARRAY['Türk Edebiyatı','Şiir','Eren Zeki Nalbant']::text[], 8.5, '{"poet":"Eren Zeki Nalbant","poet_slug":"eren-zeki-nalbant","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dus-ormanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hi', 'hi-sair-baraka-xyrhe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'The ages

Countless

a sea of possibilities

Adrift in this seething 

stream of untold dreams

a lock and a key 

would meet by chance

If I got my key 

how could I deny 

my love for hu

do love you 

as 

I did the first day 

I met you 

Herşey gönlünce olsun

yeni bir dönem

yeni bir proje,

üçüncü binyıla girerken 

yeni bir rüya 

anlatmak isterdim 

ama 

nasıl 

o 

kadar

uzaktasinki

inan ama inan 

seni çok özledim

Tu avait dit

Reasons mean 

the cause of an event

the explanation

or

excuse of an action

so

it is the power to think

understand 

and 

form opinions 

that is an unavoidable choice

Alors 

Opinions are ever changing

twisting 

and 

evolving.

Although my opinion of you 

IS 

in fact 

EVER

twisting

and

evolving 

it is NEVER

changing

I love you 

with 

all my heart 

and 

will NEVER

forget you

I hope you can say

the same

ya maitre

ya çare

A votre altesse

Oui bien entendu

Ya hu ya hu', 'The ages Countless a sea of possibilities Adrift in this seething  stream of untold dreams a lock and a key  would meet by chance If I got m...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/hi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülü Sevdim', 'bir-gulu-sevdim-ahmet-selcuk-i-lkan-gsidf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu son buluşmamız

Bu son görüşmemiz

Kimbilir bir daha karşılaşmayız

Belkide bir daha görüşemeyiz

Ayrılmalıyız ayrılmalıyız

Bir gülü sevdim

Bir seni sevdim

Bir mevsimlikmiş senle aşkımız

Gel gitme desem kal etme desem

Hiç faydası yok ayrılmalıyız

Senin gözlerin yaşlı

Benim yüreğim yaslı

Bu aşkta bir umut kalmadı yazık

Seni bir başkası bekliyor artık

Ayrılmalıyız ayrılmalıyız', 'Bu son buluşmamız Bu son görüşmemiz Kimbilir bir daha karşılaşmayız Belkide bir daha görüşemeyiz Ayrılmalıyız ayrılmalıyız Bir gülü sevdim B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-gulu-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Sesi', 'yagmurun-sesi-ferhat-topkaya-6fsej', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılığı kollayan zaman mıydı

	Sessizleştiren seni? 

Sorularıma bilinmez yanıtlar yakıştırdın.

Git desen, gidecektim; 

Kal desen…

Bak! 

Bu gece de yağmur yağıyor,

Hem de avazı çıktığı kadar.

Sessizliğin içinden yükselen acı sesi,

Yankılanıyor kulaklarımda.

Sorularımın yanıtı gizli her bir damlasında…

Ayrılığı kollayan, 

zamandı…

Susuşlarında yükselen, 

yağmurun sesi…

Ve ben biliyorum artık cevabını tüm sorunlarımın.

Dışarıda yağmur yağıyor.

Deliksiz boşalıyor bardaktan; 

Teninin tenime karıştığı bu an,

Terim değil bu sefer

	Gözyaşlarımdı terine karışan,

	Hissediyorum.

…

Bu gece…

Bu gece yağmur hiç dinmeyecek anlaşılan…

Hep biliyordun,

	Bilmiyordum…

(23-26  Mart 2001)', 'Ayrılığı kollayan zaman mıydı 	Sessizleştiren seni?  Sorularıma bilinmez yanıtlar yakıştırdın. Git desen, gidecektim;  Kal desen… Bak!  Bu g...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Topkaya']::text[], 8.5, '{"poet":"Ferhat Topkaya","poet_slug":"ferhat-topkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yagmurun-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa kısa', 'kisa-kisa-ferhat-topkaya-gcw2u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana gitme diyebilirdim,

Gelmiş olsaydın eğer...

(25 Mart 2001)', 'Sana gitme diyebilirdim, Gelmiş olsaydın eğer... (25 Mart 2001)...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Topkaya']::text[], 8.5, '{"poet":"Ferhat Topkaya","poet_slug":"ferhat-topkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kisa-kisa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğime İlk Şiir', 'bebegime-i-lk-siir-akin-simsek-eybub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni bekliyoruz bebeğim

Annenle ben umutla sevgiyle

Kolay oldu sanma beklemek

İlk öğrendiğimiz gün başladı

Her kıpırdanışın tekmelemen

Annende tatlı bir sızı

Bende anlatılmaz bir heyecanla

Bekledik bebeğim işte böyle

Artık sen vardın hayatımızda

Dünyaya gelmeden bağladın bizi

Kendine hayata senin hayatına

Geleceksin az kaldı

İşte o zaman yeni bir hayat

Sesini duymayı bile beklemek

Annenede banada bir bilsen

Ne demek bebeğim seni beklemek

Bekliyoruz bebeğim seni sesini

O ilk ağlamanı bekliyoruz

Ama en çok kim biliyormusun

Seni kim hakketti bebeğim

Seni karnında taşıyan besleyen

Hayatını her şeyini seninle paylaşan

Annen tabiiki bebeğim annen', 'Seni bekliyoruz bebeğim Annenle ben umutla sevgiyle Kolay oldu sanma beklemek İlk öğrendiğimiz gün başladı Her kıpırdanışın tekmelemen Annen...', ARRAY['Türk Edebiyatı','Şiir','Akın Şimşek']::text[], 8.5, '{"poet":"Akın Şimşek","poet_slug":"akin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bebegime-ilk-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim', 'hayallerim-akin-simsek-m80lw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bir gece

Saat tam yirmi dört

Hayallerimde sen

Seninle bir de ben

Seni düşünüyorum

Şiir yazmak istiyorum

Ellerim kanarcasına

Gözlerim uykudan kapanırcasına

Yazmak istiyorum sana

Seni özlüyorum

Seni istiyorum

Çünkü seni seviyorum

Mümkün olsa şu anda yanında olsam

Sana sarılabilsem doya doya

Çılgıncasına sarılabilsem

Dansetsek gecenin sessizliğinde

Biliyorum duyarız o melodileri

Yaşarız en içten sevgileri

Engin denizler gibi coşar

Irmaklar gibi çağlarız

Biliyorum sevgilim yanımda olsan

Meltemi andırır ılık nefesin

Yaz güneşi gibidir sıcacık tenin

Kılavuzum olur ellerin

Gözlerime bakar utangaç gözlerin

İşte yine bir gece yarısı

Seni hayal ederim', 'Yine sensiz bir gece Saat tam yirmi dört Hayallerimde sen Seninle bir de ben Seni düşünüyorum Şiir yazmak istiyorum Ellerim kanarcasına Gözl...', ARRAY['Türk Edebiyatı','Şiir','Akın Şimşek']::text[], 8.5, '{"poet":"Akın Şimşek","poet_slug":"akin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayallerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemezsin', 'gidemezsin-eshabil-kirisci-al1rj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akıvermiş gönlüm sana 

İstesende silemezsin 

Güneş kadar sıcağı ben 

Söndürüpte gidemezsin

Bugün varsam senin için 

Yarın yoksam kimin için

Benim bunda yokki suçum 

Günah olur gidemezsin

Sen nekadar gidem desen

Gözün kalır gidemezsin 

Sensiz yapamam bilirsin 

Bana kıyıp gidemezsin

Sen nerdeysen ordayım ben 

Kurtuluş yok inan benden 

Alnıma yazmış yaradan

Kaderin bu gidemezsin

Bu sevgide tek değilim

İnkar etme sende sevdin

Beni bırakıp çaresiz 

Yanlızlığa gidemezsin

  29/03/2000', 'Akıvermiş gönlüm sana  İstesende silemezsin  Güneş kadar sıcağı ben  Söndürüpte gidemezsin Bugün varsam senin için  Yarın yoksam kimin için ...', ARRAY['Türk Edebiyatı','Şiir','Eshabil Kirişçi']::text[], 8.5, '{"poet":"Eshabil Kirişçi","poet_slug":"eshabil-kirisci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandı Gönlüm', 'yandi-gonlum-eshabil-kirisci-lfh4c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostça başladı herşey

Ne yapayım yandı gönlüm

Sen nekadar olmaz desen 

Sönmez artık yandı gönlüm

Sensiz dünyam bir hoş oldu 

Bir hoş oldu bomboş oldu

Göz yaşlarım sırdaş oldu 

Bir zalime kondu gönlüm

Benim aşkım yaşanmadı

Yaşanmadı böyle sevda

Mecnun bile ağlar idi 

Bir leylaya kandı gönlüm

Sözüm geçseydi gönlüme 

Severmiydim seni söyle

İnsaf ette bir evet de

Açamadan soldu gönlüm

04/04/2000', 'Dostça başladı herşey Ne yapayım yandı gönlüm Sen nekadar olmaz desen  Sönmez artık yandı gönlüm Sensiz dünyam bir hoş oldu  Bir hoş oldu bo...', ARRAY['Türk Edebiyatı','Şiir','Eshabil Kirişçi']::text[], 8.5, '{"poet":"Eshabil Kirişçi","poet_slug":"eshabil-kirisci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yandi-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-veli-yilmaz-jcppv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tenim Toprak Olsada

Ruhum Seni Sevecek

İnan Mahşerde Bile

Göz Yaşım Dinmiyecek

Gözümü Sende Açtım

Hiç Kimseyi Sevemem

İnan Senden Başkasına

Ben Sevgilim Diyemem

Ne Meyhane,Ne şarap

Vermiyor Bana Teselli

Dünyamı Kaybettim

Senden Ayrı Düşeli', 'Tenim Toprak Olsada Ruhum Seni Sevecek İnan Mahşerde Bile Göz Yaşım Dinmiyecek Gözümü Sende Açtım Hiç Kimseyi Sevemem İnan Senden Başkasına ...', ARRAY['Türk Edebiyatı','Şiir','Veli Yılmaz']::text[], 8.5, '{"poet":"Veli Yılmaz","poet_slug":"veli-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelenim''e', 'kardelenim-e-ahmet-temel-h03x7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım! seni Niagara şelalesinin çağıltıları gibi gürültülü değil

Amazonun dingin akan suları gibi sessiz bir büyüklükle seviyorum!..

Ey benim kara gözlüm kara saçlım

Karlı dağlarda açan kardelenim

Başı eğilmeyen vakur çiçeğim

Kalbimde mahpus hilal kaşlım

Müjdeyle doludur benim için her an 

Seni düşündüğüm an yanımdasın

Bize işlemez zaman ve mekan

Damarlarımda dolaşan kanımdasın

İsmini şiirlere kazıdım 

Seni yüreğime

Sen artık orada mahpussun

Çıkamazsın istesen bile

Ne zaman diye sorma vuslat

Vuslat sonudur sevdanın 

Sevda yanımdan geldi bana yine zaman

Bedenin değil ruhun benim dermanım 

Engin deryalara açılsan da;

Sen her zaman oradasın

Orası sana ait

Sense oraya hasret

Merhaba diyeceğin günün özlemini

Belki her zaman çekecegim

Ama sunu bil ki kardelen çiçeğim

Ben seni hep sessiz bir büyüklükle seveceğim,

                     11 Ekim 1983     03:33', 'Canım! seni Niagara şelalesinin çağıltıları gibi gürültülü değil Amazonun dingin akan suları gibi sessiz bir büyüklükle seviyorum!.. Ey beni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Temel']::text[], 8.5, '{"poet":"Ahmet Temel","poet_slug":"ahmet-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kardelenim-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Muhabbetimiz', 'hani-muhabbetimiz-zubeyde-basaran-p6udm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani varlığınızın bulunduğu yer

O bulunmaz dostluğumuz varya

Müzmin ruh haliniz hani, gözyaşlarınız

Sizinlemi hep döner bulunduğunuz diyara

Avare mi? olur boş tenhalarda

Nerdesin  mühür bakışlı, hançer kalpli,

ver artık  eski hasvetli, ruh halini, dönsün bırak

yer edinmesin  ruhun içine işlerlik kazanmasın!

Sevgin  muhabbet peşkeşiyle gelsin bizlere 

Dostane gönlünüz susamış ruhlarımıza artık

Bırakında muhabbet bulsun.....

Yokken de var olan Musa HOCAMIZA......', 'Hani varlığınızın bulunduğu yer O bulunmaz dostluğumuz varya Müzmin ruh haliniz hani, gözyaşlarınız Sizinlemi hep döner bulunduğunuz diyara ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-muhabbetimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dostum', 'can-dostum-unal-bulut-y4p3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerdesin can dostum! yollarda kaldı gözlerim

Görüşelim, alemi gözlerimde elerim,

İzledin değil mi benim gibiler nasıldı?

Hepsinin yarenliği üç günlük fasıldı

Halime gelirsin diye yataklara düştüm

Bu düşünce hatrına beşerlerle sürtüştüm

Görmezler, ayaktakiler bakabilen ãma

Başımda bekleşenler ziyarteçi yanılma..

İçinde süründüğüm üstü açık mağara

Firar değilsin, ayılara yem olanlara

Bu küflenmiş yerden nereye taşınacagım?

Müjdeleri haber ver, sana sığınacağım

Son misafir ol, beden acizliğe aklamadan

Gidelim buralardan arkamıza bakmadan

Nerdesin can dostum!. harab oldu cansız yarım

Yanlız adın var, sensizlik doldu anılarım', 'Nerdesin can dostum! yollarda kaldı gözlerim Görüşelim, alemi gözlerimde elerim, İzledin değil mi benim gibiler nasıldı? Hepsinin yarenliği ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/can-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryad', 'feryad-unal-bulut-pvc45', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canını sıkma, elbet gelir geçer bu elem,

Koşup geleyim ilaç olacağımı bilsem

Dertsizim diyebilir misin dertli dünyada ?

Dertlerinden vazgeçme olsan dahi rüyada

Malum nefes nefese onlarla sarmaş dolaş

Dikmeye çalıştığımız incecik bir kumaş

Girdiğimiz borçlar altında halimiz sefil

Borçlar ödenmiyor! ortada yok hiç bir kefil

Hani bunu beraber almıştık üstümüze

Hal böyle olunca riya girdi sütümüze

Şu yollarda han arayan bir yolcuda benim

Can çekişen topal karınca renginde tenim

Son nefes verilirken hangi cümle aranır

Bulunsa dahi vakit biter, zaman tıkanır

Su gibi akan zamana karşı ne yapılır 

Bilen olsa, esrarlI güzelliğe kapılır

Geçmeden önce gülüyordu olmayan yüzü

Geçerken, alıp götürdü edeb gücümüzü

Elindeyse söyle aleme boş meşkaleyi 

Yıktırmada göreyim önündeki kaleyi

Diyelim ki, geçilmez set oldun sert çelikten

Hücum eder, girerler görünmez bir delikten

Ne geçti eline yaptıklarına karşılık

Her yanımda insanlar soğuk, kalplerse ılık

Elini gözlerine götür ne kadar nemli 

Kanayan gönlüne sor kaç zamandır elemli

Güveni yok ki kimseye, sana inanır mı?

Yalan yere verdiğin sevgileri tanır mı?

Eskiden beraberdik mutluyduk azda olsa

İstek vardı, birde büyüyen boşluklar dolsa

Ayrılmam diyenler de gidiyor buralardan', 'Canını sıkma, elbet gelir geçer bu elem, Koşup geleyim ilaç olacağımı bilsem Dertsizim diyebilir misin dertli dünyada ? Dertlerinden vazgeçm...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/feryad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-eren-zeki-nalbant-81h3t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlıkları yırtarak gelen

gece yanan ateşi söndüren

sevda bilendin,aşkı bildiren

gelip kalbime habersiz girendin

gece yıldızlardın

bir bir yanıp sönen

baharda yeşildin gözlerimde

kış ortası krizantem

sonbaharda sarı bir yaprak kadar hüzün

anılardın sen

hep can çekişen

unutulmaya yüz tutmuş

kitap arası tozlu aşklardın

romanlarda ölümsüzleşen

Belki bir melektin

ete kemiğe bürünen

belkide bir şeytan 

kalbimi benden çalan

yada bir deniz kızı

okyanuslar ülkesinden

ben seni çözemedim

bir sır ver

peki neden?', 'Karanlıkları yırtarak gelen gece yanan ateşi söndüren sevda bilendin,aşkı bildiren gelip kalbime habersiz girendin gece yıldızlardın bir bir...', ARRAY['Türk Edebiyatı','Şiir','Eren Zeki Nalbant']::text[], 8.5, '{"poet":"Eren Zeki Nalbant","poet_slug":"eren-zeki-nalbant","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Solukta Düşünmek Dünyayı', 'her-solukta-dusunmek-dunyayi-zeki-ergin-1zqcr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-eşime-

sevgilim 

delidolu akıp gidiyor dünya

özlem türküleri söylüyoruz

soluksuz

prangalar gıcırdıyor bir yerlerde

topraktaki tohum su istiyor 

ve gözlerini  açıyor

bir çocuk dünyaya

ölüme hazır

ah delişmen gençliğimiz

daha dün sanki

o günden bu  güne

değişen ne ki

ben yine kalemimi kullanıyorum

oysa onların çocukları olmuş

mutluymuşlar üstelik

yaşıyorlarmış aldırmadan dünyaya

oysa dinmeyen bir sancıdır 

içimizde yaşama sevinci

biliyorsun

biliyorsun

tepeden tırnağa

yüklüyüz bu  dünyayla

rotatifler hızla dönmekte

antenler çalışmakta

viking-1 merihten haberler gönderse de

ajans haberleri sevindirmiyor beni

silinemiyor

savaşların kara lekeleri

hiroşima

vietnam

ve beyrutta

baharın sevecen yüzüne aldırmadan

insanların üstünden tanklar  geçiyordu

dayandık buna ve diğerlerine

delice birşeydi ağlayamadık

ve koyulduk

çelik yüreklerimizle yaşamaya

sevgilim

toprağın nabzı atarken

yüreklerimizde

ben seni daha çok seviyorum

denizin

mavisiyle oynaşırken kayık

göğüslerken fırtınaları

dağları

ovaları

suları  kucaklayıp

mavi bir deniz gibi

sarılmak yaşamaya

sonra doğurtmak

saygonlu fahişeyi

yeniden dünyaya

ondan sonra yükselmek

aya 

yıldızlara

ve de yarınlara

_istanbul kasım1975

_sevgiliye isyan yt:haz04', '-eşime- sevgilim  delidolu akıp gidiyor dünya özlem türküleri söylüyoruz soluksuz prangalar gıcırdıyor bir yerlerde topraktaki tohum su isti...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/her-solukta-dusunmek-dunyayi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Ayrılmayalım', 'hic-ayrilmayalim-husnu-sakbas-7l1m4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeter artık

Bitsin bu ayrılık

Sensiz saatler geçmiyor

Ya sensiz geçecekse ömrüm

Herhalde yaşayamam

Ne olur hemen öldürme beni

Çünkü seni tanıdığım gün doğdum

Gel artık

Canıma yetti gayri

Sesin kulaklarımda

Hayalin gözlerimde

Ama sen yoksun kollarımda

Fazla bekletme

Dayanamam

Sev artık

Arının balı

Mecnunun Leylayı

Kısacası benim seni

Sevdiğim kadar

Ama hayır

Benim kadar sevme

Çabuk yıpranırsın

Sana kıyamam

Ağlama artık

Düşünme üzülme

İnan bundan sonra

Yaşama nedenim sensin

Her zaman her yerde

Daima yanındayım

Ne demiştim sana

İnan ve güven bana

Gül artık

Hiç olmazsa şimdilik

Yanımda mutlu ol

Çünkü çok yakında seni

Tahtalarını sevgimden

Küreklerini umutlarımdan

Yaptığım teknemle

Mutluluk okyanusuna

Hiç dönmemek üzere

Götüreceğim', 'Yeter artık Bitsin bu ayrılık Sensiz saatler geçmiyor Ya sensiz geçecekse ömrüm Herhalde yaşayamam Ne olur hemen öldürme beni Çünkü seni tan...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Sakbaş']::text[], 8.5, '{"poet":"Hüsnü Sakbaş","poet_slug":"husnu-sakbas","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/hic-ayrilmayalim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ki...', 'umut-ki-tansu-altunok-9c602', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün karardığın da

Dipsiz okyanusların

Kurak bir düşüsün

Bende.

Gün ağardığında

Tecavüz edilmedik tek köşesi kalmamış

Kentte

Belki bir umut.

Umut ki,

Yakılmış ,

Yağmalanmış,

Göç etmiş toprakların

         -Sıyrılıp topraktan

           Göreceği güneşi

           Savrulacağı rüzgarı beklyen-

Tohumunun umudu.

Umut ki

Sen.

Umut ki

Ben.

Umut ki...

(Belgi''ye)', 'Gün karardığın da Dipsiz okyanusların Kurak bir düşüsün Bende. Gün ağardığında Tecavüz edilmedik tek köşesi kalmamış Kentte Belki bir umut. ...', ARRAY['Türk Edebiyatı','Şiir','Tansu Altunok']::text[], 8.5, '{"poet":"Tansu Altunok","poet_slug":"tansu-altunok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umut-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılışım', 'yikilisim-mahir-toprak-hsm30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dün gece acılarıma yaslanıp ,senidüşündüm.

bir duldalıkta can verişimizi.

sanki viraneymiş geliyor hepsi bana

biliyorum düşünüyorsun neyi düşünmediklerimi

nasıl dendiğini dahi bilmezdim

seni seviyorum demenin şeklini

anlıyor insan sevince 

o kelimelerin boşuna olduğunu

ne kadar vefasızmışsın be sevgilim!

insan bi seviyorum der yıllar sonra 

kırılan bu kalbin ağırlığı azalsın seni umduğunda', 'dün gece acılarıma yaslanıp ,senidüşündüm. bir duldalıkta can verişimizi. sanki viraneymiş geliyor hepsi bana biliyorum düşünüyorsun neyi dü...', ARRAY['Türk Edebiyatı','Şiir','Mahir Toprak']::text[], 8.5, '{"poet":"Mahir Toprak","poet_slug":"mahir-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yikilisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya?Gerçek..', 'ruya-gercek-fatih-mehmet-9liqc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kıyamet kopacaktı sanki

ki karanlıktı

ve bir gürültü koptu..

birşeyler koptu yüreğimden

ve birşeyler anlamsızlaşıyordu,

biri ölüyor gibiydi..

ayaksesleri geliyordu kulağıma gidişinin,

bir dost daha gidiyordu peşisıra dünyanın..

derken bir adam gördüm..

bir yalan, 

bir riya daha..

kaçmaya çalıştım,

dost olmamaya,

güvenmemeye...

safça bakıyordu, dürüstçe,

insancaydı sanki

ki diğerleri gibi..

korktum evet korkarım,

kaçamadım,

aldatmadım,

yalanlamadım,

sonunda yine yalanlandım...', 'kıyamet kopacaktı sanki ki karanlıktı ve bir gürültü koptu.. birşeyler koptu yüreğimden ve birşeyler anlamsızlaşıyordu, biri ölüyor gibiydi....', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet']::text[], 8.5, '{"poet":"Fatih Mehmet","poet_slug":"fatih-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruya-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5 Harfini Kullanıyorum', '5-harfini-kullaniyorum-mustafa-hacisalihoglu-gohr7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '5 Harfini Kullanıyorum

alıp aklımı 

alıp alıp kaçırırken kendimi buralardan 

derken bir şiir yazmaklıyım şimdi 

içimden aklımdan dilimden parmaklarıma ne dökülürse 

ve başlıyorum 

başlayabilmeye... 

hı diyince burnumdan düşmesede şiir yada duygular 

sallıyorum biraz hayat ağacımı ve; 

naturel gitti 

derin bir yerden,derinden 

taa dipten 

bir vuruş 

ki vurgun 

ki durgunken,yorgun 

aktımı damla 

yaktımı kirpit gibi 

saklandımı ben 

aklandımı adım gibi 

ve 

olsun derken kaçışa dem 

vuran o,katran gibi... 

asılıyor 

kasılıyor 

yıl 2001 olacaktı 

sigaramda 

aslı LM olsa da... 

ama 

yangın çıkmış 

tarih:BEN 

mevzuat belliyken 

ben yine AYNI: deliyken 

ve kenlerden kurtulurken 

o''''na bakmışken 

son kez ken 

denize kenetlenmiş ken gözler 

her dudakta aynı sözler 

ler lerden önceyken ken 

sonra bir yelken der ken 

ben ve o''''y ken sevdam 

işte sadece o''''yken 

ler lerden er ken... 

yine tuhaflaştırdım ortalığı galiba.... 

evet evet den sonra

yok yok ben tuhaflaştım galiba', '5 Harfini Kullanıyorum alıp aklımı  alıp alıp kaçırırken kendimi buralardan  derken bir şiir yazmaklıyım şimdi  içimden aklımdan dilimden pa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hacısalihoğlu']::text[], 8.5, '{"poet":"Mustafa Hacısalihoğlu","poet_slug":"mustafa-hacisalihoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/5-harfini-kullaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uludağ''da', 'uludag-da-gaffar-karadogan-qxnkv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uludağ''dayım, insanları seyrediyorum

Gözlerim açık olmalı

Gördüklerimi yazmalıyım

Gözü açık gitmemek için

Sanmayın sadece seyrediyorum insanları

Üç katlı bir sağlık merkezinde

Yarım teçhizatlı bir dahiliyeci odasında

Sistemlerini de kontrol ediyorum onların

Karşı oda ortopedist Kemal''in

Benim hastalarım aşçı, yamak, hizmetli,Hastalıkları akut enfeksiyonlar

Kemalinkiler kayak kurbanları

Kırık, çıkık vesaire

Sordum aşçı Muhlise

İyi bakmıyormusunuz kendinize?

Cevapladı iyi bakmıyorlar bize

Yemeği bilmem kaç yıldızlı otelde veriyorlar

Bakmadım hiç yıldızlarına

Masamız kıyıda köşede olmasa da

Ayak altındayız biraz

Garsonlar hep başımızda

Yakın hissediyorlar bizi kendilerine

Yemek yerken bir de laf yetiştiriyoruz onlara

Şef garson İsmet

Namı diğer İsmet Baba

Elli yaşını devirmiş, saçlar ağarmış

Ama hala dimdik ayakta

Geçerken masanın yanından arada bir

Söyleniyor kendi kendine

''Ver Allahım ver zengin fakir belli olsun''

Olur mu İsmet Baba diyemiyorum

Yüksek rakımda bedava yaşayanlar olsa da bu dünyada

Yüksek rakım yüksek para gerektiriyor burada. 

                    Ocak-2000

''Uludağ Sağlık Merkezinde görevli iken yazmamak mümkün mü?''', 'Uludağ''dayım, insanları seyrediyorum Gözlerim açık olmalı Gördüklerimi yazmalıyım Gözü açık gitmemek için Sanmayın sadece seyrediyorum insan...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/uludag-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemodiyaliz Misafirlerine', 'hemodiyaliz-misafirlerine-gaffar-karadogan-lnnfp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bağlanıyorlar

Haftada iki veya üç kez

Kanı temizlemek için üreden

Antikoagulanlı bir setle

Teknobilimin harikası bir makinaya

Zorunlu olarak

Sorunlu olarak

Yaşamak uğruna 

Unutmuşlar gergin mesaneyi boşaltmanın hazzını

İşeyemiyorlar

Günlük işeme tarifi bir çay bardağı kadar

Rastladım bir litre işeyene

Bağlı dururken hemodiyalize

Yetmiyormuş işemek

Kaliteli işemek gerekiyor

Buluşturmuş bir odada insanları

Kronik böbrek yetmezliği paydası

Tenleri toprak rengi ve soluk

Gözleri takılmış derinlere

Kol başın üstüne yaslanmış

Konuşuyorlar karşı makine bağımlısıyla

Yükleniyorlar arada bir 

Kronik hastalığın kaygısı ile beraber üç-beş litre sıvı

Sonra bize düşüyor tasası

Bir de yasaklar vardı onlar için

Yiyemiyorlardı kayısıyı, muzu doyasıya

İçemiyorlardı suyu kana, kana

Öğrenmişler kan yapıcı iğneleri

Biz eritropoetin diyoruz

Öğrenmişler dengede tutmak gerektiğini

Kalsiyum ve fosforu

Dengede tutmak için ölümsüzlük duygusunu', 'Bağlanıyorlar Haftada iki veya üç kez Kanı temizlemek için üreden Antikoagulanlı bir setle Teknobilimin harikası bir makinaya Zorunlu olarak...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hemodiyaliz-misafirlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Bekçileri', 'gece-bekcileri-gaffar-karadogan-iera3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşündünüz mü? 

Gece bekçisi ne düşünür

Kendinizi gece bekçisinin yerine koyup

Düşündünüz mü

Eskimiş gazeteler niye okunur

Çayın en tatlısı nasıl demlenir

Gecenin bir vakti şeker olmasa da

Tanıdık yüzler nasıl çevrilir yoldan

Demli sohbetler için

Neden ucuza çalışır gece bekçileri

Tatlı tatlı uyumak verken

Ben onsekizinde tanıdım gece bekleyen Tevfik Dayıyı

Yanlış tanımışlar

Geceyi değil sabahı beklerdi

Öğrenci yurdu ile postahane arası beşyüz metre

Dost sesine ulaşmak beşyüz metre

Ama önce Tevfik Dayının sorusu var kapıda

Her zaman aynı söz başlatıyor sohbetleri

''Yediğin içtiğin senin olsun; gördüklerini anlat''

Yediğimiz içtiğimiz belli

Gördüklerimiz içler acısı anlatmakla bitmez

Yine de başlıyorduk anlatmaya

Onsekizinde tanıdım Tevfik Dayıyı

Yirmiyedisindeyim hala unutmadım', 'Düşündünüz mü?  Gece bekçisi ne düşünür Kendinizi gece bekçisinin yerine koyup Düşündünüz mü Eskimiş gazeteler niye okunur Çayın en tatlısı ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-bekcileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vizit', 'vizit-gaffar-karadogan-vp1d2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yangın olmasa da ilk kurtarılmalıdır

Bir intörn veya stajyer

Suskunluğun hakim olduğu

Hastanın yakınmasını bile söyleyemediği

O garip, o gergin vizit ortamında

Stajyer neyi ne kadar bildiğini

Bildiğinin ne kadar doğru olduğunu 

Bilememektedir

Eller önde kavuşmuş birbirine

Boyun ise hafif fleksiyonda

Ve suskunluğun tadı çıkarılmaktadır

Susmak burda da suçu kabul etmektir

Mahkemeyi anımsatmaktadır

Acı çeken hastanın çevresi

Toplanmış insanlar

Ortamda konuya hakim  biri vardır

Hakimin de payesi

Çok ölümlere tanık olan bir yatak

Üzerinde yatıyor bir ölümlü

Ölümlünün yüzüne bakılır

Asistanın sözüne

Sonra laboratuar kağıdına

Ağzından sözler dökülür payesi olan hakimin

Dökülenler bir asistan tarafından toplanır

Küçük bir not defterine

Gün yeni uygulamalara gebedir artık

Ve terkedilir bir tören havasında oda

Kimse bilmez ne konuşur 

Geride bırakılan pencere kenarındaki hasta

Kapı kenarındaki ile', 'Yangın olmasa da ilk kurtarılmalıdır Bir intörn veya stajyer Suskunluğun hakim olduğu Hastanın yakınmasını bile söyleyemediği O garip, o ger...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/vizit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakarya Depreminde', 'sakarya-depreminde-gaffar-karadogan-zeytr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarihi tekerrür ettirmiştik bir kere

Deprem alın yazısı ise

Biz yazmıştık o yazıyı alınlara çalakalem

Ağaç yetişecekse bu yıkıntılarda

Kovuklarına kazıyacağım

Ölüler bizim, suç hepimizin diye

Biz seçmiştik suçu fay hattına yıkan adamları

Medeniyetler yıkmıştı tarih boyunca afet

Bu kez sınıyordu

Ölüleri değil

Ölen ölmüş, kalan sağlar biziz artık

Sorumlular bizim içimizde', 'Tarihi tekerrür ettirmiştik bir kere Deprem alın yazısı ise Biz yazmıştık o yazıyı alınlara çalakalem Ağaç yetişecekse bu yıkıntılarda Kovuk...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sakarya-depreminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemşirelere', 'hemsirelere-gaffar-karadogan-37qkz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Amansız ANT takipçileri

Günboyu siz dokundunuz hastalara

Sekiz çarpı bir, belki de yirmidört çarpı bir

Esas siz sevdiniz onları

Boşuna dememişler ''sevmek dokunmaktır'' diye

Bir yol bulmak istiyorum

Mutluluğu enjekte edecek

Bolus tarzında

Hemşirelerimin

Yoğun insan ilişkilerimin

En sempatik insanlarının damarlarına

Bir sorunu var hastanın; ateşi 39° C

Bir sorunu var hastanın; epileptik nöbet geçirmekte

Bin sorunu var hemşirenin

İnsanlar sağlıklı olsun diye', 'Amansız ANT takipçileri Günboyu siz dokundunuz hastalara Sekiz çarpı bir, belki de yirmidört çarpı bir Esas siz sevdiniz onları Boşuna demem...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hemsirelere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktılar Sevdaları', 'yaktilar-sevdalari-fatih-gormez-b4cyj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu ne yaman süreçtir dostum anlayamadım...

 şairler can yoldaşları kalemlerini yakıyor meydanlarda,

  Yazarlar evlatları gi sevdikleri daktilolarını ...

 memurlar günlerce emek verdikleri defterlerini yakıyor,

  zindanlarda mahkumlar yattıkları ranzaları....

 işçiler ellerini yakıyor o ekmek parası kazanan ellerini,

   bilim adamları beyinlerini yakıyor labaratuvarlarda....

 Yurdumun dört bir yanı yanıyor cayır cayır sevgilim bu ne 

  bu ne isyandır bu ne hengame...

 içimde kavrulan bişeyler var bişeyler fısıldıyor usuldan 

 kulağıma: yak diyor sende bendenini karış yurdun dörbir

 yanında yanan isyan ateşlerine...

   Beni benden eden bişeyler var sevgilim yokluğun bir yandan birde halkım ağlıyor yurdumun ana şefkatiyle sardığı kollarında...

 Ve ben sana sesleniyorum sevgilim herkes sevdiği birşeyleri yakarken yurdumda

 sende çak kibriti sevdalının yüreğine 

 Öyle bir derinden çak ki alevlensin sevdamla halkımın sesleri yükselsin doruklara, yak sende yak beni sevgilim hemde bir benzin misali yak ki uçayım göklere.....', 'Bu ne yaman süreçtir dostum anlayamadım...  şairler can yoldaşları kalemlerini yakıyor meydanlarda,   Yazarlar evlatları gi sevdikleri dakti...', ARRAY['Türk Edebiyatı','Şiir','Fatih Görmez']::text[], 8.5, '{"poet":"Fatih Görmez","poet_slug":"fatih-gormez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaktilar-sevdalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Acısı ''Affetmek''', 'ayrilik-acisi-affetmek-fatih-gormez-jeklh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana sevgimi biriktirdiğim

O sensiz, acımasız günlerde

Hep seni düşündüm

Üzerine kurduğum dünyamda...

Ve yalnız şunu anladım canım ;

Sen benim olan herşeyden ötesin 

VE YALNIZ BENİMSİN.....

 Sana söyleyecek tek sözüm kaldı

Bu bize ait dünyamızda ;

Biliyorum ki sen bir güneşsin,

Etrafında birçok yıldız var...

Ama sen de şunu bil ki ;

Ben de dünya yım,

Yalnız bende hayat var...Benimle yaşayacaksın bu dünyada,

Sensin bu dünyamın sahibi,

Güneşi, ayı, yıldızı...

Evrene tanıttım seni,

Kimse bilmese de varlığını,

Sen bana ışık veren GÜNEŞİMsin...', 'Sana sevgimi biriktirdiğim O sensiz, acımasız günlerde Hep seni düşündüm Üzerine kurduğum dünyamda... Ve yalnız şunu anladım canım ; Sen ben...', ARRAY['Türk Edebiyatı','Şiir','Fatih Görmez']::text[], 8.5, '{"poet":"Fatih Görmez","poet_slug":"fatih-gormez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ayrilik-acisi-affetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarsız Ararken Bişeyleri', 'umarsiz-ararken-biseyleri-fatih-gormez-30v4p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden her defasında bir suçlu gibi utandım?

Aşkımdan değil gülüm...Tanırsın beni,

Aşkımdan değil

Çocuk saflığımla uzattığım elimin,

Mosmor ve kötürüm kalmasından utandım!

Kimse görmesin diye ellerime kapanıp,

Ağladım kaç gece... Yalnızca utandım...

 Ama herşeye rağmen,

Sevdim seni o saf kalbimle.

Yine de söylüyorum,

Bu bizim sevdamız adına ;

Nice nice yıllara

CANIM SEVGİLİM...', 'Neden her defasında bir suçlu gibi utandım? Aşkımdan değil gülüm...Tanırsın beni, Aşkımdan değil Çocuk saflığımla uzattığım elimin, Mosmor v...', ARRAY['Türk Edebiyatı','Şiir','Fatih Görmez']::text[], 8.5, '{"poet":"Fatih Görmez","poet_slug":"fatih-gormez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umarsiz-ararken-biseyleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Kötü Kayıp Özenti', 'en-kotu-kayip-ozenti-fatih-gormez-sua1y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllardır bana hep sıradan sıradan dedin sevgimiz 

sordum sana nedir sıradan olan sevmek dedin bana

ben şidi söylüyorum sevggilim sana ....

 Her Sevdanın Ölçütü Sıradışılıksa Eğer

       Benim Sevdamız İçin benim sınırların ötesinde olmam 

           gerek..............

               Oysa Ben Senle Olmaktan Mutluyum AŞKIM...!!!', 'Yıllardır bana hep sıradan sıradan dedin sevgimiz  sordum sana nedir sıradan olan sevmek dedin bana ben şidi söylüyorum sevggilim sana .... ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Görmez']::text[], 8.5, '{"poet":"Fatih Görmez","poet_slug":"fatih-gormez","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-kotu-kayip-ozenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablo', 'tablo-ozdemir-asaf-239we', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kedi kadının yanındaydı,

Kadın gecenin yanındaydı.

Kedi gitti geceye değdi,

Karardı,

Döndü kadına değdi.

Bir kadın portresi belirdi; 

Elinde siyah bir gül vardı,

Kucağında kırmızı bir kedi.', 'Kedi kadının yanındaydı, Kadın gecenin yanındaydı. Kedi gitti geceye değdi, Karardı, Döndü kadına değdi. Bir kadın portresi belirdi;  Elinde...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tablo-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemez', 'bilemez-abdullah-gokhan-konbul-apru7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bilirim , onsuz nasıl yasadığımı

                Ben bilirim , yalnız nasıl kaldığımı

                Kim bilir , benim büyük acılarımı

                Yalnızca ben bilirim , ben bilirim

                Suçum neydi , bilmem ne yaptım

                Sevmek miydi , neydi günahım 

                Ağlamadım , direndim sensiz zamana

                Suçum ölmek miydi senin uğruna

                Bilemez , ne acılar çektim bilemez

                Duyamaz , ağlarken sesim uzaklarda

                Silemez , olsa da gözyaşım o yanımda 

                Anlamaz, anlatamam ki derdimi ona', 'Ben bilirim , onsuz nasıl yasadığımı                 Ben bilirim , yalnız nasıl kaldığımı                 Kim bilir , benim büyük acılarımı ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gökhan Konbul']::text[], 8.5, '{"poet":"Abdullah Gökhan Konbul","poet_slug":"abdullah-gokhan-konbul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yalanları', 'nisan-yalanlari-ferhat-topkaya-3ev12', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk yoruldu, gidiyorum.

Gidiyorum da...

Önümde uzayıp giden bu yol.. 

Bu zifir sarhoşluğu gökyüzünün..

Ya bu sessizlik...

Farklı mı ki ardımda bıraktıklarımdan? 

Yoruldum.

Yorgunum izini sürmekten.

Bir söğüt gölgesi bulsam

Ya da bir dere kenarı

Uzanıp öleceğim...

Yoruldum.

Yorgunum yalnızlığa sürülmekten.

...

Güneş bulutların ardına sığınıyor...

...

Yağmur mu bu çiseleyen? 

Nisan? ...

Nisan bitmedi mi yoksa! 

Tam vaktidir o zaman...

Yaylalara ölüm yürümeden, 

Dağların yüzü hala yeşilken, 

Duyabiliyorken kokusunu fesleğenlerin

Pusuya yatmalıyım gölgesine bir şiirin, 

Yağmurlu bir mayıs akşamı

Nisan yalanlarına kanmak için.

(28 Mayıs 2000, Ankara)', 'Aşk yoruldu, gidiyorum. Gidiyorum da... Önümde uzayıp giden bu yol..  Bu zifir sarhoşluğu gökyüzünün.. Ya bu sessizlik... Farklı mı ki ardım...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Topkaya']::text[], 8.5, '{"poet":"Ferhat Topkaya","poet_slug":"ferhat-topkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nisan-yalanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabe''yi Süsler İsparta Gülleri', 'kabe-yi-susler-i-sparta-gulleri-zekeriya-cavus-v01jg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarihten ders alalım

Kendimize sahip çıkalım

Övünerek geçmişimize bakalım

Dünya tanıyor bizi unutmayalım

Saygısızlık var Ceddimize 

Sahip çıkalım memleketimize

Tarih seslenmeden bize

Gelelim kendimize.

Korkudan titrerdi  Avrupa  kentleri

Şahlanınca Anadolu Cengaverleri

Vız gelirdi Afrika çölleri, Yemen elleri

Karadan aşardı zincir vurulan denizleri.

Dost olur mu? İtalyan, Alman

Rusya, Mısır, Suriye, Irak, İran

Bulgaristan, Yunanistan, Erivan

Komşu değil hepsi düşman.

Akdeniz, Karadeniz donanmanın gölleri

İnci gibi kıvrılıp dizilir Ege sahilleri

Kabe'' yi süsler İsparta gülleri

Gülistandır yurdum değmeyince namahrem elleri.

Unutma Ermenin, Rus''un densizliğini

İtalya''nın, Yunanın, Fransız''ın kalleşliğini

Ey Türk gençliği boz artık sessizliğini

Araplar bilmiyor İslam kardeşliğini.

Güzel Marmara iç denizimiz

Spor da, İlim, İrfan da birinciliktir hedefimiz

Her zaman barıştır yurtta, cihanda ilkemiz

Elbette erecek timsale, tesanüte milletimiz.

Güzel yurdum Türkiye''nin gençleri

Serzenişim size ey islam bülbülleri

Bendlere sığmaz aşar kırar zincirleri

İncitmeye hakkımız yok kefensiz şehitleri

Dostlarımızı konuk edelim evimize

Diğerleri bizim neyimize

Biz gelelim kendimize 

Cihanı yine getiririz dize', 'Tarihten ders alalım Kendimize sahip çıkalım Övünerek geçmişimize bakalım Dünya tanıyor bizi unutmayalım Saygısızlık var Ceddimize  Sahip çı...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Çavuş']::text[], 8.5, '{"poet":"Zekeriya Çavuş","poet_slug":"zekeriya-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kabe-yi-susler-isparta-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-zubeyde-basaran-vfnil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen

Doğduğumuz gün; pamuk yüzlerimizde beliren

İlk nefes algımızla başlarsın

Yaş geçtikçe,  ten eskidikçe

Belirirsin suratlarda, mican!

Akıtıp yaşattığın her damlan zehir

Kibrinle kuşattığın insanın mı? çilekeş

Kamburu çıkmış, masum çocuklar

Yorgun ve nemli bakışlarla

Yinede güzel bakarlar sana

             Hayat!

Sars yık işle içime

Binlerce çilene razı benliğim

yer edindi, yuttu mihrim

Ömrüme ömür kattığın her acınla

Yine de güzelsin hayat

Ve sürekli güzelsin

Şimdide öylesin.....', 'Sen Doğduğumuz gün; pamuk yüzlerimizde beliren İlk nefes algımızla başlarsın Yaş geçtikçe,  ten eskidikçe Belirirsin suratlarda, mican! Akıt...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayat-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-mehmet-demirel-2-2j4k7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büşra Bebeğe

Geniş zamanların yitiği

Hırsız sevinçleri yaşamın

Soluğu ne kadar siyah

Ayrılığın ve akşamın

Körpe acılarını sular sabah

Islanır sevinci gözlerinin

Ne kadar çok gül açmış

Elleri bebeğimin

Suskun ağıtlar dilinde

Sıkar dişlerini nasıl sakin

Beyaz önlüklü acılara yiğitlenir

Büyür bebeğim

Genş zamanların yitiği

Hırsız sevinçleri yaşamın

Soluğu ne kadar siyah

Ayrılığın ve akşamın', 'Büşra Bebeğe Geniş zamanların yitiği Hırsız sevinçleri yaşamın Soluğu ne kadar siyah Ayrılığın ve akşamın Körpe acılarını sular sabah Islanı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demirel 2']::text[], 8.5, '{"poet":"Mehmet Demirel 2","poet_slug":"mehmet-demirel-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bebegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berivan', 'berivan-sair-met-xkvn2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Berivan

Ateşten gömlek aşkın 

Dağlamaz mahçup yaralarımı

Sevmez meczub yapımı 

Isırmaz otuziki dişiyle,

Sevip koşumlarımı

Berivan

Dağlalesi mi ne?

Erezyona muhtaç

Toprak örtülü yüreğime

Çal pençe pençe beni

Sazının sarı teli ile

Bırak aksın, sür benliğimi eğimine

Berivan

Kara tren gıcırtısı raylarda

Bir ahu kurulu tuzaklarda

Şimdi ıramak zamanı tanlarda

Soğuk,nemli,bırakımsı inlerde

Bekleme sevdalını

Onun iki mermisi var ciğerlerde

Berivan

Güzelliğine düzülen destan,

Aşkına yazılan roman,

Uğruna eridiğim sevdan,

Yaşa da yarım kalmasın,

Senden bihaber bu adam.

Berivan

Sen süngüsün, kara gecelerde namlumun ağzına.

Berivan

Sen bir masalsın,yazmışlar yaşamak adına.

Berivan

Sen sevgisin,ötlek mermilere siper alnımda.

Berivan 

Islatmak zorunda kaldığım dudaklarımdaki türkü,

Yaşamak uğruna çizdiğim yoldaki öykü,

Nazlı esen samyeline karşı,çiçeklerimin kökü,

Açmalısın:

Filizler açmazsa, ormanlar ölür çünkü.

Berivan

Hayat albümümün her yaprağının süsü,

Bastırmak istemediğim,özelliğim olan dürtü,

Kapattığım yolların sağlam,alaşım sürgüsü,

Bogazımdan yaban dikeni çeker gibi çıkarttılar

Döktüğün hüznü,

Bir daha hüzünlenme;

Acı çekiyorum çünkü.

                                                                   Ekim-1999', 'Berivan Ateşten gömlek aşkın  Dağlamaz mahçup yaralarımı Sevmez meczub yapımı  Isırmaz otuziki dişiyle, Sevip koşumlarımı Berivan Dağlalesi ...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/berivan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşku-Sevgi Dönüşümü', 'kusku-sevgi-donusumu-husrev-hatemi-73kry', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşku Acı''ya dönüşürdü hep

Acı da her zaman yine Sevgi''ye

Kuşkular zehirleştiği zaman

''Sevgi var'' diye ısrar niye?', 'Kuşku Acı''ya dönüşürdü hep Acı da her zaman yine Sevgi''ye Kuşkular zehirleştiği zaman ''Sevgi var'' diye ısrar niye?...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kusku-sevgi-donusumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretindeyim', 'hasretindeyim-sair-met-j9vnq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,

Şimdi gözlerde tüten bir hüzün,

Bir garip türkü içli,uzun

Biten bir öykü yanlış zamanda

Yanlış ve hazin.

Ben,hasretindeyim...

Gözlerimde 

Ayrılışımızdan kalan iki bakış var:

Mahsun ve ağlamaklı birinde,

Diğeri gürültülü ama duyamadığım bir sır

Duyamadığım ve korkulu.

Hasretindeyim...

Bir demet,

Solmayan yediverenlerden umduğum,

Gülmeyen gözlerine sunduğum.

Ağlasa da yorgun değil,kızgın ruhum,

Kızgın ve kederliyim

Hasretindeyim...

Solgun! 

Güllerle bir mi tuttun kendini,evimde soldun,

Kışlara yenik düşmek mi aşk,birden ne oldun,

Katarsız şimendiferin ızdırabı gibi mi yoruldun,

Izdırabın ve haykırışımla

Hasretindeyim...

Gül,

Kapına düştü bak yolum,

Ayrılık değilmiş anladım sonum,

Hücre hücre olmuş gözlerim,bölünmüş uykum

Bölünmüş ve yorulmuşum.

Hasretindeyim...

Değilsin! 

Geliyorum işte yanlış değilsin,

Seviyorum eceline iste ölünsün,

Kelimeler hacet mi sevgiye öyle dökülsün? 

Sevgime ve yeminime 

Hasretindeyim...', 'Sen, Şimdi gözlerde tüten bir hüzün, Bir garip türkü içli,uzun Biten bir öykü yanlış zamanda Yanlış ve hazin. Ben,hasretindeyim... Gözlerimd...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hasretindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnunum Leylamı Gördüm', 'mecnunum-leylami-gordum-sair-i-zati-yqe06', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mecnunum leylamı gördüm

Ne sordum ne söyledi

Kaşlarını yıktı geçti

Soramadım bir çift sözü

Aymıydı güneşmiydi yüzü

Sandım ki zühre yıldızı

Şavkı beni yaktı geçti

Ateşinden duramadım 

Ben bu sırra eremedim

Seher vakti göremedim

Yıldız gibi aktı geçti

Bilmem hangi zühre yıldızı

Bu dertler yaralar bizi

Gamze okun bazı bazı

Yar sineme çaktı geçti

İzati der ne hikmetmiş

Uyurken gördüm bir düş

Zülüflerin kement etmiş

Yar boynuma taktı geçti', 'Mecnunum leylamı gördüm Ne sordum ne söyledi Kaşlarını yıktı geçti Soramadım bir çift sözü Aymıydı güneşmiydi yüzü Sandım ki zühre yıldızı Ş...', ARRAY['Türk Edebiyatı','Şiir','Şair İzati']::text[], 8.5, '{"poet":"Şair İzati","poet_slug":"sair-i-zati","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mecnunum-leylami-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-eren-zeki-nalbant-nauur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahile vuran her dalga sesinde

fırtınadan önceki her sessizlikte

her gök gürlemesinde

güneşin her doğuşunda

gecelerin siyahında

her yakamoz ışıltısında

dolunay zamanında

her öfkede

her sevinçte

kızgın demir dövülürken

her çekiç sesinde

harlamasında ateşin

kora dönmesinde

suların çağlamasında

akmasında gözyaşının

bebeklerin ağlamasında

kuş seslerinde

kaçışmasında kelebeklerin

arıların bal yapmasında

kozalaktan tırtıl çıkmasında

her çiçek açışında

baharın gelmesinde

her akşam oluşunda

güneşin kayboluşunda

yıldızların göz kırpmasında

hayatın her anında

iki kelime dolanır dilime

sen varken hatırımda

seni

seviyorum', 'Sahile vuran her dalga sesinde fırtınadan önceki her sessizlikte her gök gürlemesinde güneşin her doğuşunda gecelerin siyahında her yakamoz ...', ARRAY['Türk Edebiyatı','Şiir','Eren Zeki Nalbant']::text[], 8.5, '{"poet":"Eren Zeki Nalbant","poet_slug":"eren-zeki-nalbant","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayat-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölyesine Ağlamadım', 'bolyesine-aglamadim-erhan-karagoz-tvhf6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Böylesine ağlamdım

Hiç göz yaşlarına böylesine boğulmadım

Dağlar kadar geniş yüreğim var derdim

Hiç bu kadar seveceğime inanmadım

Gözlerimde yaşlar bitmez oldu.

Sevdiğim gitti dönmez oldu

Ben mecnunsuz deli divane

Gözlerim boşlukta onu bekler oldu

İçimde bir acının haykırışları

Yüreğimde damlayan kanın çırpınışları

Boğulan içim yüreğim bedenim

Derdimi Anlatmak o kadar güç oldu 

Sevdiğim bir gitti dönerim diye 

Dönmez oldu 

Beni yanlız ve yanlız bıraktı Gelmez oldu 

Derdimi anlattığım dağlar dayanmaz oldu

Ben küçüldüm bu acıyla 

Yüreğim bu acıyı çekmez oldu

Çözüm ne dersen sevgilim

Dönmen artık şart oldu.

Dönemzsen bu dünya bana bilesin

Yaşarken mezar oldu.', 'Böylesine ağlamdım Hiç göz yaşlarına böylesine boğulmadım Dağlar kadar geniş yüreğim var derdim Hiç bu kadar seveceğime inanmadım Gözlerimde...', ARRAY['Türk Edebiyatı','Şiir','Erhan Karagöz']::text[], 8.5, '{"poet":"Erhan Karagöz","poet_slug":"erhan-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bolyesine-aglamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama Son Teşekkür', 'sevdama-son-tesekkur-mustafa-hacisalihoglu-0d1qd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdama Son Teşekkür 

sevdama teşekkür bu

son yazılmış ilk şiir saysen bunu

yaşlarıma bakma ve yıkılışıma aldırma sevdam

bırak nasıl biliyorsam seni okadar basit okadar sade okadar çocuk kal bende

ve sana ve gözlerine ve yüzüne

ve tüm merhametine

sığınarak elveda sevdam...belki başka bir yerde bulurum seni

belki kanlı belki ballı

belkide ağlamaklı gülerken...

ne kadarsan bende okadar kal yüreğimde...

tüm kelimelere tüm sözlere tüm hecelere

inat,susuyorum bende

bakışlarımda sadece senle....

bir yerlere gömüyorum seni bu akşam son kez

çocuk oyunu değil bu

kahroluşuma aldırmadan yinekimse

gidiyorum busefer başka şekilde...

çerçevemde sen kal yeter,

gözlerindeyken son kez yaşlarım

ve ellerim koynuna asılmışken 

son kelimemide sana atıyorum

elveda...', 'Sevdama Son Teşekkür  sevdama teşekkür bu son yazılmış ilk şiir saysen bunu yaşlarıma bakma ve yıkılışıma aldırma sevdam bırak nasıl biliyor...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hacısalihoğlu']::text[], 8.5, '{"poet":"Mustafa Hacısalihoğlu","poet_slug":"mustafa-hacisalihoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevdama-son-tesekkur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Şiirini Yazabilirmisin?', 'sevginin-siirini-yazabilirmisin-sadan-cerit-8fvvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/Dün gece polisler çaldı kapımı 

Komşum olacak kadın ispiyon etmiş olmalı/ 

Nihavent ile içerken rakımı 

Bir şeyler çeldi aklımı 

Neşe ile fırladım rakı masasından 

Neler neler gelmişti aklıma bir bilsen! 

Nihayet ''Sevginin Şiirini'' yazacaktım. 

Sana Sevgiyi anlatacaktım. 

Abidin Abi! diye bağırdım,

Abidin Abi, 

Nazım Ustaya ithaf edelim bunu! 

Aranmaya başladım odanın içersinde 

panik halinde 

Sağa sola koşuşturdum durdum 

Şakaklarım sıkıştı,

ter boşaldı vucudumdan 

Buldum birden aradığım kağıt ile kalemi 

Açtım kalemin ucunu, 

oturttum kağıdın üzerine 

Haydi dedim. 

.......haydi! 

..............haydi! 

Yazmaz oldu ilk satırdan sonrasını 

Bir daha denedim

bir daha... 

sonra

bir daha...

....

/1961 yaz ortalarında ben daha doğmamıştım oysa,

İnsanlık dramı yaşanıyordu Küba''da. Nazım sesleniyordu; 

''sen mutluluğun resmini yapabilirmisin (Abidin)   Usta''/ 

....

Olmadı, 

yazamadım Abidin abi! 

Utandım...

Kızdım... 

Gücendim... 

Çektim silahımı 

doğrulttum üzerlerine 

İkisinide vurdum 

alnının ortasından 

Kanlar içinde yıkıldılar oraya 

Dilimde zincir, 

bileklerimde kelepçe 

Sessizliğe gömdüler beni dün gece! 

Not: Nazım Hikmet, büyük şair; 1961 yazı ortalarında, Küba''da yoğunlaşan evrensel insanlık dramını yüreğinde yaşarken, ressam dostu Abidin Dino ''nun şahsında tüm insanlığı mutluluğun resmini yapmaya davet ediyor.

''sen mutluluğun resmini yapabilir misin Abidin

işin kolayına kaçmadan ama

gül yanaklı bebesini emziren melek yüzlü anneciğin resmini değil

ne de ak örtüde elmaların

ne de akvaryumda su kabarcıklarının arasında dolanan kırmızı balığınkini

sen mutluluğun resmini yapabilir misin Abidin

1961 yazı ortalarında Küba''nın resmini yapabilir misin

''çok şükür çok şükür bugünü de gördüm

ölsem de gam yemem gayrının''

resmini yapabilir misin üstat''', '/Dün gece polisler çaldı kapımı  Komşum olacak kadın ispiyon etmiş olmalı/  Nihavent ile içerken rakımı  Bir şeyler çeldi aklımı  Neşe ile f...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sevginin-siirini-yazabilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serap', 'serap-sadan-cerit-wf6iv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Serabımsın serap değil

Sevabımsın günah değil

Kıble diye döndüm sana

Kabem oldum Kıblem değil

Tabduk ile dergah kurdum

Yunus ile Aşk''ı buldum

Senin ile Hakkı buldum

Kabem oldun Kıblem değil', 'Serabımsın serap değil Sevabımsın günah değil Kıble diye döndüm sana Kabem oldum Kıblem değil Tabduk ile dergah kurdum Yunus ile Aşk''ı buldu...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-tunay-ozturk-c527r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben kim şiir yazmak kim!

Gün olur aşık olurum

Elimde gariban kalem;

Yazarım bir iki mısra

Yazarım da beceremem...', 'Ben kim şiir yazmak kim! Gün olur aşık olurum Elimde gariban kalem; Yazarım bir iki mısra Yazarım da beceremem......', ARRAY['Türk Edebiyatı','Şiir','Tunay Öztürk']::text[], 8.5, '{"poet":"Tunay Öztürk","poet_slug":"tunay-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gun-olur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Bilirim', 'nasil-bilirim-salih-parlak-ndnya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl bilirdim yazmasaydım sana;

gözyaşının mürekkebi dağıttığını,

kara gözlerinde şefkat ararken ben;

sende avını vuran avcının gururu,

batarken değil, okun çıkarken acıttığını.

Nasıl bilirdim görmeseydim seni;

o nazik ellerin,

akıl çelen güzelliği,

yem diye tuzağa saçtığını.

Umut bırakmak için yarına,

feda edip kendini,

bembeyaz gelin gibi, son çiçeklerini,

ağaçların ölürken açtığını.

Nasıl bilirdim sevmeseydim seni;

küçücük bir kalbin,

ne çok sevgi aldığını,

kıymak için bir cana,

eli titremez bir kızın seçilip,

asla ıskalamadan hedefini,

ölümü parmaklarıyla attığını.

Cumaali''nin dediği gibi, nasıl bilirdim;

insanı en çok sevdiklerinin ağlattığını.

	-bilmezdim

(izmir 2001)', 'Nasıl bilirdim yazmasaydım sana; gözyaşının mürekkebi dağıttığını, kara gözlerinde şefkat ararken ben; sende avını vuran avcının gururu, bat...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nasil-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif', 'elif-sadan-cerit-vy15g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıl ile görmez idim

Gönül ile sevmez idim

Ateşi ile yanmaz idim

Elifdeyim yarenlerim

Yaş iken kırılmışım

Yel ile savrulmuşum

Beni Benden çalmışım

Elifdeyim yarenlerim

Saymaz iken günlerimi

Tatmaz iken dillerini

Yunmaz iken nurlarını

Elifdeyim yarenlerim

Gönül gözüm görür elbet

Ateşinle yanar elbet

Beni bende Ben eyleyim 

Elifdeyim yarenlerim', 'Akıl ile görmez idim Gönül ile sevmez idim Ateşi ile yanmaz idim Elifdeyim yarenlerim Yaş iken kırılmışım Yel ile savrulmuşum Beni Benden ça...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elif-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-umut-kakasci-fqd3a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SENi SEViYORUM Ve Farkindayim 

Seni sevmeye devam ettikce

Hic rahat uyuyamayacagim. 

Olsun ben herseye raziyim. 

Senin icin uykusuz kalmisim cok mu? 

Yildizlari toplar getiririm geceleri sana gökyüzünden. 

Beraber gezeriz en icra gezegenleri. 

Ve yine birgün ölürsem Ugrunda; Üzülme. 

Senin icin ölmüsüm cok mu? 

Korkma ben ölsemde hasretine dayanamam. 

Her gece Cennetin Ciceklerini sererim ayaklarinin altina. 

Ve sonra Bi''tanem herseferinde geceyi beklemektense 

Gündüze suikast düzenlerim. 

Mesela Günese Bomba koyardim. 

Ay''i Baglardim gökyüzüne iplerle. 

Yildizlari civilerdim düsmesinler diye. 

Karanliga mahkum olur butun Sehir senin icin. 

Onca masum insan,

Sana olan askimin cezasini cekmesinler diye 

Hepsini ellerimle tasirdim aydinlik bir kente. 

Sonra da ikimize kalirdi bu Sehir. 

Sadece Sen Ben ve Sevgimiz. 

Hersey ne kadar guzel olurdu degil mi? 

Yok Yok Hic birsey güzel olmazdi. 

Mesela Ela gözlerini hep kahverengi görürdüm. 

Karanliklarda bogulurdu sevgimiz. 

Oysa Bir he desen 

Birakip bu karanlik günleri 

Bizi bekleyen aydinlik ve güzel günlere kosardik. 

Düsünsene bir evimiz olmus maviliklere yakin. 

Bahcesinde Cocuklarimiz. icinde sen. 

Ela Gözlerine bakardim gün boyu hic bikmadan. 

Sen simdi bana yine inanmassin. 

O zaman Bütün bunlari bir yalan say. 

Bu siir sana yazilmadi farzet. 

Tut ki seni hic sevmiyorum. 

Benim gözlerim Yesil degil de. 

Vur yüzüme hatalarimi utanma. 

Üz beni üzebildigin kadar. 

Hadi Söylesene...

Mesela beceriksizliğimden bahset.

Sevgini Dağlara değil Yollara bile yazamadın de.

Yapmadığım ihanetimden de bahset.

Dilediğim özürleri say teker teker.

Çekinme söyle yabancı yok aramızda.

Sen, Ben ve Sevgimiz Sadece.

Şimdi ne desem faydasız.

Ne yapsam yaranamam sana biliyorum.

Gökyüzünü halı diye sersem ayaklarının altına,

Denizleri içip bitirsem yudum yudum,

Affetmeyeceksin beni farkındayım.

Bir mahkumum bundan sonra bu alemde.

Yalnızlığa, Sensizliğe, Kederlere mahkum.

Özleyeceğim Seninle geçen anıları.

Gülmeyi, Sevinmeyi, Özgürlüğümü özleyeceğim.

Alev Alev yanan tenini, Başak sarısı saçlarını,

Ellerini tutmanın verdiği mutluluğu,

Saçlarımı okşarken bulduğum huzuru,

Özleyeceğim Sana sevgi sözcükleri söylemeyi.

Bilirsin saçma sapan Türk Filmleri vardır,

Sonu hep mutlu biten. Onlarıda Özleyeceğim.

Şimdi bırak beni git.

Sakın göz yaşı dökme ardımdan.

Yaşanılan bütün güzel anılar senin olsun,

Acıları bana bırakda öyle git.

Arayıp sorma beni sakın bir daha.

Gelmeni istemem maphushane kapılarına.

Giderken yanına iki gerçek daha al benden,

Biri Seni Sevdiğim, Diğeri Seni Asla aldatmadığım gerçeği...', 'SENi SEViYORUM Ve Farkindayim  Seni sevmeye devam ettikce Hic rahat uyuyamayacagim.  Olsun ben herseye raziyim.  Senin icin uykusuz kalmisim...', ARRAY['Türk Edebiyatı','Şiir','Umut Kakaşcı']::text[], 8.5, '{"poet":"Umut Kakaşcı","poet_slug":"umut-kakasci","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/seni-seviyorum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-sadan-cerit-4hx27', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir boşluk, bir yalnızlık var bu akşam

Ne Afitap hanım çaldı kapımı

Ne de her akşam kapımdan geçen

Bozacı seslendi ''Taze Bozaa'' diye

Hava birazdaha puslu

Daha soğuk, daha akşam bu akşam

Akşam vakti cumba da oturupda

Kahvemle beraber içtiğim sigaramda da tat yok bu akşam

Her akşam iş dönüşü gözetlediğim

Gözetlerken utanıp da başımı çevirdiğim

Afitap hanımın kızıda yok bu akşam

Selamlamadan geçen gemileri seyrederken

Nedendir bilinmez 

Bende de tat yok bu akşam', 'Bir boşluk, bir yalnızlık var bu akşam Ne Afitap hanım çaldı kapımı Ne de her akşam kapımdan geçen Bozacı seslendi ''Taze Bozaa'' diye Hava bi...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-aksam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Bilirdim', 'nasil-bilirdim-salih-parlak-2btxe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl bilirdim yazmasaydım sana;

gözyaşının mürekkebi dağıttığını,

kara gözlerinde şefkat ararken ben,

sende avını vuran avcının gururu,

batarken değil, okun çıkarken acıttığını.

Nasıl bilirdim görmeseydim seni;

o nazik ellerin,

akıl çelen güzelliği,

yem diye tuzağa saçtığını.

Umut bırakmak için yarına,

feda edip kendini,

bembayaz, gelin gibi son çiçeklerini,

ağaçların ölürken açtığını.

Nasıl bilirdim sevmeseydim seni;

küçücükm bir kalbin,

ne çok sevgi aldığını.

Kıymak için bir cana,

eli titremez bir kızın seçilip,

asla ıskalamadan hedefini,

ölümü parmaklarıyla attığını.

Cumaali''nin dediği gibi, nasıl bilirdim;

insanı en çok sevdiklerinin ağlattığını.

Bilmezdim.', 'Nasıl bilirdim yazmasaydım sana; gözyaşının mürekkebi dağıttığını, kara gözlerinde şefkat ararken ben, sende avını vuran avcının gururu, bat...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nasil-bilirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böylemi biter Bir aşk', 'boylemi-biter-bir-ask-salih-parlak-imnrm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Böyle mi biter bir aşk?

Eskiden; yastıkların gözyaşını tanıdığı,

''arabesk parçalara'' ram olunan,

en hafifinden yüreklere, kabak kemane hüznünün çöktüğü,

yanık köşeli mektupların,

gül kurularıyla gönderildiği zamanlarda;

gizlice ağlar kız,

oğlan duvarları yumruklardı.

Bir aşk böyle biterdi.', 'Böyle mi biter bir aşk? Eskiden; yastıkların gözyaşını tanıdığı, ''arabesk parçalara'' ram olunan, en hafifinden yüreklere, kabak kemane hüznü...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/boylemi-biter-bir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-salih-parlak-kzty0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cömertçe şifa dağıtır ellerin,

O yardan bana hep yara gelir.

Kadri fazla mı olur ellerin?

bana ne zaman sıra gelir?

Yanarım yar için, yar benden nadan,

Reva görmez bir damlayı ayrılsam dünyadan

Kadir gecesi yattığım rüyadan,

Beyazlar beklerim, kara gelir.

Çıkarır sehpaya çekmez ipimi zalim,

Cümlesini bilir cefanın, bilmez nedir halim,

Hercaidir, karar kılmaz bir daim,

Bugün söyler yarın inkara gelir.', 'Cömertçe şifa dağıtır ellerin, O yardan bana hep yara gelir. Kadri fazla mı olur ellerin? bana ne zaman sıra gelir? Yanarım yar için, yar be...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-zaman-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldı-Kaldı', 'aldi-kaldi-salih-parlak-otpdv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alır eline koklar da seherde salınan,

anlamaz beş karanfilin dilinden.

Yar dudağının hatırı için alınan,

veremedim elimde gülüm kaldı.

Son kez bakmadım buğulu gözlerle,

bir kış günü otobüs camından,

sallanmadı yar ardından ,

havada elim kaldı.

Vermese de payımı hakettiğim sevgiden,

bölünmemiş yüreğim, elimde gülle..

akşam üzeri kapısına giden,

Yürünmedi, yolum kaldı.

Bir adım attım, uçuruma düştüm,

kurdu tuzağı, uzatmadı elini,

Vurdu, bıraktı gitti,

ortada ölüm kaldı.', 'Alır eline koklar da seherde salınan, anlamaz beş karanfilin dilinden. Yar dudağının hatırı için alınan, veremedim elimde gülüm kaldı. Son k...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldi-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın Beni', 'yakin-beni-sadan-cerit-4jkgw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'El iken yaren dedin

Kör idim badem dedin

Beni bende can eyledin

Pervaneyim ışığında

Günü bilmem gecedeyim

Aşkı bilmem divaneyim

Çorağıma su eyleyin

Bir damlayım deryanızda

Deli gönül coşmaz iken

Daldan dala konmaz iken

Bir yudumla kanar iken

Deryaları arar oldum

Yar isem yaren deyin

Geceleri gün eyleyin

Elim boş çevirmeyin

Yaren diye sarın beni

Dergahında kapın olsam

Deryalara açsam seni

Kandilinde yağın olsam

Hak yoluna yakın beni', 'El iken yaren dedin Kör idim badem dedin Beni bende can eyledin Pervaneyim ışığında Günü bilmem gecedeyim Aşkı bilmem divaneyim Çorağıma su ...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yakin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam Üzeri Trabzon Yolunda', 'bir-aksam-uzeri-trabzon-yolunda-salih-parlak-w7kxo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cam kenarını severim arabanın, - haberin olsun!

mor dağlara dalıyorum, kalıyorum.

siliniyor ucuz zevkler,

ve dünya geçiyor gözümden.

İhtiyar bir kadın; elinde,

iğreti duran bir değnek.

Beli kemer, güttüklerinin ardından,

kimbilir, ne ümitlerle gider.

Bozulmuş tütün tarlalarında,

elleri kirli, kalbi temiz kadınlar,- analar,

dünyaları küçük, umutları küçük,

şehrin kaprisi ulaşmamış henüz,

ellerinde katık ekmek,

yanık çocuklar arkalarında...

Ve onları sadece melekler anlar.

Yine şiir okumaya dalıyorum...

En can alıcı yerindeyim mısranın,

sonra gizlice fotoğrafına bakıp,

nefeslerin en derinini alıyorum.

Ve dünya göçüyor gözümden.

İşte gidiyorum...', 'Cam kenarını severim arabanın, - haberin olsun! mor dağlara dalıyorum, kalıyorum. siliniyor ucuz zevkler, ve dünya geçiyor gözümden. İhtiyar...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-aksam-uzeri-trabzon-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Ben,', 've-ben-salih-parlak-e0cvy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve ben;

sana aşık olalıdan beri,

dünya yavaş dönüyor geceleri.

hem bu kadar güzel değildi,

daha önce içtiğim sigaranın tadı.

İlk defa söylendi,

ütüsüz gömlek giydiğim.

Keyifle dinlediğim şarkılar,

hüzzam makamından değildi.

Dağılmamıştı odamdaki eşyalar,

semt pazarındaki kadar, 

Ve ben.', 'Ve ben; sana aşık olalıdan beri, dünya yavaş dönüyor geceleri. hem bu kadar güzel değildi, daha önce içtiğim sigaranın tadı. İlk defa söylen...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye?', 'niye-salih-parlak-psgx7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tam demindeyken uykunun,

uyanıyorum, saat üç.

Ay bütün ihtişamıyla, ve

sözleşmiş bütün yıldızlar

hatırlatmak için seni bana.

Derin bir duygunun acısı,

tekrar kalbimde sızlar.

Gece doğurur hasretini, 

yalnızlık emzirir, kalbim büyütür.

bir yağmur başlar inceden,

susamış toprağı doyurur yavaş yavaş,

temizlenir dünyanın kirleri geceden.

Bense sevgilim;

dünyanın dertlerine inat,

canım çıkmadan çıkmayacak,

yüreğimde sonsuz umudum,

ve dünden arta kalan hasretin,

yine kirpiğimden sarkar.

Kimin için ağlar yağmur?

Kavuşmak için gül dolu bahçeye,

aceleyle inen damlalara nispet,

yağmurla rekabete kalkar;

gözlerim.', 'Tam demindeyken uykunun, uyanıyorum, saat üç. Ay bütün ihtişamıyla, ve sözleşmiş bütün yıldızlar hatırlatmak için seni bana. Derin bir duygu...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/niye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Kızı', 'coban-kizi-salih-parlak-5057p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklardan kopup gelen bir rüzgar,

Kuru soğuk, bembeyaz bir kar,

Ayın yanına düşmüş güzel yıldızı, 

Bana seni anlatır Çoban Kızı.,

Kalbimin ta şurasında bir sızı,

Bana seni anlatır Çoban Kızı.,

Gözümden uçup giden hayallerin, 

Bitmeyen özlemimle kalbimde belli yerin.

Gözlerinin mavi rengi, giydiğin kırmızı,

Bana seni anlatır Çoban Kızı.,', 'Uzaklardan kopup gelen bir rüzgar, Kuru soğuk, bembeyaz bir kar, Ayın yanına düşmüş güzel yıldızı,  Bana seni anlatır Çoban Kızı., Kalbimin ...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/coban-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gecenin Anatomisi', 'bir-gecenin-anatomisi-salih-parlak-d1xe2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirler yazmalıyım sana, 

kimsenin okumadığı / duymadığı,

uykunun ölüme ikiz kardeş olduğu;

senin bu vakitte güzelim,

bir anne kalbi kadar yumuşak yastığında uyurken,

bana mı gelir hep böyle,

kuş tüyü uykular?

	Siyah gözlerinden kurtulayım derken,

bir benim, bir de...

siper bekleyen gözlerin birleşmediği,

bu vakitte;

inadına kalbime demirlenir.

Sonra uzun, siyah saçların gelir,

her telini ilmek yapıp; 

takar gidersin boynuma.

beklerim, gülüşlerini beklerim,

yine kalbimi yakan bir matem gelir.

Toplarım hayalimdeki sevgi sözcüklerini

gönderirim sana fısıldayarak,

belki rüzgar getirir, için titrer, ürperir,

anla ki o vakitte;

kirpiklerim yeni ıslak, yine ıslak.

	Ve yeryüzünün en mübarek çağrısı gelir,

bu vakitte, hiçbir duanın geri dönmeyeceği, 

sadece Müslüman ellerin açık, 

ruhu temizleyen tek sıvının	

yeni yıkadığı bir kalple yapılan,

ve gitmesi gereken yere ulaşan,

en aciz kelimelerle yazılmış arzuhal dilekçemi

gönderirim fısıldayarak.

Yavaş yavaş beyaz gelir,

siyahın yerini alır.

Dünyanın hergün duyduğu sesler 

yeniden yankılanır.

Acaba neden geceyle gelir matem?

en sivri bıçağını saplar,

bir defa yetmez;

ve intikamını yine gözyaşı olarak alır.

İşte ''Güzelim'' bir gecenin anatomisi,

İşte ''güzelim gecelerin'' bir anatomisi.', 'Şiirler yazmalıyım sana,  kimsenin okumadığı / duymadığı, uykunun ölüme ikiz kardeş olduğu; senin bu vakitte güzelim, bir anne kalbi kadar y...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-gecenin-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elektriğin Azizliği İşte!', 'elektrigin-azizligi-i-ste-salih-parlak-94dqn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mum ışığında şiir okuyorum,

gecelerde, kara gözlü gecelerde,

layıkıyla görevini yapıyor ay.

Biraz ışık, biraz sessizlik katıp karanlığa,

seni getiriyor yavaş yavaş geceler.

Bir nefes çekip senin için,

üflediğim son duman oluyorsun.

Dayanamam, bir türkünün ardından,

yine dumanlanır odam, gözlerim.

Sen kalsaydın derim, sadece sen,

Ulupark''ta gözlerine daldığım,

Dudağımda saklı kalsaydı busen.

kuş kalbiyle beni bekleyen sevgiliye,

kırmızı gül aldığım.

Sen nöbettesin belki bu vakitte;

Bense nöbetlerde.

Dedim ya; mum ışığında şiir okuyorum,

ser gönlüne güzelim,

Sana sevgi dokuyorum.

	-Layıkıyla görevini yapıyor ay.', 'Mum ışığında şiir okuyorum, gecelerde, kara gözlü gecelerde, layıkıyla görevini yapıyor ay. Biraz ışık, biraz sessizlik katıp karanlığa, sen...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elektrigin-azizligi-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bu ya!', 'hayal-bu-ya-salih-parlak-5sm5s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kenetlenmiş ellerimiz, çıplak ayaklarımız,

sahilde dolaşacaktık yazın,

yüreğimiz, ellerimiz gibi olacaktı,

birlikte mırıldanacaktık ''Gülpembe'' yi,

mehtaplı bir İzmir akşamında,

sen olacaktın tek dinleyeni,

akort makamından çaldığım sazın.

Gözlerim güzelliğine dalacaktı,

bir sevgili gibi ilk kez tuttuğum,

senin ellerin kalacaktı.

	Haydi, ağla şimdi,

ne zaman anlarsın bilmem;

gözyaşıyla gelen pişmanlığın,

Kabil kadar eski olduğunu.', 'Kenetlenmiş ellerimiz, çıplak ayaklarımız, sahilde dolaşacaktık yazın, yüreğimiz, ellerimiz gibi olacaktı, birlikte mırıldanacaktık ''Gülpemb...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayal-bu-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla', 'zamanla-salih-parlak-egzey', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Goncayken sevilir gül,

açılınca koklanır.

Geçince hükmü baharın,

har olur bülbülün gözünde,

hatırı kalmaz dikenin.

Yutkunurken çıkan gözyaşı,

yanakta yol bulduğunda;

ne ateşler yakar yürekte zaman

ömürden geriye kuru bir ''ah'' kalır.

Geçer sorguya çekildiği günler;

kırılma korkusu olmasa,

artık, yalan söylemez aynalar.

Şaşırmaz asla zamanını ferman,

akşamı olmayan sabah kalır.', 'Goncayken sevilir gül, açılınca koklanır. Geçince hükmü baharın, har olur bülbülün gözünde, hatırı kalmaz dikenin. Yutkunurken çıkan gözyaşı...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zamanla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından-1', 'akort-makamindan-1-salih-parlak-mxs7g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir nasihatim var size; bakın,

Herşey olun şu dünyada,

Hırsız, katil, ama sakın; 

Aşık olmayın.

Sevdiğim Sen, özlediğim sen,

Hergün dudağımda ismindeki heceler.

Ne kadar yalnızım bir bilsen!

Uzun uzun bitmeyen geceler.

Zamansız oldu ayrılığımız,

Hiç ayrılmayacağız derken,

Dilimde yine o şarkımız,

Seni bırakıp giderken.

Bitecek sanma bu dertleri,

Birinin ucundan diğeri başlar.

Unutmaya kalkma sakın,

Unutulmaz ilk aşklar.

Unutulmaz kalbe giren ilk duygular,

İnanma, Mecnun''un hali de buydu.

Aşkı kalpten çıkarıp ayaklarına koydular,

Bakma bugünkü hallerine, onlar dünden unutuldu.', 'Bir nasihatim var size; bakın, Herşey olun şu dünyada, Hırsız, katil, ama sakın;  Aşık olmayın. Sevdiğim Sen, özlediğim sen, Hergün dudağımd...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından -2', 'akort-makamindan-2-salih-parlak-63l0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarın mahşer yeri gelip, kurulsa,

Bir damla teselline muhtaçtır bağrım. 

O gün senin ahval benden sorulsa,

O dün gitti deyip ağlarım.

Anla kalbimi, Sana ihtiyacı var,

Kalkıp gitme yanımdan, tut ellerimi.

Bitmez derdimin sende ilacı var,

Nasıl geldik, nasıl gideceğimiz bellimi?

Son bir defa çal gönül telimi,

Toprak alıp gitmeden bedenimi,

Son bir defa tut ellerimi,

Bekliyorum gel; kollarım açık, Seni.

Neden Seni hatırlatır,

Biten güm başlayan gece,

Ardından bir hüzün, 

Bitmeyen bir işkence.

Son gözyaşlarım, bir daha ağlamam ardından,

Dönecek diye bekleme beni, boşuna bakarsın.

Sevda denen çıkan kordur garibin bağrından,

Sen bu sevgiyi, arasan bulamazsın.', 'Yarın mahşer yeri gelip, kurulsa, Bir damla teselline muhtaçtır bağrım.  O gün senin ahval benden sorulsa, O dün gitti deyip ağlarım. Anla k...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sen!..Yine Sen! ...', 'yine-sen-yine-sen-ahmet-temel-micwu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O sevdiğim akşamlardan biri yine 

gece gündüzle çekişiyor ;

iklim tabiatına aykırı!

Gündüz güneşi gösteriyor ''iklim yaz'' derken

Geceyse ispatlıyor sonbaharı 

serin rüzgarlarıyla

İşte o rüzgar ;

uğraşmaz gecenin dağdağsıyla

parlak ışıklar saçan uçakların sefasıyla

Geçiyorum yine bab''ul -beyt''ten 

tükkettiğin soluğu içime çekmek umuduyla 

onu ciğerlerimin en ücra köşesine

bir mahzene ya da mavisakalın 40. kapısına

hapsedercesine...

İşte bu da o ruzgarın yardımıyla

Kim demiş

kara göklerdeki yıldızların ışıltısına baktığımı ,

Ben bakıyorum oysa kara gözlerindeki parlaklığa

Kalbim biliyorum belli edecek ,

az sonra fırlayacak olduğu yerden,

Üstelik dilim de ona eşlik edecek,

anlayacaksın heyecanımı

yüzümden süzülen terden

Aman Allahım !...

avuçlarımda pamuk demeye dilimin varmadığı ellerin

ince dudakların soylemiyor

ama haykırıyor sevgini bana gözlerin.

Şaşırıyorum 

''hala yerinde mi kalbim?''

ve sarılıyorum sana bir daha bırakmamacasına

Çektiğimde tüm gücümle  seni kendime

sol ytanımdaki tıkırtıyı sağ yanımda da hissediyorum

anlıyorum ki o da senin kalbin

                11-06-2000/PAZAR   22:26', 'O sevdiğim akşamlardan biri yine  gece gündüzle çekişiyor ; iklim tabiatına aykırı! Gündüz güneşi gösteriyor ''iklim yaz'' derken Geceyse ispa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Temel']::text[], 8.5, '{"poet":"Ahmet Temel","poet_slug":"ahmet-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yine-sen-yine-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından-3', 'akort-makamindan-3-salih-parlak-wiby6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin aşk aşk dediğin,

Bana fayda sağladı mı?

O vefasız bildiğim,

Yoksa oturup ağladı mı?

Kirpiklerin ok olsun, atsın kaşların,

Sevdiğini bileyim, silme dursun göz yaşların,

Sonu hep aynı değil midir?

''Gülüm'' ile başlayan aşkların.

Sevincim kederimi aştığı an;

Eğer geliyorsan sen aklıma,

Hasretini taşıyorsa yüreğim,

İnan ki seni çok seviyorum.

Ölsem ne olurdu hasretinden?

Sadece dünyadan  biri eksilirdi.

Gidenin yerine gelir biri elbet;

Ne demişler; kime niyet kime kısmet.

Acıyorum sana verdiğim yıllarıma 

Boşuna yanmışım ahlarla vahlarla,

Neden koştum peşinden bilmem ki,

Saçlarıma ortak olmuş aklar siyahlarla.', 'Senin aşk aşk dediğin, Bana fayda sağladı mı? O vefasız bildiğim, Yoksa oturup ağladı mı? Kirpiklerin ok olsun, atsın kaşların, Sevdiğini bi...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Bir El', 'gizli-bir-el-ahmet-temel-1poz8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybolur hayatın tarifsi,z ahengi 

Zaman birtablodur düşer duvarlardan

Düşüncemi aşan gizli bir mimari,

Yükselir sonsuzluk manzaralarımdan

Bir yağmur sonrası gurbetinde akşam

Ruhumun dinmeyen nedametleridir

Ağarmış saçıma eskiyen şu zaman

Sonsuza dökülen ruhun nehirleridir

Yaslasam başımı hatırlarıma

Bir şah damar gibi buruk bir hayalle

Vuslat bilemem ki hangi diyarlarda

Bilmem yaşar mıyım çektiğim hasretle

Bir terennüm olur ah dudaklarımda

Gönlümde vuslatı sürükleyen hicran

Rüzgardır içimi körükleyen sevdan

Bir yağmur sonrası gurbetinde akşam

                        7-03-2000/ Salı     01:43', 'Kaybolur hayatın tarifsi,z ahengi  Zaman birtablodur düşer duvarlardan Düşüncemi aşan gizli bir mimari, Yükselir sonsuzluk manzaralarımdan B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Temel']::text[], 8.5, '{"poet":"Ahmet Temel","poet_slug":"ahmet-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gizli-bir-el-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnizlik Kurdu', 'yalnizlik-kurdu-cezmi-ersoz-swfs9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Simdi sen gideceksin, git''

guzelligini, ulasilmazligini al ve git.

Birak beni eski kisimda

yarinimi gotur.

Gencligin o yara almaz bencilligine git.

Icinde git gide buyuyen o yalnizlik kurdunu

guzelligine dadanan o hastalikli huznunu

birak ve git...

Kibirli arzularina, altin golgedeki kusursuz yuzune...

Yillar sonra yasayacagin

unutuluslari, o acimasiz kislari

bana birak ve git ...', '''Simdi sen gideceksin, git'' guzelligini, ulasilmazligini al ve git. Birak beni eski kisimda yarinimi gotur. Gencligin o yara almaz bencillig...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-kurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Oradasin', 'sen-oradasin-cezmi-ersoz-h1bn2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen oradasin

Yazilmamis bir siir gibi...

saf ve masum

butun ofkem bu sana

basegmem ve sonsuzca

      arzulamam.', 'Sen oradasin Yazilmamis bir siir gibi... saf ve masum butun ofkem bu sana basegmem ve sonsuzca       arzulamam....', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-oradasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask Kararmak Uzeredir Odanda', 'ask-kararmak-uzeredir-odanda-cezmi-ersoz-lnfi5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski bir Turkce kitabinda

rastladim sana.

Sirtin pencereye donuktu,

odan kararmak uzereydi,

usulca one dusmustu basin

yorgun bir dusu tasiyordun omuzlarinda.

Birini bekliyordun,

kendini bekler gibi...

Ne zaman askin adi gecse

sen gelirsin aklima...

Sirtin pencereye donuk,

basin one dusmus,

bir inanc titresir, yarali, yorgun omuzlarinda

Ne zaman adin gecse

eski bir Turkce kitabinda

ask kararmak uzeredir odanda...', 'Eski bir Turkce kitabinda rastladim sana. Sirtin pencereye donuktu, odan kararmak uzereydi, usulca one dusmustu basin yorgun bir dusu tasiyo...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-kararmak-uzeredir-odanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Kadinsin Sen', 'eski-bir-kadinsin-sen-cezmi-ersoz-4bhnv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski bir kadinsin sen,

aski ogretmek icin tekrar tekrar dirilen...

Olumunu bekletiyor simdi seninle

sevdasi yarim kalmis omurler.

Bogulmus ve kanla karismis yuzu denizin

sevginle duruluyor...

Ask, unutulmus bir sanat gibi,

agirbasli bir cileyle ogreniliyor simdi

Eski bir kadinsin sen,

aski ogretmek icin celladini tekrar tekrar 

                                                         dirilten...', 'Eski bir kadinsin sen, aski ogretmek icin tekrar tekrar dirilen... Olumunu bekletiyor simdi seninle sevdasi yarim kalmis omurler. Bogulmus v...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eski-bir-kadinsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap', 'hesap-muzeyyen-tuba-741x8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük dünyasında,hayata vokal yapan düşünceler,

Alkışlardan sonra el çırpan eller.

Menfaat için yaşayanlar hayatı,

Ve kolları bağlı oturanlar

Beş  para etmeyenlerin önünde...

Düşünmemek  elde mi düşünce suçlusuyken?

Yanlışlar hangileri kimlere göre?

Demirler ardındaki masum beyinlere

Hesap verecek misiniz günün birinde?', 'Küçük dünyasında,hayata vokal yapan düşünceler, Alkışlardan sonra el çırpan eller. Menfaat için yaşayanlar hayatı, Ve kolları bağlı oturanla...', ARRAY['Türk Edebiyatı','Şiir','Müzeyyen Tuba']::text[], 8.5, '{"poet":"Müzeyyen Tuba","poet_slug":"muzeyyen-tuba","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hesap-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesizdi Asilligin', 'kimsesizdi-asilligin-cezmi-ersoz-koa8w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimsesizdi asilligin

Soyu tukenmis masal kuslari gibi

beklerdin beni dukkanlarin onunde

sokak koselerinde...

Kimse sigamazken kendi gecesine

sen kapilarin onundeki

sahipsiz dalginliga vurulurdun

Cok iyi bildigin bir meyhaneydi dunya

duslere karsi yasanan...

Tehlikeliydin, kimsesizdi asilligin

en kirli yerde

arardin sevgiyi...

en dipte...

Hayatin en unutulmus yerinde...', 'Kimsesizdi asilligin Soyu tukenmis masal kuslari gibi beklerdin beni dukkanlarin onunde sokak koselerinde... Kimse sigamazken kendi gecesine...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimsesizdi-asilligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesine Dondun Hep', 'sesine-dondun-hep-cezmi-ersoz-66cuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cocukluk bahcendi sesin senin,

alevlerle mesut, cicekli aynandi.

Sizlattiginda karsiliksiz dusler bileklerii,

nefesini kanattiginda veda sozleri

yoruldugunda ayriliklardan,

artik hep boyle olacak, dediginde

sesine dondun hep.

Orada binlerce sevdali goz seni gorsun diye,

sesinin cocukluk bahcesine...', 'Cocukluk bahcendi sesin senin, alevlerle mesut, cicekli aynandi. Sizlattiginda karsiliksiz dusler bileklerii, nefesini kanattiginda veda soz...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sesine-dondun-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyur, Bir Daha Uyanmazdin', 'uyur-bir-daha-uyanmazdin-cezmi-ersoz-sr9br', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Martilarin sana dogruyu soyleyecekti

arzu tramvaylarina binmeseydin...

Acilarin seni yeni bir sehre goturecekti

yuruyusune vurulmasaydin...

Tuhaf, ele gecmez, tehlikeli bir hayvandin.

Sehrin yaban adamlari sana oyle bakmasaydi,

uyur, bir daha uyanmazdin...', 'Martilarin sana dogruyu soyleyecekti arzu tramvaylarina binmeseydin... Acilarin seni yeni bir sehre goturecekti yuruyusune vurulmasaydin... ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uyur-bir-daha-uyanmazdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Egil', 'biraz-egil-cezmi-ersoz-koiys', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yaz Latince kursuna gitme,

                                                  beni incele.

Seneye ucarsin planorle.

Bu yaz boslugu benim cinnetimde dene...

Sana cagdisi bir romantizm getirdim,

ilkel bir soyutlama...

Isletme tezini sonra verirsin, bu yikimi             

                                                           kacirma...

Hirslarini yatistir bir sure icin...

Biraz egil, nefesimi dinle,

hic olmazsa, uzuluyormus gibi yap...

Yeniden donersin eski hayatina,

biraz saygi duy, biraz zaman kaybet...

Bak beni nasil zehirleyecek,

icinde tasidigini bile farketmedigin o ask...

Kucumseme, deneyimdir ; soranlara

                                                              anlatirsin

Senin icin bu yenilgi, bu dagilip

                                                      parcalanma...

Bu yaz Latince kursuna gitme, beni incele...', 'Bu yaz Latince kursuna gitme,                                                   beni incele. Seneye ucarsin planorle. Bu yaz boslugu benim c...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biraz-egil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Sonbaharı', 'hayatin-sonbahari-zubeyde-basaran-g1u5h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bedenimin yüzünde onlarca kırışık içinde

Beni ben eden bir tek kırışığım var

Artık yaşlandım, yoruldum

Kıvrım kıvrım nakış dokurdu  gözlerim

Güzelliğim ay yüzlüydü

Kipriklerimdeki  şebnemde  gülümserdi

Karanlıklar;  gözlerimin içinde

matemsiz nur bulurdu

içim sığmazdı içime

Duygularım hep, kouşurdu, şakırdı

Şimdilerde  yorgunum

Artık  vuslatı yaşama hazırlığındayım

Eylüllerinde  keyfini sürmeliyim

Yüreğim,  parmaklrım gibi

Yitirdi  feyzini

Fersiz  oldum

Fersiz kaldım

Yaşlandım...', 'Bedenimin yüzünde onlarca kırışık içinde Beni ben eden bir tek kırışığım var Artık yaşlandım, yoruldum Kıvrım kıvrım nakış dokurdu  gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayatin-sonbahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Şehrin Islanmyan Adamı', 'yagmurlu-sehrin-islanmyan-adami-yalniz-sevgi-cxjeu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur yumuşatır insanın yüreğini 

benim memleketimde hergün yağmur yağardı 

Hergün ıslanırdı saçlarım. 

Sen... hiç ıslanmazdın 

Her yağmurda kaçardın yanımdan 

Çocuktun... çocuk gibi sakınırdın damlalardan 

Bugünlerin o günlerden kaldı üstüne 

Gözlerin de hiç ıslanmadı senin 

Yağmur değmedi ki hiç yüreğine 

Sen her yağmurda kaçardın 

Ben,seni hiç kovalamazdım 

Kendi haline bıraktım seni 

Sen benim memleketimin, 

Yumuşak yağmurlarından kaçarken 

Başka memleketlerde kapılacağın 

Fırtınaların hezimetiyle kavrulacaksın 

Yağmurlarda yürümeyi hiç bilmediğinden 

Ayağın sulara takılacak 

Sırılsıklam olacaksın ıslaklığın çetrefilinde 

Düşeceksin,ağlayacaksın 

O hiç ıslanmamış gözlerin,yaşlarla yanacak 

Bense uzaktan seyredeceğim. 

Korkma elinden tutup kaldıracak kadar merhametliyim 

Çünkü yağmurlu şehrin yağmurlarıyla 

Islanırdı benim yüreğim 

Sen hep kaçardın 

Hadi yine kaç şimdi... 

Yağmurlu şehrin küçük çocuğu 

Ben o yağmurlarla büyüdüm 

O yağmurlarla ıslandı yüreğim 

Sen o yağmurlarda susuz büyüdün 

Şimdi Bir Ömür Susuzluğa Mahkumsun... 

                                                           (30,03,2001)', 'yağmur yumuşatır insanın yüreğini  benim memleketimde hergün yağmur yağardı  Hergün ıslanırdı saçlarım.  Sen... hiç ıslanmazdın  Her yağmurd...', ARRAY['Türk Edebiyatı','Şiir','Yalnız Sevgi']::text[], 8.5, '{"poet":"Yalnız Sevgi","poet_slug":"yalniz-sevgi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yagmurlu-sehrin-islanmyan-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vişne Bahçesi', 'visne-bahcesi-cezmi-ersoz-utagg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gunah kokulu visne bahcesinde

yuzunun en eski haliydi

aldatan beni.

Acitmamakicin disi tas, ici su dolu kalbimi

bez bebegine en gizli adimi verdin.

Oysa kacislarina vurgundun sen.

Ask degildi ozgurlugundu

ruhunu bir visne bahcesi kadar

kaygan ve elegecmez yapan.

Cunku ozgurlugun ogretti sana

dayaniksiz ask ortulerinin altinda

en uzun omurlu intikamlarin uyudugunu

Gul kokulu guneste

kuruturken hayallerini ve kadife etegini

bana baglanmadigin icin

kirli bir sevdayla bagladin beni

o uzun omrune...', 'Gunah kokulu visne bahcesinde yuzunun en eski haliydi aldatan beni. Acitmamakicin disi tas, ici su dolu kalbimi bez bebegine en gizli adimi ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/visne-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim Sevinçli Aşkımız', 'yetim-sevincli-askimiz-cezmi-ersoz-vmjtx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasil da unuttuk,

kimsesiz odalarda

iste vaktidir kendimizden kopmanin,

dedigimiz o sonsuzluk anlarinin

bizi herkesten ayirdigini...

Nasil da unuttuk,

mutluluktan,hazdan,sevincten

daha cok bizi hayata baglayan

o istirap dolu hayaletin,

o kara hulyanin

bizi herkesten ayirdigini...

Simdi yetim sevincli askimiz

buyulenmis,hayran kendine,

simdi vakitsiz, belki cok gec, kayitsiz

                                                     kendine...

Atiyor tenini, tenindeki ruhu

atiyor,

kor ve iradesiz bir sehvetin atesine...', 'Nasil da unuttuk, kimsesiz odalarda iste vaktidir kendimizden kopmanin, dedigimiz o sonsuzluk anlarinin bizi herkesten ayirdigini... Nasil d...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yetim-sevincli-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hep Bir Baskasi Savunuyor', 'beni-hep-bir-baskasi-savunuyor-cezmi-ersoz-eisp2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onca atilistan sonra

balkonuma dondum

Onca bilgi utandigim cocuklugum icindi

Cunku beni hep bir baskasi savunuyor

Sesimden, ellerimden, gulusumden biliyorum

Hep sakladigim yara izini

balkonumdan odama goturuyorum iste...

odamdan bir kez olsun cikartmadigim

sesimden, ellerimden, gulusumden

                                                          biliyorum...', 'Onca atilistan sonra balkonuma dondum Onca bilgi utandigim cocuklugum icindi Cunku beni hep bir baskasi savunuyor Sesimden, ellerimden, gulu...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-hep-bir-baskasi-savunuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cana Yakin Hayalet Ol', 'cana-yakin-hayalet-ol-cezmi-ersoz-avr3l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Simdilik beni en son sen ara

uzunc melegi dolasip dursun odamda.

Kis omuzlarini, kucult kendini

birsey isteme, istemeye yeltenme

arzuyu arzulama

hosa gorun, hosa git...incitme

incin, icini kanat... Hep acit kendini

Kendini kalabaliklara sun..Bosluga el salla

guleryuzlu ve canayakin bir hayalet ol

yuzunu hep onlara tut

gozlerini icine cevir

nefesini tut ve yasa

Cunku bitmedi daha

icindeki o buyuk hazirlik

ve sen sevdikce...sevdikce

amansiz bir sevda halinde birgun

olecek bu kasvet, olecek

benimle birlikte.

Simdilik beni en son sen ara

uzunc melegi dolasip dursun odamda.', 'Simdilik beni en son sen ara uzunc melegi dolasip dursun odamda. Kis omuzlarini, kucult kendini birsey isteme, istemeye yeltenme arzuyu arzu...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cana-yakin-hayalet-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler -Dostlar', 'turkuler-dostlar-vedat-sumbul-9j11a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aksu Çayı üzerinde

Dökük bir meyhanede

Durmadan türkü söyledik dostlarla...

Sarı Gelin,Yemen Türküsü,Metris ...

En çok da Kara Tren...

Zemheri ayazıydı,

Ben durmadan türkü söyledim dostlara...

En çok da Kara Tren...

Şimdi her türküde dostlar gelir aklıma,

Kara Tren deyince Reşat...

Siyahtan mavi damıttık

Aksu Çayı''nın serininde.

Geceydi,zemheri ayazıydı,

Belki biz biraz çocuktuk,

Türkülere sevdalı.

Kara Tren''e kara sevdalı...

Sırtımızda naftalin kokulu hüzünlerle

İnadına gülümserdik...

En yaşlımız Esat Abi''ydi;

Bir Atatürk''e bir de bize laf söyletmezdi...

Türküler söylerdi bize

Çağına yetişemediğimiz...

Ve biz durmadan daha çok severdik Esat Abi''yi.

Esat Abi,güzel adam ! 

Selam olsun sana.

Bu zemheride sustuk...

Eksildik...

Belki baska turkulerin iklimini secti dostlar

Simdi yoklar...

Onlar ki

Ben benken

Bulutta yagmur kadar coktular...

Dostlar !

Selam olsun size...

Esat Abi

         Sinan Abi

                    Mehmet Abi

                                   Resat

                                         Ali

                                            Yener...

Selam olsun size...', 'Aksu Çayı üzerinde Dökük bir meyhanede Durmadan türkü söyledik dostlarla... Sarı Gelin,Yemen Türküsü,Metris ... En çok da Kara Tren... Zemhe...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sümbül']::text[], 8.5, '{"poet":"Vedat Sümbül","poet_slug":"vedat-sumbul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/turkuler-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engellenmiş Kaçak', 'engellenmis-kacak-cezmi-ersoz-cepwg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırıldığın zaman,

çitin ötesindeki insanları düşün,

acıları içini ısıtsın, doğrulansın yüzün,

gözlerine çekimser bir mevsim süsü ver

korkma, kimsenin gözükmez içi...

Hem bak nasıl da harcanıyor dünya

aileler... sevgililer... bütün ülke.

Üstelik kadının yüzü paramparça

kadın kalpten ölecek,

o kadına sakın nüfuz etme...

Boğ odana deniz menevişleri getiren kızı

vehimlerinden yaptığın sevginle,

ufacık sahnelerde büyük öfkeler tasarla,

antika bir çerçeve uydur

büyük insanlık derdine…

Nasılsa çitin ötesinde insan dolu,

sen gövdeni düşün yalnızca

göğsünün en ince yerinde…

Hem bak nasılda harcanıyor dünya

aileler… sevgililer… bütün ülke

üstelik kadının yüzü paramparça,

kadın kalpten ölecek,

o kadına nüfuz etme…

Kış başladı… başlayacak,

artık hesaplar açık veriyor,

bir isim bulmalısın kendine

engellenmiş kaçak… engellenmiş kaçak…', 'Kırıldığın zaman, çitin ötesindeki insanları düşün, acıları içini ısıtsın, doğrulansın yüzün, gözlerine çekimser bir mevsim süsü ver korkma,...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/engellenmis-kacak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bir Oyun Değil', 'hayat-bir-oyun-degil-hikmet-tugrul-tekeli-ppi2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstemedigimiz şekilde yönlendi hayatımız

        Farklı kimliklere büründük

        Oysa biz neler düşünüyorduk 

        Neler hayal ediyorduk

        Artık anladım yaşam  bir oyun degilmiş

        Hayatı zamanında yaşamak varmış 

        Düşünceleri gerçekleştirmek gerekmiş

        Bir of çekmemek 

        Pişman olmamak için

        Hayat bir oyun degil

        Şimdide zaman akıp geçiyor

        Yine başaramıyoruz

        Biz hep seyirci 

        Biz hep zavallı

        Hiç başröl oyuncusu olamıyoruz

        Zaman zaman dönüp bakarız geriye

        Neler görürüz acaba

        Bir sürü yalan,dolan

       Saçma sapan gereksiz şeyler

       Gerçekten düşüncelerimiz,hayallerimiz bumuydu

       Yaşantımız böylemi olmalıydı

       Geç kalmadık

       Ama yinede farkında degiliz

       Yine başröl oyuncusu olamıyoruz

       Anlamıyoruz 

                           HAYAT BİR OYUN DEGİL', 'İstemedigimiz şekilde yönlendi hayatımız         Farklı kimliklere büründük         Oysa biz neler düşünüyorduk          Neler hayal ediyord...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayat-bir-oyun-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Denizi', 'sevda-denizi-omer-deniz-2nm2y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onlar ki yaşarlar bir sevda uğruna 

Akarlar coşkuyla gönülden gönüle

Onlar ki ölürler bu sevda uğruna

Akıtırlar kanlarını sevda denizine', 'Onlar ki yaşarlar bir sevda uğruna  Akarlar coşkuyla gönülden gönüle Onlar ki ölürler bu sevda uğruna Akıtırlar kanlarını sevda denizine...', ARRAY['Türk Edebiyatı','Şiir','Ömer Deniz']::text[], 8.5, '{"poet":"Ömer Deniz","poet_slug":"omer-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevda-denizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-alacan-yagmur-povkj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne hasretler gördüm ben 

aşkına endeksli

ben  seni ne kadar sevsem

hasretin o kadar büyüyor içimde 

dön ne olur dön 

bitir bu hasreti

seni seviyorum seveceğim

anla halimi

geceler ecel oldu 

sensiz geçmiyor 

ey benim bahtı kara sevgilim

ey benim yaşanılası iklimim

ey benim dünyam

rüyam 

söylenecek sözüm yok başka 

bekliyorum dön bana', 'ne hasretler gördüm ben  aşkına endeksli ben  seni ne kadar sevsem hasretin o kadar büyüyor içimde  dön ne olur dön  bitir bu hasreti seni s...', ARRAY['Türk Edebiyatı','Şiir','Alacan Yağmur']::text[], 8.5, '{"poet":"Alacan Yağmur","poet_slug":"alacan-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-siddik-altinkaynak-vjwim', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Körpeciktim sana geldim

Üsküdar''ı kamp eyledim,

Her yerini ayrı sevdim

Ne güzeldin sen İstanbul

Gençliğimi aldın benden

Yıllarımı çaldın benden,

Lodos ile Kadıköy''den

Kovdun beni sen İstanbul

Benim için ömürdün sen

Her şeyinle güzeldin sen,

Razı geldim ne ettiysen

Yokum artık ben İstanbul

Bir daha dönmem sana,

Hakkım helal benden yana,

Son bir sözüm olsun sana

Sağlıcakla kal İstanbul.', 'Körpeciktim sana geldim Üsküdar''ı kamp eyledim, Her yerini ayrı sevdim Ne güzeldin sen İstanbul Gençliğimi aldın benden Yıllarımı çaldın ben...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Altınkaynak']::text[], 8.5, '{"poet":"Sıddık Altınkaynak","poet_slug":"siddik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim ki', 'i-sterdim-ki-faruk-aysoy-3p35e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsterdim ki,

Senden kopmak,

Kalbimden söküp atmak,

Bir daha hiç hatırlamamak,

Ama elimde değil.

İsterdim ki,

Birlikte göğe çıkmak,

Yıldızlarda dolaşmak,

Hiç ayrılmamak,

Ama elimde değil.

Elimden sadece ,

Seni hep anımsamak,

Hiç unutmamak,

Ölürken bile ismini sayıklamak,

Gelir çünkü sen çok uzaklardasın...', 'İsterdim ki, Senden kopmak, Kalbimden söküp atmak, Bir daha hiç hatırlamamak, Ama elimde değil. İsterdim ki, Birlikte göğe çıkmak, Yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/isterdim-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kendini Tazeliyordu İsimsiz Dağlarda', 'hayat-kendini-tazeliyordu-i-simsiz-daglarda-faruk-dag-akqsv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat kendini tazeliyordu isimsiz dağlarda,

Yüreklerimizde yarım kalan sevdaların boynu büküklüğü,

Dilimizde söylenmemiş sevda sözlerinin pişmanlığı...

Hayat kendini tazeliyordu isimsiz dağlarda.

Doğa aydınlık günleri yaşatmanın mutluluğu ile sonbaharlaşıyordu, sararıyordu

Rüzgarlar uğuldamaya hazırlanıyordu yüksek tepelerde

Göçmen kuşlar çoktan gitmişti buralardan

Güneş ısıtmıyordu eskisi kadar

Geceler daha soğuktu içimiz titriyordu.

Bir biz kalmıştık, gidenlerin ardından bakakalan

''Asıl giden değil, kalandır terkeden, giden de bu yüzden Gitmiştir zaten'' diyordu kalın kitaplar yazan adam

Belki de biz terketmiştik onları, 

Onlar da bu yüzden gitmişti belki

Hayat kendini tazeliyordu isimsiz dağlarda

Terkedilmişliğin acısıyla yangın yerine dönmüştü yüreklerimiz

Herşey tarumar...

Kaç fırtına atlatmıştık,

Sadece saçlarımız dağılmıştı

Zaten hep dağınık bırakmıştık.

Alışamıyorduk yalnızlıklara,

Hep birileri olsun istiyorduk hayatlarımızda

En azından rakımız olsun yanıbaşımızda

Bir de bizden başkasının açmasına izin vermediğimiz

Sigara paketlerimiz.

Yetmiyordu belki, daha fazlasını istiyorduk,

Ama biz bunlarla avunuyorduk...

Biz hep mahzunduk...

Hayat kendini tazeliyordu isimsiz dağlarda.

Kendimizi kandırıyorduk aslında,

Yalnızlığa alışık değildik.

Tek odalı havasız evlerde hep geçmişi aradık,

Tanıdık bir sesin kulaklarımıza dolmasını bekledik,

Kapının çalmasını,

Halimizi soracak birilerinin ansızın çıkıp gelmesini bekledik

Sessiz gecelerde.

Hiçbiri olmadı halbuki,

Biz hep yalnız yaşadık.

Yüreğimizi burkuluyordu akşamüstü sohbetlerinde,

Dinlediğimiz şarkılar da yalancıydı ''yıllara rest çektim'' dediklerinde

Yaşanan yıllara rest çekilmiyordu,

Onlar yanıbaşımızdaydı, elimizi uzatsak ulaşacaktık..

Uzanacak gücü bulamıyorduk, 

Nereden geldiğini bilmediğimiz bir utançla...

''Yolcu girişlerindeki'' vedayı unutamıyorduk,

Gözlerimiz buğulanıyordu eski evin sokağına girdiğimizde,

Hayat kendini tazeliyordu isimsiz dağlarda,

Şimdi sıra bizdeydi,Üzerimize kara bir şal gibi serilen

Utangaçlığımızı yırtmanın zamanı gelmişti

Kendimize ait gerçek bir hayatı yaşamanın zamanı gelmişti

Hayatı yüreklerimizde bir kez daha tazelemenin zamanı gelmişti, geçiyordu...

Biz bu hayatı böyle devam ettiremezdik,

Hayatı tazelemeliydik ,

Ve yeniden mutlanmalıydık

Hayat kendini tazeliyordu isimsiz dağlarda,

Biz geride durmamalıydık....', 'Hayat kendini tazeliyordu isimsiz dağlarda, Yüreklerimizde yarım kalan sevdaların boynu büküklüğü, Dilimizde söylenmemiş sevda sözlerinin pi...', ARRAY['Türk Edebiyatı','Şiir','Faruk Dağ']::text[], 8.5, '{"poet":"Faruk Dağ","poet_slug":"faruk-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/hayat-kendini-tazeliyordu-isimsiz-daglarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-siddik-altinkaynak-qgrrv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu zaman,aman olmuş

Kötüler yaman olmuş

Sevdalar yalan olmuş

Aman,aman vay zaman

Asil nesil rezil olmuş,

Dalkavuklar vezir olmuş

Mazlum yüzü,gülmez olmuş

Aman,aman vay zaman

Kötülere bey denmiş,

Yiğidin hakkı yenmiş

Zamanın sonu gelmiş

Aman,aman vay zaman

Hani Yunus Emre''ler,

Hani Aslı,Kerem''ler

Gelmez oldu güzeller

Aman,aman vay zaman

Aman ettiğim zaman,

Güman ettiğim zaman,

Bel bağladığım zaman

Aman,aman vay zaman.

                   (20-03-2001)', 'Bu zaman,aman olmuş Kötüler yaman olmuş Sevdalar yalan olmuş Aman,aman vay zaman Asil nesil rezil olmuş, Dalkavuklar vezir olmuş Mazlum yüzü...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Altınkaynak']::text[], 8.5, '{"poet":"Sıddık Altınkaynak","poet_slug":"siddik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zaman-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Mısın', 'var-misin-faruk-aysoy-wtd9g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sadece yalnızlığın olduğu bir dünyada,

Benimle yaşamaya var mısın?

Hayatın en mutsuz gününde,

Benimle olmaya var mısın?

Kaderimle yüzleşirken,

Bana yardım etmeye var mısın?

Sana aşkımı sunduğumda,

Karşılık vermeye ver mısın?

Eğer tüm bunlara varsan,

Benimle bir ömür boyu birlikteliğe var mısın?', 'Sadece yalnızlığın olduğu bir dünyada, Benimle yaşamaya var mısın? Hayatın en mutsuz gününde, Benimle olmaya var mısın? Kaderimle yüzleşirke...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/var-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-siddik-altinkaynak-2r83p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni!

Öyle istedim,

Öylesine istedimki

Başka arzum olmadı.

Seni!

Öyle sevdim,

Öylesine sevdimki

Nefret beni tanımadı.

Seni!

Öyle yaşadım,

Öylesine yaşadımki

Ölüm beni istemedi.

Seni!

Öyle bekledim,

Öylesine bekledimki

Beni bekleyen olmadı.', 'Seni! Öyle istedim, Öylesine istedimki Başka arzum olmadı. Seni! Öyle sevdim, Öylesine sevdimki Nefret beni tanımadı. Seni! Öyle yaşadım, Öy...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Altınkaynak']::text[], 8.5, '{"poet":"Sıddık Altınkaynak","poet_slug":"siddik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Bilirsin', 'nerden-bilirsin-faruk-aysoy-9adyq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbimde ağrı sızı,

Gözümde çeşme yolu,

Aklımda Selim şuuru,

Sen sensizliğin ne demek olduğunu nerden bilirsin.

Gönlümde bir boşluk,

Fikirlerimde hep karanlık,

Çöker üstüme ağırlık,

Sen sensizliğin ne demek olduğunu nerden bilirsin.

Varsa şayet bir umut, aydınlık,

Söyleki kurtulayım bu halimden,

Olayım gene aklı, fikri, ruhu yerinde bir mahluk,

Gözlerim kapanana kadar senin aşkından.

Son olarak eklerki Aşık Faruk,

Vardır gönlünde koca bir delik,

Eğer sen sunmazsan ona sevgi,aşk,

Aşkından olacak başına bela sağlık...', 'Kalbimde ağrı sızı, Gözümde çeşme yolu, Aklımda Selim şuuru, Sen sensizliğin ne demek olduğunu nerden bilirsin. Gönlümde bir boşluk, Fikirle...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerden-bilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'II', 'ii-deniz-ulas-0tlh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman bizi gördükçe acı çekerdi,

utanırdı acımasız hukuğundan.

Şimdi her zamanki klişe lafları savuruyor

zamana esir insanlar.

''Tek ilaç zamanmış''...

Ama bilmiyorlar,

Seninle biz

Tüm sınırlandırılmışlığında zamanı kendi istediğimiz gibi yaşardık.

Günler hafta,aylar yıldı.

Sensiz günler mevsim,aylarsa deste deste yıllar gibi.

Ve zaman o yapışkan ağlarını ördü.

Sensiz zamanlarda

Kabuslar, zaman kadar acımasız ve güçlü.

Yitik zamanlarımın kazanılmışlığıydın sen

En küçük sevinçleri bile

dünyaları kazanmış gibi kazanırdık seninle.

Çocuklar gibi deniz taşları toplardık

Yaşayamadığım tüm çocukluklar 

senin o kadınsı masumiyetinde yer bulurdu,

mavileri birbirine katardık.

Yaşayamadıklarıma yarım kalmış bir sevda ekledin

ve gittin.

Zaman tüm saniye, saat ve takvim zebanileriyle

abanıyor üzerime

Şimdi her gece,

Kararmış deniz kıyılarından,

kapkara taşlar toplayıp

Kara bir denize fırlatıyorum tüm gücümle

Kararan denizim

yeniden mavileşsin diye...', 'Zaman bizi gördükçe acı çekerdi, utanırdı acımasız hukuğundan. Şimdi her zamanki klişe lafları savuruyor zamana esir insanlar. ''Tek ilaç zam...', ARRAY['Türk Edebiyatı','Şiir','Deniz Ulaş']::text[], 8.5, '{"poet":"Deniz Ulaş","poet_slug":"deniz-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-tolga-gulduren-p703d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Can dostum nerdesin?

Sen boyle yapmazdın hiç

Bırakmazdın sevdiklerini

Hatırlarmsın sizin evin arkasındakı parkta yediğimiz çekirdekleri?

İlk flörtünü?

Camdan cama sigara içme yarışı yapardınız

Ya Muhsinin abinin orda içtiğimiz çaylar

Çaylar aynı...Muhsin abide öyle ama 

Ama sen nerdesin?

Barış, sen, ben...Ne çok konuşurduk sabahlara kadar

Amma severdin sen Esra''yı

Ablanın arabasını alıp Salacakta güneşin batışını izlediğimiz akşamları hatırlıyormusun?

Şilede boğuştumuz deli dalgaları?

Ara sokaklarda yaptığımız kavgaları?

Sırtından vurmuşlardı seni...Kalleşler

Yinede gitmedin beni bırakıp

Şimdi nerdesin?

Sen herzaman yanımdaydın

Yine ol...

Aslında beni senden ayıran belkide bu huyundu

Rabbinin çağrısınada koşarak gittin

Nasıl yenik düstü güçlü bedenin birkaç taş parçasına?

Yooo, öyle yetmez bana geceleri rüyalarımda yaptığımız sohbetler

Sana sarılmak istiyorum yine eskisi gibi

Sıkı sıkı kucaklamak içime sığdırırcasına

Can dostum nerdesin?

Uzayın bittiği, sonsuzluğun başladığı yerdesin

Ama sen hep benimlesin...', 'Can dostum nerdesin? Sen boyle yapmazdın hiç Bırakmazdın sevdiklerini Hatırlarmsın sizin evin arkasındakı parkta yediğimiz çekirdekleri? İlk...', ARRAY['Türk Edebiyatı','Şiir','Tolga Güldüren']::text[], 8.5, '{"poet":"Tolga Güldüren","poet_slug":"tolga-gulduren","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nerdesin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zilan', 'zilan-celal-ulgen-99v3m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kara yazgıdır Zilan;

                          Topraksız olmak, yetim kalmak yetmezmiş kimin

                          Sensiz de olmak kara yazgıdır kurban...

                          Bilisen

                          Kaç gece kaç gündüz adın sayıklamışam

                          İçimden atamamışam

                          Küçelerde yolun gözlemişem

                          El etmişem, işmar etmişem

                          Sen gülmüş geçmişsen Zilan...

                          Ne zaman büyümüşsen farketmemişem

                          Ne zaman ellerin büyümüş

                          Ne zaman gözlerin büyümüş

                          Ne zaman börünmüşsen kara çarşafa

                          Bir gözlerin görmüşem ceylan kimin

                          Vurulmuşam.

                          Sen gülmüş geçmişsen Zilan...

                          Daracık köçelere sığmamış sevdam

                          Seni Halilrahman''a sormuşam Anzılha''da

                          Urfa kalasında Nemrut köşküne adın kazımışam

                          Sen gülmüş geçmişsen Zilan...

                          Şimdi gelin olisen telli duvaklı

                          Yine gülü misen biye?

                          Kara Şar''dan gelen deli oğlan deyi misen?

                          Sevdanı içime gömdüm bilesen

                          Bu kentin hampara taşlarına sır sakladım.

                          Üç kuruşluk başlık parasına değer miydi Zilan...

                          Bilirem dahlin yoktur bu işte.

                          Töreler böyle demiş

                          Yazgılar böyle çizmiş.

                          Kim karşı gelmiş ki sende gelesen.

                          Atalar boynumuz kıldan incedir demiş...

                                

                          Her şafak seninle sökerdi Zilan.

                          Sıcak yaz geceleri seninle eserdi.

                          Ben siye şiirler okurdum.

                          Sen biye Urfa türkülerini...

                          Yediveren gülleri kimin açılırdın baharla

                          Karakoyun deresinden çiçekler getirirdin.

                          Önceleri inanmamıştım sevdigine.

                          Anladım zamanla.

                          Seni yitirmek kor kimin yaktı yüreğimi;

                          Acımı anla...

                        

  Kar ender yağardı Urfa''ya

                          Sevdamız yağan kar kimin aktı.

                          Hatırlı misen bir de tutkumuz

                          Yağmurda ''çömçe gelin'' oynamaktı...

                          Şimdi sen mi gelin olisen Zilan?

                          Sevgin bir yanda Töreler diger yanda

                          Duydum ki ''KUMA'' olimişsen

                          Akar suda saman çöpü gibi çaresiz

                          Ve de köle kimin İtaatkar, sessiz

                          Gidisen

                          Oldu mu ya?...

                          Kaçıncı asrını yaşamakta Harran''da toprak?

                          Bu kenti terkediyem Zilan.

                          Anzılha''da kutsal balıklar şahidim olsun ki

                          Bu kenti terkediyem...

                          Yasak mayın tarlalarını

                          Kaçakta kol verenleri

                          Can verenleri terkediyem...

                          Efsunlu akrepleri, çıyanları

                          Urfa kalasında kenetlenen

                          Efsane şahmaranı

                          Kümbetlerde barınan sahipsiz insanları, terkediyem.

                          Körpecik bedenine uzanan hoyrat elleri itmediğin için

                          Yıllardır söylenen ninniyi yazgı bellediğin için

                          Bu kenti terkediyem...

                          Bu sana son satırlarım Zilan...

                          Biliyem unutacaksan beni.

                          ''Unutmam'' deme biye

                          Davullar uranda unutmalısan.

                          Yoksa nasıl yaşayabilir

                          İnsan...

                       

  Hani  nar ağaçları çiçek açardı ya

                          Hani Urfa divanı çalınırdı sıra gecelerinde.

                          İşte ben

                          Her çiçek açanda nar ağaçları

                          Ve söylenende Urfa türküleri

                          Seni ve gülüşünü hatırlayacağam...

                          Bundan böyle cigaramda dumansın

                          Kaçak tütünden sarılmış...

                          Her içime çekişte ağun yakacak beni.

                          Kendini düşünmedin

                          Beni düşünmedin

                          Sevdanı düşünmedin

                          Çocuklarını düşün.

                          Seni tutsak

                          Beni esrik eden töreler

                          Çocuklarını da yakacak bir gün...

                        

   Bu kara yazgı değildir ZİLAN...

                          Topraksız olmak, yetim kalmak yetmezmiş kimin

                          Sensiz olmak da kara yazgı değildir kurban...

                          Bu çağlar boyu insanları kul eden

                          Bağnazlıktır.

                          Ki yıkılacak.

                          Bilesen ZİLAN

                          Sen görmesen de

                          Ben görmesen de

                          Ceylan gözlü çocukların görecek ZİLAN...

   Not: Zilan 1968 yılında yaşanmış bir

Olaydan  esinlenerek yazılmıştır. Şive ile okunması gerekir.

Urfa''daki feodal düzenin hala devam ettiğini söylemek şiirin niçin 

Eskimediğini  yanıtlamaktadır.', 'Bu kara yazgıdır Zilan;                           Topraksız olmak, yetim kalmak yetmezmiş kimin                           Sensiz de olmak ka...', ARRAY['Türk Edebiyatı','Şiir','Celal Ülgen']::text[], 8.5, '{"poet":"Celal Ülgen","poet_slug":"celal-ulgen","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/zilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ve Ten', 'ben-ve-ten-zubeyde-basaran-nsnkg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ben olalı binlerce ben içinde

Ben ten olmuşum binlerce kendim içinde

Benlerime benler eklemişim 

Kamilini yaşayan   ben  olmuşum,  tenim içinde

Sonsuz olmuşum  susuz aklmışım

Acılarımı  köz yapıp  yaralarıma nerhem yapmışım

Kendim olmuşum,  ruhumla katmerli

        ten olmuşum.', 'Ben ben olalı binlerce ben içinde Ben ten olmuşum binlerce kendim içinde Benlerime benler eklemişim  Kamilini yaşayan   ben  olmuşum,  tenim...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-ve-ten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde Sen Varsan Eğer', 'i-cinde-sen-varsan-eger-julide-yildiz-z84zo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir demet kasımpatı aldım bugün

Meğer ne de özlemişim 

Çiçekleri,çiçeklerimi

Bir demet sevgi sundular bana

Renk renk kokularıyla hormonlanmış

sevgi sundular.

Unutmamışlar demek 

Ne güzel!

Benim yine onlarla olduğumu unutmamışlar!

Demek hala seviyorlar beni

Hala beyinlerindeyim,kalplerindeyim sımsıcak

Demek hala yol gösreriyorum onlara...', 'Bir demet kasımpatı aldım bugün Meğer ne de özlemişim  Çiçekleri,çiçeklerimi Bir demet sevgi sundular bana Renk renk kokularıyla hormonlanmı...', ARRAY['Türk Edebiyatı','Şiir','Jülide Yıldız']::text[], 8.5, '{"poet":"Jülide Yıldız","poet_slug":"julide-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icinde-sen-varsan-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar', 'sokaklar-sair-met-fnq0u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok anım var o sokaklarda,

Bir kapı gıcırtısı ile başlayan

Bir aşkla sona eren ,

Sessiz vakitlerde;

Uçmak isteyen aşk naraları vardı.

O kuytu,

Şehirin içinde,

Şehirden uzakta darlarda.

Bir sevenim de vardı belki bu aralarda.

Küçük penceresinden,

Perde arkası muhabbet diliyle

Aşkını beyan etmek isteyen.

Dahası kaçma eğiliminde ;

Buradan, buradakilerden.

Yani çöpçü sesinden,

İşçi yumruğundan,memur kaleminden,

Baba ocağı,ana kucağından,

Abi dili,arkadaş kıskançlığından,

Çok da düşününce;kendinden,

Benliğinden,kaçma eğiliminde.

Bir sevenim de vardı 

Tam böyle, bu sokakllarda.

Ve kalbim her acıyla dolduğunda,

Yumruğumu;

Hep o çürük duvarlara vurdum.

Avucumun içine düşmesiyle avundum

Sıva parçalarının.

Güçsüzlüğün duvarındaki,

Gücümle sevindim,oralarda.

Tuhaf gelmezdi:

Sevgilinin dudaklarına serserice değme,

Bayağı giyinip, küfür etme;

Hepsi hayatım,yaşam biçimimdi işte öyle.

Önceleri kızar takılırdım bizim terziye,

''Ne biçim hayata kılıf biçmişsin'' diye

Şimdi ise uzaklaştığımı görüyorum her sabah.

Her sabah,bir sancı gibi takılıyor ayağıma;

Sokakları yıkılmış şehrin,pembe kaldırımları.

Anlaşılan o ki özleyeceğim seni,

Gözde şehrin dar sokakları.

                                                                        Kasım-1998', 'Çok anım var o sokaklarda, Bir kapı gıcırtısı ile başlayan Bir aşkla sona eren , Sessiz vakitlerde; Uçmak isteyen aşk naraları vardı. O kuyt...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin', 'sen-benimsin-tarik-sahin-uw6xd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benimlesin

Bazen yalnızlığımda

Bazende tüm yıkılmışlığımın

Ve de ayrılıklarımın orta yerinde

Hayata bağlandığım

O gece yarılarında

Bir sensizliğin var başucumda

Elimi uzatıp tutamadığım

Sen gün batımlarında çıktığım

O yalnızlık koşularında

Nefes nefese kalışlarım

Hıçkıra hıçkıra adını sayıklayışlarım

Ve sen

Bugün kadar uzak

Yarın kadar yakın

O zaman paronayamın içerisinde

Tüm yokluğuna rağmen

Benimsin

Benimlesin', 'Sen benimlesin Bazen yalnızlığımda Bazende tüm yıkılmışlığımın Ve de ayrılıklarımın orta yerinde Hayata bağlandığım O gece yarılarında Bir s...', ARRAY['Türk Edebiyatı','Şiir','Tarık Şahin']::text[], 8.5, '{"poet":"Tarık Şahin","poet_slug":"tarik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-benimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Bu Denli Güzel Kokmaz', 'aslinda-bu-denli-guzel-kokmaz-aziz-nesin-hhnw5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslında Bu Denli Güzel Kokmaz

Aslında bu denli güzel kokmaz hiç bir karanfil,

Onda seni kokladığımdan bunca güzel.

Aslında bu denli güzel olmaz hiç bir Sarıyer,

Orda seni öptüğümden bunca güzel.

Aslında bunca güzel olmaz hiç bir dünya,

Seni sevdiğim için dünya da böyle güzel.

Aslında bu denli deli değildim sor kime istersen,

Sevince seni delilik bile bak ne güzel.

Aslında sen dünya güzeli değilsin,

Sevdiğim için dünyada tek güzelsin...

                                   

                                       Aziz Nesin', 'Aslında Bu Denli Güzel Kokmaz Aslında bu denli güzel kokmaz hiç bir karanfil, Onda seni kokladığımdan bunca güzel. Aslında bu denli güzel ol...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aslinda-bu-denli-guzel-kokmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-zulfu-livaneli-9bfoh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlerin parlayıp söndüğü yerde

Buluşmak seninle bir akşam üstü

Umarsız şarkılar,dudağımda bir yarım ezgi

Sığınmak gözlerine,sığınmak bir akşamüstü

Gözlerin bir çığlık,bir yaralı haykırış

Gözlerin bu gece çok uzaktan geçen bir gemi

Bir orman bir gece kar altındayken

Çocuksu,uçarı koşmak seninle

Elini avcumda bulup yitirmek

Sığınmak ellerine bir gece vakti

Ellerin bir martı,telaşlı ve ürkek

Ellerin fırtınada çırpınan bir beyaz yelken

Bir kenti böylece bırakıp gitmek

İçinde bin kaygı,binbir soruyla

Bitmeyen bir şarkı,dudağında bir yarım ezgi

Sığınmak şarkılara sığınmak bir ömür boyu

Gözlerin bir çığlık,bir yaralı haykırış

Gözlerin bu gece çok uzaktan geçen bir gemi

Ellerin bir martı,telaşlı ve ürkek

Ellerin fırtınada çırpınan bir beyaz yelken', 'Düşlerin parlayıp söndüğü yerde Buluşmak seninle bir akşam üstü Umarsız şarkılar,dudağımda bir yarım ezgi Sığınmak gözlerine,sığınmak bir ak...', ARRAY['Türk Edebiyatı','Şiir','Zülfü Livaneli']::text[], 8.5, '{"poet":"Zülfü Livaneli","poet_slug":"zulfu-livaneli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emremeden Sevdim', 'emremeden-sevdim-burcu-erbas-oxv85', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen sabahı olmayan gecelerde

yakalanıp özlemin sivri tırnaklı pençesine

ince ince sızan damlalarla 

uykusuz kalmayı bilmezsin güzelim

24 saat işkenceye maruz kalmayı

deniz köpüğü gibi vuran her dalgada kaybolmayı

başı sonu olmayan hasret kervanında

bitimsiz yol almayı,bilmezsin

gecenin soğuk ellerine sarılmayı

bir nefes sigaranın dağılan dumanında 

krizlere girmeyi bilemezsin

ayaklarını iskeleye uzatıp

balıklarla sohbet etmeyi

kulaklara vurulan o ayazda aşkın için 

senin sevgin için nöbet tutmayı 

ahu bir hayali seyrederken ısınmayı

tabiiki bilemezsin

çünkü sen

o uzaktan kumandalı hayatında 

hep emretmeye alışmışsın

ama sakın bende deneme

çünkü ben seni 

sen emretmeden sevdim güzelim...', 'sen sabahı olmayan gecelerde yakalanıp özlemin sivri tırnaklı pençesine ince ince sızan damlalarla  uykusuz kalmayı bilmezsin güzelim 24 saa...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/emremeden-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-burcu-erbas-0qul1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hep zorunlu bir sevgi arayışım;sen

ne bu gece benim olacaksın,ne yarın

nede sonsuza kadar beni unutmayacaksın

çünkü sen,kaybettikten sonra ağladığım

oyuncaksın....', 'hep zorunlu bir sevgi arayışım;sen ne bu gece benim olacaksın,ne yarın nede sonsuza kadar beni unutmayacaksın çünkü sen,kaybettikten sonra a...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıyorsun', 'kaciyorsun-burcu-erbas-7axxn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'akıtacağın gözyaşın mutluluk için olsun

dünya çok zor biliyorsun canım

ve sen,eski sen değilsin

ayrılmamıza sebeb belkide bu olmalı

kahretsin...

kader bu derken bile yalan söylüyorsun

verdiğim bir ömürü gözünde küçültüyorsun

en kötüsüde sen,kendi kendini kandırıyorsun

çünkü,sıradan bir alışkanlık değilsin sen

gidiyorsun....

benden kurtulmak için,kendinden kaçıyorsun

çaldığın bir valiz dolusu hatıra

birleştirilemeyen bir kalple beraber

çaresizce,apansızca,tutarsızca kaçıyorsun...', 'akıtacağın gözyaşın mutluluk için olsun dünya çok zor biliyorsun canım ve sen,eski sen değilsin ayrılmamıza sebeb belkide bu olmalı kahretsi...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaciyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-burcu-erbas-5k26n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden geldin gülüm,karanlık odama

Ansızın ayak bastın yalnızlık adama

Her geçen günün sürgün akşamlarında

Hep sana haykırışım söyle neden?

Oturmuş kumar oynarken geleceğimle ben

Seni tutmuşum kirli ellerimle

Zar misali fırlatmışım hayatın masasına

Küllenen her yazbozun burukluğu neden?

Neden gülüm şimdi ben böyleyim

Geri dönmek isteyen sensin,ben değilim

Kaybolup giderken bütün benliğim

Hep bu masum terkedilmişliğin neden?

Aşikar gözlerimle artık oynama

Ruhumu rahat bırak,gömülsün karanlığa

Susamışken gönlüm küçük bir umuda

Neden ağlıyorsun karşımda şimdi,neden?', 'Neden geldin gülüm,karanlık odama Ansızın ayak bastın yalnızlık adama Her geçen günün sürgün akşamlarında Hep sana haykırışım söyle neden? O...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizden Biri', 'i-kimizden-biri-asik-riza-dehani-1vnxb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz alışmadık günlere

Günler de bize

Sendeleyen biri var oysa...

Kim?

Yoksa 

Geçmeye mahkum günler mi?', 'Biz alışmadık günlere Günler de bize Sendeleyen biri var oysa... Kim? Yoksa  Geçmeye mahkum günler mi?...', ARRAY['Türk Edebiyatı','Şiir','Aşık Rıza Dehani']::text[], 8.5, '{"poet":"Aşık Rıza Dehani","poet_slug":"asik-riza-dehani","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ikimizden-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetme', 'zannetme-burcu-erbas-pq144', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zannetme geri dönmek amacım

Hasrete teslim oldum geri dönmeyeceğim

Sevmekse seni en büyük günahım

Öteki dünyada seni sevmeyeceğim

Kaç gemi yitirdim biliyormusun bu sahilde

Kaç limana uğradım seni bulurum diye

Kaç rüzgarda senin kokunu aradım

Boğuştum dalgalarla belki gelirsin diye

Senin uğruna girdiğim her savaşta yenildim

Zannetme düşmanlara,sadece sana

Umudum kalmadı seninle olan yarınlara

Ne başkasını seveceğim,nede geri döneceğim', 'Zannetme geri dönmek amacım Hasrete teslim oldum geri dönmeyeceğim Sevmekse seni en büyük günahım Öteki dünyada seni sevmeyeceğim Kaç gemi y...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zannetme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldattım', 'aldattim-burcu-erbas-z81e6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte fırsat...

Kus kinini, dök içini bana

İstiyorsan terket, vur kapıyı çık! 

Hayatımın en son kapısından

İşte fırsat veriyorum sana

Tam zamanı...

Çaresiz değilsin biliyorsun

Hayatta herşeyin çeresi vardır

Kaçabilirsin...

Kaçmakta bir çaredir elbet.

Sus, sakın konuşma..

Vurma ayrılığın tokatını suratıma

Gözlerini çek gözlerimden 

Onlarda senin gibi hainmiş.

Anlamamışlar onlarda beni 

Aynı senin gibi.

Sev........

Dağı, taşı, ormanı sev

İyi, kötü ne varsa sev

Sevki aklına takılmasın sözlerim

Unut her yalan gibi benide.

Yaşanan günleri, ayları

Sensiz geçen günlere tut

Aldattım...

Seni değil

Seni sevmekle kendimi

Yazık sadece yazık.........', 'İşte fırsat... Kus kinini, dök içini bana İstiyorsan terket, vur kapıyı çık!  Hayatımın en son kapısından İşte fırsat veriyorum sana Tam zam...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aldattim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Güneşim', 'yaz-gunesim-burcu-erbas-wlups', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaz güneşimsin sıcak ve uzun 

Günbatımımsın sessiz ve karanlık

Denizimsin uçsuz,bucaksız

Kaderimsin bilinmeyen bir yokuş

Sen gönlümde doğmayan yazgüneşim

Ömrüm boyunca beni düşündüren günbatımım

Girmeye korkmadığım,ürktüğüm denizim

Beni çıkmazlara sokan kaderimsin

                           kısacası herşeyimsin.....', 'Yaz güneşimsin sıcak ve uzun  Günbatımımsın sessiz ve karanlık Denizimsin uçsuz,bucaksız Kaderimsin bilinmeyen bir yokuş Sen gönlümde doğmay...', ARRAY['Türk Edebiyatı','Şiir','Burcu Erbaş']::text[], 8.5, '{"poet":"Burcu Erbaş","poet_slug":"burcu-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaz-gunesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kağıttır Yaşamak', 'bir-kagittir-yasamak-huseyin-namal-k45df', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şiirdir yaşamak,

Elleri avuçlarında bir ürperti,

Mısraları hayatının takvimi,boş sayfaları ise,

Henüz akrebin ulaşamadığı rakamlar...

Saniyesi ataların,yelkovanı  dünyayı paylaştığın insanlar,

Akrebiyse sensin bu yaşamın.

Daha turun bitmemiştir,

Henüz yetmemiştir dalındaki tohumlar,

Bilmezsin ne vakit geleceğini akşamın...

Bir kitaptır yaşamak,

Okundukça ömrü tükenen,

Yazıldıkça  sayfaları biten.

Acı bir şiir gibi ürperten...

Ve sende kahramanısındır kitabın,

Okunduktan sonra akılda kalacak,

Belki de bir sobada cayır cayır yanacak...

(09.11.2000)', 'Bir şiirdir yaşamak, Elleri avuçlarında bir ürperti, Mısraları hayatının takvimi,boş sayfaları ise, Henüz akrebin ulaşamadığı rakamlar... Sa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Namal']::text[], 8.5, '{"poet":"Hüseyin Namal","poet_slug":"huseyin-namal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kagittir-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri', 'biri-been-yilki-8cbnn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana karşı

Ne kin ve nefret,

Ne de sevgi ve istek 

duyuyorum;

Ama

Ölüm kadar gerçek

Olduğunu biliyorum..', 'Sana karşı Ne kin ve nefret, Ne de sevgi ve istek  duyuyorum; Ama Ölüm kadar gerçek Olduğunu biliyorum.....', ARRAY['Türk Edebiyatı','Şiir','Been Yilki']::text[], 8.5, '{"poet":"Been Yilki","poet_slug":"been-yilki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/biri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sevdan', 'sevdan-osman-fatih-ugplz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susuzlugunu hissettiginde dudaklarında sevdanın,                    Bitmeyecek sevdalar gömeceksin anılarına,                              Susmak icin tüm haykırıslara,                                                       Sevginden degil,sevdiginden vazgececeksin!', 'Susuzlugunu hissettiginde dudaklarında sevdanın,                    Bitmeyecek sevdalar gömeceksin anılarına,                              S...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-tugba-ozbilgin-kw1rl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yontulmuş hayatın iki sivri çıkıntısı

Farklı olduğumuz için batarız gözlere...

Sen ve ben;

Siyah-beyaz dünyanın iki renkli siması

Savaş açtık çevremizdeki bütün zevksizliklere...

Sen ve ben;

Geleceğe her zaman umutla bakan iki kişi;

Açmışız yelkenleri uçsuz bucaksız denizlere...

Sen ve ben;

Tekdüze toplumun iki özgür insanı

Kuşlar gibi yükseliyoruz mavi göklere...

                                      (18 Ocak 2000-İstanbul)', 'Yontulmuş hayatın iki sivri çıkıntısı Farklı olduğumuz için batarız gözlere... Sen ve ben; Siyah-beyaz dünyanın iki renkli siması Savaş açtı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özbilgin']::text[], 8.5, '{"poet":"Tuğba Özbilgin","poet_slug":"tugba-ozbilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-ve-ben-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derya', 'derya-tugba-ozbilgin-ahs67', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat uçsuz bucaksız bir derya

Bense yelkensiz bir gemi misali

Kaybolmuşum sonsuzluklarda 

Ne dümenim var ne de pusulam...', 'Hayat uçsuz bucaksız bir derya Bense yelkensiz bir gemi misali Kaybolmuşum sonsuzluklarda  Ne dümenim var ne de pusulam......', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özbilgin']::text[], 8.5, '{"poet":"Tuğba Özbilgin","poet_slug":"tugba-ozbilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/derya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-berkut-bahar-ahhqw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne bu sıkıntı ne bu yalnızlık böyle 

tadı tuzu senmiydin bu şehrin söyle

avutamadım kendimi hiç bir şeyle

boşlukta yaşamak gibiymiş yokluğun

uğurlamaya gelmedim veda etmeyi sevmem

gücenmişsin, kırılmışsın ben buna dayanamam

affetmezsen beni buralarda sefil olurum

savaşta esaret gibiymiş yokluğun

gözden uzak olan gönülden uzak olur derler

seni bilmem ama benim gönlüm illede sen der

kısada olsa ayrılık özledim seni yeter

toprağa gömülmek gibiymiş yokluğun', 'ne bu sıkıntı ne bu yalnızlık böyle  tadı tuzu senmiydin bu şehrin söyle avutamadım kendimi hiç bir şeyle boşlukta yaşamak gibiymiş yokluğun...', ARRAY['Türk Edebiyatı','Şiir','Berkut Bahar']::text[], 8.5, '{"poet":"Berkut Bahar","poet_slug":"berkut-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelişi-Gidişi', 'gelisi-gidisi-husrev-hatemi-pds2m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aniden,habersiz çıkagelirdin

Seçkin sevinçler içinde belirdin

Birdenbire,sessiz çıkıp giderdin

Deprem gibi derin vuran Keder''din

Hüsrev Hatemi', 'Aniden,habersiz çıkagelirdin Seçkin sevinçler içinde belirdin Birdenbire,sessiz çıkıp giderdin Deprem gibi derin vuran Keder''din Hüsrev Hate...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gelisi-gidisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Olmadıkları Kadar Benim', 'hic-olmadiklari-kadar-benim-senem-burcu-i-zci-lbn0d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok uzaklarda ararken 

Rüyaların güzellliğini

Bulutların içinde her şey silikken,

Hardal rengi yaprakların

Sonbahara karıştığı zamanda,

Günışığıyla beslenen huzuru

Karıştırdım içimdeki güvenle...

Artık uzaklar, sev dünyamda

Bana ben kadar yakın.

Kış güneşi ve yamurun kokusu da 

Hiç olmadıkları kadar benim........', 'Çok uzaklarda ararken  Rüyaların güzellliğini Bulutların içinde her şey silikken, Hardal rengi yaprakların Sonbahara karıştığı zamanda, Günı...', ARRAY['Türk Edebiyatı','Şiir','Senem Burcu İzci']::text[], 8.5, '{"poet":"Senem Burcu İzci","poet_slug":"senem-burcu-i-zci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hic-olmadiklari-kadar-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masmavi', 'masmavi-tugce-uslusoy-ofcwh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğu görüyorum, masmavi....

Upuzun yolda yürüyorum gezgin misali

Uzanıp da yakalayamadığım herşeyin bedeli;

   Nerdeyim diye düşünürken belki de ödendi..

Sonsuzluk, yalnızlık kadar yanımda sanki

Sokulmuş yüreğime, masmavi...

   Dans ettiğimi hayal ederken, beyaz güller içinde

   “Yalnızlık”, hayalimi delip kalbime girdi

   Bembeyaz, masum güller; sonsuzluğa dönüştü, masmavi...

Hangi bulutun üstündeyim bilmiyorum ki;

Yıldızlar parıldıyor belli belirsiz

Onlar da, en az yalnızlığım kadar sonsuz..

   Mevsimlerden hangisiydi hatırlayamıyorum

   Günlerden Cumartesi,

Dalgın dalgın yürüyorum yalnızlığın esiri

Kulağıma çalınmış derinden bir melodi..

Sonsuzluğa yaklaşırken, etraf yine masmavi...

   Hangi filmden çalmıştım ben bu hüznü

   Ya da bir kitapda okumuştum belki

   Kahramanlar mutsuzdu, yapayalnızdı hepsi

   Umutlar, sonsuzluk kadar uzak;

   Ümitlerim, masmavi...

Uzatıyorum elimi yine sana doğru bak;

Sonsuzluğun sırdaşı, yalnızlığımın adresi,

Her yer yine karanlık, nerede gözlerin söyle

Hangi yıldızda bulurum seni

Biliyorum senin gözlerin, sonsuzluk kadar mavi..', 'Sonsuzluğu görüyorum, masmavi.... Upuzun yolda yürüyorum gezgin misali Uzanıp da yakalayamadığım herşeyin bedeli;    Nerdeyim diye düşünürke...', ARRAY['Türk Edebiyatı','Şiir','Tuğçe Uslusoy']::text[], 8.5, '{"poet":"Tuğçe Uslusoy","poet_slug":"tugce-uslusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/masmavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimin Haritası', 'i-cimin-haritasi-unal-bulut-dnbon', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaldırın önümden bir parça dağları,

Tek pencereyle, koskoca evren yarı,

Göremediklerime emir verin gelsinler

Hürriyeti alın ellerinden birer birer,

Yanımda ölesiye gürültü, başım çatlar,

YukarIı alem aşağıyı üstüme katlar,

Sinmişliğin aciz, korkak dalları 

Sonbaharın emri her yanın sarı

Düğmelerin mantığı bir ileri bir geri,

Mantığımın emrettiği her hamle serseri,

Günler dönen bir saçmalık yumağında

Boğuldu bir sarhoş ses, dengelerin ağında

Neleri anlatmalı bir mektubun sonunda,

KağItlar bende, kalemlerim başka bir yanda

Elime içindekini sızdırmıyor kutu,

Görünüş ile oluş aynı küpe doluştu

Darbeler inince tüm kavramların başına

Merhamet var sandım kalbimin ağlayışına

Pislik dizlerinde dahi olsa hep ileri,

Anlayışın sıyrılır kin kaplar caddeleri,

Sokulunca şeytansı bir düşünce sağına,

Kesilmiş damarlardan sadeliğinle kana...

Olağan olay olmayacak, kandım,

Güz bir endamın, peşinden aldandım...', 'Kaldırın önümden bir parça dağları, Tek pencereyle, koskoca evren yarı, Göremediklerime emir verin gelsinler Hürriyeti alın ellerinden birer...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icimin-haritasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-unal-bulut-3f2bg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çölleri kulaçlıyordu yorulmuş bir akrep,

İzlere aldanıp denize ulaştı yollar,

Pusulama kavuştuğum anda kaybettim hep,

Uğramadığın dünyam sen kaçtıkça kovalar...

İki güvercin hayal penceremin önünde,

Timsahlar dalgalı sulara kanat çırpıyor,

Yaşamam gerektiğini anladığım günde,

Yoktun, yoksun, yokluğun yarına göz kırpıyor...', 'Çölleri kulaçlıyordu yorulmuş bir akrep, İzlere aldanıp denize ulaştı yollar, Pusulama kavuştuğum anda kaybettim hep, Uğramadığın dünyam sen...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanma Vakti', 'uyanma-vakti-unal-bulut-24jl6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağaçlar dikelim diyoruz, tohum kaçıyor,

Gördüğü her diyara tarihten kin saçıyor,

Uyuyup bir daha uyanmamak korkusuyla

İlaç içiyorum bir bardak zehirli suyla 

Nur kapılarına sonsuz derece yalvarış,

Can çıkıncaya kadar, bitmeyecek bu yarış,

Baksınlar, ''kahrolayım'' olacak son sözüm,

Değil uyumak, bir kere kapanırsa gözüm,

Ufuk çizgisi kapkara, ordan doğmaz güneş,

Kendinden geçmişlik ki, ölümlere olsun eş,

Kasırgalar gelirken köyümüze sessizce,

Rüyalardan çıkma vakti gelmedimi sizce...

Eskiye nazaran itibar yok ilimize,

Düşman gemileri yanaştI sahilimize,

Yanacaksa yalan, herşeyden önce yanayım,

Hakikat uyansın ve sonra ben uyanayım...', 'Ağaçlar dikelim diyoruz, tohum kaçıyor, Gördüğü her diyara tarihten kin saçıyor, Uyuyup bir daha uyanmamak korkusuyla İlaç içiyorum bir bard...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyanma-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-unal-bulut-xlpv2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kozalar kırılır, gömlekler değiştirilir,

Çatlarcasına, beyin damarları gerilir,

Casusların gözettiği nöbet alanında

Kalmaz, yok olur özgürlük vatanında

İlim şehrinde insan, yüzünde olur alim,

Hareketsiz anlayabilir, ilmi sağ salim,

Hatrıma gelmeyen günler, önüme dizilir,

Yanaklarımdaki kIrmIzılar utancımın izidir.

Meşkalem ne bilimdi, nede köklü degişim,

Madem hiçlerin resmiyim, neydi burda işim.

Destur bekler kapı önünde çekingen ölüm,

Yaklaş, ezilmiyorum ben, ezilmiyor gönlüm.', 'Kozalar kırılır, gömlekler değiştirilir, Çatlarcasına, beyin damarları gerilir, Casusların gözettiği nöbet alanında Kalmaz, yok olur özgürlü...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/degisim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekler Dans Etmez', 'melekler-dans-etmez-unal-bulut-pxp7h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz sahili reddederken boğuldu kimi,

Çalınan görüş dipte, fasıllar yer içinde	

Yankının nefreti, devrettiği gün geçti mi?

Naralara itaat, yankı kan ter içinde,

Arkamda gördüklerimin önünde kimler var,

Dünya değeriyle sorulursa sadece iki kuruş,

Devrettiklerimi  yalnız mirasım hatırlar,

Adını sayıkladıklarım çoktan unutmuş...

Eğer tatmin olacaksan kırkımda başım ez,

Baş aşağı avuntular, melekler dans etmez...', 'Deniz sahili reddederken boğuldu kimi, Çalınan görüş dipte, fasıllar yer içinde	 Yankının nefreti, devrettiği gün geçti mi? Naralara itaat, ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/melekler-dans-etmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pırlanta Bahçesi', 'pirlanta-bahcesi-unal-bulut-4l3y8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çekmecenin yaşam alanı gibi dar

Bir dağ kadar sabit halimi anlatmaya kâfi mi

Kalemler altında çırpınan bir kaç satır

Kağıtlar beyaz olmayı ısrarla reddederken

Mavilikler gökyüzüne yeni elbiseler

Hüsranlar bana yine çıplaklık vaadediyordu

Gözleri alev sarısı korkak ceylan 

Ayakları dipten kırılası cesur aslan

Gülun bağrına çaresizlik atmış gülistan

Bunlar haldir,hepsi yalnız dertsizliğe derman

Issız küllenmiş, itaatkâr ormanlarda

Sararmış mazi yapraklarını toplarken

Yarının kesilmiş ağaçlarından kaçıyordum

Kalamıyorum seni misafir etmeyen

Mahkumlara yedek esaret veren

Kervanları uçsuz bucaksız çöllere seren

Deniz dibindeki ateş mekanlarda

Dört yanı dikenli ihanetlerle çevrili

Bugünün iki sayfalık huzursuzluk romanı 

Yalnız girişten ve sondan ibaretti

Yavaş bir müziğe hızlı ritim çabasının

Sonuçsuz kalmasının tek nedeni

Telsiz sazlar ve dilsiz şarkıcılardı

Talihsiz, uğursuz rehavete uzanmış

Miskinlik çekiyorum üzerime

Hesapsız hüsran nameleri söylüyorüm

Bedenim ölmüşken dahi seni özlüyorum...', 'Bir çekmecenin yaşam alanı gibi dar Bir dağ kadar sabit halimi anlatmaya kâfi mi Kalemler altında çırpınan bir kaç satır Kağıtlar beyaz olma...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/pirlanta-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rezil Geceler', 'rezil-geceler-unal-bulut-l9dzs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarhoşluk kol gezer akılda

Ya alemin kralısın yada 

Okyanus ortasında ada

Rezil geceler bittiğinde...

Ayakların emrinde beyin

Sabah olana kadar tepin

Sorana çok eğlendik deyin

Rezil geceler bittiğinde...

Dönme dolap oda duvarı

Her lezzet, acı, sokan arı

Çağdaşlık kadehleri yarı

Rezil geceler bittiğinde...

Magaradaymışım kime ne

Şaşırmam üstüme gelmene

Ar biter, ayaklanır ene

Rezil geceler bittiğinde...

Şakaklara çakılır çivi

Saray olmuş pisliğin evi

Çöplükten çıkılır bir nevi

Rezil geceler bittiğinde...

Güneş yeni yeni uyanır

Ay gece çoktan bitti sanır

İnsanlık yaşamdan usanır

Rezil geceler bittiğinde', 'Sarhoşluk kol gezer akılda Ya alemin kralısın yada  Okyanus ortasında ada Rezil geceler bittiğinde... Ayakların emrinde beyin Sabah olana ka...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/rezil-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-unal-bulut-s0qiw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eşiğindeyim kısa bir tatilin

Sevinçler kurtaran, zaman katilin

Günler geçmesin isterdim eskiden

Bir şeyler koparıyordu her giden

Değişti galiba akış yönü

Bizi uyandırdı denizin önü

Yüzümüzde taze bir ferahlık var

Oda tüm kucaklamaları kovar

Elveda arefesinde merhaba

Göz yaşları sığacak mı bir kaba?

Takvime fazla günler ekliyorum

Bitmeyecek tatili bekliyorum

Davet gelirse gideceğim elbet

En kötüsü o güne kadar sabret

Karşımda göz kamaştıran eda

Tatilde görüşmek üzere elveda', 'Eşiğindeyim kısa bir tatilin Sevinçler kurtaran, zaman katilin Günler geçmesin isterdim eskiden Bir şeyler koparıyordu her giden Değişti gal...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elveda-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Karşımda', 'durma-karsimda-zubeyde-basaran-fd04o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çek  git   durma  karşımda

Yerden  yele  salan   ahım  tutacak 

Şimdilerde  parmak  uçlarınla   gittiğin yollarını

Bundan  sonra   dizlerin  gezecek

Git  artık  kaf  dağı  edip sardığım kalbime

Gitki   buz  süreyim

İntizarı  meyletme  bana

Çekil, gölgende  yok olsun  seninle

Çık  artık  sensiz yaşamak istiyorum hayatı

Nefesinin  bulunduğu  yer kalmasın

Nasıl  eyledin  benden  beni

Yakıştıramam  kendime  yalvarmayı

Git  ki   hayatın  yeni gül  destanını yazayım

Git ki  küllenmiş  umutlarıma  sedef  katayım

Gitki lanet etmeden 

Kendi içimde

yok  olayım....', 'Çek  git   durma  karşımda Yerden  yele  salan   ahım  tutacak  Şimdilerde  parmak  uçlarınla   gittiğin yollarını Bundan  sonra   dizlerin ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/durma-karsimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgardın', 'ruzgardin-zubeyde-basaran-tp1pc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asılda  esen  deli  rüzgar

Ben  senin savurduğun  tek kumum

Yerlere atıp,  ezip  geçtiğin

Vahşetini tek bende  deneyip

birtek bana hükmettiğin

Çöl  kumunum

Hani  saatlerin saniye olduğu

Bensiz  bulunan yerlerin  renksiz olduğu

Bütün  güzelliklerin bende

Benim  gözlerimde yok olduğu

Susuz  bahtlar gibi

Sonsuz olan  sevdanın tek kırıntısıyım

Ben  senin savurduğun

Bir tek çöl  kumuyum...

Ben senin  savurduğunum!', 'Asılda  esen  deli  rüzgar Ben  senin savurduğun  tek kumum Yerlere atıp,  ezip  geçtiğin Vahşetini tek bende  deneyip birtek bana hükmettiğ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzgardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-sukru-hazanli-40p7u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hazan yokluğunda geldi güzelim,

Baharı özlemek zamanı şimdi.

Ayrılığa sebep eldi güzelim,

Sineye çekmenin zamanı şimdi.

Kader örer iken hicran ağını,

Sensizliğe bağlar her bir bağını.

Söğüdün kuruyan ilk yaprağını

Rüzgara salmanın zamanı şimdi.

Bir gece yarısı uykusuz kalıp,

Semada eşinin seyrine dalıp,

Sensizlik türküsün kendimce çalıp,

Gözyaşı dökmenin zamanı şimdi.

Her şeye, kayıtsız kalıp her şeye,

Sormak; sen kimsin? Diye neşeye

Adını verdiğim mor menekşeye

Mahzunca bakmanın zamanı şimdi.

Sahilde kimsesiz ayak sürürken,

Her dalgaya adın yazmak isterken,

Hayalde alnını şevkle öperken,

Gerçeğe sitemin zamanı şimdi.

Boşalırken gökler deniz dolusu,

Beklerim durulsun, diyerek bu su,

Seninkine benzer toprak kokusu

İçime çekmenin zamanı şimdi.

Vuslata yorduğum aşk masalını,

Hasretten dinlemek zamanı şimdi.

Zülfünde kaybolan aşkın aslını

Yokluğunda bulmak zamanı şimdi.

                                   2 Ekim 1996', 'Hazan yokluğunda geldi güzelim, Baharı özlemek zamanı şimdi. Ayrılığa sebep eldi güzelim, Sineye çekmenin zamanı şimdi. Kader örer iken hicr...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/simdi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-sukru-hazanli-fili8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Masamda resmindir ilham sözüme

Ve aşkın bir kandil gibi her akşam

Yanarken nurlara gark olur odam

Uykuysa uğramaz artık gözüme

Dalar uzaklara unutur beni,

Buğulu gözlerin gibi gözlerim.

Ve bir zaman sonra üşür ellerim

Sıcak hatırana bir sitem gibi.

26 Ocak 1997', 'Masamda resmindir ilham sözüme Ve aşkın bir kandil gibi her akşam Yanarken nurlara gark olur odam Uykuysa uğramaz artık gözüme Dalar uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Otağı', 'askin-otagi-sukru-hazanli-mwshd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözümde çağlayan vuslat

gönlüme dert olan vuslat

gamlı bülbül öte durur

alnımdan dökülen vuslat

şairin çilesi bir ah içredir

selam dudağına kazınır sevdanın

vefa boynuna..

içlerine türkü konmuş gönüller

seslerini mırıldanır gecenin kuytusunda

ve bir nida yükselir tan tutarken semayı

sesin gözlerinde nem

nem bir ah-u zardır gözde

bir yakarış,

bir bekleyiş,

bir arzu,

bir dava aşıkın yamaçlarında

kimdedir sesine kazınan bu aşk

kimdedir bu asalet tacı

sen, saçlarının kıvrımında kaybolunan sevgili

sen, ruhunda güller kokan

sen, aşkın otağı....', 'gözümde çağlayan vuslat gönlüme dert olan vuslat gamlı bülbül öte durur alnımdan dökülen vuslat şairin çilesi bir ah içredir selam dudağına ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askin-otagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamaklı Bir Güzel', 'aglamakli-bir-guzel-sukru-hazanli-jocxv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk bakışta içimin karanlığına doğdu,

Beni güzelliğinin ışıltısına boğdu.

Bakışında sıcaklık baharın ilk cemresi,

Öyle bir endam var ki; beyaz nurdan çehresi

Beni yakan bir alev veya bir güneş gibi,

Kıvılcımlandı birden kalbimde ateş gibi.

Boydan boya upuzun ve ipince bir endam

Gözbebeğinde şefkat, sanki o yaşlı anam

Yanağında gamzesi ilk sevgiliye benzer

Göz ucundaki kapris, nazından daha beter

Andırır solgun yüzü, rüzgarda uçan tülü

Dudağında bir mana, süzgün ve üzüntülü

Yosun gibi yemyeşil o çekik gözlerinden

Bir his kopmuş görünür matemi çok derinden

Mahzun mahzun dalmışken vapur güvertesinde

Hüznünü birden bölen martıların sesinde

Onun matemi vardı ondan daha derince

Doldu yeşil özleri anlayınca yaş ile

Seyrine doyamadım ağlamaklı güzelin,

Dayanmak mümkün mü ki, titreyen iki elin

Hüzünlü bir zarafet dolu inceliğine

Ağladım onun sessiz, hazin güzelliğine

					Mayıs 1993', 'İlk bakışta içimin karanlığına doğdu, Beni güzelliğinin ışıltısına boğdu. Bakışında sıcaklık baharın ilk cemresi, Öyle bir endam var ki; bey...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aglamakli-bir-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber', 'haber-sukru-hazanli-hu26d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana bir haber gönderiver uzaktan,

Bana bir haber

Yüreğimdeki aşktan

Dudağıma çizilmiş

Vişne dudaklarınla

İki kelime söyle gelecek güne dair

Gelecek güzel günde

Umduğum aşka dair

Uçuşan tüm kuşların

Kanatlarından,

Çalınan tüm sazların

Mızraplarında,

Sensizlik günlerimi kıskandıracak

Günlerin seninle olanlarından

Ve kadın gözlerinin an güzelinden

Aşkıma dair bir haber gönder.

			Aralık 1998', 'Bana bir haber gönderiver uzaktan, Bana bir haber Yüreğimdeki aşktan Dudağıma çizilmiş Vişne dudaklarınla İki kelime söyle gelecek güne dair...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haber-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Der Kim Düşler', 'kim-der-kim-dusler-sukru-hazanli-hjuxp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretiyle pare pare yandığım şehir

Gözlerimde tüten gece

Binlerce günün hatırası

Binlerce yıl gibi

Güz gibi, bahar gibi

Kış gibi ve yaz gibi her dem

Ve her demde bir tebessüm gül yanağında

Milyonların sevdasına bir çare gibi

Merhem gibi yareme sürdüğüm

Elin gibi ve parmakların...

Bir dudak gibi al ve mor akan

Bir dudak ki; ağlasam mı, gülsem mi diyen

Bir zaman gibi

Bir sevda gibi

Şarkılar dinlerdik hasrete dair

Şiirler yazmıştık vuslata dair

Yaşıyorduk ya aşkı şarkılar gibi

Başka nasıl yaşanırdı ki aşk

Bin özlem yüreğimizde

Şiirler gibi

Bir bahardı son baharda

Bir bahar ki kış gibi

Alnıma çizgiler çeken

Ağır bir poyrazdı

Gülümseyerek bağrımı açtığım aşkın rüzgarı

Ne değişkendi alem

Ne oyunlar oynardı felek bize

Ne çok ağlardı yosmalar izbelerde

Ne çok gülerlerdi masa başında

Kim de, kim düşler, kim sanırdı ki

Elinde kalem, kağıtlara boğulan

Masasında ben

Hangi ağaç altında serinlemişti bahar

Hangi rüzgarla ben.

Hangi pınardı kana kana içtiğim

Hangisiydi söylesene

Hasretini çektiğim.

Kimin gözleriydi gördüğüm bir hazan günü

Senin sözlerindi öldüğüm.

Neye inanmıştık, hatırlar mısın?

Neler isterdi coşkun kanımız?

Ömre sığmazdı davalarım

Sevdalarımızdı ölümler gibi

Gül yüzündü bir mayıs günü

Şahin pençesinde yırtılan

Ve kanayan yarandı

Elimi yasladığım

Elinse

Gözyaşıyla kalbimde sakladığım.

Bir bahar günüydü dağlara duran

Bir bahar düğünü kasavet kovan

Gel gör ki yüz binlerin sancısıydı

İki küçük yüreği yakan

İki küçük yürekti her hazana ağlayan

Ya bir kuş gibi havalanan yüreğin

Ya yeşilliğinde masmavi boğazın

Ya derdimi sakladığım

Ve derdini anlattığın

Bir kuytu masaydı oturduğumuz.

Hangi sevdaydı hatırlasana

Semaya haykırdığımız.

Kim de, kim düşler, kim sanırdı ki

Elinde kalem, kağıtlara boğulan

Masasında ben

Hangi ağaç altında serinlemişti bahar

Hangi rüzgarla ben.

Hangi pınardı kana kana içtiğim

Hangisiydi söylesene

Hasretini çektiğim.

Hani zaman olurdu

Hani biterdi her şey

Hani savrulurdu küllerimiz

Binlerce nefes ile havaya

Hani aşk sönerdi

Tuluat giderdi bizden

Hani:

Zamandı gelip geçmek bilmeyen

Mekandı ölümleri özleten

Hani sen yok olmuştun, bense sönmüştüm

Oysa ne sen yok oldun, ne de ben söndüm

Aşkın narı hala sönmedi

Tuluatsa işte, şimdi burada.

			Temmuz 1998', 'Hasretiyle pare pare yandığım şehir Gözlerimde tüten gece Binlerce günün hatırası Binlerce yıl gibi Güz gibi, bahar gibi Kış gibi ve yaz gib...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/kim-der-kim-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sema', 'sema-sukru-hazanli-e8daf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni ban anlatan sanki bir sırlı ayna

Karanlıklar içinde pırıltılar beldesi

El ayak çekik ama anlatır anlayana

Dinleyene duyana siyah sükunun sesi

			20 Ekim 1996', 'Beni ban anlatan sanki bir sırlı ayna Karanlıklar içinde pırıltılar beldesi El ayak çekik ama anlatır anlayana Dinleyene duyana siyah sükunu...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sema-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mah Ruyan', 'mah-ruyan-sukru-hazanli-pbabe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arayıp durdum seni olmadık izbelerde

Gamla geçti günlerim yoktu neşeli anım

Ve işte hiç bir zaman ummadığım bir yerde

Kavuşuverdim sana Sultan-ı Mah-ruyan’ım

                                          19 Temmuz 1996', 'Arayıp durdum seni olmadık izbelerde Gamla geçti günlerim yoktu neşeli anım Ve işte hiç bir zaman ummadığım bir yerde Kavuşuverdim sana Sult...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mah-ruyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-sukru-hazanli-jpojm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her güzel görünen bir heves gibi,

Kalbime girip de şöyle bir gezer.

Hasta dudağında son nefes gibi,

Tıkanır içimde göğsümü ezer.

                                     Mart 1994', 'Her güzel görünen bir heves gibi, Kalbime girip de şöyle bir gezer. Hasta dudağında son nefes gibi, Tıkanır içimde göğsümü ezer.            ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Hazanlı']::text[], 8.5, '{"poet":"Şükrü Hazanlı","poet_slug":"sukru-hazanli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guzel-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliler Gibi', 'deliler-gibi-yusuf-sen-fvksj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen hep yanımdaymışsın gibi

Seslensem duyacakmışsın gibi

Uzanıp ellerimi tutacakmişsın gibi

Seni yaşıyorum deliler gibi

Bir parçam oldun bedenimde

Vazgeçilmezimsin benliğimde

İnan hep sen varsın düşlerimde

Seni düşünüyorum deliler gibi

Aramızda sıra dağlar olabilir 

Tüm çareler tükenebilir

Sevgi herşeyin üstesinden gelir 

Sana geliyorum deliler gibi

Benden uzakta olsanda, gönlüm senin olsun

Yanımda olmasanda sevgim sana avuntu olsun

Uzaklarda olsakta gönüllerimiz bir biliyorsun

seni seviyorum deliler gibi.', 'Sen hep yanımdaymışsın gibi Seslensem duyacakmışsın gibi Uzanıp ellerimi tutacakmişsın gibi Seni yaşıyorum deliler gibi Bir parçam oldun bed...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Şen']::text[], 8.5, '{"poet":"Yusuf Şen","poet_slug":"yusuf-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deliler-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benmiyim Sevmeyen', 'benmiyim-sevmeyen-kenan-saracoglu-dkfxa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni dinlemiyor artık kalbim

Tamam dur diyorum

O inadına çarpıyor aşık aşık

Unut diyorum beynime 

O hatırlıyor hasret hasret

Görme diyorum gözlerime

Onlar görüyor ışıl ışıl

Sus diyorum konusma dilime

O anlatıyor sessiz sessiz

Dinle diyorum kulaklarıma

Onlar duymuyor çığlık çığlık

Durun gitmeyin diyorum ayaklarıma

Onlar koşuyor adım adım

Bakıyorum da benı dınleyen ben varmı diye

Dudaklarım öpmüyor

Ya dudaklarım senı sevmiyor

Ya benı dınlıyor

Bir de ellerim', 'Beni dinlemiyor artık kalbim Tamam dur diyorum O inadına çarpıyor aşık aşık Unut diyorum beynime  O hatırlıyor hasret hasret Görme diyorum g...', ARRAY['Türk Edebiyatı','Şiir','Kenan Saraçoğlu']::text[], 8.5, '{"poet":"Kenan Saraçoğlu","poet_slug":"kenan-saracoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benmiyim-sevmeyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğün Geldiği Gün', 'ozgurlugun-geldigi-gun-mutlu-sahin-8251j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O büyük gün geldiğinde

Yani sevgilim 

Özgürlüğün geldiği gün

Ölmek yasak bize

Yani sevgilim

Özgürlüğün geldiği gün

Ormanlar halaya duracak

Dağlarımızda sarı kırmızı yeşil

Newroz çiçekleri yeşerecek

Kentin varoşlarında

Kardelen çiçekleri açacak

Yani sevgilim

Özgürlüğün geldiği gün

En güzel aşk şarkılarını

En güzel sevda türkülerini

En güzel devrim marşlarını

Birlikte söyleyeceğiz meydanlarda

Yani sevgilim 

Özgürlüğün geldiği gün

Ölmek yasak bize', 'O büyük gün geldiğinde Yani sevgilim  Özgürlüğün geldiği gün Ölmek yasak bize Yani sevgilim Özgürlüğün geldiği gün Ormanlar halaya duracak D...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Şahin']::text[], 8.5, '{"poet":"Mutlu Şahin","poet_slug":"mutlu-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozgurlugun-geldigi-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitki Olacaksam', 'bitki-olacaksam-aziz-nesin-gcyrj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitki Olacaksam

Bitki Olacaksam

Çayır çimen olayım

Aman baldıran değil

Yol altında kalacaksam

Gelin arabaları geçsin üstümden

Çelik paletler değil

Üstümde çocuklar koşuşsun

Ne kaçan ne kovalayan

Askerler değil

Kerpiç yapacaksanız beni

Okullarda kullanın

Ceza evlerinde değil

Soluğum tükenmez de kalırsa

Islık öttürsünler

Aman ha düdük değil

Kalem yapın beni kalem

Şiirler yazın sevgi üstüne

Ölüm kararı değil

Ölünce yaşamalıyım defne yapraklarında

Sakın ola ki

Silahlarda değil.

                            Aziz Nesin', 'Bitki Olacaksam Bitki Olacaksam Çayır çimen olayım Aman baldıran değil Yol altında kalacaksam Gelin arabaları geçsin üstümden Çelik paletler...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bitki-olacaksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkıntı Ve Çöküntüyü Yaşamak', 'yikinti-ve-cokuntuyu-yasamak-husrev-hatemi-8ipfl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başta,sevinç getirir kısa süre

Ortada ve sonda yıkıntıyı yaşamanın

Adı,Aşk''tır

Hatta geriye sarıp da kaseti,

Bir ömür dolduran coşku ve haseti

Ve yaman bir çöküntüyü yaşamanın

Adı,Aşktır', 'Başta,sevinç getirir kısa süre Ortada ve sonda yıkıntıyı yaşamanın Adı,Aşk''tır Hatta geriye sarıp da kaseti, Bir ömür dolduran coşku ve hase...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yikinti-ve-cokuntuyu-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oaristys', 'oaristys-orhan-veli-kanik-66026', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey hatırası içimde yemin kadar büyük,

Ey bahçesinin hoş günlere açık kapısı

Hala rüyalarıma giren ilk göz ağrısı,

Çocuk alınlarda duyulan sıcak öpücük.

Ey sevgi dalımda ilk çiçek açan tomurcuk,

Kanımın akışını yenileştiren damar,

Gül rengi ışıkları sevda dolu akşamlar

İçime yeni bir fecir gibi dolan çocuk.

Ey tahta perdenin üzerinden aşan hatmi

Ve havaları seslerimizle dolu bahar,

Koşuştuğumuz yollar, oynadığımız sular,

Kağıttan teknesinde sevinç taşıyan gemi.

Duyup karşı minarede okunan yatsıyı

Yatağıma sıcaklığını getiren rüya,

Denizlerinde onunla yaşadığım dünya

Ve ey ufku beyaz cennetlere giden kıyı.

Ah! Birçok şeyler hatırlatan erik ağacı

Ve o ilk yolculukla başlayan hasret, zindan; 

Atları çıngıraklı arabanın ardından

Beyaz, keten mendilimde sallanan ilk acı.

(Ankara, Haziran 1936 / Varlık Dergisi)', 'Ey hatırası içimde yemin kadar büyük, Ey bahçesinin hoş günlere açık kapısı Hala rüyalarıma giren ilk göz ağrısı, Çocuk alınlarda duyulan sı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oaristys-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balog''at', 'balog-at-arif-turan-ozbek-f6njy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yilnomadan yirtilgan sonsiz varaqlar,

Ko’zlarim o’rganmay bahorga hali

Qaytalagan kuzlar

Va yaproqlari

Tinimsiz uzilayotgan daraxtlar,

Vujudimni chaynayotgan soat millari

Ko’z oldimdan o’tayotgan bolaligimning 

Shaffof yillari…

Bir belgidir bularning bari

Bir belgidir-

Men ulg’ayyapman.

Ko’cha to’lib oqayotgan

Zabardast

Shashti past

Yuzlari tiniq

Qalb o’ti so’niq

To’g’riyu egri

Dimog’i shishgan

Va ochlikdan holsiz tirishgan

Biri umidvor

Boshqasi abgor

Odamlarning safiga qo’shilayapman.

Bolalik hotiralarimni sekin

Unutayapman.

Ona, senga omonatdir ular

Bir sen unutma.

Mendan esa sadoqat kutma

Chunki bolang ulg’ayyapti.

Mening ilk bor 

Sharob ichganda burishgan yuzim

Endi burishmas dunyoning kir ishlaridan,

Tamaki tutatganimda ilk bora humor

Achchig’idan qisilgan ko’zim

Endi asabiy qisilmas shaytonning 

Qilmishlaridan.

Polapon ortidan quvlab yetolmay 

Tirishgan peshonam

Endi osongina tirishmas

Va alam ham qilmas endi yiqilsam.

Doim charog’on betasvish ko’nglim

Endi osongina yorishmas...

Onam,

O’sha burishgan yuzimni

O’sha qisilgan ko’zimni

Osha tirishgan peshonam

Va charog’on ko’nglimni

Omonat qoldirdim senga,

Ularni bir sen unutma

Mendan esa sadoqat kutma.

O’g’irlikka tushganimda qo’shni bog’iga

Titragan qo’lim

Ilk bor yolg’on so’zlarkan

Muzlagan tilim

Sinfdosh bir qizni ranjitib avval

Keyin esa og’rigan dilim…

Bolalikdan hotiradir bularning bari.

Omonat topshirib senga ularni

Ona, tirmashib boryapman

Ulg’ayish sari.

Ko’cha to’lib oqayotgan

Shon-shuhrat ortigdan quvgan,

Bir parcha non dardi bag’rin qovurgan

Birining ko’zi birining qorni och

Biri bashang biri yalong’och

Biri uyg’oq boshqasi mudroq

Kimidir mahzun kimidir quvnoq

Odamlarning galasini ko’rayapman,

Ona, men endi sen bilgan polapon bolangmas,

Go’daklik hotiralarimni senga omonat tashlab

Katta odamlarning safiga

Qo’shilayapman,

Ularni bir sen unutma

Mendan esa sadoqat kutma,

Men 

Ulg’ayyapman…', 'Yilnomadan yirtilgan sonsiz varaqlar, Ko’zlarim o’rganmay bahorga hali Qaytalagan kuzlar Va yaproqlari Tinimsiz uzilayotgan daraxtlar, Vujud...', ARRAY['Türk Edebiyatı','Şiir','Arif Turan Özbek']::text[], 8.5, '{"poet":"Arif Turan Özbek","poet_slug":"arif-turan-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/balog-at-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrin Işıkları', 'sehrin-isiklari-mehmet-cakir-2-rhw52', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne çevirerek gözlerimi

Ay ışığıyla kapattım aşk yaramı

Rüzgara karşı tutarak ellerimi

Şehrin ışıklarıyla yaktım son sigaramı

Zehri çekerken içime, derince

Aşkın ayrıldı bedenimden önce

Ve artık ismini, çektiğim her nefeste

Şehrin ışıklarına haykırdım sessizce

Hatırladım, sigarami boşluğa bırakırken

Bir sene önce, bir soğuk gecede

Asla bitmez dediğinde açılmıştı yaram

Şimdi hayat denen yıldızım kayarken

Şehrin ışıklarıyla beraber söndü sigaram', 'Gökyüzüne çevirerek gözlerimi Ay ışığıyla kapattım aşk yaramı Rüzgara karşı tutarak ellerimi Şehrin ışıklarıyla yaktım son sigaramı Zehri çe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çakır 2']::text[], 8.5, '{"poet":"Mehmet Çakır 2","poet_slug":"mehmet-cakir-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehrin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nedir?', 'ask-nedir-ozden-i-nce-9a9ze', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ask nedir biliyormusun?

Ask bir yaprak gibi 

Sararıp dökülen,

Bir anı gibidir..

Sevgi nedir biliyormusun?

Bir ağaç gibi kökünden

Sökülüp , yeniden yetişemiyen

Ve gerçekleşmeyen bir düş gibidir..

Sevda nedir biliyormusun?

Kırılan dallar gibi

bir daha bir araya gelemeyen

Ayrılıkların en acısıdır...', 'Ask nedir biliyormusun? Ask bir yaprak gibi  Sararıp dökülen, Bir anı gibidir.. Sevgi nedir biliyormusun? Bir ağaç gibi kökünden Sökülüp , y...', ARRAY['Türk Edebiyatı','Şiir','Özden İnce']::text[], 8.5, '{"poet":"Özden İnce","poet_slug":"ozden-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-nedir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyle Bir Dünyada Yokum', 'ben-boyle-bir-dunyada-yokum-ozden-i-nce-mwx2f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aç bırakacaksanız çocukları,

Vuruyorsanız suçsuz insanları,

Cana kıymak o kadar kolaysa,

Ben böyle bir dünyada yokum.

Heyyy fani dünya , ölümlüysen,

Her gelen giden kula zalimse,

Gençliği kara toprakta çürütüyorsan,

Ben böyle bir dünyada yokum.

Saygıyı yerden yere vuracaksa,

Sevgimi kalbimden söküp atacaksa,

Sevdayı parayla satın alacaksa,

Ben böyle bir dünyada yokum.

İyilik kula herşeyi kaybettiriyorsa,

Eşe dosta dürüstlük yaramıyorsa,

Dört duvar arasında gençlik yıpranıyorsa,

Zengin fakiri dünyada hor gürüyorsa,

Ben böyle bir dünyada yokum...', 'Aç bırakacaksanız çocukları, Vuruyorsanız suçsuz insanları, Cana kıymak o kadar kolaysa, Ben böyle bir dünyada yokum. Heyyy fani dünya , ölü...', ARRAY['Türk Edebiyatı','Şiir','Özden İnce']::text[], 8.5, '{"poet":"Özden İnce","poet_slug":"ozden-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-boyle-bir-dunyada-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-baris-ozkaya-cx8hz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ovaya gömüp hatıraları 

ilk dağı örtünce üstüne 

huzur bulur kaçışın. 

Şeker serper kuşların büyüsüne 

İstanbul semalarında uçuşun 

görene dek Boğaz''ın dibinde 

hortlayıp yara deşen yıldızları... 

Gider mi? 

yüklesen gemilere geceden 

keyif bozan hatıraları', 'Ovaya gömüp hatıraları  ilk dağı örtünce üstüne  huzur bulur kaçışın.  Şeker serper kuşların büyüsüne  İstanbul semalarında uçuşun  görene d...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kacis-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmeden Önce', 'esmeden-once-baris-ozkaya-wjr97', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgar,rüzgar olmadan önce 

esmez bekler kayaların ucunda 

ah! o kayalar yok mu? 

sırtında suskunluğun acısını hissettiği... 

ve denizi seyreder kayalardan 

denizse o zamanlar suskun 

rüzgar esmeden önce 

Tanışırken denizle rüzgar 

görecektin kayaların halini 

aşkı ilanıyla rüzgarın 

kum olup savruldular. 

ve birgün, hissedersin 

o aşkın dalgaları 

kaylardan sekip ıslatıyor ellerini 

rüzgar olup esmeden önce', 'Rüzgar,rüzgar olmadan önce  esmez bekler kayaların ucunda  ah! o kayalar yok mu?  sırtında suskunluğun acısını hissettiği...  ve denizi seyr...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/esmeden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Seviyorsun Ya Kardeşim', 'sen-seviyorsun-ya-kardesim-baris-ozkaya-5j8dc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seviyor 

                sevmiyor 

          seviyor 

                    sevmiyor 

              seviyor 

                        sevmiyor 

''haklısın sormakta bana 

              biliyorum kardeşim 

geçende oturmuştu yanıma 

kimi sevdiğini 

           çıtlatmıştı kulağıma 

       sen misin? 

                değil misin? 

                      bilirim 

ama boşver koparma yapraklarımı 

ben belki yalan söylerim''

      seviyor 

                sevmiyor 

          seviyor 

                    sevmiyor 

              seviyor 

                        sevmiyor 

''tamam! 

    koparma yapraklarımı 

                 söylüyorum işte: 

al götür de beni sevdiğine 

bir daha gelip 

papatyaları ziyan etmesin''

''ama bana güvenme 

ben belki yalan söylerim'' 

      seviyor 

                sevmiyor 

          seviyor 

                    sevmiyor 

              seviyor 

                        sevmiyor 

''yeter kopardığın yapraklar 

al götür beni sevdiğine 

             ben de ziyan olmadan. 

ne de olsa ona 

        bir papatya 

             vermeyecek misin?'' 

      seviyor 

                sevmiyor 

          seviyor 

                    sevmiyor 

              seviyor 

                        sevmiyor 

''yeter kopardığın yapraklarımı 

ben belki yalan söylerim 

                böyle acı çekerken 

          sen de benle beraber 

   acı çekiyorsun kardeşim 

                  yalnızca acı!'' 

      seviyooor 

                 sevmiyooor 

      seviyoooor 

                  ......... 

     kahretsin sevmiyor! 

''emin misin? 

belki yalan söyledim!''

      seviyor 

                sevmiyor 

          seviyor 

                    sevmiyor 

              seviyor 

                        sevmiyor 

''yeter kopardığın çiçekleri 

      ha seviyor 

                ha sevmiyor 

al götür beni sevdiğine 

sen seviyorsun ya kardeşim!''', 'seviyor                  sevmiyor            seviyor                      sevmiyor                seviyor                          sevmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/sen-seviyorsun-ya-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümceğin Düşüşü', 'orumcegin-dususu-baris-ozkaya-h2pn3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tavandan aşağı

Nasıl çıktın yola

Güvenip o incecik ağa

Gördün mü?

Yolun yarısında

Düşüverdin masaya

Bre, örümcek!', 'Tavandan aşağı Nasıl çıktın yola Güvenip o incecik ağa Gördün mü? Yolun yarısında Düşüverdin masaya Bre, örümcek!...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/orumcegin-dususu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-bilal-degirmendereli-kbc8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uyanmak istemiyorum ''öyle birdenbireki''''nin hayalinden

niye düşünmek istediğimi istemiyorum düşünmek

göz kapağımla görülen siyah odacıkların bulanıklığını sorguluyorum

kusmak, atmak düşünmenin sıkıntılarını, tek şey başaramadığım

vuslatımız düşünmeyi düşenebildiğin zaman

düşünmeksizin bekliyorum düşünmeyi başarmanı

tükenerek,eriyerek, bıkarak bekliyorum vuslatı

bile bile düş kırıklığına hoşgeldin dedirteceğini,

bekliyorum seni ve senli sensizliği', 'uyanmak istemiyorum ''öyle birdenbireki''''nin hayalinden niye düşünmek istediğimi istemiyorum düşünmek göz kapağımla görülen siyah odacıkların...', ARRAY['Türk Edebiyatı','Şiir','Bilal Değirmendereli']::text[], 8.5, '{"poet":"Bilal Değirmendereli","poet_slug":"bilal-degirmendereli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vuslat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kol Kola Gençler', 'kol-kola-gencler-mustafa-yildizdogan-e55wd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu memleket bahçe sizlerse çiçek

Sevgiyle hayaller gerçekleşecek

Eğriler yanlışlar hep düzelecek

Olursa kol kola kol kola gençler.

Tertemiz duyguyla tek niyet ile

Ayrım gayrım olmaz adalet ile

Bir savaş başlar ki cehalet ile

Olursa kol kola kol kola gençler.

İlimde irfanda kol kola gençler

Akılda mantıkta kol kola gençler

Gayrette,çabada kol kola gençler

Bu memleket için kol kola gençler...', 'Bu memleket bahçe sizlerse çiçek Sevgiyle hayaller gerçekleşecek Eğriler yanlışlar hep düzelecek Olursa kol kola kol kola gençler. Tertemiz ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kol-kola-gencler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün', 'gun-ramazan-erdogan-bn1k9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'günü yaşamak kadar,

dünü düşünmek;

yarını düşlemekte önemli galiba...

ama hergünü bir önceki günden ayıran,

gelecek günlere umutla bakmayı sağlayan,

büyük aşklar yaşamalı insan...

bakıyorumda kendime,

kimilerine göre acınacak halime;

hangi günüm yaşanır,

hangi dünü yaşadım,

yada hangi gün yarınlarımın umudu oldu?

umut dedimde gülüm!

inan umutsuz geçiyor hergünüm...

seni görmediğim dünler,

sesini duymadığım bugünler,

benim olmayacağın yarınlar...

ve inan,hergün acımasızca

bir okadar yüksek sesle haykırıyorlar ismini bana...

söyle!!!

hangi günüm senle doğmadı?

yada...yaad boşver!

beni anladınmı yada anlayacakmısın bilemem?

ama anladığın gün!

ne dün,ne bugün,nede yarın 

umrumda bile olmaz inan!

sadece sen bir tek sen!

bir tek sana atar bu yürek!

her solukta alev alev yanar,

her hayal,her rüyada ismini sayıklarım...

ama dedim ya,boşver!

kandıramam kendimi

kandırma sende kendini,

sorarım ben aşkı,aşka:

hangi gün???', 'günü yaşamak kadar, dünü düşünmek; yarını düşlemekte önemli galiba... ama hergünü bir önceki günden ayıran, gelecek günlere umutla bakmayı s...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenemedik', 'ogrenemedik-ramazan-erdogan-iej0d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlayamadık biçok şeyi,

özlemi ahsreti yaşadık,

ama öğrenemedik bi türlü sevmeyi!

seni seviyorum derken;susuyordu yüreğimiz...

el ele yanarken;üşüyordu ellerimiz...

sustuğumuz anlarda;boş bakıyordu gözlerimiz...

anlamsız sorularla doluydu sözlerimiz...

dedim ya!

anlayamadık biçok şeyi,

özlemi hasreti yaşadık;

ama öğrenemedik bi türlü sevmeyi...', 'anlayamadık biçok şeyi, özlemi ahsreti yaşadık, ama öğrenemedik bi türlü sevmeyi! seni seviyorum derken;susuyordu yüreğimiz... el ele yanark...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ogrenemedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-mustafa-yildizdogan-91150', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimler geldi kimler geçti

Dünya denen handan

Kalıcı bir eser

Geride tek kalan

Zengin ne götürdü

O servetten o maldan

Fakirden farkı ne

Yalan hepsi yalan.

Emanet bu dünya

Bedende can bile

Ne varki sevgiyle

Yaşasak el ele..

Bir yanda israflar

Bir yanda sefalet

Bir bebek ölüyor

Açlıktan merhamet..', 'Kimler geldi kimler geçti Dünya denen handan Kalıcı bir eser Geride tek kalan Zengin ne götürdü O servetten o maldan Fakirden farkı ne Yalan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüksün', 'kucuksun-yanliz-kral-yduct', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçüksün sen hayat asrını bilirim senin yalnızlığımda

Gerçekeleri yansıtmıştın sandın sanki anlıma

Felek bile ağlardı senin haline 

Ne yazıkki ağlattın beni derbeder karanlığa

Akıl varya senden bana nimet gibi

Hislerim var darma dağın sınırsızda bir yaşamım

Bazen kızar bazen güler nefretim

Küçüksün sen hayat değmez neşene kederine

Öyle şeyler örettinki bana yıkıldım sandım duramadığım 

Kızacam anılara ve senin dehşet verici acımasızlığına

Aldın o hiç vermedin aklımı sınırsız dağlarda

Küçüksün be hayat ben senin fikrini azmini sevmedim

Son olarak bağırmak istedim bir yüksek tepeden

Hayret ben seni bir kızgın demirle oydum

Sen bunu anlamadın aslında bir tarih yazdım

Küçüksün be hayat zırlama artık.', 'Küçüksün sen hayat asrını bilirim senin yalnızlığımda Gerçekeleri yansıtmıştın sandın sanki anlıma Felek bile ağlardı senin haline  Ne yazık...', ARRAY['Türk Edebiyatı','Şiir','Yanlız Kral']::text[], 8.5, '{"poet":"Yanlız Kral","poet_slug":"yanliz-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucuksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amirim', 'amirim-mustafa-yildizdogan-g8u40', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine sana yazıyorum,yine sana döküyorum içimi,

senden başka kim anlar ki beni

dün o fırtınalı gecede,eve giderken,karanlık kuytu bir köşede

bir adam çıktı karşıma.

beyim,beyim,dedi elindeki yarım kalan sigarayı göstererek,

ateş istedi tam sigarasını yakıyordum ki.

parmağından yüzzüğü görünce,o buz gibi elleri,ta ciğerimi yaktı..

bu yüzük dedimkafasını kaldırdı yüzüme baktı dokunma dedi

hey allahım bu o amirim

sarıdım boynuna tanıyamadı hatırlayamadı beni,

yalvara yalvara zor razı ettim.

eve gitmeye hava çok soğuk tu .bir allahın kulu yoktu ortalıkta

bizden ve peşinden ayrılmayan siyah kediden başka.

eve varıncaya kadar o günleri anlattım beni nasıl çatışmadan kurtardığını. yüzüğüde o günün hatırası olarak parmağına taktığımı,daha başka aydınlı plakacı 09 osmanı,trabzonlu

laz dursunu,maraşlı ede ökkeşi,erzurumlu yanık ömeri,

ama nerede,beni dinlemiyordu,bilehep birşeyler mırıldanıyorduağırdan ve sessiz.

gidenler gelmeyecek gidenler gelmeyecek,amirim başka dünyalardaydı.eve vardık kediyi kucağına aldıkediyi ısıtıyordu,halbuki kendisi titriyordu sobanın farkında bile değildi garibimberaber çektirdiğ*imiz fotağraflarıbana hediye ettiği cevşeni gösterdim oralı bile olmadı,tedirgindi bir şeyler arıyordu cebinden eski bir kağıt parçası çıkardı,

baktı,baktı,kül tablasına bıraktıfark ettirmeden aldım bir telefon numarası yazılıydı aradım,telefona çıkan karısıydı amirimin yanımda olduğunu söyleyince,kadın öyle bir çığlık attıki,kalp atışını yüreğimde hissettim.

nasıl bu hale düştüğünü sorunca,kadın bir ah çekip anlatmaya başladı.

teskeresine oniki gün geçen  fakat çatışmada olduğu için alayına dönemiyen evli yirmi yedi günlük yeni bebeği olan bir evin bir oğlu sivaslı ali adında bir asker kucağında şehit olmuş o anda şuurynu kaybetmiş vel hasıl kafayı yemiş vay be amirimki eksi yirmi beş derecede hakkarinin dağlarında kara kışa ve haydutlara karşı meydan okurdu vatan dedinmi bir vatan daha çıkardı ağzından zoru sevdirmişti çileyi sevdirmişti ay yıldızlı bayrak için ölümü sevdirmişti amirim lafın kısası güzel anam bir gün sonra kadın cağız iki çocuğunuda alıp gelmişti o karşılaşma anı var ya vijdansızı merhamete getirecek bir an karısının ve çocuklarının karşısında görünce o umursamaz adam doğruldu kanatlanacak kuşgibi öyle bir atıldıki çocuklarının üstüne anlatamam ne kadar israr ettiysem kalmak istemediler vedalaştık kapının önünde arkalarından baka kaldım kavuşmak ne güzel şey ah birde ben sana kavuşa bilsem ey güzel anam amirim sanki bir şey unutmuş gibi bir den geri döndü elini onzuma koydu gözlerini gözlerime dikti yutkundu yutgundu ve şu okkalı sözler döküldü dudaklarından bir ağaçtan bir milyon kibrit çıkar bir kibrit bir milyon ağacı kakar....', 'Yine sana yazıyorum,yine sana döküyorum içimi, senden başka kim anlar ki beni dün o fırtınalı gecede,eve giderken,karanlık kuytu bir köşede ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/amirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüncedeyim', 'dusuncedeyim-selcuk-yilmaz-tdzhc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İmgeler yaşadı bu ömür

Yaşıyor bir de seni,

Bir serap gibi giriverdin dünyama;

Bir varmış, bir yokmuşsun ,

Bir masal kahramanı gibi,

Yadsınamaz hiç

Ruhun, benliğin,

O hiç mi hiç görmediğim

Görselliğin.

Sadece o vesikalık resmin durur

Zihnimde bir yerde,

Düşüncedeyim düşünce de son günlerde,

Diyarına selam götürdüğü

Belki de o telli turnanın kanadında,

Bir deniz kabuğunun içinde belki,

Sahilde yürürken rastladığım...

Bu bir memleket 

Özlemini duyduğum,

İçinde seni barındıran bir koca şehir;

Sevgi kuşun kanadındaymış,

Kanadında bir dolu sevda yüklü

Bir o yana, bir bu yana estiren..

Düşüncedeyim düşünce de son günlerde

Yaşayan kavgasıyla bir koca şehir ve sen

Ve her yerde seni düşünen ben,

Ne kadar da yapayalnızız,

Koca denizde iki nokta.....

S.Y.  1.4.2001', 'İmgeler yaşadı bu ömür Yaşıyor bir de seni, Bir serap gibi giriverdin dünyama; Bir varmış, bir yokmuşsun , Bir masal kahramanı gibi, Yadsına...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dusuncedeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'leyli Güzel', 'leyli-guzel-mustafa-yildizdogan-5owu1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sinem delik deşik oldu

Kirpiklerin ok mu güzel

Acınacak hale düştüm

Hiç insafın yokmu güzel.

Bir bakıştı bir bakıştı

Bakış değil bir yakıştı

Gönlüm benden firar etti

O bakışla can tutuştu..

Leyli güzel leyli güzel

Gelde beni güldür güzel

Bu ayrılık yetti cana

Bu yangını söndür güzel..', 'Sinem delik deşik oldu Kirpiklerin ok mu güzel Acınacak hale düştüm Hiç insafın yokmu güzel. Bir bakıştı bir bakıştı Bakış değil bir yakıştı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/leyli-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmişim', 'sevmisim-mustafa-yildizdogan-0gy5y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim dağlarda kır çiçeğimsin,

Baharım goncamsın sevmişim seni,

Bir ömür geçmişim geleceğimsin,

Hayatım,canımsın,sevmişim seni..

Bülbüln nazları güle saklıdır,

Aşıkların özünde çile saklıdır,

Yaşanır söylenmez dile saklıdır,

Aşikar vefamsın sevmişim seni.

Hasretin çökünce gönül katına,

Başlıyor ruhumda deli fırtına,

Ne gerek binmeye sevda atına,

Kalbimde atansın sevmişim seni....', 'Sen benim dağlarda kır çiçeğimsin, Baharım goncamsın sevmişim seni, Bir ömür geçmişim geleceğimsin, Hayatım,canımsın,sevmişim seni.. Bülbüln...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Ayrılık Şiiri 4', 'on-ayrilik-siiri-4-ataol-behramoglu-bjxjo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başka biri olacaksın istemesen de

Tenine başka bir ten dokunduğunda

Gövden buluştuğunda başka bir gövdeyle

Başka bir nefesle karıştğında nefesin

Başka biri olacaksın istemesen de

Gece uykunda ya da gün ortasında

İrkileceksin apansız bir duyguyla

Bir uçurum kıyısında sendelemiş gibi

Başka biri olacaksın istemesen de

Bakışlarımın izini taşıyan giysilerin

Tüketecek ömürlerini birer birer

Değişecek yeri bir dolabın,pencerede bir çiçeğin

Başka biri olacaksın istemesen de

Dudaklarında benden sonraki bir çizgi

Tanımadığım bir ton gülüşünde

Ve artık beni unutmaya başlayan gözlerin

Sonra,sonra başka birisin', 'Başka biri olacaksın istemesen de Tenine başka bir ten dokunduğunda Gövden buluştuğunda başka bir gövdeyle Başka bir nefesle karıştğında nef...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/on-ayrilik-siiri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevg,i Allahım', 'sevg-i-allahim-mustafa-yildizdogan-p83z6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz sevgi garibi

Sevda fakiriyiz

Gönlümüz kuru

Gönlümüz susuz

Çölde can gibiyiz

Sevgi allahım...

Aşktan,meşkten uzak,

Bir acı feryadız

Huzurun adı yok

Kavgalardayız

Sevgi allahım..', 'Biz sevgi garibi Sevda fakiriyiz Gönlümüz kuru Gönlümüz susuz Çölde can gibiyiz Sevgi allahım... Aşktan,meşkten uzak, Bir acı feryadız Huzur...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevg-i-allahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk De Gitsin!!', 'ask-de-gitsin-abdullah-gokhan-konbul-takwq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek suçsa, en büyük suçlu benim.

Cezam ağlamaksa, bırakın ağliyim!

Aşk yalan,aşık olmak yalansa. En büyük yalancı benim .

Seni sevmenin bu kadar acı çektireceğini bilseydim 

İnan yinede seni severdim', 'Sevmek suçsa, en büyük suçlu benim. Cezam ağlamaksa, bırakın ağliyim! Aşk yalan,aşık olmak yalansa. En büyük yalancı benim . Seni sevmenin b...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gökhan Konbul']::text[], 8.5, '{"poet":"Abdullah Gökhan Konbul","poet_slug":"abdullah-gokhan-konbul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-de-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim Bu Kentten Uzaklara', 'gidecegim-bu-kentten-uzaklara-ozcan-nevres-3a1km', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GİDECEĞİM BU KENTTEN UZAKLARA

Gideceğim bu kentten çok uzaklara.

Bir yer bulacağım yaşanacak,

En içten sevgilerle dolu.

Bu kentte iki yüzlülükler diz boyu.

Gerçek sevgilerse, bir arpa boyu. 

Beyaz evler olacak gittiğim o yerde.

Sevgilerin ve içtenliğin simgesi.

Evimin saçaklarında kuşlar yuva yapacaklar.

Cıvıl, cıvıl ötecekler gün boyu.

Bahçesinde çiçekleri olacak

Renk, renk açacaklar her mevsim.

Kümeslerinde tavuklar, tavşanlar.

Bir çukur açacağım, su dolduracağım içine.

Ördeklerim, kazlarım yüzsünler diye.

Sabahları kalkacağım gün doğumu. 

Bir türkü tutturacağım mutluluktan yana.

Yemlerini verirken hayvanlarıma.

Hırsız serçeler dalacak aralarına.

Kapacaklar, ne düştüyse paylarına.

Etrafımda bir sevgi yumağı oluşacak,

Evcilleriyle, yabanisiyle.

Alacalı tavşanım gelip kucağıma çıkacak,

Elimden aldıklarıyla karnını doyuracak.

Yumuşacık tüylerini okşarken,

Yine sen geleceksin aklıma.

Parmaklarımla taradığım,

Saçlarını anımsatacak bana,

Vefasızlığınla birlikte.

Issız bir yerden geçerken korkarsın ya,

Türküler söylersin avaz, avaz,

İçindeki korkuyu yenmek için. 

İşte öylesine türküler söyleyeceğim.

Seni unutmak için. 

Kazıyacağım içimden seni. 

Yem yapıp hırsız serçelere atacağım.

Ki......

Bir daha dönmeyesin geriye. 

			Özcan NEVRES', 'GİDECEĞİM BU KENTTEN UZAKLARA Gideceğim bu kentten çok uzaklara. Bir yer bulacağım yaşanacak, En içten sevgilerle dolu. Bu kentte iki yüzlül...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gidecegim-bu-kentten-uzaklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-yalcin-gul-ddxbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arka sırada tek başına 

Hep yalnızdı Umut

Hiç arkadaşı yoktu

Olamazdı da 

Ya döverdi küçükleri

Ya kırardı cetvelleri, kalemleri

Sevmedi hiç birimizi

Hatta o çok sabırlı sevecen öğretmenimizi

Bu gün duydum öksüz ve yetim büyüdüğünü

Nasıl sevebilirdi ki?

Görmemişti, öğrenmemişti ana baba sevgisini

İsterse kırabilir bütün kalemlerimi

İsterse kırabilir bütün cetvellerimi

Sabırla, umutla bekleyeceğim

Umut''un sevmeyi öğrenmesini.', 'Arka sırada tek başına  Hep yalnızdı Umut Hiç arkadaşı yoktu Olamazdı da  Ya döverdi küçükleri Ya kırardı cetvelleri, kalemleri Sevmedi hiç ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Gül']::text[], 8.5, '{"poet":"Yalçın Gül","poet_slug":"yalcin-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum!', 'sustum-mustafa-gokhan-sahin-nvt9z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En az benim kadar aklın karışmadıysa;

Benim kadar dalmadıysan başka alemlere;

Benim seni aradığım gibi sokaklara vurmadıysan kendini;

Her baktığın kişide beni görmediysen;

Acaba sen misin demediysen defalarca;

Sevmediysen beni benim seni sevdiğim kadar;

Ah, ben sana daha ne diyeyim ki?

(Mart 2001 Turhal-İstanbul)', 'En az benim kadar aklın karışmadıysa; Benim kadar dalmadıysan başka alemlere; Benim seni aradığım gibi sokaklara vurmadıysan kendini; Her ba...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökhan Şahin']::text[], 8.5, '{"poet":"Mustafa Gökhan Şahin","poet_slug":"mustafa-gokhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sustum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-ozcan-nevres-9wuuk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GİDİYORSUN

Gidiyorsun veda etmeden

Bu gidişin dönüşü olur mu bilemem

Nice aşklar, hiç uğruna tükenirken

Gidişine ağlamadım diyemem

Gitmesen iyi olur muydu bilmiyorum

Döne bilir miydik eski güzel günlerimize

Yanan bir ormanın ardında kalan, 

Küllerin üstünde yeşeren fidanlar gibi

Yeniden filizlenir miydi aşkımız

Bir gün pişmanlıkla burkulursa yüreğin

Dön gel güzelim, açık sana yüreğim

		Özcan NEVRES', 'GİDİYORSUN Gidiyorsun veda etmeden Bu gidişin dönüşü olur mu bilemem Nice aşklar, hiç uğruna tükenirken Gidişine ağlamadım diyemem Gitmesen ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidiyorsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demek ki Gidiyorsun', 'demek-ki-gidiyorsun-ozcan-nevres-z4gpb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DEMEK Kİ GİDİYORSUN

Demek ki gidiyorsun 

Göz yaşlarıma aldırmayarak

Neden bu gidişin diye sormuyorum

Terk etmek senin tutkundur biliyorum

Sen aşkın ne olduğunu  bilmedin. 

Benim gibi delicesine sevmedin

Sevseydin eğer terk edip gider miydin

Giderken ne olur bakma arkana

Göz yaşlarımı görüp sakın aldanma

Sileceğim seni gönlümden inan bana

Pişman olur, dönersen bir gün geriye

Gönül kapımı açık bulacağını sanma

Bundan böyle sen yoluna ben yoluma

			Özcan NEVRES', 'DEMEK Kİ GİDİYORSUN Demek ki gidiyorsun  Göz yaşlarıma aldırmayarak Neden bu gidişin diye sormuyorum Terk etmek senin tutkundur biliyorum Se...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/demek-ki-gidiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar', 'karar-mustafa-gokhan-sahin-ftf5a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni seveyim mi sevmeyeyim mi?

Senin için öleyim mi ölmeyeyim mi?

Sana aşık olayım mı olmayayım mı?

Ne bileyim?

Kararsızım;

Bir kere yüzüme gülmedin ki!

(Mart 2001, Turhal-İstanbul)', 'Seni seveyim mi sevmeyeyim mi? Senin için öleyim mi ölmeyeyim mi? Sana aşık olayım mı olmayayım mı? Ne bileyim? Kararsızım; Bir kere yüzüme ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökhan Şahin']::text[], 8.5, '{"poet":"Mustafa Gökhan Şahin","poet_slug":"mustafa-gokhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/karar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahkar Mevsim', 'gunahkar-mevsim-cezmi-ersoz-jnufv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yakınlaştıkça kaybolan

Bir kente dönüşürdün

Keşfedilmezim olurdun

İçinde yolculuk etsem de...

Günahkar mevsimimdin.

Hiç umut yoktu sende,

O yüzden vazgeçilmezdin,

Vazgeçilmezimdin...', 'Yakınlaştıkça kaybolan Bir kente dönüşürdün Keşfedilmezim olurdun İçinde yolculuk etsem de... Günahkar mevsimimdin. Hiç umut yoktu sende, O ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunahkar-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebrik', 'tebrik-mustafa-gokhan-sahin-4fdxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni hiç arama,

Halimi hatırımı sorma,

Telefonunu söyleme,

Bana mektup yazma,

Yüzüme bir kere gülme,

Tebessüm etme bana,

Mavili başörtünü giyme,

Hiç ortalıkta gözükme.

Sen en iyisi beni öldür emi!

Aferin.

(Mart 2001, İstanbul)', 'Beni hiç arama, Halimi hatırımı sorma, Telefonunu söyleme, Bana mektup yazma, Yüzüme bir kere gülme, Tebessüm etme bana, Mavili başörtünü gi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökhan Şahin']::text[], 8.5, '{"poet":"Mustafa Gökhan Şahin","poet_slug":"mustafa-gokhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tebrik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümü Kayda Geçirdi Bir Sokak', 'omrumu-kayda-gecirdi-bir-sokak-cezmi-ersoz-5e983', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski bir yalnızlıktan ödünç alınmış günlerle

Yaşadım gençliğimi ölü bir kadının saçlarını

Okşayarak ...

Yaşadım babamın ruhuma ithaf ettiği

Bütün pişmanlıkları ,

Bozgun bir kalp ve siyah bayraklı şiirlerle

Dolaştım bütün sahipsiz duyarlıkları...

Ömrümü kayda geçirdi bir sokak

Sokak ki vaiz ve ticaret 

Islak tül kokusu ve kömür.

Sokak ki hep kışa doğru yürür', 'Eski bir yalnızlıktan ödünç alınmış günlerle Yaşadım gençliğimi ölü bir kadının saçlarını Okşayarak ... Yaşadım babamın ruhuma ithaf ettiği ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/omrumu-kayda-gecirdi-bir-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Patron', 'kucuk-patron-yalcin-gul-fkukh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Babamın iş yerine 

Patron oluyordum

Böylece onu bütün gün

Görebiliyordum

Tam ona zam yapacaktım

O da oğluna 

Bisiklet alcaktı

En güzel yerinde rüyamın

Uyandıracak ne vardı?', 'Babamın iş yerine  Patron oluyordum Böylece onu bütün gün Görebiliyordum Tam ona zam yapacaktım O da oğluna  Bisiklet alcaktı En güzel yerin...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Gül']::text[], 8.5, '{"poet":"Yalçın Gül","poet_slug":"yalcin-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kucuk-patron-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklentisel Gece Hikayesi', 'beklentisel-gece-hikayesi-avni-dincer-kghy4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece içindeyim

Geceyi bekliyorum...

Bir ben bekliyorum

Kimseler yok ayrıntıda...

Vurdukça saatin kadranı

Nakış nakış işliyorum geceye yalnızlığımı...

Beklemiyorum çalmayacak kapıyı

Gelmeyecek telefonu

Yazılmayan mektubu...

Geceyi bekliyorum

Gündüzün göklerine özgürce imzasını atan

Kuşların uyuduğu geceyi...

Günlerin üstüne

Bütün ağırlığı ile devrilen geceyi...

Kuytu bir sokakta açan

Ve yine o kuytu sokakta ölecek

Karanfilin gecesini bekliyorum...

Geceyi bekliyorum

Özgür gecelerimi

Yalnızlığımı içtiğim gecelerimi...', 'Gece içindeyim Geceyi bekliyorum... Bir ben bekliyorum Kimseler yok ayrıntıda... Vurdukça saatin kadranı Nakış nakış işliyorum geceye yalnız...', ARRAY['Türk Edebiyatı','Şiir','Avni Dinçer']::text[], 8.5, '{"poet":"Avni Dinçer","poet_slug":"avni-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beklentisel-gece-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicrana Şükr et', 'hicrana-sukr-et-sair-baraka-43jdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ertesindeyim olgunluğumun

Yokum huzurumdayım

Günün hadisini dinleyin

hutbemdir

Her zaman her şeyde

Şükr et yar ad ana

Hiç bir şey vermesede

Şükür et şükür yine

Ki sana kötü bir şey vermemiş

Şükür et ki seni şüpheyle uyarmış

Aslın esastan 

cismin maninden

Bir delinin bir alinin kaale kalmaz

Sözleri ya su ya küdr ya ud

Yad ile ed bir şükür ile bad et

Zamanı yoktur her an ba hane

Bin şüküre bin rahmete

Ki o an edildi

Bir kehanetle

Yüce maharetle

Bir hiç ile

Seni eyledi

Bil de ki

O na mer ha ba

Ya şükr ya yazed

Bir bes me le 

me dir dil de

mey aline şükr ed

ya su ya hu 

deyu deyu

ya şüya ya huya

seni var eyledi

ya hu deyu deyu

ciğerimincanlarına......

barakadan', 'Ertesindeyim olgunluğumun Yokum huzurumdayım Günün hadisini dinleyin hutbemdir Her zaman her şeyde Şükr et yar ad ana Hiç bir şey vermesede ...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hicrana-sukr-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Zamanları - Veda -', 'yagmur-zamanlari-veda-i-sa-sari-yb0ic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir veda vaktidir akşamlar şimdi.....

gözlerine değen gülleri an....

bir mavi dalgaya kanıp da gider...

yüreğine değen gözleri an....

küllere karışır bir akşam vakti..

rüzgar da uçuşan külleri an...

yan ki bir serinlikte aşklar uyansın...

hedefe koşuşan kurşun dayansın...

keşmir de bir ayşe kız... 

ayakları yalıncak...

filistin de bir garip evlat acısı...

ve ah unutulmuş sevdalar...

selamı selam olmayan ruh....

ve artık nursuz umursuz dualar...

zamanın yalnız çocukları kadar..

olamıyorsam onurlu...

bırakın gideyim bırakın gideyim beni...

hey akşamlar...

ne ölümünde yalnız,  ne vahşetinde kıskanç 

ve bir çocuk şarkısı kadar saf aradığım masum yüz...

insan gözleri içinde en güzel bir çift siyah göz...

ya  da uzakları içine sindiren dalgınca bir gidiş...

gerçeğin senfonisi ayakuçlarında yalnızlığımızın...

zamanın durduğu yerde utanç duruşumuz...

ve artık susuşumuz bir mevsim boyu...

ne umudu olmayacağımız ne de dönüşü olmayan bir gidiş..

içimizde yükselen sesler ve susturduklarımız...

ve kimselere tanıdık gelmeyen yalnızlıklarımız...

bizi ancak saf  ve masum uzaklar anlayacak...

bu rüya bittiğinde anlatmadığımız...

ne kimsesizlerin kimsesi

ne kimselerin kimsesizliği

yolların şöyle yada böyle olması hiç umurumda değil

içimizden akan damlalarla ıslanacak penceremiz

her damla bir nota her damla bir adım

ve bir damla alıp götürecek başımızı uzak diyarlara

ruhumuz bir başka mevsim

gözlerimiz bir başka akşam

dalıp gittiğimiz kadar uzaklara

mırıldandığımız melodilere

bu gidişi ancak o yollar anlatacak...

Artık, bozkıra dönmek vaktidir...', 'bir veda vaktidir akşamlar şimdi..... gözlerine değen gülleri an.... bir mavi dalgaya kanıp da gider... yüreğine değen gözleri an.... küller...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yagmur-zamanlari-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Zamanları - Zaman Tüneli -', 'yagmur-zamanlari-zaman-tuneli-i-sa-sari-wt5fb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adsız ve amansız bir kavganın

Yitik insanları

Bir zaman tünelinden geçmiş gibi

Bitik  ve şaşkın

Yorgun anılardan

Hatıra devşirmeye çalışırken yakalandılar ansızın

Bu şehir o şehir değildi 

Ne yüzler o yüzler 

Ne vakit gençlik çağı

Kudret ve acz, hüzün ve zafer

Şanlı ayrılığı ölümün ve hayatın 

İçinden akıyor yalnızlığımız...

                   1999...', 'Adsız ve amansız bir kavganın Yitik insanları Bir zaman tünelinden geçmiş gibi Bitik  ve şaşkın Yorgun anılardan Hatıra devşirmeye çalışırke...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmur-zamanlari-zaman-tuneli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Zamanları - Söz Kurşundan Ağır -', 'yagmur-zamanlari-soz-kursundan-agir-i-sa-sari-p46z0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çalınmış akşamlar da

ve yarım kalmış şarkılarda kaybettiğim izler ah 

ah yalınayak tozlu yollarda yürüyen çocukluğumun saf günleri

ah ateşe durmuş aşamüstleri

ah uzaklarda kalmış mavilikler

neden çaldınız gözlerimden uzayıp giden bir senfoniyi

oysa

ölümlü bir ağacın ilk su gördüğü gün gibi 

bir karanlık hücrede ağaran günün ilk ışığı sanmıştım 

ben bu geçen gölgeyi

ve ruhumda her insan bir tebessüm dü

neden yargıladınız bir dalgadan içimize vuran parıltıyı

o ki bir buluttan adımını atarken aşşağıya 

özgürlük sanıp kanmıştı yalanımıza

o ki bir sükuta  dem olmuştu biraz çekingen isyanıyla

bir damla da öldürdük ya güllerin çalımını

son kurşunumuz tükendiğinde

onurumuzu sürdük kavga meydanına

gün oldu kurşundan da ağır oldu sözümüz..

ve artık ağaran bir sonbahar yaprağında

dalgınca yere diktiğimiz yüzümüz

ne zaman başkaldırsa

uzaklara dalar gider

utancımız yok

insan gibi insan olmakdan başka

gün olur enginde bir mavilikde 

yankılanır sözümüz

gün olur

söylenecek  söz kalır dünyada....

2001', 'çalınmış akşamlar da ve yarım kalmış şarkılarda kaybettiğim izler ah  ah yalınayak tozlu yollarda yürüyen çocukluğumun saf günleri ah ateşe ...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yagmur-zamanlari-soz-kursundan-agir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar - İzmir -', 'ruzgar-i-zmir-i-sa-sari-dd38m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey insanlık 

Bir gün unutabilirim sizi

Kendimi bir köşe de unuttuğum gibi

Gözbebekleri kayıp bir insanın 

Gözlerinde ne mana vardır bilirmisiniz

Bir şehrin gökyüzünü terkeden yıldızlar gibi

Bir gün siz de gidebilir misiniz

Düşüne çığ düşmüş İzmir akşamlarından...', 'Hey insanlık  Bir gün unutabilirim sizi Kendimi bir köşe de unuttuğum gibi Gözbebekleri kayıp bir insanın  Gözlerinde ne mana vardır bilirmi...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgar-izmir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar    - Hepimizin Gurbeti -', 'ruzgar-hepimizin-gurbeti-i-sa-sari-fbi7n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tüter duman duman gözümüzde hasreti

Giden trenler gibi, bir bomboş gardan

Her yeniden doğuş, uzaklaşmak diyardan...

Her ufukta iz, çöker sıla hasreti

Yükseklerden süzülüp, enginlere gelinir

Umut, her adımda yollarla belenir...

Nefes, soluk soluk göğsümüzde hasreti

Sızısı çöker, pençesiyle ciğerimize

Her gidiş karmakarışık, söylenir bize...

Bu şehir...Bu şehir... Hepimizin gurbeti

Hayali can, yaşadım mı zannettin? 

O duyduğun çığlık senin türkündü

Dalıp gittin, bir heybetli dalgınlığa...', 'Tüter duman duman gözümüzde hasreti Giden trenler gibi, bir bomboş gardan Her yeniden doğuş, uzaklaşmak diyardan... Her ufukta iz, çöker sıl...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruzgar-hepimizin-gurbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç kez? ...', 'kac-kez-ferit-teksoy-sfl2s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu kaldırımların dili olsa anlatsa,kaç kez geçtim? 

Dalgın sen düşünerek,söylese kaç kez? 

Gece yıldızlar gördü,karanlıklar şahidim,

Hayalinle konuşup,adını söyleyerek sabahlar ettim kaç kez? 

Gözlerimle kavgamı onlar söylesin sana,

Kapanmak isteyeni soğuk sulara vurdum,ıslattım kaç kez? 

Beynimle savaşımı düşünme onu diye,

Kafam avuçlarımda dişlerimi sıktım,kanattım kaç kez? 

Elim cebimde dalgın sahilimde yürürken,

Boş kutular söylesin kaç tekme vurdum,kaç kez? 

Kaç taş attım öfkeyle,kaderime söverek? 

Sor denize söylesin..söylesin deniz kaç kez? 

Bir de martılara sor öfkeli bakışımı,

Gözlerim uzaklarda küfürler ettim kaç kez? 

Yılgın,umutsuz,kırgın kaç geceler geçirdim? 

Duvarı yumrukladım,kadehler kırdım kaç kez? 

Beynim seninle dolu,elimde kalem,kâğıt,

Sana yazıp,çizdiğimi,söylesin kalem kaç kez? 

Zonklayan başım desin,ağrısı dinsin diye,

Kaç çeşit hap içtiğimi,uyuşmak için kaç kez? 

Bir de sol elime sor parmak aralarımda unuttuğum sigaram,

Dalgın sen düşünürken..yazarken yandı kaç kez? 

03 Ocak 2001', 'Şu kaldırımların dili olsa anlatsa,kaç kez geçtim?  Dalgın sen düşünerek,söylese kaç kez?  Gece yıldızlar gördü,karanlıklar şahidim, Hayalin...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kac-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeler', 'maskeler-mustafa-caykoylu-u2lsk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Maskeler takılır sabahın kör vakti

Aktör gibi oynar rolunu oluverir baska kisi

Gece uyku vaktine kadar yasar bu garip kisi

Sanmayın bu sahte adamin çeliktendir dişi

Bazen oluverir korkusuz bir suvari

Bazende filmlerin sempatik romantigi

Vicadanindan ruhuna yayilan sahteligi

Anlayamaz yavas yavas kemirdigi

Zavalli ruhunun son demini.', 'Maskeler takılır sabahın kör vakti Aktör gibi oynar rolunu oluverir baska kisi Gece uyku vaktine kadar yasar bu garip kisi Sanmayın bu sahte...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çayköylü']::text[], 8.5, '{"poet":"Mustafa Çayköylü","poet_slug":"mustafa-caykoylu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/maskeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen', 'hep-sen-ozcan-nevres-kvv4b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahile gideceğim bu gece,

Karanlığın ve sessizliğin,

En yoğun olduğu yerde.

Seni düşleyeceğim.

Geçmişte kalan o güzel günlerimizi 

Anımsayacağım vefasızlığınla birlikte. 

Sanma ki ağlayacağım yine.

İhanetini ve tüm kötülükleri,

Söküp atacağım gönlümden,

Geride yalnızca iyilikler kalacak.

Bir inci miydi ki umutlarım,

Kumlar içinde kaybolan?

Bulunması öylesine zor olan?

Umutlar yeşerecek gönlümde,

Bir dağın güney yamacındaki

Ormanlar gibi, 

Olabildiğince gür ve yeşil.

Yağmuru indireceğim gök yüzünden,

Sinemde toplayacağım,

 Tüm yağmur sularını.

Kurumuş yol boyu, çoban çeşmeleri,

Yine akacaklar şırıl, şırıl 

Eskisi gibi.

Nice bağrı yanıklar,

Susuzluğunu giderecek çeşmelerimden.

İçlerindeki yangın söndüğünde,

Diyecekler,

Bu çeşmeler kurumuştu bir zamanlar.

Benim yüreğim kadar yanıktılar. 

Susuzluktan çatlamıştı tüm yalaklar.

Ne olmuş  bunlara böyle

Coşkun ırmaklara dönmüşler.

Kitabe olacağım, çeşme kaidelerinde.

Okuyacaklar beni,

Bir zamanlar ben de yanıyordum,

Sizler gibi yürekten.

Terkedilmişlikti beni,

Yangın yerine çeviren.

İhaneti unuttum,

Sildim tüm geçmişi gönlümden.

Yeni sevgiler buldum.

Bulut oldum, yağmur oldum, orman oldum

Ve su oldum, tüm yangınları söndüren.

Sende,

Geçmişi unut, 

Seni yakan o vefasızla birlikte.', 'Sahile gideceğim bu gece, Karanlığın ve sessizliğin, En yoğun olduğu yerde. Seni düşleyeceğim. Geçmişte kalan o güzel günlerimizi  Anımsayac...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/hep-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerimiz', 'siirlerimiz-zeki-ergin-izvge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şiirlerimiz birer neşterdir

işleyen yaralara

şiirlerimiz

şiirlerimiz birer aydınlık yoldur

yarınlara', 'şiirlerimiz birer neşterdir işleyen yaralara şiirlerimiz şiirlerimiz birer aydınlık yoldur yarınlara...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siirlerimiz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostundum Hani', 'dostundum-hani-fatma-karakaya-lrdo7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güle baktım;birde sana 

tek fark sen daha vefalısın dostum 

Bir dünü yaşıdım birde yarını 

İkiside geçti bir sen kaldın dostum 

Bir anılardı beni anlayan 

Birde herşeyim olan sen 

Anlamsız olmayan tek varlık 

Hayatıma değer dostum benim.

BENİM SANA CEVABIM GEÇ KALINMIŞ BİR CEVAP YADA

Dostu dost yapan,dostluğu olmamalı

Düşmanken bile sevişebilmek

İşte dostu dost yapan budur.

Herşeyim dediğin ben şimdi hiçbirşeyinsem

Hiçbirşeyinmişim herşeyinkende.

Anlamsız olmayan tek varlık göstersem

O sen olurdun 

Benim anlamlılığımın eserisin çünkü.

Dostun af dilerdi ama artık çok geç

Kendini kendine emanet ediyorum.

Beni dost yapan sana,kalbinin sana dostluğuydu

Kalbin olgunlaştı gitgide,hür ve özgür 

Tek olmak senin için en güzeli.

Uzaklardan sevgi sunulmuyor Fatma

Ne dostluk ne de başka birşey

Ben beceremedim ya da,yoruldum

Acılar içinden mutluluğu sana anlatmak ilaçtı ikimizede ama

Ben tükendim,olmuyor bitsin istedim....

Sana da zarar vermekten korkmuştum ki

İstemeden daha da üzdüm.

Sonsuzlukta yankılansın bu mısralar ki.

Ben ne yaptımsa senin için yaptım

Elimde olsa dünyaları önüne sererdim

Eyvallah...', 'Bir güle baktım;birde sana  tek fark sen daha vefalısın dostum  Bir dünü yaşıdım birde yarını  İkiside geçti bir sen kaldın dostum  Bir anıl...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakaya']::text[], 8.5, '{"poet":"Fatma Karakaya","poet_slug":"fatma-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dostundum-hani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enkaz Altında', 'enkaz-altinda-yavuz-nufel-4msw9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'baba bak! 

o görünen annemin eli

senin aldığın yüzükten belli

kardeşlerimi düşünme

onlar şu anda parktadır belki

oyuncak helikopter 

alamıştın ya hani

alma artık istemem

bak onlarca helikopter

hem hepsi de sahici

kıpırdat gözlerini

 konuş benimle baba

''Elle gelen dğün bayram''

derdin ya hep

bu nasıl düğün, 

bu nasıl bayram? 

 neden yerde yatıyor

teyzem,, halam, dayım, amcam? 

ne olur birşeyler söyle

konuş benimle

hadi benim aslan babam...

istemezsen bu sene

okula da gitmem, 

eğer gidersem; 

geçen seneki idare eder, 

yeni önlükte istemem...

bir kerecik ''oğlum'' de yeter.

bacaklarında kan var

kırıldı mı yoksa? 

alçıya alsınlar

duyuyor musun? ...

geliyor ambulanslar...

sen iyileşinceye kadar

ben su satar, simit satar

size bakarım; 

annemin çamaşır ipleri 

yine kopmuş, 

sen üzülme ben takarım! ..

daha dün senin 

kocaman adamındım; 

berbere götürecektin hani, 

uzadığı için saçlarım...

''Yavrum'' de; okşa saçlarımı, 

öp yanaklarımı

babacığım ne olursun! ...

hadi kalk! 

 sen de bağır, sende çağır

her taraf yanıyor cayır cayır! ...

''Erkekler ağlamaz'' dersin

ama

ağlamak istiyorsan ağla

vallahi kimseye söylemem baba...

gözlerine toz dolmuş! 

silsene baba! 

baba! .. baba! ..

yoksa? ! . Baba! ...

BABAAAAAAAAAA! ...', 'baba bak!  o görünen annemin eli senin aldığın yüzükten belli kardeşlerimi düşünme onlar şu anda parktadır belki oyuncak helikopter  alamışt...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Nufel']::text[], 8.5, '{"poet":"Yavuz Nufel","poet_slug":"yavuz-nufel","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/enkaz-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez mi', 'yetmez-mi-mustafa-tarakci-jgp8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yetmez mi?

Bunca yapılanlar yetmez mi?

O''nu anlamaya, O''nu anmaya.

Yetmez mi bunca eser?

Doğudan batıya.

Her nereye baksak O''nun eseri,

Demiryolu, Şeker Fabrikası, Seka''sı,

Demir İşletmesi, Basması, Etibank''ı,

Yetmez mi bunca eser, bunca reformlar?

Yeni harf, yeni kıyafet, takvim, tartı,

Yeni hukuk sistemi, yeni eğitim sistemi çağdaş ülkelerde olan,

Cumhuriyet.

Eşitlik esaslı, adil ve bilime dayanan.

Yetmez mi bunca silkiniş kısa sürede?

Topu topu 18 yılda, 1920''den 38''e,

Kim başarmış, hangi lider bunca işleri?

Gerek değil mi söylediği!

''Az zamanda çok ve büyük işler yapıldı''.

Azim ile, çoşku ile, birlik ve beraberlik içinde.

Yetmez mi kardeşim, O''nu anmak için?

O''na minnet ve şükran duymak için bunlar.

Dört bir baştan sarılmıştır vatan!

Şura benim, ora senin kavgaları işgalcilerde;

Sanki bu topraklar ucuz bulundu,

Sanki bu topraklar birilerinden lütuf oldu,

Sanki hiç can verilmedi, hiç kan akıtılmadı,

1071''den 1918''e.

Yetmez mi bunca devletlerle başa çıkmak?

Türk''ün gücünü, Türk''ün azmini, Türk''ün vatan sevgisini kanıtlamak.

Yetmez mi bunca çaba, bunca gayret?

Cepheden cepheye koşarak, ölümün üstüne giderek,

Elini vicdanına koy be kardeşim!

Yetmez mi bunca yapılanlar?

O''nu bağrımıza basmaya, O''na minnet ve şükran duymaya,

O''nun önünde saygı ile eğilmeye...

Yetmez mi?', 'Yetmez mi? Bunca yapılanlar yetmez mi? O''nu anlamaya, O''nu anmaya. Yetmez mi bunca eser? Doğudan batıya. Her nereye baksak O''nun eseri, Demi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tarakçı']::text[], 8.5, '{"poet":"Mustafa Tarakçı","poet_slug":"mustafa-tarakci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yetmez-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazire', 'nazire-la-edri-0u0e7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kadar ders-i zaifle ne yapsam gerek

Kuse-i uzlette inekves calissam gerek

Surup ayagin tozuna yuz pirin

Her dem yag u cila mi ceksem gerek

Doldurup sira vu duvari kopyayla

Cakdurmayup kimseye ceksem mi gerek

Okundu kagud-i vizeler geldi zaifler

Pedere bunlari az gostersem gerek', 'Bu kadar ders-i zaifle ne yapsam gerek Kuse-i uzlette inekves calissam gerek Surup ayagin tozuna yuz pirin Her dem yag u cila mi ceksem gere...', ARRAY['Türk Edebiyatı','Şiir','La Edri']::text[], 8.5, '{"poet":"La Edri","poet_slug":"la-edri","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doksan Beşe Doğru', 'doksan-bese-dogru-tevfik-fikret-9tczi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir devr-i şeamet, yine çiğnendi yeminler; 

Çiğnendi, yazık, milletin ümmid-i bülendi! 

Kanun diye topraklara sürtündü cebinler; 

Kanun diye, kanun diye kanun tepelendi...

Bihude figanlar yine, bihude eninler.

Eyvah! otuz üç yıl o zehir giryeleriyle,

Hüsranları, buhranları, ehvali, melali,

Amal-ü devahisi ve sulh-ü seferiyle

Bir sel gibi akmış, mütevekkil, mütehali.

Yazsın bunu tarih-i iber hatt-ı zeriyle! 

Ey bir dem-i rüya gibi geçmiş kara günler,

Bir lahza edin seyr-i cahiminizi tekrar,

Dönsün bize o derin nazra-i muğber.

Heyhat! otuz üç yıl, otuz üç yıl bütün ekdar

Heyhat! ne bir ders, ne bir fikr-i mukarrer

Silmez fakat elvahını tarih-i muanit,

Doksan beşi aç! gölgesi bir tac-ı harisin

Saklar mütelaşi, mütereddit, mütemerrit

Evca-ı şebengizini bir yevm-i habisin.

Hala o vesavis, o desayis, o mefasit.

Hala o şebin zeyl-i temadisi bu ezlam,

Hala o cehalet, o tecahül ve o techil,

Hala vatan hissesi bir tude-i alam,

Hala düşünen başlara hep latme-i tenkil,

Hala sırıtan dişlere hep lokma-i inam! 

Hala tarafiyyet, hasebiyyet, nesebiyyet,

Hala: ‘bu senindir, bu benim! ’ kısmeti cari,

Hala gazap altında hakikatle hamiyyet.

Hep dünkü terennüm, sayıdan, saygıdan ari; 

Son nağmesi yalnız: yaşasın sevgili millet! 

Millet yaşamaz, hakka tahassürle solurken

Sussun diye vicdanına yumruklar inerse; 

Millet yaşamaz, meclisi müstahkar olurken

İğfal ile, tehdit ile titrer ve sinerse; 

Millet yaşamaz maşer-i millet boğulurken! 

Kanun diyoruz; nerde o mescud-i muhayyel? 

Düşman diyoruz nerde bu? hariçte mi, biz mi? 

Hürriyetimiz var, diyoruz, şanlı, mübeccel,

Düşman bize kanun mu? ya hürriyetimiz mi? 

Bir hamlede biz bunları, kahrettik en evvel.

Bir hamle-i mahnum-i tagallüple değiştik

Hürriyeti şahsiyyete, kanunu gurura,

Heyhat! otuz üç yıl geri düştük ve mühlik

Yoldan şu nedametli ve gafletli mürura

Bişüphe o humma-yi cünun oldu muharrik.

Ey millete bir sille olan darbe-i münker,

Ey hürmeti kanunu tepen sadme-i bidad,

Milliyeti, kanunu mukaddes tanıyan her

Vicdan seni lanetle, mezelletle eder yad...

Düşsün sana meyyal-i tahakküm eğilen ser

Kopsun seni –bir hak diye- alkışlıyan eller

1912', 'Bir devr-i şeamet, yine çiğnendi yeminler;  Çiğnendi, yazık, milletin ümmid-i bülendi!  Kanun diye topraklara sürtündü cebinler;  Kanun diye...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/doksan-bese-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenindeki Kutsal Mum', 'tenindeki-kutsal-mum-cezmi-ersoz-aw9xv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En ayıp sözcüklerle soyardım bedenini, 

Düşlerimin teriyle kirletir, 

En sabırsız, en iştahlı, en yabancı yanımla girer, 

Arzularımın kanıyla kirletirdim onu. 

Oysa kötülendikçe, kirlendikçe yüreğinden 

Işımaya başlayan 

Hissettiğim en kırılgan bedendi seninkisi 

Biterdi sonra her şey... 

Asıl serüveni başlardı bedeninin, 

Çekilir bir köşeye seyrederdik... 

Ayıp, kirli, kötü 

Ne varsa, 

Teninin içindeki pencerelerde yanan kutsal bir muma dönüşürdü... 

Çekilir bir köşeye seyrederdik', 'En ayıp sözcüklerle soyardım bedenini,  Düşlerimin teriyle kirletir,  En sabırsız, en iştahlı, en yabancı yanımla girer,  Arzularımın kanıyl...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tenindeki-kutsal-mum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancağ-ı Şerif Huzurunda', 'sancag-i-serif-huzurunda-tevfik-fikret-u8emj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey rayet-i Peygamber, ey ümmid-i ahiri

Milyonla kulubun;

Ey nefha-i gaybiye-i nusret, ki safiri

Vecd- aver olur ruhuna şarkın ve cenubun;

Kudsiyyet-i feyzinle açıl, rengini göster,

Varsın soluk olsun

Bir hahzacık ey seyf-i cihad, oyna kınından,

Aksın koyu kanlar;

Vadeyliyor Allah, olacaktır sana kurban

İslam’a ihanet düşünen can-ü cihanlar.

Gafil medeniyyet, seni en sonra muhakkak

Hüsran ile tetvic edecek akl-i tebahın

Allahına şükret:

Şükret ve maasine olup taib-ü nadim,

Haktan talep-i ecr-i cihad et... Ne saadet,

Rabbin ne saadet ki, bugün din uğrunda

			Emvalimi verdim;

Rabbim ne saadet, ne saadet ki yolunda

Emvalimi, eşgalimi, amalimi verdim.

Artık yürürüm... avn-i Hüda meşal-i rahım,

			Biazm-ü iradet;

Peygamberimin sancağı oldukça penahım.

Elbet benimdir ebedi savn-ü selamet

Artık yürürüm... Yıldırım insin beni yakmaz,

			Boğmaz beni tufan;

Ben hıfz-ı melaikteyim, elbette bırakmaz

Onlar beni düşmanlara, yoktur buna imkan.

Gözler yumulu, sine açık, can müteselli,

Vicdansa pür-ümmid.

Ben Rabbime doğru

Her an müteveccih, mütevekkil ve saburum,

Ölsem de ne mutlu bana, kalsam da ne mutlu!

1915   (Son Şiiri)', 'Ey rayet-i Peygamber, ey ümmid-i ahiri Milyonla kulubun; Ey nefha-i gaybiye-i nusret, ki safiri Vecd- aver olur ruhuna şarkın ve cenubun; Ku...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sancag-i-serif-huzurunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağla Buzullarından Sökülmüş Zaman', 'cagla-buzullarindan-sokulmus-zaman-ethem-vayvayli-y0pjh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zaman kar fırtınalarının

akşamdan içip

yollara kadar inmesinden

kurtların öte

zaman atların öte

kandillerin,kadınların,aşkların öte

benim en beri memleketimdir

sırçadır siyah inciler içinde

ne akalga ne durağan bilemezsin

dipdiri dudakları salınır güneşle

birlikte sararan denizlerin 

en tuzlu uzaklıklarında 

en çiçeksi uyanışı koklar ilkbahar

her nefesin düşüşünde

sereserpe zamana 

zaman

sonra çağla buzullarından sökülmüş

en soğutucu yeşiller yüreğimize 

kurtarılmış tebsiler sunarken

mavi gök anlar

toprak bakır ikindilerin çoğulsu

sarılışını anımsar kolkola 

bedenbedene şehrin en kalabalık

apartman girişlerinde

sussam şimdi dirilik kalmış

o yaşanmamış duyguların içinde

bir zaman olur aslında

sulanmış meyvelerin

bir zaman heryanın 

gözlerin 

tenin

şimdi dalgın kuğular beslenir

çatılara düşen gözyaşlarınla

kaçar arkandan zaman

zaman budala yakarışlarla

sokular zümrütlerine

duydukça aklı gider

aklı kanar yangınlarda

düşer yanık bedenli gece kuşları 

köşe bucak kesilmiş çeşmelere

aydınlık gülümsemeni yaşarken

bebek

yaşarken enguvan tadında

buseye dönüşen melodiler

uykuyla karışık ağlar zaman

ağlar yarı aydınlık sahanlıkta

ey pembeler girmiş zaman

zincirlerine şebboy saklamış kız

ne kaldı ellerinde sararan zamandan

tut yücelikte devrilmiş bir saltanat

deliveren gövdesinde çakıyla kazınmış adımız

içlenmiş aşk

örselenmiş şiirler 

zaman şarabın tadında

ayrıldık zamandan böyle bir zamanda

280401', 'zaman kar fırtınalarının akşamdan içip yollara kadar inmesinden kurtların öte zaman atların öte kandillerin,kadınların,aşkların öte benim en...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/cagla-buzullarindan-sokulmus-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ressama', 'bir-ressama-hasan-akcay-0gciq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana bir sokak çiz, izbe virane

Bu öksüz şehirden öyle bir sokak

İçinde bir adam, deli- divane

Gelmez sabahlara yürüsün bırak.

Bana bir çiçek çiz, mahzun ve ölgün

Rüzgarla dalından gidecek gibi

Ufuktan ufuğa savrulduğu gün

Yeniden yeşerip açacak gibi

Bana bir kadın çiz, mahzun gözleri

Birini beklesin pencerelerde

Kurusun gözünde yaş denizleri

Ağlasın; ''o giden sevgilim nerde?!''

Ve sonra beni çiz, çizgilerde ben

Yüzüme neş''eden gölge düşmesin

Çizdiğin o kadın tutup elimden;

''Ben de senin kadar yalnızım!'' desin', 'Bana bir sokak çiz, izbe virane Bu öksüz şehirden öyle bir sokak İçinde bir adam, deli- divane Gelmez sabahlara yürüsün bırak. Bana bir çiçe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akçay']::text[], 8.5, '{"poet":"Hasan Akçay","poet_slug":"hasan-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-ressama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elsaya Şiirler', 'elsaya-siirler-louis-aragon-5o7va', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana büyük bir sır söyleyeceğim Zaman sensin 

Zaman kadındır İster ki 

Hep okşansın diz çökülsün hep 

Dökülmesi gereken bir giysi gibi ayaklarına 

Bir taranmış 

Bir upuzun saç gibi zaman 

Soluğun buğulandırıp sildiği ayna gibi 

Zaman sensin uyuyan sen şafakta ben uykusuz seni beklerken 

Sensin gırtlağıma dalan bir bıçak gibi 

Ah bu söyleyemediğim işkencesi hiç geçmeyen zamanın 

Bu durdurulmuş zamanın işkencesi mavi çanaklarda kan gibi 

Bu göz susuzluğundan sen yürürken odada 

Bense bilirim büyüyü bozmamak gerektiğini 

Daha beter seni kaçak 

Seni yabancı bilmekten 

Aklın ayrı bir yerde gönlün ayrı bir yüzyılda kalmaktan 

Tanrım ne ağırdır sözcükler Asıl demek istediğim bu 

Hazzın ötesinde sevgim hiçbir zararın erişemeyeceği yerde bugün sevgim 

Sen ki benim saat-şakağımda vurursun 

Boğulurum soluk alıp vermesen 

Tenimde bir duraksar ve yerleşir adımın 

Sana büyük bir sır söyleyeceğim Her söz 

Dudağımda bir dilenen zavallı 

Acınacak birşey ellerin için kararan birşey bakışının altında 

İşte bu yüzdendir sık sık seni seviyorum deyişim 

Boynuna takabileceğin bir tümcenin o parlakca kalp kristali 

Kaba konuşmamdan gücenme benim Bu konuşma 

Ateşte şu tatsız cızırtıyı çıkaran sudur o kadar 

Sana büyük bir sır söyleyeceğim Bilmem ben 

Sana benzeyen zamandan söz açmayı 

Bilmem senden söz açmayı bilir görünürüm 

Tıpkı uzun bir süre garda 

El sallayanlar gibi gittikten sonra trenler 

Bilekleri sönerken yeni ağırlığından gözyaşlarının 

Sana büyük bir sır söyleyeceğim Korkuyorum senden 

Korkuyorum yanın sıra gidenden Pencerelere doğru akşam üzeri 

El kol oynatışından söylenmeyen sözlerden 

Korkuyorum hızlı ve yavaş zamandan korkuyorum senden 

Sana büyük bir sır söyleyeceğim Kapat kapıları 

Ölmek daha kolaydır sevmekten 

Bundandır işte benim yaşamaya katlanmam 

Sevgilim.', 'Sana büyük bir sır söyleyeceğim Zaman sensin  Zaman kadındır İster ki  Hep okşansın diz çökülsün hep  Dökülmesi gereken bir giysi gibi ayakl...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis-aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/elsaya-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemedim', 'diyemedim-aydin-ozturk-7n5w8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yürek tükettim

Bilmem kaç dört mevsim

Diyemedim

Bir suskun haykırıştı

Ağlamaklı duruyordu içimde sevgin

Anladım ki

Değil akışına hayatın

Düşlerimiz bile 

Ayrı renklerden salınır

Ayrı ufukları heceler

Hasretim

                         (istanbul 1982)', 'Bir yürek tükettim Bilmem kaç dört mevsim Diyemedim Bir suskun haykırıştı Ağlamaklı duruyordu içimde sevgin Anladım ki Değil akışına hayatın...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diyemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolaymı?', 'kolaymi-ramazan-erdogan-l39aj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kolaymı aşkı bitirmek?

severken ölesiye...

daha başlamadan,dönmek geriye?

hani derdim ya ben hep:

-bu aşkı bitirecek biri varsa oda sensin!diye;

haklıymışım işte kahrolası,

haklıymışsın sende galiba,

kolaymış aşkı bitirmek,

severken ölesiye...', 'kolaymı aşkı bitirmek? severken ölesiye... daha başlamadan,dönmek geriye? hani derdim ya ben hep: -bu aşkı bitirecek biri varsa oda sensin!d...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kolaymi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetçi Olduk', 'gurbetci-olduk-zeki-ergin-c4zgc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'önce umudu perçinledik

yüreğimize/çelikten

sonra yaşamayı bir türkü belledik

ve koyulduk yollara

dağlar ardına

elimizde bavul

sırtımızda yatak

gurbetçi olduk', 'önce umudu perçinledik yüreğimize/çelikten sonra yaşamayı bir türkü belledik ve koyulduk yollara dağlar ardına elimizde bavul sırtımızda yat...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gurbetci-olduk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil Susar Yürek Konuşur', 'dil-susar-yurek-konusur-gassan-satar-xxvow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dil susar bazen yürek konuşur

Bazen her şey söner karanlığa bürünür de,

Sevgilinin gözlerinin parıltısı aydınlatır dünyanı.

Dudaktan çıkan kelimeler donar da,

Bir dokunus aşk sözcükleri olur sevgiliye söylenen.

Güneş ulaştıramaz ışınlarını bedenine de,

Bir bakışı olur sevgilinin seni ısıtan.

Bazen kaybolursun yaşam yolunda da,

İçten gelen tek bir gülüs tek bir gülümseme sana yol olur.

Dedim ya,

Bazen dil susar yürek konuşur

En eski dildir bu sevenler arasında hissedilen

Ve gözler, konuşan dili olur yüreğin

Tek bir bakış ömrünü dolduran bir sözcük olur o an

Gönülden gönüle ulasan en eski yoldur bu

Sadece sevenlerin bildiği

Sadece aşıktan maşuka ulaşan bir dildir bu

Tek bir bakisin dünyanı doldurduğu

Tek bir gulusun seni aşk sarhoşluğuna sürüklediği

Tek bir dokunusun tenini yaktığı dildir. yüreğin dili...

(7 Aralık 2000)', 'Dil susar bazen yürek konuşur Bazen her şey söner karanlığa bürünür de, Sevgilinin gözlerinin parıltısı aydınlatır dünyanı. Dudaktan çıkan k...', ARRAY['Türk Edebiyatı','Şiir','Gassan Satar']::text[], 8.5, '{"poet":"Gassan Satar","poet_slug":"gassan-satar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dil-susar-yurek-konusur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Dostla Sohbet', 'i-cimdeki-dostla-sohbet-gassan-satar-np4v2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oturursun tek başına dalarsın geçmişe 

Aklına gelir yaşadıkların birer birer

Sevdaların, hüzünlerin, terk edilişlerin, acılar ve sevinçlerin

Yaşanılanda kayıp olmaz bilirsin

Geçmiş ve yaşanılan sadece kazançtır öğrendiklerin adına

Her anın sana katılmıştır seni büyüterek

Nehir misalisindir aynı noktada iki kere akmayan

Nehir misalisindir ya bir çayla beslenip büyüyen

Ya da suyu ile toprağı sulayıp büyüten yeşerten

Ama hep daha büyüyen hep kazançlı olan

Suyunun eksilişiyle bile kazanç sağlayan

Ve acılar ve hüzünler hep insanı büyüten duygulardır

Sana katılan..

Seni oluşturan..

Seni büyüten..

Bak ufuklara hep erişilmez gibi gözükür

Ama bir bakışınla dolar gözlerine o ulaşılmaz görünen ufuklar

Gökkuşağının renklerine bak

Elinle tutamazsın ama yüreğinin ta en derinine islersin o renkleri

Bak gecenin karanlığına

O karanlık ki

Biraz sonraki gündoğumunun güzelliğini yaşatacak olandır

Aldırma yolunun sisine

Dağılınca o sis aydınlığın berraklığını yaşatacak olandır

Üzülme sevgilinin terk edişine

Her terk ediliş yeni bir sevgilinin

Daha çok sarılacağın sevginin kaynağıdır başlangıcıdır

unutma her şey senin içindir

yeter ki sen elini uzatıp almasını bil

korkma sevgisizlikten yeter ki sen sevmeyi bil

aç yüreğini sevgiye, insanlara..

(9 Kasım 2000)', 'Oturursun tek başına dalarsın geçmişe  Aklına gelir yaşadıkların birer birer Sevdaların, hüzünlerin, terk edilişlerin, acılar ve sevinçlerin...', ARRAY['Türk Edebiyatı','Şiir','Gassan Satar']::text[], 8.5, '{"poet":"Gassan Satar","poet_slug":"gassan-satar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/icimdeki-dostla-sohbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖZLEM', 'ozlem-siddik-altinkaynak-atjdm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O zamanlar..

Türküler,

Türkü tadında

Söylenirdi.

Bir güzeli,

Bir yiğit adamı

Anlatırdı sözleri.

O zamanlar..

Delice,

Yaşanırdı aşklar

Deli yüreklerde.

Ağıt olur,

Türkü olur

Söylenirdi dillerde.

O zamanlar..

Düşmanlık mertçe,

Dostluk,

Cömertçe sunulurdu.

Her yiğidin gönlünde,

Bir aslan bulunurdu.', 'O zamanlar.. Türküler, Türkü tadında Söylenirdi. Bir güzeli, Bir yiğit adamı Anlatırdı sözleri. O zamanlar.. Delice, Yaşanırdı aşklar Deli y...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Altınkaynak']::text[], 8.5, '{"poet":"Sıddık Altınkaynak","poet_slug":"siddik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozlem-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BALAGÖZ', 'balagoz-siddik-altinkaynak-5p55m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daldığım hülyalarda,

Gördüğüm rüyalarda,

Baktığım aynalarda

Hep sen varsın balagöz.

Ellerimin buz dağında,

Yüreğimin ocağında,

Ömrümün son çağında

Bir sen varsın balagöz.

En içten dualarda,

O güzelim anılarda,

Dinlediğim şarkılarda

Hep sen varsın balagöz.

Yşantımın anlamında,

Bu sevdanın tamamında,

Aşkın hüzzam makamında

Bir sen varsın balagöz..', 'Daldığım hülyalarda, Gördüğüm rüyalarda, Baktığım aynalarda Hep sen varsın balagöz. Ellerimin buz dağında, Yüreğimin ocağında, Ömrümün son ç...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Altınkaynak']::text[], 8.5, '{"poet":"Sıddık Altınkaynak","poet_slug":"siddik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/balagoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan-2', 'yalan-2-siddik-altinkaynak-zg3yu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice yıllar yaşadık !

Kah ağladık,kah güldük

Geçti ömrün yarısı,

Anlayamadık.

Kaçtık ölümsüz gerçekten,

Feryat !!

Bir ömür,bir yalana sarıldık.

Şan,şöhret,mevkilere

Nice yıllar harcadık

Dünyalık sevgilere,

El açıp bel bağladık.

Ölümlü sevgiliye,

Ne yürekler dağladık

Heyhat !!

Bir ömür,bir yalana ağladık.

Kabahati yok,

Geçen yılların

Kabahat yalnız,

Bihaber kulların.

Gerçeği yalanda,

İmanı karanlıkta aradık.

Ey!arşı,arzı yaradan

Affet...

Bir ömür,bir yalana aldandık.', 'Nice yıllar yaşadık ! Kah ağladık,kah güldük Geçti ömrün yarısı, Anlayamadık. Kaçtık ölümsüz gerçekten, Feryat !! Bir ömür,bir yalana sarıld...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Altınkaynak']::text[], 8.5, '{"poet":"Sıddık Altınkaynak","poet_slug":"siddik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalan-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dotlarımız', 'dotlarimiz-hazan-tekir-wndgq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi zaman bıçaklandı sırtımız

sırtımıza merhem oldu dostlarımız

keşke hiçbir zaman kopmasa

gönüldeki dostluk bağlarımız.

Sevmek güzeldir lakin hakedeni

sevdiği için ölmesini bileni

herkese güvenme kolla kendini

gözdeki yaşta aklıdır dostlarımız.

Bazen dökersin gözündeki mercanı

anlatamazsın içinde kanayan yaranı

bir yudum muhabbettir bunun dermanı

gönüllere derman olur doslarımız.

Seni sevdiğini söylüyorsa yüzüne

inanmak için bak gözüne

o zaman inanırsın tatlı sözüne

dilimizdeki baldır dostlarımız.', 'Kimi zaman bıçaklandı sırtımız sırtımıza merhem oldu dostlarımız keşke hiçbir zaman kopmasa gönüldeki dostluk bağlarımız. Sevmek güzeldir la...', ARRAY['Türk Edebiyatı','Şiir','Hazan Tekir']::text[], 8.5, '{"poet":"Hazan Tekir","poet_slug":"hazan-tekir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dotlarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendim İçin Yaşamıyorum', 'kendim-i-cin-yasamiyorum-yilmaz-guney-3hzhy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şeye rağmen düşmana inat yaşayacağız. Yarın bizim çünkü... Biz öleceğiz ama çocuklarımız bırakacağımız mirasi taşıyacaklar yüreklerinde... Ve onların yürekleri bizim altında ezildiğimiz korkuları taşımayacak........', 'Her şeye rağmen düşmana inat yaşayacağız. Yarın bizim çünkü... Biz öleceğiz ama çocuklarımız bırakacağımız mirasi taşıyacaklar yüreklerinde....', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Güney']::text[], 8.5, '{"poet":"Yılmaz Güney","poet_slug":"yilmaz-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kendim-icin-yasamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Dönümü', 'gun-donumu-ulku-subasi-k1pdf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vurdum duymaz tavırlarımda,pervasız bakışlarımda,

Gündüzlerin karanlığından,gecelerin aydınlığına,

Zaman tutmazlığın yolculuğu bu,

Ay ışık tuttu karanlığıma.

Gece bekçileri türkü söyledi,

Parmaklığın öte yanından yalnızlığıma,

İçin için yanmak neymiş anladım.

Sonra dizi dizi,en hikayeleri dinledim,

En korkulu,en coşkulu,en aşık,

Hepsi nafile,hepsi biçare.

En çok ben sevdim,ben yandım,

Yandım söndümde,sevinin eminliğinde kör gözlerim,

Bir daha böyle olursa!

Kuşku şimdi duman,kuşku şimdi barut,

Bir elimde kibrit,ağzımda sigara

Yalnızlığım ve ben.

Belki başıboşluğunda yaşamak var hayatı,

Ummadan,umursamadan olduğu gibi öylece.

Oysa benim korkum umarsız tufanımda,

Tüm öfkelerimi sindiren sessiz sabrımda,

Bir elimde kibrit,ağzımda sigara.

Vefa eski bir arkadaşımın adı,yazık ki genç öldü,

Saadet bugünlerde görünmez oldu,şimdi huzurla

Minik bir kır çiçeği kopardım doğanın göğsünden,

Kelebekler kızdı bana uçtu önümden.

Onmaz,onulmaz bir derdi,

Vurdum duymaz tavırlarımda gizledim ben.

En-en imkasızı,

Gözlerimle uçurdum gökyüzüne.

Seni dünyada unuttum,Venüs de sevdim ben.

Şimdi senin olsun tüm avuntular,

İçimde bilmem hangi duygunun esirliği var.

Ben uçurdum kanadı kırık bir güvercini özgürlüğüne,

Elimde hala kibrit,ağzımda bitmiş bir izmarit!!!', 'Vurdum duymaz tavırlarımda,pervasız bakışlarımda, Gündüzlerin karanlığından,gecelerin aydınlığına, Zaman tutmazlığın yolculuğu bu, Ay ışık t...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Subaşı']::text[], 8.5, '{"poet":"Ülkü Subaşı","poet_slug":"ulku-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gun-donumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gültanem', 'gultanem-ulku-subasi-6hjk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yenildim gültanem

Özgürlüğümü sessizliğimde yaşadım

Sevgiye doğdum güzelliğinle

Dokunamadım omzuna

Yenildim

Sensiz sessiz ağladım.

Heyecanı,çoşkuyu,ızdırabı

Gözlerinde tanıdım

Yutkundum

Konuşamadım

Yenildim birtanem

Gözlerine ağladım.

Yalnızlığıma karşı

Karıştım kalabalığa

Her yerde hareket

Her şeyde renk

Ne güzel şey ahenk

Dalda bir kuş

Çiçekte böcek

Yaşamak...Hareket...

Unutamamak

Unutamamak o çocukca sevgiyi

Hatırlamak o güzel esintiyi

Bunca yılın ardından

Özlemek ne zor nurtanem

Yeni güne seninle doğmak

Yeni günde seninle ölmek

Sensiz sessiz ağlamak

Çok zor gültanem.', 'Yenildim gültanem Özgürlüğümü sessizliğimde yaşadım Sevgiye doğdum güzelliğinle Dokunamadım omzuna Yenildim Sensiz sessiz ağladım. Heyecanı,...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Subaşı']::text[], 8.5, '{"poet":"Ülkü Subaşı","poet_slug":"ulku-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gultanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayıs', 'mayis-sabahattin-ali-uuyzm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mayıs, ayların gülüdür, 

 taze bir çiçek dalıdır, 

 İçerim ateş doludur; 

 Mayıs‘ta gönlüm delidir. 

 Yeşil dağlara göçülür, 

 Kırmızı şaraplar içilir; 

 Yarim dökülüp saçılır, 

 Mayıs‘ta gönlüm delidir. 

 Göklere karşı yatılır, 

 Dertlerimiz unutulur; 

 Eski sevgiler atılır; 

 Mayıs‘ta gönlüm delidir. 

 Uzakta kuşlar seslenir; 

 Gönlüm genişler beslenir; 

 Yaşamağa heveslenir, 

 Mayıs‘ta gönlüm delidir. 

 Yumuşak rüzgarlar eser; 

 Çimenlerde yarim gezer, 

 Yanılır, bana gülümser; 

 Mayıs‘ta gönlüm delidir.', 'Mayıs, ayların gülüdür,   taze bir çiçek dalıdır,   İçerim ateş doludur;   Mayıs‘ta gönlüm delidir.   Yeşil dağlara göçülür,   Kırmızı şarap...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali']::text[], 8.5, '{"poet":"Sabahattin Ali","poet_slug":"sabahattin-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Şarkıları', 'yagmur-sarkilari-ridvan-canim-z0wq4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şarkımıdır yaşamak 

yoksa bir hüzünmüdür

en yağmurlu gecelerden arta kalan

bazan yürek dolusu sevmekmidir birilerini

dalından koparılmış bir yaprağın ardından

koşmak belkide

kimbilir belkide ıslanmaktır / umarsızca

ince ince yağan bir yağmurun kollarında....

                                                                                                         Bazan en lirik bir gazelmidir yaşamak

bir kaşı kara,bir saçı kara , kirpiği kara 

ve illâ gözü karanın                                                          

en deli yağmurlarına tutulmakmıdır yaşamak

yoksa

bir minyatürün gözlerinden dökülen

kara bir gecenin ortasında

yapayalnız kalmakmıdır yaşamak....

Yüreğinde eylül güneşleri taşırken birde

bir kervansaray avlusunda

gölgesini yitirmiş içi boş çınarlar altında

Hüsn ü Aşk kadar muhayyel

bir sevda düşünde

ve mumdan bir gemiyle ateşten bir denizi 

geçmekmidir yaşamak......

Bazan göllere yağan bir yağmurdur yaşamak

bakarsın kıyıya vuran yalnızlık

ve bazanda en deli yağmurlarda 

bir çift kara gözü

sandalsız ve küreksiz geçebilmektir 

yaşamak..

Ve

sonra yağmur şarkıları söylemek

birde gülümseyebilmekhayata rağmen

güneşli ama yağmurlu bir günde

dahası

kutsal kitaplar adına

yeşil kanatlı yağmur kuşları adına

bir çift siyah göz hatırına

en önemlisi söylenemeyen şiirler hatırına

leyl ü nehâra katlanmak belki de

yaşamak dediğimiz şey...', 'Bir şarkımıdır yaşamak  yoksa bir hüzünmüdür en yağmurlu gecelerden arta kalan bazan yürek dolusu sevmekmidir birilerini dalından koparılmış...', ARRAY['Türk Edebiyatı','Şiir','Rıdvan Canım']::text[], 8.5, '{"poet":"Rıdvan Canım","poet_slug":"ridvan-canim","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yagmur-sarkilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Güzeli', 'yagmur-guzeli-yavuz-bulent-bakiler-oibf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlar yağmıyor mu inceden ince

Rüzgarlar esmiyor mu serince

Bir sigara yakıyorum efkarlanarak

Çıkıp karşıma sen geliyorsun

Saçların ıslanmış oluyor

“Gel” diyorum duymuyorsun beni bir türlü

Seni böyle hayal meyal yaşamak çok zor

Uzanıp tutsam diyorum incecik ellerinden

Ellerim boşlukta kalıyor.

Bir gün çıkıp gideceksin 

Sonra arkandan yine ince bir yağmur yağacak

Cadde cadde,sokak sokak 

Sayıklar gibi dolaşıp seni arayacağım

Beni bir köşe başında ağlıyor bulacaklar. 

Saklamak zor olacak,çaresiz kalacağım

Seni sevdiğimi anlayacaklar.

Üstüme yağmurlar yağacak 

İnce bir dal gibi birden kopup kırılacağım

Kaldırım taşlarında sıcaklığım kalacak

Kahrolacağım.

Bu şiiri yağmur yağarken yazdım

Ezanlar okunuyordu minarelerden

Seni düşünmeseydim yağmurlu havalarda

Sokaklara çıkmayı göze almazdım.

Melul mahzun dolaşmazdım akşam karanlığında,

Duraklarda yapayalnız kalmazdım.

Yağmurlar yağmıyor mu inceden ince

Rüzgarlar esmiyor mu serince

Bir sigara yakıyorum efkarlanarak

Çıkıp karşıma sen geliyorsun

Saçların ıslanmış oluyor

“Gel” diyorum duymuyorsun beni bir türlü

Seni böyle hayal meyal yaşamak çok zor

Uzanıp tutsam diyorum incecik ellerinden

Ellerim boşlukta kalıyor.', 'Yağmurlar yağmıyor mu inceden ince Rüzgarlar esmiyor mu serince Bir sigara yakıyorum efkarlanarak Çıkıp karşıma sen geliyorsun Saçların ısla...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yagmur-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkımın Bestesini', 'sarkimin-bestesini-sair-baraka-w8bvf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şarkımın bestesini

çalarınıda gönder ki

çalayım her dem 

seni andıkça bende

göreyim heran sendeki 

sevgimin ben den 

nasıl sana geldiğini 

sual edelim 

ne olur 

bir an olsun ki 

o maharet o hüner 

o ne imiş ki 

sende benden saklı 

bir ben bilenim dindi

bende raks edeyim 

nice yunuslarla 

ta nusrat sarhoşluğuna

mirimin batağına 

sana 

akan sendedir 

aslım ki 

koru onu emi 

ki varolasın 

her daim 

gönlümde 

bir benle 

benden içerü 

ya o nura ya şada 

deyu deyu

hür met ede şükr ede

ya aşka ya sukuda

ya hazret ya velede

ya bada ya duda

ya hu ya hu

deyu deyu

hem senden

hem sende

ben alin

ya hu ya dur

des te dur

ya hu ya hu

cicimhazretime......

barakadan', 'Şarkımın bestesini çalarınıda gönder ki çalayım her dem  seni andıkça bende göreyim heran sendeki  sevgimin ben den  nasıl sana geldiğini  s...', ARRAY['Türk Edebiyatı','Şiir','Şair Baraka']::text[], 8.5, '{"poet":"Şair Baraka","poet_slug":"sair-baraka","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sarkimin-bestesini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Alıp Satıcı Gönül', 'bir-alip-satici-gonul-enver-gokce-6k27x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düştüm bir öylesi çekilmez derde,

Ne ölümü düşünürdüm, ne yaşamak korkusu,

Ne sır aradım herşeyde, ne gariplik var serde,

Ne kara sevda, ne sevmek ne sevilmek arzusu

Artık her şarkı dokunur bana bu şehirde.

Hasret nedir bilmezken o kadar

Şimdi, her an, her yerde gurbetteyim.

Çünkü daha görmediğim güzellikler var,

Öyle bir yürek koymuşlar ki içime neyleyim,

Her yere gönlümü vermeden geçemem dostlar! 

Ben deli miyim bilmem mi neler ettiğimi.

Bir han köşesinde yatmayınan Kerem diyorlar,

Ne tuhaf bu insanlar derdini dökmeyinen

Çaresiz derde bulunmaz merhem diyorlar,

Ah.. bir alıp satıcı gönlüm var gezer çarşı çarşı,

Başım güneşe düşmüş yanmayı öğrenir.

Nolur böyle duradursun cama güneşe karşı,

Gönül her yerde bir kardeşim güzel her yerde bir..', 'Düştüm bir öylesi çekilmez derde, Ne ölümü düşünürdüm, ne yaşamak korkusu, Ne sır aradım herşeyde, ne gariplik var serde, Ne kara sevda, ne ...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-alip-satici-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yozgat', 'yozgat-sukru-erbas-e0m0c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yozgat bir kar kentidir

Sürmeli bir türküdür

Serttir soğuktur küçüktür.

İki dağın dudağına kısılmış

İncecik bir sudur

İçinde zamandan başka herşeyin aktığı...

Güneşi bir nazlı konuktur yazlar içinde

Ömrü çiçeklerin rengi kadardır.

Ağaçları çatılardan yüksek

Avluları evlerinden geni
..........
..........', 'Yozgat bir kar kentidir Sürmeli bir türküdür Serttir soğuktur küçüktür. İki dağın dudağına kısılmış İncecik bir sudur İçinde zamandan başka ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yozgat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir Ölüyor', 'bu-sehir-oluyor-vedat-sumbul-cvgso', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinin yangın yerinde 

Hastalıklı bir şubat akşamı can veriyor...

100.Yıl Bulvarı''nda fahişeler,

Yalancı gülüşlerle sevgili oluyor

Akşam zamparalarına...

Bu şehir ölüyor...

Ölse ağlayanı olur mu bilmem;

Ama sevgilerimizin,

Hüzünlerimizin şehri,

Yağmurlarında ıslandığımız şehir

Ölüyor, ihmal edilmiş şubat akşamlarında...

Barlarda haber (!) kovalayan gazeteciler,

Bar kapılarındaki çiçekçi çocukları

Görmezden geliyorlar.

Bu şehir ölüyor...

Bu şehir ölüyor ;

Çünkü tükendi mavisi.

Ve hiçbir şehir mavisiz yaşayamaz...

Aşkımızın Kır Kahvesi''nde 

Bir ölümlük mavi kaldıysa hala,

Uykusunda oğlumun yanagına

''UMUT'' yazabilirim,serçe parmağımla

Ve oğlum ,

Tahir''le Zühre Meselesi''ni okuyabilir babasına...

Şimdi şurda bir cinayet işlemek de varken

Bir çiçekçi çocuğun tüm çiçeklerini satın alıyorum,

Gidip umuda uyusun diye anasının kokusunda...

Hep böyle git çocuğum,umutlu...

Ve her gidişinde yine böyle

Dolmuş camlarının buğusunu silip 

Gülümse bana...

Çünkü tükeniyor bu şehir

Ve belki de senin gülümsemen kurtaracak

Hüzünlerimizin şehrini...

Ey aşklarımızın betonarme şehri !

Ölüyorsun mavisizlikten...

Kimbilir, belki de bir sıkımlık canını

Kendi öz apartmanların alacaktır.

Dolunaylarında gidenlerin ardından

Şiirler okuduğumuz şehir ölüyor...

UYANSANIZA !...', 'Gözlerinin yangın yerinde  Hastalıklı bir şubat akşamı can veriyor... 100.Yıl Bulvarı''nda fahişeler, Yalancı gülüşlerle sevgili oluyor Akşam...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sümbül']::text[], 8.5, '{"poet":"Vedat Sümbül","poet_slug":"vedat-sumbul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bu-sehir-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Deseydin', 'gel-deseydin-hasan-akcay-e97s1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimi yıllır yılı yakan sevda ateşi

Söner, güle dönerdi eğer sen dileseydin

Tükenirdi ömrümün bu sonsuz bekleyişi

Bana gönül sesinden bir kere gel deseydin

Ayaklarında deniz, yakanda gül olurdum

Sana senin yanında istesen kul olurdum

Razıydım yaksan bile, yolunda kül olurdum

Bana gönül sesinden bir kere gel deseydin.', 'Kalbimi yıllır yılı yakan sevda ateşi Söner, güle dönerdi eğer sen dileseydin Tükenirdi ömrümün bu sonsuz bekleyişi Bana gönül sesinden bir ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akçay']::text[], 8.5, '{"poet":"Hasan Akçay","poet_slug":"hasan-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-deseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demek Sen De Gidiyorsun', 'demek-sen-de-gidiyorsun-atilgan-alemdar-jodal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'demek sen de gidiyorsun ve de gece yarısı

daha önce gitmiş gibi avuntu bırakmadan

demek sen de gidiyorsun yüreğime sormadan

san ki çare bitmiş gibi yokmuş gibi sonrası 

hayâllerimi ver de git seninkiler yalanmış

sıcaklığını unutmak yıllarımı alsa da 

gidiyorsun işte git bende izin kalsa da

en büyük acılar bile takvimlerle bitermiş

zamana kaldı yüreğim yani mahşer gününe

avunmak harcım değildir ölümüm aşktan olsun

üstelik belli gibiydi sonunda gidiyorsun

tam da veda ediyorken rakıya ve tütüne

alışırım bu derde git senin gemin yanaşmış

sigaram korkarak yansa ve gözlerim dolsa da

biliyorsun işte git ben kolay ağlarım ya

hem malûm: limanlarda terkedilenler ağlarmış

kahır, gelişindi zaten gül koklamak neyime

benim ömrüm baştan sona sonbahara kapalıydı

saniyeler teker teker acılara tapuluydu

çare olamazdın elbet bu devasa derdime

buluşuruz mahşerde git aşklar yarım kalmazmış

dudağından eksik bir tad yanağımda kalsa da

bitiyorsun işte git yüzün hüzün olsa da 

uzatma , vedalar hiç hafızadan çıkmazmış

körler gibi sevmiştim ben seni hiç tanımadan

tapar gibi dokunurdum günahından korkmadan

oysa şimdi gidiyorsun tüm diğer düşler gibi

sadece

bir mahşer farkı bırakarak alnımın yazısına

demek sen de gidiyorsun bu son olur demiştim

aslında ben şimdi değil sen sevince ölmüştüm', 'demek sen de gidiyorsun ve de gece yarısı daha önce gitmiş gibi avuntu bırakmadan demek sen de gidiyorsun yüreğime sormadan san ki çare bitm...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/demek-sen-de-gidiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-vasif-senturk-f7emg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretinle yağmur olan gözyaşlarımın

Tek damlası üstüne düşsün istemem

Gönlümde kopan fırtınanın rüzgarı

Saçının tek telini üzsün istemem

İstemem

Buğulansın gözlerin

İstemem 

Titremesin dizlerin

Hep sevgiyle an beni

Unutmanı istemem

Seni görmek istememem 

Seni sevmiyorum değildir

Seni çok seviyorum

Kaybetmek 

İstemem', 'Hasretinle yağmur olan gözyaşlarımın Tek damlası üstüne düşsün istemem Gönlümde kopan fırtınanın rüzgarı Saçının tek telini üzsün istemem İs...', ARRAY['Türk Edebiyatı','Şiir','Vasıf Şentürk']::text[], 8.5, '{"poet":"Vasıf Şentürk","poet_slug":"vasif-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Değilmidir', 'guzel-degilmidir-dilek-demir-3umaf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevği ve sayğιya karşιlιk vererek hayatιmιza neşe katsak

Bütün güzellikleri kötüye kullanmadan dahada çok güzelleştirsek

Içimizdeki sevinci, yüreğimizdeki mutluluğu paylaşarak

Varsayιmlarda bulunmadan, insanlarιn kalblerini kιrmadan

Güzel bir dünyada yaşamak, daha güzel değilmidir?

Birbirini suçlamadan, herkesin hepbirlikte yaşayabileceği

Var olanlarι yok etmeden güzel mekanlar oluştursak

Hayatιn kιymetini, insanlarιn değerini

Kardeşliğin, dostluğun bir olduğu yerde

Verebileceğinin en güzelini vermek, daha güzel değilmidir?', 'Sevği ve sayğιya karşιlιk vererek hayatιmιza neşe katsak Bütün güzellikleri kötüye kullanmadan dahada çok güzelleştirsek Içimizdeki sevinci,...', ARRAY['Türk Edebiyatı','Şiir','Dilek Demir']::text[], 8.5, '{"poet":"Dilek Demir","poet_slug":"dilek-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guzel-degilmidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marifet', 'marifet-vasif-senturk-pwnyn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir amacın var mı?

Mutluluğu bulmak gibi

Bir beklentin var mı?

Sonsuza ermek gibi

Cesaretin var mı?

Uğrunda ölmek gibi

Dertlerin var mı?

Hüzünle gülmek gibi

Marifetin var mı?

Aşkımı bilmek gibi

           Mersin-05.01.1995', 'Bir amacın var mı? Mutluluğu bulmak gibi Bir beklentin var mı? Sonsuza ermek gibi Cesaretin var mı? Uğrunda ölmek gibi Dertlerin var mı? Hüz...', ARRAY['Türk Edebiyatı','Şiir','Vasıf Şentürk']::text[], 8.5, '{"poet":"Vasıf Şentürk","poet_slug":"vasif-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/marifet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bu Sensizlik Yok mu', 'ah-bu-sensizlik-yok-mu-ozcan-nevres-lxbtf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam oldu yine,

 Karanlık çökerken kentin üstüne,

Ayaklarım beni sürüklüyor yine 

Kırık Çatal meyhanesine.

Ah... ah bu sensizlik yok mu?

Seni unutmak için

Seni içeceğim kadehlerden

Ve yitik umutlarımı

 Meze yapacağım içtiklerime.

Doyasıya içeceğim bu gece.

Alkolün uyuşturduğu beynimde

Sisler oluşacak,

Seni hapsedeceğim o sislerin içine.

Umut bu ya,

Haykıracaksın var gücünle,

Boğuluyorum, kurtar beni diye.

Daha, daha içeceğim,

Sisleri daha da yoğunlaştıracağım.

Belki de seni sislerin içinde,

Yitik umutlarımla birlikte boğacağım.

Seni tümden kaybetmenin hüzünü çökecek içime.

Bu kez de yokluğuna ağlayacağım uzun uzun. 

Göz yaşlarımı fark edecek sarhoşun biri.

Gelip sarılacak boynuma,

 Onun da gözleri yaşlı.

Çökecek yanı başımdaki sandalyeye,

Bağıracak meyhaneciye peltek peltek,

Getir bize bir ufak daha.

Beraber içeceğiz.

Yitikliğimizi, dertlerimizi anlatacağız biri birimize. 

Hesabı getirdiğinde meyhaneci,

O özür dileyip gidecek.

Dertlerime dert kattığı dertleriyle birlikte,

Hesabı ödemekte bana kalacak.', 'Akşam oldu yine,  Karanlık çökerken kentin üstüne, Ayaklarım beni sürüklüyor yine  Kırık Çatal meyhanesine. Ah... ah bu sensizlik yok mu? Se...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ah-bu-sensizlik-yok-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdeki Sevgiliye', 'hayalimdeki-sevgiliye-ozcan-nevres-gj94k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim hayalimdeki

 Tanımadığım sevgilimsin. 

Üstelik vefasızsın da.

Bilir misin seni nerelerde aradığımı?

Sen bazen gönlümde sım sıcak bir sevgi,

Bazen gözlerimde göz yaşı seli,

Bazen kalbimi burkan, acıtan bir sızı.

Bazen de arzu, kin ve intikamsın.

Seni gecenin bir yarısında,

Ip ıssız ve karanlık yollarda

Bazen de kumsalı döven,

Hırçın dalgaların serinliğinde

Ve gecenin bilmem kaçıncı saatinde,

Denizdeki yakamozlarda arıyorum.

Gecenin ilerlemiş bir saati,

Her taraf derin bir uykuda.

Bense karanlıklar içinde,

Benim olmayan bir dünyada,

Uykusuz ve umutsuz,

Yakamozlarda şekillenen hayalinin esiri

Bir garip aşık.

Yeşil gözlerin gel diyor bana.

Koşup gelmek istiyorum sana.

Kahkahalar atarak kaçıyorsun.

Aşkımla alay ediyorsun.

Gözlerimde yaş, kalbimde acı,

Terk ediyorum sahili.

Bir sahil gazinosunda,

Çam ağaçlarının koyu gölgesinde,

Köpüklü dalgaların dövdüğü sahilinde

Seni unutmak için içiyorum.

Komşu masalardan kahkahalar yükseliyor.

Yüksek sesle müziğe eşlik ediyor.

Bense acılar içinde, içim parçalanırcasına.

Kadehim yere çarpıyorum, çıldırmışçasına

Kadehimin tuz buz olmuş parçacıklarında,

Yine sen varsın param parça.

Toplayıp bir bütün etmek istiyorum seni.

Toplayamıyorum, ellerim kan içinde.

Çıkıp gidiyorum, yitik umutlarım peşimde.', 'Sen benim hayalimdeki  Tanımadığım sevgilimsin.  Üstelik vefasızsın da. Bilir misin seni nerelerde aradığımı? Sen bazen gönlümde sım sıcak b...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hayalimdeki-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüş Günü Konuşması', 'gorus-gunu-konusmasi-kemal-ozer-vmikt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oğul ben senin görüş gününe

dağları devşirerek geldim

-bizim oranın dağlarını-

sevincimi ırmaklarda arıtarak

-bizim oranın ırmaklarında-

sabah yeliyle örerek saçlarımı

-bizim oranın sabah yeliyle-

o şimdi özlemiştir dedim

sesimi bizim oranın

çiçeklerine değdirerek geldim:

                          Nasılsın?

İşte yıllardan sonra oğul

yüz yüzeyiz yine seninle

aramızda duruyorsa bu telörgü

sen de benim alnıma bakmalısın

dağılana dek birer birer bulutlar

görünene dek bizim oradan

senin için taşıdığım gökyüzü.

Bu telörgü durduramaz çünkü

ne senin bakışını ne benim

yeter ki gözlerimiz susmasın:

                           Nasılsın...

Oğul ben senin görüş gününde

ninniler söylemeyi isterdim

-avutmak için uykusuz gecelerini-

türküler söylemeyi isterdim

-düğününe sakladığım türküleri-

nice ağıtlar düğümlendi boğazımda

-birer harman yangınıydı her biri-

söylemeyi isterdim yasak olmasa

bana kendi dilimizi kullanmak.

Ama bu da durduramaz oğul

ne senin söyleyeceğini ne benim

yeter ki bir tek sözcüğe sığsın:

                           Nasılsın!

Bir tek sözcükle alırım ellerini elime

-üşüdükçe ovalayıp ısıtmak için-

bir tek sözcükle basarım bağrıma seni

-en öksüz saatinde kuşluk vaktinin-

bir tek sözcükle duyururum öğütümü

-gördüğün zulum mayanı berkitsin-

bir tek sözcükle ulaşır sana dileğim

-gün devrilsin ama sen devrilmeyesin-

boşuna bunca zulüm,bunca yasak ve engel,

onları aramıza koyanlar utansın:

                           Nasılsın?!', 'Oğul ben senin görüş gününe dağları devşirerek geldim -bizim oranın dağlarını- sevincimi ırmaklarda arıtarak -bizim oranın ırmaklarında- sab...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gorus-gunu-konusmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '_ Farkında Mısın?', 'farkinda-misin-cengiz-numanoglu-vqt2r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beşerin temeli, bir küçük cenin,

Can vermeye gücü yetmez kimsenin,

Kâinat denilen, dev değirmenin,

Suyu nerden gelir, farkında mısın? 

Yıldızlar bir adım yolundan şaşmaz.

Dağlar haddin bilir, denizler taşmaz.

Karıncanın yükü, boyunu aşmaz.

Bunca dengelerin, farkında mısın? 

Bu dünya, uzunca bir yolun başı,

O mezar dediğin, bir sınırtaşı,

Ömür, iki günlük îman savaşı,

Her an bitebilir, farkında mısın? 

Senin sahibin var, yokluğa kanma,

Sana senden yakın, uzakta sanma,

O''na tüm kâinat, dar gelir amma,

Bir gönüle girer, farkında mısın? 

Cehâlettir, O''nu inkâr nedeni,

Ne mümkün görmemek, O var edeni,

Beyin yönetirken, bütün bedeni,

Beyni kim yönetir, farkında mısın? 

Etrafına bir bak, gör nicesini,

Gel de çöz, şu insan bilmecesini,

Bazen, ömür bile, tek hecesini,

Çözmeye yetmiyor, farkında mısın? 

Kimi, kibir denizinde boğulmuş,

Kimi, minnet ile, kula eğilmiş,

İnsan olabilmek, kolay değilmiş,

O kutsal savaşın, farkında mısın? 

Kimi, servetini, sefâya sermiş,

Kimi zekâtını, dürüstçe vermiş,

Kimi, bir lokmanın, şükrüne varmış,

Gerçek zenginlerin, farkında mısın? 

Kimi, imân eden, kula çatarken,

Korkulara düşer, güneş batarken,

Kimi, ona buna, akıl satarken,

Kendisi muhtaçtır, farkında mısın? 

Kimi, şans ve talih peşinden gider,

Durmadan kadere sitemler eder,

Böylesi kullara, neylesin kader? 

Ekmeden biçen yok, farkında mısın? 

Ömürler, mevsimler gibi dönerler,

Mumlar, yanar yanar, biter sönerler,

Yapraklar, sararıp, yere inerler,

Toprağa dönerler, farkında mısın? 

''''Aşk'''' sözcüğü, günümüzde karmaşa,

Aşklar var, bir gaflet, bir kara maşa,

Ama, bir aşk var ki; gelince başa,

Ölüm kavuşmaktır, farkında mısın? 

İnsanlar, el ayak, kol, kafa, beden,

Hiçbiri birine benzemez neden? 

Bir güç, bir irâde var ki, hükmeden,

Dört yanını sarmış, farkında mısın? 

Gece gündüz, boş hayaller kurarsın,

Kendi gafletine ortak ararsın,

Çıkmaz sokaklarda, adres sorarsın,

Oysa, adres sende, farkında mısın? 

Yaşamak, kalbine korku salarken,

Ümitsizlik batağına dalarken,

Teselliyi, kadehlerde ararken,

Seni Yaradanın, farkında mısın? 

Nice güzel renkler, dünyayı sarmış,

Siyahın yanında, beyaz da varmış,

Parmakların, kalem tutar, yazarmış,

Elin, kolun varmış, farkında mısın? 

Pembe beyaz açan bahar dalını,

Mor dağların, yeşilini, alını,

O kelebeklerin, ipek şalını,

Gören gözün varmış, farkında mısın? 

Sonsuzların bile, ömürleri var,

Sanma ki, saltanat, kurumaz pınar,

Mal, canın yongası olsa ne çıkar? 

Gölgeler fânidir, farkında mısın? 

Yorgun yüzlerdeki, derin izlerde,

Sevgiye susamış, muhtaç gözlerde,

Boğazlara düğümlenen sözlerde,

Ne feryatlar gizli, farkında mısın? 

İlaçtan çok, dost gerekir hastaya,

O dost yazılır, yüce listeye,

Bir gönül köprüsü, kuran ustaya,

Ücreti kim verir, farkında mısın? 

Tatlı dil, güçlüdür, demir çelikten,

Yılan bile duymuş, çıkmış delikten,

İnsanlara özgü, bu incelikten,

Kimler hisse almış, farkında mısın? 

Namus şeref derler, elle tutulmaz,

Şan şöhretle, para pulla satılmaz,

Kumar çöplüğüne, asla atılmaz,

Atıp satanlar var, farkında mısın? 

Eğer varsa kulda, vicdan yarası,

Karışır, servetin akla karası,

İnsan ömrü, iki nefes arası,

Kaç adımlık yoldur, farkında mısın? 

Sen, fakir arkadaş, düşünme derin,

Bin türlü derdi var, o zenginlerin,

Darılıp küstüğün, kendi kaderin,

Sana siper olmuş, farkında mısın? 

Dinle ki, genç ana, bu sözler sana,

Böyle yazdım diye, darılma bana,

O yavrun sevgiden, şevkatten yana,

Biraz aç görünür, farkında mısın? 

Aklı tutsak eden, dar sınırları,

Geç de gör, âlemde nice sırları,

Yazan, yazmış amma, bu satırları,

Neden, niçin yazmış, farkında mısın? 

(1989)', 'Beşerin temeli, bir küçük cenin, Can vermeye gücü yetmez kimsenin, Kâinat denilen, dev değirmenin, Suyu nerden gelir, farkında mısın?  Yıldı...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Numanoğlu']::text[], 8.5, '{"poet":"Cengiz Numanoğlu","poet_slug":"cengiz-numanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/farkinda-misin-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mâra', 'm-ra-asaf-halet-celebi-jbgeh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilmemek bilmekten iyidir

düşünmeden yaşayalım

mâra

günü ve saatleri ne yapacaksın

senelerin bile ehemmiyeti yoktur

seni ne tanıdığım günleri hatırlarım

ne seneleri

yalnız seni hatırlarım

ki benim gibi bir insansın

tanımamak tanımaktan iyidir

seni bir kere tanıdıktan sonra

yaşamak acısını da tanıdım

bu acıyı beraber tadalım

mâra

başım omuzunda iken sayıkladığıma bakma

beni istediğin yere götür

ikimiz de ne uykudayız

ne uyanık', 'bilmemek bilmekten iyidir düşünmeden yaşayalım mâra günü ve saatleri ne yapacaksın senelerin bile ehemmiyeti yoktur seni ne tanıdığım günler...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-dilaver-cebeci-k06ah', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sukut etsin perisan zulf soyleyen dudag olsun

Bu sinem uzre anin lebleri her dem du dag olsun

Tebessum eyleyub baran doker sahra-yi sevdama

Bulutlar her gece habgahi,seyrangahi bag olsun

Haberdar olmasin varsin benim pinhan sirisgimden

Bu nademsaz gonul ardinca seyreden ayag olsun

Dokup giysularin gecsin guzergah-i bahtimdan

Niyazimdir guzel basi belalardan irag olsun

Dilaver razi olmustur uzaklardan temasaya

Yeter ki husnu var olsun ve sirin cani sag olsun', 'Sukut etsin perisan zulf soyleyen dudag olsun Bu sinem uzre anin lebleri her dem du dag olsun Tebessum eyleyub baran doker sahra-yi sevdama ...', ARRAY['Türk Edebiyatı','Şiir','Dilaver Cebeci']::text[], 8.5, '{"poet":"Dilaver Cebeci","poet_slug":"dilaver-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gazel-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İltica', 'i-ltica-dilaver-cebeci-kr7h4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurşun benizli bulutlar gelir ufuklardan,

Sıkar üstümüze gömleklerini.

Çılgın bir sağanak vurur bahçemin güllerini,

Arsız böcekler yapraklara sığınır,

Ben sana…

Uyanır denizlerin bahadır askerleri,

Göklerse davranır kılıçlarına,

Ateşler düşer dervişimin avuçlarına,

Sefineler kaçışır, limanlara sığınır,

Ben sana…

Masal kaçkını devler gezinir şehirlerde,

Kenetlenmiş sarı seyrek dişleri.

Söner birden bebeğimin pembe gülüşleri,

Ürperir örümcekler, ağlarına sığınır,

Ben sana…

Uğultular gelir geceleri koyaklardan,

Rüzgârlar eser İsrafil nefesi.

Çatırdar tutsak ruhumun çürümüş kafesi,

Doruklarda kartallar kayalara sığınır,

Ben sana…

Güneş kanlar içinde yavaş yavaş boğulur.

Karanlık kuşanır pusatlarını

Titretir bozkırların başıboş atlarını

Yıldızlar uzakta Kehkeşan''lara sığınır

Ben sana sığınırım...', 'Kurşun benizli bulutlar gelir ufuklardan, Sıkar üstümüze gömleklerini. Çılgın bir sağanak vurur bahçemin güllerini, Arsız böcekler yapraklar...', ARRAY['Türk Edebiyatı','Şiir','Dilaver Cebeci']::text[], 8.5, '{"poet":"Dilaver Cebeci","poet_slug":"dilaver-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/iltica-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaz Sabahı', 'bir-yaz-sabahi-cagdas-cirak-0i3ko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç dinledinmi dalgaların sesini 

Sen hiç düşündünmü yaz akşamı sevgilinle beraber olmayı

Sen hiç düşündünmü yalnızlık insana neler yaptırır

Sen hiç düşündünmü martılar neden uçar 

Sen hiç düşündünmü geride kalan hayatını 

Sen hiç düşündünmü bizlerin hayatını 

Sen hiç düşündünmü bizler neden aşık oluruz

Sen hiç düşündünmü bir aşksız  bir yaz gününü

Sen olmazsan günler geçmiyor

Çünkü sen  benim alın yazımsın.

Çünkü bu hayata senle başladım ve senle veya sensiz bitecek

Ama artık düşünemezsin çünkü yalnız kalmadın kalamazsın.

Ben senim sende ben.artık yeter  tanrım çektiğim azap.', 'Sen hiç dinledinmi dalgaların sesini  Sen hiç düşündünmü yaz akşamı sevgilinle beraber olmayı Sen hiç düşündünmü yalnızlık insana neler yapt...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Çırak']::text[], 8.5, '{"poet":"Çağdaş Çırak","poet_slug":"cagdas-cirak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-yaz-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündüm...', 'dusundum-melek-menekse-stio8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman, daima su gibi akip geçen

Vakitleri tüketen zaman, tükenmez oldu

Saatlerce, dakikalarca, saniyelerce

Degerlendirip, yasadigim anilar

Sanki sadece bir hayalmis gibi

Karsima dikilir oldu

Her zaman, içimde, beni bir çocuk gibi costuran sevgi

Son günlerimde beni yikar oldu

Düsündüm... çok düsündüm

Eski çilginligim, coskum, hayatdolu günlerim

Geri gelirmi diye

Benle eskisi gibi sinirsiz ilgilenip

Tekrar delice severmisin diye

Düsündüm... döktügüm yaslar

çilginca çocuksu sevince tekrar dönermi diye

Düsündükçe içimin burkuldugunu

Içimden sanki birseylerin koptugunu hissettim

Ama herseye ragmen, bir umut var

Hafif bir meltemin usulca esip

Defalarca ''seni seviyorum'' fisildamasi

Sadece... seni seviyorum...', 'Zaman, daima su gibi akip geçen Vakitleri tüketen zaman, tükenmez oldu Saatlerce, dakikalarca, saniyelerce Degerlendirip, yasadigim anilar S...', ARRAY['Türk Edebiyatı','Şiir','Melek Menekşe']::text[], 8.5, '{"poet":"Melek Menekşe","poet_slug":"melek-menekse","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-ozcan-nevres-7ugmv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖZLEYİŞ

Özledim bağlarımızın tozlu yollarını.

Özledim yaz günlerinin yakıcı sıcağını,

İçimi kavuran susuzluğumu giderdiğim,

Tulumbamın buzu aratmayan suyunu.

Ne güzel günlerdi o günler.

Nerede kaldı dalından kopardığım meyveler.

Kendi elimle yetiştirdiğim sebzeler. 

Bir düş müydü o günler bilmiyorum.

Çocukluğumun en güzel günleriydi,

Sıcaktan kavrulduğumuz o yaz günleri.

Yoldan geçen devecilere bağırırdık,

Aşçı Mehmet’i gördün mü diye.

Kalaylanmadık yerimiz kalmazdı. 

Hayır için yol boyundaki su küpüne,

Kum atardık oyun olsun diye.

Susuzluktan yandığımızda,

Biz içerdik o bulanık suyu yine. 

Çukur açardık yoldaki araba izine.

Üstünü çalılarla yapraklarla örterdik.

Ve oturup beklerdik, çukura kim batacak diye. 

Çukura düşünce bir arabanın tekeri,

Bayram ederdik, uzaktan seyrederdik,

Tekeri kurtarmak için neler çekildiğini.

Nemli bir yeri eştiğimde,

Duru bir su kaynadığını gördüğümde,

Koşarak babama muştulamıştım.

Evimizin önündeki sebze bahçesini,

Benim olan suyla sulayacaktık. 

Boşuna sevinme dedi babam.

O su, sulama kanalından geliyor.

İnanmadım, tükenmez bir kaynakmış gibi

Su yolları açtım. 

Kanal bekçileri suyumun kaynağı,

Köstebek deliğini kapayınca,

Suyum yok oldu umutlarımla birlikte.

Kuş yuvaları arardım ağaçlar üstünde. 

Bazen de bulurdum çalılıklar içinde.

Yavruların büyümesini beklerdim umutla. 

Bir gün baktığımda yuva boşalmış.

Ehlileştireceğim kuşun umudu,

Bir başka bahara kalmış.

Kargıdan atlarımız olurdu.

Kıyasıya yarıştırırdık onları.

Seninki değil benimki kazandı diye,

Ölümüne dövüşür , küserdik biri birimize.

Uzun sürmezdi küslüklerimiz.

Tez barışırdık,

Yeni kavgalara hazır olalım diye.

Oyuna kapılırdık, açlığımız gelmezdi aklımıza.

Neden geç kaldınız diye, 

Annelerimiz hayıt sopalarıyla düşerdi peşimize.

Yakalanın vay haline. 

Böğürtlenlerin, hayıtların arasına gizlenirdik.

Kimse bizi bulmasın diye.

Sabırla beklerdik öfkeleri geçsin diye.

Hiç bitmezdi bu geç kalmalar

Ve kaçıp kovalamalar sürerdi tüm yaz boyu.

Okulların açılması dert olurdu. 

Çok sınırlı olurdu oyun saatleri. 

Özlerdik o bol kavgalı, bol dayaklı,

Sıcak yaz günlerini.

Nar ağacından kopardığım narları,

Ayva ağacının koyu gölgesinde yerdim. 

Narın tek bir tanesini düşürmeden,

Tümünü yiyebilirsen eğer. 

Öldüğünde cennete gidersin derlerdi.

Denemelerim hep boşuna giderdi.

Evimizin bahçesindeki fırında,

Ekmeklerden sonra ayvalar pişerdi.

Pişmiş ayvalar ne güzel şeylerdi.

Bağ bozumu üzümler çiğnerdik ayaklarımızla. 

Kocaman bir kazanda kaynardı şıralar. 

Pekmeze yatırılmadan önce,

Bardaklar dolusu içerdik gönlümüzce.

Tava balı, patlıcan ve kabak reçelinden sonra,

Köfteler yapılırdı, içinde bol cevizler.

Kurutulan üzümlerin en iyilerini,

Ayırırdık kendimize.

Bademler, iğdeler ve kurutulan incirler,

Depolanırdı kilerimize.

Şimdilerde,

Vitrinlerde görüyorum tüm bunları.

Gel de arama çocukluğumun,

O en güzel bolluk dolu güzelim yıllarını.

17.03.2001 01: 27			Özcan NEVRES', 'ÖZLEYİŞ Özledim bağlarımızın tozlu yollarını. Özledim yaz günlerinin yakıcı sıcağını, İçimi kavuran susuzluğumu giderdiğim, Tulumbamın buzu ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/ozleyis-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sen', 'bir-sen-melek-menekse-03bt2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirmisin, bir gün sonsuzluktan yola çikmistim

Ne gidecegim mekandan, nede ulasicagim noktadan haberdar

Sadece bir yolculuk, sadece bir heyecan, sadece ulasilmaz, çok saf, bir kaç umut

Gökkusagindan alabilecegim bir kaç renk...

Hatirlarmisin, issiz bir gece vakti karanligin içinde kaybolmustum

Kimseleri tanimaz, ne yapacagimi bilmez, bir ceylan yavrusu gibi ürkek

Belki siginacak bir yuva, belki ulasabilecek bir liman, belkide sicacik bir kucak arzusu

Kollarini açtin, beni sardin...

Animsarmisin, gözlerimin içine bakip kivilcimlar yakmistin

Kollarindaydim, yildizlardan daha parlak, çiçeklerden daha mutlu, minik bir serçeden daha özgür

Sanki bir rüyada, sanki bir cennette, sanki bir ask vadisinde, çilginca bir cosku

Yüregimin en derin noktasindan haykiran bir ses...

Simdide söylermisin bitanem

Beni benden eden seni, seni senden daha çok seven 

Bu serçenin rüyalarina ortak olurmusun

Asla bikmadan, o iki sözcügün anilarini bir ömür boyu paylasirmisin...', 'Bilirmisin, bir gün sonsuzluktan yola çikmistim Ne gidecegim mekandan, nede ulasicagim noktadan haberdar Sadece bir yolculuk, sadece bir hey...', ARRAY['Türk Edebiyatı','Şiir','Melek Menekşe']::text[], 8.5, '{"poet":"Melek Menekşe","poet_slug":"melek-menekse","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Yorgunu', 'eylul-yorgunu-hasan-akcay-evzly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgar mı getirdi yoktu az önce

Dağlardan yürüyen suskun akşamı

Akşam ki, etrafı sarıp örtünce

Eritir ufukta donuk zamana

Vicdanım dünlerden gel yap sorgunu

Kafeste kuş gönlüm/eylül yorgunu

Resimler çizilir gözleri yaşlı

Silinir bulutlar göğe değince

Sevinç bir içimde, hüzün on başlı

Kanatır yüreği yere eğince

Dağlarda çimenler yağmur vurgunu

Yürümez topraklar/ eylül yorgunu

Haykırış küçülür varmaz kulağa

Gönül seslerini duyan mı olur

Bakışla da gidemezken uzağa

Yıldızı geceden sayan mı olur

Muştular yağmursuz bulut durgunu

Gecede esen yel/ eylül yorgunu

Sessizlik hükümdar gece tahtında

Adımlar kısaldı, tutuk nefesler

Bir sarı yaprak var umut bahtında

Girmiş damarına endişe eser

Yalnızlık, gün senin çevir burgunu

Şiirler, şarkılar /eylül yorgunu

Eylül mü sen misin büken boynumu

Uçuşan yapraklar,göçen kuşlar mı

Sildirmez gözümden ömür sonumu

Ey bahar bir daha çağın başlar mı

Yalan baharların gönlüm dargını

Kavuşmak ümidi... Eylül yorgunu.', 'Rüzgar mı getirdi yoktu az önce Dağlardan yürüyen suskun akşamı Akşam ki, etrafı sarıp örtünce Eritir ufukta donuk zamana Vicdanım dünlerden...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akçay']::text[], 8.5, '{"poet":"Hasan Akçay","poet_slug":"hasan-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/eylul-yorgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris Şiirleri IV', 'paris-siirleri-iv-ataol-behramoglu-h95qz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arıyordum özgürlüğe giden yolu

İnsan yüzlerinde değil gökyüzünde

Arıyordum küçük beyaz bir bulutu

Boğularak uyandığım o saatte

Beni avutan o küçük bulut muydu

Bir aşk bile yoktu yıkan ve onaran

Bir aşk pırıl pırıl yağmur sularından

Paylaştığım bir şey yoktu bu şehirde

Şiirin bittiği yerde başlayan ne 

Çocukluğum muydu içimde sızlayan

Ve hayatın artık geçip gittiğini

Anlıyordum derin akan sular gibi

Kopmuş köklerimden çarparken rüzgarda

Gece bir uçurum gibi başlayınca 

Boğuntulardan çıkardım bu şiirde

Kimse yok Akdeniz ağlıyor sadece

Garip ve yitik bir sonbahar gününde

Anlamların hızı biçimi aşarken 

Ağlamaz kendi uçurumuna düşen 

Boğulan kendinin labirentlerinde

                                  (Nisan 1985)', 'Arıyordum özgürlüğe giden yolu İnsan yüzlerinde değil gökyüzünde Arıyordum küçük beyaz bir bulutu Boğularak uyandığım o saatte Beni avutan o...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/paris-siirleri-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris Şiirleri V', 'paris-siirleri-v-ataol-behramoglu-c3xjg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arıyordum özgürlüğe giden yolu

İnsan yüzlerinde değil gökyüzünde

Arıyordum küçük beyaz bir bulutu

Boğularak uyandığım o saatte

Beni avutan o küçük bulut muydu

Bir aşk bile yoktu yıkan ve onaran

Bir aşk pırıl pırıl yağmur sularından

Paylaştığım bir şey yoktu bu şehirde

Şiirin bittiği yerde başlayan ne 

Çocukluğum muydu içimde sızlayan

Ve hayatın artık geçip gittiğini

Anlıyordum derin akan sular gibi

Kopmuş köklerimden çarparken rüzgarda

Gece bir uçurum gibi başlayınca 

Boğuntulardan çıkardım bu şiirde

Kimse yok Akdeniz ağlıyor sadece

Garip ve yitik bir sonbahar gününde

Anlamların hızı biçimi aşarken 

Ağlamaz kendi uçurumuna düşen 

Boğulan kendinin labirentlerinde

                                  (Nisan 1985)', 'Arıyordum özgürlüğe giden yolu İnsan yüzlerinde değil gökyüzünde Arıyordum küçük beyaz bir bulutu Boğularak uyandığım o saatte Beni avutan o...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/paris-siirleri-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçının Umudu(!)', 'balikcinin-umudu-baris-kav-zkk9s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam güneşinin gölgesindeydi balıkçının

kürek çektiği kayığındaki ekmek umudu.

Deniz dalgasıyla geçiyordu salınarak,

Bu akşamın daboş geçeceğinin habercisi olarak.

Yakamozdan balık olsa keşke de tuttuğumuzla

kalksak gökyüzüne dedim.

Sonra küreğin köpüklüğünü kayboldu yavaş

yavaş akşam güneşinin gölgesinde.

Sonrası püsküleriyle kahverengi bereyi 

hatırladık suyun yüzünde...

(19/07/2000)', 'Akşam güneşinin gölgesindeydi balıkçının kürek çektiği kayığındaki ekmek umudu. Deniz dalgasıyla geçiyordu salınarak, Bu akşamın daboş geçec...', ARRAY['Türk Edebiyatı','Şiir','Barış Kav']::text[], 8.5, '{"poet":"Barış Kav","poet_slug":"baris-kav","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/balikcinin-umudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili!!!', 'sevgili-ceren-gulec-j2sry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili!

Gördüm ki,

Sadece saçma bir düzen değilmiş

                        içinde bulunduğumuz.

Ne bir sigarayla söndürülüyormuş korkular,

Ne de kitap aralarına koyulan

                        kağıt parçalarıyla

                                duraklıyormuş yaşam!

Gördüm;

Taş kalpler üzerine atılan

                        çizgilermiş anılar...

Zamanı üfledim,

İlk adımım,

          o toz bulutunun

                        içine gömdü başımı...

Geriye döndüm,

-sadece bakmak için bıraktıklarıma-

Gördüm ki,

        ben yokken,

                fırtına olmuş o küçük esintiler...

Sevgili!

Ne bir kaçıştı içime yüklediğim,

Ne de gözkapaklarımın arkasındaki

                         görüntülerin tılsımı...

Meğer sadece,

           yanıbaşımdan gelen

                    fısıltılarmış

                            titremenin kaynağı....

Sevgili!

Sen yokmuşsun ortalarda.

-belki de hala yoksun-

Ben hissetmiyormuşum varlığımı.

Ve boş yere

         hissettirmeye çalışıyormuşum

                     hissetmediğim varlıklara...

Yaşadığım hiçbir gün,

O ''hiçbir gün''lerden değilmiş.

Ve o ''hiçbir gün''lerin birinde,

Avcumda bir parça ''yok''la çıkarsam karşına,

Ya da

Açtığım herhangi bir kapının arkasında

                      bulduğumda seni,

Ve olmayan gözlerinle bana bakıp

                 olmayan ellerini uzattığında bana

Geçip gidersem yokluğunu içinden,

Ve kapatırsam kapıyı yokluğunun yüzüne

Sorma bana

''Neden bu kaçış?'' diye......

Sevgili!!!

Kaçış yoktur yokluklardan......', 'Sevgili! Gördüm ki, Sadece saçma bir düzen değilmiş                         içinde bulunduğumuz. Ne bir sigarayla söndürülüyormuş korkular, ...', ARRAY['Türk Edebiyatı','Şiir','Ceren Güleç']::text[], 8.5, '{"poet":"Ceren Güleç","poet_slug":"ceren-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sevgili-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına Çocukları', 'firtina-cocuklari-ahmet-i-nce-2beo7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'burası yağmur ve deniz ülkesi

özgürlük ve barışın sesi

mavi ile yeşilin nikahı burda kıyıldı 

burda yazıldı hamsi ile mısırın aşkı

fındık ile çay bu toprakta öpüştü

şimdi

özgürlük şimşekleri

tekmeler karnını karanlığın

inletir yeri göğü yıldırımlar

değişim sancısıyla kıvranırken doğa 

aralar bacaklarını bulutlar

salar suyunu aşağılara

o zaman biz 

            ıslanırız ezgisinde kemençenin

yıkanırız bakışlarında hamsi gözlü güzellerin 

savrulurken yeşil saçları sisli kıyıların 

yaşarız günahların gizli aşkların 

biz fırtına çocuklarıyız

               ömrümüz sularda

                          yağmurlarda geçer

en çılgın aşıklarıyız doğanın

deniz türküleri 

             horon havası

                       hamsinin hoplaması

                                             yansıtır bizi

ormanların yeşil gülüşünden geçer sevgimiz

deniz mavisinde yıkanır umutlarımız 

bütün renkleri en hızlı biz yaşarız

geleceğin resmini en güzel biz yaparız

çünkü biz

           isyan türküleri yakan            

                  karanlıktan aydınlığa akan

                                   fırtına çocuklarıyız

                                Ahmet İNCE

                           03.04.2001-Trabzon', 'burası yağmur ve deniz ülkesi özgürlük ve barışın sesi mavi ile yeşilin nikahı burda kıyıldı  burda yazıldı hamsi ile mısırın aşkı fındık il...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/firtina-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sallandık', 'sallandik-baris-kav-mzdj8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sallandık...

17 Ağustos 1999

Deliler gibi,

Döne döne.

Yana yana.

Sonra öldük.

Binlerce diri diri.

Sokaklar dar geldi,

Göğ birden yere indi.

Koynumuza aldık günlerce;

Korkuyu,telaşı,üzüntüyü.

Dert kaosu sever

Kaos ise arkadaşlığı

Bir dert geldi ki yürekler acısı

Günler geçmekte

Sallandık...

Darısı kimsenin başına...', 'Sallandık... 17 Ağustos 1999 Deliler gibi, Döne döne. Yana yana. Sonra öldük. Binlerce diri diri. Sokaklar dar geldi, Göğ birden yere indi. ...', ARRAY['Türk Edebiyatı','Şiir','Barış Kav']::text[], 8.5, '{"poet":"Barış Kav","poet_slug":"baris-kav","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sallandik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül (Yine Hüzün)', 'gul-yine-huzun-nurullah-genc-s3pyy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bitir bu işkenceyi, sende artık bana gül

dokundurma elini pıhtılaşan kana gül

bahçe boş; çeşme kuru; nerde bostancıbaşı

gelde feryâd ü figân etme bu hüsrâna gül

yıllarca yatağında uyudum semenderin

çakallar yuvalandı bizim olan hana gül

unuttum gökkuşağı altındaki resmini

nice bühtan ettiler eski bir sultana gül

kâinat oluk oluk boşalırken içimden

yağmur damlası bile olamadım sana gül

uzandığım her hayal tutuşturdu ömrümü

her yangınla yeni bir yangın düştü cana gül

ya öldür, yarasalar okşasın cesedimi

ya da terkedip gitme beni bu isyâna gül

dinle ki, en ölümcül şarkımı söylüyorum

darağacı kurdular döndüğüm her yana gül

nasıl sevişiyorsun kırkayakla, çıyanla

hani boyun bükmüştün ebedî fermana gül

meğer bir yanılgının zinciriymiş umudum

güvenimi yitirdim şimdi her dermana gül.', 'bitir bu işkenceyi, sende artık bana gül dokundurma elini pıhtılaşan kana gül bahçe boş; çeşme kuru; nerde bostancıbaşı gelde feryâd ü figân...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-yine-huzun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Şiir', 'bitmeyen-siir-ahmet-i-nce-4i6oq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sardıkça sevgimi sevgin

akarsın pınarından özlemin

yansıtır sözlerin güneş gibi

yüreğimin içini

sesine yaslandıkça

göğsünü dinledikçe 

hırçın bir deniz gibi

inledikçe kürelerin

açılıp saçılıyor sevgim

sen bitmeyen bir şiirsin

altın saçlı bebeğimsin

karanfil gibi büyülü, sıcak

kızıl bir keklik gibi yumuşak

ne zaman seni düşünsem

başkaldırır sevgimde bir ıtır

mavi bir şaraptır gözlerin

baktıkça gözlerimi ısıtır

               Trabzon, 22.10.1994', 'sardıkça sevgimi sevgin akarsın pınarından özlemin yansıtır sözlerin güneş gibi yüreğimin içini sesine yaslandıkça göğsünü dinledikçe  hırçı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bitmeyen-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevme Zamanı', 'sevme-zamani-ahmet-i-nce-mxj25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sunarken 

Sıcak göğsünü 

Dudaklara deniz

Uçar sabırsız kuşlar

Koynunda serin özlemlerin

Hazırlan sen de sevgilim

Karşılamaya akıp giden zamanı

Ve susturmaya sesini nefretin

Kaybolurken

Ak bakışlarda karanlık 

Bil ki sevme zamanıdır

Aksın arzular

Kucaklasın yaşamı tutkular', 'Sunarken  Sıcak göğsünü  Dudaklara deniz Uçar sabırsız kuşlar Koynunda serin özlemlerin Hazırlan sen de sevgilim Karşılamaya akıp giden zama...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevme-zamani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku Fırtınası', 'tutku-firtinasi-ahmet-i-nce-sw856', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün 

Kuşlar kadar özgürüm

Uzansam dokunabilirim

Kızıl saçlarına güneşin

Ve mavi yüreğine Karadeniz’in

Tuz kokulu kıyıları

Okşarken akşam güneşi

Coşar mavi ile beyazın valsı

Çırpınır yüreğimde tutsak arzular

Hızlanır bulut içinde ateşin dansı

Yeşil yapraklar arasında

Göz kırpar ışığı yutan sular

Balkonlar çiçek seli

Her pencere özgün bir yürek

Her bakışta gizli bir istek

İstekler yüreklere el eder 

Baygın bakışlarda

                      şiir gibi ezgiler

Gönülden gönüle

                      ince sevgiler gider

Denizde ışık seli

Dilimde şiirin hası

Elimde özlemin eli

İçimde tutku fırtınası

Bugün

Kuşlar kadar özgürüm

Uzansam dokunabilirim 

Mavi yüreğine Karadeniz’in

Ve sarı saçlarına sevgilimin

                          

                   ( Trabzon11.08.1999)', 'Bugün  Kuşlar kadar özgürüm Uzansam dokunabilirim Kızıl saçlarına güneşin Ve mavi yüreğine Karadeniz’in Tuz kokulu kıyıları Okşarken akşam g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tutku-firtinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızı', 'deniz-kizi-ahmet-i-nce-dutyy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soyundu 

                ak zambak gibi

                   deniz kıyısında

                                   bir kız 

Saçları saman sarısı

Gözleri buzdan mavi

Gülüşü gül

            bakışı naz

              yanakları kızıl elma

                dudakları bal kiraz

                  dişleri inciden beyazdı

Giysilerinden kurtulan kız

Tanrıça Afrodit’ten daha güzeldi

Denizin koynuna girmeden

Baktı etrafına üzünçle

Bakmadı kendisini süzen aç gözlere

Karşılık vermedi

              güzelliğine hayran sözlere

El salladı yalnızca

Yeşil kayaların tepesinde

Kendisine el sallamayan sevgilisine

Sonra

Atladı azgın dalgaların köpüklü koynuna 

Yöneldi son hızla

               güneşin battığı yere

Yüzdü gitti küskünce

             yüreğinin götürdüğü enginlere

                                            

                             (Trabzon,15.02.2000)', 'Soyundu                  ak zambak gibi                    deniz kıyısında                                    bir kız  Saçları saman sarısı ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/deniz-kizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dostuma', 'gonul-dostuma-nilgun-pakyildiz-87443', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yudum aşkadır benim susuzluğum, 

Sevda ateşlerinde yanmayadır vurgunluğum. 

Hep seni aradım gökyüzünün renginde,ufkunda 

Bir kuşun kanadında,uçuşundadır benim umudum. 



Yüreğimdeki karanlığa,fikrimdeki adınadır suskunluğum 

Seni mecnun misali aramayadır burukluğum. 

Hep seni aradım gecenin bağrında,yatağında, 

Sevda uykusunun kucağında,rüyalarındadır benim umudum. 



Yeşermeyen baharlaradır,ömrümün sonunadır solgunluğum. 

Kısalan bu yolda küçücük bir ışıktır elimde tuttuğum 

Hep seni aradım gülün yaprağında,goncasında 

Misk-i amber kokusunda kuruyan toprağındadır benim umudum. 



Sevda girdaplarında kaybolmayadır yokluğum 

Sensiz yaşanan yıllaradır yorgunluğum 

Hep seni aradım yalnızlığın sesinde,uğultusunda 

Bir aydınlık bir de karanlıktadır benim umudum. 



Rüzgarın sesinde,fırtınasında seni bulsam aşık olurum 

Denizin melteminde,köpüğünde aşkı bulsam seni bulurum 

Hep seni aradım yağmurun selinde damlasında 

Bir dağın eteğinde doruğundadır benim umudum. 



Ömrümce hep seni arar dururum,neredesin ey gönül dostum? 

Aşkı bulsam seni bulurum,seni bulsam aşık olurum. 

Hep seni aradım,hep seni,neredesin ey gönül dostum? 

Son dem son nefese kadar yüreğimdedir benim umudum 

Hep seni aradım,hep seni neredesin ey gönül dostum?', 'Bir yudum aşkadır benim susuzluğum,  Sevda ateşlerinde yanmayadır vurgunluğum.  Hep seni aradım gökyüzünün renginde,ufkunda  Bir kuşun kanad...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Pakyıldız']::text[], 8.5, '{"poet":"Nilgün Pakyıldız","poet_slug":"nilgun-pakyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-dostuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansıma', 'yansima-ahmet-i-nce-3occw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'karanlığın gözlerinde

              uyanırken kanlı güneş

çıplak tepelerinde özgürlüğün

kızışır ateşin dansı

yanar nice tutkular

karlı dağların yamaçlarından

tutsak kentlerin varoşlarına doğru

kirli bir nehirde zehir  akar

akar ölüm

sömürü dünyasında kutsanırken şiddet

kudurur talan ve rant

vampir çeteler yalnızca

para ve kan emer

sabrın sonsuz derinliklerinde

patlıyor öfkesi ezilenlerin

sallanıyor bacakları zorbalığın

karanlığın her yanından

boşalıyor zehir ve zulüm

fışkırıyor kin ve irin

karanlık kuduz dev 

kuduz dev saldırıyor yine de

emeğe ve özgürlüğe

vahşetin hükmüne karşın

sahipsiz değil yüce sevda

hak ve özgürlük tutkusuyla

                        çoğala çoğala

umudun emekçileri

     yeniden doğuyor destanlarda

                              TRABZON

                           (18.04.1998)', 'karanlığın gözlerinde               uyanırken kanlı güneş çıplak tepelerinde özgürlüğün kızışır ateşin dansı yanar nice tutkular karlı dağla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yansima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Bir Yaprak Olmak', 'yesil-bir-yaprak-olmak-arzu-dincer-z74g5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşil bir yaprak olmak,

Cılız bir dalın üstünde.

Elleri rüzgarlara açık,

Güçlü...güçlü olmak.

Ve bilmek,

İstesede dönüşemeyeceğini

Pembe yapraklara...

Ama bi o kadar kararlı,

Direnebilmek,

Direnebilmek acılara...

Yeşil bir yaprak olmak,

Cılız bir dalın üstünde.

Gözleri,

Gözleri sabah çiğ taneleri...

Bilmek gün ışığı ile,

Gözlerin akacağını...

Ama ...ama yine de

Tanımak dünyayı...

Görebilmek, hissedebilmek

Tüycüklerin üzerinde dolanan

Deli rüzgarların tadını...

Yeşil bir yaprak olmak,

Cılız bir dalın üstünde.

Küçük bir böceğin,

Yoldaşlığını hissetmek...

Minik adımlarında,

Ve nankörce bir ısırılışla,

Hissetmek iki yüzlülüğü..

Ve yine de yaşamak,

Yaşamak her solumada..

Tükenmemek ...

Yeşil bir yaprak olmak,

Cılız bir dalın üstünde...

Vakit tamam dendiğinde,

Düşmek toprağa,

Ve toprak olup,

Dal''a öz olarak ulaşmak sonunda....

İnanmak 

İnanmak tekrar yaprak olmaya...

5/4/2001  Ankara', 'Yeşil bir yaprak olmak, Cılız bir dalın üstünde. Elleri rüzgarlara açık, Güçlü...güçlü olmak. Ve bilmek, İstesede dönüşemeyeceğini Pembe yap...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yesil-bir-yaprak-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil', 'karanfil-arzu-dincer-vujcx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne karanfiller düştü toprağa,

Ağladım..ağladım hıçkıra hıçkıra...

Anılar karanfillerle dolu...

Andım onları okuya okuya....

Ne karanfiller düştü toprağa,

Cenaze törenleri hüznü bağladı,

Hüzün öfkeye döndü...

Sarıldım kaleme....

Ne karanfiller düştü toprağa,

Toprak yeter dedi,

Karanfiller doymadı düşmeye,

Kalemler boyun eğmeden,

Sayfaları öptü..öptü...

Ne karanfiller düştü toprağa,

Toprak tarih yazdı,

Çocuklar tarih okudu...

Niye dediler...?

Satırlar cevap veremediler...

Nedensiz diyemediler....

Ne karanfiller düştü toprağa, 

Toprak koynundan,

Ne karanfiller çıkardı sonra...

Çoğaldılar..çoğaldılar...

Karanfil oldu insanlar..

5/4/2001 Ankara', 'Ne karanfiller düştü toprağa, Ağladım..ağladım hıçkıra hıçkıra... Anılar karanfillerle dolu... Andım onları okuya okuya.... Ne karanfiller d...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karanfil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan', 'kanayan-i-lhan-tulman-h029y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kanayan ne varsa

Denizlerin hayalet çığlıklarını taşırdı

Ben

O zamanlar

Alarga tanrıların önünde

Bir poyrazdım

Saçlarımda kırılmış yürekler ..', 'kanayan ne varsa Denizlerin hayalet çığlıklarını taşırdı Ben O zamanlar Alarga tanrıların önünde Bir poyrazdım Saçlarımda kırılmış yürekler ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Tülman']::text[], 8.5, '{"poet":"İlhan Tülman","poet_slug":"i-lhan-tulman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kanayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-i-brahim-kilinc-u1uem', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizliği bana sorarsan eğer, 

Havanın havasız kalması gibi,

''Bensiz geçen günler nasıldır? '' dersen,

Suyun susuzluktan yanması gibi.

Geceleri sorma, nasıl geceler,

Sevdamın sırrına,ermez heceler,

Titretir her gece gönlü acılar,

Güneşin  soğuktan donması gibi.

Her şafak sökerken başlar ayazlar

Sanma ki farklıdır kışlardan yazlar

Düşer şakaklara bir bir beyazlar

Çöllere karların yağması gibi

Gidiyorken ''bekle, dur '' diyememek

''Bir gününü bana ver'' diyememek

''Ne olursun, bir kez gül'' diyememek

Bir bedenin ruhsuz kalması gibi', 'Sensizliği bana sorarsan eğer,  Havanın havasız kalması gibi, ''Bensiz geçen günler nasıldır? '' dersen, Suyun susuzluktan yanması gibi. Gecel...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-aytac-aydin-88d8q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne güzel şeydir kendini özgür hissetmek

Salıvermek ruhunu göklere

Sınırların ötesine geçmek

Sorumsuzca seçmek istediklerini......

Ne güzel şeydir kendini özgür hissetmek

Karar vermek

Yapabilmek herşeyi

Her duyguyu yaşayabilmek dolu dolu........', 'Ne güzel şeydir kendini özgür hissetmek Salıvermek ruhunu göklere Sınırların ötesine geçmek Sorumsuzca seçmek istediklerini...... Ne güzel ş...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Aydın']::text[], 8.5, '{"poet":"Aytaç Aydın","poet_slug":"aytac-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozgurluk-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüken(mişim)', 'tuken-misim-riza-aslan-ts6i3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tükenmişim.

suçlu ararken

kendi benliğimde.

savunmasız duygulara

yüklerken belirsizlikleri;

hakketmemişlikleri

haksızlıkları

hep dışarıda ararken,

- olmayanda ararken -

tüketmişim.

tükenmişim.

tükenmişim.

bir saldırganlık saplantısıyla.

kendime dönmüş

yıkıntılarım;

yok etmek isterken 

çelişkileri,

kendimi yok etmişim.

tüketmişim

tükenmişim

tükenmişim.

hep söz vermişim,

hiç bir zaman tutmayacağımı bildiğim

bu kez son demişim,

son olmadığını bildiğim

hep bir umut aramışım

gerçekleş(e)meyeceğini bildiğim

tükendi artık demişim,

tükenmişim

tükenmişim.

durgun sularda , fırtınalar koparmışım

savurmuşum kendi benliğimi

- her bir parçam ayrı bir yere -

tüketmişim

tükenmişim

04-04-2001

karacan ankara', 'tükenmişim. suçlu ararken kendi benliğimde. savunmasız duygulara yüklerken belirsizlikleri; hakketmemişlikleri haksızlıkları hep dışarıda ar...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/tuken-misim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Ruhum Çingene', 'benim-ruhum-cingene-aytac-aydin-g4dwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim ruhum çingene

Sevgilim rengarenk

Renklerin alacası bulacası

Benim ruhumun aynası.

Ufak şeyler sevindirir beni

İhtiraslar bana göre değil

Kapı gıcırtısı oyun havası

Yerimde duramam oynarım.

Göçebeyim diyar diyar

Yasemenler papatyalar

Koklamam her çiçeği, seçerim;

Seni bütün çiçeklerden ayrı tutarım.', 'Benim ruhum çingene Sevgilim rengarenk Renklerin alacası bulacası Benim ruhumun aynası. Ufak şeyler sevindirir beni İhtiraslar bana göre değ...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Aydın']::text[], 8.5, '{"poet":"Aytaç Aydın","poet_slug":"aytac-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-ruhum-cingene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olduğun İçin', 'sen-oldugun-i-cin-aytac-aydin-766lb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen Olduğun İçin

Seni sen olduğun için sevdim

İçimde senin sıcaklığını hissettiğimde

Ellerinin ellerimde olduğunu farkettim

Sevdim seni sen olduğun için.', 'Sen Olduğun İçin Seni sen olduğun için sevdim İçimde senin sıcaklığını hissettiğimde Ellerinin ellerimde olduğunu farkettim Sevdim seni sen ...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Aydın']::text[], 8.5, '{"poet":"Aytaç Aydın","poet_slug":"aytac-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-oldugun-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından-4', 'akort-makamindan-4-salih-parlak-1lez6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen o kadar yabancımısın bana?

Amansız bir savaşta düşmanız sanki.

Ne bileyim, gün gelir tutarsın ellerimi,

Dünyaya geldiğimize pişmanız sanki.

Yıllar hasretini kalbime saplar,

Kalbim görse seni; gözlerimden saklar.

Sevmiyorsun dese yalancı dudaklar,

Saçımda duruyor şahidim aklar.

Kaç ay oldu göremedim yüzünü,

Sormam artık baharını güzünü,

Sevdiğini söylesen, duysam sözünü,

Yeminler etsen, inanıp ta dönmem.

Ağlarsan silme gözyaşlarını,

Nasıl da zor değil mi ağlamak?

Kolay değil; sevmeyenin ardından,

Bir kalbi bir kalbe bağlamak.

İhtiyacım yok anılarına,

Ben ihtiyarmıyım ki?

Böyle çaresizce,

Anılara muhtaç kalacak?', 'Sen o kadar yabancımısın bana? Amansız bir savaşta düşmanız sanki. Ne bileyim, gün gelir tutarsın ellerimi, Dünyaya geldiğimize pişmanız san...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından-5', 'akort-makamindan-5-salih-parlak-rsxv5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk sarhoş edermiş; kim nereye sızmış?

Sevmeseydi Leyla’yı mecnun haksızmış.

Ateşiyle yanıp tutuşan gönülden,

Gösterin bana seven hangi kızmış?

Gözlerim ufukta, kalbim umutta,

Boşuna bekleme...

Bugünün çiçekleri soldu,

Umutlar yarına kaldı.

“Seni sevmiyor” dese de aklım,

Kalbim bunu kabullenmiyor.

Asıl beni kahreden;

Allah’ım bu ümit neden?

İnsanlar yazsalardı kaderlerini,

Yer vermezdim defterimde kedere,

Çözerdim dünyanın bütün sırlarını,

Düğümü bırakmazdım İskender’e.

Sen yanıldın güzelim;

Bakılan göz aşınmıyor.

Kalp de hergün çarpıyor;

Ama boşuna taşınmıyor.', 'Aşk sarhoş edermiş; kim nereye sızmış? Sevmeseydi Leyla’yı mecnun haksızmış. Ateşiyle yanıp tutuşan gönülden, Gösterin bana seven hangi kızm...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından-6', 'akort-makamindan-6-salih-parlak-2bkvm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boğazımda düğümleniyor düşüncelerim,

Çatlıyor heyecandan kan damarlarım.

Sen yeter ki gel;

Saatleri ben ayarlarım.

İstemem sana edilmesin beddualar,

Bir çocuk saflığıyla,

Allah’a ulaşır,

Kabul olur ettiğim dualar.

Unutmadım seni görünce,

Kalbimin atışını,

Bir de evden ayrılırken;

Anamın ardımdan bakışını.

Bardaktan boşanırcasına yağmıyor yağmur,

Yok artık, sırılsıklam ıslanan iki sevgili.

Ağaçlara kalp kazımayı da unuttuk,

Çöllerde kaldı eski aşklar.

Sus! Konuşma sevgilim,

Yorulmasın gül dudakların,

Söylemesen de olur o iki kelimeyi;

Ben gözlerinden anlarım.', 'Boğazımda düğümleniyor düşüncelerim, Çatlıyor heyecandan kan damarlarım. Sen yeter ki gel; Saatleri ben ayarlarım. İstemem sana edilmesin be...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-bulent-erkigun-vattx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni hayal ediyorum hiç işim yokmuş gibi

Çok derinden hayal etmişim ki, kendimi bir an yanında sanıyorum.

Derin bir nefes alıp kalıyorum,

Ah ne vardı simdi yanında olsaydım.

Dizlerinin altında,

Ellerim ellerinde,

Gözlerinin derinliklerinde, seninle iç içe, 

Biliyorum imkânsız, ama düşüncesi bile yetmekte...

Hayatımın akışı değişiyor, hüzünlenmeye başlıyorum.

Sensiz yarınlarda ne yaparım acaba? Bilmiyorum...

Zaten şu anda bilmekte istemiyorum.

Anımı yaşamak,

Ağlamak istiyorum.

Seni komacan komacan seviyorum.

Sığdıramıyorum dağlara taşlara sevgimi

Bol bol seni düşünüyorum.

Bekle beni, yanına geliyorum diye avaz avaz bağırmak geliyorsa da içimden,

susuyorum...

İçim yanıyor, ağlıyorum,

Ama sana kavuştuğum gün, iste o gün bir daha ağlamayacağım,

Bunu biliyorum, zor bir ihtimal belkide,

İnanamıyorum.', 'Seni hayal ediyorum hiç işim yokmuş gibi Çok derinden hayal etmişim ki, kendimi bir an yanında sanıyorum. Derin bir nefes alıp kalıyorum, Ah...', ARRAY['Türk Edebiyatı','Şiir','Bülent Erkigün']::text[], 8.5, '{"poet":"Bülent Erkigün","poet_slug":"bulent-erkigun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aglamak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akort Makamından-7', 'akort-makamindan-7-salih-parlak-j4qel', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbim kapalı başkasına,

Birgün açmış görürsün,

Omuzlar eller üstünde,

Beni göçmüş görürsün.

Takılsam, çıkamasam saçlarının ağından,

Sıcak bir gözyaşı olup aksam,

Elimle dokunamadığım;

Pembe yanağından.

Sensiz geçen her gün,

Bilirmisin beni nasıl kahreder?

Sevincimi paylaşır parça parça dakikalar,

Benim payıma düşen, üzüntü ve keder.

Aklımda dolaşan bin türlü düşünce;

Kimi seni düşünüyor, kimi darmadağın,

Ama; bir noktada toplanıyorlar hemen; 

Sen aklıma düşünce.

Kırılsın bütün aynalar,

Ben bakmalıyım yüzüne.

Senin gibi bir güzel;

Gelmedi henüz yeryüzüne.', 'Kalbim kapalı başkasına, Birgün açmış görürsün, Omuzlar eller üstünde, Beni göçmüş görürsün. Takılsam, çıkamasam saçlarının ağından, Sıcak b...', ARRAY['Türk Edebiyatı','Şiir','Salih Parlak']::text[], 8.5, '{"poet":"Salih Parlak","poet_slug":"salih-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akort-makamindan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Bana', 'yazik-bana-bulent-erkigun-6buc5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşünmekten başka işim kalmadı.

Askerliği bile düşünmüyorum artık.

Tek düşündüğüm 

Sensiz geçen o güzel günlerim.

Seni düşünmekten başka işim kalmadı.

Yatıyorum sen, kalkıyorum sen.

Neden bilmiyorum ama     (İSTİARE)

Hep seni düşünüyorum.

Seni düşünmekten başka işim kalmadı.

Seni düşünürken içim titriyor, kanım hızlanıyor.

Exstra bir güç geliyor bana 

Seni düşünürken.

Seni düşünmekten başka işim kalmadı.

Her nedense seni düşünmeyi seviyorum.

Karnıma ağrılar giriyor, içim sızlıyor, canım yanıyor,

Yine de seni düşünmeyi seviyorum.

Seni düşünmekten başka işim kalmadı.

Kendi halimi düşünürken bile seninle birlikte düşünüyorum.

Sensizliği düşünmek bile istemiyorum.

İstemiyorum işte ya, sana ne istemiyorum.

Seni düşünmekten başka işim kalmadı.

Seni düşünmek, 

En güzel şarkıyı dinlemek gibi bir şey,

Ama artık şarkıyı dinlemek değil,

Söylemek istiyorum.', 'Seni düşünmekten başka işim kalmadı. Askerliği bile düşünmüyorum artık. Tek düşündüğüm  Sensiz geçen o güzel günlerim. Seni düşünmekten başk...', ARRAY['Türk Edebiyatı','Şiir','Bülent Erkigün']::text[], 8.5, '{"poet":"Bülent Erkigün","poet_slug":"bulent-erkigun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yazik-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteyenin Bir Yüzü', 'i-steyenin-bir-yuzu-bulent-erkigun-3i1ol', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsterdim ki; beraber oran ormanlarında yürüyelim el ele, göle bakalım, 

içimize çekelim o temiz oksijeni, doğa sarhoşu olalım.

İsterdim ki; sinemaya gidelim çıkınca eleştirelim, tartışalım. 

Alış-verişe gidelim o senin bu benim giyip giyip çıkaralım, hiç bir şey almadan da çıkalım sinir edelim oradakileri. 

İsterdim ki; cafeye gidelim, santranç, tavla, okey, piçti, bilardo oynayalım, 

eğlenelim, stres atalım.

İsterdim ki; bir iftar yemeğinde senin en sevdiğin şeyler masanda tabi ki birde ben,

 mumlar altında yemek yiyelim. 

İsterdim ki; kendimizden bahsedelim keşfe çıkalım, birbirimizi bulalım safari avında. 

Doğruyu yanlışı tartışalım.

İsterdim ki; el ele gezelim hiç bir şeyi umursamadan,

İsterdim ki; yağmur altında dans edelim, o soğuk havada sımsıkı sarılalım ısıtalım birbirimizi, 

aşk sarhoşu olalım.

İsterdim ki; bir simidi, duygularımızı, beraberliğimizi, sevgimizi paylaşacağımız gibi paylaşalım.

İsterdim ki; konuşacak bir şey kalmadığında bırakalım gözlerimiz konuşsun

 anlatsın karşılıklı duygularımızı.

Çok şey istedim galiba zaten üstüne alınanda yok. 

Benim gibiler zaten hep isterler, veren olmadıktan sonra istemenin ne anlamı varsa, 

olsun, ne olursa olsun ben hep isteyeceğim vermeyenin canı sağ olsun, 

önemli olan o zaten. Ama o vereceği günü hep bekleyeceğim, 

KİMBİLİR...', 'İsterdim ki; beraber oran ormanlarında yürüyelim el ele, göle bakalım,  içimize çekelim o temiz oksijeni, doğa sarhoşu olalım. İsterdim ki; ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Erkigün']::text[], 8.5, '{"poet":"Bülent Erkigün","poet_slug":"bulent-erkigun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/isteyenin-bir-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerlik', 'askerlik-bulent-erkigun-e9y0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerim akip gidiyor. 

Hayat sürmeye devam ediyor,durdurmak istesemde,

Yasama sevincimi yitiriyorum.

Askerlik lanet olasi. 

Insanlar bos, bombos

Ya da  öyle geliyor.

Vurdum duymaz halimi yitiriyorum, düsünüyorum.

Askerlik lanet olasi

Ben beni istiyorum artik,

Bir ben vardim kendimi gördügüm,

O da son anlarini yasıyor,

Askerlik lanet olasi', 'Günlerim akip gidiyor.  Hayat sürmeye devam ediyor,durdurmak istesemde, Yasama sevincimi yitiriyorum. Askerlik lanet olasi.  Insanlar bos, b...', ARRAY['Türk Edebiyatı','Şiir','Bülent Erkigün']::text[], 8.5, '{"poet":"Bülent Erkigün","poet_slug":"bulent-erkigun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askerlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-i-nci-ozcan-0vpuu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yğmurları sevdiğini söylüyorsun

Yağınca şemsiyeni açıyosun

Rüzgarı sevdiğini söylüyosun

Esince pencereni kapatıyosun

Şimdide kalkmış beni sevdiğini söylüyosun

Korkuyorummm', 'Yğmurları sevdiğini söylüyorsun Yağınca şemsiyeni açıyosun Rüzgarı sevdiğini söylüyosun Esince pencereni kapatıyosun Şimdide kalkmış beni se...', ARRAY['Türk Edebiyatı','Şiir','İnci Özcan']::text[], 8.5, '{"poet":"İnci Özcan","poet_slug":"i-nci-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-seviyorum-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-hikmet-tugrul-tekeli-u4z22', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz,sessiz geceler

          Seni düşündüğüm                                                             

          Nice hayaller kurduğum

          Senin için ağladığım geceler

          Karanlığın ortasında yalnız 

          Yaptıklarımdan pişman 

          Allah''tan hep seni istedigim geceler

          Dinlediğim şiirler

          Söylediğim şarkılar

          Hep seni hatırlatır

          Yanık yüreğimi,karşılıksız aşkımı

          Sessiz haykırışlarımdır karanlık geceler

          Seninle konuşmalarım

          Elini tutmalarım

          Sana sevdiğimi söylediğim an

          Ve bunların hep bir hayal olduğu zamandırGECELER', 'Sensiz,sessiz geceler           Seni düşündüğüm                                                                        Nice hayaller kurduğu...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Halime Of', 'of-halime-of-mustafa-kosar-2h3ek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoo hayır sil artık gözlerini

Sus konuşma birşey söylemek zorunda değilsin

Ağaç gibi yıktın ümitlerimi bırak bırakta ömrüm yaşken eğilsin 

Çok şey söylemeyeceğim ama inan şeytan gibisin

Halime şu halime bak bak ellerime söyle 

Bunlar senin eserin değilmi?söyle of halime off

İnsan ne olursa olsun bir seveni ezmez

Sonra hiçbirşeyi umursamayıp alay edipte gülmez

Ben derdime alıştım sende vicdan azabı bitmez

Halime şu halime bak bak yüzüme söyle

Bu kırışıklıklar senin eserin değilmi söyle of halime off

Farkında bile değildin seni hatırlayıp içerken

Sen hep uyurdun ben evinin önünden geçerken

Neden çıktın karşıma seni hiç düşünmezken

Halime şu halime bak bak saçlarıma 

Bu beyazlar senin eserin değilmi söyle of halime off

Ne istedin yarınlarıma gülen bahtımdan 

Ne alıp veremediğin var üç kuruşluk canımdan

Her şeyi unutursunda bir gözlerimi çıkartamazsın aklımdan

Halime ,Halime şu halime bak bak söyle 

Bu yıkılmış abide senin eserin değilmi söyle 

Susma söyle of halime of ofki ne offff..!!!', 'Yoo hayır sil artık gözlerini Sus konuşma birşey söylemek zorunda değilsin Ağaç gibi yıktın ümitlerimi bırak bırakta ömrüm yaşken eğilsin  Ç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koşar']::text[], 8.5, '{"poet":"Mustafa Koşar","poet_slug":"mustafa-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/of-halime-of-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Mahkumu', 'yalnizlik-mahkumu-hikmet-tugrul-tekeli-2bgi5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mahkum olmuşum yalnızlığa

             Bir vefasız yar yüzünden

             Suçum sadece sevmek

             Ama inan hiç istemeyerek

             Bilmezdim yolların uzun ve karanlık olduğunu

             Sevmenin cezasının yalnızlık olduğunu

             Bense toz pembe hayaller kurmuştum

             Bilsen içine neler  doldurmuştum

             Çocuklarımız için isim bile bulmuştum

             Oysa ben vefasız bir yare tutulmuşum

             Ve hep rüyalar peşinde koşmuşum

             Elbette

             Herşeyin bir bedeli var

             Benimkisi yalnızlık

             Kadere karşı koyamamazlık

             Bir sen birde imkansızlık

             Büktüm boynumu bir kere

             Ölümden öncesi yalnızlık

             Seninki meçhul

             Bu son dileğim Allah''tan 

             Senide mahkum etsin yalnızlığa 

             Hemde benim yüzümden', 'Mahkum olmuşum yalnızlığa              Bir vefasız yar yüzünden              Suçum sadece sevmek              Ama inan hiç istemeyerek      ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizlik-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-hikmet-tugrul-tekeli-ep3a9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkuyorum gecenin karanlığında

                 İnan seni kaybetmekten

                Seni bir daha görememekten korkuyorum

                 Ve biliyorum gerçeği

                 Düşünüyorum

                 Geleceğimi ve seni

                 Yinemi anlamıyorum yoksa 

                 İnan bilmiyorum

                 Tek bildiğim yüreğimdeki o minicik çocuğun 

                 Hala susmadığı yada hala büyümediği

                 Herşeyin gelip geçici ve sonuçlarına 

                 Razı olmama  rağmen dayanamıyorum

                 Bir zamanlar güneş doğmak üzereydi

                 Herşey güzeldi

                 Kuş cıvıltıları,sabahın sessizliği

                 Kış günlerinin dondurucu soguğu

                 Yağan yağmurun sesi 

                 Ve sesinin sıcaklığı

                 Herşey güzeldi

                 Şimdi ise güneş batıyor

                 Ardında kırık bir kalp

                 Bir kaç damla yaş 

                 Ve kocaman bir ooofff bırakıyor.', 'Korkuyorum gecenin karanlığında                  İnan seni kaybetmekten                 Seni bir daha görememekten korkuyorum               ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/korkuyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemezsin', 'diyemezsin-m-sunullah-arisoy-5pjrp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her doğan gün ne getirir,

Bir yenisini mi hüznün? 

Bilemezsin.

Gök, mavidir, güzeldir,

Gün ışıklı işveli…

Yüreciğin oynar yerinden,

Koşasın gelir, uçasın gelir.

Gelir gelmesine ya...

Gel gör ki bir gün olsun,

Gülemezsin...

Bakarsın gözlerine,

Gözlerin yeşiline,

Yeşilin en güzeline 

Harelisine...

Kımıldar içinde arzular,

Bir ışıktır, yanıp söner

Yanıp söner,

Kımıldaşır arzular da,

Gözlerin yeşiline,

Yeşilin en güzeline,

Sevdiğim diyemezsin.', 'Her doğan gün ne getirir, Bir yenisini mi hüznün?  Bilemezsin. Gök, mavidir, güzeldir, Gün ışıklı işveli… Yüreciğin oynar yerinden, Koşasın ...', ARRAY['Türk Edebiyatı','Şiir','M. Sunullah Arısoy']::text[], 8.5, '{"poet":"M. Sunullah Arısoy","poet_slug":"m-sunullah-arisoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/diyemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare', 'care-nail-abbas-sayar-8o7ln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baktım 

Toprağa düşecek gibi değil su

Tohumu buluta ektim.', 'Baktım  Toprağa düşecek gibi değil su Tohumu buluta ektim....', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Sana', 'merhaba-sana-mehmet-bilen-mr7kl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgalarını engelleyemediğin

Karşılaştığında önce korku veren

Yaklaştıkça titreten

Yani sınır tanımayan

Yalanın adını bilinmediği

Dünyaların şekilsiz olduğu

Uykusuzluk dolu gözlerle baktıran

Gizemli tanışmaların ardından gelen

Gözlerin sözlerden üstün olduğu

Yaşadıkça serserileşen

Sonsuzluğa benzeyen ufkuyla

Yaşama sevinci veren

AŞK MERHABA', 'Dalgalarını engelleyemediğin Karşılaştığında önce korku veren Yaklaştıkça titreten Yani sınır tanımayan Yalanın adını bilinmediği Dünyaların...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bilen']::text[], 8.5, '{"poet":"Mehmet Bilen","poet_slug":"mehmet-bilen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/merhaba-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gariban', 'gariban-elbeyli-osman-rout0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğin titreyerek beklemek onun gelişini,

''Ya gelmezse'' diye korkarak beklemek.

Ve sevgi ummak bir çift samimi sözden

Yalnız yüreğini onunla avutmak kendi kendine.

Sanki!

Hiç dersini almamış gibi,

O yolardan hiç geçmemiş gibi ,

Hayaller kurmak ahmakça.

Geçmişine ve gerçeklere sünger çekip,

Beyhude dolanmak aşk çemberinde.

işte bu olsa gerek gariplik

Ve benim o gariban

Elbeyli gariban Osman

                                    21/02/2001', 'Yüreğin titreyerek beklemek onun gelişini, ''Ya gelmezse'' diye korkarak beklemek. Ve sevgi ummak bir çift samimi sözden Yalnız yüreğini onunl...', ARRAY['Türk Edebiyatı','Şiir','Elbeyli Osman']::text[], 8.5, '{"poet":"Elbeyli Osman","poet_slug":"elbeyli-osman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gariban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey...', 'her-sey-ozan-babayigit-baa2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her şeyin rengi bambaşka

dünyama geldin geleli

şimdi dünyaya bedel saçının bir tek teli

yaşadıkça seni sevmekte güzel ama,

seninle ömürboyu sevişmek en güzeli', 'her şeyin rengi bambaşka dünyama geldin geleli şimdi dünyaya bedel saçının bir tek teli yaşadıkça seni sevmekte güzel ama, seninle ömürboyu ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Babayiğit']::text[], 8.5, '{"poet":"Ozan Babayiğit","poet_slug":"ozan-babayigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/her-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ALLAH''a Kulmusun', 'sen-allah-a-kulmusun-elbeyli-osman-75djy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün öylesin bir gün böyle.

Cennete giden yok öyle.

Elini gönlüne koyda sen söyle

Sen ALLAH'' a kulmusun?', 'Bir gün öylesin bir gün böyle. Cennete giden yok öyle. Elini gönlüne koyda sen söyle Sen ALLAH'' a kulmusun?...', ARRAY['Türk Edebiyatı','Şiir','Elbeyli Osman']::text[], 8.5, '{"poet":"Elbeyli Osman","poet_slug":"elbeyli-osman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-allah-a-kulmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Olduysa...', 'nasil-olduysa-attila-i-lhan-tnwzj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nasıl olduysa birden adımı unuttum

adını unuttuğum o sıcak şehirde

yıldız alacası yüzen bir zakkum

yanımda o hayal kız ikide birde

yolumu gözlerine bakıp bulduğum

sahi ben ne hırçın bir çocuktum

ele avuca sığmaz aklı fikri şiirde

mısra mısra başımı belaya soktum

İzmir cezaevi dokuzyüz kırk bir''de

kaşla göz arası liseden kovuldum

inanmakta geç sevmekte çabuktum

bazen yaşadıklarım aklıma gelir de

kaç kere umutsuzluğun yolunu tuttum

istenmeyen adam hemen her devirde

hemen her devirde ateşten bir buluttum

binlerce umuttan belki bir umuttum', 'nasıl olduysa birden adımı unuttum adını unuttuğum o sıcak şehirde yıldız alacası yüzen bir zakkum yanımda o hayal kız ikide birde yolumu gö...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-olduysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diyebilirim Ki Sana', 'ne-diyebilirim-ki-sana-mehmet-ozyurt-9pfli', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne diyebilirim ki sana 

Seni seviyorumdan başka

Ağzımı her açtığımda, elini her tuttuğumda

Sen yokken bile seninle olduktan sonra

Yalnızlık mı denir buna

Rüyalarım da bile seninleyken

Ne diyebilirim ki sana

Seni seviyorumdan başka...

Evet seviyorum seni hem de delicesine

Bilmiyorum ama belki de ümitsizce

Ben bu durumdayken bile 

Ne diyebilirim ki sana

Seni seviyorumdan başka...

Yorgun akşamların sabahında beklerken seni

Ve uykusuz gecelerde ararken ellerini

Soluduğum her nefeste bulurken seni

Ne diyebilirim ki sana

Seni seviyorumdan başka...

Sevmeyi senden öğrendim 

Ama belki sevilmeyi değil

Yine de sevdim seni

Bir çocuğu sever gibi

Ve bekledim seni yine

Ölümü bekleyen hastalar gibi

Ve ölümümün son nefesinde bile

Ne diyebilirim ki sana

SENİ SEVİYORUMDAN BAŞKA...', 'Ne diyebilirim ki sana  Seni seviyorumdan başka Ağzımı her açtığımda, elini her tuttuğumda Sen yokken bile seninle olduktan sonra Yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ne-diyebilirim-ki-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Soruyorum', 'hesap-soruyorum-mehmet-ozyurt-uuf8s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günün batışını seyrederken hüzünle

Yüreğimde bir sancı, aklımda yine sen

Ve senin ayrılırken söylediğin söz;

Sevmek, cesaret ister demiştin bana,

Onca acıya ve zahmete katlanmak.

Ve sevmek, lavların içinde yüzmektir demiştin

Sanki serin sularda yüzercesine.

Yalnız kaldığımda,

Hep nerede yanlış yaptığımı düşünüyorum

Ve seni sevip sevemediğimi düşünürken

Beynimin yavaş yavaş eridiğini hissediyorum.

Ve gözlerime,

SENİ ANLATMADILAR DİYE HESAP SORUYORUM...', 'Günün batışını seyrederken hüzünle Yüreğimde bir sancı, aklımda yine sen Ve senin ayrılırken söylediğin söz; Sevmek, cesaret ister demiştin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hesap-soruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-mehmet-ozyurt-va0zl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen garip dostum benim

Yalnızlığın hüznünde ağlama yeter

Gel bulalım beraber dostu

Dost ki herzaman bizi bekler...

Zamanın varlığında yokluk ararken

Kim bilir ne canlar yandı 

Zaman yavaş yavaş erirken

Seni sende yok etmek ne kadar güç

Dostun huzuruna varmak en büyük övünç...

Yatağımdayım baş ucumda insanlar

Diller Kur''an okuyor yükseliyor nidalar

Allah! dedi ince bir ses yavaştan

Nedir bu kargaşa, nedir bu heyecan

Sesleniyorum sesimi duymuyor insanlar

Ölmüşüm de beni dosta uğurluyorlar...', 'Sen garip dostum benim Yalnızlığın hüznünde ağlama yeter Gel bulalım beraber dostu Dost ki herzaman bizi bekler... Zamanın varlığında yokluk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dost-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-mehmet-ozyurt-8e78z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşin yeniden doğduğunu görmek güzel

Yıldızları seyretmek ve onları saymak

Çiçeği dalından koparmadan koklamak

Hayatın tüm kötülüklerine rağmen

Hayattan zevk almak güzel

Hayatı seninle geçirmek ise en güzel...

Her şey fani bu dünyada bir gün gelir geçer

Değerini bilmek lazım herşeyin

Her an yaşamaya değer

Bazı anlar vardır insanı mutlu eder

Seninle geçen her saniye dünyaya bedel...

Doğduk, büyüdük ve halen büyüyoruz

Gün gelecek birgün öleceğiz diyoruz

Senden istediğim bu dostunu unutma

Gözlerin gülsün ve yaşamın mutlu olsun

Sana söyleyeceğim son söz;

DOĞUM GÜNÜN KUTLU OLSUN...', 'Güneşin yeniden doğduğunu görmek güzel Yıldızları seyretmek ve onları saymak Çiçeği dalından koparmadan koklamak Hayatın tüm kötülüklerine r...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumanlı havayı sevmek', 'dumanli-havayi-sevmek-riza-aslan-1tjhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dışarıda yağmur yağıyor

içimde kaybolmayan bir sis

kurt dumanlı havayı severmiş

bende...

dışarıda yağmur yağıyor

sicim, sicim

inatla ,hırsla

tükenmeden

dışarda yağmur yağıyor

ortalık zifiri karanlık

görülen tek şey

dokunabildiğin 

ama, hissedemediğin boşluk

dışarıda yağmur yağıyor

sele hiç bir zaman 

dönüş(e)meden

engelleri aş(a)madan

dışarıda yağmur yağıyor

ama;

birazdan dinecek

rıza aslan

Karacan / Ankara

04-04-2001', 'dışarıda yağmur yağıyor içimde kaybolmayan bir sis kurt dumanlı havayı severmiş bende... dışarıda yağmur yağıyor sicim, sicim inatla ,hırsla...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dumanli-havayi-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tali Bir Akşamın Tılsımı', 'tali-bir-aksamin-tilsimi-i-smail-aykanat-v0w36', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tali bir akşamın tılsımı

biçti çıkışlarımı

aldım ardına serdim hayta zamanlarımı

yer ve gök geri verdi nihayetsiz andımı

şimdi kehribar günler yıkılıyor üstüme

yürürdü duruşları ıslatırdı güneşi

her şey canım kadar yakındı bize

ve leylanın ayakları değince denize

yoksa yalancı mıydı kum saati

kör bir fener gibi yanıp sönen

tali bir akşamın tılsımı', 'tali bir akşamın tılsımı biçti çıkışlarımı aldım ardına serdim hayta zamanlarımı yer ve gök geri verdi nihayetsiz andımı şimdi kehribar günl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tali-bir-aksamin-tilsimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Yaşamaların Şiiri', 'uzak-yasamalarin-siiri-i-smail-aykanat-tkr3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nehirleri yüklesen saçlarıma

ölümü de önüme katarım bir gün

şu üç beş kelime için 

kaç kez atıldım bilsen sokaklarına

uzak yaşamaların şiirine dök beni

yüzünün yalımında otağ kurduran ney/i

çağır içimdeki şiiri dirilten çağı

evinden döner gibi eve giden gelini

mercan susuşlarından geçir

çün sana verdim bütün dolunayları

saçlarında aradım kaybettiğim yolları

geceye yorumladım zülüflerini senin

eski ustalardan kalma bir ah

ile gel', 'nehirleri yüklesen saçlarıma ölümü de önüme katarım bir gün şu üç beş kelime için  kaç kez atıldım bilsen sokaklarına uzak yaşamaların şiiri...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzak-yasamalarin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal Oldu', 'hal-oldu-erhan-eker-di0i3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana düşte rastladım gönlümün gül çağında

Yaşanıp gitti demler hatıran hayal oldu

Bir sevdanın peşine koştum Kaf Dağında 

İnleyen çırpınışlar dillerde masal oldu

Seni aradım günler günleri kovaladı

Gönül gönül gezindim gönlüme bir hal oldu

Gitmedi yüreğimden kaldı sevdanın tadı

Ne ölüm haram oldu ne yaşam helal oldu

Şimdi yükselir sesim çığlık çığlık nerdesin

Elçim oldu turnalar elçime zeval oldu

Ben bir garip beklerim seni gurbet ellerde

Gülmedin ızdırabım mecnuna misal oldu...

                                 1997', 'Sana düşte rastladım gönlümün gül çağında Yaşanıp gitti demler hatıran hayal oldu Bir sevdanın peşine koştum Kaf Dağında  İnleyen çırpınışla...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hal-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazap', 'gazap-erhan-eker-78d4o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bağrımı deldi hıncı

Kalbimde dost kılıncı

Bilmemki kaçıncı

Ellerinin gazabı

Yükseldi dost feryadı

Kalmadı dünya tadı

Ağlayanlar ağladı

Çektilerde azabı

Coşmuşta deli deli

Akar gözlerin seli

Bağrımızı deleli

Çökmüştür ızdırabı

Yağmurlara bir kol at

Kuruyan ruhu ıslat

Badenin tadı vuslat

İçelim aşk şarabı

Erhan bir dem istersin

Demleri kim göstersin

Düşler gerçeğe ersin

Canlansın dost serabı

         (26-08-1998)', 'Bağrımı deldi hıncı Kalbimde dost kılıncı Bilmemki kaçıncı Ellerinin gazabı Yükseldi dost feryadı Kalmadı dünya tadı Ağlayanlar ağladı Çekti...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gazap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyormusun', 'bilmiyormusun-erhan-eker-58n4m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİLMİYORMUSUN

Kanlı yaşımı

Silmiyormusun

Dertli başımı

Bilmiyormusun

Gönlün baharı

Ömrümün varı

Ettiğim zarı

Bilmiyormusun

Hep yane yane

Muma pervane

Oldum divane

Bilmiyormusun

Olmam amade

Senden ziyade

Aşkın bir bade

Bilmiyormusun

Eyleme cefa

Sürelim sefa

Sevdiğim vefa

Bilmiyormusun

Garip Erhan''ım

Sana hayranım

Geçti devranım

Bilmiyormusun

          1997', 'BİLMİYORMUSUN Kanlı yaşımı Silmiyormusun Dertli başımı Bilmiyormusun Gönlün baharı Ömrümün varı Ettiğim zarı Bilmiyormusun Hep yane yane Mum...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilmiyormusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-erhan-eker-ex43m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEVDİĞİM

Eser gönlüme seherden

Ilık bir yel sevdiğim

Çabuk ufuktan şafak

Sökmeden gel sevdiğim

Aşkın düzenim bozan 

Aşkınla oldum ozan

Dertli gönlüme hazan

Çökmeden gel sevdiğim

Erhan yaslı ezeli

Ruhum dertle bezeli

Dalımdan son gazeli

Dökmeden gel sevdiğim

        1997', 'SEVDİĞİM Eser gönlüme seherden Ilık bir yel sevdiğim Çabuk ufuktan şafak Sökmeden gel sevdiğim Aşkın düzenim bozan  Aşkınla oldum ozan Dertl...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdigim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maral', 'maral-erhan-eker-88e7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey bozkırların maralı

Gel görki gönlüm yaralı

Aşkı sineme saralı

Mecnun oldu artık adım

Çöllerde seni aradım

Ne yerdesin ne gökte

Neredesin tek muradım

Sevda bu içi dışı dert

Sillesi yıldırımdan sert

Dönenler olurmuş namert

Böyle yazmışlar kuralı

Dönüş yolları kapalı

Ya benimsin ya toprağın

Ey! Bozkırların maralı

İste dağları deleyim

İste çölleri eleyim

İste kuş olup geleyim

Sana ezelden talibim

Ne mağlub nede galibim

Anla perişan halimi

Sensiz cihanda garibim

Kehribar saçında saklı

İlkbahar tacında saklı

Görenin kaybolur aklı

Yumşacık bebk gibisin

Kırda kelebek gibisin

Sensiz cihanı neyleyim

Sanki bir melek gibisin

                 1995', 'Ey bozkırların maralı Gel görki gönlüm yaralı Aşkı sineme saralı Mecnun oldu artık adım Çöllerde seni aradım Ne yerdesin ne gökte Neredesin ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/maral-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-erhan-eker-t9dhg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar

İnce ince yağan kar

Bana seni anlatır

Gözümden akan yaşlar

Bana seni anlatır

Hefiften eser rüzgar

Soğuk yüzüme çarpar

Yalnız kalmış sokaklar

Bana seni anlatır

Gönlüm düşünü gözler

Ruhum yüzünü özler

Karda belirsiz izler

Bana seni anlatır

Saçında en hoş sarı

Kavurur bakışları

Bu zemheri kışları

Bana seni anlatır

Kar gibi tenin beyaz

Gülüşünle gelir yaz

Uzağında bir ayaz

Bana seni anlatır

Kanlı yaşlarım pınar

Donupta olsam çınar

Bir kuş dalıma konar

Bana seni anlatır

               1996', 'Kar İnce ince yağan kar Bana seni anlatır Gözümden akan yaşlar Bana seni anlatır Hefiften eser rüzgar Soğuk yüzüme çarpar Yalnız kalmış soka...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-erhan-eker-i6h0j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SENSİN

Taşlı ömür yollarının

En narin toprağı sensin

Asırlık kuru dalların

Yeşeren yaprağı sensin

Bin dert ile talan olmuş

Efsanesi yalan olmuş

Aşkın ile nalan olmuş

Ömrümün gül çağı sensin

Düş gerçeğe döndüğü an

Efkar közü söndüğü an

Kopar benden bir çağlayan

Suların kaynağı sensin

Erhan bir gün dolar süren

Çıkar kim düşman kim yaren

Ezelden ebede süren

Zamanın sancağı sensin

                 1996', 'SENSİN Taşlı ömür yollarının En narin toprağı sensin Asırlık kuru dalların Yeşeren yaprağı sensin Bin dert ile talan olmuş Efsanesi yalan ol...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Yarin Bahçesinde', 'zalim-yarin-bahcesinde-erhan-eker-4b3wl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zalim yarin bahçesinde

Onsuz boştum onla doldum

Bir sevdalı gönül oldum

Aşkla şeyda bülbül oldum

Zalim yarin bahçesinde

Ona kanat ona koldum

Gülşeninde ayrık oldum

Hazan vurdu şimdi soldum

Zalim yarin bahçesinde

Yandı gönül közler kaldı

Bir bakışan gözler kaldı

Güle sinmiş sözler kaldı

Zalim yarin bahçesinde

Ebedimdi ezel oldu

Bir gün ömre bedel oldu

Tüm yapraklar gazel oldu

Zalim yarin bahçesinde

Keder ile heder oldum

Bu dünyadan gider oldum

Evvel güldüm şimdi soldum

Zalim yarin bahçesinde

                    1996', 'Zalim yarin bahçesinde Onsuz boştum onla doldum Bir sevdalı gönül oldum Aşkla şeyda bülbül oldum Zalim yarin bahçesinde Ona kanat ona koldum...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zalim-yarin-bahcesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Gelir', 'dar-gelir-erhan-eker-425fq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DAR GELİr

Hasretinle alevlenip kavruldum

Rüzgarınla dalgalanıp savruldum

Özlem dolu gecelerde dert buldum

Talan oldum yüreğimden zar gelir..

Bir zamanlar mesut idim pas tuttum

Uçup giden gençliğime yas tuttum

Yıllar oldu gülmek nedir unuttum

Ben kaçtıkça üserime har gelir

Yollarında tükendi tüm kudretim

Sana karşı hiç doğmadı nefretim

Ey vatanım memleketim hasretim

Gurbet elde ulu dağlar dar gelir

Üzerimde pare pare taş yıllar

Gözlerimde damla damla yaş yıllar

Yakmış hasret ateşini fasıllar

Yüreğime sahralardan nar gelir

Erhan derde karşı sinen açarsın

Gurbetlerde ilden ile kaçarsın

Sen sılana kavuşmadan naçarsın

Sanma sana bu gurbetten kar gelir

                        1995', 'DAR GELİr Hasretinle alevlenip kavruldum Rüzgarınla dalgalanıp savruldum Özlem dolu gecelerde dert buldum Talan oldum yüreğimden zar gelir.....', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dar-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-erhan-eker-8b2kt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarhoş

Yaşamımda halka halka

Hatıralar sıralanır

Yollarında düşe kalka

Sarhoş kalbim oyalanır

Ahu zarım vardı aya

Bitmez dertler saya saya

Aman bilmez bu sevdaya

Gönlüm her an yakalanır

Kederim tek hatırası

Yandı sönmez aşk çırası

Şu gönlümün ihtirası

Yalanlarla parçalanır

                     1995', 'Sarhoş Yaşamımda halka halka Hatıralar sıralanır Yollarında düşe kalka Sarhoş kalbim oyalanır Ahu zarım vardı aya Bitmez dertler saya saya A...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarhos-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyu', 'uyu-erhan-eker-17ig1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UYU

Gece sessizlik ve uyku

Bürür gözlerimi inceden

Bir kuytu

Sıyırır düşünceden

Artık ipler koptu

Yolar meltem

Ilık bir yel..

Ötelerden tel tel

Okşar gibi bir el

Susar her beste

Hep aheste aheste

Gözlerin tükenir feri,

Dertli dertli parlar ay...

Sanki bir peri

Oda dedimi hay hay

Gelde tut kiprikleri

Başka bir alem 

Çeker ağır ağır

Kulaklar sağır

Ararsan düşlerden çağır

Kalmışım bu heveste 

Hep aheste aheste

Bırak!..Burası iyi

Hülyalarda bir durak

Bozmasın kimse sessizliği

Bırak!

Burası iyi!

Başka bir dem

Hayal içinde,

Meyal içinde,

Sanki bir masal içinde,

Güller sunar deste deste

Hep aheste aheste

Leyla Mecnun yanyana

Kerem ile Aslı...

Aşk içerler kana kana,

Bu bir sevda faslı

Görünmez ucu bucağı

Değilsen yaslı

Sende yaşa bu çağı,

Açıp bir düş kucağı

Kaybol bu seste

Hep aheste aheste

****', 'UYU Gece sessizlik ve uyku Bürür gözlerimi inceden Bir kuytu Sıyırır düşünceden Artık ipler koptu Yolar meltem Ilık bir yel.. Ötelerden tel ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Eker']::text[], 8.5, '{"poet":"Erhan Eker","poet_slug":"erhan-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/uyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Şair ile Söyleşi', 'bi-sair-ile-soylesi-yusuf-sabri-bagriacik-ya5wk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bi şaire sormuşlar nerede oturuyorsun diye

elini göğe uzatarak

ve tek başına parlayan bi yıldızı işaret ederek

şurada, gördüğün tek yıldızda demiş

daha da merak etmişler ve sormuşlar

nasıl gidiyorsun oraya

soğuk kanlılıkla şair

orasını bi ben bilirim. 

bi de evime gelen kadınlar demiş

bi şaire sormuşlar nerede oturuyorsun diye

yine deminki gibi,

aha şuradaki yıldızda demiş

tek başına var ya bi tane...

bunları söylemesiyle 

bulutlar siper olmuş yıldıza

hani demişler 

bahsettiğin yıldız nerede

evimi bi ben görürüm 

bi de bana gelen kadınlar demiş şair.

bi şaire sormuşlar nerede oturuyorsun diye

aha şuradaki yıldızda demiş

nasıl olur demişler

nasıl taşınılır oraya

adam cevap vermiş

her şeyi emlakçı ayarladı

                            (Ocak 2001, istanbul)', 'bi şaire sormuşlar nerede oturuyorsun diye elini göğe uzatarak ve tek başına parlayan bi yıldızı işaret ederek şurada, gördüğün tek yıldızda...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bi-sair-ile-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklar', 'isiklar-yusuf-sabri-bagriacik-lr2a3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ışıklar çapraz geçiyordu gözlerimden

bakıyım dedim onlara

acayip oldu gözlerim, kamaştı

bakarsam senden başka bi ışığa,

elbette

tanrı da beni böyle cezalandırır.

	(Ocak 2001, istanbul)', 'ışıklar çapraz geçiyordu gözlerimden bakıyım dedim onlara acayip oldu gözlerim, kamaştı bakarsam senden başka bi ışığa, elbette tanrı da ben...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/isiklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-yusuf-sabri-bagriacik-x0uyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'son sözü söyle, uyuyacağım

düşüncelerimle beraber

acaba istiyor muyum, 

istemiyor muyum diyerek

imkansız olan aşktır derim her zaman

bi bulmaca var önümde, 

çözmekten korkarım.

çözdükten sonra,

kalan harfleri 

soldan sağa doğru 

sıralı bi biçimde okuduğum da

yazılanları yaşayamamaktan korkarım

anlamamaktan korkarım seni

biliyorum bu yazılardan sonra 

şiddetleneceksin

arzulayacaksın

ama bu gecelik,

son sözü söyle

		uyuyacağım...

	(Ocak 2001, istanbul)', 'son sözü söyle, uyuyacağım düşüncelerimle beraber acaba istiyor muyum,  istemiyor muyum diyerek imkansız olan aşktır derim her zaman bi bulm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-soz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukların Olmalı', 'cocuklarin-olmali-munevver-armay-pdhuf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyada en mutlu yer

Çocukların yüreği olmalı

En güzel bakan göz onların

Doğruyu söyleyen dil onların olmalı

Sevgiyle öpen en sıcak dudak

En güzel kokuyu duyan burun

Onların olmalı.

Özgürlüğün rüzgarıyla dalgalanan saç

Sadece sevince dökülen yaşları olmalı

Geleceğe kalkan el onların

Zulme boyun eğmeyen baş onların olmalı

En doğru yere giden ayak onların

En güzeli bulan düşünce onların olmalı

Dünyada güzel olan her şey

Çocukların olmalı.', 'Dünyada en mutlu yer Çocukların yüreği olmalı En güzel bakan göz onların Doğruyu söyleyen dil onların olmalı Sevgiyle öpen en sıcak dudak En...', ARRAY['Türk Edebiyatı','Şiir','Münevver Armay']::text[], 8.5, '{"poet":"Münevver Armay","poet_slug":"munevver-armay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuklarin-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkek Erkeğe', 'erkek-erkege-tayfun-yahsi-5fup6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şişe şarap 

Ve bir kaç haydar

Bugün kızlar gelmesin

İçelim ölene kadar...

Hani diyordun ya

Geçmiş günler sabaha kadar

Ya ne kadar sürecek

Geç kalan şu bahar

Aşk demiştin, hatırlar mısın

Yalanın diğer adı

O yok işte, beklemede

Denizin bile kalmadı tadı

Kucakla beni ölüm

Son seferim kursağımda

Bugün geçmişten bir gün olsa da

Devamı yok nasılsa...

Kaç mecnun var altında

kaç ferhat için yüreklisin

Ya aynalardan fışkıran görüntü

Ben bu isem sen kimsin', 'Bir şişe şarap  Ve bir kaç haydar Bugün kızlar gelmesin İçelim ölene kadar... Hani diyordun ya Geçmiş günler sabaha kadar Ya ne kadar sürece...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yahşi']::text[], 8.5, '{"poet":"Tayfun Yahşi","poet_slug":"tayfun-yahsi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erkek-erkege-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atilla Güner''e', 'atilla-guner-e-yusuf-sabri-bagriacik-51qgd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'köşeyi döndüğüm de

upuzun bir cadde çıktı karşıma 

dokuz tane lambası vardı

ve de dokuz tane ağacı

neydi acaba bu dokuzun kerameti

sanki dokuz satır laf anlatacak gibiydi

sonradan fark ettim 

caddeyi...

	  dokuz dakikada yürüdüğümü.

                       (Aralık 2000, istanbul)', 'köşeyi döndüğüm de upuzun bir cadde çıktı karşıma  dokuz tane lambası vardı ve de dokuz tane ağacı neydi acaba bu dokuzun kerameti sanki dok...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/atilla-guner-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan', 'uyan-resul-bal-dxfln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyan ey halkım !!!!!

Kaldır başını 

Sana yapılan zulmü gör

Onlar bize karşı kör

Uyan ey halkım 

Eğme başını

Verme bir avuç toprağını taşını

Gerekirse kurban et yaşamını

Uyan ey halkım 

Kır esaret zincirini

Geçir prangayı ayaklarına

Bize zulmeden görsün zulmü

Uyan ey halkım

Uyumanın sırası değil

Özgürlük zamanı gelip çatmış

Kalk yürü özgürlüğe

Uyan ey halkım

Nehir nasıl denize akarsa

Güneş nasıl dağların arasından doğarsa

Sende yürü katıl özgürlük kervanına', 'Uyan ey halkım !!!!! Kaldır başını  Sana yapılan zulmü gör Onlar bize karşı kör Uyan ey halkım  Eğme başını Verme bir avuç toprağını taşını ...', ARRAY['Türk Edebiyatı','Şiir','Resul Bal']::text[], 8.5, '{"poet":"Resul Bal","poet_slug":"resul-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdam Sehpasında Yürüken', 'i-dam-sehpasinda-yuruken-resul-bal-c5ktf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimde iki damla yaş 

Elimde ucu kırık bir kalem

Önümde eski bir kağıt 

İçimi döküyorum arkadaş

İdam sehpasına yürürken 

Arkamda iki damla göz yaşı 

Boynu bükük bir kalem

İçimi döktüğüm bir kağıt parçası

Bırakıyorum arkadaş

Suçum suçlu doğmakmış

Cezası ölümmüş

İdam sehpasına yürürken

Arkamda sevdiklerim ağlarken

Doğduğuma isyan ediyorum arkadaş

Doğduğum anda anlıma 

Suçlu damgası vurulmuş

Ellerim ayaklarım zincirlenmiş

İdam sehpasına yürürken

Düşmanlarım sevinirmiş arkadaş

Cellat bekler boynuma 

İpi geçirmek için

Suçlu diyenler bekler

Ölmemi görmek için arkadaş

Korkmuyorum ölmekten

İstemem celladı

Yağlı ilmiği kendim geçiririm boynuma

Siz sadece bir tekme vurun 

Altımdaki sehpaya

Kapamayın gözlerimi

Son bir defa göreyim arkadaşımı

Senin kaderinde benim gibi olmasın 

Kaç kurtul be arkadaş......', 'Gözlerimde iki damla yaş  Elimde ucu kırık bir kalem Önümde eski bir kağıt  İçimi döküyorum arkadaş İdam sehpasına yürürken  Arkamda iki dam...', ARRAY['Türk Edebiyatı','Şiir','Resul Bal']::text[], 8.5, '{"poet":"Resul Bal","poet_slug":"resul-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/idam-sehpasinda-yuruken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Kalmak', 'sensiz-kalmak-bulent-erkigun-1d4wg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her zaman ki gibi askerliği düşünüyorum.

Sensizlik bir mızrak gibi saplanacak kalbime.

O son anımızı düşünüyorum,

O seni koyup gidişimi,

İlk defa bu kadar üzüldüm dünyaya geldiğime

Askerlik! Kaçınılmaz son,

O soğuk kelime bir gün ucuz bir fahişe gibi koynuma girecek,

Bedenimde gezinecek pis ve iğrenç elleri,

Vücudumu saracak.

Seni bırakıp gitmenin hüznünü ben yaşarım,

Çünkü ben seninle bildim kendimi,

Sende sevdim,

Senin yanında, seninle değerlendi kısıtlı zamanlarım.

Ne acı gün kadehlerin boş kalması,

Şarkıların yarım,

Benim korkum askerlik değil,

Seni yalnız bırakmak, 

Sensiz kalmak.', 'Her zaman ki gibi askerliği düşünüyorum. Sensizlik bir mızrak gibi saplanacak kalbime. O son anımızı düşünüyorum, O seni koyup gidişimi, İlk...', ARRAY['Türk Edebiyatı','Şiir','Bülent Erkigün']::text[], 8.5, '{"poet":"Bülent Erkigün","poet_slug":"bulent-erkigun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensiz-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-ayhan-birinci-f1fn2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah penceremden seni selamlar

     İşe giderim,mutlu.

     İşteyim,işte!

     Aklım hep o gülüşte.

     Zaman geçmek bilmez,işler yetişmez;

     Çünkü aklım hep o gülüşte.

     N''olur aşkım, beni bana bırak

     Birgünde hakkıyla çalışayım, ben işte!

     Yok yok, sakın ha beni sensiz bırakma,

     Sen şakayı seversin, beni yanlış anlama emi!..

     Akşamlar negüzel seninle,gözgöze.

     Yüreğim bir kuş olur,uçar gönlüne.

     Varsın bu gece de uykusuz kalayım,

      N''olcak sanki,sen karşı pençerede.

      Keşke hiç sabah olmasa,gözlerim kalsa sende

      Kalbim o sıcacık aşık ellerinde...', 'Her sabah penceremden seni selamlar      İşe giderim,mutlu.      İşteyim,işte!      Aklım hep o gülüşte.      Zaman geçmek bilmez,işler yeti...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Birinci']::text[], 8.5, '{"poet":"Ayhan Birinci","poet_slug":"ayhan-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-burhan-kamali-c0pfq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bağırsam sesimi duymaz mısın

Çığlığım bir bulut olsa

Yağmur olup başına yağsa

Sırılsıklam ıslanmaz mısın

.

Uzatsam elimi tutmaz mısın

Ellerim bir avuç toprak olsa

Üzerine karlar yağsa

kardelen olup açmaz mısın', 'Bağırsam sesimi duymaz mısın Çığlığım bir bulut olsa Yağmur olup başına yağsa Sırılsıklam ıslanmaz mısın . Uzatsam elimi tutmaz mısın Elleri...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sen Sen', 'sen-sen-sen-yavuz-bulent-bakiler-2uy8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dağbaşı yalnızlığı yaşıyorum yeniden., 

Dağbaşı yalnızlığı ölümden beter. 

Hiç kimse aramasa sormasa beni 

Sen gelsen yeter.. 

Huzur ellerinin güzelliğidir. 

Gözlerin karşımda mutluluk denizi. 

Her sabah soframızda ekmeğimizi 

Sen bölsen yeter.. 

Yüreğim seninle yaylalar kadar serin 

Ne bir çizgi hasret, ne bir nokta gam 

Yayla dumanı gibi gözlerime her akşam 

Sen dolsan yeter.. 

Bende çaresizlik sonsuz kördüğüm. 

Bende sabır sende naz.. 

Gündüzünden vazgeçtim düşümde biraz 

Bir yüz görümlüğü sen olsan yeter.. 

Duymasa da hiç kimse şâir gönlümün, 

Sende karar kıldığını... 

Ve içimin şerha şerha yarıldığını, 

Sen bilsen yeter.. 

Bir gün duysan bittiğimi, tükendiğimi.. 

Çıkıp gelsen uzaklardan korkulu ürkek.. 

Bir incecik dal gibi üzerime titreyerek, 

Eğilsen yeter...........', 'Bir dağbaşı yalnızlığı yaşıyorum yeniden.,  Dağbaşı yalnızlığı ölümden beter.  Hiç kimse aramasa sormasa beni  Sen gelsen yeter..  Huzur ell...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-sen-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zühtü', 'zuhtu-mustafa-turker-lsgr1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimsesiz bir garipti Zühtü

Samanlıktan kaldıramadı samanı

Dünya onun için büyük bir yüktü

Çünkü Zühtü samanın altında kaldı', 'Kimsesiz bir garipti Zühtü Samanlıktan kaldıramadı samanı Dünya onun için büyük bir yüktü Çünkü Zühtü samanın altında kaldı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Türker']::text[], 8.5, '{"poet":"Mustafa Türker","poet_slug":"mustafa-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zuhtu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçkin', 'seckin-ayhan-birinci-b4qx4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu bir kalbin var , biliyorum.

Eskimeyen dostluğun var, eyvallah onuda.

Çiçekler gibi güzelliğin var,eee bişey mi dedik..

Kendinden çok seni seven bir sevgilin var, ama bilmiyorsun.

İçindeki aşk ateşi adamcağızı günbe gün eritirken

Ne suçu var sanki, senden bir avuç içi sevgi istiyor diye?', 'Sevgi dolu bir kalbin var , biliyorum. Eskimeyen dostluğun var, eyvallah onuda. Çiçekler gibi güzelliğin var,eee bişey mi dedik.. Kendinden ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Birinci']::text[], 8.5, '{"poet":"Ayhan Birinci","poet_slug":"ayhan-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seckin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-burhan-kamali-0mbps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde saklı kaldı 

Naftalin kokulu kelimeler

Kapağı açılmamış sandıkta gibiydiler

Gün ışığınada hasrettiler

Şimdi her an gitti gidecekler', 'İçimde saklı kaldı  Naftalin kokulu kelimeler Kapağı açılmamış sandıkta gibiydiler Gün ışığınada hasrettiler Şimdi her an gitti gidecekler...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kelimeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaldir', 'hayaldir-bir-sair-ml6a8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden ayrılmak bir ölüm gibi

Sensiz yaşamak zulümden beter

Bir gün sana kavuşmak

Bir hayaldir gelir geçer....', 'Senden ayrılmak bir ölüm gibi Sensiz yaşamak zulümden beter Bir gün sana kavuşmak Bir hayaldir gelir geçer.......', ARRAY['Türk Edebiyatı','Şiir','Bir Şair']::text[], 8.5, '{"poet":"Bir Şair","poet_slug":"bir-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayaldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu musun Züleyha', 'mutlu-musun-zuleyha-yusuf-sabri-bagriacik-adrhx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece aradı züleyha 

uzun zaman olmuştu, aramayalı

aradığın da gülüyordu

ve kapatana kadar da güldü

güzeldi gülmesi

fakat, 

onu güldüren ben olamadığım için 

ilk defa o, gülerken kahroluyordum.

tam kendimden geçiyordum aradı

		[züleyha

sesine susamıştım

gittim içeriden bi bardak aldım

bi bardaklık ses aldım

bardağın içine başka sesler de döküldü.

ışık tam sönerken aradı, züleyha

bende ki güç biterken,

içimdeki züleyha, uykuya dalarken...

bi anda aradı

		[züleyha

gülüyordu, güldürülüyordu

her gülüşün de ben,

bi çivi daha yutuyordum,

bi kez daha deydiriyordum göğsümü,

buz gibi taşa...

sebebi ben olmadığım 

her gülüşün de,

eziyet çekmek istiyordum.

ateş parçaları aradım sabaha kadar

ki ellerini içine sokup

seni düşünmek için

gülüyordun, güldürülüyordun züleyha

işte bu yüzden her gülüşün de ben,

bi çivi daha yutuyordum

daha önce ki yuttuklarımı yok sayarcasına

işte be züleyha

bende ki aşk, 

böyle bi şey 

başka türlü bi şey

bi arka bahçede unutulan bi şey

bi salkım söğüdün altında kurumaya yüz tutmuş bi şey

bi uçurumun kenarından aşağıda ki denize bakan bi şey

tıpkı babası ile uçurumun kenarında hayal kuran kız çocuğu gibi

farklı hayalleri ve düşünceleri olan bi şey

bende ki aşk

             senin gibi bi şey züleyha.

                                        (Mart 2001, istanbul)', 'gece aradı züleyha  uzun zaman olmuştu, aramayalı aradığın da gülüyordu ve kapatana kadar da güldü güzeldi gülmesi fakat,  onu güldüren ben ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/mutlu-musun-zuleyha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Kurşun', 'uc-kursun-taylan-sanli-waopc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç Kurşun Olur Bu Sevda

Biri Benim Anlımda

Biri Senindir.

Kalanı Yüreğimin Sımsıcak Namlusunda

Bizi Ayıranları Beklemelidir.', 'Üç Kurşun Olur Bu Sevda Biri Benim Anlımda Biri Senindir. Kalanı Yüreğimin Sımsıcak Namlusunda Bizi Ayıranları Beklemelidir....', ARRAY['Türk Edebiyatı','Şiir','Taylan Şanlı']::text[], 8.5, '{"poet":"Taylan Şanlı","poet_slug":"taylan-sanli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uc-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Başı', 'dag-basi-orhan-veli-kanik-ynhwk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağ başındasın;

Derdin günün hasretlik

Akşam olmuş,güneş batmış

İçmeyipte ne halt edeceksin', 'Dağ başındasın; Derdin günün hasretlik Akşam olmuş,güneş batmış İçmeyipte ne halt edeceksin...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dag-basi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miladım Sensin', 'miladim-sensin-mesut-biyik-he6el', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gri bir sabahı bekliyordum

parmaklarımın ucunda dolaşarak

binlerce renk ve kokuyla geldin

bir yığın çarkıfelek

bir yığın açelya

ve tepeden tırnağa buluta kesmiş şebboylar gibi

geldin ve miladım oldun flora

yokken yoktu hayatın ne rengi ne kokusu

uçmaya kalksam kanatlarım kül

ve geldin

ve içimi bana doğru çevirip 

gösterdin apaçık

ve bana baharı getirdin

geldin ve

kendini bana sevdirdin

ve kendimi bana sevdirdin

seni yaşamak var artık

seni sevmek

sensiz yaşayamamak var

sen varsın

iyi ki varsın', 'gri bir sabahı bekliyordum parmaklarımın ucunda dolaşarak binlerce renk ve kokuyla geldin bir yığın çarkıfelek bir yığın açelya ve tepeden t...', ARRAY['Türk Edebiyatı','Şiir','Mesut Bıyık']::text[], 8.5, '{"poet":"Mesut Bıyık","poet_slug":"mesut-biyik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/miladim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-orhan-veli-kanik-d861e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Annemi ölmüş gördüm rüyamda

Ağlayarak uyanışımı hatırlattı bana,

Bir bayram sabahı

Gökyüzüne kaçırdığım balonuma bakarak

Ağlayışımı...', 'Annemi ölmüş gördüm rüyamda Ağlayarak uyanışımı hatırlattı bana, Bir bayram sabahı Gökyüzüne kaçırdığım balonuma bakarak Ağlayışımı......', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ruya-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar', 'ne-cikar-yusuf-polat-kw9cj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gider derim ki arkadasim bulutlara

  bir cocuk dogmus buyumus

  gider derim ki ey beyaz karlar

  buz tutmus gol, sari kir cicekleri

  gider derim ki mezarsiz olu

  bu gokyuzu, bu sehir, bu yasam

  neden bu kadar aci dolu

  gider derim ki arkadasim daglara

  denizler sarhos olur mu hic

  insan ekilir mi topraga

  neden eksik olmaz huzun yuregimizde

  neden ozlem kokar gokyuzu

  gozler kapaliyken dunya sonsuzdur arkadas

  gormesende toprak ordadir, hasret orda

  ordadir cicekler kokusunu duymasan da.

  ama unutacaksin arkadasim,

  ilk cicek aldigin gunu.

  ilk sevdam, ilk optugum kiz,

  cocuklugum, hic yasamadigim gencligim

  hani nerde demeyeceksin.

  bir de yesile bakma arkadasim

  yesile bakma hic.

  bakma ama

  yine de yesil kalan

  en azindan yesermeye calisan 

  bir seyler olsun hayatinda

  bir de kocaman yuregin olsun,

  dostun olsun bir tane seni anlayan.

  eger sahipsen tum bunlara

  dimdik ayakta durabiliyorsan eger

  varsin yureginde acilar olsun

  ne cikar...

  dedim ya arkadasim

  gozyaslari biraz sicak olur 

  hasret icin dokuluyorsa.

  yine de seveceksin arkadasim

  iyiyle kotuyu ayiracaksin ama

  bir de dikkat et bahara;

  baharda ayrilik zor gelir adama...

  hani bir kus gelir konar pencerene

  sevda getirmistir bakma sen ona.

  aci bu,

  ben de alisirim aciya demeyeceksin

  bir kalem mutlaka bulundur yaninda

  siir yazmam deme 

  siir de yazacaksin

  olacak sey degil ya

  bir gun kavusursan eger

  gider derim ki arkadasim yildizlara

  bir cocuk dogmus buyumus

  gider derim ki ey dertli cesme

  ceviz dali,

  gunese donmus ay cicekleri

  gider derim ki catlamis toprak

  bir cocuk dogmus buyumus

  ve sonra isik her taraf.

  ama bu hava, bu ruzgar

  bu yollar, bu Ankara

  ve bu insanlar

  yuregime agir gelen geceler

  bilirim aci her zaman yanimdadir

  benimle beraber yudumlar yasamimi.

  ama dostum 

  yine de bir umit olsun yureginde

  kalbini sunabilecegin bir dostun olsun

  eger sahipsen bunlara

  acilara ragmen unutmamissa dudaklarin

  gulumsemeyi

  varsin yueginde acilar olsun

  NE CIKAR!...

  Yusuf POLAT', 'gider derim ki arkadasim bulutlara   bir cocuk dogmus buyumus   gider derim ki ey beyaz karlar   buz tutmus gol, sari kir cicekleri   gider ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Polat']::text[], 8.5, '{"poet":"Yusuf Polat","poet_slug":"yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/ne-cikar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazı', 'yazi-omer-aksoy-jz9x8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk aşk dedikleri nedir

Kumsala yazılan bir yazı

Dalgaların sildiği

Ben öyle bir aşk biliyorum ki

Silen dalgaların da bildiği', 'Aşk aşk dedikleri nedir Kumsala yazılan bir yazı Dalgaların sildiği Ben öyle bir aşk biliyorum ki Silen dalgaların da bildiği...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aksoy']::text[], 8.5, '{"poet":"Ömer Aksoy","poet_slug":"omer-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizce', 'sessizce-munevver-armay-bw5kb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce aynalar terketti

Sonra başında uçan kavak yelleri

Ne zaman geriye dönüp yakalamaya çalıştıysa

Ellerinden kayıp gidenleri

Dikenli tellere takıldı parmakları

Uçurtmasını hiç göremedi

Ki masmaviydi gökyüzü gibi

Önce aynalar terketti

Gülen gözlerini', 'Önce aynalar terketti Sonra başında uçan kavak yelleri Ne zaman geriye dönüp yakalamaya çalıştıysa Ellerinden kayıp gidenleri Dikenli teller...', ARRAY['Türk Edebiyatı','Şiir','Münevver Armay']::text[], 8.5, '{"poet":"Münevver Armay","poet_slug":"munevver-armay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sessizce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlı Bir Ay Vaktiydi Gözlerin', 'yildizli-bir-ay-vaktiydi-gozlerin-mesut-biyik-isnky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bildiğim bütün şarkıları söylerdim sana

sen bana yalnızca bakardın

ve susardın derin uçurumlar gibi

saçlarının kokusu sinerdi tüm şehre

tüm şehir saçlarından geçerdi bütün bir gece

hayat bir tutamdı saçların gibi

ve ben ne yapsam kendimi tutamazdım

ağır bir yokuşu koşmaya benzerdi ellerini tutmak

gözlerine bakmak neler anlatırdı anlatamazdım

yıldızlı bir ay vaktiydi gözlerin

şimdi yıldızlı bir gökyüzü kadar uzaksın bana

bir otoban geçiyor tam orta yerimizden

ayırıyor bizi bu şehir gibi

bu şehir gibi öksüzlük çekiyoruz', 'bildiğim bütün şarkıları söylerdim sana sen bana yalnızca bakardın ve susardın derin uçurumlar gibi saçlarının kokusu sinerdi tüm şehre tüm ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Bıyık']::text[], 8.5, '{"poet":"Mesut Bıyık","poet_slug":"mesut-biyik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yildizli-bir-ay-vaktiydi-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vız Gelecek', 'viz-gelecek-omer-hayyam-uwc6j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce aynalar terketti

Sonra başında uçan kavak yelleri

sevgiyle dolu olsun ağzına dek.

Bizim deftere adın hele bir yazılsın, kardeş,

o zaman cennet de vız gelecek sana,

göreceksin cehennem de vız gelecek.', 'Önce aynalar terketti Sonra başında uçan kavak yelleri sevgiyle dolu olsun ağzına dek. Bizim deftere adın hele bir yazılsın, kardeş, o zaman...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/viz-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-nalan-kazazoglu-dxegy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tesadüfen bulunduğumuz mekanlarda, anlaşamıyoruz;

farklı, farklı....

Birarada olmak güçlük,eziyet..

Dura kalka giden insanlar;

türlü, türlü...

Sağır, dilsiz mi olaydım;

duvar, duvar.....', 'Tesadüfen bulunduğumuz mekanlarda, anlaşamıyoruz; farklı, farklı.... Birarada olmak güçlük,eziyet.. Dura kalka giden insanlar; türlü, türlü....', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duvar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümlenmez', 'olumlenmez-i-lhan-tulman-zh35s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siz şimdi bu yalnızlığı da bilirsiniz

O sabah erguvani değen yağmurdunuz

Çılgın gibi gökkuşağına

  Öyleydiniz...

  Ay upuzun bir ağıta.

Dünyanın batan iki kentinden 

Birinde yaşamıştınız

Ölümler öğretip

Herşeyimizi anılara

  Öyleydiniz..

    Ateş

       Kül

         ve 

           Duman

Babamın saçları bahardır şimdi....', 'Siz şimdi bu yalnızlığı da bilirsiniz O sabah erguvani değen yağmurdunuz Çılgın gibi gökkuşağına   Öyleydiniz...   Ay upuzun bir ağıta. Düny...', ARRAY['Türk Edebiyatı','Şiir','İlhan Tülman']::text[], 8.5, '{"poet":"İlhan Tülman","poet_slug":"i-lhan-tulman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olumlenmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-i-lhan-tulman-smb5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzünün çizgilerindeydim, geceydi

    ve bir çığlık yerleşmişti gözlerime

Bir çığlık ah, kör gözlerin üstünde 

  asılı ve yalnız

İnsan nedir ki zaten, insan

  telaşlar

    ve

    yalanlar 

Yüzünü geçiyorum çay kokusu öpüşlerle

Yüzünün çizgilerinde hayatım

Hayatımız..', 'Yüzünün çizgilerindeydim, geceydi     ve bir çığlık yerleşmişti gözlerime Bir çığlık ah, kör gözlerin üstünde    asılı ve yalnız İnsan nedir...', ARRAY['Türk Edebiyatı','Şiir','İlhan Tülman']::text[], 8.5, '{"poet":"İlhan Tülman","poet_slug":"i-lhan-tulman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ciglik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşaklar', 'usaklar-ayhan-birinci-oh0hq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selam ey sevgili vatan,

Çok uzaklardan sesleniyor,her gece hayalini kuran.

Afacan bir çocuk olsam yine, yeşil yaylalarında kuzular güden.

Her obada kızılağaç dalından çadırlar yapsam.

Avazım çıktığınca dağlara karşı türküler  söylesem.

Her gelen geçeni selamlayıp ekmek meyve yani bir şeyler  istesem.

Bir gürgen ağacının serininde uyusam, kuzularım kaybolsa ve saatlerce ağlasam.

Yaz gecelerinde lüksle balık avına çıkan o küçük çocuk şimdi  nerede?

Nerede, güz gecelerinde ellerinde soğan çuvallarından yapılmış filelerle bıldırcın tutan uşaklar?

Yok; hani göremiyorum yalın ayak futbol oynayan uşakları.

Artık üç kuruş için salyangoz toplayan uşaklar olmayacak mı?

Kış gecelerinde hurma ile ceviz yiyip etrafa bol gaz saçan uşaklar olmuş mudur acaba?

Baharda taze erikleri yiyip ishal olmuşsa uşaklar

Yazın; kiraz ,dut, kızılcık birde fındık yiyince nasıl hasta olmasın garibanlar.

Sema çikletlerin

Salı günleri annesiyle çarşıya gitmek için sabaha kadar  ağlamaz mı  artık uşaklar?

Nerede , söyleyin dostlarım nerede o sevimli bizim uşaklar?', 'Selam ey sevgili vatan, Çok uzaklardan sesleniyor,her gece hayalini kuran. Afacan bir çocuk olsam yine, yeşil yaylalarında kuzular güden. He...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Birinci']::text[], 8.5, '{"poet":"Ayhan Birinci","poet_slug":"ayhan-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/usaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hisset', 'hisset-akin-simsek-jg89q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiirimle bir buse yollasam hissedermisin

O loş ışıktaki bakışımla

En değerli varlığıma sana

Yaz güneşi gibi yakıcı bir buse

Şiirimle sana ulaşabilsem

Anlatabilsem çağlayan duygularımı

Varabilsem uzakta olan sana

Tutabilsem ellerini sarılabilsem

Bir an bir an olsun yeter

Razıyım yeterki sana ulaşabilsem

Anlıyormusun hissediyormusun beni

Şiirimle gönderdiğim dudağımı ellerimi

Ne olur hisset yanında olmasamda benliğimi

Yanımda olmasanda hissediyorum

Biricik sevgilim seni', 'Şiirimle bir buse yollasam hissedermisin O loş ışıktaki bakışımla En değerli varlığıma sana Yaz güneşi gibi yakıcı bir buse Şiirimle sana ul...', ARRAY['Türk Edebiyatı','Şiir','Akın Şimşek']::text[], 8.5, '{"poet":"Akın Şimşek","poet_slug":"akin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hisset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekizinci Mektup', 'sekizinci-mektup-umit-yasar-oguzcan-tg3xz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana çılgın diyorsun, seni sevdiğim için.

Yanılıyorsun, sevmek çılgınlık değil. 

Sevmek insan tarafımızı bulmamızdır bence. 

Biraz da yaklaşmamızdır Tanrıya zaman zaman.

Dünyada sevmeyenlere, sevemeyenlere acımalı. 

O, ot gelip, ot gidenlere acımalı. Sevebilen insan

kendini keşfetmiş insandır. Talihli insandır.

Çektiği bütün acılara rağmen; mutlu,

kıvançlı insandır o. Aşktır yücelten bizi ve

derinliğimiz aşktandır. Gerisi boş, yalan.

Aşksa, sevmektir. Durmadan, 

nefes alırcasına sevmektir.

Sevmakle sevilmek ayrı şeyler... Sevilmeyi

çoğaltmak, ona bir başka şekil vermek,

daha da yoğunlaştırmak onu, elimizde değil. 

Oysa ki, sevgimizi dilediğimiz gibi yoğurabilir, 

dilediğimiz şekli verebiliriz ona.

Derinlikse derinlik, yükseklikse yükseklik,

genişlikse genişlik. 

Sevmekle gücümüz var, irademiz, aklımız var.

Biz varız sevmekte. Sevmek, yaratmaktır bir bakıma.

Sevilmekse; yaratılmak...

Demek ki, biz seninle birbirimizi yaratıyoruz

durmadan. Sen beni yarattıkça güzelsin işte ve

ben seni yarattıkça güçlüyüm, daha bir insanım.

Beni sevmeseydin yine bir şey değişmeyecekti

benim için. Sen biraz eksik kalacaktın, 

biraz sen kaybedecektin. O kadar.

Şimdi insanların en güzeliyiz, en iyisiyiz elbette. 

Seviyoruz , seviliyoruz .

Sevgimi anlamadığın ve ona saygı göstermediğin

anda ölebilirim. Karşılık vermediğin anda değil.

Birbirimizi yeniden yaratmaya devam edelim.', 'Bana çılgın diyorsun, seni sevdiğim için. Yanılıyorsun, sevmek çılgınlık değil.  Sevmek insan tarafımızı bulmamızdır bence.  Biraz da yaklaş...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sekizinci-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıncı Mektup', 'altinci-mektup-umit-yasar-oguzcan-9569d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün bir yalnızlığa düştüm yine. Başımı

ellerimin arasına aldım, sessizce ağlamaya başladım .

Önümde yarıya gelmiş bir konyak şişesi ''beni iç''

diye fısıldıyordu, ''beni iç''. Sonra yalvarmaya başladı:

''Ne olur'' dedi ''ne olur haydi iç beni''.

Bir bardak doldurdum, tepeme diktim .

Şişe rahatladı, sustu. Hani ellerimiz birbirine

değince nasıl oluyorduk? İşte öyle oldum .

Hani bakışlarımız buluştuğu zaman, bir başka

türlü atması vardı yüreklerimizin. Onu hatırladım .

Sonra bir tren hareket etti. Sabahtı. Karşıkarşıyaydık .

Konuşuyorduk. Ben sevmek diyordum durmadan.

Gözlerim gözlerine soruyordu: ''seviyor musun?'' diye.

Hep evet diyordu gözlerin, ellerin, dudakların hep

evet diyordu. Oysa ki, bir çok hayır diyen insan vardı

çevremizde. Örneğin: bir çocuk hayır, diyordu, bir kadın, 

bir adam ve bir başkası, bir başkası hayır diyordu.

Hayır''lar arasında ezilmeğe mahkûmdu evet''lerimiz .

Tren ilerliyordu. Gözlerin gözlerime soruyordu 

ne olacak diye. Sigara üstüne sigara yakıyordum,

kadeh kadeh içki içiyordum, fakat bilmiyordum

ben de ne olacağını. Bizi sürükleyen bir akıntıydı.

Durduramazdık onu, hükmedemezdik ona. 

Bir anafora rastlayıp yok oluncaya kadar akıp

gidecektik işte. Peki anafor nerdeydi? Uzak mıydı? 

Belki çok yakındı kimbilir. Biz onu 

göremiyecektik. O, gözlerimizi kör ettikten sonra 

saracaktı bizi buz gibi kollarıyla.

Tren ilerliyordu. Pencereden deniz görünüyordu. 

Denize akşam güneşi vurmuştu. Renk renk

kayıklar gördük kıyılarda. Denize taş atan çocuklar

gördük. Uzakta bir balıkçı ağlarını topluyordu. 

Ve tren ilerliyordu. Kadere yaklaşıyorduk .

Bir alacakaranlık bastı zamanı. Gözlerim gözlerindeydi. 

Ellerini tuttum, titredin. Acı acı bir düdük öttü. 

Bir şeyler koptu içimizden.

Sonra tren durdu, indik, yollarımız ayrı ayrıydı. 

Şimdi, o gün verdiğin yalnızlığı yaşıyorum .', 'Bir gün bir yalnızlığa düştüm yine. Başımı ellerimin arasına aldım, sessizce ağlamaya başladım . Önümde yarıya gelmiş bir konyak şişesi ''ben...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/altinci-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Mektup', 'i-kinci-mektup-umit-yasar-oguzcan-y24z5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aramak... Ömür boyunca aramak... 

Yalnız seni aramak... Paslı teneke kutularda, küf kokan 

dolaplarda, çerçevelerde, tenhalarda, ağaç diplerinde,

sonra vapurlarda, trenlerde hep seni aramak. 

Belki bu şehirde değilsin. Ne çıkar? Seni arıyorum ya.

Belki de ayni sokakta evlerimiz, sabahları

beni görüyorsun işime giderken. 

Sonra akşamı bekliyorsun, alacakaranlığı... 

Beni bekliyorsun ya da bir başkasını, bir başkasını...

Hiç gel demiyeceğim sana. Aramak neredeyse 

ben oradayım. Ayaklarım ne güne duruyor? 

Yok yok birden karşıma çıkma. 

Kaç, saklan. Seni aramak istiyorum.

Git bu şehirden haydi git. Dağlara çık, o uzak dağlara.

Rüzgârların krallığında hüküm sür. Baktın ki oraya da 

geldim, yine kaç. Başını al, açıl denizlere.

Gemilerin en güzeli, en büyüğü dilediğin limana 

götürmeli seni, dilediğin yere demir atmalı. 

Ben küçük bir balıkçı kayığı ile

peşinden gelsem yeter. Seni arıyorum ya !

Bir yıl, beş yıl, on yıl değil; beşikten mezara kadar 

aramalı insan ama ne aradığını bilmeli. 

Yaklaşıp uzaklaşmalı aradığından. Okyanus dalgaları 

üstünde bir küçük tekne gibi alçalıp yükselmeli.

Yalınayak koşmalı yollarda, ayaklarını sivri taşlar kesip

kanatmalı. Çöllerden geçmeli yolu, yanmalı kavrulmalı. 

Sonra gözün alabildiğine ak, soğuk ülkelere düşmeli. 

Buzlar kırılmalı ayaklarının altında,

üstüne kar yağmalı.

Bir gün bulacaksam bile parça parça bulmalıyım seni.

Ayaklarını Afrika''dan getirip bir kâğıt üzerine 

yapıştırmalıyım, saçların Sibirya''da bir mabudun

gözleri olmalı, ellerin İtalya''da bir heykelin elleri.

Bulsam da seni parça parça bulmalıyım.

Yine de bir yerin eksik kalmalı.

Yeniden yollara düşmeliyim, onu aramalıyım.

Ve tam seni tamamladığım anda ölmeliyim.', 'Aramak... Ömür boyunca aramak...  Yalnız seni aramak... Paslı teneke kutularda, küf kokan  dolaplarda, çerçevelerde, tenhalarda, ağaç dipler...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ikinci-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Ağrısı', 'safak-agrisi-zeki-ergin-hbl62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ak türküler  düştü

gözlerine çocuğun

yarına dair

yarına dair

masallar dinliyor  şimdi

kafdağı

yedibaşlı devler değil

düşlerinde yaşayan

makineler

makineler

ağlatan değil

gürleyen

ak türküler düştü

gözlerine çocuğun

karaönlük

karatahta

kitaplar düştü

gözlerine çocuğun

kitaplar düştü

sonra

tüten fabrika

dönen volan

süren traktör düştü

gözlerine çocuğun

bahar sürgünü

temmuz güneşi

şafak ağrısı düştü

gözlerine çocuğun

sustu artık

uzun karakış ninnileri

yüreğini büyütüyor şimdi

davul zurna

grev türküleri

grev gözcüsü babası düştü

gözlerine çocuğun

ey mavi gözleriyle bir top güneş gibi

insanlığa bakan çocuk

doyumsuz bir  dünya

ak güvercinler istiyorsun

ve biliyorsun

dinecek şafak ağrıların bir gün

bahar sürgünleri

meyveye durduğu gün

_tek-met-iş şub76 sayı:46

_maden-iş 1kas79 sayı:109

_sevgiliye isyan yt:haz06', 'ak türküler  düştü gözlerine çocuğun yarına dair yarına dair masallar dinliyor  şimdi kafdağı yedibaşlı devler değil düşlerinde yaşayan maki...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/safak-agrisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem Var Hem Yoksun', 'hem-var-hem-yoksun-deniz-akpinar-nn46q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni anlatabilmek kendime

Issız bri adada su gibi susuzluğuma

Yakamoz yapan gecede,gecenin serinliğine,

Anlatabilmek  her açan gonca gül tanesine..

Uzanıpta tutacakmış gibi olursun ya

Doruğun tepesinde dururken yıldızlara

Uzatınca elini anlarsın  çok uzaklarda...

Hem varsın,hem yoksun yanımda....

Özlem çeken benin hasret sensin

Sevda beni gonca gülüm sensin 

Dal benim gonca gülüm sensin

Hayat benim nefesim sensin.......

                                                   05/04/2001 yenaya.....', 'Seni anlatabilmek kendime Issız bri adada su gibi susuzluğuma Yakamoz yapan gecede,gecenin serinliğine, Anlatabilmek  her açan gonca gül tan...', ARRAY['Türk Edebiyatı','Şiir','Deniz Akpınar']::text[], 8.5, '{"poet":"Deniz Akpınar","poet_slug":"deniz-akpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hem-var-hem-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Bir Kitaptı', 'genclik-bir-kitapti-omer-hayyam-svpbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençlik bir kitaptı, okuduk bitti;

Canım bahar geçti çoktan, kış şimdi.

Hani sevincin, o cıvıl cıvıl kuş?

Nasıl, ne zaman geldi, nasıl gitti?', 'Gençlik bir kitaptı, okuduk bitti; Canım bahar geçti çoktan, kış şimdi. Hani sevincin, o cıvıl cıvıl kuş? Nasıl, ne zaman geldi, nasıl gitti...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/genclik-bir-kitapti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madem', 'madem-omer-hayyam-ej06o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Madem bizler çamurdan halk edildik,

Sebep ne ki; Hak tanısın eksik, gedik?

Kusursuzsak neden bizi kırıp döker?

Kusurluysak acep kimde bu eksiklik?!', 'Madem bizler çamurdan halk edildik, Sebep ne ki; Hak tanısın eksik, gedik? Kusursuzsak neden bizi kırıp döker? Kusurluysak acep kimde bu eks...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/madem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mı Dünyada Günah İşlemeyen', 'var-mi-dunyada-gunah-i-slemeyen-omer-hayyam-6cco3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim senin yasanı çiğnemedi ki söyle? 

Günahsız bir ömrün tadı ne ki söyle 

Yaptığım kötülüğü kötülükle ödetirsen sen

sen ile ben arasında ne fark kalır ki söyle', 'Kim senin yasanı çiğnemedi ki söyle?  Günahsız bir ömrün tadı ne ki söyle  Yaptığım kötülüğü kötülükle ödetirsen sen sen ile ben arasında ne...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/var-mi-dunyada-gunah-islemeyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman dedikleri', 'zaman-dedikleri-arzu-dincer-517u6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kara delik diyorlar bilmediklerine…

Aman be ! Desinler…

Ne bosa gecen zaman vardir..

Söyleyin bilsinler…

Su an yasamaksa ödevimiz..

Derdi unutmaksa yasamdan yana

Yasasin zamanin üstünde giden

Zamansizlik çelengi..

Gerinemedikten sonra şöyle uzun uzun

Vakit mi bulacagız tabutta …

İki kelamı saate bakip yaptigimizda,

Sözler düğümlenip, kisalinca,

Dönebilecek miyiz o zamana…

Ahh ! Ahhh!

Ne yaptiklarimiz yapacaklarimizin,

Ne yapamadiklarimiz yaptiklarimizin

Kaniti olacak ayrilik vakti…

İki dakika fazla zaman ayirdigimiz,

Gözyaşi dökecek..

Ve o iki dakika yanlizligi unutturacak bize…

06/04/2001', 'Kara delik diyorlar bilmediklerine… Aman be ! Desinler… Ne bosa gecen zaman vardir.. Söyleyin bilsinler… Su an yasamaksa ödevimiz.. Derdi un...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zaman-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-arzu-dincer-95qn9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ormandan gelen bir sesti beni çeken,

Ağlıyordu biri…

Umursamaz oldum…

Yükseldi ses…

İnsaniz ya özde..

Yöneldim orman''a

Ses daha yakindan 

Çağırıyordu beni…

Ağaçlar dallarını açmış..

Bekliyordu…

Derken bir taşa takildim…

Taş bir yürek gibi bakıyordu bana

Sonra yüreğime baktim,

Ağliyordu …', 'Ormandan gelen bir sesti beni çeken, Ağlıyordu biri… Umursamaz oldum… Yükseldi ses… İnsaniz ya özde.. Yöneldim orman''a Ses daha yakindan  Ça...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ses-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahh Ustam ahhh!', 'ahh-ustam-ahhh-arzu-dincer-uxjf8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne sucularin hiç durmayan çıngırakları kaldı,

Ne de havanın suyun bedavaligi,

Ahh be Ustam!

Bir görsen halimizi..

Siirler dert dolu…

Kadinlarin cilveli yürümeğe vakti kalmadı,

Çocuklar öyle tozu dumana katip oynayamıyorlar..

Ve anlatamadigimiz o kadar çok şey varki birilerine

Aşk tek sığınak kaldı yüreğimize…

Süleyman Efendinin nasrı,

Ayağını aştı cevahirlere sardı,

Kim gördü yerine, görmeyen var mı diyorlar..

Ahh Ustam ahh!', 'Ne sucularin hiç durmayan çıngırakları kaldı, Ne de havanın suyun bedavaligi, Ahh be Ustam! Bir görsen halimizi.. Siirler dert dolu… Kadinla...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ahh-ustam-ahhh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir yazalım Seninle', 'bir-siir-yazalim-seninle-arif-baltaci-ch8jt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazalım seninle gel üstad

İçinde sevgilerin en temizi olsun

Ve yanına dostluğumuzu da koyalım

Her yudumda hissedelim gurbeti

Sevda türküleri söyleyelim

Bağıra bağıra,avazımızın çıktığınca 

Sonra aşktan konuşalım biraz

Kadehlerden vakit kalırsa

Bu gece uyumak istemiyorum üstad

İçimde mahşer kalabalığı

Ve yüreğimin içine işlemiş yalnızlık

Bende bir yangın var ki sorma üstad

Yalnız kalmayanların anlayacağı türden değil', 'Bir şiir yazalım seninle gel üstad İçinde sevgilerin en temizi olsun Ve yanına dostluğumuzu da koyalım Her yudumda hissedelim gurbeti Sevda ...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-siir-yazalim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fanus', 'fanus-arzu-dincer-wokuq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir masal anlatmak isterim sana…

Bir masal yaşatmak…

Pamuklara sarılmış bir hayat ..

Gülmeni hep gülmeni isterim sonra..

-Biliyor musun güldükçe nasıl güzelleştiğini !

Sevginin sonsuz resmini çizmek isterim sana..

Saflığın doyumsuzluğunu..

Ama … ama,

Büyüyüp fanustan çıkmak isteyince,

Sonra nasıl salarım seni kurtlar sofrasına?', 'Bir masal anlatmak isterim sana… Bir masal yaşatmak… Pamuklara sarılmış bir hayat .. Gülmeni hep gülmeni isterim sonra.. -Biliyor musun güld...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fanus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Sana Sevgilim', 'selam-sana-sevgilim-arif-baltaci-ed2ze', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selam sana;

Baharın koynunda bekleyenim

Sonsuz sevgilerimle kalan sevgilim,selam sana

Üç ay oldu görüşemedik seninle

Ben mahpus türküleri tutturmuşum

Küçük hücremin penceresinde 

Sense sonsuzluğa kucak açmışsın

İçinde sınırsız sevgilerle

Beni beklemenin ızdırabını yaşamışsın

Ve sonra geleceğimi düşünüp rahatlamışsın

Selam sana;

Gözyaşlarıyla umudumu büyüten sevgilim

İnadıyla baharı getiren sevgilim,selam sana.

Resimlerin elimde şimdi

Veda buğsen aklımda 

Ve hayalin yanımda

Küçük penceremden sana açılıyorum

Büyüyorum ,

Yıldızlar kaplamış gökyüzünü

Onları tutmak için büyüyorum

Ve tuttukça yıldızları sana yaklaşıyorum

Kavuşmamıza az kaldı sevgilim

Aç kollarını,söyle umut şarkılarını

Sevdiğini haykır insanlara 

Ben geliyorum...', 'Selam sana; Baharın koynunda bekleyenim Sonsuz sevgilerimle kalan sevgilim,selam sana Üç ay oldu görüşemedik seninle Ben mahpus türküleri tu...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/selam-sana-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Ömür Biçiyorlar', 'aska-omur-biciyorlar-arzu-dincer-emg2i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşka ömür biçiyorlar..

Yalan yalan bir tanem..

Aşkın ömrü olmaz…

Canlı''dır aşk,

Yaşanır.. hissedilir..

Aşka ömür biçiyorlar birtanem,

Mevsimlere benzetiyorlar..

Oysa mevsimsiz ve zamansız yaşamaktır aşk..

Olduğu gibi, sığdırabildiği kadardır…

Kelimeler kifayetsiz diyorlar..

Kifayet değil midir aşk?

Aşka ömür biçiyorlar birtanem..

Diyorlarki..

Diyorlarki iki elmanın yarısı..

Çürürmü aşk sence?

Her dem taze değil midir..

Gözlerin buluştuğunda..

Aşka ömür biçiyorlar birtanem,

Her sabah uyandığında,

Bir nefes hissetmenin

Güzelliğini unutarak…

İnsan teninin en güzel dansını

Görmezden gelerek…', 'Aşka ömür biçiyorlar.. Yalan yalan bir tanem.. Aşkın ömrü olmaz… Canlı''dır aşk, Yaşanır.. hissedilir.. Aşka ömür biçiyorlar birtanem, Mevsim...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aska-omur-biciyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Bilirsin Sevmenin Manasını', 'sende-bilirsin-sevmenin-manasini-arif-baltaci-9cos7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen de bilirsin sevmenin manasını

Seninde kalbinde açar sevda gülleri

İnadına susarsın  oysa 

Sevgin yüreğini acıttıkça

Sevgini saklamaya çalışırsın kendince 

Ama bakışlarını kaçıramazsın 

Konuşmanın en anlamsız yerinde 

Birden düşünmeye başlarsın

Sanırsın ki yalnız sen hayal kurarsın

Sevda üstüne,

Şiirleri yalnız sen okursun 

Tüm içtenliğiyle

İçinde ne duyguları saklamışsındır

Kaç kez söylemekten vazgeçtiğin 

Ne duyguları saklamışsındır kimbilir

Belkide o duygulardan 

Bir buket yapmışsındır sevgiliye 

Sunmaktan çekindiğin,

Aşkınla büyüttüğün

Sevda güllerinden oluşan bir buket', 'Sen de bilirsin sevmenin manasını Seninde kalbinde açar sevda gülleri İnadına susarsın  oysa  Sevgin yüreğini acıttıkça Sevgini saklamaya ça...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sende-bilirsin-sevmenin-manasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Hikayesi Bu', 'bir-ask-hikayesi-bu-arif-baltaci-hhlvs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne umutlarım vardı gelecekten 

Seninle,hep elele,hep birlikte 

Sen benim,ben senin herşeyi olacaktık 

Şimdi,şimdi gidiyorsun gerçekten 

Ve bana unut diyorsun beni

Farzet ki seninle elele gezmedik

Farzet ki öpüşen biz değildik

Şehrin dar sokaklarında

Hiç tanımadık say birbirimizi 

Hiç görmedik say herşeyi 

Yıldızların altında elele 

Dolaşan başkalarıydı de 

Dizine yattığın ben değildim

Dizime yatan da sen değil 

Sahilde,çıplak ayaklarla 

Elele dolaşmadık hiç

Artık ben seni,sende beni

Hiç tanımayacaksın 

Seni seviyorum demedin say 

Beraber sabahladıklarımızı 

Es geç hatıralarımızı 

Olmadı hiç elim elinde 

Olmadı hiç gözün gözümde

Ve hiç olmadı dudaklarımda 

Senin kırmızı dudakların 

Saçlarıma dokunmadın 

Dokunmadın vucüduma 

Öpmedin beni doyasıya 

Öpüşmedik birkere de olsa 

Beraber şarkı söylemedik 

Dinlemedik say 

^Nasıl geçti habersiz^şarkısını

Söylemedik say 

Hiçbir şarkıyı 

Çimenlerde uzanan sevgililer 

Biz değildik de 

Hiç gezmedik biz 

Beraberce elele 

Kucağımda taşıdığım 

O güzel sarışın sen değildin

Sen değildin beni saran 

Beraber yemek yemedik

Su içmedik kana kana 

Ağlamadık yana yana 

Sana hiç şiir okumadım 

Şiir de yazmadın bana 

Farzet ki sevmedik birbirimizi 

Diyorsunda güzelim 

Kolaymı unutmak seni

Öpüştüğümüzü,sahilde 

Koşup,sonra düştüğümüzü

Koyunları sevip,karanfil aldığımızı 

Dizinde yattığımı

Söylediğimiz şarkıları 

Uzandığımız yatağı

Yediğimiz yemekleri

Gittiğimiz ırmakları

Yaşadığmız o günleri

Unutabilirmiyim sanıyorsun

Say ki unuttum

Ya gözlerini nasıl unuturum

Sözlerini saçlarını 

Söylesene seni nasıl unuturum 

Sanma ki sen gidersen unuturum seni 

Gidersen resimlere bakarım 

Gezdiğimiz yerlerde izini ararım 

Avare olurum uğrunda

Divane olurum

Ama unutamam seni

Say ki unuttum 

Kalbim nefret eder benden 

Çinki kalbimde yalnız sen vardın

Gözlerim küser bana 

Hep sana bakardı ya 

Kulağım işitmez beni 

Senin sesini dinlerdi ya 

Dudaklarım kıpırdamaz 

Senin dudaklarını tattıktan sonra 

Ellerim hareket etmez 

Sana bir kez dokunursa 

Şimdi söyle bana güzelim

Seni nasıl unuturum

Sözler yeter mi unutturmaya seni

Ya da mesafeler yeter mi 

Ne farkeder sen gitsende 

Unuturmuyum sanıyorsun  seni

Seni unutmanın tek yolu var 

O da yaşamı unutmak güzelim

Eğer unut diyorsan hala 

Hazırım,hadi bitsin şimdi 

Sensiz bu hayat 

Ölümden de beter be sevgilim', 'Ne umutlarım vardı gelecekten  Seninle,hep elele,hep birlikte  Sen benim,ben senin herşeyi olacaktık  Şimdi,şimdi gidiyorsun gerçekten  Ve b...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/bir-ask-hikayesi-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-ahmet-meydan-od98t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin yağıyordu gözlerime

ıslak mayıs akşamları

ve apartman girişlerindeki

hanımeli oluyordu teninin kokusu

uyandığımda bir temmuz sabahı.', 'Gözlerin yağıyordu gözlerime ıslak mayıs akşamları ve apartman girişlerindeki hanımeli oluyordu teninin kokusu uyandığımda bir temmuz sabahı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yagmur-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm Abi', 'gordum-abi-arif-baltaci-remf6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiyi gördüm abi

Öksüz ve minik bir kızın gözlerinde 

Annesiyle giden çocuklara bakarken 

Gördüm abi gerçekten gördüm

Karşılıksız bir sevgiydi bence 

Kendi için değildi bu sevgi onlar içindi abi

Değerini bilsinler diye 

Onun sevinemsi düşlerdeydi abi

Rüyasını bile göremediği düşlerde 

Yaşamak kadar kendisine uzakta olsa

Sevginin değerinin biliyordu abi 

Belkide sevgi için dayanıyordu

Küçücük  bedeni bu zor hayata 

Sadakati gördüm abi 

Bir sokak çocuğunun yüeğinde 

Nasıl da sahip çıkıyordu 

Kader  arkadaşına 

Görmeliydin abi görmeliydin

Soğuktan morarmış elleri

Belkide yeni tanıştığı 

Kader arkadaşı için 

Havadaydı 

İnmedi abi yere 

Haksızlık bitene dek 

Haksızlık bitmeden 

Yüreğindeki sadakat volkanı sönmedi abi

Belki yalnız

Belki sahipsiz

Belki sevgisiz 

Ama gururluydu 

Ama sadakatliydi

Belkide çoğumuzun yapamadığını 

O küçük sokak çocuğu yaptı abi 

Karşılık beklemedi sevgiden 

Hiçbirşey beklemedi kimseden

Sokak kanunlarına uymalıymış abi

Tek başına yaşamasını öğrendi 

Paylaşmayı öğrendi 

En önemlisi abi

Herşeye rağmen yaşamasını öğrendi', 'Sevgiyi gördüm abi Öksüz ve minik bir kızın gözlerinde  Annesiyle giden çocuklara bakarken  Gördüm abi gerçekten gördüm Karşılıksız bir sevg...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gordum-abi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yağıyor+', 'ne-yagiyor-bayram-tunca-6ae5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nisan yağmuru değil zam yağmuru yağıyor

Halkımızın feryad-ü figanı yürekleri dağlıyor

Ekonomik kriz nedeniyle nice aileler ağlıyor

Kimi, feryat edenlerin elini kolunu bağlıyor

Kimileri hortumladı, kimileri de hortumlattı

Yerdeki ve göktekiler bütün olanları tanıktı

Zamlar dolu gibi yağınca gözyaşları sel olup aktı

Halkımız pâktı fakat zamlar alev alev onları yaktı

Umutla, nisan yağmurlarını beklerken insanlarımız

Dolu gibi zam yağmurunu yakalandı fakir halkımız

Eğer Allah lütfetmezse, halkımıza sabır ve ihsanını

O zaman yürek mi dayanır halkımızın perişanlığını

06.04.2001-05:00

Aşk Ateşten Gömlek', 'Nisan yağmuru değil zam yağmuru yağıyor Halkımızın feryad-ü figanı yürekleri dağlıyor Ekonomik kriz nedeniyle nice aileler ağlıyor Kimi, fer...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam...', 'sevdam-yavuz-yasar-knqru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'umutsuz yarınlarda ben

seni içtim her gece

yorgun akşamların hüznü

gariban çocukların sevinişi gibi...

ben seni sevesiye değil

ölesiye sevmiştim...

ben kimseye dememiştim daha önce

hayatimin anlamisin diye..

ben bir seni sevdim birde:

sevmendeki çekingenliğini

sevmek ne zor şeymiş be canim

ağlamak zor her gece...

sevdam dedim bu şiire 

nedeni basit sevdamsin işte

dahası yok dahası yok bunlarin

ölesiye kadar sevdamsın işte.....

                                    07.04.2001', 'umutsuz yarınlarda ben seni içtim her gece yorgun akşamların hüznü gariban çocukların sevinişi gibi... ben seni sevesiye değil ölesiye sevmi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Yaşar']::text[], 8.5, '{"poet":"Yavuz Yaşar","poet_slug":"yavuz-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar çiçekleri', 'bahar-cicekleri-ahmet-meydan-11uso', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sahildeki kıza’

Eprimiş bir yanlızlıktı seninkisi

hiç kimseninkine benzemeyen.

Sıkılgan akşamların 

donuk ritimleri atardı kalbinde

ve 

sen

böyle zamanlarda

öksüz savaş çocukları gibi

tekrar kapanırdın kendine.

Benzerdin açmayan bahar çiçeklerine', 'sahildeki kıza’ Eprimiş bir yanlızlıktı seninkisi hiç kimseninkine benzemeyen. Sıkılgan akşamların  donuk ritimleri atardı kalbinde ve  sen ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bahar-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışlarınla Tutuşturduğun Geceler', 'bakislarinla-tutusturdugun-geceler-guven-karatas-q0lva', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakışlarınla tutuşturduğun gecelerde

Adının heceleriyle başlayan 

Kelimeleri duyumsuyordum sadece

Adının hecelerinden yoksun kelimelere

    Lal kalıyordum...

Belirsizleşen insan siluetleri içerisinde

    Gözlerini arıyordum

Deniz, dalgalarını

    Yapraklar, rüzgarını

          Ay, ışıklarını

Gece, lacivert tonlarını arıyordu

Bakışların bakışlarıma dokunana dek...

mart 2001', 'Bakışlarınla tutuşturduğun gecelerde Adının heceleriyle başlayan  Kelimeleri duyumsuyordum sadece Adının hecelerinden yoksun kelimelere     ...', ARRAY['Türk Edebiyatı','Şiir','Güven Karataş']::text[], 8.5, '{"poet":"Güven Karataş","poet_slug":"guven-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bakislarinla-tutusturdugun-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Senin', 'gelecek-senin-adil-koruyan-eu91p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yol ki düşün, bu senin geleceğin.

Yaşam denen bu yolda giden sensin.

Katettiğin yollara, geçmişe bir bak.

Sanma, geçmişteki sapaklar artık olmayacak.

Gideceğin yeri, varmak istediğin hedefi biliyorsan,

Güveniyorsan kendine, durmaksızın korkusuzca yürü.

Hele bir de sevgi doluysan ve seviliyorsan;

Yarınlar senindir, senin olacak inan.

Yollar taşlı da olsa, sapaklar kaybolacak.

Huzur bulacaksın, mutluluğu yakalayacaksın inan.

28.03.2001', 'Bir yol ki düşün, bu senin geleceğin. Yaşam denen bu yolda giden sensin. Katettiğin yollara, geçmişe bir bak. Sanma, geçmişteki sapaklar art...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gelecek-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bir Sözcük Değil..', 'sevgi-bir-sozcuk-degil-adil-koruyan-xwko6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiyi bir sözcük sayan insanlar,

Sevmeyi bilmediklerinden yalan sözylüyorlar.

Sevmek, sözcüklerle anlatılamayacak kadar,

Duygudur, duyumdur, doyumsuzluktur.

Sevgiliyle yaşanan saatler değil,

Sevgilisiz anlardır, yeri doldurulamayan.

Sevgi bir bakıştır, içten kalbe dolan.

Sevgi bir temastır, kor gibi yakan.

Yokluğunda o''nu yaşamaktır,kahreden,

Acıyı bütün benliğinde duymaktır.

06.04.2001', 'Sevgiyi bir sözcük sayan insanlar, Sevmeyi bilmediklerinden yalan sözylüyorlar. Sevmek, sözcüklerle anlatılamayacak kadar, Duygudur, duyumdu...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgi-bir-sozcuk-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim', 'duslerim-don-juan-de-marco-ltmm6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlerimde karanlık,

Gözlerimde gözlerinin izi.

Limandaki o kahve,

Haykırıyor hepseni.

Ölüm bile, seni benden aldıgını sanıyor

Oysa, kulaklarımda o ezgi batarken güneşim

Kucak açtım sonsuzluğa, ellerimde ellerin.', 'Düşlerimde karanlık, Gözlerimde gözlerinin izi. Limandaki o kahve, Haykırıyor hepseni. Ölüm bile, seni benden aldıgını sanıyor Oysa, kulakla...', ARRAY['Türk Edebiyatı','Şiir','Don Juan de Marco']::text[], 8.5, '{"poet":"Don Juan de Marco","poet_slug":"don-juan-de-marco","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ol', 'ol-umit-bahadir-z6uja', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nar''dayım  serinlemez tenim

Kar''dayım  ılımaz bedenim

Nar''da   kar''ım ol

Kar''da narım ol

   *       *        *

Susuzum  kanmazım

Açım  doymazım

Susuzumda  selim  ol

Açımda  aşım ol

*       *       *        *       *

Zifirideyim  görmez gözüm

Felçteyim  tutmaz bedenim

Felçimde  dinçim ol

Zifiride  nurum  ol', 'Nar''dayım  serinlemez tenim Kar''dayım  ılımaz bedenim Nar''da   kar''ım ol Kar''da narım ol    *       *        * Susuzum  kanmazım Açım  doyma...', ARRAY['Türk Edebiyatı','Şiir','Ümit Bahadır']::text[], 8.5, '{"poet":"Ümit Bahadır","poet_slug":"umit-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-meltem-pirlibeylioglu-vxz6u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yemyeşil bayırların

Al giysili güzeliyim,

Narin,ince ve nazlı

Sanki sihirli periyim.

Açarım yapraklarımı,

Görünür siyah gözlerim.

Yüreğimde sevgilerle

Hep sevenleri izlerim.

Kimisi seyreder beni,

Kimisi koparıp alır,

İşte o an yüreğimde ,

Derince bir sızı kalır.

Kimileri demet demet

Sunarlar sevdiklerine,

Kimileri koyar beni,

Başlarına taç yerine.

Ben baharın neşesiyim,

İnce belli gelinciğim,

Bir kiyabın sayfasında,

Sakla beni sevdiceğim.', 'Yemyeşil bayırların Al giysili güzeliyim, Narin,ince ve nazlı Sanki sihirli periyim. Açarım yapraklarımı, Görünür siyah gözlerim. Yüreğimde ...', ARRAY['Türk Edebiyatı','Şiir','Meltem Pirlibeylioğlu']::text[], 8.5, '{"poet":"Meltem Pirlibeylioğlu","poet_slug":"meltem-pirlibeylioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelincik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözdeki', 'gozdeki-ozdemir-asaf-7b3f0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana senin için, 

O mu, diye sordular.

O değil, dedim onlara..

Anladılar.', 'Bana senin için,  O mu, diye sordular. O değil, dedim onlara.. Anladılar....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozdeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan''ı Beklerken', 'nisan-i-beklerken-vedat-koseoglu-pjv7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeniden doğmak için Nisan''ı beklerken

Dalda yaprak, toprakta çiçek, sahilde deniz,

Hülyası yıkılmış, güze dönmüş bir ömrün

Tenha karanlıklarında iki gölge gibiydik biz...

İşte Nisan''la beraber yeniden başladı her şey

Hayalimiz bir, arzumuz bir, birdir artık dilimiz,

Aşk dolu, sevda dolu, ortak bir bahçeye 

Bakıyor bütün gönül pencerelerimiz...

Ne bulut var gökyüzünde, ne de bir hüzün

Bir bayram yerine döndü dışımız, içimiz,

Ben huzur dolu bir sahilde bir kum tanesiyim şimdi

Sen ise sevgi dolu dalgalarla sahile koşan deniz.....', 'Yeniden doğmak için Nisan''ı beklerken Dalda yaprak, toprakta çiçek, sahilde deniz, Hülyası yıkılmış, güze dönmüş bir ömrün Tenha karanlıklar...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nisan-i-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seveli', 'seni-seveli-sema-akbaba-x8g8r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni seveli böyleyim 

Böyle mahsun,dalgın

Bazen kulaklarımda yalnız senin sesin

Adımı sağıra çıkardılar sonunda

Bazen de gözlerimde bir tek sen

Senin gözlerin

Şimdi de kör diyorlar bana 

Oysa ne körlük ne sağırlık benim derdim

Benimki kara sevda...', 'Seni seveli böyleyim  Böyle mahsun,dalgın Bazen kulaklarımda yalnız senin sesin Adımı sağıra çıkardılar sonunda Bazen de gözlerimde bir tek ...', ARRAY['Türk Edebiyatı','Şiir','Sema Akbaba']::text[], 8.5, '{"poet":"Sema Akbaba","poet_slug":"sema-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seveli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gercek Seven', 'gercek-seven-omer-fazil-w9f28', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceler vardır ki,uyunamazdı,

Büyük bekeleyişler vardı,içimde

Çoğu zaman neyin bekleyişiydi,

Kolum kanadım yorgun bir aşk bekleyişi,

Hala içimden çıkmaz ve seni düşünür,

Senin kaderine,hüzünlerine ortak olmayı,

Gözlerim bir tek aşk yolunu gösterince,

Seçimi her zaman senden yanadır,

Ben yeryüzü seslerini işitmez olunca,

Dudaklarım yeryüzünün sularını içmez olunca,

Belki bu satırları okuyunca ,

O zaman anlarsın gerçek seveni', 'Geceler vardır ki,uyunamazdı, Büyük bekeleyişler vardı,içimde Çoğu zaman neyin bekleyişiydi, Kolum kanadım yorgun bir aşk bekleyişi, Hala iç...', ARRAY['Türk Edebiyatı','Şiir','Ömer Fazıl']::text[], 8.5, '{"poet":"Ömer Fazıl","poet_slug":"omer-fazil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-seven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yildizlar', 'yildizlar-cem-ozgur-dumlupinar-e98v4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eyer gün olurda yildizlari ararsa gözlerin

Gecenin karanligini bekleme 

Yildizlari görmek icin,

Ariyorsa gözlerin güzeli,güzel olani

kaldir basini, gökyüzünün derin maviliklerine dik gözlerini.

Bilki yldizlar hep yerliyerindeler.

Hayal kurmak icinde bekleme geceyi,

ögrenmelisin yildizlari gün isiginda görmeyi

Hayallerini yildizlara bakarak 

günes sicakliginda ve gecenin yanlizliginda yasamayi.

Ay düsecek olursa pencerene sakin alma iceri 

bilki tek seven sen degilsin 

Karartma asklarin gecelerini.

Ask karanliktir zaten,isik tutmali asklara, aski ögernmeli

Aski yenmek icin ASIK

Cem-Özgür Dumlupinar

      07.04.2001', 'Eyer gün olurda yildizlari ararsa gözlerin Gecenin karanligini bekleme  Yildizlari görmek icin, Ariyorsa gözlerin güzeli,güzel olani kaldir ...', ARRAY['Türk Edebiyatı','Şiir','Cem Özgür Dumlupınar']::text[], 8.5, '{"poet":"Cem Özgür Dumlupınar","poet_slug":"cem-ozgur-dumlupinar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yildizlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ukala', 'ukala-cem-ozgur-dumlupinar-ax8xz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Basima geldi Kötü bir kaza 

Allah vermesin böyle yara

Gittim doktora,dedi bahtin kara 

ASIK olmussun ulan 

UKALA.', 'Basima geldi Kötü bir kaza  Allah vermesin böyle yara Gittim doktora,dedi bahtin kara  ASIK olmussun ulan  UKALA....', ARRAY['Türk Edebiyatı','Şiir','Cem Özgür Dumlupınar']::text[], 8.5, '{"poet":"Cem Özgür Dumlupınar","poet_slug":"cem-ozgur-dumlupinar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ukala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Kitabeden...', 'eski-bir-kitabeden-sair-baltigmore-ebkro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gürültü ve patırtının ortasında sükunetle dolaş;

Sessizliğin içinde huzur bulunduğunu unutma

Başka türlü davranmak ,açıkça gerekmedikçe 

Herkesle dost olmaya çalış,

Ama kimseye teslim olma.

Telaşsız ,açık ve seçik konuş

Başkalarına da kulak ver

Aptal ve cahil oldukları zaman bile dinle onları;

Çünkü,dünyada herkesin bir hikayesi vardır.

Yalnız planlarının değil,

Başkalarının da tadını çıkarmaya çalış

Ne kadar küçük olursa olsun işinle ilgilen

Hayattaki dayanağın odur

Olduğun gibi görün ,göründüğün gibi ol.

Sevmediğin zaman sever gibi yapma.

Aşka burun kıvırma sakın;

O ,çöl ortasında çimenli bir yerdir

Yılların geçmesine öfkelenme

Gençliğine yakışan şeyleri gülümseyerek teslim et geçmişe

Ara sıra isyana yönelecek olsan bile hatırla ki,

Kainatı yargılamak imkansızdır

Onun için kavgalarını sürdürürken bile

Kendi kendinle barış içinde ol

Görmeye çalış ki,

Bütün pisliğine ve kalleşliğine rağmen

Dünya yine de güzeldir...

(1816 ABD)', 'Gürültü ve patırtının ortasında sükunetle dolaş; Sessizliğin içinde huzur bulunduğunu unutma Başka türlü davranmak ,açıkça gerekmedikçe  Her...', ARRAY['Türk Edebiyatı','Şiir','Şair Baltigmore']::text[], 8.5, '{"poet":"Şair Baltigmore","poet_slug":"sair-baltigmore","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/eski-bir-kitabeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İFK', 'i-fk-mustafa-i-slamoglu-l8y9a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nur ordusunun bir soylu neferi

Çöl serinliğinde nur aramakta

Saffan ibn-i Muattal Es Sülemi

Gecenin göğsünden huzur sağlamakta

İçinde bir deniz sakin mi sakin

Birden kabarmakta,dalgalanmakta

-O''ndan geldik O''na döneceğiz biz

Ey annemiz işte devem,buyur bin

Kutsal emaneti o taşımakta

Kafile görünür tan ağarırken

Emaneti ulaştırır şafakta

Bazı gözler ihanete ayarlı

Bazı gözler takılmıştır çapakta

Göklerin gelini yanlız sorudur

Düşman sınanmakta dost sınanmakta

Atılmıştır pak damene bir çamur

Allah yıkamaya hazırlanmakta

Düşman atsın taşlarını gam değil

Dostun attığı gül yaralamakta

Göklerin gelini baba evinde

Çektiği ah yeri göğü sarsmakta', 'Nur ordusunun bir soylu neferi Çöl serinliğinde nur aramakta Saffan ibn-i Muattal Es Sülemi Gecenin göğsünden huzur sağlamakta İçinde bir de...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İslamoğlu']::text[], 8.5, '{"poet":"Mustafa İslamoğlu","poet_slug":"mustafa-i-slamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ifk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeyl-c', 'zeyl-c-mustafa-i-slamoglu-etuhg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Örtüne çiçek düşürdüm

Namluya duanı sürdüm

Sen ağlamasaydın anne

Gül mevsiminde üşürdüm', 'Örtüne çiçek düşürdüm Namluya duanı sürdüm Sen ağlamasaydın anne Gül mevsiminde üşürdüm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İslamoğlu']::text[], 8.5, '{"poet":"Mustafa İslamoğlu","poet_slug":"mustafa-i-slamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zeyl-c-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'şiir', 'siir-deniz-erdem-9zyfa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'meryem ana gibidir şiir

babasız şair doğurur', 'meryem ana gibidir şiir babasız şair doğurur...', ARRAY['Türk Edebiyatı','Şiir','Deniz Erdem']::text[], 8.5, '{"poet":"Deniz Erdem","poet_slug":"deniz-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/siir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dialektik Bir Aşk Hikayesi', 'dialektik-bir-ask-hikayesi-deniz-erdem-zabvf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende soprano bir zarafet

Bende ise bozlak bir utanç

Sen kalın Fransız romanlarında 

İnce narin kadın

Ben yırtılmış bir şiir kitabında

Yarım kalmış dize

Sen gözlerime bakınca 

Denizin akisini görürsün

Ben denize baksam

Senin denize vuran gölgeni görürüm

Sen binlerce gözde yeniden doğarsın

Bense arabesk yalnızlığımda kaybolurum

Ve aklıma her geldiğinde

Dudaklarım da yalnız şu dize

Sende soprano bir zarafet

Bende ise bozlak bir utanç', 'Sende soprano bir zarafet Bende ise bozlak bir utanç Sen kalın Fransız romanlarında  İnce narin kadın Ben yırtılmış bir şiir kitabında Yarım...', ARRAY['Türk Edebiyatı','Şiir','Deniz Erdem']::text[], 8.5, '{"poet":"Deniz Erdem","poet_slug":"deniz-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dialektik-bir-ask-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya-sin', 'ya-sin-mustafa-i-slamoglu-kv3eq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.......

Ben kendime ağlarken Uhud da ağlar mıymış? 

Hira''yı mahzun gördüm soramadım sevgili

Hasretinin dışınd başka derdi varmıy mış? 

........

Dua çıkmayan göğe sevdalar çıkarmıy mış? 

Bülbülünü kaybetmiş bu evrensel bahçede

Dikenler bile bir hoş gayrı gül kokar mıymış? 

.......

O bengisu gözünden fışkıran pınar mıymış? 

Baharların kaynağı ve yolunu gözleyen

Bir ben sevda şehidi bir de şu çınar mıymış? 

.......

Niçin döndü bu rüzgar yol vermez dağlar mıymış? 

Yine Ferhat kesildin be ne canhıraş gönlüm

Bağrını deldin diye dağlar da ağlar mıymış? 

.......

Acımı tartamayan aşkımı tartar mıymış? 

Gönlüme yol vermeyen şu zifiri perdeyi

O cennet elleriyle lutfedip yırtar mıymış? 

........

Çekilen dizde ferman gözümdeki fer miymiş? 

Kendimi bir kum diye atuversem çölüne

O na vurgun bulutlar üstümde gezer miymiş? 

.....

Söyle gönlüm bu sevda mahşere kalır mıymış? 

Alışılmış sözcükler yükleyip kanadına

Ona doğru uçursam katına  alır mıymış? 

.....

Sen olmazsan gemide bu tufan diner miymiş? 

Gemilerin de yandı sil aklından dönüşü

Vakt indi yüreğim gidenler döner miymiş?', '....... Ben kendime ağlarken Uhud da ağlar mıymış?  Hira''yı mahzun gördüm soramadım sevgili Hasretinin dışınd başka derdi varmıy mış?  ........', ARRAY['Türk Edebiyatı','Şiir','Mustafa İslamoğlu']::text[], 8.5, '{"poet":"Mustafa İslamoğlu","poet_slug":"mustafa-i-slamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ya-sin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Baçemin Sultanı', 'gul-bacemin-sultani-cuma-kaya-1er7g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dilerim yaşadığın müddetçe

Mutluluğun her boyutunu tadarsın

Ömrün boyunca seni üzecek engeller

Önünden eğilerek çekilsin

Gül bahçendeki

güllerin kokuları hiç dinmesin

çevreye gül kokuları saçasın

ama izin ver gül bahçende

dikenlerine takılmış

garip bir bülbül yaşasın', 'Dilerim yaşadığın müddetçe Mutluluğun her boyutunu tadarsın Ömrün boyunca seni üzecek engeller Önünden eğilerek çekilsin Gül bahçendeki güll...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gul-bacemin-sultani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana vermedim pamukşekerini', 'sana-vermedim-pamuksekerini-selcuk-sahin-5i0il', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğa sarılan düşlerim

ellerinde büyüyebilse,

kırmızı tepelere sürüklerdim saçlarımı.

Boşalan sokaklardan yığınla

ter taşırım odama,

aşka yıkılmış binlerce ağaç

taşırım..

Biraz sevda susamış herkes böyle uyukluyor sevgili düşlerinde...

Bitirdim işte o pamuk şekerlerini kendi başıma

O dalgalara at şimdi kendini,

gözlerimdeki..', 'Sonsuzluğa sarılan düşlerim ellerinde büyüyebilse, kırmızı tepelere sürüklerdim saçlarımı. Boşalan sokaklardan yığınla ter taşırım odama, aş...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Şahin']::text[], 8.5, '{"poet":"Selçuk Şahin","poet_slug":"selcuk-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sana-vermedim-pamuksekerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ali-atilgan-qz6rq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine bu boş odada;

sensiz güneşin doğuşuna 

takıldım;

bu kimsesiz ,bu çaresiz

odanın duvarlarına

seni haykırdım;biliyormusun

bir resmi çizer gibi

bir şarkıyı söyler gibi

ağladım;

her damla gözyaşına

gözlerini,hasretini,sensizliği

seni ekledim.

yine senle doldurdum

buram  buram kokunu

sigaramın dumanına  kattım

nefes nefes çektim seni

hayallerim;

sana dokunacak kadar yakın

seninle gülecek kadar mutlu

seninle hüzünlenecek kadar duygusal

bu kadar yakınken

bir o kadarda uzak

ya bir pamuk ipliği ;

koparcasına

ya bir uçurum kenarı

boşluğa bırakırcasına

sen,hep sen

özlediğim sen

sarıldığım sen

kokladığım sen

sen;

ya ben.......', 'yine bu boş odada; sensiz güneşin doğuşuna  takıldım; bu kimsesiz ,bu çaresiz odanın duvarlarına seni haykırdım;biliyormusun bir resmi çizer...', ARRAY['Türk Edebiyatı','Şiir','Ali Atılgan']::text[], 8.5, '{"poet":"Ali Atılgan","poet_slug":"ali-atilgan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyorum', 'oluyorum-cuma-kaya-b8f4p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerinin içine bakarak

ölüyorum burada

bir kaleyi düşürdükten hemen sonra

ve arefesinde yeni bir savaşın

ortada hiçbir sebep yokken

işte öylesine bir sabah

herkes uykudayken

şebnemlere dokunarak ölüyorum

bağırmadan ve söylemeden adımı

ve hatta mümkünse ağzımın kenarında 

küçük bir gülümseme iskeletiyle

fotoğraf çektirir gibi

traş olur gibi

misafirliğe gider gibi 

ölüyorum burada', 'gözlerinin içine bakarak ölüyorum burada bir kaleyi düşürdükten hemen sonra ve arefesinde yeni bir savaşın ortada hiçbir sebep yokken işte ö...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşımın Aşkısın', 'arkadasimin-askisin-cuma-kaya-utk8i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'avuçlarımızın ahşap

düşlerimizin spartaküs

saçlarımızın saç olduğu günlerdi

taşın, demirin,bıçağın,narın

ve burçak tarlasının hakkını verip

her an yeni bir alın yarasına

meyleder gibi otururduk

anlımdaki bıçak yarası senin yüzünden

diyor ya şair

işte aynen öyle

orada anlatıldığı gibi bir şeydi

aşık olmak

ve sonrasında 

üstünden yıllar geçtikçe

gereksizleşecek 

ama asla küçülmeyecek

komikleşmeyecek bi dolu delilik yapardık

ve kanımız bıçak isterdi

yaralanmak isterdik

keskin bir soğuğun altında

ve inatla ve ısrarla 

parçalamak isterdik

göğüs kafesimizi

ve çıkartıp kalbimizi oradan

o sıcak yuvasından bir gece

yukarılara doğru fırlatmak isterdik

yukarılara, karanlığa geceye doğru fırlatmak

ve bağırmak,bağırmak,bağırmak

yaralı bir puma gibi bağırmak isterdik

''arkadaşımın aşkısın''

arkadaşımın aşkısın o kadar

ben yumruğumu ısırarak çekilirim aradan', 'avuçlarımızın ahşap düşlerimizin spartaküs saçlarımızın saç olduğu günlerdi taşın, demirin,bıçağın,narın ve burçak tarlasının hakkını verip ...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/arkadasimin-askisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç ve Ceza', 'suc-ve-ceza-cuma-kaya-fhoed', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ey hayatın yağız çocukları

asi ruhlar

rüzgar ve güneş aksanlı serseriler

yetişin

bir bıçak kavgasının ortasında kaldık

bugünlerde

façasını bozduğumuz züppeler

beyaz yumurta kafalı saray çocukları

sakin ve silahsız yakaladı sicilimizi

adam yaralama, hesaba çekme

mekan basma ve namus cinayeti türünden

her biri kendi içinden fiyakalı suçlar işledik

asla vurmadık bir adamı arkadan

ve düşürmedik pusuya bir yüreği

insanları sırtından vuranları

ve pusuya düşürüp harcayanları

sevmeyiz

sevmeyiz ve bir biçimde 

kıstırıp biryerlerde

sorarız hesabını kalleşliğin......', 'ey hayatın yağız çocukları asi ruhlar rüzgar ve güneş aksanlı serseriler yetişin bir bıçak kavgasının ortasında kaldık bugünlerde façasını b...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/suc-ve-ceza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum', 'i-stemiyorum-cuma-kaya-bnvjb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'milyonlarca aydın,yarı aydın

ve çeyrek porsiyon zekanın

üstüste ekleyerek çoğalttığı

ama sadece çoğalttığı

toplumsal şizofreniden

bir nebze sıyrılıp

susuzluğun büyük mektebine attım ruhumu

aydınlanmak istemiyorum ben

aydın olmak ve iyi seçilmiş cümlelerle 

çocuk öldürmek istemiyorum

bir adamı adam gibi 

öldürmeyi beceremiyenlerin

düşmanının önüne tek başlarına 

ve erkek gibi çıkamayanların

bin dereden getirdikleri suyu

felsefe ,ideoloji falan filan diye

ezberlemeye niyetim yok artık...', 'milyonlarca aydın,yarı aydın ve çeyrek porsiyon zekanın üstüste ekleyerek çoğalttığı ama sadece çoğalttığı toplumsal şizofreniden bir nebze ...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istemiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Kendimize', 'kendi-kendimize-cuma-kaya-xgo49', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hepimiz biraz eksiğiz ve kirliyiz biraz

ben sana eksiğim mesela

sen bana kırgın biraz

edilen bütün laflara

ve kullanılan her sözcüğe

renklerine tablonun

taşa ve çamura küskünüz

bir anlamı yok aşkımızın

yada dünyanın en anlamlı şeyi

bu yürek kıpırtıları

masum değiliz ve yok böyle de bir niyetimiz

biz kendi kirimizle lirliyiz ancak

avuçlarımızda masumların kanı yok

biz kendi küfürümüzle kafir

kendi tövbemizle müminiz o kadar...', 'hepimiz biraz eksiğiz ve kirliyiz biraz ben sana eksiğim mesela sen bana kırgın biraz edilen bütün laflara ve kullanılan her sözcüğe renkler...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kendi-kendimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğiz', 'gelecegiz-cuma-kaya-91jz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüzünki bu topraklara başka türlü iner

ve bazı evlerinde bu memleketin

korsika konuşulur,ogaden konuşulur

meksika ve ateş konuşulur

ve zapatanın beyaz atı

gözlerimize doğru koşar geceleri

ellerimizdeki taşları vurarak birbirine 

büyütürüz isyanı

önüne çıktığımız tarih 

baştan ayağı gül keser

baştan ayağa zafer oluruz

girerek kapılardan içeri

yeşil çimenli bahçelere

oyalı ağaçların altına

kayıtsız uzanır,kayıtsız vururuz

bizki gerçeğiz ve geleceğiz

yarında geleceğiz 

yarından sonrada.......', 'hüzünki bu topraklara başka türlü iner ve bazı evlerinde bu memleketin korsika konuşulur,ogaden konuşulur meksika ve ateş konuşulur ve zapat...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelecegiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veyso''ya...', 'veyso-ya-sair-abdulask-tm4ya', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir boyacı çocuk kağıt mendil satan kızı sevse n''olur, sevmese n''olur...

Ne cilalanacak umutlar kaldı geriye, 

Ne de mendile deger gözpınarları.

Tepsisini devirip ağlamasını nerden öğrendi bu tatlıcı çocuk? 

Bir eliyle sakız satan kızın diger eli dilenmeye meyilli. 

Mavi küre batıyor kendi içine doğru

'' Önce kadınlar ve çocuklar! ''

Yalan...

Rezerve artık tüm filikalar.

Bir boyacı çocuk kağıt mendil satan kızı sevse n''olur, sevmese n''olur...

Miki fareli külotlarda döl lekeleri...', 'Bir boyacı çocuk kağıt mendil satan kızı sevse n''olur, sevmese n''olur... Ne cilalanacak umutlar kaldı geriye,  Ne de mendile deger gözpınarl...', ARRAY['Türk Edebiyatı','Şiir','Şair Abdulaşk']::text[], 8.5, '{"poet":"Şair Abdulaşk","poet_slug":"sair-abdulask","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/veyso-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'olasiliklar', 'olasiliklar-sair-abdulask-373ic', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün ihtimalleri hesapladım.

Güneşin can çekiştiği vakitlerde,

Sondan üçüncü sigaramı içerken olacak

Ne olacaksa...

Üşengeç kırlangıç sokak lambasında uyuya kalacak,

Çıplak ayaklı çocuğun ayağına cam batacak.             Ağlayacak.

Yağmurlar yağacak,

Köşedeki panzerin altı hariç tüm sokak ıslanacak.

Ve işte o an olacak,

Ne olacaksa...

Biz acıyalım diye kediler bebek taklidi yaparken

Bir yaprak düşecek toprağa, yer sarsılacak.

Ama kimseler duymayacak...

Uzun trenler küçük kasabalara kavuşmama öyküleri taşıyacak.

Tam da o an olacak , ne olacaksa.

Yine de sen üzülme,

Sana birşey olmayacak...', 'Bütün ihtimalleri hesapladım. Güneşin can çekiştiği vakitlerde, Sondan üçüncü sigaramı içerken olacak Ne olacaksa... Üşengeç kırlangıç sokak...', ARRAY['Türk Edebiyatı','Şiir','Şair Abdulaşk']::text[], 8.5, '{"poet":"Şair Abdulaşk","poet_slug":"sair-abdulask","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olasiliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-ahmet-meydan-degw5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gülüşünde gamzelerin

sırlarla dolu bir kapı olurdu

benim için.

O yazlık berraklığın

sonunu getirirdi

kağıttan gemilerimin

ve her kulacımda

biraz daha boğulurdum 

derinliklerinde gözlerinin.', 'Her gülüşünde gamzelerin sırlarla dolu bir kapı olurdu benim için. O yazlık berraklığın sonunu getirirdi kağıttan gemilerimin ve her kulacım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/intihar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar', 'bulutlar-ahmet-meydan-mae2g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüznün kapanır

gözlerine

ve, ufak bulutlar gibi

yağardı yüzüne.', 'Hüznün kapanır gözlerine ve, ufak bulutlar gibi yağardı yüzüne....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulutlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esin''e', 'esin-e-ahmet-meydan-kwylo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzün hüzün kokardı kokuşmuş,sefil yaz akşamlarında;

işte ben en çok bu kokunun masumiyetini severdim

ve en çok böyle akşamların gecelerinde mahvolurdum. Ilık yaz

gecelerinde bir yüzün bir de bu masum hüzün kahretti beni.', 'Yüzün hüzün kokardı kokuşmuş,sefil yaz akşamlarında; işte ben en çok bu kokunun masumiyetini severdim ve en çok böyle akşamların gecelerinde...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/esin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil', 'yesil-ahmet-meydan-30ozi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kokun değildi sanki

yağmurlar altındaki

ıhlamur ağaçlarıydı ,

yeşildi

yaprakların ;

gözlerin.

Kalbin değildi sanki

kondu konacak

iki kırlangıç

avludaki ağaçlarına

kalbimin.', 'Kokun değildi sanki yağmurlar altındaki ıhlamur ağaçlarıydı , yeşildi yaprakların ; gözlerin. Kalbin değildi sanki kondu konacak iki kırlang...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yesil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lale Bahçesi', 'lale-bahcesi-ahmet-meydan-8jdef', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen , gülüşü lale bahçesi

yüzü göçeden iki kırlangıç

gözlerine dalmaya dayanamam

o girdaplar anaforlar

sanadır her dileğim ve

seninledir yüreğim.', 'Sen , gülüşü lale bahçesi yüzü göçeden iki kırlangıç gözlerine dalmaya dayanamam o girdaplar anaforlar sanadır her dileğim ve seninledir yür...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/lale-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlevihane', 'mevlevihane-ahmet-meydan-bfv8b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamanın üstünden geçtiğimiz oldu ,

deliliğin sularına çıplak ayaklarla girdiğimiz

ve bitmeyen aşıklık halimiz

uzaklara giden kuşlar gibi

bırakıp gidişimiz , divaneliğimiz...

Kalbimiz varlığından azad oldukça erir.', 'Zamanın üstünden geçtiğimiz oldu , deliliğin sularına çıplak ayaklarla girdiğimiz ve bitmeyen aşıklık halimiz uzaklara giden kuşlar gibi bır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mevlevihane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can ''ıma', 'can-ima-ahmet-meydan-nyugl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son güneşinde Datça'' nın

tan yeri kızıllığında

şiirler söylerdi.

Bademlerin altına oturur

salkım salkım

üzüm yer gibi

şarap içerdi.

Canımın içiydi

içti

içti

iç oldu.', 'Son güneşinde Datça'' nın tan yeri kızıllığında şiirler söylerdi. Bademlerin altına oturur salkım salkım üzüm yer gibi şarap içerdi. Canımın ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/can-ima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin', 'sesin-ahmet-meydan-h1k25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sana çarpar

yüzün ekşitir.

Sesin depremden 

arda kalan

yangınlar olur ;

çınlar durur

içimde bir yerde.

Bir nota düşer

kırılır yerde

dağılır, saçılır

altıntozu, karbeyazı.

Bir ayin başlar

yürekteli kopar,

kırlangıçlar konar

avluya

ciğerler sızım sızım

kanar.

Sesin olur suretin;

gözyaşıdır 

akar.', 'Seni sana çarpar yüzün ekşitir. Sesin depremden  arda kalan yangınlar olur ; çınlar durur içimde bir yerde. Bir nota düşer kırılır yerde dağ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ancak', 'biz-ancak-kemal-ozer-j1omq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz ancak o vakit

sokaklarda dal bedenli

sevda çağında kızlar

yürüyorsa duraksamadan

dişleri birbirine kenetli

yürüyorsa üstüne üstüne

faşist saldırganlığın

ve grevci işçilerle kol kola

en önündeyse halayın

biz ancak o vakit

Ve daha yirmi yaşında

öğrendiyse alnıyla gülümsemeyi

ve daha yirmi yaşında

yirmi yüzyıl yaşamış gibi özverili

duvağını sarıyorsa yarasına

ve her şeye fiyat biçen dünya

satın alamıyorsa körpeliğini

biz ancak o vakit

söyleyebiliriz sevdamızın

yeni kovanlar için oğul verdiğini', 'Biz ancak o vakit sokaklarda dal bedenli sevda çağında kızlar yürüyorsa duraksamadan dişleri birbirine kenetli yürüyorsa üstüne üstüne faşis...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-ancak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canda Can', 'canda-can-selcuk-yilmaz-j3tyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çizgisinde  yaşamın 

Tanık oluruz , gider canlar birer birer;

Hazan yaprakları gibi sararıp soluşuna;

Dostların gözümüz önünde eriyişine,

Bir veda bile edemeden gidişine,

Ne demeli işte gidip gider 

can dostlar birer birer;

Önce sen gittin sevdiceğim, 

sonra yine sen,

Sonra arkadaşım , bir dostum

Canda can,

Ya da memlekette herhangi bir insan,

Yitip gider her gün bu dünyadan,

Belki de bir hiç uğruna bedavadan,

Bir veda bile edemeden

Öyle apansız aniden,

Olur mu hiç böyle olur mu?

Geride gözler hep yaşlı,

Canları böyle uğurlamak olur mu?....  

                                                         Selçuk Yılmaz   7.4.2001', 'Bir çizgisinde  yaşamın  Tanık oluruz , gider canlar birer birer; Hazan yaprakları gibi sararıp soluşuna; Dostların gözümüz önünde eriyişine...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canda-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir', 'kimbilir-atabay-guveloglu-pif6c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum,çok yakınında,

Yine ilkbahar,yine bahçende hanımelleri.

Uyuyorsun o kutsal yatağında

Yine yüzükoyun,yine yüzü gülümsemeli.

Yine ellerin yastığın altında

Ne güzel uyuyorsun kim bilir?

Ne güzel uyuyorsun...

Seni özlüyorum,çatlamış toprak gibi,

Kaç yıldır susuzum bilemem,kaç ay,kaç hafta.

Ne gecedeyim tanrım,kıyamet kopacak gibi,

Ruh oldum,baş ucundayım hatta.

Aşkı fısıldıyorum,kulaklarında

Ne güzellikler duyuyorsun kimbilir,

Ne güzellikler duyuyorsun...', 'Seni düşünüyorum,çok yakınında, Yine ilkbahar,yine bahçende hanımelleri. Uyuyorsun o kutsal yatağında Yine yüzükoyun,yine yüzü gülümsemeli. ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimbilir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş kalalım', 'arkadas-kalalim-atabay-guveloglu-5m4p2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşık olma bana,candan gönülden,

Sönmüş bir ateşim,yandıramazsın.

Farkı yok gönlümün yangın yerinden,

Külleri ortadan kaldıramazsın.

Bir zamanlar ben de senin gibiydim,

Çiçekli dağların seli gibiydim.

Anlatması çok zor,deli gibiydim,

Gönlüme başka yar aldıramazsın.

Terk edip de gitti ruhumu çalan,

On yıl oldu ama,dop dolu kafam.

Öyle param parça oldu ki dünyam,

İçimi okusan,anlatamazsın.

Dünya güzeliydi,onu geç buldum,

İkinci bahardı,aşkı güç buldum.

Voltaja kapıldım,sanki felç oldum,

Çektiğim acıyı dindiremezsin.

Göründüğüm gibi değilim canım,

Mutsuzum,başka birinde aklım.

Bir avcıdan derin yaralar aldım,

Ne yapsan yüzümü güldüremezsin.

Üzülürsün her gün,mutsuz bulunca,

Ağlatır anılar,akşam olunca.

Arkadaş kalalım ömür boyunca,

Sen onun yerini dolduramazsın.

Sema''nın yerini dolduramazsın,

Dolduramazsın kızım,

Dolduramazsın...', 'Aşık olma bana,candan gönülden, Sönmüş bir ateşim,yandıramazsın. Farkı yok gönlümün yangın yerinden, Külleri ortadan kaldıramazsın. Bir zama...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/arkadas-kalalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahtamad ve Agis', 'ahtamad-ve-agis-atabay-guveloglu-29jg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani,masallarda olur ya,

Mavi gözlü,sap sarı saçları olan,

Uuzun boyu ile dalgalanan bir derya.

Hani,görenlerin aklı gider ya,

Bakan bir daha bakar,

İşte öyle güzel bir kızmış Ahtamar.

Hem de van kralının kızı.

Her kraldan daha katı ve gaddar

Ahtamar''ın babası...

Kendisi saraya,

Güzelliği dünyaya dar geliyor.

Doğayı seviyor,insanlara imreniyor,

Ama çıkamıyor dışarıya.

Kıskanç baba izin vermiyor

Ne ata binmesine,

Ne van Gölü''nde yüzmesine.

Yaşı geliyor otuza,

Ama cesaret edemiyor kimse

Yaklaşamıyor bu kıza.

Ne bu güzelliği görmeye,

Ne kraldan istemeye

Yürekleri yetmiyor...

Saraya meyve getiren bir genç,

Kaderin oyunu çok ilginç.

Adı Agis.

Yakışıklı mı yakışıklı,

Güçlü mü güçlü,fakir bir çiftçi.

Ne kralın kızını bilir,

Ne bu aşk Ahtamar''ın aklına gelir.

Ama birden gözleri görür,

Gönülleri birleşir.

Eros''un aşk oku

Taa yüreklerine gelir.

Sarar bir ateş benliklerini,

Unutup giderler mevkilerini,kimliklerini.

Her gün ancak uzaktan uzağa

Görebilirler birbirlerini...

Gizli gizli buluşmaya,

Saray bahçesinde uçmaya başlarlar.

Aşkın güçlü kollarına atılmaya,

Mutlulğa alışırlar.

Kulağına ulaşır zalim kralın,

Sevgilileri ayırırlar.

Agis,penceresi göle bakan bir zindana,

Ahtamar ise gölün ortasına

Bir adaya gönderilir.

Kralın bir ev yaptırdığı adayı

Zindan penceresinden görür,

Agis,adeta her gün ölür...

Bakarak adaya yıllarca,

''Ahtamaaar,Ahtamaaar''diye bağırır.

Çığlıklarını duyan halkca,

O günden sonra bu adanın adı

''Ahtamar adası''kalır.

Bu hazin aşkın anısına zamanla

Adaya tapınaklar yaptırılır.

Asırlar boyunca Agis ve Ahtamar

Dualarla,ağıtlarla anılır...

Evet Ahtamar^ım,

Evet sultanım!

Sen de benim Ahtamar''ımsın,

Ölümsüz aşkların diyarı Van''dasın,

Gölün suları kadar damarlarımdasın.

senen Agis''in her zaman zindanda,

On üç yıl geçip gitti bir anda.

Deldi de geçti ruhumu,

Eğdi de geçti boynumu.

Sen,yalnız başına Van''da,

Ben,bıraktığın gibi Adana''da.

Ve o büyük aşk,

Bir gurur uğruna ortada!

Hiç unutamadım hiç,niçin?

Anlasana,anlasana...', 'Hani,masallarda olur ya, Mavi gözlü,sap sarı saçları olan, Uuzun boyu ile dalgalanan bir derya. Hani,görenlerin aklı gider ya, Bakan bir dah...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/ahtamad-ve-agis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
