INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-faruk-aysoy-glb9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecemi aydınlatan ateş,

Gönlümü aydınlatan sevgisin,

Çünkü hayatımın tek ışık kaynağısın,

Sen, tüm özelliğinle...

Pırlantadan, elmasdan, tüm madenlerden,

Daha değerli olan yegane varlıksın,

Çünkü gönlümün en büyük ışığı, aşkısın,

Sen, tüm güzelliğinle...

İnsanlara mutluluğu tattıran tek canlı,

Bana ise aşkı tattıran yegane insansın,

Çünkü dünya üzerinde tek olansın,

Sen, tüm kutsallığınla...', 'Gecemi aydınlatan ateş, Gönlümü aydınlatan sevgisin, Çünkü hayatımın tek ışık kaynağısın, Sen, tüm özelliğinle... Pırlantadan, elmasdan, tüm...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Bende Saklı', 'adi-bende-sakli-faruk-aysoy-93yri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel gözleriyle içimi aydınlatan,

Tatlı sözleriyle yüzümü güldüren,

Kara saçılya özelliği barındıran,

Adı bende saklı olan güzel.

Gülücükleriyle etrafa neşe saçan,

Aşkıyla kalbini ateşlendiren,

Sevgisiyle bana baharı getiren,

Adı bende saklı olan güzel.

Her ne kadar onu kendime saklasamda,

Yalnızlığıma onunla son versemde,

İsmini yazarken elim titrese de,

Onun adı güzel MELİSAdır güzel MELİSA...', 'Güzel gözleriyle içimi aydınlatan, Tatlı sözleriyle yüzümü güldüren, Kara saçılya özelliği barındıran, Adı bende saklı olan güzel. Gülücükle...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-bende-sakli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melisa', 'melisa-faruk-aysoy-o9x2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Melisadır onun adı,

Mutlulukların perisi,

Yalnızlığın baş düşmanı,

Aşkın en güzeli.

Melisadır onun adı,

Her derdin devası,

Güzelliğin mimarı,

Gönüllerin sultanı.

Melisadır onun adı,

Herşeyden özel olanı,

Bana yaşatan aşkı,

Kalbimde açtıran çiçekleri.', 'Melisadır onun adı, Mutlulukların perisi, Yalnızlığın baş düşmanı, Aşkın en güzeli. Melisadır onun adı, Her derdin devası, Güzelliğin mimarı...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/melisa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut Kalmalı', 'bir-umut-kalmali-asli-gunbars-nmahj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir parça umud kalmalı geriye

Yıkılan hayallerinardından

Bir parça sevgi kalmalı yürekte

O bitirilen sevdalara inad

Bir bakış kalmalı ki 

Gitmelerin ardından bir ömür  unutulmamacasına

Bir hatıra kalmalı ki düşlerde

Düş olduğundan şüpheli

Yinede...

Yineden bir parça umud kalmalı geriye 

Kalmalı ki hapsolmalı

KARANLIKLAR!!!!', 'Bir parça umud kalmalı geriye Yıkılan hayallerinardından Bir parça sevgi kalmalı yürekte O bitirilen sevdalara inad Bir bakış kalmalı ki  Gi...', ARRAY['Türk Edebiyatı','Şiir','Aslı Günbars']::text[], 8.5, '{"poet":"Aslı Günbars","poet_slug":"asli-gunbars","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-umut-kalmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umud Kalmalı', 'bir-umud-kalmali-asli-gunbars-01akp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir parça umud kalmalı geriye

Yıkılan hayallerinardından

Bir parça sevgi kalmalı yürekte

O bitirilen sevdalara inad

Bir bakış kalmalı ki 

Gitmelerin ardından bir ömür  unutulmamacasına

