INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Ağaç Böyle Harikulade Yemiş Vermemiştir...', 'hic-bir-agac-boyle-harikulade-yemis-vermemistir-nazim-hikmet-ran-xp7z6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Topraktan ateşten ve denizden 

doğanların

en mükemmeli doğacak bizden...

