INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanan Yıldız', 'yanan-yildiz-ahmet-i-nce-a6ohq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzanıp yattım

yanan bir yıldızın koynuna

Kızgın bir kumsalın

 kalbine uzanırcasına

Aşkın ateşiyle

gülümseyen kara gözlerin

Işıltılar saçarak

gezinmişti tutkulu tenimde

Kürelerin

ateşte birleşen

iki bombaydı sanki

Bereketli ovalarda  

 bir kolun kızıl

öteki mavi ırmaktı

En baskın mutluluk

ırmaklar arasında 

suskunca kaybolmaktı

Dolu dolu yaşadık

Deltasında arzuların

Gelip geçti altın bir mevsim

Enlem ve boylamlarında tutkuların', 'Uzanıp yattım yanan bir yıldızın koynuna Kızgın bir kumsalın  kalbine uzanırcasına Aşkın ateşiyle gülümseyen kara gözlerin Işıltılar saçarak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yanan-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı 2', 'sarki-2-yahya-kemal-beyatli-5wrbe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah eden kimdir bu saat kuytuda

Sustu bülbüller,hıyaban uykuda

Şimdi ay bir serv-i simindir suda

Esme ey bad,esme canan uykuda

Başka aşıklardan almışsan nefes

Başka yerden, başka vadilerden es

Doğmasın ruhunda ani bir heves

Esme gülşenden ki canan uykuda', 'Ah eden kimdir bu saat kuytuda Sustu bülbüller,hıyaban uykuda Şimdi ay bir serv-i simindir suda Esme ey bad,esme canan uykuda Başka aşıklard...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sarki-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdaydı Yaşanılan', 'bir-sevdaydi-yasanilan-bulent-karasu-ykdgu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR SEVDAYDI YAŞANILAN

                    Öncesi benliksiz

                    Sonrası sensizlik 

                    Bir sevdaydı yaşanılan

                    Sadece şimdisi vardı

                    Ama şimdi yoktu...

                    Gerçekten uzun mu sürmüştü?

                    Yoksa gereğinden kısa mı?

                    Her yanı belgisiz 

                    Belli belirsiz 

                    Bir sevdaydı yaşanılan.

                    Sorulacak çok şey vardı

                    Ama tek cevap yoktu...

				

						BÜLENT KARASU', 'BİR SEVDAYDI YAŞANILAN                     Öncesi benliksiz                     Sonrası sensizlik                      Bir sevdaydı yaşanıla...', ARRAY['Türk Edebiyatı','Şiir','Bülent Karasu']::text[], 8.5, '{"poet":"Bülent Karasu","poet_slug":"bulent-karasu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-sevdaydi-yasanilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığımız', 'varligimiz-bulent-karasu-mewxc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'VARLIĞIMIZ

                 Vuslatını düşünerek geçmiyor zaman

                 Tesellisi  olmazmış zaten ayrılığın

                 Gökyüzünden ufuğa doğru uzaklaşan

                 Yıldızlardan daha uzak şimdi varlığın.

      

                 Kanayan yaralarım var yardan armağan

                 Hasretinden ibaret bütün yalnızlığım

                 Kaçan gözlerini düşündükçe ağlayan 

                 Hüzün yağan bir buluttur şimdi varlığım...', 'VARLIĞIMIZ                  Vuslatını düşünerek geçmiyor zaman                  Tesellisi  olmazmış zaten ayrılığın                  Gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Bülent Karasu']::text[], 8.5, '{"poet":"Bülent Karasu","poet_slug":"bulent-karasu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/varligimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O 45 Saniye..', 'o-45-saniye-arzu-dincer-zsrfx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kardesimdi ranzami paylastigim, 

         Ust katta duydukca nefesini mutlu oldugum. 

         Yaz gecesinin tatli yorgunlugunda, 

         Annemle Babamin buyuten opucuguydu 

         Yanaklarimiza konan. 

         Yarin kumdan kaleler yapacaktik. 

         -Cunku ufakligin hayaliydi gerceklerini yapmak... 

         Bilemedik kumdan evlerde uyudugumuzu. 

         Daldik cocuk ruyalarin sardigi uykuya. 

         Ruyaydi o biliyorum... 

         ''Annem bebek besigimde salliyordu beni, 

         Nedense kardesim agliyordu, 

         Karanlikta bir yerlerde....'' 

         Anlamsiz geldi sonradan ogrendigim 

         O 45 saniye.. 

         Sabah olmak bilmedi, 

         Uyanmak istesemde ruyamdan.. 

         Seslendim canim ust katta yatan kardesime, 

         Ses vermedi.. ya da duyuramadim sesimi. 

         Annemle Babam da yoktu yanimda, 

         -Oysa bir yan odadan 

         Kimbilir kac defa kosmuslardi 

         Bir sesimize.. 

         Beklemenin ve zamanin bilmiyordum anlamini, 

         Ama! ''Cocuk uykum, YETER! bit artik'' dedikce..., 

         Agirlik vardi ustumde, uyanamadim. 

         Kac zaman gecti bilmemezligin ustunden, 

         Ya da kac aydede gorundu gokyuzunde? 

         Bir isik sizdiginda iceriye, 

         Bilemedim, cocuk uykum nasil bitti. 

         Bir amca el uzatti bana, 

         Konustu, durmadan benimle. 

         Babamin sesi degildi.. 

         Aklima dustu birden annem, 

         ''Yabancilarla konusma'' derdi bana, 

         Seslendim kardesime, 

         ''Sakin konusma..'' 

         Ama ses vermedi bana, 

         Ne ''Konuscam'' ne de '' Konusmiycam'' diye 

         Beni cektiklerinde, 

         Soz verdim kendime, 

         Bir daha asla ruya gormiycam, 

         Cocuk olupta, cocuk ruyasi olsa bile...', 'Kardesimdi ranzami paylastigim,           Ust katta duydukca nefesini mutlu oldugum.           Yaz gecesinin tatli yorgunlugunda,           ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/o-45-saniye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Mutlu Ol Yeter', 'sen-mutlu-ol-yeter-i-nci-ozcan-r99xh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün benim ilk aldanışım 

İlk aldanışımın yerine içiyorum

Bir ela gözlüm vardı oda eskiden

Bugün onun düğününü kutluyorum

Kızma be meyhanesi

Kırılan boş şişeler olsun

Bir ela gözlüm vardı oda eskiden

Bugün onun dügününü kutluyorum

üzülme yerine siyahı mavisi gelir

Yeterki o mutlu olsun', 'Bugün benim ilk aldanışım  İlk aldanışımın yerine içiyorum Bir ela gözlüm vardı oda eskiden Bugün onun düğününü kutluyorum Kızma be meyhanes...', ARRAY['Türk Edebiyatı','Şiir','İnci Özcan']::text[], 8.5, '{"poet":"İnci Özcan","poet_slug":"i-nci-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-mutlu-ol-yeter-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Okulu', 'sevgi-okulu-ahmet-i-nce-mzdci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kirli bir gecenin sabahında 

tırmalıyor beynimi elleri yorgunluğun

süzüyor umudu şiir

avuçlarımda aşınmamış imgeler

boşuna beklemesin kapıda kara duygu

göz kapaklarım geçit vermez artık

                               mor karanlıklara

üzünç duvarını aşıp geçmek 

ve ballı dudaklarından yaşamın

                               öpmek istiyorum

duygularım öğrenci

yüreğim sevi okulu 

çiçek açmış elimde şiir 

kalemim karanfil kokulu

                                Trabzon

                             05.03.1984', 'kirli bir gecenin sabahında  tırmalıyor beynimi elleri yorgunluğun süzüyor umudu şiir avuçlarımda aşınmamış imgeler boşuna beklemesin kapıda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-okulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 1', 'mektup-1-osman-yuksel-serdengecti-at0vh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilimin ve kalemimin ucundasin,

Fakat kalbimin icinde,

Su tukenen yillara sor, gecelere

gunduzlere sor: kiminleyim ben?

Hic sizin semtinizde vefa ruzgari esmez mi?

Daglara seslendim, onlar bile ses verdi de

Sen neden susuyorsun...

Sen ses ver de senin semtinden esecek vefa

ve ask ruzgarlarina bagrimi acayim..

cigerlerime cekeyim...

''Beni ne yapacaksin'' deme

''Benim yuzumden ne hale gelmissin'' de!

Yollarda ayak izlerini gordum,

Bu izlere yuzlerimi surdum.

Evet, buralardan gecen sensin!..

Yollardan gectigin gibi benden de mi gececeksin?..

Yollardaki izlerini baska izler bozar siler...

Fakat kalbimde biraktigin izler ebedidir, bozulmaz, silinmez...

Seni dusune dusune dusume giriyorsun

Onun icin ben, gunduzlerden cok geceleri sever oldum

Senin olmadigin yerde gunes yok bana

Ates yok bana..Hayat yok bana...

Muhacir kuslar sicak iklimlere goctuler

Demek ki goc zamani..benim kusumsa

''ask'' denilen kafeste cirpinip dudu.

Seninle olduktan sonra her sey sicaktir bana

Son bahar bile ilk bahar gibidir.

Bir baktin canimi yaktin

Bir daha bak ki , kul olayim, savrulayim...

Bu bayram da sensiz gecti.Seninle her gun bayram bana

Sen olmayinca bayramdan ne haber?

Is bildigin gibi degil.Bilmedigin gibi...

Sen kendine bakma, bana bak..neler oluyor o zaman anlarsin

Oldugum zaman mezarima gel

De ki '' bu adam benden neler cekti

Ey toprak, boyle bir dertliyi sen nasil cekiyorsun...''', 'Dilimin ve kalemimin ucundasin, Fakat kalbimin icinde, Su tukenen yillara sor, gecelere gunduzlere sor: kiminleyim ben? Hic sizin semtinizde...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Serdengeçti']::text[], 8.5, '{"poet":"Osman Yüksel Serdengeçti","poet_slug":"osman-yuksel-serdengecti","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mektup-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azgın Irmak', 'azgin-irmak-ahmet-i-nce-mt6t7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yeni doğmuş bir ay gibi

düşlere giren melek

dün gece azgın bir ırmak oldun

durmaksızın üstümden akarak

beni dipsiz karanlıklarda bıraktın

gel beni yeniden ışığa çıkar

dün gece yarısı

açıldı göğsünün mor çiçeği

ıslandı menekşeler öpücüklerden

dudak dudağa çarpışan sözler

yavaş yavaş 

ısındı sınırsız bir neşeden

parladı kadın gözlerinde

bir tanrıça gülüşü

parladı söndü

tanımsız bir endişeden

ıslak bir gecelikte gizlenen incelik

sıyrıldı yumuşacık bir tenden

birleşince çırpınan iki beden

kıvılcımlar sıçradı çakışan yüreklerden

                  TRABZON

                  Ekim-1994', 'yeni doğmuş bir ay gibi düşlere giren melek dün gece azgın bir ırmak oldun durmaksızın üstümden akarak beni dipsiz karanlıklarda bıraktın ge...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/azgin-irmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 2', 'mektup-2-osman-yuksel-serdengecti-ns7l0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen benden ne ayrisin, ne gayri...

Amma feryatlarim neye? 

Gidisin bir turlu harap ediyor beni, gelisin bir turlu...

Fakat bu iki harabe arasindaki cani gor! ...

Senin icin ''geliyor'' dediler; aklim gitti.

Gelirsin, aklim gider; gidersin, aklim gider..

Acik soyle sen akil dusmani misin? ...

Topraga dusen tohum gibi

ben de ayaklarina dusuyorum...

Bu ask ne zaman basak verecek? 

Sen; '' Sen ne olursan ol, bana ne? '' diyorsun...

Ben; ''Ne olursan ol bana gel! ...''diyorum...

Hangimiz hakliyiz? ..Soyle..

Artik bu is boyle gitmez. Artik bu attek

Boyle tutmez. Dumanim kesildi, serapa 

kor oldum..Anla...

Aksam oluyor, gunes batmak uzere...

Ask uzun bir geceye benzer.

Sabah ayiklar icindir.

Biz ki sarhosuz.

Gel! ...uzun gecelere burunelim...', 'Sen benden ne ayrisin, ne gayri... Amma feryatlarim neye?  Gidisin bir turlu harap ediyor beni, gelisin bir turlu... Fakat bu iki harabe ara...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Serdengeçti']::text[], 8.5, '{"poet":"Osman Yüksel Serdengeçti","poet_slug":"osman-yuksel-serdengecti","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektup-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Işığı', 'askin-isigi-ahmet-i-nce-muq4x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göğsün göğsümde

Dudakların yalımlarda

Saçlarının çağlayanı tenimde

Sevgi için sahil yok

                 liman yok

                   durak yok zaman için

Aşkın ışığında susalım artık

Sessizlik ve gizemdir ötesi

Kutsal sözlerin ruha inişi gibi

İnelim gizemlerine tutsak isteklerin

Aşk ışınlarının fışkırdığı öpüşlerde

İki dalga iki okyanus olsun gece

Ve içelim sessizliği delice

İstek yağmurlarında

                               ıslansın ellerimiz

Boşlukta uçan iki yıldız gibi

               sevginin gökyüzünden

                  inelim   yeryüzüne               

                                 TRABZON

                                 19.12.2000', 'Göğsün göğsümde Dudakların yalımlarda Saçlarının çağlayanı tenimde Sevgi için sahil yok                  liman yok                    durak ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilmeyeceksin', 'sen-bilmeyeceksin-oya-erdemci-4tr6e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bembeyaz örtülerde,

Kırmızı güllerin süslediği

Mum ışığı ve hüzün

Elimde bir kadeh şarap

Gözlerim kapıda...

Saatler telaşlı

Kapı ha çaldı ha çalacak

Ama gelmeyeceksin

Beklenenin sen, bekleyenin bel olduğumu bilmeyeceksin.

Hüzün dalgaları yayılacak odaya,

Bembeyaz sayfalarda

Adına yazılmış şiirler

Sayfalar dolusu aşk mektupları

Ama sen bilmeyeceksin

Sevenin ben,sevilenin sen olduğunu.

Zamanla sen olacağım

Adım adım yaklaşacağım sana

Gölgen olacağım,ruhun olacağım

Bir gün kapın çalacak

Açacaksın,yabancı sanacaksın

Yine bilmeyeceksin

Aslında bu gelenin sen olduğunu.', 'Bembeyaz örtülerde, Kırmızı güllerin süslediği Mum ışığı ve hüzün Elimde bir kadeh şarap Gözlerim kapıda... Saatler telaşlı Kapı ha çaldı ha...', ARRAY['Türk Edebiyatı','Şiir','Oya Erdemci']::text[], 8.5, '{"poet":"Oya Erdemci","poet_slug":"oya-erdemci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-bilmeyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharda Sevdim', 'baharda-sevdim-oya-erdemci-obixm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni baharda sevdim birtanem

Tohumun toprağa,suya uyanışı gibiydi

Ruhumun uyanışı sevgine

Güneş değildi ısıtan beni

Sevgindi sıcaklığını hissettiğim

Haykırışlarımda adın gizliydi

Gecelerimde hayalin

Bahardı benim için artık her mevsim.', 'Ben seni baharda sevdim birtanem Tohumun toprağa,suya uyanışı gibiydi Ruhumun uyanışı sevgine Güneş değildi ısıtan beni Sevgindi sıcaklığını...', ARRAY['Türk Edebiyatı','Şiir','Oya Erdemci']::text[], 8.5, '{"poet":"Oya Erdemci","poet_slug":"oya-erdemci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baharda-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-yeliz-cevheroglu-m5rc4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözümde

bir damla yaş, yağar durur,

yağar durur.

Bırak yağsın, güzelleşir

hayat.

Bahardır yağmur,

hayattır sudur.

Sevgidir bir damla,

o göz yaşı.

Sevgidir hayat.

Sevgidir yaşam.', 'Gözümde bir damla yaş, yağar durur, yağar durur. Bırak yağsın, güzelleşir hayat. Bahardır yağmur, hayattır sudur. Sevgidir bir damla, o göz ...', ARRAY['Türk Edebiyatı','Şiir','Yeliz Cevheroğlu']::text[], 8.5, '{"poet":"Yeliz Cevheroğlu","poet_slug":"yeliz-cevheroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozyasi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tanımı', 'askin-tanimi-baris-ozkaya-bgyjp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biri aşk nedir diye sormuş

Binbir ülkeden binbir kişiye

Binbir değişik cevap almış

Biri binbir kere aşık olmuş

Değişmiş aşkın anlamı

Her seferinde binbir kere

Aşk kayıp sözlüğün arasından

Bir kuyuya düşmüş

Binbir aşık çıkaramamış

Aşkın tanımı yokmuş

Ama herkes ''aşık'' olmuş', 'Biri aşk nedir diye sormuş Binbir ülkeden binbir kişiye Binbir değişik cevap almış Biri binbir kere aşık olmuş Değişmiş aşkın anlamı Her sef...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askin-tanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennete Davet', 'cennete-davet-baris-ozkaya-0m7h0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıpkırmızı elmalardan davet var

Çitlerin arkasından davet

Davet Var Davet

Yasak bahçeye davet

Çitlerden atlamak yasak

Çitleri parçalayıp gelin

Gelin Koşun Gelin

Burası elma bahçesi

Tırmanın ağaçlara

Elmalardan davet var

> Davet Var Davet

> Cenete davet

> Davete gelin

> Gelin Koşun Gelin

> Dünyaya cennet var', 'Kıpkırmızı elmalardan davet var Çitlerin arkasından davet Davet Var Davet Yasak bahçeye davet Çitlerden atlamak yasak Çitleri parçalayıp gel...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cennete-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin;', 'gittin-arif-baltaci-zw8h8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin;

Yağmurlu bir sabahtı

Benim içimde

Akşamdan kalma hüzünler

Yaşadığımız hatıralar vardı

Neler vermezdim seni döndürmek için

Çıktığın yani beni terkettiğin

Yani beni terkettiğin

Yani beni mahvettiğin

Yoldan seni döndürmek için neler vermezdim

Gittin;

Sebebebini bile söylemeden

Sevmemişmiydim seni gönülden

Aşk nağmelerini hiç düşürmüşmüydüm dilimden

Ve sen,bir an olsun çıkmamıştın kalbimden

Avutulurmu sanıyorsun bu yürek

Zamanda sensizliği yaşayabilirmiyim

Gittin;

Ardında kaldı bu deli çocuk

Neden giderken beni götürmedin

Neden giderken bu aşkı bitirmedin

Ben bu filmi çok izledim

Hadi şimdi kendini de bitir

Aşkımız,aşkımız gibi bitir...', 'Gittin; Yağmurlu bir sabahtı Benim içimde Akşamdan kalma hüzünler Yaşadığımız hatıralar vardı Neler vermezdim seni döndürmek için Çıktığın y...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-yeliz-cevheroglu-s6632', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen,

güller açar içimde.

Solmasınlar.

Gözyaşlarımla sular,

sevgim ile beslerim.

İzin ver,

adını, 

biraz değiştireyim:

''Dost'' diyeyim.

''Sevgili''nin yanına,

''Dost''u da ekleyeyim', 'Bazen, güller açar içimde. Solmasınlar. Gözyaşlarımla sular, sevgim ile beslerim. İzin ver, adını,  biraz değiştireyim: ''Dost'' diyeyim. ''Sev...', ARRAY['Türk Edebiyatı','Şiir','Yeliz Cevheroğlu']::text[], 8.5, '{"poet":"Yeliz Cevheroğlu","poet_slug":"yeliz-cevheroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dost-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Aşk Böyledir', 'her-ask-boyledir-arif-baltaci-iaqr1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep bu son olsun dedik 

Ve başladık aşklara

Güneşin doğmasıyla.

Ama bozuldu büyü

Her aşkın ortasında.

Ya beceremedik sevmeyi

Ya da aşk bize tersti.

Sonra olgunlaştık

Her ne kadar içimizde

Deli çocuklar olsada 

Olgunlaştık işte.

Her aşkta biraz daha yıprandık

Kanadık,boyuna ağladık

Bir sigaradan,bir aşktan çektik içimize 

Yanına denizi de bıraktık.

Her biten aşkla gitti

Kalbimizin bir yerleri

Bilinmez uzaklara', 'Hep bu son olsun dedik  Ve başladık aşklara Güneşin doğmasıyla. Ama bozuldu büyü Her aşkın ortasında. Ya beceremedik sevmeyi Ya da aşk bize ...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/her-ask-boyledir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Bir Yarısı', 'gecenin-bir-yarisi-arif-baltaci-2gszo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı;

Bir acı düşer yüreğine

Çırpınırsın,kanarsın boyuna

Sonra yer çekimine uyarsın 

Gözünde damlalarla.

Yaşamı hatırlarsın

Çocukluğunu

Dönsen sanki uzanacaksın 

Bıraksan sanki ömür boyu kopacaksın

Gecenin bir yarısı;

Yağmur yağmaya başlar

O tenha sokaklara 

Her cama vuran damlada 

Gidersin uzaklara

Sonra yer çekimine uyarsın 

Gözünde damlalarla.

Sevdiğini hatırlarsın

Dönsen sanki öpeceksin

Bıraksan sanki hiç göremeyeceksin

Gecenin bir yarısı;

Bir sigara yakarsın

O karanlık odanda 

Yalnız kalırsın

Yapayalnız

Sonra yerçekimine uyarsın

Gözünde damlalarla.

Anneni hatırlarsın

Acıların koynunda 

Dönsen sanki sarılacaksın boynuna

Bıraksın sanki öldüreceksin onu da 

Gecenin bir yarısı;

Gideceksin uzak diyarlara 

Korkma...sakın ha korkma', 'Gecenin bir yarısı; Bir acı düşer yüreğine Çırpınırsın,kanarsın boyuna Sonra yer çekimine uyarsın  Gözünde damlalarla. Yaşamı hatırlarsın Ço...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gecenin-bir-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erirdi Yüreğim', 'erirdi-yuregim-arif-baltaci-hen5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve erirdi yüreğim

Değince gözlerime gözlerin

Sense baharı yaşardın 

Görmediğim 

Tatmadığım baharı

Sahi baharların vardı senin

Yüreğine kattığın

Aşkı yaşattığın

Beni aldattığın 

Baharların vardı

Unutmuşum!!!', 'Ve erirdi yüreğim Değince gözlerime gözlerin Sense baharı yaşardın  Görmediğim  Tatmadığım baharı Sahi baharların vardı senin Yüreğine kattı...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/erirdi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmayınca', 'sen-olmayinca-ramazan-erdogan-kwz9u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rüyalar yetmiyor,

hayaller avutmuyor,

sen olmayınca!

güneş ısıtmıyor,

yılıdızlar sönüyor,

sen olmayınca!

gözlerim dalıyor,

aklım almıyor,

sen olmayınca!

gül soluyor,

bülbül susuyor,

sen olmayınca!

canım yanıyor,

yüreğim acıyor,

sen olmayınca!

notalar eskiyor,

şarkılar susuyor,

sen olmayınca!

yollar uzuyor,

bitmek bilmiyor,

sen olmayınca!

işte böyle,sen olmayınca;

olmuyor işte!', 'rüyalar yetmiyor, hayaller avutmuyor, sen olmayınca! güneş ısıtmıyor, yılıdızlar sönüyor, sen olmayınca! gözlerim dalıyor, aklım almıyor, se...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-olmayinca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Zorki', 'oyle-zorki-ramazan-erdogan-z2hz8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alışamadım aşkım,

ne gidişine,ne terkedişine...

öyle zorki yaşamak:

seni sensiz,

seni yıldızlarda

seni hergün doğan ayda,

batmak bilmeyen güneşte,

tek dostum gecelerde,

en sevdiğim şarkının melodisinde,

içtiğim suda,

yediğim yemekte,

çaresiz gülüşlerde,

ağlayan gözlerde,

kanayan yüreğimde,

öyle zorki yaşamak...

seni sensiz ve öylesine...', 'alışamadım aşkım, ne gidişine,ne terkedişine... öyle zorki yaşamak: seni sensiz, seni yıldızlarda seni hergün doğan ayda, batmak bilmeyen gü...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oyle-zorki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemedim mi?', 'ozlemedim-mi-ramazan-erdogan-ylpit', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hadi!söksene ismini kalbimden!

alsana hadi beni benden!

ama,ama aldın ya giderken,

beni gözü yaşlı,

beni ardına bakmadan,

bir elveda bile demeden...

aaah!ah!özlemedim mi zannedersin be!

ben hasretini çektim her nefeste içime!

ölüyorum anlasana be zalim,günden güne!

dön bir ardına nolur!

bak lütfen,bir an bir saniye bile olsa gözümün içine!

bitti de!sevmiyorum de be zalim!

ama nerde sende o yürek!

nerde sende o cesaret?

özlemedimmi be!

özlemek ne kelime!

astım ben kendimi hergün,

ismini kazıdığım ağacın dallarına,bile bile!

ölmedim genede be kahrolası!

acıtmadı nefessiz kalışım,

giderken gözüme bakmayışın kadar!

özlemedimmi be!özlemek ne kelime!

kor alevler içtim kadehlerde,

içim yana yana haykırdım ismini gecelere!

yıldızlar bile duydu,sen duymadın be zalim!

bulutlar ağladı benimle,yalvardılar benim için ardından...

ya sen?ya sen ne yaptın söylesene!

bitti dedinmi gözlerime?

sebep söyledinmi yüreğime?

aaaah!ah!özlemedimmi be!

özlemek ne kelime!

eriyorum ben her an,her saniye,

hemde bile bile...', 'hadi!söksene ismini kalbimden! alsana hadi beni benden! ama,ama aldın ya giderken, beni gözü yaşlı, beni ardına bakmadan, bir elveda bile de...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ozlemedim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemen', 'yasemen-ramazan-erdogan-fv8qa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benliğinle hislerinin zıtlaştığı anlar vardır...

biri alır beni götürür sana,

biri alır benliğimi benden öte yanlızlığa!

söylesene gül kokulum:

ya çıkmasaydın karşıma?

dört bir yanım duvar,

bir yanda eski,kırık dökük sevdalar,

bir yanda dağların arkasında umutlar,

başım iki elim arasında,

söylesene gül kokulum

ya ağlarsam karşında?

güldürmez yüzümü hüzünler,

ağlattı desem yetermi dersin?

yarınsız dünü,bugünden ömrümü çaldı desem?

ve küçük odamda ağlayıp inlesem,

söylesene yasemen kokulum,

ya ben kollarında ölürsem?', 'benliğinle hislerinin zıtlaştığı anlar vardır... biri alır beni götürür sana, biri alır benliğimi benden öte yanlızlığa! söylesene gül kokul...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasemen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belkide', 'belkide-ramazan-erdogan-j3r9w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sonsuzlukta bağırsan tüm gücünle,

essen buz gibi,soğuk bir rüzgar gibi derinlere,

nafile deseler yıkılmasan

inat etsen yada benim gibi,

seversin sende bir gün en az benim gibi...

ertelenmez denir sevdalar,

varoluşun sebebidir ya hani sevmek

mahvolmak,ağlamak,terkedilmek hani,

eninde sonunda bulur ya seni,

merak etme yaşarsın sende bir gün en az benim gibi...

eğilse bütün dağlar önünde,

incitsen küçükte olsa bir kalbi

zorlasan biraz sende yüreğini benim gibi,

inandırsan onu sevebilirsin diye hani,

nerde olursa olsun bulursun,kimbilir,belkide beni...

vay halime deme hiçbirzaman

erkek gibi derler ya hani,güçlü ol sende

razı ol azda olsa kaderine,

yılma asla hayattan en az benim gibi

sorma hesabını kendine geçen yılların,

eğilme hayatın nede aşkın önünde hiçbir zaman

mahvoldum deme güçlü ol hani

inandır demiştim ya sana yüreğini

ne zaman olursa olsun bulursun,kimbilir belkide beni...

(baş harfler:seni sevmeme izin ver yasemin)', 'sonsuzlukta bağırsan tüm gücünle, essen buz gibi,soğuk bir rüzgar gibi derinlere, nafile deseler yıkılmasan inat etsen yada benim gibi, seve...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/belkide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-ramazan-erdogan-159o4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıldızlar hep gecemi çıkar zannedersin?

bulutlar hep ağlarmı dersin?

yaprağı hep solarmı bilirsin?

öyleyse eğer sen bi delisin!

toprak hep çatlarmı zannedersin?

yağmur hep yağarmı dersin?

güneş hep doğarmı bilirsin?

öyleyse eğer sen bi delisin!

aşklar hep bitermi zannedersin?

gözlerin hep ağlarmı dersin?

söyle!sen hep yanlızmı kalırsın?

öyleyse eğer yüreğim,sen bi delisin!', 'yıldızlar hep gecemi çıkar zannedersin? bulutlar hep ağlarmı dersin? yaprağı hep solarmı bilirsin? öyleyse eğer sen bi delisin! toprak hep ç...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin için', 'senin-icin-ramazan-erdogan-crmg0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kucak dolusu hasretle çıktım karşına,

yanlız başıma aştım dağları ben.

senin için...

yaş dolu gözlerle çıktım karşına,

yanlız başıma aştım denizleri ben,

senin için...

susmuş bi yürekle çıktım karşıan,

yanlız başıma aştım engelleri ben,

senin için...

ayrılık dolu sözlerle çıktın karşıma,

ve yanlız bbaşına aşamdın hiçibir şeyi sen!

ayrılık ise;

benim için...', 'kucak dolusu hasretle çıktım karşına, yanlız başıma aştım dağları ben. senin için... yaş dolu gözlerle çıktım karşına, yanlız başıma aştım d...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senin-icin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madalya', 'madalya-sunay-akin-s6l4y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'koltuk deyneklerini

bırakamadığı için alkışlamadığına

inandırır herkesi

Ölü askerlerin ceplerinden

topladıkları kanlı fotoğrafları

barış toplantılarında

sinema önündeki çocuklar gibi

birbirleriyle nasıl değiştirdiklerini

bilir generallerin

Kaç askeri

kendisine özendirdiğini de saymıştır

savaşın tam ortasında

kuyruğunu bırakıp

kum torbaları arasından

evine kaçan kertenkelenin

Bayram yerinde canlandırılırken

kentin kurtuluşu

ayakları kesilen gazi

hiç düşünmeden

değişir madalyasını

çorap kokusuna', 'koltuk deyneklerini bırakamadığı için alkışlamadığına inandırır herkesi Ölü askerlerin ceplerinden topladıkları kanlı fotoğrafları barış top...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/madalya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyormusun?', 'biliyormusun-ramazan-erdogan-ls85b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'korkuyorum,

yanımda olmadığın anlarda,

ya gidersen diye...

korkuyorum işte,

anlamsızmı geliyor?saçmamı buluyorsun?

hayır diyosun ama

gözlerin öyle demiyo biliyomusun?

üşüyorum,

sarıyosun beni kollarına ama

sende üşüyosun...

yanan bi alevinmi ortasındayız?

evet diyosun ama,

yüreğin öyle demiyo biliyomusun?

ve gidiyorum işte!

yaşanmamış bir aşkın hayalini kurmuşum ben,

kalayımmı?seviyomusun?

evet diyosun ama,

gözyaşların öyle demiyo biliyomusun?', 'korkuyorum, yanımda olmadığın anlarda, ya gidersen diye... korkuyorum işte, anlamsızmı geliyor?saçmamı buluyorsun? hayır diyosun ama gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/biliyormusun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece', 'bu-gece-ramazan-erdogan-2c9jf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu gece öyle özledimki seni,

gözlerini,sesini,herşeyini,

gözümde canlanır olursun ya,

anladım;

hasret bağrımda bir yara...

bu gece öyle hasretimki sana

ellerine,yüzüne,herşeyine,

hayalin canlanır olur ya karşımda

anladım;

üzmek boşuna...

bu gece öyle muhtacım ki sana,

gülüşüne,öpüşüne,herşeyine,

rüyamda gelir olursun ya yanıma,

anladım;

unutmaya çalışmak boşuna', 'bu gece öyle özledimki seni, gözlerini,sesini,herşeyini, gözümde canlanır olursun ya, anladım; hasret bağrımda bir yara... bu gece öyle hasr...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-gece-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim-2', 'yuregim-2-ramazan-erdogan-oc6kd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gönlümde sahte sevdaların derin izleri,

içimde cevapsız onlarca soru,hiçmi sevilmedim ben?

yada hiçmi sevmedi yüreğim?

bu moral bozukluğu,

bu iç çekişler,

gözlerimden düşen yaşlar neden?

yalanmı bütün sevdalar?

boşunamı uykusuz geçen onlarca gece?

hep hayal kırıklığı,

hep başıboş sevdalarmı bulur beni?

yada anlamsız mı gelir yaşamak?

severken seni sevmeyeni...

keşkelerle örülü bir hayat,

yaşamak zor,alışmak zor

hepmi yanarsın be yüreğim,

hepmi umutsuz sevdalara kapılırsın?

söyle!sen ne zaman akıllanırsın?

bilmezsin ama,aslında beni birtek sen yakarsın!', 'gönlümde sahte sevdaların derin izleri, içimde cevapsız onlarca soru,hiçmi sevilmedim ben? yada hiçmi sevmedi yüreğim? bu moral bozukluğu, b...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregim-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalırmısın?', 'kalirmisin-ramazan-erdogan-7445v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözyaşım yağmura karışıp,

yanağımdan süzülse,

istesem ne olur desem 

kalırmısın yanımda?

soğukta kuruyan yaprağım,

rüzgarla düşse yerlere,

istesem ne olur desem

kalırmısın yanımda?

üşüsem soğukta,

korksam karanlıkta,

istesem ne olur desem 

kalırmısın yanımda?

sana ruhumu

sama ömrümü verdim desem

istesem ne olur desem 

kalırmısın yanımda?

ve.....

seni sevdiğimi söylesem

boynum bükük,çaresiz,

kızarmısın küsermisin?kalırmısın yanımda?

istesem ne olur desem

kalırmısın yanımda?', 'gözyaşım yağmura karışıp, yanağımdan süzülse, istesem ne olur desem  kalırmısın yanımda? soğukta kuruyan yaprağım, rüzgarla düşse yerlere, i...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama', 'ama-ramazan-erdogan-uehmw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen benim gizemli sevgilimdin...

yüzünü göremediğim,

sesini duyamadığım...

ama delice sevdiğim...

sen hayalimdeki sevgilimdin,

her gece gördüğüm,

uğruna öldüğüm,

ama delice sevdiğim...

sen beni bırakan sevgilimdin,

yüzünü görmek istemediğim,

hayatımdan sildiğim,

ama kahrolası,delice sevdiğim...', 'sen benim gizemli sevgilimdin... yüzünü göremediğim, sesini duyamadığım... ama delice sevdiğim... sen hayalimdeki sevgilimdin, her gece görd...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-ramazan-erdogan-bju3z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yazdığım her şiirde

ya sen,yada sen varsın...

yoksun aslında ama

her an yanımda başucumdasın...

bir yıldız seçtim hatta,

senin için,ikimiz için...her gece konuşuyorum onunla,ü

sen hiç farkına varmasanda

döküyorum içimi hergece,o parlayan yıldıza

saçma geliyor dimi sana?

ne yapayım ama,halimden anlasana,

kaybettim kendimi ben

''''giderken sanki bende gittim kendimden''''

bomboş bir beden

ve ismini sayıklar oldum,

öldüm ben aslında,

hatta hiç varolmadım aslında,

ama bilirim,hayalim her an yanında

dedim ya;

sen hiç farkına varmasanda,

aşkım,aşkın bağrımda,

beni benden alan,

beni çaresiz bırakan bir yara...', 'yazdığım her şiirde ya sen,yada sen varsın... yoksun aslında ama her an yanımda başucumdasın... bir yıldız seçtim hatta, senin için,ikimiz i...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/askim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklarım adını', 'saklarim-adini-ramazan-erdogan-vmauk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'söyleyemem adını kimseye,

hele sana söyleyemem asla,

kızarsın küsersin bilirim,

saklarım adını bu yüzden...

gözlerine bakınca ne fırtınalar kopar içimde bir bilsen,

bir görsen bir anlayabilsen halimden,

bilirim olmayacaksın benim,hiçbir zaman

saklarım adını bu yüzden...

keşke hiç konuşmasak seninle,

zaman dursa,gözlerine dalsam,

yada her an yanında kalsam.

ben hayalimde bile yaşayamadımki seni,

saklarım  adını bu yüzden...

birde diyorum,kocaman bir demet gül getirsem sana,

anlarsınn belkide kimbilir beni?

anlasan ne fayda,yüreğim inanmazki aşka!

yada sen inanmazsın bana,

saklarım adını bu yüzden...

yaad diyorum haykırsam ismini,

dağlar taşlar duyun beni desem,

ve...

sen asla benim olmasanda,

benim güzeller güzelim;

senin adın ............................', 'söyleyemem adını kimseye, hele sana söyleyemem asla, kızarsın küsersin bilirim, saklarım adını bu yüzden... gözlerine bakınca ne fırtınalar ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Erdoğan']::text[], 8.5, '{"poet":"Ramazan Erdoğan","poet_slug":"ramazan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/saklarim-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-muhammet-sevilgen-08dy7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevdiğinden ayrılanlara...

yepyeni bir gün,yeni bir nefes...

herşey daha farklı...

değişmeyen tek şey ise sevgim,sana olan özlemim...

hayatın acımasızlığı ve zamanın zalimliği yetmezmiş gibi,

bir de senin hasretin dağlıyor,perişan yüreğimi...

ağlamak...

ağlamak rahatlatmıyor artık,eskisi gibi.

gülmekse tat vermiyor,

hayalin gözlerimde gülümsemedikçe...

gülmek, sayıklarken ağlamayı gözbebeklerimde; neyime!

uykusuzum...

uykusuzum sensiz.

yaşanmıyor senden uzak,sevginden uzak ve sesinden...

şimdi sensizim,sevgisiz ve çaresiz...

ektiğim tohumlar fidan oldu, nerdesin?

yarım kaldım senden uzakta...

ağlarken geceleri yatağımda,ismini haykıramadım. yani;

kendimi unuturken seni düşündüğümde ve

bulutların üzerinden düşerken,ümütsiz.

yüzme bilmeden çırpınıyor gibiyim,

okyanusun ortasında...

alışamadım yokluğuna,bir de hayatın zorluğuna...

artık gelme,beni sevdiğini söyleme artık.

dayanamam, ölürüm...

(içel/09-04-2001)', 'sevdiğinden ayrılanlara... yepyeni bir gün,yeni bir nefes... herşey daha farklı... değişmeyen tek şey ise sevgim,sana olan özlemim... hayatı...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sevilgen']::text[], 8.5, '{"poet":"Muhammet Sevilgen","poet_slug":"muhammet-sevilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/alisamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Hasreti', 'gecenin-hasreti-deniz-akpinar-tixde', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi gecenin en koyu rengi 

Gözlerim  bir  an baka kaldı

Denizin kurşun olmuş rengine

Uzaklarda karşı tarafın ışıklarına

Biri yanıp biri sönüyordu sanki göz kırpar gibi

Bir an istanbulda düşledim kendimi

Bostancıya doğru bakıpta seni aradığımı düşledim

21;30 vapuruna binipte giderken arkaya  san baktığımı

Seni denizin dalgalarında düşledim

Yaşarken boğuşmak gibi dertlere bata çıka dalgalara

Dalgaların köpüğü  gibi beyaz elde tutulmayan...

Ya sevgiyle boğuşmalı yürekten yada kaçmalı denizlerden

                       tatlıma 8/4/2001.....yüreğimdeki sevgimle', 'Şimdi gecenin en koyu rengi  Gözlerim  bir  an baka kaldı Denizin kurşun olmuş rengine Uzaklarda karşı tarafın ışıklarına Biri yanıp biri sö...', ARRAY['Türk Edebiyatı','Şiir','Deniz Akpınar']::text[], 8.5, '{"poet":"Deniz Akpınar","poet_slug":"deniz-akpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecenin-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sora Sora', 'sora-sora-mahzuni-serif-gprfx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Divane ettin aklımı

Taştan taşa vura vura

Aradım can yoldaşımı

Baştan başa sora sora

Kimi yanar kimi söner

Kimi iner kimi biner

Saraylar virana döner

Baştan başa dura dura

Gir Mahzuni dost bağına

Kar yamış dostluk dağına

Gençliğim ömrüm çağına

Baştan başa yara yara', 'Divane ettin aklımı Taştan taşa vura vura Aradım can yoldaşımı Baştan başa sora sora Kimi yanar kimi söner Kimi iner kimi biner Saraylar vir...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sora-sora-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Dünyanın Aleni', 'su-dunyanin-aleni-mahzuni-serif-c6oz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kolay değil şu dünyanın aleni

Kuru lafla sürülmez ki süreyim

Tutupta nefsime idam kararı

Vicdan vardır verilmez ki vereyim

İçime akıyor gözümün yaşı

Ne kadar zor olur ahbalan taşı

Erciyes Dağı’nda uçan bir kuşu

Kör gözünen görülmezki göreyim

Kalmadı dizimin gayrı dermanı

Ekin ektim yapamadım harmanı

Suçum yokken beyler vermiş fermanı

Dost Mahzuni verilmez ki vereyim', 'Kolay değil şu dünyanın aleni Kuru lafla sürülmez ki süreyim Tutupta nefsime idam kararı Vicdan vardır verilmez ki vereyim İçime akıyor gözü...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-dunyanin-aleni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmak', 'unutulmak-murat-erdogan-mizkc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi zaman olur ki alır beni düşüce

Kendini kür kuyuya atmaktır unutulmak

Toz pembeden kurtulup, akıl başa düşünce;

Hayali üç kuruşa satmaktır unutulmak

Anılar düşünülür en samimi dostuyla

Muhabbet arar günül eskisi, yenisiyle

Çıkılır yolculuğa bir hüzün gemisiyle

Hicranın denizinde batmaktır unutulmak

Yalnızlığın acısı sararken bedenini

Aklın son damlasıyla düşünür nedenini

Sitemle yad ederken terkedip gidenini;

Her an daha tükenip, bitmektir unutulmak

Titrek bakışlarıyla güz pınarı nemlenir

Bulanık zihinlerde çaresizlik çimlenir

Eller kalkar semaya son kez umut dilenir

Dönülmez bir sefere gitmektir unutulmak

Yıkılıp viran olur günüldeki otağı

Otağdan geri kanal tek hatıra çardağı

Istırap zehri ile doluvermiş bardağı;

Bir solukta içerek, yutmaktır unutulmak

Soğuk,ıslak,karanlık bir delhize tıkılıp,

Her dem kahır,kederle can evinden yıkılıp

Ne zaman düner diye beklemekten sıkılıp

Diri diri mezara yatmaktır unutulmak', 'Kimi zaman olur ki alır beni düşüce Kendini kür kuyuya atmaktır unutulmak Toz pembeden kurtulup, akıl başa düşünce; Hayali üç kuruşa satmakt...', ARRAY['Türk Edebiyatı','Şiir','Murat Erdoğan']::text[], 8.5, '{"poet":"Murat Erdoğan","poet_slug":"murat-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutulmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlanı Aşk', 'i-lani-ask-murat-aslan-2-nan24', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkımı anlattığım gün

Cümleler aciz kaldı

Ama söylenen her söz

Bu güne veciz kaldı

Kalbimde üç damla kan 

Aşkınla ısındı yüreğim yandı

Ateş başıma vurdu aklım dolandı

Düşünüyorum da

Sensiz geçen ömre 

Bu can nasıl dayandı', 'Aşkımı anlattığım gün Cümleler aciz kaldı Ama söylenen her söz Bu güne veciz kaldı Kalbimde üç damla kan  Aşkınla ısındı yüreğim yandı Ateş ...', ARRAY['Türk Edebiyatı','Şiir','Murat Aslan 2']::text[], 8.5, '{"poet":"Murat Aslan 2","poet_slug":"murat-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ilani-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sen', 've-sen-ahmet-atilla-3bn5w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve düşen yıldırımın donduğu gece

Sen gitmeseydin ölürmüydü çocuklar

Bir sevda ateşini bırakıpta geride

Görebilseydin yağan karın yere düşmeden eridiğini

Hasretliğin bu denli acı olduğunu

Bir suda yanan nergiz bildi bir ben

Ve şimdi hiçbir zaman söylenemeyecek

Bir aşk kaldı birde....deme kalsın', 'Ve düşen yıldırımın donduğu gece Sen gitmeseydin ölürmüydü çocuklar Bir sevda ateşini bırakıpta geride Görebilseydin yağan karın yere düşmed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atilla']::text[], 8.5, '{"poet":"Ahmet Atilla","poet_slug":"ahmet-atilla","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saka Kuşu', 'saka-kusu-orhan-veli-kanik-xdt7z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel kız; sen küçüklüğümde

Bahçemizde ki erik ağacının

En yüksek dalına kurduğum

Öksenin üstünde dolaşan

Saka kuşu kadar

Sevimli değilsin!', 'Güzel kız; sen küçüklüğümde Bahçemizde ki erik ağacının En yüksek dalına kurduğum Öksenin üstünde dolaşan Saka kuşu kadar Sevimli değilsin!...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/saka-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İş Olsun Diye', 'i-s-olsun-diye-orhan-veli-kanik-ycg5k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün güzel kadınlar zannetilerki

Aşk üzerine yazdığım her şiir

Kewndileri için yazılmıştır...

Bense daima üzüntüsünü çektim,

Onları iş olsun diye yaptığımı bilmenin.', 'Bütün güzel kadınlar zannetilerki Aşk üzerine yazdığım her şiir Kewndileri için yazılmıştır... Bense daima üzüntüsünü çektim, Onları iş olsu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/is-olsun-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan önce', 'asktan-once-umit-yasar-oguzcan-sq9dz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günlerden bir gün

Ya pazartesi ya salı

Son meteliğime kadar içeceğim...

Yine hatırıma sen geleceksin

Oturup ağlayacağım.', 'Günlerden bir gün Ya pazartesi ya salı Son meteliğime kadar içeceğim... Yine hatırıma sen geleceksin Oturup ağlayacağım....', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asktan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renklerin Dansı', 'renklerin-dansi-ahmet-i-nce-17ysw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Minik bir manolya gibi

Konaklar  kumsalda sevgi

Tutuşur tutsak arzular

Karadeniz’in koynunda

Kızışırken renklerin dansı

Özlemin gözlerinde gezinerek

Sıcak şiirler üretir yanık bir yürek

Morluk içinde uyanır mavi

Yeşilin kalbinde

Zevkin kasırgasıdır sarı

Kara fırtınalar kucaklarken kıyıları

Ak köpükler yeşil yosunları yalar

Dalgalanır yaşam tutkusu

Martılar balıkları tutuklar

Serin  beklentilerin gözlerinde

Şiirler şarkı olur

Düşler ezgilerde ıslanır

El ele tutuşurken sevgiler

Gülümser güzellikte gözler

Deniz ve tuz kokan ormanlar

Serinletir eteklerini yıldızların

Göz kırpar dalgalara esmer kuşlar

Kaybolurken kızıl sularda güneş

Kumsalda masal üretir gizemli aşklar

                                        TRABZON

                                         08.09.1999', 'Minik bir manolya gibi Konaklar  kumsalda sevgi Tutuşur tutsak arzular Karadeniz’in koynunda Kızışırken renklerin dansı Özlemin gözlerinde g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/renklerin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvimli Saat', 'takvimli-saat-umit-yasar-oguzcan-veunf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanrım paran yoksa biz verelim

Kendine bir saat al,

En iyisinden.

Bir daha zamanı şaşırma,

Vakitli vakitsiz öldürme bizi.', 'Tanrım paran yoksa biz verelim Kendine bir saat al, En iyisinden. Bir daha zamanı şaşırma, Vakitli vakitsiz öldürme bizi....', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/takvimli-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lizi Ve Son', 'lizi-ve-son-hanifi-i-spirli-f7ot4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Bardak Suya Akseden Hayal

1.

hayır

zaman kısa değil

ben diyorum

bu hastamın iyileştiğini görmeliyim

neden zaman geçmiyor

inilti kusuyor hastane odaları

ah sevgilim ah Lizi

zaman geçse de iyileşsen

geçmiyor işte

ağlayanlar var geçiyor diye

geçmiyor

ben

ben görmeliyim senin iyileştiğini

azmediyorum Lizi

başında beklemek eritti beni

ya yetmezse

benim sana şu ömrüm

ondan korkmuyorum

bir an önce iyileşsen

de görsem seni

zaman geçmiyor Lizi

soğuk kış geceleri

ne kadar uzun oluyordu

seni tanıdıktan sonra

şimdi o gecelerin

saniyesi asır olmuş

Lizi

zaman geçmiyor işte

geçmiyor

2.

bak şu kapının önünde toplananlara

kim çekti sana bu protestoyu

çık şu cama

inat etme artık

bir nutuk at şu çılgınlara

anlat kendini Lizi

anlat artık

geçmiyor zaman

ham fikirler tartışılırken

her şeyi doğuruyor toprak

senin fikirlerini asla

onları kim doğurdu

anlat onlara Lizi

bilsinler zaman diye bir şey

olmadığını

iki yılı bir gün

bir günü saat kabul ettiğini

yaşamak istediğini zamansız mekânda

bilsinler kime ait olduğunu

kaynak fikirlerinin Lizi

ah Lizi

3.

ben

zebaniye sevgilim diye hitap ederken

geçmediğini anlat zamanın

de ki

eğer geçseydi zaman

hatırlar mıydım

anamdan doğduğum günü

''elestü bi rabbiküm''

hitabına cevabı

hatırlar mıydım hiç

yandık Lizi

geçmiyor zaman

geçseydi zaman

ya da

insana verilmeseydi can

ne demekti zaman

onu siz uydurdunuz

yalvar Lizi

4.

daha dün diyor

dün konuştuk onunla

salvo sohbetler

kavgalı tartışmalar

hepsi hâyal şimdi

ama dün konuştuk onunla

inanmıyor zamanın geçmediğine

anlat Lizi

vazifen bu

biraz daha Lizi

ah Lizi

bu havada ortanca

bu bahçede kamelya

odanın penceresinden görünen

bunlar

onlar bizim dostlarımız

bir tek onlar anlıyor bizi

birde birbirimizi

başka kimimiz var Lizi

dayan Lizi

biraz daha

olsun

varsın inanmasınlar

ama bana çok lazımsın

yaşamalısın ki

yaşayabileyim

bir tek menzilim var

şu çirkef su üstünde

o da bir an önce iyileştiğini görmek

olmuyor işte

geçmiyor zaman', 'Bir Bardak Suya Akseden Hayal 1. hayır zaman kısa değil ben diyorum bu hastamın iyileştiğini görmeliyim neden zaman geçmiyor inilti kusuyor ...', ARRAY['Türk Edebiyatı','Şiir','Hanifi İspirli']::text[], 8.5, '{"poet":"Hanifi İspirli","poet_slug":"hanifi-i-spirli","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/lizi-ve-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumlar', 'yorumlar-hanifi-i-spirli-4ukq3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana ne istersen alıp geleyim

tarihi yakasından tutup geleyim

şahımı kraliçemi vurup geleyim

vurulacak yerlerimi sen vuracaksan

kalkıp sana yüreğimle geleyim

ben kolay dokunmadım

bunu en iyi sen bilirsin

nakışları söken sensin bilirsin

yakamıza yapışmış sulardan taşıp

istiyorsan ölümüne ölümüne geleyim

suçlu biziz suçsuz biziz daha ne

yıkılmaya başlamış

bu aşklardan kime ne

onu seven de biz toprağa gömen de

geceyi kucaklayıp onunla sevişen de

bekliyorsan aç yanını geleyim

bakırcılar çarşısından alüminyum tencere

eczacılar çarşısından bir tutam altın otu

neye şaşar bu akıl kendi değil midir bu

kendi değil midir ki başı yukarılarda

neye şaşar bu akıl bu coğrafyada

şaşmayacaksan eğer

yanmayacaksan

kitaplarımı atıp

kalkıp sana geleyim', 'sana ne istersen alıp geleyim tarihi yakasından tutup geleyim şahımı kraliçemi vurup geleyim vurulacak yerlerimi sen vuracaksan kalkıp sana ...', ARRAY['Türk Edebiyatı','Şiir','Hanifi İspirli']::text[], 8.5, '{"poet":"Hanifi İspirli","poet_slug":"hanifi-i-spirli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yorumlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağdaş Hengame', 'cagdas-hengame-hanifi-i-spirli-d6t92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağa gitti kadınlar

Nostalji dünyası şimdi yüreğim

Arabesk veremlerden birini seçin

Gidiyorum artık

Sokaklarda gölgemi çiğneyin

Bir kent susuzluğunda ellerim

Taş binalarda sarhoşluğum

Ebu zer

Hey ebu zer

Neredesin artık gel

Burada olduğumu kimse bilmiyor

Ne polis

Ne hastane doktorları

Ne de thomson namluları

Bazen farlar aydınlatıyor pencereleri

Bazen de hayal kelepçeleri

Yine geceye haciz gelecek

Borçlu doğacağız sabaha

Yalnızlığı hapsettiğim

İki sandalyeli evimde

Alıp onu karşıma satranç oynayacağım

Para tedavülden kalkacak

Şiir olacak geçer akçe

Çağıracaklar kadınları

Gün bir daha olmayacak', 'Dağa gitti kadınlar Nostalji dünyası şimdi yüreğim Arabesk veremlerden birini seçin Gidiyorum artık Sokaklarda gölgemi çiğneyin Bir kent sus...', ARRAY['Türk Edebiyatı','Şiir','Hanifi İspirli']::text[], 8.5, '{"poet":"Hanifi İspirli","poet_slug":"hanifi-i-spirli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cagdas-hengame-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam', 'hocam-sair-davali-dsl4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'o´nda mahzun bir gönül 

Daim dertli bas vardir, 

Ne zaman baksan yüzüne, 

Damla damla yas vardir. 

Sevgi dolu mesajinda, 

Ne kin, ne savas vardir, 

Katilasan gönüllere, 

Dilinde ilac vardir. 

Hep hizmet düsüncesi... 

Ne evlat,ne es vardir, 

Herkes derin uykuda, 

Yine O´nda is vardir. 

Tut elimden Hocam, 

Sanma bende güc vardir, 

Sana karsi mahcubum, 

Defter dolu suc vardir.', 'o´nda mahzun bir gönül  Daim dertli bas vardir,  Ne zaman baksan yüzüne,  Damla damla yas vardir.  Sevgi dolu mesajinda,  Ne kin, ne savas v...', ARRAY['Türk Edebiyatı','Şiir','Şair Davalı']::text[], 8.5, '{"poet":"Şair Davalı","poet_slug":"sair-davali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hocam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kahraman Bekliyoruz!', 'bir-kahraman-bekliyoruz-sair-davali-pscr3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kal''a gibi dik başın bulutlarla yarışsın.

Dalga dalga saçların rüzgârlara karışsın.

Adını nakşedelim, eski-kadîm surlara

Sesini haykıralım asırdan asırlara

Savletinden titresin yeniden Doğu, Batı

Ve kurulsun ebedî Allah''ın saltanatı

Ufukları kaplasın bayraklarımız al al

Göklere zaferini çizsin vahşi bir kartal

Kahramanlar büyüsün masalda dev misali,

Eğilsin öpsün gökler canım nazlı hilâlli.

Ordularım yeniden Tuna''ya akın etsin

Bir yıldırım çıksın da uzağı yakın etsin.

Selâm dursun karşımda bütün şerefler şanlar,

Namını tebcil etsin, yıldızlar, kehkeşanlar.

İçimde hiç sönmeyen bir fetih sevdası var,

Yavuz gibi diyorum: Bir dünya insana dar!

Bir seda duymak için, sahralara düşmeyim,

Helâl olsun bu yolda varım yoğum her şeyim.

Volkan gibi lâv atmış, ne susmuş ne sönmüşüm,

Ben fikir uğruna çılgınlara dönmüşüm.

Bir deha bekliyoruz, gençliğe mihrap olsun,

Ruhları tutuşturan bir ateş mihrak olsuun.

Sinesinde birleşsin sağa sola sapanlar

Kahrolsun Hak dururken yabancıya tapanlar

Çık nerdesin zuhur et, biz seni bekliyoruz

Yıllardır yollarında, yorgun emekliyoruz

Musa ol Hakka yüksel, tecelli et de Tûr''a

Zulmet yıkılsın gitsin, cihan garkolsun Nûra

İstiyorum yeniden bir hilkat istiyorum

Ne hayâl ne kuruntu, hakikat istiyorum.

Hakikat, hakikat, hakikat istiyorum...', 'Kal''a gibi dik başın bulutlarla yarışsın. Dalga dalga saçların rüzgârlara karışsın. Adını nakşedelim, eski-kadîm surlara Sesini haykıralım a...', ARRAY['Türk Edebiyatı','Şiir','Şair Davalı']::text[], 8.5, '{"poet":"Şair Davalı","poet_slug":"sair-davali","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-kahraman-bekliyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
